    def _calculate_comprehensive_performance_score(self, model_data: Dict[str, Any]) -> float:
        """Calculate composite performance score from multiple metrics"""
        try:
            performance = model_data.get('performance', {})
            weights = {
                'structural_accuracy': 0.25,
                'bootstrap_stability': 0.20,
                'geological_consistency': 0.20,
                'cross_validation_score': 0.15,
                'intervention_validation': 0.10,
                'causal_strength_correlation': 0.10
            }
            
            score = 0.0
            for metric, weight in weights.items():
                value = performance.get(metric, 0.0)
                score += weight * value
            
            return min(1.0, max(0.0, score))  # Clamp between 0 and 1
        except:
            return 0.5  # Default score

    def _detect_performance_changes(self, performance_history: List[Dict]) -> Dict[str, Any]:
        """Detect significant changes in model performance"""
        try:
            if len(performance_history) < 2:
                return {'significant_degradation': False, 'trend': 'stable'}
            
            recent_scores = [entry['composite_score'] for entry in performance_history[-5:]]
            older_scores = [entry['composite_score'] for entry in performance_history[-10:-5]]
            
            if len(older_scores) == 0:
                return {'significant_degradation': False, 'trend': 'insufficient_data'}
            
            recent_avg = np.mean(recent_scores)
            older_avg = np.mean(older_scores)
            degradation = (older_avg - recent_avg) / older_avg
            
            return {
                'significant_degradation': degradation > 0.1,  # 10% degradation threshold
                'degradation_percentage': degradation * 100,
                'trend': 'degrading' if degradation > 0.05 else 'stable' if degradation > -0.05 else 'improving'
            }
        except:
            return {'significant_degradation': False, 'trend': 'unknown'}

    async def _trigger_performance_alert(self, model_id: str, performance_change: Dict):
        """Trigger alert for significant performance changes"""
        try:
            alert_message = f"Model {model_id} performance degradation: {performance_change['degradation_percentage']:.1f}%"
            self.logger.warning(alert_message)
            # In practice, would send notifications to stakeholders
        except Exception as e:
            self.logger.error(f"Failed to trigger performance alert: {e}")

