    async def _query_global_ridge_database(self, lat, lon):
        """Query comprehensive global ridge database with spreading rates and morphology"""
        try:
            from .database_integration import DatabaseManager
            db = DatabaseManager()
            async with db.get_session() as session:
                result = await session.execute(text("""
                    WITH ridge_segments AS (
                        SELECT 
                            pb.id,
                            pb.boundary_type,
                            pb.spreading_rate_mm_yr,
                            pb.boundary_geometry,
                            ST_Distance(pb.boundary_geometry::geography, ST_Point(:lon, :lat)::geography) / 1000.0 as distance_km,
                            pb.confidence_level
                        FROM plate_boundaries pb
                        WHERE pb.boundary_type = 'divergent'
                        AND ST_DWithin(pb.boundary_geometry::geography, ST_Point(:lon, :lat)::geography, 500000)
                        ORDER BY distance_km
                        LIMIT 1
                    )
                    SELECT 
                        COALESCE(rs.spreading_rate_mm_yr, 20) as spreading_rate,
                        COALESCE(rs.distance_km, 1000) as distance_km,
                        CASE 
                            WHEN rs.spreading_rate_mm_yr < 20 THEN 'ultraslow'
                            WHEN rs.spreading_rate_mm_yr < 50 THEN 'slow'
                            WHEN rs.spreading_rate_mm_yr < 80 THEN 'intermediate'
                            WHEN rs.spreading_rate_mm_yr < 120 THEN 'fast'
                            ELSE 'superfast'
                        END as ridge_type
                    FROM ridge_segments rs
                """), {"lat": lat, "lon": lon})
                row = result.fetchone()
                if row:
                    return {
                        'spreading_rate': row.spreading_rate,
                        'distance_km': row.distance_km,
                        'ridge_type': row.ridge_type
                    }
            return {'spreading_rate': 20, 'distance_km': 1000, 'ridge_type': 'unknown'}
        except Exception as e:
            self.logger.debug(f"Ridge database query failed: {e}")
            return {'spreading_rate': 20, 'distance_km': 1000, 'ridge_type': 'unknown'}
    
    async def _query_magnetic_anomaly_data(self, lat, lon):
        """Query magnetic anomaly data from EMAG2v3 and marine magnetic profiles"""
        try:
            from .external_data_connectors import MagneticDataConnector
            mag = MagneticDataConnector()
            anomaly_data = await mag.query_anomaly(lat, lon)
            reversal_pattern = await mag.get_reversal_pattern(lat, lon)
            return {
                'anomaly': anomaly_data.get('total_intensity_nT', 0),
                'reversal_pattern': reversal_pattern
            }
        except Exception as e:
            self.logger.debug(f"Magnetic anomaly query failed: {e}")
            return {'anomaly': 0, 'reversal_pattern': []}
    
    async def _query_heat_flow_database(self, lat, lon):
        """Query global heat flow database from IHFC"""
        try:
            from .database_integration import DatabaseManager
            db = DatabaseManager()
            async with db.get_session() as session:
                result = await session.execute(text("""
                    SELECT 
                        AVG(heat_flow_mW_m2) as avg_heat_flow,
                        COUNT(*) as measurement_count
                    FROM heat_flow_measurements
                    WHERE ST_DWithin(location::geography, ST_Point(:lon, :lat)::geography, 100000)
                """), {"lat": lat, "lon": lon})
                row = result.fetchone()
                if row and row.measurement_count > 0:
                    return {'heat_flow': row.avg_heat_flow}
            return {'heat_flow': 50}
        except Exception as e:
            self.logger.debug(f"Heat flow query failed: {e}")
            return {'heat_flow': 50}
    
