    def _parse_swrl_rule(self, rule_text: str):
        """Advanced SWRL rule parser with full semantic understanding and compilation"""
        try:
            tokens = self._tokenize_swrl(rule_text)
            parsed_rule = self._recursive_descent_parse(tokens)
            executable_rule = self._compile_to_executable(parsed_rule)
            validated_rule = self._validate_semantics(executable_rule)
            inference_patterns = self._generate_inference_patterns(validated_rule)
            
            return {
                'text': rule_text.strip(),
                'ast': parsed_rule,
                'executable': validated_rule,
                'patterns': inference_patterns,
                'variables': self._extract_typed_variables(validated_rule),
                'predicates': self._extract_semantic_predicates(validated_rule),
                'constraints': self._extract_constraints(validated_rule),
                'complexity_score': self._compute_rule_complexity(validated_rule),
                'optimization_hints': self._generate_optimization_hints(validated_rule)
            }
        except Exception as e:
            self.logger.error(f"Advanced SWRL parsing failed: {e}")
            return self._fallback_parse(rule_text)
    
    def _tokenize_swrl(self, rule_text: str) -> list:
        """Advanced tokenization with semantic token classification"""
        import re
        from typing import NamedTuple
        
        class Token(NamedTuple):
            type: str
            value: str
            position: int
            metadata: dict
        
        token_patterns = [
            ('IMPLICATION', r'→|:-'),
            ('CONJUNCTION', r'∧|&|,'),
            ('DISJUNCTION', r'∨|\|'),
            ('NEGATION', r'¬|!|not'),
            ('QUANTIFIER', r'∀|∃|forall|exists'),
            ('VARIABLE', r'\?[a-zA-Z_][a-zA-Z0-9_]*'),
            ('PREDICATE', r'[A-Z][a-zA-Z0-9_]*(?=\()'),
            ('BUILTIN', r'swrlb:[a-zA-Z_][a-zA-Z0-9_]*'),
            ('URI', r'<[^>]+>'),
            ('LITERAL', r'"[^"]*"|\'[^\']*\''),
            ('NUMBER', r'-?\d+\.?\d*'),
            ('LPAREN', r'\('),
            ('RPAREN', r'\)'),
            ('COMMA', r','),
            ('WHITESPACE', r'\s+'),
            ('UNKNOWN', r'.')
        ]
        
        tokens = []
        position = 0
        
        while position < len(rule_text):
            matched = False
            for token_type, pattern in token_patterns:
                regex = re.compile(pattern)
                match = regex.match(rule_text, position)
                if match:
                    value = match.group(0)
                    if token_type != 'WHITESPACE':
                        metadata = {'context': rule_text[max(0, position-10):position+10]}
                        tokens.append(Token(token_type, value, position, metadata))
                    position = match.end()
                    matched = True
                    break
            if not matched:
                position += 1
        
        return tokens
    
    def _recursive_descent_parse(self, tokens: list):
        """Recursive descent parser implementing full SWRL grammar"""
        class SWRLParser:
            def __init__(self, tokens):
                self.tokens = [t for t in tokens if t.type != 'WHITESPACE']
                self.position = 0
                self.current_token = self.tokens[0] if self.tokens else None
            
            def advance(self):
                self.position += 1
                self.current_token = self.tokens[self.position] if self.position < len(self.tokens) else None
            
            def parse_rule(self):
                antecedent = self.parse_conjunction()
                if self.current_token and self.current_token.type == 'IMPLICATION':
                    self.advance()
                    consequent = self.parse_conjunction()
                    return {'type': 'rule', 'antecedent': antecedent, 'consequent': consequent}
                return {'type': 'fact', 'body': antecedent}
            
            def parse_conjunction(self):
                left = self.parse_disjunction()
                while self.current_token and self.current_token.type == 'CONJUNCTION':
                    op = self.current_token.value
                    self.advance()
                    right = self.parse_disjunction()
                    left = {'type': 'conjunction', 'operator': op, 'left': left, 'right': right}
                return left
            
            def parse_disjunction(self):
                left = self.parse_atom()
                while self.current_token and self.current_token.type == 'DISJUNCTION':
                    op = self.current_token.value
                    self.advance()
                    right = self.parse_atom()
                    left = {'type': 'disjunction', 'operator': op, 'left': left, 'right': right}
                return left
            
            def parse_atom(self):
                if self.current_token and self.current_token.type == 'NEGATION':
                    self.advance()
                    atom = self.parse_atom()
                    return {'type': 'negation', 'atom': atom}
                elif self.current_token and self.current_token.type == 'PREDICATE':
                    return self.parse_predicate()
                elif self.current_token and self.current_token.type == 'BUILTIN':
                    return self.parse_builtin()
                elif self.current_token and self.current_token.type == 'LPAREN':
                    self.advance()
                    expr = self.parse_conjunction()
                    if self.current_token and self.current_token.type == 'RPAREN':
                        self.advance()
                    return expr
                else:
                    return {'type': 'unknown', 'token': self.current_token}
            
            def parse_predicate(self):
                name = self.current_token.value
                self.advance()
                args = []
                if self.current_token and self.current_token.type == 'LPAREN':
                    self.advance()
                    while self.current_token and self.current_token.type != 'RPAREN':
                        args.append(self.parse_term())
                        if self.current_token and self.current_token.type == 'COMMA':
                            self.advance()
                    if self.current_token and self.current_token.type == 'RPAREN':
                        self.advance()
                return {'type': 'predicate', 'name': name, 'args': args}
            
            def parse_builtin(self):
                name = self.current_token.value
                self.advance()
                args = []
                if self.current_token and self.current_token.type == 'LPAREN':
                    self.advance()
                    while self.current_token and self.current_token.type != 'RPAREN':
                        args.append(self.parse_term())
                        if self.current_token and self.current_token.type == 'COMMA':
                            self.advance()
                    if self.current_token and self.current_token.type == 'RPAREN':
                        self.advance()
                return {'type': 'builtin', 'name': name, 'args': args}
            
            def parse_term(self):
                if not self.current_token:
                    return {'type': 'unknown', 'value': None}
                if self.current_token.type == 'VARIABLE':
                    value = self.current_token.value
                    self.advance()
                    return {'type': 'variable', 'name': value}
                elif self.current_token.type == 'LITERAL':
                    value = self.current_token.value.strip('"\'')
                    self.advance()
                    return {'type': 'literal', 'value': value}
                elif self.current_token.type == 'NUMBER':
                    value = float(self.current_token.value) if '.' in self.current_token.value else int(self.current_token.value)
                    self.advance()
                    return {'type': 'number', 'value': value}
                elif self.current_token.type == 'URI':
                    value = self.current_token.value.strip('<>')
                    self.advance()
                    return {'type': 'uri', 'value': value}
                else:
                    value = self.current_token.value
                    self.advance()
                    return {'type': 'unknown', 'value': value}
        
        if not tokens:
            return {'type': 'empty'}
        
        parser = SWRLParser(tokens)
        return parser.parse_rule()
    
    def _compile_to_executable(self, parsed_rule: dict):
        """Compile AST to optimized executable form with advanced optimization"""
        if parsed_rule.get('type') == 'empty':
            return parsed_rule
            
        executable = {
            'type': parsed_rule['type'],
            'execution_plan': self._generate_execution_plan(parsed_rule),
            'variable_bindings': self._analyze_variable_bindings(parsed_rule),
            'predicate_order': self._optimize_predicate_order(parsed_rule),
            'index_hints': self._generate_index_hints(parsed_rule)
        }
        
        if parsed_rule['type'] == 'rule':
            executable['antecedent'] = self._compile_clause(parsed_rule['antecedent'])
            executable['consequent'] = self._compile_clause(parsed_rule['consequent'])
        else:
            executable['body'] = self._compile_clause(parsed_rule['body'])
            
        return executable
    
    def _validate_semantics(self, executable_rule: dict):
        """Advanced semantic validation with type checking and consistency analysis"""
        validation_result = {
            'valid': True,
            'warnings': [],
            'errors': [],
            'type_constraints': {},
            'consistency_score': 1.0
        }
        
        try:
            validation_result['type_constraints'] = self._infer_types(executable_rule)
            validation_result['consistency_score'] = self._compute_consistency_score(executable_rule)
            
            if validation_result['consistency_score'] < 0.5:
                validation_result['warnings'].append('Low consistency score detected')
                
        except Exception as e:
            validation_result['valid'] = False
            validation_result['errors'].append(str(e))
        
        executable_rule['validation'] = validation_result
        return executable_rule
    
    def _generate_inference_patterns(self, validated_rule: dict):
        """Generate optimized inference patterns for different execution strategies"""
        patterns = {
            'forward_chaining': self._generate_forward_pattern(validated_rule),
            'backward_chaining': self._generate_backward_pattern(validated_rule),
            'hybrid': self._generate_hybrid_pattern(validated_rule)
        }
        return patterns
    
    def _extract_typed_variables(self, rule: dict) -> dict:
        """Extract variables with comprehensive type inference and constraint analysis"""
        variables = {}
        
        def extract_from_node(node, context='unknown'):
            if isinstance(node, dict):
                if node.get('type') == 'variable':
                    var_name = node['name']
                    if var_name not in variables:
                        variables[var_name] = {
                            'type': self._infer_variable_type(node, rule, context),
                            'constraints': [],
                            'binding_strength': 0.0,
                            'contexts': []
                        }
                    variables[var_name]['contexts'].append(context)
                    variables[var_name]['binding_strength'] += self._compute_binding_strength(node, rule, context)
                
                for key, value in node.items():
                    if isinstance(value, (dict, list)):
                        extract_from_node(value, f"{context}.{key}")
            elif isinstance(node, list):
                for i, item in enumerate(node):
                    extract_from_node(item, f"{context}[{i}]")
        
        extract_from_node(rule, 'root')
        return variables
    
    def _extract_semantic_predicates(self, rule: dict) -> dict:
        """Extract predicates with comprehensive semantic analysis and relationship mapping"""
        predicates = {}
        
        def extract_from_node(node):
            if isinstance(node, dict):
                if node.get('type') == 'predicate':
                    pred_name = node['name']
                    predicates[pred_name] = {
                        'arity': len(node.get('args', [])),
                        'semantic_type': self._classify_predicate_semantics(pred_name),
                        'domain': self._infer_predicate_domain(node),
                        'range': self._infer_predicate_range(node),
                        'relationships': self._find_predicate_relationships(pred_name),
                        'selectivity': self._estimate_selectivity(pred_name),
                        'cost_estimate': self._estimate_evaluation_cost(node)
                    }
                
                for value in node.values():
                    if isinstance(value, (dict, list)):
                        extract_from_node(value)
            elif isinstance(node, list):
                for item in node:
                    extract_from_node(item)
        
        extract_from_node(rule)
        return predicates
    
    def _extract_constraints(self, rule: dict) -> list:
        """Extract logical and type constraints from the rule"""
        constraints = []
        
        if rule.get('validation', {}).get('type_constraints'):
            constraints.extend([
                {'type': 'type_constraint', 'constraint': tc}
                for tc in rule['validation']['type_constraints'].values()
            ])
        
        constraints.extend(self._extract_logical_constraints(rule))
        constraints.extend(self._extract_domain_constraints(rule))
        
        return constraints
    
    def _compute_rule_complexity(self, rule: dict) -> float:
        """Compute comprehensive complexity score for the rule"""
        base_complexity = self._compute_structural_complexity(rule)
        semantic_complexity = self._compute_semantic_complexity(rule)
        execution_complexity = self._estimate_execution_complexity(rule)
        
        return (base_complexity + semantic_complexity + execution_complexity) / 3.0
    
    def _generate_optimization_hints(self, rule: dict) -> list:
        """Generate comprehensive optimization hints based on rule analysis"""
        hints = []
        
        if rule.get('index_hints'):
            hints.extend([{'type': 'index', 'hint': h} for h in rule['index_hints']])
        
        hints.extend(self._generate_execution_order_hints(rule))
        hints.extend(self._generate_caching_hints(rule))
        hints.extend(self._generate_parallelization_hints(rule))
        
        return hints
    
    def _fallback_parse(self, rule_text: str):
        """Fallback parser for basic rule processing when advanced parsing fails"""
        import re
        return {
            'text': rule_text.strip(),
            'antecedent': rule_text.split('→')[0].strip() if '→' in rule_text else rule_text.strip(),
            'consequent': rule_text.split('→')[1].strip() if '→' in rule_text else None,
            'variables': list(set(re.findall(r'\?(\w+)', rule_text))),
            'predicates': list(set(re.findall(r'([A-Z][a-zA-Z]*)\(', rule_text))),
            'parse_mode': 'fallback'
        }

