    def _compute_adaptive_threshold(self, attention_matrix: np.ndarray) -> float:
        """Compute adaptive threshold using statistical significance testing."""
        try:
            from scipy import stats
            
            # Flatten non-diagonal elements
            off_diagonal = attention_matrix[~np.eye(attention_matrix.shape[0], dtype=bool)]
            
            # Use mixture model to separate signal from noise
            from sklearn.mixture import GaussianMixture
            gmm = GaussianMixture(n_components=2, random_state=42)
            gmm.fit(off_diagonal.reshape(-1, 1))
            
            # Find threshold that maximizes separation between components
            means = gmm.means_.flatten()
            stds = np.sqrt(gmm.covariances_.flatten())
            
            # Conservative threshold at intersection of distributions
            if len(means) == 2:
                threshold = np.mean(means) + 0.5 * np.min(stds)
            else:
                threshold = np.mean(attention_matrix) + np.std(attention_matrix)
                
            return float(threshold)
            
        except Exception as e:
            self.logger.warning(f"Adaptive threshold computation failed: {e}")
            return np.mean(attention_matrix) + np.std(attention_matrix)
    
    def _construct_causal_graph(self, attention_matrix: np.ndarray, threshold: float) -> nx.DiGraph:
        """Construct sophisticated causal graph with edge validation."""
        G = nx.DiGraph()
        n_nodes = attention_matrix.shape[0]
        
        # Add nodes with geological context
        geological_types = ['geochemical', 'structural', 'temporal', 'spatial', 'thermodynamic']
        for i in range(n_nodes):
            node_type = geological_types[i % len(geological_types)]
            G.add_node(i, 
                      geological_type=node_type,
                      centrality_prior=np.random.uniform(0.1, 1.0),
                      temporal_precedence=i / n_nodes)
        
        # Add edges with comprehensive validation
        for i in range(n_nodes):
            for j in range(n_nodes):
                if i != j:
                    edge_strength = attention_matrix[i, j]
                    
                    if edge_strength > threshold:
                        # Validate edge with multiple criteria
                        validation_score = self._validate_causal_edge(attention_matrix, i, j)
                        
                        if validation_score > 0.3:  # Validation threshold
                            G.add_edge(i, j, 
                                     weight=edge_strength,
                                     validation_score=validation_score,
                                     causal_strength=self._compute_causal_strength(attention_matrix, i, j),
                                     geological_plausibility=self._assess_geological_plausibility(i, j))
        
        return G
    
    def _validate_causal_edge(self, attention_matrix: np.ndarray, i: int, j: int) -> float:
        """Validate causal edge using multiple statistical tests."""
        validation_scores = []
        
        # Asymmetry test (causal relationships should be asymmetric)
        asymmetry_score = abs(attention_matrix[i, j] - attention_matrix[j, i]) / (attention_matrix[i, j] + attention_matrix[j, i] + 1e-8)
        validation_scores.append(asymmetry_score)
        
        # Transitivity validation
        transitivity_score = self._compute_transitivity_score(attention_matrix, i, j)
        validation_scores.append(transitivity_score)
        
        # Statistical significance (using permutation test)
        significance_score = self._permutation_test_significance(attention_matrix, i, j)
        validation_scores.append(significance_score)
        
        # Consistency across local neighborhoods
        consistency_score = self._compute_neighborhood_consistency(attention_matrix, i, j)
        validation_scores.append(consistency_score)
        
        return np.mean(validation_scores)
    
    def _comprehensive_graph_analysis(self, G: nx.DiGraph, attention_matrix: np.ndarray) -> Dict[str, Any]:
        """Comprehensive analysis of causal graph structure."""
        analysis = {}
        
        # Basic graph metrics
        analysis['basic_metrics'] = {
            'nodes': G.number_of_nodes(),
            'edges': G.number_of_edges(),
            'density': nx.density(G),
            'is_dag': nx.is_directed_acyclic_graph(G),
            'weakly_connected_components': nx.number_weakly_connected_components(G),
            'strongly_connected_components': nx.number_strongly_connected_components(G)
        }
        
        # Advanced centrality measures
        analysis['centrality_measures'] = {
            'betweenness': nx.betweenness_centrality(G),
            'closeness': nx.closeness_centrality(G),
            'eigenvector': nx.eigenvector_centrality_numpy(G, max_iter=1000),
            'pagerank': nx.pagerank(G),
            'katz': nx.katz_centrality_numpy(G),
            'load': nx.load_centrality(G)
        }
        
        # Motif analysis
        analysis['motifs'] = self._analyze_causal_motifs(G)
        
        # Path analysis
        analysis['path_analysis'] = {
            'average_shortest_path': self._compute_average_path_length(G),
            'diameter': self._compute_graph_diameter(G),
            'longest_paths': self._find_longest_paths(G),
            'critical_paths': self._identify_critical_paths(G, attention_matrix)
        }
        
        # Community structure
        analysis['community_structure'] = self._analyze_community_structure(G)
        
        # Robustness analysis
        analysis['robustness'] = self._analyze_graph_robustness(G)
        
        return analysis
    
    def _pc_algorithm_causal_discovery(self, attention_matrix: np.ndarray) -> Dict[str, Any]:
        """Implementation of PC algorithm for causal structure learning."""
        try:
            from itertools import combinations
            
            n_vars = attention_matrix.shape[0]
            
            # Step 1: Start with complete undirected graph
            skeleton = np.ones((n_vars, n_vars)) - np.eye(n_vars)
            
            # Step 2: Remove edges based on conditional independence tests
            for i, j in combinations(range(n_vars), 2):
                for subset_size in range(n_vars - 2):
                    for conditioning_set in combinations([k for k in range(n_vars) if k != i and k != j], subset_size):
                        # Conditional independence test
                        independence_score = self._conditional_independence_test(attention_matrix, i, j, conditioning_set)
                        
                        if independence_score < 0.05:  # Independence threshold
                            skeleton[i, j] = 0
                            skeleton[j, i] = 0
                            break
            
            # Step 3: Orient edges using v-structures and propagation rules
            oriented_graph = self._orient_edges_pc(skeleton, attention_matrix)
            
            return {
                'skeleton': skeleton.tolist(),
                'oriented_graph': oriented_graph.tolist(),
                'algorithm': 'PC',
                'confidence': self._compute_algorithm_confidence(oriented_graph, attention_matrix)
            }
            
        except Exception as e:
            self.logger.warning(f"PC algorithm failed: {e}")
            return {'error': str(e), 'algorithm': 'PC'}
    
    def _ges_causal_discovery(self, attention_matrix: np.ndarray) -> Dict[str, Any]:
        """Greedy Equivalence Search algorithm implementation."""
        try:
            n_vars = attention_matrix.shape[0]
            
            # Initialize with empty graph
            current_graph = np.zeros((n_vars, n_vars))
            best_score = self._compute_ges_score(current_graph, attention_matrix)
            
            # Forward phase: add edges
            improved = True
            while improved:
                improved = False
                best_candidate = None
                best_candidate_score = best_score
                
                for i in range(n_vars):
                    for j in range(n_vars):
                        if i != j and current_graph[i, j] == 0:
                            # Try adding edge i -> j
                            candidate_graph = current_graph.copy()
                            candidate_graph[i, j] = 1
                            
                            if nx.is_directed_acyclic_graph(nx.DiGraph(candidate_graph)):
                                candidate_score = self._compute_ges_score(candidate_graph, attention_matrix)
                                
                                if candidate_score > best_candidate_score:
                                    best_candidate = candidate_graph
                                    best_candidate_score = candidate_score
                                    improved = True
                
                if improved:
                    current_graph = best_candidate
                    best_score = best_candidate_score
            
            # Backward phase: remove edges
            improved = True
            while improved:
                improved = False
                best_candidate = None
                best_candidate_score = best_score
                
                edges = np.where(current_graph == 1)
                for i, j in zip(edges[0], edges[1]):
                    # Try removing edge i -> j
                    candidate_graph = current_graph.copy()
                    candidate_graph[i, j] = 0
                    
                    candidate_score = self._compute_ges_score(candidate_graph, attention_matrix)
                    
                    if candidate_score > best_candidate_score:
                        best_candidate = candidate_graph
                        best_candidate_score = candidate_score
                        improved = True
                
                if improved:
                    current_graph = best_candidate
                    best_score = best_candidate_score
            
            return {
                'causal_graph': current_graph.tolist(),
                'score': float(best_score),
                'algorithm': 'GES',
                'confidence': self._compute_algorithm_confidence(current_graph, attention_matrix)
            }
            
        except Exception as e:
            self.logger.warning(f"GES algorithm failed: {e}")
            return {'error': str(e), 'algorithm': 'GES'}
    
    def _lingam_causal_discovery(self, attention_matrix: np.ndarray) -> Dict[str, Any]:
        """Linear Non-Gaussian Acyclic Model causal discovery."""
        try:
            from sklearn.decomposition import FastICA
            
            # Apply ICA to find causal ordering
            ica = FastICA(n_components=attention_matrix.shape[0], random_state=42, max_iter=1000)
            
            # Use attention matrix as pseudo-data
            try:
                ica_components = ica.fit_transform(attention_matrix)
                mixing_matrix = ica.mixing_
                
                # Estimate causal adjacency matrix
                causal_matrix = np.abs(mixing_matrix)
                
                # Apply permutation to find causal order
                causal_order = self._find_causal_order_lingam(causal_matrix)
                
                # Construct final causal graph
                lingam_graph = self._construct_lingam_graph(causal_matrix, causal_order)
                
                return {
                    'causal_graph': lingam_graph.tolist(),
                    'causal_order': causal_order.tolist(),
                    'mixing_matrix': mixing_matrix.tolist(),
                    'algorithm': 'LiNGAM',
                    'confidence': self._compute_algorithm_confidence(lingam_graph, attention_matrix)
                }
                
            except Exception as ica_error:
                self.logger.warning(f"ICA in LiNGAM failed: {ica_error}")
                return {'error': str(ica_error), 'algorithm': 'LiNGAM'}
            
        except Exception as e:
            self.logger.warning(f"LiNGAM algorithm failed: {e}")
            return {'error': str(e), 'algorithm': 'LiNGAM'}
    
    def _granger_causality_analysis(self, attention_matrix: np.ndarray) -> Dict[str, Any]:
        """Advanced Granger causality analysis for temporal relationships."""
        try:
            from scipy.stats import f
            
            n_vars = attention_matrix.shape[0]
            granger_matrix = np.zeros((n_vars, n_vars))
            p_values = np.zeros((n_vars, n_vars))
            
            # Create pseudo time series from attention patterns
            time_series_length = max(50, n_vars * 3)
            time_series = self._generate_time_series_from_attention(attention_matrix, time_series_length)
            
            # Test Granger causality for each pair
            for i in range(n_vars):
                for j in range(n_vars):
                    if i != j:
                        granger_score, p_value = self._granger_causality_test(
                            time_series[:, i], time_series[:, j]
                        )
                        granger_matrix[i, j] = granger_score
                        p_values[i, j] = p_value
            
            # Find significant causal relationships
            significant_threshold = 0.05
            significant_causality = p_values < significant_threshold
            
            return {
                'granger_causality_matrix': granger_matrix.tolist(),
                'p_values': p_values.tolist(),
                'significant_relationships': significant_causality.tolist(),
                'algorithm': 'Granger',
                'temporal_lags': self._identify_optimal_lags(time_series),
                'confidence': float(np.mean(significant_causality))
            }
            
        except Exception as e:
            self.logger.warning(f"Granger causality analysis failed: {e}")
            return {'error': str(e), 'algorithm': 'Granger'}
    
