    async def store_causal_graph(self, 
                                graph: Dict[str, Any], 
                                metadata: Dict[str, Any],
                                geological_context: Optional[Dict[str, Any]] = None,
                                validate_physics: bool = True) -> str:
        """
        Store causal graph with comprehensive metadata and geological context
        
        Features:
        1. Graph structure persistence with adjacency matrix compression
        2. Node and edge metadata storage with geological annotations
        3. Statistical significance tracking for each causal relationship
        4. Uncertainty quantification storage for confidence intervals
        5. Temporal evolution tracking for dynamic causal patterns
        6. Integration with existing model versioning system
        7. Geological constraint validation and storage
        8. Performance metrics and accuracy tracking
        9. Physics-informed validation before storage
        """
        try:
            if not self.model_database or not self.model_database_initialized:
                self.logger.warning("Model database not initialized, using fallback storage")
                return await self._fallback_causal_graph_storage(graph, metadata)
            
            # Validate causal graph against physics constraints if requested
            if validate_physics and hasattr(self, 'geological_constraints'):
                # Extract states and actions from the graph or context
                states = geological_context.get('states', np.array([])) if geological_context else np.array([])
                actions = geological_context.get('actions', np.array([])) if geological_context else np.array([])
                
                # Perform comprehensive physics-informed validation
                validation_results = await self._validate_causal_with_physics_constraints(
                    graph, states, actions
                )
                
                # Store validation results in metadata
                metadata['physics_validation'] = {
                    'overall_validity': validation_results['overall_validity'],
                    'violations': validation_results.get('physics_violations', []),
                    'optimization_performed': validation_results.get('optimization_performed', False),
                    'conservation_laws': validation_results.get('conservation_laws', {}),
                    'thermodynamic_validity': validation_results.get('thermodynamic_validity', {}),
                    'mechanical_validity': validation_results.get('mechanical_validity', {}),
                    'geological_feasibility': validation_results.get('geological_feasibility', {}),
                    'timestamp': datetime.now().isoformat()
                }
                
                # If optimization was performed, use the optimized graph
                if validation_results.get('optimization_performed', False):
                    graph = validation_results.get('optimized_graph', graph)
                    metadata['graph_optimized'] = True
                
                # Log warning if validity is low
                if validation_results['overall_validity'] < 0.7:
                    self.logger.warning(
                        f"Storing causal graph with low physics validity: {validation_results['overall_validity']}"
                    )
            
            # Generate unique identifier for the causal graph
            graph_id = f"causal_graph_{datetime.now().strftime('%Y%m%d_%H%M%S')}_{hash(str(graph))}"
            
            # 1. Prepare graph structure for storage
            graph_structure = {
                'adjacency_matrix': np.array(graph.get('adjacency_matrix', [])).tolist(),
                'nodes': graph.get('nodes', []),
                'edges': graph.get('edges', []),
                'edge_weights': graph.get('edge_weights', {}),
                'statistical_significance': graph.get('significance_tests', {}),
                'confidence_intervals': graph.get('confidence_intervals', {}),
                'p_values': graph.get('p_values', {}),
                'effect_sizes': graph.get('effect_sizes', {})
            }
            
            # 2. Create comprehensive metadata with geological context
            enhanced_metadata = ModelMetadata(
                id=graph_id,
                name=metadata.get('name', f'Causal_Graph_{datetime.now().strftime("%Y%m%d")}'),
                version=metadata.get('version', '1.0'),
                description=f"Causal discovery results: {metadata.get('description', 'Geological causal relationships')}",
                author=metadata.get('author', 'EnKF_Knowledge_Integration'),
                institution=metadata.get('institution', 'Prometheus_Platform'),
                creation_date=datetime.now(),
                last_modified=datetime.now(),
                model_type='causal_graph',
                region=geological_context.get('region', 'unknown') if geological_context else 'global',
                resolution={
                    'temporal': geological_context.get('temporal_resolution', 1.0) if geological_context else 1.0,
                    'spatial': geological_context.get('spatial_resolution', 1.0) if geological_context else 1.0
                },
                dimensions={
                    'nodes': len(graph_structure['nodes']),
                    'edges': len(graph_structure['edges']),
                    'variables': len(graph.get('variables', []))
                },
                coordinate_system='geological' if geological_context else 'abstract',
                processing_parameters={
                    'algorithm': metadata.get('algorithm', 'ensemble'),
                    'confidence_threshold': metadata.get('confidence_threshold', 0.05),
                    'bootstrap_iterations': metadata.get('bootstrap_iterations', 1000),
                    'geological_constraints_applied': bool(geological_context),
                    'uncertainty_quantification': metadata.get('uncertainty_quantification', True)
                },
                quality_metrics={
                    'graph_density': len(graph_structure['edges']) / (len(graph_structure['nodes']) * (len(graph_structure['nodes']) - 1)),
                    'average_edge_strength': np.mean(list(graph_structure['edge_weights'].values())) if graph_structure['edge_weights'] else 0.0,
                    'significant_relationships': len([p for p in graph_structure['p_values'].values() if p < 0.05]),
                    'geological_consistency_score': geological_context.get('consistency_score', 0.0) if geological_context else 0.0
                },
                tags=['causal_discovery', 'geological_modeling', 'ensemble_learning', 'uncertainty_quantification'],
                file_format='json_compressed'
            )
            
            # 3. Prepare data for storage
            causal_data = {
                'graph_structure': graph_structure,
                'metadata': metadata,
                'geological_context': geological_context or {},
                'storage_timestamp': datetime.now().isoformat(),
                'statistical_validation': graph.get('validation_results', {}),
                'uncertainty_analysis': graph.get('uncertainty_analysis', {})
            }
            
            # 4. Store in model database with compression
            import json
            import gzip
            from pathlib import Path
            
            # Create temporary file for storage
            temp_path = Path(f"/tmp/causal_graph_{graph_id}.json.gz")
            with gzip.open(temp_path, 'wt', encoding='utf-8') as f:
                json.dump(causal_data, f, indent=2, default=str)
            
            # Register with model database
            stored_id = await self.model_database.register_model(
                str(temp_path),
                enhanced_metadata,
                storage_backends=['local']
            )
            
            # 5. Update indices for fast retrieval
            await self._update_causal_knowledge_indices(graph_id, graph, metadata, geological_context)
            
            # 6. Track performance metrics
            await self._track_causal_model_performance(graph_id, {
                'storage_time': datetime.now(),
                'graph_complexity': len(graph_structure['nodes']) * len(graph_structure['edges']),
                'geological_accuracy': geological_context.get('accuracy_score', 0.0) if geological_context else 0.0
            })
            
            # 7. Clean up temporary file
            temp_path.unlink(missing_ok=True)
            
            self.logger.info(f"Causal graph stored successfully: {stored_id}")
            return stored_id
            
        except Exception as e:
            self.logger.error(f"Failed to store causal graph: {e}")
            # Fallback to local storage
            return await self._fallback_causal_graph_storage(graph, metadata)
    
    async def retrieve_causal_graph(self, 
                                   graph_id: str,
                                   version: Optional[str] = None) -> Optional[Dict[str, Any]]:
        """
        Retrieve causal graph with full metadata and geological context
        
        Features:
        1. Fast retrieval using optimized indices
        2. Version-specific graph reconstruction
        3. Metadata validation and integrity checking
        4. Geological context restoration
        5. Statistical significance validation
        6. Uncertainty quantification reconstruction
        7. Performance tracking for retrieval operations
        8. Automatic fallback mechanisms for data integrity
        """
        try:
            if not self.model_database or not self.model_database_initialized:
                self.logger.warning("Model database not available, using fallback retrieval")
                return await self._fallback_causal_graph_retrieval(graph_id)
            
            retrieval_start = datetime.now()
            
            # 1. Get model metadata
            metadata = await self.model_database.get_model_metadata(graph_id)
            if not metadata:
                self.logger.warning(f"Causal graph {graph_id} not found in database")
                return None
            
            # 2. Download model data
            temp_path = f"/tmp/retrieved_causal_{graph_id}.json.gz"
            downloaded_path = await self.model_database.download_model(
                graph_id, 
                version=version,
                local_path=temp_path
            )
            
            # 3. Load and decompress data
            import json
            import gzip
            
            with gzip.open(downloaded_path, 'rt', encoding='utf-8') as f:
                causal_data = json.load(f)
            
            # 4. Reconstruct graph structure
            graph_structure = causal_data.get('graph_structure', {})
            reconstructed_graph = {
                'adjacency_matrix': np.array(graph_structure.get('adjacency_matrix', [])),
                'nodes': graph_structure.get('nodes', []),
                'edges': graph_structure.get('edges', []),
                'edge_weights': graph_structure.get('edge_weights', {}),
                'variables': graph_structure.get('nodes', []),
                'significance_tests': graph_structure.get('statistical_significance', {}),
                'confidence_intervals': graph_structure.get('confidence_intervals', {}),
                'p_values': graph_structure.get('p_values', {}),
                'effect_sizes': graph_structure.get('effect_sizes', {}),
                'validation_results': causal_data.get('statistical_validation', {}),
                'uncertainty_analysis': causal_data.get('uncertainty_analysis', {})
            }
            
            # 5. Add comprehensive metadata
            result = {
                'graph': reconstructed_graph,
                'metadata': causal_data.get('metadata', {}),
                'geological_context': causal_data.get('geological_context', {}),
                'storage_metadata': {
                    'graph_id': graph_id,
                    'version': metadata.version,
                    'stored_date': metadata.creation_date,
                    'retrieved_date': datetime.now(),
                    'retrieval_time_ms': (datetime.now() - retrieval_start).total_seconds() * 1000
                },
                'quality_metrics': metadata.quality_metrics or {},
                'processing_parameters': metadata.processing_parameters or {}
            }
            
            # 6. Validate data integrity
            validation_result = await self._validate_retrieved_causal_graph(result)
            if not validation_result['valid']:
                self.logger.warning(f"Data integrity issues found: {validation_result['issues']}")
                result['integrity_warnings'] = validation_result['issues']
            
            # 7. Update retrieval performance tracking
            await self._track_retrieval_performance(graph_id, {
                'retrieval_time_ms': (datetime.now() - retrieval_start).total_seconds() * 1000,
                'data_size_mb': Path(downloaded_path).stat().st_size / (1024 * 1024),
                'integrity_check': validation_result['valid']
            })
            
            # 8. Clean up temporary file
            Path(downloaded_path).unlink(missing_ok=True)
            
            self.logger.info(f"Causal graph retrieved successfully: {graph_id}")
            return result
            
        except Exception as e:
            self.logger.error(f"Failed to retrieve causal graph {graph_id}: {e}")
            return await self._fallback_causal_graph_retrieval(graph_id)
    
    async def search_causal_graphs(self, 
                                  query: Dict[str, Any],
                                  limit: int = 50) -> List[Dict[str, Any]]:
        """
        Search causal graphs using comprehensive query capabilities
        
        Features:
        1. Multi-criteria search (geological context, variables, relationships)
        2. Temporal range filtering for dynamic causal patterns
        3. Statistical significance filtering
        4. Geological constraint matching
        5. Similarity-based graph structure search
        6. Performance-based ranking
        7. Uncertainty-aware result filtering
        8. Domain-specific geological search patterns
        """
        try:
            if not self.model_database or not self.model_database_initialized:
                return await self._fallback_causal_graph_search(query, limit)
            
            # 1. Prepare search query for model database
            db_query = {}
            
            # Basic filters
            if 'geological_region' in query:
                db_query['region'] = query['geological_region']
            
            if 'algorithm' in query:
                db_query['processing_parameters'] = {'algorithm': query['algorithm']}
            
            if 'min_accuracy' in query:
                db_query['quality_metrics'] = {'geological_consistency_score__gte': query['min_accuracy']}
            
            if 'date_range' in query:
                if 'start' in query['date_range']:
                    db_query['created_after'] = query['date_range']['start']
                if 'end' in query['date_range']:
                    db_query['created_before'] = query['date_range']['end']
            
            # Add model type filter for causal graphs
            db_query['model_type'] = 'causal_graph'
            
            # 2. Search in model database
            models = await self.model_database.search_models(db_query, limit=limit)
            
            # 3. Filter and rank results based on advanced criteria
            filtered_results = []
            
            for model in models:
                # Load graph for detailed filtering
                graph_data = await self.retrieve_causal_graph(model.id)
                if not graph_data:
                    continue
                
                # Apply advanced filters
                if 'variables' in query:
                    required_vars = set(query['variables'])
                    graph_vars = set(graph_data['graph'].get('variables', []))
                    if not required_vars.issubset(graph_vars):
                        continue
                
                if 'min_edge_strength' in query:
                    edge_weights = graph_data['graph'].get('edge_weights', {})
                    max_strength = max(edge_weights.values()) if edge_weights else 0
                    if max_strength < query['min_edge_strength']:
                        continue
                
                if 'causal_relationships' in query:
                    required_rels = query['causal_relationships']
                    graph_edges = graph_data['graph'].get('edges', [])
                    # Check if required relationships exist
                    found_rels = []
                    for edge in graph_edges:
                        if isinstance(edge, (list, tuple)) and len(edge) >= 2:
                            found_rels.append((edge[0], edge[1]))
                    
                    required_found = all(
                        any((rel[0] in edge and rel[1] in edge) for edge in found_rels)
                        for rel in required_rels
                    )
                    if not required_found:
                        continue
                
                # 4. Calculate relevance score
                relevance_score = await self._calculate_causal_graph_relevance(
                    graph_data, query
                )
                
                filtered_results.append({
                    'graph_id': model.id,
                    'metadata': {
                        'name': model.name,
                        'version': model.version,
                        'creation_date': model.creation_date,
                        'quality_metrics': model.quality_metrics,
                        'description': model.description
                    },
                    'relevance_score': relevance_score,
                    'preview': {
                        'node_count': len(graph_data['graph'].get('nodes', [])),
                        'edge_count': len(graph_data['graph'].get('edges', [])),
                        'geological_context': graph_data.get('geological_context', {}),
                        'significant_relationships': len([
                            p for p in graph_data['graph'].get('p_values', {}).values() 
                            if p < 0.05
                        ])
                    }
                })
            
            # 5. Sort by relevance score and return top results
            filtered_results.sort(key=lambda x: x['relevance_score'], reverse=True)
            
            self.logger.info(f"Found {len(filtered_results)} matching causal graphs")
            return filtered_results[:limit]
            
        except Exception as e:
            self.logger.error(f"Causal graph search failed: {e}")
            return await self._fallback_causal_graph_search(query, limit)
    
    async def _update_causal_knowledge_indices(self, graph_id: str, graph: Dict[str, Any], 
                                             metadata: Dict[str, Any], geological_context: Optional[Dict[str, Any]]):
        """Update specialized indices for fast causal knowledge retrieval"""
        try:
            # Update graph structure index
            if 'adjacency_matrix' in graph:
                self.causal_graph_index[graph_id] = {
                    'adjacency_hash': hash(str(graph['adjacency_matrix'])),
                    'node_count': len(graph.get('nodes', [])),
                    'edge_count': len(graph.get('edges', [])),
                    'variables': graph.get('variables', [])
                }
            
            # Update geological process index
            if geological_context:
                process = geological_context.get('process_type', 'unknown')
                self.process_causal_index[process].append({
                    'graph_id': graph_id,
                    'accuracy': geological_context.get('accuracy_score', 0.0),
                    'region': geological_context.get('region', 'unknown')
                })
            
            # Update temporal patterns index
            if 'temporal_lags' in graph:
                for variable, lag in graph['temporal_lags'].items():
                    self.temporal_causal_index[variable][graph_id] = lag
            
            # Update confounder index
            if 'confounders' in graph:
                self.confounder_index[graph_id] = graph['confounders']
            
            # Update uncertainty index
            if 'uncertainty_analysis' in graph:
                self.uncertainty_index[graph_id] = {
                    'confidence_intervals': graph['uncertainty_analysis'].get('confidence_intervals', {}),
                    'bootstrap_results': graph['uncertainty_analysis'].get('bootstrap_results', {})
                }
            
        except Exception as e:
            self.logger.error(f"Failed to update causal knowledge indices: {e}")
    
    async def _track_causal_model_performance(self, graph_id: str, performance_data: Dict[str, Any]):
        """Track performance metrics for causal model storage and retrieval operations"""
        try:
            if graph_id not in self.causal_model_performance:
                self.causal_model_performance[graph_id] = []
            
            self.causal_model_performance[graph_id].append({
                **performance_data,
                'timestamp': datetime.now()
            })
            
            # Limit history to last 100 entries
            self.causal_model_performance[graph_id] = self.causal_model_performance[graph_id][-100:]
            
        except Exception as e:
            self.logger.error(f"Failed to track causal model performance: {e}")
    
    async def _track_retrieval_performance(self, graph_id: str, retrieval_data: Dict[str, Any]):
        """Track retrieval performance metrics"""
        try:
            if 'retrieval_performance' not in self.__dict__:
                self.retrieval_performance = defaultdict(list)
            
            self.retrieval_performance[graph_id].append({
                **retrieval_data,
                'timestamp': datetime.now()
            })
            
            # Limit history
            self.retrieval_performance[graph_id] = self.retrieval_performance[graph_id][-50:]
            
        except Exception as e:
            self.logger.error(f"Failed to track retrieval performance: {e}")
    
    async def _calculate_causal_graph_relevance(self, graph_data: Dict[str, Any], query: Dict[str, Any]) -> float:
        """Calculate relevance score for causal graph search results"""
        try:
            relevance_score = 0.0
            
            # Base relevance from quality metrics
            quality_metrics = graph_data.get('quality_metrics', {})
            if 'geological_consistency_score' in quality_metrics:
                relevance_score += quality_metrics['geological_consistency_score'] * 0.3
            
            # Variable overlap bonus
            if 'variables' in query:
                query_vars = set(query['variables'])
                graph_vars = set(graph_data['graph'].get('variables', []))
                overlap_ratio = len(query_vars.intersection(graph_vars)) / len(query_vars) if query_vars else 0
                relevance_score += overlap_ratio * 0.4
            
            # Geological context matching
            if 'geological_region' in query:
                geological_context = graph_data.get('geological_context', {})
                if geological_context.get('region') == query['geological_region']:
                    relevance_score += 0.2
            
            # Statistical significance bonus
            p_values = graph_data['graph'].get('p_values', {})
            significant_count = len([p for p in p_values.values() if p < 0.05])
            total_relationships = len(p_values) if p_values else 1
            significance_ratio = significant_count / total_relationships
            relevance_score += significance_ratio * 0.1
            
            return min(relevance_score, 1.0)  # Cap at 1.0
            
        except Exception as e:
            self.logger.error(f"Failed to calculate relevance score: {e}")
            return 0.0
    
    async def _validate_retrieved_causal_graph(self, graph_data: Dict[str, Any]) -> Dict[str, Any]:
        """Validate integrity and consistency of retrieved causal graph data"""
        try:
            validation_result = {'valid': True, 'issues': []}
            
            # Check required fields
            required_fields = ['graph', 'metadata', 'geological_context']
            for field in required_fields:
                if field not in graph_data:
                    validation_result['issues'].append(f"Missing required field: {field}")
                    validation_result['valid'] = False
            
            # Validate graph structure
            graph = graph_data.get('graph', {})
            if 'nodes' in graph and 'edges' in graph:
                # Check edge consistency
                nodes = set(graph['nodes'])
                for edge in graph['edges']:
                    if isinstance(edge, (list, tuple)) and len(edge) >= 2:
                        if edge[0] not in nodes or edge[1] not in nodes:
                            validation_result['issues'].append(f"Edge references non-existent node: {edge}")
                            validation_result['valid'] = False
            
            # Check statistical significance consistency
            if 'p_values' in graph:
                p_values = graph['p_values']
                for rel, p_value in p_values.items():
                    if not (0 <= p_value <= 1):
                        validation_result['issues'].append(f"Invalid p-value for {rel}: {p_value}")
                        validation_result['valid'] = False
            
            return validation_result
            
        except Exception as e:
            self.logger.error(f"Graph validation failed: {e}")
            return {'valid': False, 'issues': [f"Validation error: {e}"]}
    
    async def _fallback_causal_graph_storage(self, graph: Dict[str, Any], metadata: Dict[str, Any]) -> str:
        """Fallback storage mechanism for causal graphs"""
        try:
            import json
            from pathlib import Path
            
            # Create fallback directory
            fallback_dir = Path("./fallback_causal_storage")
            fallback_dir.mkdir(exist_ok=True)
            
            # Generate fallback ID
            fallback_id = f"fallback_{datetime.now().strftime('%Y%m%d_%H%M%S')}_{hash(str(graph))}"
            
            # Store data
            fallback_data = {
                'graph': graph,
                'metadata': metadata,
                'storage_timestamp': datetime.now().isoformat(),
                'storage_type': 'fallback'
            }
            
            fallback_path = fallback_dir / f"{fallback_id}.json"
            with open(fallback_path, 'w') as f:
                json.dump(fallback_data, f, indent=2, default=str)
            
            self.logger.info(f"Causal graph stored in fallback location: {fallback_id}")
            return fallback_id
            
        except Exception as e:
            self.logger.error(f"Fallback storage failed: {e}")
            return f"storage_failed_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
    
    async def _fallback_causal_graph_retrieval(self, graph_id: str) -> Optional[Dict[str, Any]]:
        """Fallback retrieval mechanism for causal graphs"""
        try:
            from pathlib import Path
            import json
            
            # Check fallback directory
            fallback_dir = Path("./fallback_causal_storage")
            fallback_path = fallback_dir / f"{graph_id}.json"
            
            if fallback_path.exists():
                with open(fallback_path, 'r') as f:
                    fallback_data = json.load(f)
                
                self.logger.info(f"Retrieved causal graph from fallback: {graph_id}")
                return fallback_data
            
            return None
            
        except Exception as e:
            self.logger.error(f"Fallback retrieval failed: {e}")
            return None
    
    async def _fallback_causal_graph_search(self, query: Dict[str, Any], limit: int) -> List[Dict[str, Any]]:
        """Fallback search mechanism for causal graphs"""
        try:
            from pathlib import Path
            import json
            
            results = []
            fallback_dir = Path("./fallback_causal_storage")
            
            if not fallback_dir.exists():
                return []
            
            # Search through fallback files
            for fallback_file in fallback_dir.glob("*.json"):
                try:
                    with open(fallback_file, 'r') as f:
                        data = json.load(f)
                    
                    # Simple matching
                    graph = data.get('graph', {})
                    metadata = data.get('metadata', {})
                    
                    # Check basic criteria
                    match = True
                    if 'variables' in query:
                        query_vars = set(query['variables'])
                        graph_vars = set(graph.get('variables', []))
                        if not query_vars.issubset(graph_vars):
                            match = False
                    
                    if match:
                        results.append({
                            'graph_id': fallback_file.stem,
                            'metadata': metadata,
                            'relevance_score': 0.5,  # Default score
                            'preview': {
                                'node_count': len(graph.get('nodes', [])),
                                'edge_count': len(graph.get('edges', [])),
                                'source': 'fallback_storage'
                            }
                        })
                        
                        if len(results) >= limit:
                            break
                            
                except Exception as e:
                    self.logger.warning(f"Failed to process fallback file {fallback_file}: {e}")
                    continue
            
            return results
            
        except Exception as e:
            self.logger.error(f"Fallback search failed: {e}")
            return []
    
    async def _calculate_geological_consistency_score(self, graph: Dict[str, Any]) -> float:
        """Calculate geological consistency score for causal relationships"""
        try:
            if not graph or 'edges' not in graph:
                return 0.0
            
            consistency_score = 0.0
            total_relationships = len(graph['edges'])
            
            if total_relationships == 0:
                return 0.0
            
            for edge in graph['edges']:
                if isinstance(edge, (list, tuple)) and len(edge) >= 2:
                    # Check if causal relationship makes geological sense
                    cause, effect = edge[0], edge[1]
                    
                    # Geological domain knowledge validation
                    geological_validity = await self._validate_geological_causal_relationship(cause, effect)
                    consistency_score += geological_validity
            
            return consistency_score / total_relationships
            
        except Exception as e:
            self.logger.error(f"Failed to calculate geological consistency score: {e}")
            return 0.0
    
