    async def _create_causal_ab_test(self, test_name: str, test_config: Dict[str, Any]):
        """Create specific A/B test for causal discovery"""
        try:
            if test_name == 'algorithm_comparison' and 'models' in test_config:
                # Multi-variant test for algorithm comparison
                test_id = self.mlops_pipeline.ab_test_manager.create_multi_variant_test(
                    test_name=f"causal_{test_name}",
                    model_variants=test_config['models'],
                    traffic_split=test_config['traffic_split'],
                    success_metrics=test_config['success_metrics'],
                    duration_hours=test_config['test_duration_hours']
                )
                
            elif test_name == 'hyperparameter_optimization':
                # Hyperparameter A/B test
                variations = test_config['variations']
                test_id = self.mlops_pipeline.ab_test_manager.create_ab_test(
                    test_name=f"causal_{test_name}",
                    model_a_id=f"{test_config['model']}_variant_a",
                    model_b_id=f"{test_config['model']}_variant_b",
                    success_metrics=test_config['success_metrics']
                )
                
            else:
                # Standard A/B test
                test_id = self.mlops_pipeline.ab_test_manager.create_ab_test(
                    test_name=f"causal_{test_name}",
                    model_a_id=test_config['baseline'],
                    model_b_id=test_config['treatment'],
                    success_metrics=test_config['metrics']
                )
            
            self.logger.debug(f"Created A/B test for {test_name}: {test_id}")
            
        except Exception as e:
            self.logger.warning(f"Failed to create A/B test for {test_name}: {e}")
    
