    async def _train_constraint_optimizer(self):
        """Train ML-based constraint optimizer with historical data"""
        try:
            if self.ml_constraint_optimizer is None:
                return
            
            # Generate or load training data
            training_data = await self._generate_constraint_training_data()
            
            if training_data and len(training_data['features']) > 100:
                # Train the optimizer
                self.ml_constraint_optimizer.train(
                    features=training_data['features'],
                    constraint_satisfaction=training_data['satisfaction_scores'],
                    violation_patterns=training_data.get('violation_patterns', [])
                )
                
                self.logger.info("ML constraint optimizer trained successfully")
            
        except Exception as e:
            self.logger.error(f"Error training constraint optimizer: {e}")
    
