        major_elements = ['sio2', 'al2o3', 'feo', 'mgo', 'cao', 'na2o', 'k2o', 'tio2']
        element_values = {}
        
        for element in major_elements:
            values = self._extract_parameter_values(parameters, [element, element.upper(), element.replace('2', '_')])
