class SeismicDataScaler:
    """Advanced scaler for seismic data with velocity and amplitude considerations."""
    
    def __init__(self):
        self.velocity_ranges = {'p_wave': (1500, 8000), 's_wave': (800, 4500)}
        self.amplitude_statistics = {}
        self.frequency_characteristics = {}
    
    def scale(self, data: np.ndarray) -> np.ndarray:
        """Scale seismic data considering velocity and frequency content."""
        # Velocity-based scaling
        velocity_scaled = self._velocity_based_scaling(data)
        
        # Amplitude normalization with geological constraints
        amplitude_scaled = self._geological_amplitude_scaling(velocity_scaled)
        
        # Frequency domain normalization
        frequency_scaled = self._frequency_domain_scaling(amplitude_scaled)
        
        return frequency_scaled

