class GeologicalPreprocessor:
    """
    Advanced geological data preprocessing with multi-scale analysis,
    domain-specific transformations, and uncertainty quantification.
    """
    
    def __init__(self):
        self.scaling_methods = {
            'seismic': SeismicDataScaler(),
            'geochemical': GeochemicalDataScaler(),
            'structural': StructuralDataScaler(),
            'magnetic': MagneticDataScaler(),
            'gravity': GravityDataScaler()
        }
        self.feature_transformers = self._initialize_feature_transformers()
        self.noise_filters = self._initialize_noise_filters()
        self.outlier_detectors = self._initialize_outlier_detectors()
        self.uncertainty_estimators = self._initialize_uncertainty_estimators()
    
    def process(self, x: np.ndarray, data_type: str = 'mixed') -> np.ndarray:
        """
        Comprehensive preprocessing with domain-specific transformations.
        
        Args:
            x: Input data array
            data_type: Type of geological data
            
        Returns:
            np.ndarray: Processed and enhanced data
        """
        # Multi-stage preprocessing pipeline
        processed_data = x.copy()
        
        # Stage 1: Noise filtering and outlier detection
        processed_data = self._filter_noise(processed_data, data_type)
        processed_data = self._detect_and_handle_outliers(processed_data, data_type)
        
        # Stage 2: Domain-specific scaling and normalization
        processed_data = self._apply_domain_scaling(processed_data, data_type)
        
        # Stage 3: Feature transformation and enhancement
        processed_data = self._transform_features(processed_data, data_type)
        
        # Stage 4: Multi-scale decomposition
        processed_data = self._apply_multiscale_decomposition(processed_data)
        
        # Stage 5: Uncertainty quantification
        processed_data = self._quantify_and_propagate_uncertainty(processed_data)
        
        return processed_data
    
    def _initialize_feature_transformers(self) -> dict:
        """Initialize comprehensive feature transformation methods."""
        return {
            'wavelet': WaveletTransformer(wavelet_family='daubechies', scales=8),
            'fourier': AdvancedFourierTransformer(window_type='hanning'),
            'empirical_mode': EmpiricalModeDecomposer(n_modes=10),
            'principal_component': GeologicalPCATransformer(n_components=0.95),
            'independent_component': GeologicalICATransformer(n_components=None),
            'sparse_coding': SparseCodingTransformer(n_atoms=256, alpha=0.1),
            'multifractal': MultifractalTransformer(q_range=(-10, 10)),
            'hilbert_huang': HilbertHuangTransformer(sifting_threshold=0.01)
        }
    
    def _initialize_noise_filters(self) -> dict:
        """Initialize advanced noise filtering methods."""
        return {
            'adaptive_wiener': AdaptiveWienerFilter(noise_variance_estimation='robust'),
            'anisotropic_diffusion': AnisotropicDiffusionFilter(iterations=10, kappa=50),
            'bilateral': BilateralFilter(sigma_spatial=5, sigma_intensity=0.1),
            'non_local_means': NonLocalMeansFilter(h=0.1, template_window_size=7),
            'morphological': MorphologicalFilter(structure_element='disk', size=3),
            'total_variation': TotalVariationDenoising(weight=0.1, iterations=100),
            'spectral_subtraction': SpectralSubtractionFilter(alpha=2, beta=0.001),
            'empirical_mode_filtering': EMDFilter(noise_mode_threshold=0.1)
        }
    
    def _initialize_outlier_detectors(self) -> dict:
        """Initialize advanced outlier detection methods."""
        return {
            'isolation_forest': GeologicalIsolationForest(contamination=0.1),
            'local_outlier_factor': GeologicalLOF(n_neighbors=20),
            'one_class_svm': GeologicalOneClassSVM(nu=0.05, gamma='scale'),
            'elliptic_envelope': GeologicalEllipticEnvelope(contamination=0.1),
            'dbscan': GeologicalDBSCAN(eps=0.5, min_samples=5),
            'statistical_outlier': StatisticalOutlierDetector(z_threshold=3.5),
            'mahalanobis': MahalanobisOutlierDetector(chi2_threshold=0.95),
            'geological_domain': GeologicalDomainOutlierDetector()
        }
    
    def _initialize_uncertainty_estimators(self) -> dict:
        """Initialize uncertainty estimation methods."""
        return {
            'bootstrap': BootstrapUncertaintyEstimator(n_bootstrap=1000),
            'monte_carlo_dropout': MCDropoutUncertaintyEstimator(n_samples=100),
            'bayesian_neural_network': BayesianNeuralNetworkUncertainty(),
            'conformal_prediction': ConformalPredictionUncertainty(alpha=0.1),
            'ensemble': EnsembleUncertaintyEstimator(n_estimators=10),
            'gaussian_process': GaussianProcessUncertainty(kernel='rbf'),
            'deep_ensemble': DeepEnsembleUncertainty(n_models=5),
            'geological_uncertainty': GeologicalUncertaintyEstimator()
        }
    
    def _filter_noise(self, data: np.ndarray, data_type: str) -> np.ndarray:
        """Advanced multi-method noise filtering with adaptive selection."""
        # Noise characteristics analysis
        noise_characteristics = self._analyze_noise_characteristics(data, data_type)
        
        # Adaptive filter selection based on noise type
        optimal_filters = self._select_optimal_filters(noise_characteristics, data_type)
        
        # Multi-stage filtering
        filtered_data = data.copy()
        for filter_name in optimal_filters:
            filter_obj = self.noise_filters[filter_name]
            filtered_data = filter_obj.filter(filtered_data)
            
            # Validation of filtering effectiveness
            filtering_quality = self._assess_filtering_quality(data, filtered_data)
            if filtering_quality < 0.7:  # Quality threshold
                # Adjust filter parameters or try alternative
                filtered_data = self._adaptive_filter_adjustment(
                    data, filtered_data, filter_obj, noise_characteristics
                )
        
        return filtered_data
    
    def _detect_and_handle_outliers(self, data: np.ndarray, data_type: str) -> np.ndarray:
        """Comprehensive outlier detection with geological domain validation."""
        # Multi-method outlier detection
        outlier_scores = {}
        for detector_name, detector in self.outlier_detectors.items():
            outlier_scores[detector_name] = detector.detect(data)
        
        # Consensus-based outlier identification
        consensus_outliers = self._compute_outlier_consensus(outlier_scores)
        
        # Geological domain validation of outliers
        validated_outliers = self._validate_geological_outliers(
            consensus_outliers, data, data_type
        )
        
        # Intelligent outlier handling
        handled_data = self._handle_validated_outliers(
            data, validated_outliers, data_type
        )
        
        return handled_data
    
    def _apply_domain_scaling(self, data: np.ndarray, data_type: str) -> np.ndarray:
        """Apply domain-specific scaling with geological constraints."""
        if data_type in self.scaling_methods:
            scaler = self.scaling_methods[data_type]
            scaled_data = scaler.scale(data)
        else:
            # Mixed or unknown data type - apply composite scaling
            scaled_data = self._apply_composite_scaling(data)
        
        # Validate scaling effectiveness
        scaling_quality = self._validate_scaling_quality(data, scaled_data, data_type)
        
        # Adaptive scaling adjustment if needed
        if scaling_quality < 0.8:
            scaled_data = self._adaptive_scaling_adjustment(
                data, scaled_data, data_type
            )
        
        return scaled_data
    
    def _transform_features(self, data: np.ndarray, data_type: str) -> np.ndarray:
        """Advanced feature transformation with geological domain enhancement."""
        transformed_features = []
        transformation_effectiveness = {}
        
        # Apply multiple transformations
        for transform_name, transformer in self.feature_transformers.items():
            try:
                transformed = transformer.transform(data)
                effectiveness = self._assess_transformation_effectiveness(
                    data, transformed, data_type
                )
                transformation_effectiveness[transform_name] = effectiveness
                transformed_features.append(transformed)
            except Exception as e:
                # Handle transformation failures gracefully
                continue
        
        # Select and combine most effective transformations
        optimal_transformations = self._select_optimal_transformations(
            transformation_effectiveness, threshold=0.6
        )
        
        # Intelligent feature combination
        combined_features = self._combine_transformed_features(
            transformed_features, optimal_transformations, data
        )
        
        return combined_features
    
    def _apply_multiscale_decomposition(self, data: np.ndarray) -> np.ndarray:
        """Advanced multi-scale decomposition with geological scale awareness."""
        # Wavelet-based multi-scale decomposition
        wavelet_decomposition = self._wavelet_multiscale_decomposition(data)
        
        # Empirical mode decomposition
        emd_decomposition = self._empirical_mode_decomposition(data)
        
        # Fourier-based scale decomposition
        fourier_decomposition = self._fourier_scale_decomposition(data)
        
        # Multifractal decomposition
        multifractal_decomposition = self._multifractal_decomposition(data)
        
        # Scale-aware feature integration
        integrated_scales = self._integrate_multiscale_features(
            wavelet_decomposition, emd_decomposition, 
            fourier_decomposition, multifractal_decomposition
        )
        
        # Geological scale validation
        validated_scales = self._validate_geological_scales(integrated_scales, data)
        
        return validated_scales
    
    def _quantify_and_propagate_uncertainty(self, data: np.ndarray) -> np.ndarray:
        """Comprehensive uncertainty quantification and propagation."""
        uncertainty_estimates = {}
        
        # Multiple uncertainty estimation methods
        for estimator_name, estimator in self.uncertainty_estimators.items():
            try:
                uncertainty = estimator.estimate_uncertainty(data)
                uncertainty_estimates[estimator_name] = uncertainty
            except Exception as e:
                continue
        
        # Uncertainty consensus and validation
        consensus_uncertainty = self._compute_uncertainty_consensus(uncertainty_estimates)
        
        # Uncertainty propagation through preprocessing pipeline
        propagated_uncertainty = self._propagate_uncertainty_through_pipeline(
            data, consensus_uncertainty
        )
        
        # Enhanced data with uncertainty information
        uncertainty_enhanced_data = self._integrate_uncertainty_information(
            data, propagated_uncertainty
        )
        
        return uncertainty_enhanced_data

