class SpectralGeologicalFeatureExtractor:
    """
    Extract comprehensive spectral geological features using advanced frequency domain analysis
    with geological domain expertise and multi-method spectral characterization.
    """
    
    def __init__(self, n_frequencies: int = 64, sampling_rate: float = 1.0, 
                 geological_context: dict = None):
        self.n_frequencies = n_frequencies
        self.sampling_rate = sampling_rate
        self.geological_context = geological_context or {}
        
        # Advanced spectral analysis components
        self.spectral_analyzers = self._initialize_comprehensive_spectral_analyzers()
        self.geological_interpreters = self._initialize_geological_interpreters()
        self.frequency_bands = self._define_geological_frequency_bands()
        self.spectral_validators = self._initialize_spectral_validators()
        
        # Mathematical transformation engines
        self.fft_engine = self._initialize_advanced_fft_engine()
        self.stft_engine = self._initialize_stft_engine()
        self.periodogram_analyzers = self._initialize_periodogram_analyzers()
        self.coherence_analyzers = self._initialize_coherence_analyzers()
        
        # Geological spectral knowledge base
        self.geological_spectral_signatures = self._load_geological_spectral_signatures()
        self.seismic_frequency_bands = self._define_seismic_frequency_bands()
        self.geophysical_spectral_patterns = self._load_geophysical_spectral_patterns()
        
    def extract_features(self, x: np.ndarray, geological_context: dict = None) -> dict:
        """
        Extract comprehensive spectral geological features with advanced analysis.
        
        Args:
            x: Input geological data array
            geological_context: Additional geological context information
            
        Returns:
            dict: Comprehensive spectral feature dictionary
        """
        context = {**(self.geological_context or {}), **(geological_context or {})}
        
        try:
            # Validate input data quality
            validation_results = self._validate_spectral_input(x)
            if not validation_results['is_valid']:
                return self._handle_invalid_spectral_input(x, validation_results)
            
            # Comprehensive spectral feature extraction
            features = {}
            
            # Advanced frequency content analysis
            features['frequency_content'] = self._analyze_comprehensive_frequency_content(x, context)
            
            # Geological spectral peak identification with domain expertise
            features['spectral_peaks'] = self._identify_geological_spectral_peaks(x, context)
            
            # Multi-method bandwidth analysis
            features['bandwidth_analysis'] = self._analyze_comprehensive_bandwidth(x, context)
            
            # Advanced spectral coherence with geological interpretation
            features['spectral_coherence'] = self._compute_geological_spectral_coherence(x, context)
            
            # Power spectral density analysis
            features['power_spectrum'] = self._analyze_power_spectral_density(x, context)
            
            # Spectral entropy and complexity measures
            features['spectral_entropy'] = self._compute_spectral_entropy_measures(x, context)
            
            # Cross-spectral analysis for multi-channel data
            features['cross_spectrum'] = self._analyze_cross_spectral_features(x, context)
            
            # Geological spectral pattern matching
            features['geological_patterns'] = self._match_geological_spectral_patterns(x, context)
            
            # Spectral anomaly detection
            features['spectral_anomalies'] = self._detect_spectral_anomalies(x, context)
            
            # Spectral stability and stationarity analysis
            features['spectral_stability'] = self._analyze_spectral_stability(x, context)
            
            # Feature quality assessment
            features['quality_metrics'] = self._assess_spectral_feature_quality(features, context)
            
            return features
            
        except Exception as e:
            return self._handle_spectral_extraction_error(e, x, context)
    
    def _initialize_comprehensive_spectral_analyzers(self) -> dict:
        """Initialize comprehensive spectral analysis components."""
        return {
            'fft_analyzer': self._create_advanced_fft_analyzer(),
            'welch_analyzer': self._create_welch_periodogram_analyzer(),
            'multitaper_analyzer': self._create_multitaper_analyzer(),
            'wavelet_spectrum_analyzer': self._create_wavelet_spectrum_analyzer(),
            'autoregressive_analyzer': self._create_ar_spectrum_analyzer(),
            'music_analyzer': self._create_music_spectrum_analyzer(),
            'eigenvalue_analyzer': self._create_eigenvalue_spectrum_analyzer(),
            'geological_spectrum_matcher': self._create_geological_spectrum_matcher()
        }
    
    def _analyze_comprehensive_frequency_content(self, x: np.ndarray, context: dict) -> dict:
        """Analyze frequency content using multiple advanced methods."""
        frequency_analysis = {}
        
        # FFT-based frequency analysis
        fft_result = self.spectral_analyzers['fft_analyzer'].analyze(x)
        frequency_analysis['fft_spectrum'] = {
            'frequencies': fft_result['frequencies'],
            'magnitudes': fft_result['magnitudes'],
            'phases': fft_result['phases'],
            'power': fft_result['power']
        }
        
        # Welch periodogram for robust power spectral density
        welch_result = self.spectral_analyzers['welch_analyzer'].compute_psd(x)
        frequency_analysis['welch_psd'] = {
            'frequencies': welch_result['frequencies'],
            'power_density': welch_result['psd'],
            'confidence_intervals': welch_result['confidence_intervals']
        }
        
        # Multitaper method for high-resolution spectral estimation
        multitaper_result = self.spectral_analyzers['multitaper_analyzer'].estimate_spectrum(x)
        frequency_analysis['multitaper_spectrum'] = {
            'frequencies': multitaper_result['frequencies'],
            'spectrum': multitaper_result['spectrum'],
            'bandwidth': multitaper_result['bandwidth'],
            'degrees_of_freedom': multitaper_result['dof']
        }
        
        # Autoregressive spectral estimation
        ar_result = self.spectral_analyzers['autoregressive_analyzer'].estimate_spectrum(x)
        frequency_analysis['ar_spectrum'] = {
            'frequencies': ar_result['frequencies'],
            'spectrum': ar_result['spectrum'],
            'model_order': ar_result['order'],
            'coefficients': ar_result['coefficients']
        }
        
        # Geological frequency band analysis
        frequency_analysis['geological_bands'] = self._analyze_geological_frequency_bands(x, context)
        
        # Dominant frequency identification with geological interpretation
        frequency_analysis['dominant_frequencies'] = self._identify_dominant_frequencies(x, context)
        
        return frequency_analysis
    
    def _identify_geological_spectral_peaks(self, x: np.ndarray, context: dict) -> dict:
        """Identify spectral peaks with geological domain expertise."""
        peak_analysis = {}
        
        # Multi-method peak detection
        peak_methods = {
            'local_maxima': self._find_local_maxima_peaks(x),
            'prominence_based': self._find_prominence_peaks(x),
            'geological_signatures': self._find_geological_signature_peaks(x, context),
            'adaptive_threshold': self._find_adaptive_threshold_peaks(x),
            'wavelet_peaks': self._find_wavelet_based_peaks(x)
        }
        
        # Peak characterization
        for method, peaks in peak_methods.items():
            peak_analysis[f'{method}_peaks'] = {
                'frequencies': peaks['frequencies'],
                'amplitudes': peaks['amplitudes'],
                'widths': peaks['widths'],
                'geological_interpretation': self._interpret_peaks_geologically(peaks, context),
                'confidence_scores': peaks['confidence_scores']
            }
        
        # Consensus peak identification
        peak_analysis['consensus_peaks'] = self._compute_consensus_peaks(peak_methods, context)
        
        # Peak stability analysis
        peak_analysis['peak_stability'] = self._analyze_peak_stability(x, context)
        
        # Geological peak classification
