    async def _statistical_feedback_significance_testing(self, feedback_loop_sets: List[List[Dict]]) -> List[Dict]:
        """Statistical significance testing for identified feedback loops."""
        try:
            significant_loops = []
            
            # Flatten all feedback loops
            all_loops = []
            for loop_set in feedback_loop_sets:
                all_loops.extend(loop_set)
            
            for loop in all_loops:
                # Permutation test for feedback significance
                p_value = await self._permutation_test_feedback_significance(loop)
                loop['statistical_p_value'] = p_value
                
                # Bootstrap confidence interval for strength
                confidence_interval = await self._bootstrap_feedback_strength_confidence(loop)
                loop['strength_confidence_interval'] = confidence_interval
                
                # Multiple testing correction
                corrected_p_value = await self._apply_multiple_testing_correction(p_value, len(all_loops))
                loop['corrected_p_value'] = corrected_p_value
                
                # Keep statistically significant loops
                if corrected_p_value < 0.05:
                    loop['statistically_significant'] = True
                    significant_loops.append(loop)
                else:
                    loop['statistically_significant'] = False
            
            return significant_loops
            
        except Exception as e:
            self.logger.error(f"Statistical significance testing failed: {e}")
            return [loop for loop_set in feedback_loop_sets for loop in loop_set]

    async def _dynamic_feedback_strength_estimation(self, feedback_loops: List[Dict]) -> List[Dict]:
        """Dynamic estimation of feedback loop strength with uncertainty quantification."""
        try:
            strength_estimated_loops = []
            
            for loop in feedback_loops:
                # Multi-method strength estimation
                strength_estimates = {}
                
                # Correlation-based strength
                correlation_strength = await self._calculate_correlation_feedback_strength(loop)
                strength_estimates['correlation'] = correlation_strength
                
                # Information-theoretic strength
                info_theoretic_strength = await self._calculate_information_theoretic_feedback_strength(loop)
                strength_estimates['information_theoretic'] = info_theoretic_strength
                
                # Causal effect size strength
                causal_effect_strength = await self._calculate_causal_effect_feedback_strength(loop)
                strength_estimates['causal_effect'] = causal_effect_strength
                
                # Time-varying strength estimation
                time_varying_strength = await self._estimate_time_varying_feedback_strength(loop)
                strength_estimates['time_varying'] = time_varying_strength
                
                # Ensemble strength with uncertainty
                ensemble_strength = np.mean(list(strength_estimates.values()))
                strength_uncertainty = np.std(list(strength_estimates.values()))
                
                loop['strength'] = ensemble_strength
                loop['strength_uncertainty'] = strength_uncertainty
                loop['strength_estimates'] = strength_estimates
                loop['strength_reliability'] = 1.0 / (1.0 + strength_uncertainty)
                
                strength_estimated_loops.append(loop)
            
            return strength_estimated_loops
            
        except Exception as e:
            self.logger.error(f"Dynamic strength estimation failed: {e}")
            return feedback_loops

