    async def _rank_and_validate_feedback_loops(self, feedback_loops: List[Dict]) -> List[Dict]:
        """Rank and validate detected feedback loops."""
        try:
            # Calculate comprehensive ranking scores
            for loop in feedback_loops:
                ranking_score = (
                    0.25 * loop.get('strength', 0.0) +
                    0.20 * loop.get('strength_reliability', 0.0) +
                    0.15 * loop.get('geological_relevance', 0.5) +
                    0.15 * loop.get('flow_efficiency', 0.5) +
                    0.10 * loop.get('temporal_stability', 0.5) +
                    0.10 * loop.get('evolution_confidence', 0.5) +
                    0.05 * (1.0 if loop.get('statistically_significant', False) else 0.0)
                )
                loop['ranking_score'] = ranking_score
            
            # Sort by ranking score
            feedback_loops.sort(key=lambda x: x['ranking_score'], reverse=True)
            
            # Select top feedback loops
            top_feedback_loops = feedback_loops[:20]
            
            # Add validation metadata
            for i, loop in enumerate(top_feedback_loops):
                loop['validation_rank'] = i + 1
                loop['validation_confidence'] = min(1.0, loop['ranking_score'] / 0.8)
                loop['validation_status'] = 'validated' if loop['ranking_score'] > 0.6 else 'tentative'
            
            return top_feedback_loops
            
        except Exception as e:
            self.logger.error(f"Feedback loop ranking failed: {e}")
            return feedback_loops[:15]

