    async def _validate_with_geological_constraints(self, graph: Dict) -> Dict:
        """Validate causal graph against geological domain constraints."""
        try:
            if not hasattr(self, 'geo_constraints'):
                return graph
                
            validated_graph = {}
            
            for edge_key, properties in graph.items():
                # Check if edge is geologically plausible
                is_valid = await self.geo_constraints.validate_causal_relationship(
                    edge_key, properties
                )
                
                if is_valid:
                    # Enhance with geological validation score
                    properties['geological_validity'] = await self.geo_constraints.score_geological_validity(
                        edge_key, properties
                    )
                    validated_graph[edge_key] = properties
                else:
                    self.logger.debug(f"Edge {edge_key} rejected by geological constraints")
            
            return validated_graph
            
        except Exception as e:
            self.logger.error(f"Geological validation failed: {e}")
            return graph
    
    async def _enhance_with_pattern_discovery(self, graph: Dict) -> Dict:
        """Enhance causal graph with hidden relationship pattern discovery."""
        try:
            if not hasattr(self, 'relationship_discovery'):
                return graph
            
            enhanced_graph = graph.copy()
            
            # Discover hidden patterns in the causal graph
            hidden_patterns = await self.relationship_discovery.discover_causal_patterns(graph)
            
            # Integrate discovered patterns into the graph
            for pattern in hidden_patterns:
                pattern_edges = pattern.get('edges', [])
                for edge_key in pattern_edges:
                    if edge_key in enhanced_graph:
                        enhanced_graph[edge_key]['hidden_patterns'] = enhanced_graph[edge_key].get('hidden_patterns', [])
                        enhanced_graph[edge_key]['hidden_patterns'].append(pattern)
            
            return enhanced_graph
            
        except Exception as e:
            self.logger.error(f"Pattern discovery enhancement failed: {e}")
            return graph
    
