    def _analyze_attractor_geometry(self, phase_space: np.ndarray) -> Dict:
        """Analyze geometric properties of the reconstructed attractor"""
        try:
            results = {}
            
            if phase_space.size == 0 or len(phase_space) < 10:
                return {'attractor_analysis_error': 'insufficient_data'}
            
            # Attractor trajectory properties
            trajectory_vectors = np.diff(phase_space, axis=0)
            trajectory_lengths = np.linalg.norm(trajectory_vectors, axis=1)
            
            results['total_trajectory_length'] = float(np.sum(trajectory_lengths))
            results['mean_step_length'] = float(np.mean(trajectory_lengths))
            results['trajectory_length_variance'] = float(np.var(trajectory_lengths))
            
            # Attractor volume estimation using convex hull
            try:
                from scipy.spatial import ConvexHull
                hull = ConvexHull(phase_space)
                results['attractor_volume'] = float(hull.volume)
                results['attractor_surface_area'] = float(hull.area)
                results['hull_vertices_count'] = len(hull.vertices)
            except Exception:
                results['attractor_volume'] = 0.0
                results['attractor_surface_area'] = 0.0
            
            # Centroid and spread analysis
            centroid = np.mean(phase_space, axis=0)
            distances_from_centroid = np.linalg.norm(phase_space - centroid, axis=1)
            
            results['attractor_centroid'] = centroid.tolist()
            results['mean_distance_from_centroid'] = float(np.mean(distances_from_centroid))
            results['max_distance_from_centroid'] = float(np.max(distances_from_centroid))
            results['attractor_radius'] = results['max_distance_from_centroid']
            
            # Attractor density distribution
            try:
                from scipy.stats import gaussian_kde
                kde = gaussian_kde(phase_space.T)
                density_estimate = kde(phase_space.T)
                results['density_heterogeneity'] = float(np.std(density_estimate))
                results['max_density'] = float(np.max(density_estimate))
                results['mean_density'] = float(np.mean(density_estimate))
            except Exception:
                results['density_heterogeneity'] = 0.0
            
            # Principal component analysis of attractor
            from sklearn.decomposition import PCA
            pca = PCA()
            pca.fit(phase_space)
            
            results['pca_explained_variance_ratio'] = pca.explained_variance_ratio_.tolist()
            results['effective_dimensionality'] = float(np.sum(pca.explained_variance_ratio_ > 0.01))
            results['pca_components'] = pca.components_.tolist()
            
            return results
            
        except Exception as e:
            self.logger.error(f"Attractor geometry analysis failed: {e}")
            return {'attractor_analysis_error': str(e)}
    
    def _compute_multi_method_fractal_dimension(self, phase_space: np.ndarray) -> Dict:
        """Compute fractal dimension using multiple methods for robustness"""
        try:
            fractal_results = {}
            
            # Box-counting dimension
            try:
                box_counting_dim = self._box_counting_dimension(phase_space)
                fractal_results['box_counting_dimension'] = box_counting_dim
            except Exception as e:
                self.logger.warning(f"Box counting dimension failed: {e}")
                fractal_results['box_counting_dimension'] = 0.0
            
            # Information dimension
            try:
                info_dim = self._information_dimension(phase_space)
                fractal_results['information_dimension'] = info_dim
            except Exception as e:
                self.logger.warning(f"Information dimension failed: {e}")
                fractal_results['information_dimension'] = 0.0
            
            # Kaplan-Yorke dimension estimate
            try:
                ky_dim = self._kaplan_yorke_dimension(phase_space)
                fractal_results['kaplan_yorke_dimension'] = ky_dim
            except Exception as e:
                self.logger.warning(f"Kaplan-Yorke dimension failed: {e}")
                fractal_results['kaplan_yorke_dimension'] = 0.0
            
            # Average fractal dimension
            valid_dimensions = [v for v in fractal_results.values() if v > 0]
            if valid_dimensions:
                fractal_results['mean_fractal_dimension'] = float(np.mean(valid_dimensions))
                fractal_results['fractal_dimension_std'] = float(np.std(valid_dimensions))
            else:
                fractal_results['mean_fractal_dimension'] = 0.0
                fractal_results['fractal_dimension_std'] = 0.0
            
            return fractal_results
            
        except Exception as e:
            self.logger.error(f"Multi-method fractal dimension computation failed: {e}")
            return {'fractal_dimension_error': str(e)}
    
    def _box_counting_dimension(self, phase_space: np.ndarray) -> float:
        """Compute box-counting fractal dimension"""
        try:
            if phase_space.size == 0:
                return 0.0
            
            # Normalize data to unit hypercube
            mins = np.min(phase_space, axis=0)
            maxs = np.max(phase_space, axis=0)
            ranges = maxs - mins
            ranges[ranges == 0] = 1  # Avoid division by zero
            
            normalized = (phase_space - mins) / ranges
            
            # Range of box sizes
            n_boxes_list = [2**i for i in range(2, 8)]  # 4, 8, 16, 32, 64, 128 boxes per dimension
            box_counts = []
            
            for n_boxes in n_boxes_list:
                # Discretize points into boxes
                box_indices = np.floor(normalized * n_boxes).astype(int)
                # Handle edge case where point equals maximum
                box_indices = np.minimum(box_indices, n_boxes - 1)
                
                # Count unique boxes
                unique_boxes = set()
                for point in box_indices:
                    unique_boxes.add(tuple(point))
                
                box_counts.append(len(unique_boxes))
            
            if len(box_counts) < 2:
                return 0.0
            
            # Fit log-log relationship: log(N) = -D * log(r) + constant
            log_r = np.log([1.0/n for n in n_boxes_list])
            log_N = np.log(box_counts)
            
            # Linear regression
            coeffs = np.polyfit(log_r, log_N, 1)
            dimension = -coeffs[0]  # Slope is -D
            
            return float(max(0.0, dimension))
            
        except Exception as e:
            self.logger.error(f"Box counting dimension computation failed: {e}")
            return 0.0
    
    def _information_dimension(self, phase_space: np.ndarray) -> float:
        """Compute information dimension"""
        try:
            if phase_space.size == 0:
                return 0.0
            
            # Similar to box counting but weighted by probability
            mins = np.min(phase_space, axis=0)
            maxs = np.max(phase_space, axis=0)
            ranges = maxs - mins
            ranges[ranges == 0] = 1
            
            normalized = (phase_space - mins) / ranges
            
            n_boxes_list = [2**i for i in range(2, 7)]
            info_dimensions = []
            
            for n_boxes in n_boxes_list:
                box_indices = np.floor(normalized * n_boxes).astype(int)
                box_indices = np.minimum(box_indices, n_boxes - 1)
                
                # Count points in each box
                from collections import Counter
                box_counter = Counter()
                for point in box_indices:
                    box_counter[tuple(point)] += 1
                
                # Compute information entropy
                total_points = len(phase_space)
                entropy = 0.0
                for count in box_counter.values():
                    p = count / total_points
                    if p > 0:
                        entropy -= p * np.log(p)
                
                # Information dimension approximation
                box_size = 1.0 / n_boxes
                if box_size > 0:
                    info_dim = entropy / (-np.log(box_size))
                    info_dimensions.append(info_dim)
            
            return float(np.mean(info_dimensions)) if info_dimensions else 0.0
            
        except Exception as e:
            self.logger.error(f"Information dimension computation failed: {e}")
            return 0.0
    
    def _kaplan_yorke_dimension(self, phase_space: np.ndarray) -> float:
        """Estimate Kaplan-Yorke dimension using Lyapunov exponents"""
        try:
            # This is an approximation - would need actual Lyapunov spectrum
            # For now, estimate based on phase space properties
            
            if phase_space.size == 0:
                return 0.0
            
            # Use PCA eigenvalues as proxy for Lyapunov exponents
            from sklearn.decomposition import PCA
            pca = PCA()
            pca.fit(phase_space)
            
            eigenvalues = pca.explained_variance_
            # Convert to log scale (proxy for Lyapunov exponents)
            pseudo_lyapunov = np.log(eigenvalues + 1e-10)
            
            # Kaplan-Yorke dimension formula: D_KY = j + sum(λ_i)/|λ_{j+1}|
            # where j is largest integer such that sum of first j exponents is positive
            
            cumulative_sum = np.cumsum(pseudo_lyapunov)
            j = 0
            
            for i, cum_sum in enumerate(cumulative_sum):
                if cum_sum > 0:
                    j = i + 1
                else:
                    break
            
            if j < len(pseudo_lyapunov) - 1 and pseudo_lyapunov[j] != 0:
                ky_dim = j + cumulative_sum[j-1] / abs(pseudo_lyapunov[j])
            else:
                ky_dim = j
            
            return float(max(0.0, min(ky_dim, len(phase_space[0]) if len(phase_space) > 0 else 0)))
            
        except Exception as e:
            self.logger.error(f"Kaplan-Yorke dimension computation failed: {e}")
            return 0.0
    
    def _recurrence_quantification_analysis(self, phase_space: np.ndarray) -> Dict:
        """Perform recurrence quantification analysis (RQA)"""
        try:
            if phase_space.size == 0 or len(phase_space) < 20:
                return {'rqa_error': 'insufficient_data'}
            
            # Compute recurrence matrix
            epsilon = 0.1 * np.std(phase_space)  # Threshold parameter
            n_points = len(phase_space)
            
            # For computational efficiency, limit to subset if too large
            if n_points > 1000:
                indices = np.linspace(0, n_points-1, 1000, dtype=int)
                phase_subset = phase_space[indices]
            else:
                phase_subset = phase_space
            
            n = len(phase_subset)
            
            # Compute distance matrix
            distance_matrix = np.zeros((n, n))
            for i in range(n):
                for j in range(i, n):
                    dist = np.linalg.norm(phase_subset[i] - phase_subset[j])
                    distance_matrix[i, j] = dist
                    distance_matrix[j, i] = dist
            
            # Recurrence matrix
            recurrence_matrix = (distance_matrix < epsilon).astype(int)
            
            # RQA measures
            rqa_results = {}
            
            # Recurrence rate
            rqa_results['recurrence_rate'] = float(np.sum(recurrence_matrix) / (n * n))
            
            # Determinism (ratio of recurrent points forming diagonal lines)
            diagonal_lines = self._find_diagonal_lines(recurrence_matrix, min_length=2)
            total_diagonal_points = sum(len(line) for line in diagonal_lines)
            total_recurrent_points = np.sum(recurrence_matrix)
            
            rqa_results['determinism'] = float(total_diagonal_points / max(total_recurrent_points, 1))
            
            # Average diagonal line length
            if diagonal_lines:
                rqa_results['mean_diagonal_length'] = float(np.mean([len(line) for line in diagonal_lines]))
                rqa_results['max_diagonal_length'] = float(max(len(line) for line in diagonal_lines))
            else:
                rqa_results['mean_diagonal_length'] = 0.0
                rqa_results['max_diagonal_length'] = 0.0
            
            # Laminarity (ratio of recurrent points forming vertical lines)
            vertical_lines = self._find_vertical_lines(recurrence_matrix, min_length=2)
            total_vertical_points = sum(len(line) for line in vertical_lines)
            
            rqa_results['laminarity'] = float(total_vertical_points / max(total_recurrent_points, 1))
            
            # Entropy of diagonal line lengths
            if diagonal_lines:
                line_lengths = [len(line) for line in diagonal_lines]
                from collections import Counter
                length_counts = Counter(line_lengths)
                total_lines = len(diagonal_lines)
                
                entropy = 0.0
                for count in length_counts.values():
                    p = count / total_lines
                    if p > 0:
                        entropy -= p * np.log(p)
                
                rqa_results['diagonal_entropy'] = float(entropy)
            else:
                rqa_results['diagonal_entropy'] = 0.0
            
            return rqa_results
            
        except Exception as e:
            self.logger.error(f"Recurrence quantification analysis failed: {e}")
            return {'rqa_error': str(e)}
    
    def _find_diagonal_lines(self, recurrence_matrix: np.ndarray, min_length: int = 2) -> List:
        """Find diagonal lines in recurrence matrix"""
        try:
            lines = []
            n = len(recurrence_matrix)
            
            # Check all possible diagonal starting points
            for start_i in range(n):
                for start_j in range(n):
                    if recurrence_matrix[start_i, start_j] == 1:
                        # Follow diagonal line
                        line = []
                        i, j = start_i, start_j
                        
                        while i < n and j < n and recurrence_matrix[i, j] == 1:
                            line.append((i, j))
                            i += 1
                            j += 1
                        
                        if len(line) >= min_length:
                            lines.append(line)
            
            return lines
            
        except Exception:
            return []
    
    def _find_vertical_lines(self, recurrence_matrix: np.ndarray, min_length: int = 2) -> List:
        """Find vertical lines in recurrence matrix"""
        try:
            lines = []
            n = len(recurrence_matrix)
            
            # Check all possible vertical starting points
            for j in range(n):
                for start_i in range(n):
                    if recurrence_matrix[start_i, j] == 1:
                        # Follow vertical line
                        line = []
                        i = start_i
                        
                        while i < n and recurrence_matrix[i, j] == 1:
                            line.append((i, j))
                            i += 1
                        
                        if len(line) >= min_length:
                            lines.append(line)
            
            return lines
            
        except Exception:
            return []
    
    def _compute_entropy_measures(self, signal: np.ndarray, phase_space: np.ndarray) -> Dict:
        """Compute various entropy measures for complexity characterization"""
        try:
            entropy_results = {}
            
            # Sample entropy
            try:
                sample_ent = self._sample_entropy(signal, m=2, r=0.2)
                entropy_results['sample_entropy'] = sample_ent
            except Exception:
                entropy_results['sample_entropy'] = 0.0
            
            # Approximate entropy
            try:
                approx_ent = self._approximate_entropy(signal, m=2, r=0.2)
                entropy_results['approximate_entropy'] = approx_ent
            except Exception:
                entropy_results['approximate_entropy'] = 0.0
            
            # Permutation entropy
            try:
                perm_ent = self._permutation_entropy(signal, order=3)
                entropy_results['permutation_entropy'] = perm_ent
            except Exception:
                entropy_results['permutation_entropy'] = 0.0
            
            # Spectral entropy
            try:
                spec_ent = self._spectral_entropy(signal)
                entropy_results['spectral_entropy'] = spec_ent
            except Exception:
                entropy_results['spectral_entropy'] = 0.0
            
            return entropy_results
            
        except Exception as e:
            self.logger.error(f"Entropy measures computation failed: {e}")
            return {'entropy_error': str(e)}
    
    def _sample_entropy(self, signal: np.ndarray, m: int = 2, r: float = 0.2) -> float:
        """Compute sample entropy"""
        try:
            N = len(signal)
            if N < m + 1:
                return 0.0
            
            std_signal = np.std(signal)
            tolerance = r * std_signal
            
            def _maxdist(xi, xj, m):
                return max([abs(ua - va) for ua, va in zip(xi, xj)])
            
            def _phi(m):
                patterns = np.array([signal[i:i + m] for i in range(N - m + 1)])
                matches = 0
                for i in range(len(patterns)):
                    for j in range(len(patterns)):
                        if i != j and _maxdist(patterns[i], patterns[j], m) <= tolerance:
                            matches += 1
                return matches / (N - m + 1)
            
            phi_m = _phi(m)
            phi_m1 = _phi(m + 1)
            
            if phi_m == 0 or phi_m1 == 0:
                return 0.0
            
            return float(-np.log(phi_m1 / phi_m))
            
        except Exception:
            return 0.0
    
    def _approximate_entropy(self, signal: np.ndarray, m: int = 2, r: float = 0.2) -> float:
        """Compute approximate entropy"""
        try:
            N = len(signal)
            if N < m + 1:
                return 0.0
            
            std_signal = np.std(signal)
            tolerance = r * std_signal
            
            def _maxdist(xi, xj):
                return max([abs(ua - va) for ua, va in zip(xi, xj)])
            
            def _phi(m):
                patterns = [signal[i:i + m] for i in range(N - m + 1)]
                phi_values = []
                
                for i in range(len(patterns)):
                    matches = 0
                    for j in range(len(patterns)):
                        if _maxdist(patterns[i], patterns[j]) <= tolerance:
                            matches += 1
                    if matches > 0:
                        phi_values.append(np.log(matches / len(patterns)))
                
                return np.mean(phi_values) if phi_values else 0
            
            return float(_phi(m) - _phi(m + 1))
            
        except Exception:
            return 0.0
    
    def _permutation_entropy(self, signal: np.ndarray, order: int = 3) -> float:
        """Compute permutation entropy"""
        try:
            N = len(signal)
            if N < order:
                return 0.0
            
            # Generate all possible ordinal patterns
            from itertools import permutations
            ordinal_patterns = list(permutations(range(order)))
            pattern_counts = {pattern: 0 for pattern in ordinal_patterns}
            
            # Count occurrences of each pattern
            for i in range(N - order + 1):
                subsequence = signal[i:i + order]
                sorted_indices = tuple(np.argsort(subsequence))
                if sorted_indices in pattern_counts:
                    pattern_counts[sorted_indices] += 1
            
            # Compute entropy
            total_patterns = sum(pattern_counts.values())
            if total_patterns == 0:
                return 0.0
            
            entropy = 0.0
            for count in pattern_counts.values():
                if count > 0:
                    p = count / total_patterns
                    entropy -= p * np.log(p)
            
            # Normalize by maximum possible entropy
            max_entropy = np.log(len(ordinal_patterns))
            return float(entropy / max_entropy) if max_entropy > 0 else 0.0
            
        except Exception:
            return 0.0
    
    def _spectral_entropy(self, signal: np.ndarray) -> float:
        """Compute spectral entropy"""
        try:
            from scipy import signal as scipy_signal
            
            # Compute power spectral density
            frequencies, psd = scipy_signal.welch(signal, nperseg=min(256, len(signal)//4))
            
            # Normalize PSD
            psd_norm = psd / np.sum(psd)
            
            # Compute entropy
            entropy = 0.0
            for p in psd_norm:
                if p > 0:
                    entropy -= p * np.log(p)
            
            # Normalize by maximum possible entropy
            max_entropy = np.log(len(psd))
            return float(entropy / max_entropy) if max_entropy > 0 else 0.0
            
        except Exception:
            return 0.0
    
    async def _classify_geological_phase_patterns(self, phase_space: np.ndarray, phase_results: Dict) -> Dict:
        """Classify geological phase space patterns using database reference patterns"""
        try:
            # Initialize database connection
            from .database_integration import DatabaseIntegration, DatabaseConfig
            import os
            
            db_config = DatabaseConfig(
                host=os.environ.get('DB_HOST', 'localhost'),
                port=int(os.environ.get('DB_PORT', '5432')),
                database=os.environ.get('DB_NAME', 'prometheus_geo'),
                user=os.environ.get('DB_USER', 'postgres'),
                password=os.environ.get('DB_PASSWORD', ''),
                enable_timescaledb=True,
                enable_postgis=True
            )
            
            db_integration = DatabaseIntegration(db_config)
            
            # Query geological phase space reference patterns
            query = """
            SELECT 
                pattern_type, geological_process, 
                embedding_dimension, correlation_dimension,
                largest_lyapunov_exponent, fractal_dimension,
                pattern_confidence, reference_location
            FROM geological_phase_space_patterns
            WHERE embedding_dimension BETWEEN %s AND %s
            AND correlation_dimension BETWEEN %s AND %s
            AND pattern_confidence > 0.7
            ORDER BY pattern_confidence DESC
            LIMIT 20
            """
            
            # Query parameters based on current analysis
            emb_dim = phase_results.get('embedding_dimension', 3)
            corr_dim = phase_results.get('correlation_dimension', 2.0)
            
            reference_patterns = await db_integration.execute_query(
                query, 
                (emb_dim - 1, emb_dim + 1, corr_dim - 0.5, corr_dim + 0.5)
            )
            
            classification_results = {}
            
            if reference_patterns:
                # Compute similarity scores with reference patterns
                pattern_similarities = []
                
                for pattern in reference_patterns:
                    # Multi-dimensional similarity metric
                    similarity_score = 0.0
                    weight_sum = 0.0
                    
                    # Embedding dimension similarity
                    if 'embedding_dimension' in phase_results:
                        emb_sim = 1.0 - abs(phase_results['embedding_dimension'] - pattern['embedding_dimension']) / 10.0
                        similarity_score += emb_sim * 0.2
                        weight_sum += 0.2
                    
                    # Correlation dimension similarity
                    if 'correlation_dimension' in phase_results:
                        corr_sim = 1.0 - abs(phase_results['correlation_dimension'] - pattern['correlation_dimension']) / 3.0
                        similarity_score += corr_sim * 0.3
                        weight_sum += 0.3
                    
                    # Lyapunov exponent similarity
                    if 'largest_lyapunov_exponent' in phase_results:
                        lyap_sim = 1.0 - abs(phase_results['largest_lyapunov_exponent'] - pattern['largest_lyapunov_exponent']) / 2.0
                        similarity_score += lyap_sim * 0.3
                        weight_sum += 0.3
                    
                    # Fractal dimension similarity
                    if 'mean_fractal_dimension' in phase_results:
                        frac_sim = 1.0 - abs(phase_results['mean_fractal_dimension'] - pattern['fractal_dimension']) / 3.0
                        similarity_score += frac_sim * 0.2
                        weight_sum += 0.2
                    
                    if weight_sum > 0:
                        final_similarity = (similarity_score / weight_sum) * pattern['pattern_confidence']
                        pattern_similarities.append({
                            'pattern_type': pattern['pattern_type'],
                            'geological_process': pattern['geological_process'],
                            'similarity_score': final_similarity,
                            'reference_confidence': pattern['pattern_confidence']
                        })
                
                # Sort by similarity score
                pattern_similarities.sort(key=lambda x: x['similarity_score'], reverse=True)
                
                if pattern_similarities:
                    best_match = pattern_similarities[0]
                    classification_results['geological_pattern_type'] = best_match['pattern_type']
                    classification_results['geological_process'] = best_match['geological_process']
                    classification_results['pattern_similarity_score'] = best_match['similarity_score']
                    classification_results['classification_confidence'] = best_match['reference_confidence']
                    classification_results['alternative_patterns'] = pattern_similarities[1:3]  # Top 3 alternatives
            
            # Default classification if no matches
            if not classification_results:
                classification_results = {
                    'geological_pattern_type': 'unknown',
                    'geological_process': 'unclassified',
                    'pattern_similarity_score': 0.0,
                    'classification_confidence': 0.0
                }
            
            return classification_results
            
        except Exception as e:
            self.logger.error(f"Geological phase space pattern classification failed: {e}")
            return {
                'geological_classification_error': str(e),
                'geological_pattern_type': 'error',
                'geological_process': 'analysis_failed'
            }
    
    async def _ml_phase_space_classification(self, phase_results: Dict, features: Dict) -> Dict:
        """Machine learning-based phase space classification"""
        try:
            from .model_manager import ModelManager, ModelConfig
            import os
            
            # Initialize model manager
            model_config = ModelConfig(
                model_registry_path=os.environ.get('MODEL_REGISTRY_PATH', './models'),
                database_url=os.environ.get('MODEL_DB_URL', 'sqlite:///models.db'),
                cache_enabled=True
            )
            
            model_manager = ModelManager(model_config)
            
            # Load pre-trained phase space classification model
            phase_classifier = await model_manager.load_model(
                'geological_phase_space_classifier_v3.2',
                model_type='phase_space_analysis'
            )
            
            ml_results = {}
            
            if phase_classifier:
                # Prepare feature vector for ML model
                feature_vector = []
                
                # Phase space geometric features
                feature_vector.extend([
                    phase_results.get('embedding_dimension', 0),
                    phase_results.get('correlation_dimension', 0),
                    phase_results.get('largest_lyapunov_exponent', 0),
                    phase_results.get('mean_fractal_dimension', 0),
                    phase_results.get('attractor_volume', 0),
                    phase_results.get('total_trajectory_length', 0),
                    phase_results.get('chaos_indicator', 0),
                    phase_results.get('recurrence_rate', 0),
                    phase_results.get('determinism', 0),
                    phase_results.get('laminarity', 0)
                ])
                
                # Entropy measures
                feature_vector.extend([
                    phase_results.get('sample_entropy', 0),
                    phase_results.get('approximate_entropy', 0),
                    phase_results.get('permutation_entropy', 0),
                    phase_results.get('spectral_entropy', 0)
                ])
                
                # Additional geological context features
                feature_vector.extend([
                    features.get('welch_total_power', 0),
                    features.get('welch_centroid', 0),
                    features.get('welch_spread', 0),
                    features.get('zero_crossing_rate', 0),
                    features.get('rms_energy', 0)
                ])
                
                # Convert to numpy array and reshape for prediction
                feature_array = np.array(feature_vector).reshape(1, -1)
                
                # Handle NaN/infinite values
                feature_array = np.nan_to_num(feature_array, nan=0.0, posinf=1e6, neginf=-1e6)
                
                try:
                    # Get prediction probabilities
                    prediction_probs = phase_classifier.predict_proba(feature_array)[0]
                    prediction_class = phase_classifier.predict(feature_array)[0]
                    
                    # Assuming classes: ['volcanic', 'tectonic', 'anthropogenic', 'noise', 'complex_system']
                    class_names = ['volcanic', 'tectonic', 'anthropogenic', 'noise', 'complex_system']
                    
                    ml_results['ml_predicted_class'] = prediction_class
                    ml_results['ml_prediction_confidence'] = float(np.max(prediction_probs))
                    
                    # Detailed class probabilities
                    for i, class_name in enumerate(class_names):
                        if i < len(prediction_probs):
                            ml_results[f'ml_prob_{class_name}'] = float(prediction_probs[i])
                    
                    # Classification uncertainty
                    entropy_pred = -np.sum(prediction_probs * np.log(prediction_probs + 1e-10))
                    ml_results['ml_prediction_uncertainty'] = float(entropy_pred)
                    
                except Exception as e:
                    self.logger.warning(f"ML phase space prediction failed: {e}")
                    ml_results['ml_prediction_error'] = str(e)
            
            return ml_results
            
        except Exception as e:
            self.logger.error(f"ML phase space classification failed: {e}")
            return {'ml_classification_error': str(e)}
    
