    # Distance calculation methods
    def _euclidean_distance(self, coords1: np.ndarray, coords2: np.ndarray) -> float:
        """Calculate Euclidean distance between coordinate sets."""
        # Use centroids for overall distance
        centroid1 = np.mean(coords1, axis=0)
        centroid2 = np.mean(coords2, axis=0)
        return np.linalg.norm(centroid1 - centroid2)
    
    def _manhattan_distance(self, coords1: np.ndarray, coords2: np.ndarray) -> float:
        """Calculate Manhattan distance between coordinate sets."""
        centroid1 = np.mean(coords1, axis=0)
        centroid2 = np.mean(coords2, axis=0)
        return np.sum(np.abs(centroid1 - centroid2))
    
    def _hausdorff_distance(self, coords1: np.ndarray, coords2: np.ndarray) -> float:
        """Calculate Hausdorff distance between coordinate sets."""
        try:
            # Simplified Hausdorff distance calculation
            max_dist1 = np.max([np.min([np.linalg.norm(p1 - p2) for p2 in coords2]) for p1 in coords1])
            max_dist2 = np.max([np.min([np.linalg.norm(p2 - p1) for p1 in coords1]) for p2 in coords2])
            return max(max_dist1, max_dist2)
        except Exception:
            return float('inf')
    
    def _wasserstein_distance(self, coords1: np.ndarray, coords2: np.ndarray) -> float:
        """Calculate Wasserstein distance between coordinate distributions."""
        try:
            # Simplified 1D Wasserstein distance on first coordinate
            return np.mean(np.abs(np.sort(coords1[:, 0]) - np.sort(coords2[:, 0])))
        except Exception:
            return float('inf')
    
    def _geodesic_distance(self, coords1: np.ndarray, coords2: np.ndarray) -> float:
        """Calculate geodesic distance (simplified as Euclidean for now)."""
        return self._euclidean_distance(coords1, coords2)
    
    def _mahalanobis_distance(self, coords1: np.ndarray, coords2: np.ndarray) -> float:
        """Calculate Mahalanobis distance between coordinate sets."""
        try:
            combined_coords = np.vstack([coords1, coords2])
            cov_matrix = np.cov(combined_coords.T)
            cov_inv = np.linalg.pinv(cov_matrix)
            
            centroid1 = np.mean(coords1, axis=0)
            centroid2 = np.mean(coords2, axis=0)
            diff = centroid1 - centroid2
            
            return np.sqrt(np.dot(np.dot(diff, cov_inv), diff))
        except Exception:
            return float('inf')
    
    # Helper methods for spatial analysis
    def _calculate_geometric_moments(self, coords: np.ndarray) -> Dict[str, float]:
        """Calculate geometric moments for shape analysis."""
        try:
            centroid = np.mean(coords, axis=0)
            centered_coords = coords - centroid
            
            # Second-order moments
            m20 = np.mean(centered_coords[:, 0]**2)
            m02 = np.mean(centered_coords[:, 1]**2) if coords.shape[1] > 1 else 0
            m11 = np.mean(centered_coords[:, 0] * centered_coords[:, 1]) if coords.shape[1] > 1 else 0
            
            return {
                'centroid': centroid.tolist(),
                'm20': m20,
                'm02': m02,
                'm11': m11,
                'aspect_ratio': m20 / (m02 + 1e-8) if coords.shape[1] > 1 else 1.0
            }
        except Exception:
            return {'centroid': [0, 0], 'm20': 0, 'm02': 0, 'm11': 0, 'aspect_ratio': 1.0}
    
    def _compare_moments(self, moments1: Dict, moments2: Dict) -> float:
        """Compare geometric moments between two datasets."""
        try:
            # Compare aspect ratios and moment values
            aspect_sim = 1.0 - abs(moments1['aspect_ratio'] - moments2['aspect_ratio']) / \
                        (moments1['aspect_ratio'] + moments2['aspect_ratio'] + 1e-8)
            
            m20_sim = 1.0 - abs(moments1['m20'] - moments2['m20']) / \
                     (moments1['m20'] + moments2['m20'] + 1e-8)
            
            m02_sim = 1.0 - abs(moments1['m02'] - moments2['m02']) / \
                     (moments1['m02'] + moments2['m02'] + 1e-8)
            
            return np.mean([aspect_sim, m20_sim, m02_sim])
        except Exception:
            return 0.0
    
    def _compare_convex_hulls(self, coords1: np.ndarray, coords2: np.ndarray) -> float:
        """Compare convex hull properties."""
        try:
            from scipy.spatial import ConvexHull
            
            if coords1.shape[1] >= 2 and coords2.shape[1] >= 2:
                hull1 = ConvexHull(coords1[:, :2])
                hull2 = ConvexHull(coords2[:, :2])
                
                # Compare hull areas
                area_similarity = 1.0 - abs(hull1.volume - hull2.volume) / \
                                (hull1.volume + hull2.volume + 1e-8)
                
                return max(0.0, area_similarity)
            else:
                return 0.5  # Default for 1D data
        except Exception:
            return 0.0
    
