    def _generate_spatial_cache_key(self, data1: Dict, data2: Dict) -> str:
        """Generate cache key for spatial similarity computation."""
        try:
            # Create hash from coordinate data
            coords1_hash = hash(data1['coordinates'].tobytes())
            coords2_hash = hash(data2['coordinates'].tobytes())
            return f"spatial_{coords1_hash}_{coords2_hash}"
        except Exception:
            return f"spatial_{time.time()}_{np.random.randint(10000)}"
    
    def _cache_spatial_results(self, cache_key: str, results: Dict) -> None:
        """Cache spatial similarity results."""
        if len(self._similarity_cache) >= self._cache_size_limit:
            # Remove oldest entries
            oldest_keys = list(self._similarity_cache.keys())[:len(self._similarity_cache)//2]
            for key in oldest_keys:
                del self._similarity_cache[key]
        
        self._similarity_cache[cache_key] = results
    
    def _assess_spatial_similarity_quality(self, results: Dict) -> Dict[str, Any]:
        """Assess the quality of spatial similarity analysis."""
        try:
            # Quality metrics
            completeness = len([r for r in results.values() if isinstance(r, dict) and 'error' not in r]) / len(results)
            
            # Consistency check across different spatial methods
            similarities = []
            for result in results.values():
                if isinstance(result, dict) and 'overall_similarity' in result:
                    similarities.append(result['overall_similarity'])
            
            consistency = 1.0 - np.std(similarities) if len(similarities) > 1 else 1.0
            
            # Overall quality score
            quality_score = (completeness + consistency) / 2
            
            return {
                'quality_score': quality_score,
                'completeness': completeness,
                'consistency': consistency,
                'successful_analyses': len(similarities),
                'total_analyses': len(results)
            }
        except Exception as e:
            return {
                'quality_score': 0.0,
                'error': str(e)
            }
    
    def _calculate_spatial_confidence(self, results: Dict, data1: Dict, data2: Dict) -> float:
        """Calculate confidence score for spatial similarity analysis."""
        try:
            # Base confidence factors
            data_quality = min(len(data1.get('coordinates', [])), len(data2.get('coordinates', []))) / 1000
            data_quality = min(1.0, data_quality)  # Cap at 1.0
            
            # Dimensional consistency
            dim_consistency = 1.0 if data1.get('dimensions') == data2.get('dimensions') else 0.7
            
            # Analysis completeness
            successful_analyses = len([r for r in results.values() 
                                     if isinstance(r, dict) and 'error' not in r])
            analysis_completeness = successful_analyses / max(1, len(results))
            
            # Overall confidence
            confidence = np.mean([data_quality, dim_consistency, analysis_completeness])
            
            return confidence
        except Exception:
            return 0.5  # Default confidence
    
    def _interpret_spatial_similarity_geologically(self, results: Dict) -> Dict[str, Any]:
        """Provide geological interpretation of spatial similarity results."""
        try:
            overall_sim = results.get('geometric_similarity', {}).get('overall_similarity', 0)
            
            # Geological interpretation based on similarity scores
            if overall_sim > 0.9:
                interpretation = "Highly similar spatial patterns suggesting common geological processes"
                geological_significance = "high"
            elif overall_sim > 0.7:
                interpretation = "Moderately similar spatial patterns with some common characteristics"
                geological_significance = "moderate"
            elif overall_sim > 0.5:
                interpretation = "Some spatial similarities but likely different geological contexts"
                geological_significance = "low"
            else:
                interpretation = "Distinct spatial patterns suggesting different geological processes"
                geological_significance = "minimal"
            
            return {
                'interpretation': interpretation,
                'geological_significance': geological_significance,
                'confidence': 'medium',
                'recommendations': self._generate_spatial_recommendations(results)
            }
        except Exception as e:
            return {
                'interpretation': 'Unable to provide geological interpretation',
                'error': str(e)
            }
    
    def _generate_spatial_recommendations(self, results: Dict) -> List[str]:
        """Generate recommendations based on spatial analysis."""
        recommendations = []
        
        try:
            # Check geometric similarity
            geom_sim = results.get('geometric_similarity', {}).get('overall_similarity', 0)
            if geom_sim < 0.5:
                recommendations.append("Consider analyzing different spatial scales or resolutions")
            
            # Check distribution similarity
            dist_sim = results.get('distribution_similarity', {}).get('overall_similarity', 0)
            if dist_sim < 0.5:
                recommendations.append("Examine spatial clustering patterns and point distributions")
            
            # Check shape similarity
            shape_sim = results.get('shape_similarity', {}).get('overall_similarity', 0)
            if shape_sim < 0.5:
                recommendations.append("Investigate morphological differences and shape characteristics")
            
            if not recommendations:
                recommendations.append("Spatial patterns show good correspondence across multiple dimensions")
                
        except Exception:
            recommendations.append("Review spatial data quality and analysis parameters")
        
        return recommendations
    
    def _categorize_spatial_similarity(self, similarity: float) -> str:
        """Categorize spatial similarity level."""
        if similarity >= 0.9:
            return "very_high"
        elif similarity >= 0.7:
            return "high"
        elif similarity >= 0.5:
            return "moderate"
        elif similarity >= 0.3:
            return "low"
        else:
            return "very_low"
    
