    def _update_quality_statistics(self, quality_record: Dict[str, Any]):
        """Update quality statistics."""
        try:
            current_quality = quality_record['overall_quality']
            
            if len(self.quality_history) > 0:
                self.quality_statistics.update({
                    'mean_quality': np.mean(self.quality_history),
                    'std_quality': np.std(self.quality_history),
                    'min_quality': np.min(self.quality_history),
                    'max_quality': np.max(self.quality_history),
                    'quality_range': np.max(self.quality_history) - np.min(self.quality_history),
                    'quality_trend': self._calculate_quality_trend(),
                    'quality_stability': 1.0 - np.std(self.quality_history)
                })
            
        except Exception as e:
            logging.error(f"Error updating quality statistics: {str(e)}")
    
    def _calculate_quality_trend(self) -> float:
        """Calculate quality trend direction and magnitude."""
        try:
            if len(self.quality_history) < 10:
                return 0.0
            
            recent_quality = list(self.quality_history)[-10:]
            earlier_quality = list(self.quality_history)[-20:-10] if len(self.quality_history) >= 20 else []
            
            if not earlier_quality:
                return 0.0
            
            recent_mean = np.mean(recent_quality)
            earlier_mean = np.mean(earlier_quality)
            
            trend = (recent_mean - earlier_mean) / max(0.01, earlier_mean)
            return np.clip(trend, -1.0, 1.0)
            
        except Exception as e:
            logging.error(f"Error calculating quality trend: {str(e)}")
            return 0.0
    
    def _analyze_quality_trends(self, quality_record: Dict[str, Any]):
        """Analyze quality trends."""
        try:
            current_trend = self._calculate_quality_trend()
            self.trend_history.append(current_trend)
            
            # Detect trend patterns
            if len(self.trend_history) >= 5:
                recent_trends = list(self.trend_history)[-5:]
                
                # Detect declining trend
                if all(t < -0.02 for t in recent_trends):
                    self._trigger_trend_alert('declining', recent_trends)
                
                # Detect volatile trend
                trend_volatility = np.std(recent_trends)
                if trend_volatility > 0.1:
                    self._trigger_trend_alert('volatile', recent_trends)
            
        except Exception as e:
            logging.error(f"Error analyzing quality trends: {str(e)}")
    
    def _detect_quality_anomalies(self, quality_record: Dict[str, Any]):
        """Detect quality anomalies."""
        try:
            current_quality = quality_record['overall_quality']
            
            if len(self.quality_history) >= 10:
                mean_quality = np.mean(self.quality_history)
                std_quality = np.std(self.quality_history)
                
                # Z-score anomaly detection
                z_score = abs(current_quality - mean_quality) / max(0.01, std_quality)
                
                if z_score > 2.5:
                    anomaly_info = {
                        'type': 'statistical_anomaly',
                        'z_score': z_score,
                        'current_quality': current_quality,
                        'expected_range': (mean_quality - 2*std_quality, mean_quality + 2*std_quality)
                    }
                    self._handle_quality_anomaly(anomaly_info)
            
        except Exception as e:
            logging.error(f"Error detecting quality anomalies: {str(e)}")
    
