    def _detect_quality_degradation(self, current_quality: float) -> bool:
        """Detect quality degradation."""
        try:
            if len(self.quality_history) < 5:
                return False
            
            recent_average = np.mean(list(self.quality_history)[-5:])
            baseline_quality = self.quality_baseline['mean_quality']
            
            # Check for significant degradation
            degradation = baseline_quality - recent_average
            
            if degradation > self.degradation_threshold:
                self.monitoring_stats['degradations_detected'] += 1
                return True
            
            return False
            
        except Exception as e:
            logging.error(f"Error detecting quality degradation: {str(e)}")
            return False
    
