    def _update_adaptive_thresholds(self, quality_assessment: Dict[str, Any]):
        """Update adaptive quality thresholds."""
        try:
            dimension_scores = quality_assessment['dimension_scores']
            
            for dimension, score in dimension_scores.items():
                if dimension in self.adaptive_thresholds:
                    threshold_info = self.adaptive_thresholds[dimension]
                    
                    # Adaptive threshold adjustment
                    if score > threshold_info['current'] * 1.1:
                        # Increase threshold gradually
                        new_threshold = min(
                            threshold_info['max'],
                            threshold_info['current'] + threshold_info['adaptation_rate']
                        )
                        threshold_info['current'] = new_threshold
                    elif score < threshold_info['current'] * 0.8:
                        # Decrease threshold gradually
                        new_threshold = max(
                            threshold_info['min'],
                            threshold_info['current'] - threshold_info['adaptation_rate']
                        )
                        threshold_info['current'] = new_threshold
                    
                    threshold_info['update_count'] += 1
            
        except Exception as e:
            logging.error(f"Error updating adaptive thresholds: {str(e)}")
    
