    def _generate_quality_forecast(self, recent_qualities: List[float]) -> Optional[Dict[str, Any]]:
        """Generate quality forecast."""
        try:
            if len(recent_qualities) < 10:
                return None
            
            # Simple trend-based forecast
            trend = self._calculate_quality_trend()
            current_quality = recent_qualities[-1]
            
            forecast_points = []
            for i in range(1, self.forecast_horizon + 1):
                forecasted_quality = current_quality + (trend * i * 0.1)
                forecasted_quality = max(0.0, min(1.0, forecasted_quality))
                forecast_points.append(forecasted_quality)
            
            return {
                'forecast_points': forecast_points,
                'trend': trend,
                'confidence': 0.7,  # Simplified confidence
                'horizon': self.forecast_horizon
            }
            
        except Exception as e:
            logging.error(f"Error generating quality forecast: {str(e)}")
            return None
    
