    def _compute_advanced_quality_analytics(self, experiences: List[Dict[str, Any]]) -> Dict[str, Any]:
        """Compute advanced quality analytics."""
        try:
            quality_scores = [exp.get('quality_score', 0.5) for exp in experiences]
            
            return {
                'quality_percentiles': {
                    'p10': np.percentile(quality_scores, 10),
                    'p25': np.percentile(quality_scores, 25),
                    'p75': np.percentile(quality_scores, 75),
                    'p90': np.percentile(quality_scores, 90),
                    'p95': np.percentile(quality_scores, 95),
                    'p99': np.percentile(quality_scores, 99)
                },
                'quality_stability': 1.0 - np.std(quality_scores),
                'quality_consistency': self._calculate_quality_consistency(quality_scores),
                'outlier_count': self._count_quality_outliers(quality_scores),
                'quality_volatility': self._calculate_quality_volatility(quality_scores)
            }
            
        except Exception as e:
            logging.error(f"Error computing advanced quality analytics: {str(e)}")
            return {}
    
    def _calculate_quality_consistency(self, quality_scores: List[float]) -> float:
        """Calculate quality consistency metric."""
        try:
            if len(quality_scores) < 2:
                return 1.0
            
            # Calculate consistency as inverse of coefficient of variation
            mean_quality = np.mean(quality_scores)
            std_quality = np.std(quality_scores)
            
            if mean_quality == 0:
                return 0.0
            
            cv = std_quality / mean_quality
            consistency = 1.0 / (1.0 + cv)
            
            return consistency
            
        except Exception as e:
            logging.error(f"Error calculating quality consistency: {str(e)}")
            return 0.5
    
    def _count_quality_outliers(self, quality_scores: List[float]) -> int:
        """Count quality outliers using IQR method."""
        try:
            if len(quality_scores) < 4:
                return 0
            
            q25 = np.percentile(quality_scores, 25)
            q75 = np.percentile(quality_scores, 75)
            iqr = q75 - q25
            
            lower_bound = q25 - 1.5 * iqr
            upper_bound = q75 + 1.5 * iqr
            
            outliers = [score for score in quality_scores if score < lower_bound or score > upper_bound]
            return len(outliers)
            
        except Exception as e:
            logging.error(f"Error counting quality outliers: {str(e)}")
            return 0
    
    def _calculate_quality_volatility(self, quality_scores: List[float]) -> float:
        """Calculate quality volatility."""
        try:
            if len(quality_scores) < 2:
                return 0.0
            
            # Calculate rolling differences
            differences = [abs(quality_scores[i] - quality_scores[i-1]) for i in range(1, len(quality_scores))]
            volatility = np.mean(differences)
            
            return volatility
            
        except Exception as e:
            logging.error(f"Error calculating quality volatility: {str(e)}")
            return 0.0
    
    def _analyze_quality_distribution(self, quality_scores: List[float]) -> Dict[str, Any]:
        """Analyze quality score distribution."""
        try:
            from scipy import stats
            
            distribution_analysis = {
                'distribution_type': 'unknown',
                'normality_test': {'statistic': 0, 'p_value': 1.0, 'is_normal': False},
                'skewness': 0.0,
                'kurtosis': 0.0
            }
            
            if len(quality_scores) >= 8:
                # Normality test
                stat, p_value = stats.shapiro(quality_scores)
                distribution_analysis['normality_test'] = {
                    'statistic': stat,
                    'p_value': p_value,
                    'is_normal': p_value > 0.05
                }
                
                # Skewness and kurtosis
                distribution_analysis['skewness'] = stats.skew(quality_scores)
                distribution_analysis['kurtosis'] = stats.kurtosis(quality_scores)
                
                # Determine distribution type
                if distribution_analysis['normality_test']['is_normal']:
                    distribution_analysis['distribution_type'] = 'normal'
                elif distribution_analysis['skewness'] > 1:
                    distribution_analysis['distribution_type'] = 'right_skewed'
                elif distribution_analysis['skewness'] < -1:
                    distribution_analysis['distribution_type'] = 'left_skewed'
                else:
                    distribution_analysis['distribution_type'] = 'approximately_normal'
            
            return distribution_analysis
            
        except ImportError:
            return {'error': 'scipy not available for distribution analysis'}
        except Exception as e:
            logging.error(f"Error analyzing quality distribution: {str(e)}")
            return {'error': str(e)}
    
    def _analyze_comprehensive_trends(self, quality_scores: List[float]) -> Dict[str, Any]:
        """Analyze comprehensive quality trends."""
        try:
            trend_analysis = {
                'overall_trend': 0.0,
                'trend_direction': 'stable',
                'trend_strength': 0.0,
                'trend_consistency': 0.0,
                'recent_trend': 0.0,
                'long_term_trend': 0.0
            }
            
            if len(quality_scores) >= 10:
                # Overall trend
                x = np.arange(len(quality_scores))
                slope, _, r_value, _, _ = stats.linregress(x, quality_scores)
                
                trend_analysis['overall_trend'] = slope
                trend_analysis['trend_strength'] = abs(r_value)
                trend_analysis['trend_consistency'] = r_value ** 2
                
                # Trend direction
                if slope > 0.01:
                    trend_analysis['trend_direction'] = 'improving'
                elif slope < -0.01:
                    trend_analysis['trend_direction'] = 'declining'
                else:
                    trend_analysis['trend_direction'] = 'stable'
                
                # Recent vs long-term trend
                if len(quality_scores) >= 20:
                    recent_scores = quality_scores[-10:]
                    recent_x = np.arange(len(recent_scores))
                    recent_slope, _, _, _, _ = stats.linregress(recent_x, recent_scores)
                    trend_analysis['recent_trend'] = recent_slope
                    trend_analysis['long_term_trend'] = slope
            
            return trend_analysis
            
        except Exception as e:
            logging.error(f"Error analyzing comprehensive trends: {str(e)}")
            return {'error': str(e)}
    
    def _analyze_dimension_statistics(self, experiences: List[Dict[str, Any]]) -> Dict[str, Any]:
        """Analyze dimension-wise quality statistics."""
        try:
            dimension_analysis = {}
            
            for dimension in self.quality_dimensions:
                dimension_scores = []
                for exp in experiences:
                    if 'dimension_scores' in exp and dimension in exp['dimension_scores']:
                        dimension_scores.append(exp['dimension_scores'][dimension])
                
                if dimension_scores:
                    dimension_analysis[dimension] = {
                        'mean': np.mean(dimension_scores),
                        'std': np.std(dimension_scores),
                        'min': np.min(dimension_scores),
                        'max': np.max(dimension_scores),
                        'threshold_compliance': np.mean([
                            score >= self.quality_dimensions[dimension]['threshold']
                            for score in dimension_scores
                        ]),
                        'trend': self._calculate_dimension_trend(dimension_scores)
                    }
                else:
                    dimension_analysis[dimension] = {
                        'mean': 0.0,
                        'data_available': False
                    }
            
            return dimension_analysis
            
        except Exception as e:
            logging.error(f"Error analyzing dimension statistics: {str(e)}")
            return {}
    
    def _calculate_dimension_trend(self, dimension_scores: List[float]) -> float:
        """Calculate trend for a specific dimension."""
        try:
            if len(dimension_scores) < 3:
                return 0.0
            
            x = np.arange(len(dimension_scores))
            slope, _, _, _, _ = stats.linregress(x, dimension_scores)
            return slope
            
        except Exception as e:
            logging.error(f"Error calculating dimension trend: {str(e)}")
            return 0.0
    
    def _analyze_comprehensive_correlations(self, experiences: List[Dict[str, Any]]) -> Dict[str, Any]:
        """Analyze comprehensive correlations."""
        try:
            correlation_analysis = {
                'dimension_correlations': {},
                'performance_correlations': {},
                'temporal_correlations': {}
            }
            
            # Dimension correlations
            if len(experiences) >= 10:
                dimension_data = {}
                for dimension in self.quality_dimensions:
                    scores = []
                    for exp in experiences:
                        if 'dimension_scores' in exp and dimension in exp['dimension_scores']:
                            scores.append(exp['dimension_scores'][dimension])
                    if len(scores) == len(experiences):
                        dimension_data[dimension] = scores
                
                # Calculate correlation matrix
                if len(dimension_data) >= 2:
                    correlation_matrix = {}
                    dimensions = list(dimension_data.keys())
                    
                    for i, dim1 in enumerate(dimensions):
                        correlation_matrix[dim1] = {}
                        for j, dim2 in enumerate(dimensions):
                            if i != j:
                                correlation = np.corrcoef(dimension_data[dim1], dimension_data[dim2])[0, 1]
                                correlation_matrix[dim1][dim2] = correlation
                    
                    correlation_analysis['dimension_correlations'] = correlation_matrix
            
            return correlation_analysis
            
        except Exception as e:
            logging.error(f"Error analyzing comprehensive correlations: {str(e)}")
            return {}
    
    def _get_prediction_statistics(self) -> Dict[str, Any]:
        """Get quality prediction statistics."""
        try:
            prediction_stats = {
                'predictor_available': self.quality_predictor is not None,
                'prediction_accuracy': 0.0,
                'last_forecast_available': False,
                'forecast_horizon': self.forecast_horizon
            }
            
            if self.quality_predictor:
                prediction_stats['prediction_accuracy'] = self.quality_predictor.get('prediction_accuracy', 0.0)
                
                if 'last_forecast' in self.quality_predictor:
                    prediction_stats['last_forecast_available'] = True
                    prediction_stats['last_forecast'] = self.quality_predictor['last_forecast']
            
            return prediction_stats
            
        except Exception as e:
            logging.error(f"Error getting prediction statistics: {str(e)}")
            return {'error': str(e)}
    
    def _assess_monitoring_health(self) -> Dict[str, Any]:
        """Assess monitoring system health."""
        try:
            health_metrics = {
                'system_status': 'healthy',
                'monitoring_active': self.monitoring_active,
                'total_experiences_processed': self.monitoring_stats['total_experiences'],
                'quality_assessments_completed': self.monitoring_stats['quality_assessments'],
                'alerts_triggered': self.monitoring_stats['alerts_triggered'],
                'degradations_detected': self.monitoring_stats['degradations_detected'],
                'optimizations_applied': self.monitoring_stats['optimizations_applied'],
                'alert_handlers_active': len(self.alert_handlers),
                'adaptive_thresholds_active': len(self.adaptive_thresholds),
                'quality_history_size': len(self.quality_history),
                'detailed_history_size': len(self.detailed_quality_history)
            }
            
            # Health assessment
            if self.monitoring_stats['total_experiences'] == 0:
                health_metrics['system_status'] = 'inactive'
            elif self.monitoring_stats['quality_assessments'] < self.monitoring_stats['total_experiences'] * 0.9:
                health_metrics['system_status'] = 'degraded'
            
            return health_metrics
            
        except Exception as e:
            logging.error(f"Error assessing monitoring health: {str(e)}")
            return {'system_status': 'error', 'error': str(e)}
    
    def _generate_comprehensive_recommendations(self, experiences: List[Dict[str, Any]]) -> List[str]:
        """Generate comprehensive quality improvement recommendations."""
        try:
            recommendations = []
            
            if not experiences:
                return ["No experiences available for analysis"]
            
            quality_scores = [exp.get('quality_score', 0.5) for exp in experiences]
            avg_quality = np.mean(quality_scores)
            
            # Overall quality recommendations
            if avg_quality < 0.6:
                recommendations.append("Consider comprehensive system review and model architecture optimization")
            elif avg_quality < 0.8:
                recommendations.append("Focus on hyperparameter tuning and validation strategy improvement")
            
            # Trend-based recommendations
            if len(quality_scores) >= 10:
                trend = self._calculate_quality_trend()
                if trend < -0.05:
                    recommendations.append("Quality is declining - investigate data drift and model degradation")
                elif trend > 0.05:
                    recommendations.append("Quality is improving - maintain current optimization strategies")
            
            # Variability recommendations
            quality_std = np.std(quality_scores)
            if quality_std > 0.2:
                recommendations.append("High quality variability detected - implement stability optimization")
            
            # Monitoring recommendations
            if self.monitoring_stats['alerts_triggered'] > self.monitoring_stats['total_experiences'] * 0.1:
                recommendations.append("High alert frequency - review alert thresholds and quality targets")
            
            return recommendations[:7]  # Limit to top recommendations
            
        except Exception as e:
            logging.error(f"Error generating comprehensive recommendations: {str(e)}")
            return ["Unable to generate recommendations due to analysis error"]
    
