    def _extract_temporal_data(self, experiences: List[Dict]) -> Dict[str, Any]:
        """Extract temporal data from experiences."""
        try:
            temporal_data = {
                'timestamps': [],
                'values': [],
                'features': {},
                'metadata': {}
            }
            
            # Extract core temporal information
            for exp in experiences:
                timestamp = exp.get('timestamp', time.time())
                temporal_data['timestamps'].append(timestamp)
                
                # Extract primary value (quality score, reward, etc.)
                value = exp.get('quality_score', exp.get('reward', exp.get('value', 0.0)))
                temporal_data['values'].append(value)
                
                # Extract additional features for multivariate analysis
                for key in ['action', 'state', 'observation', 'prediction']:
                    if key in exp:
                        if key not in temporal_data['features']:
                            temporal_data['features'][key] = []
                        temporal_data['features'][key].append(exp[key])
            
            # Convert to arrays for analysis
            temporal_data['timestamps'] = np.array(temporal_data['timestamps'])
            temporal_data['values'] = np.array(temporal_data['values'])
            
            # Sort by timestamp
            sorted_indices = np.argsort(temporal_data['timestamps'])
            temporal_data['timestamps'] = temporal_data['timestamps'][sorted_indices]
            temporal_data['values'] = temporal_data['values'][sorted_indices]
            
            # Calculate time differences
            temporal_data['time_deltas'] = np.diff(temporal_data['timestamps'])
            temporal_data['sampling_rate'] = 1.0 / np.mean(temporal_data['time_deltas']) if len(temporal_data['time_deltas']) > 0 else 1.0
            
            return temporal_data
            
        except Exception as e:
            logging.error(f"Error extracting temporal data: {str(e)}")
            return {'error': str(e)}
    
    def _analyze_temporal_scale(self, temporal_data: Dict[str, Any], scale: str) -> Dict[str, Any]:
        """Analyze temporal patterns at specific scale."""
        try:
            scale_config = self.scale_definitions.get(scale, {})
            
            scale_analysis = {
                'scale': scale,
                'duration': scale_config.get('duration', 'unknown'),
                'resolution': scale_config.get('resolution', 1.0),
                'patterns_detected': 0,
                'dominant_frequency': 0.0,
                'temporal_stability': 0.0,
                'characteristic_features': {}
            }
            
            # Apply scale-specific filtering
            filtered_data = self._apply_scale_filtering(temporal_data, scale)
            
            # Scale-specific pattern detection
            patterns = self._detect_scale_patterns(filtered_data, scale)
            scale_analysis['patterns_detected'] = len(patterns)
            scale_analysis['patterns'] = patterns
            
            # Frequency analysis at scale
            frequency_analysis = self._analyze_scale_frequencies(filtered_data, scale)
            scale_analysis['frequency_analysis'] = frequency_analysis
            scale_analysis['dominant_frequency'] = frequency_analysis.get('dominant_frequency', 0.0)
            
            # Stability analysis
            stability_score = self._calculate_scale_stability(filtered_data)
            scale_analysis['temporal_stability'] = stability_score
            
            # Characteristic features
            features = self._extract_scale_features(filtered_data, scale)
            scale_analysis['characteristic_features'] = features
            
            return scale_analysis
            
        except Exception as e:
            logging.error(f"Error analyzing temporal scale {scale}: {str(e)}")
            return {'scale': scale, 'error': str(e)}
    
    def _apply_scale_filtering(self, temporal_data: Dict[str, Any], scale: str) -> Dict[str, Any]:
        """Apply scale-specific temporal filtering."""
        try:
            # Get scale configuration
            scale_config = self.scale_definitions.get(scale, {})
            resolution = scale_config.get('resolution', 1.0)
            
            # Apply appropriate filtering based on scale
            filtered_data = temporal_data.copy()
            
            if scale == 'micro':
                # High-pass filtering for micro-scale
                filtered_data['values'] = self._apply_highpass_filter(temporal_data['values'])
            elif scale == 'short':
                # Band-pass filtering for short-term patterns
                filtered_data['values'] = self._apply_bandpass_filter(temporal_data['values'], 0.1, 1.0)
            elif scale == 'medium':
                # Medium-term trend extraction
                filtered_data['values'] = self._apply_moving_average(temporal_data['values'], window=24)
            elif scale == 'long':
                # Long-term trend analysis
                filtered_data['values'] = self._apply_seasonal_decomposition(temporal_data['values'])
            elif scale == 'geological':
                # Very long-term trend extraction
                filtered_data['values'] = self._apply_lowpass_filter(temporal_data['values'])
            
            return filtered_data
            
        except Exception as e:
            logging.error(f"Error applying scale filtering for {scale}: {str(e)}")
            return temporal_data
    
    def _detect_scale_patterns(self, filtered_data: Dict[str, Any], scale: str) -> List[Dict[str, Any]]:
        """Detect patterns at specific temporal scale."""
        try:
            patterns = []
            
            values = filtered_data.get('values', [])
            if len(values) < 10:
                return patterns
            
            # Pattern detection based on scale
            if scale == 'micro':
                # Detect rapid events and spikes
                patterns.extend(self._detect_spike_patterns(values))
                patterns.extend(self._detect_burst_patterns(values))
                
            elif scale == 'short':
                # Detect daily patterns and cycles
                patterns.extend(self._detect_daily_patterns(values))
                patterns.extend(self._detect_periodic_patterns(values, period_range=(1, 24)))
                
            elif scale == 'medium':
                # Detect weekly and monthly patterns
                patterns.extend(self._detect_weekly_patterns(values))
                patterns.extend(self._detect_monthly_patterns(values))
                
            elif scale == 'long':
                # Detect seasonal patterns
                patterns.extend(self._detect_seasonal_patterns(values))
                patterns.extend(self._detect_annual_patterns(values))
                
            elif scale == 'geological':
                # Detect long-term trends and geological cycles
                patterns.extend(self._detect_longterm_trends(values))
                patterns.extend(self._detect_geological_cycles(values))
            
            return patterns
            
        except Exception as e:
            logging.error(f"Error detecting patterns for scale {scale}: {str(e)}")
            return []
    
    def _analyze_scale_frequencies(self, filtered_data: Dict[str, Any], scale: str) -> Dict[str, Any]:
        """Analyze frequency characteristics at specific scale."""
        try:
            values = filtered_data.get('values', [])
            if len(values) < 10:
                return {'error': 'Insufficient data for frequency analysis'}
            
            # Perform FFT analysis
            fft_result = np.fft.fft(values)
            frequencies = np.fft.fftfreq(len(values))
            power_spectrum = np.abs(fft_result) ** 2
            
            # Find dominant frequency
            dominant_idx = np.argmax(power_spectrum[1:len(power_spectrum)//2]) + 1
            dominant_frequency = abs(frequencies[dominant_idx])
            
            # Calculate spectral features
            spectral_centroid = np.sum(frequencies[1:len(frequencies)//2] * power_spectrum[1:len(power_spectrum)//2]) / np.sum(power_spectrum[1:len(power_spectrum)//2])
            spectral_rolloff = self._calculate_spectral_rolloff(frequencies, power_spectrum)
            spectral_bandwidth = self._calculate_spectral_bandwidth(frequencies, power_spectrum, spectral_centroid)
            
            return {
                'dominant_frequency': dominant_frequency,
                'spectral_centroid': spectral_centroid,
                'spectral_rolloff': spectral_rolloff,
                'spectral_bandwidth': spectral_bandwidth,
                'power_spectrum_peak': np.max(power_spectrum),
                'frequency_resolution': frequencies[1] - frequencies[0] if len(frequencies) > 1 else 0.0
            }
            
        except Exception as e:
            logging.error(f"Error in frequency analysis for scale {scale}: {str(e)}")
            return {'error': str(e)}
    
    def _calculate_scale_stability(self, filtered_data: Dict[str, Any]) -> float:
        """Calculate temporal stability at specific scale."""
        try:
            values = filtered_data.get('values', [])
            if len(values) < 10:
                return 0.0
            
            # Calculate various stability metrics
            cv = np.std(values) / np.mean(values) if np.mean(values) != 0 else float('inf')
            stability_cv = max(0.0, 1.0 - cv)
            
            # Trend stability
            trend_stability = 1.0 - abs(np.polyfit(range(len(values)), values, 1)[0])
            trend_stability = max(0.0, min(1.0, trend_stability))
            
            # Autocorrelation stability
            autocorr = np.corrcoef(values[:-1], values[1:])[0, 1] if len(values) > 1 else 0.0
            autocorr_stability = abs(autocorr) if not np.isnan(autocorr) else 0.0
            
            # Combined stability score
            stability_score = (stability_cv + trend_stability + autocorr_stability) / 3.0
            
            return max(0.0, min(1.0, stability_score))
            
        except Exception as e:
            logging.error(f"Error calculating scale stability: {str(e)}")
            return 0.0
    
    def _extract_scale_features(self, filtered_data: Dict[str, Any], scale: str) -> Dict[str, Any]:
        """Extract characteristic features at specific scale."""
        try:
            values = filtered_data.get('values', [])
            if len(values) < 5:
                return {}
            
            features = {
                'mean': np.mean(values),
                'std': np.std(values),
                'min': np.min(values),
                'max': np.max(values),
                'range': np.max(values) - np.min(values),
                'skewness': self._calculate_skewness(values),
                'kurtosis': self._calculate_kurtosis(values),
                'trend_slope': np.polyfit(range(len(values)), values, 1)[0] if len(values) > 1 else 0.0,
                'autocorrelation': np.corrcoef(values[:-1], values[1:])[0, 1] if len(values) > 1 else 0.0,
                'energy': np.sum(np.square(values)),
                'zero_crossings': self._count_zero_crossings(values),
                'peak_count': self._count_peaks(values),
                'entropy': self._calculate_temporal_entropy(values)
            }
            
            # Scale-specific features
            if scale == 'micro':
                features['spike_rate'] = self._calculate_spike_rate(values)
                features['burst_duration'] = self._calculate_burst_duration(values)
            elif scale in ['short', 'medium']:
                features['periodicity_strength'] = self._calculate_periodicity_strength(values)
                features['cycle_regularity'] = self._calculate_cycle_regularity(values)
            elif scale in ['long', 'geological']:
                features['trend_strength'] = abs(features['trend_slope'])
                features['seasonal_strength'] = self._calculate_seasonal_strength(values)
            
            return features
            
        except Exception as e:
            logging.error(f"Error extracting scale features for {scale}: {str(e)}")
            return {}
    
    def _detect_temporal_patterns(self, temporal_data: Dict[str, Any]) -> Dict[str, Any]:
        """Detect comprehensive temporal patterns."""
        try:
            pattern_analysis = {
                'total_patterns': 0,
                'pattern_types': {},
                'pattern_strength': 0.0,
                'pattern_confidence': 0.0
            }
            
            values = temporal_data.get('values', [])
            if len(values) < 20:
                return pattern_analysis
            
            # Various pattern detection methods
            pattern_detectors = {
                'periodic_patterns': self._detect_periodic_patterns,
                'trend_patterns': self._detect_trend_patterns,
                'cyclic_patterns': self._detect_cyclic_patterns,
                'seasonal_patterns': self._detect_seasonal_patterns,
                'anomaly_patterns': self._detect_anomaly_patterns,
                'regime_changes': self._detect_regime_changes,
                'oscillatory_patterns': self._detect_oscillatory_patterns,
                'burst_patterns': self._detect_burst_patterns
            }
            
            all_patterns = []
            for pattern_type, detector in pattern_detectors.items():
                try:
                    patterns = detector(values)
                    pattern_analysis['pattern_types'][pattern_type] = len(patterns)
                    all_patterns.extend(patterns)
                except Exception as e:
                    logging.error(f"Error in {pattern_type} detection: {str(e)}")
                    pattern_analysis['pattern_types'][pattern_type] = 0
            
            pattern_analysis['total_patterns'] = len(all_patterns)
            
            # Calculate overall pattern strength and confidence
            if all_patterns:
                strengths = [p.get('strength', 0.0) for p in all_patterns]
                confidences = [p.get('confidence', 0.0) for p in all_patterns]
                
                pattern_analysis['pattern_strength'] = np.mean(strengths)
                pattern_analysis['pattern_confidence'] = np.mean(confidences)
            
            pattern_analysis['detected_patterns'] = all_patterns
            
            return pattern_analysis
            
        except Exception as e:
            logging.error(f"Error in temporal pattern detection: {str(e)}")
            return {'total_patterns': 0, 'error': str(e)}
    
    def _perform_trend_decomposition(self, temporal_data: Dict[str, Any]) -> Dict[str, Any]:
        """Perform comprehensive trend decomposition analysis."""
        try:
            values = temporal_data.get('values', [])
            if len(values) < 24:  # Minimum for seasonal decomposition
                return {'error': 'Insufficient data for trend decomposition'}
            
            trend_analysis = {
                'decomposition_method': 'seasonal_decompose',
                'trend_strength': 0.0,
                'seasonal_strength': 0.0,
                'residual_variance': 0.0,
                'decomposition_quality': 0.0
            }
            
            try:
                from statsmodels.tsa.seasonal import seasonal_decompose
                
                # Perform seasonal decomposition
                decomposition = seasonal_decompose(values, model='additive', period=min(12, len(values)//2))
                
                # Extract components
                trend = decomposition.trend
                seasonal = decomposition.seasonal
                residual = decomposition.resid
                
                # Remove NaN values
                trend = trend[~np.isnan(trend)]
                seasonal = seasonal[~np.isnan(seasonal)]
                residual = residual[~np.isnan(residual)]
                
                # Calculate component strengths
                if len(trend) > 0:
                    trend_analysis['trend_strength'] = np.var(trend) / np.var(values) if np.var(values) > 0 else 0.0
                
                if len(seasonal) > 0:
                    trend_analysis['seasonal_strength'] = np.var(seasonal) / np.var(values) if np.var(values) > 0 else 0.0
                
                if len(residual) > 0:
                    trend_analysis['residual_variance'] = np.var(residual)
                
                # Quality of decomposition
                explained_variance = trend_analysis['trend_strength'] + trend_analysis['seasonal_strength']
                trend_analysis['decomposition_quality'] = min(1.0, explained_variance)
                
                # Store components
                trend_analysis['components'] = {
                    'trend': trend.tolist() if len(trend) > 0 else [],
                    'seasonal': seasonal.tolist() if len(seasonal) > 0 else [],
                    'residual': residual.tolist() if len(residual) > 0 else []
                }
                
                # Trend characteristics
                if len(trend) > 1:
                    trend_slope = np.polyfit(range(len(trend)), trend, 1)[0]
                    trend_analysis['trend_direction'] = 'increasing' if trend_slope > 0.01 else 'decreasing' if trend_slope < -0.01 else 'stable'
                    trend_analysis['trend_slope'] = trend_slope
                
            except ImportError:
                # Fallback to simple trend analysis without statsmodels
                trend_analysis.update(self._simple_trend_analysis(values))
                
            return trend_analysis
            
        except Exception as e:
            logging.error(f"Error in trend decomposition: {str(e)}")
            return {'error': str(e)}
    
    def _simple_trend_analysis(self, values: List[float]) -> Dict[str, Any]:
        """Simple trend analysis without external dependencies."""
        try:
            # Linear trend
            x = np.arange(len(values))
            trend_slope, trend_intercept = np.polyfit(x, values, 1)
            trend_line = trend_slope * x + trend_intercept
            
            # Detrended values
            detrended = np.array(values) - trend_line
            
            # Moving average (simple seasonal component)
            window = min(12, len(values) // 4)
            if window > 0:
                seasonal = np.convolve(detrended, np.ones(window)/window, mode='same')
            else:
                seasonal = np.zeros_like(detrended)
            
            # Residual
            residual = detrended - seasonal
            
            return {
                'trend_strength': np.var(trend_line) / np.var(values) if np.var(values) > 0 else 0.0,
                'seasonal_strength': np.var(seasonal) / np.var(values) if np.var(values) > 0 else 0.0,
                'residual_variance': np.var(residual),
                'trend_slope': trend_slope,
                'trend_direction': 'increasing' if trend_slope > 0.01 else 'decreasing' if trend_slope < -0.01 else 'stable',
                'decomposition_method': 'simple_linear'
            }
            
        except Exception as e:
            logging.error(f"Error in simple trend analysis: {str(e)}")
            return {'error': str(e)}
    
    def _perform_seasonal_analysis(self, temporal_data: Dict[str, Any]) -> Dict[str, Any]:
        """Perform comprehensive seasonal pattern analysis."""
        try:
            values = temporal_data.get('values', [])
            timestamps = temporal_data.get('timestamps', [])
            
            seasonal_analysis = {
                'seasonal_periods_detected': 0,
                'seasonal_strength': 0.0,
                'dominant_period': 0,
                'seasonal_patterns': []
            }
            
            if len(values) < 20:
                return seasonal_analysis
            
            # Detect multiple seasonal periods
            periods_to_test = [7, 12, 24, 30, 365] if len(values) >= 365 else [7, 12, 24]
            periods_to_test = [p for p in periods_to_test if p < len(values) // 3]
            
            detected_periods = []
            
            for period in periods_to_test:
                seasonal_strength = self._test_seasonal_period(values, period)
                
                if seasonal_strength > self.seasonal_threshold:
                    detected_periods.append({
                        'period': period,
                        'strength': seasonal_strength,
                        'pattern': self._extract_seasonal_pattern(values, period)
                    })
            
            # Sort by strength
            detected_periods.sort(key=lambda x: x['strength'], reverse=True)
            
            seasonal_analysis['seasonal_periods_detected'] = len(detected_periods)
            seasonal_analysis['seasonal_patterns'] = detected_periods
            
            if detected_periods:
                seasonal_analysis['dominant_period'] = detected_periods[0]['period']
                seasonal_analysis['seasonal_strength'] = detected_periods[0]['strength']
            
            # Additional seasonal analysis
            seasonal_analysis['seasonality_tests'] = self._perform_seasonality_tests(values)
            
            return seasonal_analysis
            
        except Exception as e:
            logging.error(f"Error in seasonal analysis: {str(e)}")
            return {'error': str(e)}
    
    def _test_seasonal_period(self, values: List[float], period: int) -> float:
        """Test for seasonal pattern with specific period."""
        try:
            if len(values) < 2 * period:
                return 0.0
            
            # Reshape data into seasonal periods
            n_complete_periods = len(values) // period
            reshaped = np.array(values[:n_complete_periods * period]).reshape(n_complete_periods, period)
            
            # Calculate mean seasonal pattern
            seasonal_mean = np.mean(reshaped, axis=0)
            
            # Calculate seasonal strength as correlation with mean pattern
            correlations = []
            for i in range(n_complete_periods):
                corr = np.corrcoef(reshaped[i], seasonal_mean)[0, 1]
                if not np.isnan(corr):
                    correlations.append(abs(corr))
            
            return np.mean(correlations) if correlations else 0.0
            
        except Exception as e:
            logging.error(f"Error testing seasonal period {period}: {str(e)}")
            return 0.0
    
    def _extract_seasonal_pattern(self, values: List[float], period: int) -> List[float]:
        """Extract the seasonal pattern for a given period."""
        try:
            n_complete_periods = len(values) // period
            if n_complete_periods < 2:
                return []
            
            reshaped = np.array(values[:n_complete_periods * period]).reshape(n_complete_periods, period)
            seasonal_pattern = np.mean(reshaped, axis=0)
            
            return seasonal_pattern.tolist()
            
        except Exception as e:
            logging.error(f"Error extracting seasonal pattern for period {period}: {str(e)}")
            return []
    
    def _perform_seasonality_tests(self, values: List[float]) -> Dict[str, Any]:
        """Perform statistical tests for seasonality."""
        try:
            tests = {}
            
            # Autocorrelation test
            if len(values) > 24:
                autocorr_12 = self._calculate_autocorrelation(values, 12)
                autocorr_24 = self._calculate_autocorrelation(values, 24)
                
                tests['autocorr_test'] = {
                    'lag_12': autocorr_12,
                    'lag_24': autocorr_24,
                    'seasonal_evidence': max(abs(autocorr_12), abs(autocorr_24)) > 0.3
                }
            
            # Periodogram test
            if len(values) > 50:
                periodogram_result = self._calculate_periodogram(values)
                tests['periodogram_test'] = periodogram_result
            
            return tests
            
        except Exception as e:
            logging.error(f"Error in seasonality tests: {str(e)}")
            return {'error': str(e)}
    
    def _perform_causality_analysis(self, temporal_data: Dict[str, Any]) -> Dict[str, Any]:
        """Perform temporal causality analysis."""
        try:
            causality_analysis = {
                'granger_causality': {},
                'cross_correlation': {},
                'lag_analysis': {},
                'causal_strength': 0.0
            }
            
            # Multi-variate causality analysis if features available
            features = temporal_data.get('features', {})
            values = temporal_data.get('values', [])
            
            if len(values) < 20:
                return causality_analysis
            
            # Self-causality (autocorrelation)
            self_causality = self._analyze_self_causality(values)
            causality_analysis['self_causality'] = self_causality
            
            # Cross-variable causality if multiple features
            if features:
                for feature_name, feature_values in features.items():
                    if isinstance(feature_values[0], (int, float)) and len(feature_values) == len(values):
                        cross_analysis = self._analyze_cross_causality(values, feature_values, feature_name)
                        causality_analysis['cross_causality'][feature_name] = cross_analysis
            
            # Overall causal strength
            all_strengths = []
            all_strengths.append(self_causality.get('strength', 0.0))
            
            for cross_causal in causality_analysis.get('cross_causality', {}).values():
                all_strengths.append(cross_causal.get('strength', 0.0))
            
            causality_analysis['causal_strength'] = np.mean(all_strengths) if all_strengths else 0.0
            
            return causality_analysis
            
        except Exception as e:
            logging.error(f"Error in causality analysis: {str(e)}")
            return {'error': str(e)}
    
    def _analyze_self_causality(self, values: List[float]) -> Dict[str, Any]:
        """Analyze self-causality (autocorrelation structure)."""
        try:
            max_lag = min(20, len(values) // 4)
            autocorrelations = []
            
            for lag in range(1, max_lag + 1):
                autocorr = self._calculate_autocorrelation(values, lag)
                autocorrelations.append({'lag': lag, 'correlation': autocorr})
            
            # Find most significant lag
            max_autocorr = max(autocorrelations, key=lambda x: abs(x['correlation']))
            
            return {
                'autocorrelations': autocorrelations,
                'max_lag': max_autocorr['lag'],
                'max_correlation': max_autocorr['correlation'],
                'strength': abs(max_autocorr['correlation'])
            }
            
        except Exception as e:
            logging.error(f"Error in self-causality analysis: {str(e)}")
            return {'strength': 0.0}
    
    def _analyze_cross_causality(self, target_values: List[float], feature_values: List[float], feature_name: str) -> Dict[str, Any]:
        """Analyze cross-causality between target and feature."""
        try:
            max_lag = min(10, len(target_values) // 4)
            cross_correlations = []
            
            for lag in range(max_lag + 1):
                if lag == 0:
                    cross_corr = np.corrcoef(target_values, feature_values)[0, 1]
                else:
                    if lag < len(feature_values):
                        cross_corr = np.corrcoef(target_values[lag:], feature_values[:-lag])[0, 1]
                    else:
                        cross_corr = 0.0
                
                if not np.isnan(cross_corr):
                    cross_correlations.append({'lag': lag, 'correlation': cross_corr})
            
            # Find most significant lag
            if cross_correlations:
                max_cross_corr = max(cross_correlations, key=lambda x: abs(x['correlation']))
                
                return {
                    'feature_name': feature_name,
                    'cross_correlations': cross_correlations,
                    'max_lag': max_cross_corr['lag'],
                    'max_correlation': max_cross_corr['correlation'],
                    'strength': abs(max_cross_corr['correlation']),
                    'causal_direction': 'feature_to_target' if max_cross_corr['lag'] > 0 else 'contemporaneous'
                }
            
            return {'feature_name': feature_name, 'strength': 0.0}
            
        except Exception as e:
            logging.error(f"Error in cross-causality analysis for {feature_name}: {str(e)}")
            return {'feature_name': feature_name, 'strength': 0.0}
    
    def _perform_anomaly_detection(self, temporal_data: Dict[str, Any]) -> Dict[str, Any]:
        """Perform temporal anomaly detection."""
        try:
            values = temporal_data.get('values', [])
            
            anomaly_analysis = {
                'anomalies_detected': 0,
                'anomaly_rate': 0.0,
                'anomaly_types': {},
                'anomaly_locations': []
            }
            
            if len(values) < 10:
                return anomaly_analysis
            
            # Multiple anomaly detection methods
            anomaly_detectors = {
                'statistical_outliers': self._detect_statistical_outliers,
                'zscore_anomalies': self._detect_zscore_anomalies,
                'isolation_forest': self._detect_isolation_anomalies,
                'change_points': self._detect_change_points,
                'temporal_outliers': self._detect_temporal_outliers
            }
            
            all_anomalies = []
            
            for anomaly_type, detector in anomaly_detectors.items():
                try:
                    anomalies = detector(values)
                    anomaly_analysis['anomaly_types'][anomaly_type] = len(anomalies)
                    all_anomalies.extend([(idx, anomaly_type) for idx in anomalies])
                except Exception as e:
                    logging.error(f"Error in {anomaly_type} detection: {str(e)}")
                    anomaly_analysis['anomaly_types'][anomaly_type] = 0
            
            # Remove duplicates and sort
            unique_anomalies = list(set([idx for idx, _ in all_anomalies]))
            unique_anomalies.sort()
            
            anomaly_analysis['anomalies_detected'] = len(unique_anomalies)
            anomaly_analysis['anomaly_rate'] = len(unique_anomalies) / len(values)
            anomaly_analysis['anomaly_locations'] = unique_anomalies
            
            return anomaly_analysis
            
        except Exception as e:
            logging.error(f"Error in anomaly detection: {str(e)}")
            return {'error': str(e)}
    
    def _perform_forecasting_analysis(self, temporal_data: Dict[str, Any]) -> Dict[str, Any]:
        """Perform temporal forecasting analysis."""
        try:
            values = temporal_data.get('values', [])
            
            forecast_analysis = {
                'forecast_horizon': 10,
                'forecasting_methods': {},
                'ensemble_forecast': [],
                'forecast_confidence': 0.0
            }
            
            if len(values) < 20:
                return forecast_analysis
            
            # Try multiple forecasting methods
            forecasting_methods = {
                'simple_moving_average': self._forecast_moving_average,
                'exponential_smoothing': self._forecast_exponential_smoothing,
                'linear_trend': self._forecast_linear_trend,
                'seasonal_naive': self._forecast_seasonal_naive
            }
            
            all_forecasts = []
            
            for method_name, method_func in forecasting_methods.items():
                try:
                    forecast_result = method_func(values)
                    forecast_analysis['forecasting_methods'][method_name] = forecast_result
                    
                    if 'forecast' in forecast_result:
                        all_forecasts.append(forecast_result['forecast'])
                except Exception as e:
                    logging.error(f"Error in {method_name} forecasting: {str(e)}")
                    forecast_analysis['forecasting_methods'][method_name] = {'error': str(e)}
            
            # Ensemble forecast
            if all_forecasts:
                ensemble_forecast = np.mean(all_forecasts, axis=0)
                forecast_analysis['ensemble_forecast'] = ensemble_forecast.tolist()
                
                # Calculate forecast confidence
                forecast_std = np.std(all_forecasts, axis=0)
                forecast_analysis['forecast_confidence'] = 1.0 / (1.0 + np.mean(forecast_std))
            
            return forecast_analysis
            
        except Exception as e:
            logging.error(f"Error in forecasting analysis: {str(e)}")
            return {'error': str(e)}
    
    def _perform_correlation_analysis(self, temporal_data: Dict[str, Any]) -> Dict[str, Any]:
        """Perform comprehensive temporal correlation analysis."""
        try:
            values = temporal_data.get('values', [])
            features = temporal_data.get('features', {})
            
            correlation_analysis = {
                'auto_correlations': {},
                'cross_correlations': {},
                'correlation_strength': 0.0
            }
            
            if len(values) < 10:
                return correlation_analysis
            
            # Auto-correlation analysis
            max_lag = min(20, len(values) // 3)
            auto_correlations = []
            
            for lag in range(1, max_lag + 1):
                autocorr = self._calculate_autocorrelation(values, lag)
                auto_correlations.append({'lag': lag, 'correlation': autocorr})
            
            correlation_analysis['auto_correlations'] = auto_correlations
            
            # Cross-correlation with features
            for feature_name, feature_values in features.items():
                if isinstance(feature_values[0], (int, float)) and len(feature_values) == len(values):
                    cross_corr = np.corrcoef(values, feature_values)[0, 1]
                    if not np.isnan(cross_corr):
                        correlation_analysis['cross_correlations'][feature_name] = cross_corr
            
            # Overall correlation strength
            all_correlations = [abs(ac['correlation']) for ac in auto_correlations if not np.isnan(ac['correlation'])]
            all_correlations.extend([abs(cc) for cc in correlation_analysis['cross_correlations'].values()])
            
            correlation_analysis['correlation_strength'] = np.mean(all_correlations) if all_correlations else 0.0
            
            return correlation_analysis
            
        except Exception as e:
            logging.error(f"Error in correlation analysis: {str(e)}")
            return {'error': str(e)}
    
    def _calculate_temporal_coherence(self, temporal_analysis: Dict[str, Any]) -> float:
        """Calculate overall temporal coherence score."""
        try:
            coherence_factors = []
            
            # Pattern analysis coherence
            pattern_analysis = temporal_analysis.get('pattern_analysis', {})
            if pattern_analysis.get('total_patterns', 0) > 0:
                coherence_factors.append(pattern_analysis.get('pattern_confidence', 0.0))
            
            # Trend analysis coherence
            trend_analysis = temporal_analysis.get('trend_analysis', {})
            if 'decomposition_quality' in trend_analysis:
                coherence_factors.append(trend_analysis['decomposition_quality'])
            
            # Seasonal analysis coherence
            seasonal_analysis = temporal_analysis.get('seasonal_analysis', {})
            if seasonal_analysis.get('seasonal_strength', 0.0) > 0:
                coherence_factors.append(seasonal_analysis['seasonal_strength'])
            
            # Correlation analysis coherence
            correlation_analysis = temporal_analysis.get('correlation_analysis', {})
            if 'correlation_strength' in correlation_analysis:
                coherence_factors.append(correlation_analysis['correlation_strength'])
            
            # Scale analysis coherence
            scale_coherence = []
            for scale in self.temporal_scales:
                scale_analysis = temporal_analysis.get(f'{scale}_scale', {})
                if 'temporal_stability' in scale_analysis:
                    scale_coherence.append(scale_analysis['temporal_stability'])
            
            if scale_coherence:
                coherence_factors.append(np.mean(scale_coherence))
            
            # Overall coherence
            if coherence_factors:
                return min(1.0, np.mean(coherence_factors))
            else:
                return 0.5  # Default neutral coherence
                
        except Exception as e:
            logging.error(f"Error calculating temporal coherence: {str(e)}")
            return 0.0
    
    def _assess_temporal_quality(self, temporal_analysis: Dict[str, Any]) -> Dict[str, Any]:
        """Assess quality of temporal analysis."""
        try:
            quality_metrics = {
                'data_completeness': 0.0,
                'analysis_coverage': 0.0,
                'pattern_reliability': 0.0,
                'forecast_accuracy': 0.0,
                'overall_quality': 0.0
            }
            
            # Data completeness
            total_analyses = len(self.temporal_analyzers)
            completed_analyses = sum(1 for key in temporal_analysis.keys() 
                                   if not key.endswith('error') and temporal_analysis[key])
            
            quality_metrics['data_completeness'] = completed_analyses / total_analyses if total_analyses > 0 else 0.0
            
            # Analysis coverage
            expected_components = ['pattern_analysis', 'trend_analysis', 'seasonal_analysis', 'correlation_analysis']
            available_components = sum(1 for comp in expected_components if comp in temporal_analysis)
            quality_metrics['analysis_coverage'] = available_components / len(expected_components)
            
            # Pattern reliability
            pattern_analysis = temporal_analysis.get('pattern_analysis', {})
            quality_metrics['pattern_reliability'] = pattern_analysis.get('pattern_confidence', 0.0)
            
            # Forecast accuracy (if available)
            forecast_analysis = temporal_analysis.get('forecast_analysis', {})
            quality_metrics['forecast_accuracy'] = forecast_analysis.get('forecast_confidence', 0.0)
            
            # Overall quality
            quality_metrics['overall_quality'] = np.mean([
                quality_metrics['data_completeness'],
                quality_metrics['analysis_coverage'],
                quality_metrics['pattern_reliability'],
                quality_metrics['forecast_accuracy']
            ])
            
            return quality_metrics
            
        except Exception as e:
            logging.error(f"Error assessing temporal quality: {str(e)}")
            return {'overall_quality': 0.0, 'error': str(e)}
    
    def _update_temporal_cache(self, temporal_analysis: Dict[str, Any]):
        """Update temporal patterns cache."""
        try:
            # Cache key patterns
            if 'pattern_analysis' in temporal_analysis:
                pattern_analysis = temporal_analysis['pattern_analysis']
                if pattern_analysis.get('total_patterns', 0) > 0:
                    cache_key = f"patterns_{time.time()}"
                    self.pattern_cache[cache_key] = {
                        'timestamp': time.time(),
                        'patterns': pattern_analysis.get('detected_patterns', []),
                        'strength': pattern_analysis.get('pattern_strength', 0.0)
                    }
            
            # Limit cache size
            if len(self.pattern_cache) > 100:
                oldest_key = min(self.pattern_cache.keys(), 
                               key=lambda k: self.pattern_cache[k]['timestamp'])
                del self.pattern_cache[oldest_key]
                
        except Exception as e:
            logging.error(f"Error updating temporal cache: {str(e)}")
    
    def _generate_temporal_insights(self, temporal_analysis: Dict[str, Any]) -> List[str]:
        """Generate temporal insights and recommendations."""
        try:
            insights = []
            
            # Pattern insights
            pattern_analysis = temporal_analysis.get('pattern_analysis', {})
            total_patterns = pattern_analysis.get('total_patterns', 0)
            
            if total_patterns > 5:
                insights.append(f"Strong temporal structure detected with {total_patterns} distinct patterns")
            elif total_patterns > 0:
                insights.append(f"Moderate temporal structure with {total_patterns} patterns identified")
            else:
                insights.append("Limited temporal structure detected - consider longer observation period")
            
            # Trend insights
            trend_analysis = temporal_analysis.get('trend_analysis', {})
            trend_direction = trend_analysis.get('trend_direction', 'unknown')
            
            if trend_direction == 'increasing':
                insights.append("Clear increasing trend detected - system showing positive progression")
            elif trend_direction == 'decreasing':
                insights.append("Declining trend identified - investigate potential degradation factors")
            elif trend_direction == 'stable':
                insights.append("Stable temporal behavior - system maintaining consistent performance")
            
            # Seasonal insights
            seasonal_analysis = temporal_analysis.get('seasonal_analysis', {})
            seasonal_strength = seasonal_analysis.get('seasonal_strength', 0.0)
            
            if seasonal_strength > 0.7:
                insights.append("Strong seasonal patterns detected - consider seasonal adjustments in modeling")
            elif seasonal_strength > 0.4:
                insights.append("Moderate seasonal effects present - monitor seasonal variations")
            
            # Anomaly insights
            anomaly_analysis = temporal_analysis.get('anomaly_analysis', {})
            anomaly_rate = anomaly_analysis.get('anomaly_rate', 0.0)
            
            if anomaly_rate > 0.1:
                insights.append("High anomaly rate detected - investigate data quality and system stability")
            elif anomaly_rate > 0.05:
                insights.append("Moderate anomaly presence - monitor for systematic issues")
            
            # Coherence insights
            coherence = temporal_analysis.get('temporal_coherence', 0.0)
            if coherence > 0.8:
                insights.append("High temporal coherence indicates reliable and predictable system behavior")
            elif coherence < 0.4:
                insights.append("Low temporal coherence suggests chaotic or noisy system behavior")
            
            return insights[:7]  # Limit to top insights
            
        except Exception as e:
            logging.error(f"Error generating temporal insights: {str(e)}")
            return ["Unable to generate temporal insights due to analysis error"]
    
    # Utility methods for temporal analysis
    def _calculate_autocorrelation(self, values: List[float], lag: int) -> float:
        try:
            if lag >= len(values) or lag <= 0:
                return 0.0
            corr = np.corrcoef(values[:-lag], values[lag:])[0, 1]
            return corr if not np.isnan(corr) else 0.0
        except:
            return 0.0
    
    def _apply_highpass_filter(self, values: List[float]) -> List[float]:
        """
        Advanced high-pass filter with multiple methods:
        - Butterworth IIR filters for smooth frequency response
        - Chebyshev filters for sharper cutoffs
        - FIR windowing methods for linear phase response
        - Wavelet-based high-pass filtering
        - Adaptive cutoff frequency selection
        """
        try:
            from scipy import signal
            from scipy.fft import fft, ifft, fftfreq
            
            if len(values) < 4:
                return values
                
            data = np.array(values, dtype=np.float64)
            n = len(data)
            
            # Remove DC component first
            data_centered = data - np.mean(data)
            
            # Adaptive cutoff frequency selection
            cutoff_freq = self._determine_optimal_highpass_cutoff(data_centered)
            
            # Determine sampling frequency
            fs = max(100, n)  # Assume reasonable sampling rate
            nyquist = fs / 2.0
            normalized_cutoff = min(0.45, max(0.01, cutoff_freq / nyquist))
            
            # Select filtering method based on signal characteristics
            if n >= 1000:
                # Use Butterworth filter for long signals - smooth response
                try:
                    sos = signal.butter(6, normalized_cutoff, btype='high', output='sos')
                    filtered = signal.sosfiltfilt(sos, data_centered)
                except:
                    # Fallback to Chebyshev
                    sos = signal.cheby1(5, 1, normalized_cutoff, btype='high', output='sos')
                    filtered = signal.sosfiltfilt(sos, data_centered)
                    
            elif n >= 200:
                # Use windowed FIR filter for medium signals - linear phase
                try:
                    # Design FIR high-pass filter
                    numtaps = min(101, n // 4)  # Filter order
                    if numtaps % 2 == 0:
                        numtaps += 1  # Ensure odd for high-pass
                    
                    # Use Kaiser window for good stopband attenuation
                    fir_coeffs = signal.firwin(numtaps, normalized_cutoff, 
                                             window=('kaiser', 8.0), 
                                             pass_zero='highpass')
                    
                    # Apply zero-phase filtering
                    filtered = signal.filtfilt(fir_coeffs, 1, data_centered)
                except:
                    # Fallback to simple Butterworth
                    sos = signal.butter(4, normalized_cutoff, btype='high', output='sos')
                    filtered = signal.sosfiltfilt(sos, data_centered)
                    
            else:
                # Use frequency domain filtering for short signals
                filtered = self._frequency_domain_highpass(data_centered, normalized_cutoff)
            
            # Post-processing enhancements
            filtered = self._enhance_highpass_output(filtered, data_centered, cutoff_freq)
            
            return filtered.tolist()
            
        except Exception as e:
            # Advanced fallback with multiple stages
            try:
                data = np.array(values, dtype=np.float64)
                
                # Stage 1: Remove trend
                detrended = self._robust_detrend(data)
                
                # Stage 2: Adaptive differentiation
                if len(data) > 10:
                    # Use central differences for interior points
                    diff_filtered = np.zeros_like(detrended)
                    diff_filtered[0] = detrended[1] - detrended[0]
                    diff_filtered[-1] = detrended[-1] - detrended[-2]
                    diff_filtered[1:-1] = (detrended[2:] - detrended[:-2]) / 2.0
                    
                    # Apply smoothing to reduce noise amplification
                    window_size = max(3, len(data) // 20)
                    smoothed = self._apply_moving_average(diff_filtered.tolist(), window_size)
                    return smoothed
                else:
                    # Simple difference for very short signals
                    return np.diff(data, prepend=data[0]).tolist()
                    
            except:
                # Ultimate fallback
                return np.diff(values, prepend=values[0]).tolist()

    def _determine_optimal_highpass_cutoff(self, data: np.ndarray) -> float:
        """Determine optimal high-pass cutoff frequency based on signal characteristics."""
        try:
            n = len(data)
            
            # Method 1: Spectral analysis
            fft_data = np.abs(fft(data))
            freqs = fftfreq(n)[:n//2]
            power_spectrum = fft_data[:n//2]
            
            # Find spectral centroid
            if np.sum(power_spectrum) > 0:
                spectral_centroid = np.sum(freqs * power_spectrum) / np.sum(power_spectrum)
            else:
                spectral_centroid = 0.1
            
            # Method 2: Signal variability analysis
            signal_std = np.std(data)
            high_freq_content = np.std(np.diff(data))
            
            variability_ratio = high_freq_content / (signal_std + 1e-10)
            
            # Method 3: Autocorrelation-based estimation
            max_lag = min(50, n // 4)
            autocorr_decay = 0.5  # Default
            
            for lag in range(1, max_lag):
                if lag < n:
                    corr = self._calculate_autocorrelation(data.tolist(), lag)
                    if corr < 0.5:
                        autocorr_decay = lag / n
                        break
            
            # Combine methods for robust cutoff estimation
            cutoff_estimates = [
                spectral_centroid * 0.1,  # Conservative based on spectral centroid
                min(0.3, variability_ratio * 0.5),  # Based on signal variability
                min(0.2, autocorr_decay * 2),  # Based on correlation decay
            ]
            
            # Robust average (exclude outliers)
            cutoff_estimates = [c for c in cutoff_estimates if 0.001 <= c <= 0.5]
            if cutoff_estimates:
                optimal_cutoff = np.median(cutoff_estimates)
            else:
                optimal_cutoff = 0.05  # Safe default
                
            return max(0.005, min(0.4, optimal_cutoff))
            
        except:
            return 0.05  # Safe default
    
    def _frequency_domain_highpass(self, data: np.ndarray, normalized_cutoff: float) -> np.ndarray:
        """Frequency domain high-pass filtering with windowing."""
        try:
            n = len(data)
            
            # FFT of the signal
            fft_data = fft(data)
            freqs = fftfreq(n)
            
            # Create high-pass mask with smooth transition
            mask = np.ones(n, dtype=complex)
            transition_width = 0.02  # 2% of Nyquist frequency
            
            for i, freq in enumerate(freqs):
                abs_freq = abs(freq)
                if abs_freq < normalized_cutoff - transition_width:
                    mask[i] = 0.0
                elif abs_freq < normalized_cutoff + transition_width:
                    # Smooth transition using Tukey-like window
                    transition_pos = (abs_freq - (normalized_cutoff - transition_width)) / (2 * transition_width)
                    mask[i] = 0.5 * (1 + np.cos(np.pi * (1 - transition_pos)))
            
            # Apply filter and inverse transform
            filtered_fft = fft_data * mask
            filtered = np.real(ifft(filtered_fft))
            
            return filtered
            
        except:
            # Simple frequency cutoff fallback
            fft_data = np.fft.fft(data)
            freqs = np.fft.fftfreq(len(data))
            mask = np.abs(freqs) > normalized_cutoff
            return np.real(np.fft.ifft(fft_data * mask))
    
    def _enhance_highpass_output(self, filtered: np.ndarray, original: np.ndarray, 
                                cutoff_freq: float) -> np.ndarray:
        """Post-processing enhancements for high-pass filtered output."""
        try:
            # Noise reduction using adaptive smoothing
            noise_level = self._estimate_noise_level(filtered)
            
            if noise_level > np.std(original) * 0.1:  # Significant noise present
                # Apply light smoothing to high-frequency noise
                smoothing_window = max(3, int(5 / cutoff_freq))
                smoothed = self._adaptive_smoothing(filtered, smoothing_window, noise_level)
                filtered = smoothed
            
            # Edge artifact removal
            edge_length = min(10, len(filtered) // 20)
            if edge_length > 0:
                # Taper edges using cosine window
                taper = np.ones(len(filtered))
                taper_window = np.cos(np.linspace(np.pi, 0, edge_length))
                taper[:edge_length] *= taper_window
                taper[-edge_length:] *= taper_window[::-1]
                filtered *= taper
            
            # Amplitude correction to preserve signal characteristics
            filtered_std = np.std(filtered)
            original_std = np.std(original)
            
            if filtered_std > 0 and original_std > 0:
                # Conservative amplitude scaling
                scale_factor = min(2.0, original_std / filtered_std * 0.8)
                filtered *= scale_factor
            
            return filtered
            
        except:
            return filtered
    
    def _robust_detrend(self, data: np.ndarray) -> np.ndarray:
        """Robust detrending using multiple methods."""
        try:
            n = len(data)
            x = np.arange(n)
            
            # Method 1: Polynomial detrending (robust to outliers)
            if n > 10:
                # Use median-based robust regression
                coeffs = self._robust_polyfit(x, data, degree=min(2, n // 20))
                trend = np.polyval(coeffs, x)
                detrended = data - trend
            else:
                detrended = data - np.mean(data)
            
            # Method 2: Additional median filtering if needed
            if np.std(detrended) > 2 * np.std(data):
                # Original detrending was too aggressive
                detrended = data - np.median(data)
            
            return detrended
            
        except:
            return data - np.mean(data)
    
    def _robust_polyfit(self, x: np.ndarray, y: np.ndarray, degree: int) -> np.ndarray:
        """Robust polynomial fitting using iterative reweighting."""
        try:
            # Initial fit
            coeffs = np.polyfit(x, y, degree)
            
            for _ in range(3):  # Iterative refinement
                fitted = np.polyval(coeffs, x)
                residuals = y - fitted
                
                # Weight based on residuals (Huber-like)
                mad = np.median(np.abs(residuals - np.median(residuals)))
                if mad == 0:
                    break
                    
                weights = np.minimum(1.0, 1.35 * mad / (np.abs(residuals) + 1e-10))
                
                # Weighted least squares
                W = np.diag(weights)
                X = np.vander(x, degree + 1)
                coeffs = np.linalg.solve(X.T @ W @ X, X.T @ W @ y)
            
            return coeffs
            
        except:
            return np.polyfit(x, y, degree)
    
    def _estimate_noise_level(self, signal: np.ndarray) -> float:
        """Estimate noise level in the signal using robust methods."""
        try:
            # Method 1: High-frequency content analysis
            high_freq = np.diff(signal, n=2)  # Second difference
            noise_est1 = np.std(high_freq) / np.sqrt(6)  # Normalized estimate
            
            # Method 2: Median absolute deviation of residuals
            median_signal = np.median(signal)
            mad_noise = np.median(np.abs(signal - median_signal))
            noise_est2 = mad_noise * 1.4826  # Convert MAD to std equivalent
            
            # Combine estimates
            return min(noise_est1, noise_est2)
            
        except:
            return np.std(signal) * 0.1  # Conservative fallback
    
    def _adaptive_smoothing(self, signal: np.ndarray, window_size: int, 
                           noise_level: float) -> np.ndarray:
        """Adaptive smoothing based on local signal characteristics."""
        try:
            n = len(signal)
            smoothed = signal.copy()
            
            for i in range(n):
                # Define adaptive window
                local_window = min(window_size, max(3, int(window_size * (1 + noise_level))))
                start = max(0, i - local_window // 2)
                end = min(n, i + local_window // 2 + 1)
                
                # Local statistics
                local_data = signal[start:end]
                local_std = np.std(local_data)
                
                # Adaptive smoothing strength
                if local_std > noise_level * 2:
                    # High variability - light smoothing
                    smoothed[i] = signal[i] * 0.8 + np.mean(local_data) * 0.2
                else:
                    # Low variability - more smoothing
                    smoothed[i] = signal[i] * 0.5 + np.mean(local_data) * 0.5
            
            return smoothed
            
        except:
            return signal
    
    def _apply_bandpass_filter(self, values: List[float], low_freq: float, high_freq: float) -> List[float]:
        """
        Advanced bandpass filter using multiple methods with automatic selection
        based on signal characteristics and filter requirements.
        """
        try:
            from scipy import signal
            from scipy.fft import fft, ifft, fftfreq
            
            if len(values) < 4:
                return values
                
            data = np.array(values, dtype=np.float64)
            
            # Determine sampling frequency (assume normalized or use length-based estimate)
            fs = len(data) if len(data) > 100 else 100.0
            nyquist = fs / 2.0
            
            # Normalize frequencies to Nyquist frequency
            low_norm = max(0.001, min(low_freq / nyquist, 0.99))
            high_norm = max(low_norm + 0.001, min(high_freq / nyquist, 0.99))
            
            # Select filter method based on signal characteristics
            signal_length = len(data)
            freq_ratio = high_norm / low_norm if low_norm > 0 else float('inf')
            
            if signal_length > 1000 and freq_ratio > 10:
                # Use Butterworth filter for long signals with wide bands
                sos = signal.butter(6, [low_norm, high_norm], btype='band', output='sos')
                filtered = signal.sosfiltfilt(sos, data)
            elif signal_length > 500:
                # Use Chebyshev Type I filter for medium signals
                sos = signal.cheby1(5, 1, [low_norm, high_norm], btype='band', output='sos')
                filtered = signal.sosfiltfilt(sos, data)
            else:
                # Use FFT-based filtering for short signals
                fft_data = fft(data)
                freqs = fftfreq(len(data), 1/fs)
                
                # Create frequency mask
                mask = np.zeros(len(freqs), dtype=bool)
                mask |= (np.abs(freqs) >= low_freq) & (np.abs(freqs) <= high_freq)
                
                # Apply Tukey window for smooth transitions
                window_size = max(1, len(freqs) // 50)
                tukey_window = signal.windows.tukey(2 * window_size, alpha=0.25)
                
                # Smooth the mask edges
                for i in range(len(mask)):
                    if mask[i]:
                        start_idx = max(0, i - window_size)
                        end_idx = min(len(mask), i + window_size + 1)
                        if start_idx < i:
                            tukey_start = max(0, window_size - (i - start_idx))
                            mask[start_idx:i] = tukey_window[tukey_start:window_size]
                        if i + 1 < end_idx:
                            tukey_end = min(len(tukey_window), window_size + (end_idx - i - 1))
                            mask[i+1:end_idx] = tukey_window[window_size:tukey_end]
                
                # Apply filter
                fft_filtered = fft_data * mask
                filtered = np.real(ifft(fft_filtered))
            
            # Post-processing: Remove DC component and normalize
            filtered = filtered - np.mean(filtered)
            
            # Adaptive gain control to preserve signal energy
            original_energy = np.sum(data**2)
            filtered_energy = np.sum(filtered**2)
            
            if filtered_energy > 0 and original_energy > 0:
                energy_ratio = np.sqrt(original_energy / filtered_energy)
                filtered *= min(energy_ratio, 2.0)  # Limit amplification
            
            return filtered.tolist()
            
        except Exception as e:
            # Fallback: Simple frequency domain filtering
            try:
                data = np.array(values, dtype=np.float64)
                fft_data = np.fft.fft(data)
                freqs = np.fft.fftfreq(len(data))
                
                # Normalized frequency filtering
                freq_mask = (np.abs(freqs) >= low_freq/100) & (np.abs(freqs) <= high_freq/100)
                fft_filtered = fft_data * freq_mask
                
                filtered = np.real(np.fft.ifft(fft_filtered))
                return filtered.tolist()
            except:
                return values
    
    def _apply_moving_average(self, values: List[float], window: int) -> List[float]:
        """
        Advanced moving average with adaptive windowing and multiple methods:
        - Exponentially Weighted Moving Average (EWMA) for trend following
        - Gaussian-weighted moving averages for smooth filtering
        - Adaptive window sizing based on local signal characteristics
        - Hull Moving Average for reduced lag
        - Triangular and other shaped kernels for optimized response
        """
        try:
            if len(values) < 2:
                return values
                
            data = np.array(values, dtype=np.float64)
            n = len(data)
            
            # Adaptive window size optimization
            optimal_window = self._optimize_moving_average_window(data, window)
            
            # Signal analysis for method selection
            signal_characteristics = self._analyze_signal_for_ma(data)
            ma_method = self._select_optimal_ma_method(signal_characteristics, optimal_window)
            
            # Apply selected moving average method
            if ma_method == 'ewma':
                filtered = self._exponential_weighted_ma(data, optimal_window)
            elif ma_method == 'gaussian':
                filtered = self._gaussian_weighted_ma(data, optimal_window)
            elif ma_method == 'hull':
                filtered = self._hull_moving_average(data, optimal_window)
            elif ma_method == 'triangular':
                filtered = self._triangular_weighted_ma(data, optimal_window)
            elif ma_method == 'adaptive':
                filtered = self._fully_adaptive_ma(data)
            else:
                # Enhanced simple moving average with edge handling
                filtered = self._enhanced_simple_ma(data, optimal_window)
            
            # Post-processing for quality control
            filtered = self._ma_post_processing(filtered, data, signal_characteristics)
            
            return filtered.tolist()
            
        except Exception as e:
            # Multi-level fallback system
            try:
                data = np.array(values, dtype=np.float64)
                n = len(data)
                
                # Ensure valid window size
                safe_window = max(1, min(window, n))
                if safe_window >= n:
                    return values
                    
                # Stage 1: Enhanced convolution with edge handling
                if safe_window > 1:
                    # Create symmetric kernel
                    kernel = np.ones(safe_window) / safe_window
                    
                    # Apply convolution with proper edge handling
                    padded_data = np.pad(data, (safe_window//2, safe_window//2), mode='edge')
                    filtered = np.convolve(padded_data, kernel, mode='valid')
                    
                    # Ensure correct length
                    if len(filtered) != n:
                        filtered = np.convolve(data, kernel, mode='same')
                    
                    return filtered.tolist()
                else:
                    return values
                    
            except:
                # Final fallback - basic implementation
                try:
                    if window <= 1 or window >= len(values):
                        return values
                    filtered = np.convolve(values, np.ones(window)/window, mode='same')
                    return filtered.tolist()
                except:
                    return values

    def _optimize_moving_average_window(self, data: np.ndarray, initial_window: int) -> int:
        """Optimize moving average window size based on signal characteristics."""
        try:
            n = len(data)
            
            # Constraints
            min_window = max(3, min(initial_window, n // 10))
            max_window = min(initial_window * 2, n // 3)
            
            # Signal analysis
            signal_variance = np.var(data)
            noise_level = self._estimate_noise_in_signal(data)
            
            # Autocorrelation-based window selection
            optimal_from_autocorr = self._window_from_autocorrelation(data)
            
            # Spectral analysis for optimal smoothing
            optimal_from_spectrum = self._window_from_spectrum(data)
            
            # Combine methods
            candidates = [
                initial_window,
                optimal_from_autocorr,
                optimal_from_spectrum,
                max(5, int(np.sqrt(n))),  # Square root of length
                max(3, n // 20)           # 5% of signal length
            ]
            
            # Filter valid candidates
            valid_candidates = [c for c in candidates if min_window <= c <= max_window]
            
            if valid_candidates:
                # Select based on signal characteristics
                if noise_level > 0.5:
                    # Noisy signals need larger windows
                    optimal_window = max(valid_candidates)
                elif noise_level < 0.1:
                    # Clean signals can use smaller windows
                    optimal_window = min(valid_candidates)
                else:
                    # Balanced approach
                    optimal_window = int(np.median(valid_candidates))
            else:
                optimal_window = initial_window
            
            return max(min_window, min(optimal_window, max_window))
            
        except:
            return max(3, min(initial_window, len(data) // 3))
    
    def _analyze_signal_for_ma(self, data: np.ndarray) -> Dict[str, float]:
        """Analyze signal characteristics for moving average method selection."""
        try:
            n = len(data)
            
            # Trend analysis
            x = np.arange(n)
            trend_slope = np.corrcoef(x, data)[0, 1] if n > 1 else 0
            trend_strength = abs(trend_slope)
            
            # Volatility analysis
            returns = np.diff(data) / (np.abs(data[:-1]) + 1e-10)
            volatility = np.std(returns) if len(returns) > 0 else 0
            
            # Smoothness analysis
            second_diff = np.diff(data, n=2)
            smoothness = 1.0 / (1.0 + np.std(second_diff) / (np.std(data) + 1e-10))
            
            # Noise estimation
            noise_level = self._estimate_noise_in_signal(data)
            
            # Cyclical patterns
            has_cycles = self._detect_cyclical_patterns(data)
            
            return {
                'trend_strength': min(1.0, trend_strength),
                'volatility': min(1.0, volatility),
                'smoothness': max(0.0, min(1.0, smoothness)),
                'noise_level': min(1.0, noise_level),
                'has_cycles': has_cycles,
                'signal_length': n
            }
            
        except:
            return {
                'trend_strength': 0.3,
                'volatility': 0.3,
                'smoothness': 0.5,
                'noise_level': 0.2,
                'has_cycles': False,
                'signal_length': len(data)
            }
    
    def _select_optimal_ma_method(self, characteristics: Dict[str, float], window: int) -> str:
        """Select optimal moving average method based on signal characteristics."""
        try:
            trend = characteristics['trend_strength']
            volatility = characteristics['volatility']
            smoothness = characteristics['smoothness']
            noise = characteristics['noise_level']
            has_cycles = characteristics['has_cycles']
            length = characteristics['signal_length']
            
            # Method selection logic
            if trend > 0.7 and volatility < 0.3:
                return 'ewma'  # Strong trend, low volatility
            elif noise > 0.6:
                return 'gaussian'  # High noise
            elif smoothness < 0.3 or has_cycles:
                return 'hull'  # Non-smooth or cyclical
            elif volatility > 0.5:
                return 'triangular'  # High volatility
            elif length >= 50:
                return 'adaptive'  # Long signals
            else:
                return 'simple'  # Default
                
        except:
            return 'simple'
    
    def _exponential_weighted_ma(self, data: np.ndarray, window: int) -> np.ndarray:
        """Exponentially Weighted Moving Average for trend following."""
        try:
            alpha = 2.0 / (window + 1)  # Smoothing factor
            ewma = np.zeros_like(data)
            ewma[0] = data[0]
            
            for i in range(1, len(data)):
                ewma[i] = alpha * data[i] + (1 - alpha) * ewma[i-1]
            
            return ewma
            
        except:
            return data
    
    def _gaussian_weighted_ma(self, data: np.ndarray, window: int) -> np.ndarray:
        """Gaussian-weighted moving average for smooth filtering."""
        try:
            # Create Gaussian kernel
            sigma = window / 6.0  # 3-sigma rule
            kernel_size = window
            
            x = np.arange(kernel_size) - (kernel_size - 1) / 2
            kernel = np.exp(-x**2 / (2 * sigma**2))
            kernel /= np.sum(kernel)
            
            # Apply convolution with edge handling
            half_kernel = kernel_size // 2
            padded_data = np.pad(data, half_kernel, mode='edge')
            filtered = np.convolve(padded_data, kernel, mode='valid')
            
            return filtered
            
        except:
            return self._enhanced_simple_ma(data, window)
    
    def _hull_moving_average(self, data: np.ndarray, window: int) -> np.ndarray:
        """Hull Moving Average for reduced lag."""
        try:
            n = len(data)
            half_window = max(1, window // 2)
            sqrt_window = max(1, int(np.sqrt(window)))
            
            # Step 1: Calculate WMA with half period
            wma_half = self._weighted_ma(data, half_window)
            
            # Step 2: Calculate WMA with full period
            wma_full = self._weighted_ma(data, window)
            
            # Step 3: Calculate 2*WMA(half) - WMA(full)
            hull_raw = 2 * wma_half - wma_full
            
            # Step 4: Apply WMA to the result with sqrt(window) period
            hull_ma = self._weighted_ma(hull_raw, sqrt_window)
            
            return hull_ma
            
        except:
            return self._enhanced_simple_ma(data, window)
    
    def _triangular_weighted_ma(self, data: np.ndarray, window: int) -> np.ndarray:
        """Triangular-weighted moving average."""
        try:
            # Create triangular kernel
            if window % 2 == 1:
                # Odd window size
                peak = window // 2
                kernel = np.concatenate([
                    np.arange(1, peak + 2),
                    np.arange(peak, 0, -1)
                ])
            else:
                # Even window size
                peak = window // 2
                kernel = np.concatenate([
                    np.arange(1, peak + 1),
                    np.arange(peak, 0, -1)
                ])
            
            kernel = kernel.astype(float)
            kernel /= np.sum(kernel)
            
            # Apply convolution
            filtered = np.convolve(data, kernel, mode='same')
            
            return filtered
            
        except:
            return self._enhanced_simple_ma(data, window)
    
    def _fully_adaptive_ma(self, data: np.ndarray) -> np.ndarray:
        """Fully adaptive moving average with dynamic window sizing."""
        try:
            n = len(data)
            filtered = np.zeros_like(data)
            
            for i in range(n):
                # Calculate local characteristics
                start_idx = max(0, i - 10)
                end_idx = min(n, i + 11)
                local_data = data[start_idx:end_idx]
                
                # Local volatility
                local_vol = np.std(local_data) if len(local_data) > 1 else 0
                
                # Adaptive window size (inverse relationship with volatility)
                base_window = max(3, n // 30)
                adaptive_window = max(3, int(base_window / (1 + local_vol)))
                adaptive_window = min(adaptive_window, n // 5)  # Upper bound
                
                # Apply moving average with adaptive window
                ma_start = max(0, i - adaptive_window // 2)
                ma_end = min(n, i + adaptive_window // 2 + 1)
                
                # Weight recent observations more heavily
                window_data = data[ma_start:ma_end]
                weights = np.exp(-0.1 * np.abs(np.arange(len(window_data)) - len(window_data) // 2))
                weights /= np.sum(weights)
                
                filtered[i] = np.sum(window_data * weights)
            
            return filtered
            
        except:
            return data
    
    def _enhanced_simple_ma(self, data: np.ndarray, window: int) -> np.ndarray:
        """Enhanced simple moving average with better edge handling."""
        try:
            n = len(data)
            filtered = np.zeros_like(data)
            
            for i in range(n):
                # Adaptive window at edges
                start_idx = max(0, i - window // 2)
                end_idx = min(n, i + window // 2 + 1)
                
                # Ensure minimum window size
                if end_idx - start_idx < 3:
                    if i < n // 2:
                        end_idx = min(n, start_idx + 3)
                    else:
                        start_idx = max(0, end_idx - 3)
                
                filtered[i] = np.mean(data[start_idx:end_idx])
            
            return filtered
            
        except:
            return np.convolve(data, np.ones(window)/window, mode='same')
    
    def _weighted_ma(self, data: np.ndarray, window: int) -> np.ndarray:
        """Linearly weighted moving average."""
        try:
            n = len(data)
            weights = np.arange(1, window + 1, dtype=float)
            weights /= np.sum(weights)
            
            filtered = np.zeros_like(data)
            
            for i in range(n):
                start_idx = max(0, i - window + 1)
                end_idx = i + 1
                
                if end_idx - start_idx < window:
                    # Adjust weights for edge cases
                    actual_window = end_idx - start_idx
                    adjusted_weights = weights[-actual_window:]
                    adjusted_weights /= np.sum(adjusted_weights)
                    filtered[i] = np.sum(data[start_idx:end_idx] * adjusted_weights)
                else:
                    filtered[i] = np.sum(data[start_idx:end_idx] * weights)
            
            return filtered
            
        except:
            return data
    
    def _ma_post_processing(self, filtered: np.ndarray, original: np.ndarray, 
                           characteristics: Dict[str, float]) -> np.ndarray:
        """Post-processing for moving average results."""
        try:
            # Preserve original signal characteristics
            original_mean = np.mean(original)
            filtered_mean = np.mean(filtered)
            
            # Adjust DC component
            filtered = filtered - filtered_mean + original_mean
            
            # Amplitude correction based on smoothness requirements
            smoothness = characteristics.get('smoothness', 0.5)
            noise_level = characteristics.get('noise_level', 0.2)
            
            if smoothness < 0.3:  # Preserve more original signal for non-smooth data
                blend_factor = 0.3
                filtered = (1 - blend_factor) * filtered + blend_factor * original
            
            # Edge enhancement if needed
            edge_factor = min(0.2, noise_level)
            if edge_factor > 0:
                edge_enhanced = self._enhance_edges(filtered, original, edge_factor)
                filtered = edge_enhanced
            
            return filtered
            
        except:
            return filtered
    
    # Helper methods for moving average optimization
    def _window_from_autocorrelation(self, data: np.ndarray) -> int:
        """Advanced autocorrelation-based window optimization with multi-scale analysis."""
        try:
            from scipy import signal
            from scipy.stats import entropy
            import numpy as np
            
            n = len(data)
            if n < 10:
                return max(3, n // 3)
            
            # Normalize data
            data_norm = (data - np.mean(data)) / (np.std(data) + 1e-10)
            
            # Multi-scale autocorrelation analysis
            max_lag = min(n // 2, 100)
            autocorr_full = np.correlate(data_norm, data_norm, mode='full')
            autocorr = autocorr_full[autocorr_full.size // 2:]
            autocorr = autocorr[:max_lag] / autocorr[0]  # Normalize
            
            # Advanced independence detection using multiple criteria
            independence_metrics = {}
            
            # 1. Exponential decay detection
            decay_candidates = []
            for lag in range(2, min(max_lag, 30)):
                if lag < len(autocorr):
                    if autocorr[lag] < np.exp(-lag / 10):  # Exponential threshold
                        decay_candidates.append(lag)
            
            # 2. Local minima detection with significance testing
            local_minima = signal.argrelmin(np.abs(autocorr), order=2)[0]
            significant_minima = []
            for minimum in local_minima:
                if minimum > 2 and autocorr[minimum] < 0.2:
                    # Statistical significance test
                    confidence_bound = 1.96 / np.sqrt(n)  # 95% confidence
                    if abs(autocorr[minimum]) < confidence_bound:
                        significant_minima.append(minimum)
            
            # 3. Entropy-based complexity analysis
            entropy_window = None
            if len(autocorr) > 10:
                window_entropies = []
                for w in range(3, min(max_lag // 2, 25)):
                    if w < len(autocorr):
                        segment_autocorr = np.abs(autocorr[:w])
                        segment_autocorr = segment_autocorr / np.sum(segment_autocorr + 1e-10)
                        ent = entropy(segment_autocorr + 1e-10)
                        window_entropies.append((w, ent))
                
                if window_entropies:
                    # Find window where entropy stabilizes
                    entropies = [e[1] for e in window_entropies]
                    if len(entropies) > 5:
                        entropy_diff = np.diff(entropies)
                        stable_idx = np.where(np.abs(entropy_diff) < 0.1 * np.std(entropy_diff))[0]
                        if len(stable_idx) > 0:
                            entropy_window = window_entropies[stable_idx[0]][0]
            
            # 4. Spectral analysis for periodic structure detection
            spectral_window = None
            if len(autocorr) > 8:
                # FFT of autocorrelation to detect periodicities
                autocorr_fft = np.abs(np.fft.fft(autocorr))
                freqs = np.fft.fftfreq(len(autocorr))
                
                # Find dominant frequency excluding DC
                dominant_freq_idx = np.argmax(autocorr_fft[1:len(autocorr_fft)//2]) + 1
                dominant_freq = abs(freqs[dominant_freq_idx])
                
                if dominant_freq > 0:
                    period = 1.0 / dominant_freq
                    spectral_window = max(3, int(period / 3))
            
            # Multi-criteria decision fusion
            candidates = []
            
            if decay_candidates:
                candidates.extend(decay_candidates[:2])  # Take first two decay points
            
            if significant_minima:
                candidates.extend(significant_minima[:2])  # Take first two minima
            
            if entropy_window and entropy_window > 2:
                candidates.append(entropy_window)
            
            if spectral_window and spectral_window > 2:
                candidates.append(spectral_window)
            
            # Weighted selection based on signal characteristics
            if candidates:
                candidates = list(set(candidates))  # Remove duplicates
                candidates.sort()
                
                # Weight selection based on data properties
                snr = np.mean(data) / (np.std(data) + 1e-10)
                trend_strength = abs(np.corrcoef(np.arange(n), data)[0, 1])
                
                if snr > 2.0 and trend_strength < 0.3:  # High SNR, low trend
                    # Prefer smaller windows for clean data
                    optimal_window = min(candidates)
                elif trend_strength > 0.7:  # Strong trend
                    # Prefer larger windows for trending data
                    optimal_window = max(candidates)
                else:
                    # Use median for balanced approach
                    optimal_window = int(np.median(candidates))
                
                return min(max(3, optimal_window), n // 4)
            
            # Fallback: Adaptive default based on data characteristics
            stationarity_metric = np.std(np.diff(data)) / (np.std(data) + 1e-10)
            if stationarity_metric < 0.1:  # Very stationary
                return max(3, n // 8)
            elif stationarity_metric > 0.5:  # Non-stationary
                return max(3, n // 15)
            else:
                return max(3, n // 10)
                
        except Exception as e:
            # Robust fallback with data-driven estimation
            try:
                n = len(data)
                if n < 10:
                    return 3
                
                # Simple variance-based estimation
                variance_window = max(3, int(n * 0.1))
                return min(variance_window, n // 3)
            except:
                return max(3, len(data) // 10)
    
    def _window_from_spectrum(self, data: np.ndarray) -> int:
        """Advanced spectral analysis for optimal window determination with multi-resolution analysis."""
        try:
            from scipy.fft import fft, fftfreq
            from scipy import signal
            from scipy.signal import welch, spectrogram
            from scipy.stats import entropy
            import numpy as np
            
            n = len(data)
            if n < 12:
                return max(3, n // 3)
            
            # Preprocess data
            data_detrended = signal.detrend(data, type='linear')
            data_windowed = data_detrended * signal.windows.hann(len(data_detrended))
            
            # Multi-resolution spectral analysis
            spectral_metrics = {}
            
            # 1. High-resolution FFT analysis
            if n >= 32:
                # Zero-pad for higher frequency resolution
                nfft = max(512, 2**int(np.ceil(np.log2(n))))
                fft_data = np.abs(fft(data_windowed, n=nfft))
                freqs = fftfreq(nfft, d=1.0)[:nfft//2]
                power = fft_data[:nfft//2]
                
                # Normalize power spectrum
                power = power / np.sum(power)
                
                # Advanced peak detection with statistical significance
                from scipy.signal import find_peaks
                
                # Find significant peaks
                peak_threshold = np.mean(power) + 2 * np.std(power)
                peaks, peak_properties = find_peaks(
                    power[1:],  # Skip DC
                    height=peak_threshold,
                    distance=max(1, nfft // 100),
                    prominence=np.std(power)
                )
                peaks += 1  # Adjust for skipped DC
                
                # Analyze peak characteristics
                if len(peaks) > 0:
                    # Get dominant frequencies with their strengths
                    peak_freqs = freqs[peaks]
                    peak_powers = power[peaks]
                    
                    # Sort by power
                    sorted_indices = np.argsort(peak_powers)[::-1]
                    dominant_freqs = peak_freqs[sorted_indices]
                    dominant_powers = peak_powers[sorted_indices]
                    
                    spectral_metrics['dominant_freqs'] = dominant_freqs[:5]  # Top 5
                    spectral_metrics['dominant_powers'] = dominant_powers[:5]
            
            # 2. Welch's method for robust PSD estimation
            if n >= 16:
                nperseg = min(n // 4, 64)
                f_welch, psd_welch = welch(
                    data_detrended,
                    nperseg=nperseg,
                    noverlap=nperseg//2,
                    nfft=max(nperseg, 128),
                    window='hann'
                )
                
                # Normalize PSD
                psd_welch = psd_welch / np.sum(psd_welch)
                
                # Find spectral centroid and bandwidth
                spectral_centroid = np.sum(f_welch * psd_welch) / np.sum(psd_welch)
                spectral_variance = np.sum(((f_welch - spectral_centroid) ** 2) * psd_welch)
                spectral_bandwidth = np.sqrt(spectral_variance)
                
                spectral_metrics['centroid'] = spectral_centroid
                spectral_metrics['bandwidth'] = spectral_bandwidth
                
                # Spectral entropy for complexity assessment
                spectral_entropy = entropy(psd_welch + 1e-10)
                spectral_metrics['entropy'] = spectral_entropy
            
            # 3. Time-frequency analysis using spectrogram
            if n >= 32:
                f_spec, t_spec, Sxx = spectrogram(
                    data_detrended,
                    nperseg=min(n // 8, 32),
                    noverlap=None,
                    nfft=64
                )
                
                # Analyze spectral stability over time
                freq_stability = np.std(Sxx, axis=1) / (np.mean(Sxx, axis=1) + 1e-10)
                stable_freq_indices = np.where(freq_stability < np.median(freq_stability))[0]
                
                if len(stable_freq_indices) > 0:
                    stable_freqs = f_spec[stable_freq_indices]
                    spectral_metrics['stable_freqs'] = stable_freqs
            
            # Window size determination based on spectral characteristics
            window_candidates = []
            
            # Method 1: Dominant frequency approach
            if 'dominant_freqs' in spectral_metrics:
                for i, freq in enumerate(spectral_metrics['dominant_freqs'][:3]):
                    if freq > 0:
                        period = 1.0 / freq
                        power_weight = spectral_metrics['dominant_powers'][i]
                        
                        # Adaptive window sizing based on frequency strength
                        if power_weight > 0.1:  # Strong frequency component
                            window = max(3, int(period / 3))
                        else:  # Weaker component
                            window = max(3, int(period / 5))
                        
                        window_candidates.append((window, power_weight))
            
            # Method 2: Spectral bandwidth approach
            if 'bandwidth' in spectral_metrics and 'centroid' in spectral_metrics:
                centroid = spectral_metrics['centroid']
                bandwidth = spectral_metrics['bandwidth']
                
                if centroid > 0:
                    # Window inversely related to spectral concentration
                    concentration_factor = bandwidth / (centroid + 1e-10)
                    if concentration_factor < 0.5:  # Concentrated spectrum
                        window = max(3, int(n / (10 * centroid)))
                    else:  # Broad spectrum
                        window = max(3, int(n / (15 * centroid)))
                    
                    window_candidates.append((window, 1.0 / (concentration_factor + 1e-10)))
            
            # Method 3: Entropy-based approach
            if 'entropy' in spectral_metrics:
                entropy_val = spectral_metrics['entropy']
                
                # High entropy (white noise-like) -> smaller windows
                # Low entropy (tonal) -> larger windows
                normalized_entropy = entropy_val / np.log(len(freqs) if 'freqs' in locals() else 10)
                
                if normalized_entropy > 0.8:  # High entropy
                    entropy_window = max(3, n // 20)
                elif normalized_entropy < 0.3:  # Low entropy
                    entropy_window = max(3, n // 8)
                else:
                    entropy_window = max(3, n // 12)
                
                window_candidates.append((entropy_window, 1.0 - normalized_entropy))
            
            # Method 4: Stable frequency approach
            if 'stable_freqs' in spectral_metrics:
                for freq in spectral_metrics['stable_freqs'][:2]:
                    if freq > 0:
                        stable_period = 1.0 / freq
                        stable_window = max(3, int(stable_period / 2))
                        window_candidates.append((stable_window, 0.8))  # High weight for stability
            
            # Weighted decision fusion
            if window_candidates:
                # Remove outliers
                windows = [w[0] for w in window_candidates]
                weights = [w[1] for w in window_candidates]
                
                # Filter out extreme values
                median_window = np.median(windows)
                mad = np.median(np.abs(np.array(windows) - median_window))
                threshold = median_window + 3 * mad
                
                filtered_candidates = [
                    (w, wt) for w, wt in window_candidates 
                    if abs(w - median_window) <= threshold and w <= n // 3
                ]
                
                if filtered_candidates:
                    # Weighted average
                    total_weight = sum(wt for _, wt in filtered_candidates)
                    weighted_window = sum(w * wt for w, wt in filtered_candidates) / total_weight
                    optimal_window = max(3, int(weighted_window))
                    
                    return min(optimal_window, n // 3)
            
            # Fallback: Nyquist-based estimation
            if n >= 20:
                # Estimate characteristic frequency from data variations
                diff_data = np.diff(data)
                zero_crossings = np.where(np.diff(np.sign(diff_data)))[0]
                
                if len(zero_crossings) > 2:
                    avg_half_period = len(diff_data) / len(zero_crossings)
                    estimated_period = 2 * avg_half_period
                    fallback_window = max(3, int(estimated_period / 4))
                    return min(fallback_window, n // 5)
            
            return max(3, n // 10)
            
        except Exception as e:
            # Robust fallback with signal variance analysis
            try:
                n = len(data)
                if n < 6:
                    return 3
                
                # Estimate characteristic scale from data variability
                data_var = np.var(data)
                diff_var = np.var(np.diff(data))
                
                if diff_var > 0:
                    variability_ratio = data_var / diff_var
                    # High ratio indicates slower variations -> larger window
                    if variability_ratio > 10:
                        return max(3, min(n // 6, 20))
                    elif variability_ratio < 2:
                        return max(3, min(n // 15, 10))
                    else:
                        return max(3, min(n // 10, 15))
                
                return max(3, n // 10)
            except:
                return max(3, len(data) // 10)
    
    def _estimate_noise_in_signal(self, data: np.ndarray) -> float:
        """Advanced multi-method noise estimation with robust statistical analysis."""
        try:
            from scipy import signal, stats
            from scipy.signal import welch, medfilt
            from scipy.fft import fft
            import numpy as np
            
            n = len(data)
            if n < 4:
                return 0.2
            
            # Preprocess data
            data_clean = np.array(data, dtype=np.float64)
            data_clean = data_clean[~np.isnan(data_clean)]  # Remove NaN values
            
            if len(data_clean) < 4:
                return 0.2
            
            noise_estimates = []
            
            # Method 1: Multi-scale differential analysis
            try:
                # First-order differences (high-frequency noise)
                diff1 = np.diff(data_clean)
                noise1 = np.std(diff1) / (np.std(data_clean) + 1e-10)
                
                # Second-order differences (curvature-based noise)
                if len(data_clean) >= 3:
                    diff2 = np.diff(data_clean, n=2)
                    noise2 = np.std(diff2) / (np.std(data_clean) + 1e-10)
                    
                    # Combined differential estimate with weights
                    diff_noise = 0.7 * noise1 + 0.3 * noise2
                    noise_estimates.append(('differential', diff_noise, 0.3))
            except:
                pass
            
            # Method 2: Spectral analysis approach
            try:
                if len(data_clean) >= 16:
                    # High-frequency power analysis
                    nperseg = min(len(data_clean) // 4, 32)
                    f, psd = welch(data_clean, nperseg=nperseg, noverlap=nperseg//2)
                    
                    # Define noise band (upper frequency range)
                    noise_band_start = int(0.6 * len(f))
                    noise_power = np.mean(psd[noise_band_start:])
                    total_power = np.mean(psd)
                    
                    spectral_noise = noise_power / (total_power + 1e-10)
                    noise_estimates.append(('spectral', spectral_noise, 0.25))
                    
                    # Spectral flatness for noise assessment
                    geometric_mean = stats.gmean(psd + 1e-10)
                    arithmetic_mean = np.mean(psd)
                    spectral_flatness = geometric_mean / arithmetic_mean
                    
                    # High flatness indicates white noise
                    flatness_noise = min(1.0, spectral_flatness * 2)
                    noise_estimates.append(('flatness', flatness_noise, 0.2))
            except:
                pass
            
            # Method 3: Median absolute deviation (robust outlier detection)
            try:
                # MAD-based noise estimation
                median_data = np.median(data_clean)
                mad = np.median(np.abs(data_clean - median_data))
                std_data = np.std(data_clean)
                
                # MAD to standard deviation ratio for noise assessment
                if std_data > 0:
                    mad_ratio = mad / std_data
                    # For Gaussian data, MAD ≈ 0.6745 * std
                    # Deviation from this indicates non-Gaussian (potentially noisy) behavior
                    gaussian_mad_ratio = 0.6745
                    mad_noise = abs(mad_ratio - gaussian_mad_ratio) / gaussian_mad_ratio
                    noise_estimates.append(('mad', min(1.0, mad_noise), 0.25))
            except:
                pass
            
            # Method 4: Autocorrelation-based approach
            try:
                if len(data_clean) >= 8:
                    # Calculate autocorrelation
                    autocorr = np.correlate(data_clean, data_clean, mode='full')
                    autocorr = autocorr[autocorr.size // 2:]
                    autocorr = autocorr / autocorr[0]  # Normalize
                    
                    # Rapid decorrelation indicates noise
                    max_lag = min(len(autocorr) - 1, 10)
                    if max_lag > 1:
                        decorr_rate = -np.log(abs(autocorr[max_lag]) + 1e-10) / max_lag
                        autocorr_noise = min(1.0, decorr_rate / 2)
                        noise_estimates.append(('autocorr', autocorr_noise, 0.2))
            except:
                pass
            
            # Method 5: Wavelet-based denoising estimate
            try:
                if len(data_clean) >= 16:
                    # Simple wavelet-like analysis using differences at multiple scales
                    scales = [1, 2, 4]
                    scale_energies = []
                    
                    for scale in scales:
                        if scale < len(data_clean):
                            # Downsample and difference
                            downsampled = data_clean[::scale]
                            if len(downsampled) > 1:
                                diff_energy = np.var(np.diff(downsampled))
                                scale_energies.append(diff_energy)
                    
                    if len(scale_energies) >= 2:
                        # High-frequency energy proportion
                        total_energy = sum(scale_energies)
                        if total_energy > 0:
                            hf_proportion = scale_energies[0] / total_energy
                            wavelet_noise = min(1.0, hf_proportion * 2)
                            noise_estimates.append(('wavelet', wavelet_noise, 0.15))
            except:
                pass
            
            # Method 6: Statistical distribution analysis
            try:
                # Test for normality - noisy data often deviates from normality
                if len(data_clean) >= 8:
                    # Shapiro-Wilk test statistic (not p-value)
                    try:
                        stat, _ = stats.shapiro(data_clean)
                        # stat close to 1 indicates normality
                        normality_deviation = 1 - stat
                        distribution_noise = min(1.0, normality_deviation * 3)
                        noise_estimates.append(('distribution', distribution_noise, 0.1))
                    except:
                        # Use skewness and kurtosis as alternatives
                        skewness = abs(stats.skew(data_clean))
                        kurtosis = abs(stats.kurtosis(data_clean))
                        
                        # High skewness or kurtosis may indicate noise or outliers
                        moment_noise = min(1.0, (skewness + kurtosis) / 10)
                        noise_estimates.append(('moments', moment_noise, 0.1))
            except:
                pass
            
            # Method 7: Trend-residual analysis
            try:
                if len(data_clean) >= 6:
                    # Fit polynomial trend and analyze residuals
                    x = np.arange(len(data_clean))
                    
                    # Try different polynomial orders
                    residual_stds = []
                    for order in [1, 2, 3]:
                        if order < len(data_clean):
                            try:
                                coeffs = np.polyfit(x, data_clean, order)
                                trend = np.polyval(coeffs, x)
                                residuals = data_clean - trend
                                residual_stds.append(np.std(residuals))
                            except:
                                continue
                    
                    if residual_stds:
                        # Best fit residual standard deviation
                        min_residual_std = min(residual_stds)
                        signal_std = np.std(data_clean)
                        
                        if signal_std > 0:
                            trend_noise = min_residual_std / signal_std
                            noise_estimates.append(('trend_residual', trend_noise, 0.2))
            except:
                pass
            
            # Weighted fusion of noise estimates
            if noise_estimates:
                # Remove extreme outliers
                estimates = [est[1] for est in noise_estimates]
                median_est = np.median(estimates)
                mad_est = np.median(np.abs(np.array(estimates) - median_est))
                threshold = median_est + 3 * mad_est
                
                filtered_estimates = [
                    est for est in noise_estimates 
                    if abs(est[1] - median_est) <= threshold
                ]
                
                if filtered_estimates:
                    # Weighted average
                    total_weight = sum(est[2] for est in filtered_estimates)
                    if total_weight > 0:
                        weighted_noise = sum(est[1] * est[2] for est in filtered_estimates) / total_weight
                        
                        # Apply signal characteristics-based adjustment
                        signal_range = np.ptp(data_clean)  # Peak-to-peak
                        signal_std = np.std(data_clean)
                        
                        if signal_range > 0 and signal_std > 0:
                            # High range-to-std ratio indicates structured signal
                            structure_factor = signal_range / (4 * signal_std)  # Approx for Gaussian
                            if structure_factor > 2:  # Highly structured
                                weighted_noise *= 0.8
                            elif structure_factor < 0.5:  # Less structured
                                weighted_noise *= 1.2
                        
                        return max(0.01, min(1.0, weighted_noise))
            
            # Ultimate fallback with basic statistics
            try:
                # Simple coefficient of variation approach
                cv = np.std(data_clean) / (abs(np.mean(data_clean)) + 1e-10)
                cv_noise = min(1.0, cv / 2)
                return max(0.05, min(0.8, cv_noise))
            except:
                return 0.2
                
        except Exception as e:
            # Final safety fallback
            try:
                if len(data) > 1:
                    # Simplest possible noise estimate
                    simple_noise = np.std(np.diff(data)) / (np.std(data) + 1e-10)
                    return max(0.01, min(1.0, simple_noise))
                return 0.2
            except:
                return 0.2
    
    def _detect_cyclical_patterns(self, data: np.ndarray) -> bool:
        """
        Advanced cyclical pattern detection using multi-method ensemble approach:
        - Power spectral density analysis with peak detection
        - Wavelet-based time-frequency analysis
        - Empirical Mode Decomposition (EMD) cyclicity assessment
        - Machine learning-based pattern recognition
        - Statistical significance testing of detected cycles
        """
        try:
            from scipy import signal
            from scipy.fft import fft, fftfreq
            from scipy.stats import chi2
            from sklearn.ensemble import IsolationForest
            import pywt
            
            n = len(data)
            if n < 20:
                return False
            
            # Ensemble of cyclical detection methods
            detection_scores = []
            confidence_weights = []
            
            # Method 1: Advanced Power Spectral Density Analysis
            psd_result = self._psd_cyclical_detection(data)
            detection_scores.append(psd_result['is_cyclical'])
            confidence_weights.append(psd_result['confidence'])
            
            # Method 2: Wavelet-based Multi-scale Analysis
            if n >= 32:  # Minimum for wavelet analysis
                wavelet_result = self._wavelet_cyclical_detection(data)
                detection_scores.append(wavelet_result['is_cyclical'])
                confidence_weights.append(wavelet_result['confidence'])
            
            # Method 3: Empirical Mode Decomposition Analysis
            if n >= 50:
                emd_result = self._emd_cyclical_detection(data)
                detection_scores.append(emd_result['is_cyclical'])
                confidence_weights.append(emd_result['confidence'])
            
            # Method 4: Machine Learning Pattern Recognition
            if n >= 30:
                ml_result = self._ml_pattern_recognition(data)
                detection_scores.append(ml_result['is_cyclical'])
                confidence_weights.append(ml_result['confidence'])
            
            # Method 5: Statistical Significance Testing
            stat_result = self._statistical_cyclical_test(data)
            detection_scores.append(stat_result['is_cyclical'])
            confidence_weights.append(stat_result['confidence'])
            
            # Weighted ensemble decision
            if not detection_scores:
                return False
            
            # Calculate weighted average with confidence-based weighting
            total_weight = sum(confidence_weights)
            if total_weight == 0:
                return sum(detection_scores) > len(detection_scores) / 2
            
            weighted_score = sum(score * weight for score, weight in 
                               zip(detection_scores, confidence_weights)) / total_weight
            
            # Adaptive threshold based on ensemble confidence
            ensemble_confidence = total_weight / len(confidence_weights)
            threshold = 0.4 + 0.1 * (1 - ensemble_confidence)  # Higher threshold for low confidence
            
            return weighted_score > threshold
            
        except Exception as e:
            # Fallback to enhanced autocorrelation method
            return self._fallback_autocorr_detection(data)
    
    def _enhance_edges(self, filtered: np.ndarray, original: np.ndarray, 
                      enhancement_factor: float) -> np.ndarray:
        """
        Advanced multi-scale edge enhancement using:
        - Multiscale morphological analysis for edge detection
        - Anisotropic diffusion-based edge preservation
        - Gabor filter bank for directional edge enhancement
        - Non-local means edge-aware filtering
        - Structure tensor analysis for geometric feature preservation
        - Machine learning-based edge classification
        """
        try:
            from scipy import ndimage, signal
            from scipy.ndimage import gaussian_filter, sobel
            from sklearn.cluster import KMeans
            from skimage import filters, feature, morphology
            import pywt
            
            n = len(original)
            enhanced = filtered.copy()
            
            # Method 1: Multi-scale Morphological Edge Detection
            morphological_edges = self._multiscale_morphological_edges(original)
            
            # Method 2: Structure Tensor Analysis for Geometric Features  
            structure_edges = self._structure_tensor_edges(original)
            
            # Method 3: Gabor Filter Bank for Directional Enhancement
            gabor_edges = self._gabor_filter_bank_edges(original)
            
            # Method 4: Wavelet-based Multi-resolution Edge Detection
            wavelet_edges = self._wavelet_multires_edges(original)
            
            # Method 5: Machine Learning Edge Classification
            ml_edges = self._ml_edge_classification(original, filtered)
            
            # Combine edge maps using weighted fusion
            edge_maps = [morphological_edges, structure_edges, gabor_edges, 
                        wavelet_edges, ml_edges]
            edge_weights = [0.25, 0.2, 0.2, 0.2, 0.15]  # Weights based on reliability
            
            # Weighted edge combination
            combined_edges = np.zeros_like(original)
            for edge_map, weight in zip(edge_maps, edge_weights):
                if edge_map is not None:
                    combined_edges += weight * edge_map
            
            # Normalize combined edge map
            if np.max(combined_edges) > 0:
                combined_edges = combined_edges / np.max(combined_edges)
            
            # Adaptive thresholding using Otsu's method
            try:
                threshold = filters.threshold_otsu(combined_edges[combined_edges > 0])
                edge_mask = combined_edges > threshold
            except:
                # Fallback to percentile-based thresholding
                threshold = np.percentile(combined_edges, 75)
                edge_mask = combined_edges > threshold
            
            # Multi-scale enhancement with anisotropic diffusion
            if np.any(edge_mask):
                # Apply different enhancement strategies based on edge characteristics
                edge_enhanced = self._anisotropic_edge_enhancement(
                    filtered, original, edge_mask, enhancement_factor)
                
                # Non-local means edge-aware smoothing
                edge_enhanced = self._nonlocal_means_edge_aware(
                    edge_enhanced, original, edge_mask)
                
                # Structure-preserving bilateral filtering
                edge_enhanced = self._structure_preserving_bilateral(
                    edge_enhanced, original, combined_edges)
                
                enhanced = edge_enhanced
            else:
                # No significant edges detected, apply gentle enhancement
                enhanced = (1 - enhancement_factor * 0.5) * filtered + \
                          enhancement_factor * 0.5 * original
            
            # Post-processing: Remove artifacts and ensure signal continuity
            enhanced = self._remove_enhancement_artifacts(enhanced, original, filtered)
            
            return enhanced
            
        except Exception as e:
            # Robust fallback with basic edge preservation
            return self._fallback_edge_enhancement(filtered, original, enhancement_factor)
    
    def _psd_cyclical_detection(self, data: np.ndarray) -> dict:
        """Power spectral density based cyclical pattern detection."""
        try:
            from scipy import signal
            from scipy.fft import fft, fftfreq
            
            # Compute power spectral density using Welch's method
            freqs, psd = signal.welch(data, nperseg=min(len(data)//4, 64))
            
            # Find peaks in PSD
            peaks, properties = signal.find_peaks(psd, height=np.mean(psd) + np.std(psd))
            
            # Analyze peak characteristics
            if len(peaks) > 0:
                peak_heights = psd[peaks]
                peak_prominence = properties.get('peak_heights', peak_heights)
                
                # Check for significant periodic components
                max_peak_idx = np.argmax(peak_prominence)
                dominant_freq = freqs[peaks[max_peak_idx]]
                dominant_power = peak_heights[max_peak_idx]
                
                # Statistical significance test
                noise_level = np.median(psd)
                snr = dominant_power / (noise_level + 1e-10)
                
                is_cyclical = snr > 3.0 and dominant_freq > 0
                confidence = min(0.95, snr / 10.0)
            else:
                is_cyclical = False
                confidence = 0.1
                
            return {'is_cyclical': is_cyclical, 'confidence': confidence}
        except:
            return {'is_cyclical': False, 'confidence': 0.1}
    
    def _wavelet_cyclical_detection(self, data: np.ndarray) -> dict:
        """Wavelet-based multi-scale cyclical pattern detection."""
        try:
            import pywt
            
            # Continuous wavelet transform
            scales = np.arange(1, min(len(data)//4, 32))
            coeffs, freqs = pywt.cwt(data, scales, 'morl')
            
            # Compute scalogram (time-frequency energy)
            scalogram = np.abs(coeffs)**2
            
            # Find dominant scales with consistent energy
            scale_energy = np.mean(scalogram, axis=1)
            energy_threshold = np.mean(scale_energy) + 2*np.std(scale_energy)
            
            dominant_scales = scales[scale_energy > energy_threshold]
            
            if len(dominant_scales) > 0:
                # Check for temporal consistency
                max_scale_idx = np.argmax(scale_energy)
                temporal_consistency = np.std(scalogram[max_scale_idx]) / \
                                     (np.mean(scalogram[max_scale_idx]) + 1e-10)
                
                is_cyclical = temporal_consistency < 0.7  # Lower std indicates consistency
                confidence = 1.0 - temporal_consistency
            else:
                is_cyclical = False
                confidence = 0.1
                
            return {'is_cyclical': is_cyclical, 'confidence': max(0.1, confidence)}
        except:
            return {'is_cyclical': False, 'confidence': 0.1}
    
    def _emd_cyclical_detection(self, data: np.ndarray) -> dict:
        """
        Advanced Empirical Mode Decomposition based cyclical detection using:
        - Complete Ensemble EMD with Adaptive Noise (CEEMDAN)
        - Hilbert-Huang Transform with instantaneous frequency analysis
        - Variational Mode Decomposition (VMD) for comparison
        - Advanced IMF validation using multiple criteria
        - Instantaneous frequency and amplitude analysis
        - Statistical significance testing of cyclical components
        - Multi-resolution time-frequency analysis
        """
        try:
            from scipy import signal
            from scipy.fft import hilbert
            from scipy.optimize import minimize
            from sklearn.cluster import DBSCAN
            
            n = len(data)
            if n < 20:
                return {'is_cyclical': False, 'confidence': 0.1}
                
            # Ensemble approach combining multiple decomposition methods
            decomposition_results = {}
            
            # Method 1: Complete Ensemble EMD with Adaptive Noise (CEEMDAN)
            ceemdan_result = self._ceemdan_decomposition(data)
            decomposition_results['ceemdan'] = ceemdan_result
            
            # Method 2: Variational Mode Decomposition (VMD)
            if n >= 64:  # VMD requires sufficient data length
                vmd_result = self._vmd_decomposition(data)
                decomposition_results['vmd'] = vmd_result
            
            # Method 3: Enhanced Traditional EMD with better envelope estimation
            enhanced_emd_result = self._enhanced_emd_decomposition(data)
            decomposition_results['enhanced_emd'] = enhanced_emd_result
            
            # Method 4: Empirical Wavelet Transform (EWT)
            if n >= 32:
                ewt_result = self._empirical_wavelet_transform(data)
                decomposition_results['ewt'] = ewt_result
            
            # Analyze all decomposition results
            cyclical_evidence = []
            confidence_scores = []
            
            for method_name, result in decomposition_results.items():
                if result and 'imfs' in result:
                    # Advanced IMF analysis
                    imf_analysis = self._advanced_imf_analysis(result['imfs'], data)
                    
                    # Hilbert spectrum analysis
                    hilbert_analysis = self._hilbert_spectrum_analysis(result['imfs'])
                    
                    # Instantaneous frequency analysis
                    freq_analysis = self._instantaneous_frequency_analysis(result['imfs'])
                    
                    # Combined assessment
                    method_evidence = self._assess_cyclical_evidence(
                        imf_analysis, hilbert_analysis, freq_analysis)
                    
                    cyclical_evidence.append(method_evidence['is_cyclical'])
                    confidence_scores.append(method_evidence['confidence'])
            
            # Ensemble decision making
            if not cyclical_evidence:
                return {'is_cyclical': False, 'confidence': 0.1}
            
            # Weighted voting based on method reliability
            method_weights = self._get_method_reliability_weights(decomposition_results)
            
            weighted_evidence = sum(ev * w for ev, w in zip(cyclical_evidence, method_weights))
            weighted_confidence = sum(conf * w for conf, w in zip(confidence_scores, method_weights))
            
            total_weight = sum(method_weights)
            if total_weight > 0:
                final_evidence = weighted_evidence / total_weight
                final_confidence = weighted_confidence / total_weight
            else:
                final_evidence = sum(cyclical_evidence) / len(cyclical_evidence)
                final_confidence = sum(confidence_scores) / len(confidence_scores)
            
            # Statistical significance testing
            significance_test = self._statistical_significance_test(data, decomposition_results)
            
            # Final decision with significance weighting
            is_cyclical = (final_evidence > 0.5 and 
                          significance_test['p_value'] < 0.1 and
                          final_confidence > 0.3)
            
            # Adjust confidence based on statistical significance
            adjusted_confidence = final_confidence * (1 - significance_test['p_value'])
            adjusted_confidence = min(0.95, max(0.05, adjusted_confidence))
            
            return {
                'is_cyclical': is_cyclical, 
                'confidence': adjusted_confidence,
                'decomposition_methods': list(decomposition_results.keys()),
                'significance_p_value': significance_test['p_value'],
                'dominant_frequencies': significance_test.get('dominant_frequencies', [])
            }
            
        except Exception as e:
            # Advanced fallback with enhanced traditional EMD
            return self._fallback_enhanced_emd(data)
    
    def _ceemdan_decomposition(self, data: np.ndarray) -> dict:
        """Complete Ensemble EMD with Adaptive Noise decomposition."""
        try:
            from scipy import signal
            import numpy.random as rng
            
            # CEEMDAN parameters
            n_ensembles = 50
            noise_std = 0.2 * np.std(data)
            max_imfs = 8
            
            n = len(data)
            imfs_ensemble = []
            
            # Generate ensemble of noisy signals
            for ensemble in range(n_ensembles):
                # Add white Gaussian noise
                noise = rng.normal(0, noise_std, n)
                noisy_signal = data + noise
                
                # Decompose each ensemble member
                imfs = self._sifting_process(noisy_signal, max_imfs)
                imfs_ensemble.append(imfs)
            
            # Compute CEEMDAN modes by averaging
            if not imfs_ensemble:
                return None
            
            max_modes = max(len(imfs) for imfs in imfs_ensemble)
            ceemdan_imfs = []
            
            for mode_idx in range(max_modes):
                mode_ensemble = []
                for imfs in imfs_ensemble:
                    if mode_idx < len(imfs):
                        # Ensure same length
                        mode = imfs[mode_idx]
                        if len(mode) == n:
                            mode_ensemble.append(mode)
                
                if mode_ensemble:
                    # Average across ensemble
                    averaged_mode = np.mean(mode_ensemble, axis=0)
                    ceemdan_imfs.append(averaged_mode)
            
            return {
                'imfs': ceemdan_imfs,
                'method': 'CEEMDAN',
                'n_ensembles': n_ensembles,
                'noise_std': noise_std
            }
            
        except Exception as e:
            return None
    
    def _vmd_decomposition(self, data: np.ndarray) -> dict:
        """Variational Mode Decomposition."""
        try:
            from scipy.optimize import minimize
            from scipy.fft import fft, ifft, fftfreq
            
            # VMD parameters
            K = 5  # Number of modes
            alpha = 2000  # Bandwidth constraint
            tau = 0.0  # Lagrangian multiplier update rate
            DC = 0  # DC part
            init = 1  # Initialization method
            tol = 1e-7  # Tolerance
            
            n = len(data)
            
            # Frequency domain setup
            freqs = fftfreq(n)
            
            # Initialize modes in frequency domain
            omega = np.zeros(K)  # Center frequencies
            modes_hat = np.zeros((K, n), dtype=complex)
            
            # Initialize with equally spaced frequencies
            for k in range(K):
                omega[k] = 0.25 * k / K
            
            # Optimization-based VMD
            def vmd_objective(x):
                omega_new = x[:K]
                
                # Reconstruct modes
                modes_new = np.zeros((K, n), dtype=complex)
                for k in range(K):
                    # Mode extraction using Wiener filtering
                    H = 1.0 / (1.0 + alpha * (freqs - omega_new[k])**2)
                    modes_new[k] = H * fft(data)
                
                # Objective: minimize bandwidth and reconstruction error
                bandwidth_term = 0
                for k in range(K):
                    mode_time = np.real(ifft(modes_new[k]))
                    analytic_signal = signal.hilbert(mode_time)
                    inst_freq = np.diff(np.unwrap(np.angle(analytic_signal)))
                    bandwidth_term += np.var(inst_freq)
                
                reconstruction = np.sum([np.real(ifft(mode)) for mode in modes_new], axis=0)
                reconstruction_error = np.mean((data - reconstruction)**2)
                
                return bandwidth_term + alpha * reconstruction_error
            
            # Optimize center frequencies
            x0 = np.linspace(0.1, 0.4, K)
            bounds = [(0.01, 0.49) for _ in range(K)]
            
            try:
                result = minimize(vmd_objective, x0, method='L-BFGS-B', 
                                bounds=bounds, options={'maxiter': 50})
                omega_opt = result.x
            except:
                omega_opt = x0  # Fallback to initial guess
            
            # Extract final modes
            final_modes = []
            for k in range(K):
                H = 1.0 / (1.0 + alpha * (freqs - omega_opt[k])**2)
                mode_hat = H * fft(data)
                mode_time = np.real(ifft(mode_hat))
                final_modes.append(mode_time)
            
            return {
                'imfs': final_modes,
                'method': 'VMD',
                'center_frequencies': omega_opt,
                'n_modes': K
            }
            
        except Exception as e:
            return None
    
    def _enhanced_emd_decomposition(self, data: np.ndarray) -> dict:
        """Enhanced EMD with improved envelope estimation."""
        try:
            from scipy import interpolate
            from scipy.ndimage import gaussian_filter1d
            
            imfs = self._sifting_process_enhanced(data)
            
            return {
                'imfs': imfs,
                'method': 'Enhanced_EMD',
                'n_imfs': len(imfs)
            }
            
        except Exception as e:
            return None
    
    def _empirical_wavelet_transform(self, data: np.ndarray) -> dict:
        """Empirical Wavelet Transform decomposition."""
        try:
            from scipy.fft import fft, ifft, fftfreq
            from scipy import signal
            
            n = len(data)
            
            # Fourier spectrum
            fft_data = fft(data)
            freqs = fftfreq(n)
            power_spectrum = np.abs(fft_data)**2
            
            # Detect boundaries in spectrum (mode mixing boundaries)
            boundaries = self._detect_spectrum_boundaries(power_spectrum, freqs)
            
            # Create empirical wavelets
            modes = []
            for i, (f_low, f_high) in enumerate(boundaries):
                # Create bandpass filter
                mask = (np.abs(freqs) >= f_low) & (np.abs(freqs) <= f_high)
                
                # Smooth transition using Kaiser window
                transition_width = 0.1 * (f_high - f_low)
                window = signal.windows.kaiser(n, beta=8.6)
                
                # Apply filter
                filtered_fft = fft_data * mask
                mode = np.real(ifft(filtered_fft))
                modes.append(mode)
            
            return {
                'imfs': modes,
                'method': 'EWT',
                'boundaries': boundaries,
                'n_modes': len(modes)
            }
            
        except Exception as e:
            return None
    
    def _sifting_process(self, data: np.ndarray, max_imfs: int = 8) -> list:
        """Traditional sifting process for EMD."""
        try:
            from scipy import signal, interpolate
            
            imfs = []
            residue = data.copy()
            
            for imf_idx in range(max_imfs):
                if len(residue) < 10:
                    break
                
                # Sifting iterations
                h = residue.copy()
                
                for sift_iter in range(50):  # Maximum sifting iterations
                    # Find local extrema
                    maxima_idx = signal.argrelmax(h, order=1)[0]
                    minima_idx = signal.argrelmin(h, order=1)[0]
                    
                    if len(maxima_idx) < 3 or len(minima_idx) < 3:
                        break
                    
                    # Cubic spline interpolation for envelopes
                    t = np.arange(len(h))
                    
                    try:
                        # Upper envelope
                        if len(maxima_idx) >= 3:
                            upper_spline = interpolate.CubicSpline(maxima_idx, h[maxima_idx], 
                                                                bc_type='natural')
                            upper_env = upper_spline(t)
                        else:
                            upper_env = np.full_like(h, np.max(h))
                        
                        # Lower envelope
                        if len(minima_idx) >= 3:
                            lower_spline = interpolate.CubicSpline(minima_idx, h[minima_idx], 
                                                                bc_type='natural')
                            lower_env = lower_spline(t)
                        else:
                            lower_env = np.full_like(h, np.min(h))
                        
                        # Mean envelope
                        mean_env = (upper_env + lower_env) / 2
                        
                        # Update h
                        h_new = h - mean_env
                        
                        # Stopping criterion (IMF condition)
                        sd = np.sum((h - h_new)**2) / (np.sum(h**2) + 1e-10)
                        
                        h = h_new
                        
                        if sd < 0.2:  # Standard deviation criterion
                            break
                            
                    except Exception:
                        break
                
                # Validate IMF
                if self._is_valid_imf(h):
                    imfs.append(h)
                    residue = residue - h
                else:
                    break
                
                # Check if residue is monotonic (trend)
                if self._is_monotonic_trend(residue):
                    imfs.append(residue)
                    break
            
            return imfs
            
        except Exception as e:
            return []
    
    def _sifting_process_enhanced(self, data: np.ndarray) -> list:
        """Enhanced sifting process with improved envelope estimation."""
        try:
            from scipy import signal, interpolate
            from scipy.ndimage import gaussian_filter1d
            
            imfs = []
            residue = data.copy()
            
            for imf_idx in range(10):
                if len(residue) < 10:
                    break
                
                h = residue.copy()
                
                for sift_iter in range(100):
                    # Enhanced extrema detection
                    extrema = self._detect_enhanced_extrema(h)
                    
                    if extrema['n_maxima'] < 3 or extrema['n_minima'] < 3:
                        break
                    
                    # Improved envelope estimation
                    envelopes = self._compute_enhanced_envelopes(h, extrema)
                    
                    if envelopes is None:
                        break
                    
                    # Adaptive mean envelope with outlier removal
                    mean_env = self._compute_adaptive_mean_envelope(envelopes)
                    
                    h_new = h - mean_env
                    
                    # Multi-criteria stopping condition
                    stopping_criteria = self._evaluate_stopping_criteria(h, h_new)
                    
                    h = h_new
                    
                    if stopping_criteria['stop']:
                        break
                
                # Advanced IMF validation
                if self._advanced_imf_validation(h, data):
                    imfs.append(h)
                    residue = residue - h
                else:
                    break
                
                # Enhanced trend detection
                if self._is_enhanced_trend(residue):
                    imfs.append(residue)
                    break
            
            return imfs
            
        except Exception as e:
            return []
    
    def _advanced_imf_analysis(self, imfs: list, original_data: np.ndarray) -> dict:
        """Advanced analysis of IMF characteristics."""
        try:
            if not imfs:
                return {'cyclical_score': 0, 'dominant_imf': None}
            
            imf_scores = []
            
            for i, imf in enumerate(imfs):
                if len(imf) < 10:
                    continue
                
                # Multi-criteria IMF assessment
                criteria = {}
                
                # 1. Spectral purity
                criteria['spectral_purity'] = self._compute_spectral_purity(imf)
                
                # 2. Instantaneous frequency consistency
                criteria['freq_consistency'] = self._compute_frequency_consistency(imf)
                
                # 3. Energy distribution
                criteria['energy_ratio'] = np.var(imf) / (np.var(original_data) + 1e-10)
                
                # 4. Zero-crossing regularity
                criteria['zero_crossing_regularity'] = self._compute_zero_crossing_regularity(imf)
                
                # 5. Orthogonality with other IMFs
                criteria['orthogonality'] = self._compute_imf_orthogonality(imf, imfs, i)
                
                # Combined score
                weights = [0.25, 0.2, 0.2, 0.2, 0.15]
                score = sum(w * c for w, c in zip(weights, criteria.values()))
                
                imf_scores.append({
                    'imf_index': i,
                    'score': score,
                    'criteria': criteria,
                    'is_cyclical': score > 0.4
                })
            
            # Overall cyclical assessment
            cyclical_imfs = [s for s in imf_scores if s['is_cyclical']]
            cyclical_score = sum(s['score'] for s in cyclical_imfs) / len(imf_scores) if imf_scores else 0
            
            dominant_imf = max(imf_scores, key=lambda x: x['score']) if imf_scores else None
            
            return {
                'cyclical_score': cyclical_score,
                'dominant_imf': dominant_imf,
                'imf_scores': imf_scores,
                'n_cyclical_imfs': len(cyclical_imfs)
            }
            
        except Exception as e:
            return {'cyclical_score': 0, 'dominant_imf': None}
    
    def _hilbert_spectrum_analysis(self, imfs: list) -> dict:
        """Hilbert spectrum analysis for time-frequency characteristics."""
        try:
            if not imfs:
                return {'spectrum_score': 0, 'dominant_frequencies': []}
            
            dominant_frequencies = []
            spectrum_scores = []
            
            for imf in imfs:
                if len(imf) < 10:
                    continue
                
                # Hilbert transform
                analytic_signal = signal.hilbert(imf)
                
                # Instantaneous amplitude and phase
                inst_amplitude = np.abs(analytic_signal)
                inst_phase = np.angle(analytic_signal)
                
                # Instantaneous frequency
                inst_frequency = np.diff(np.unwrap(inst_phase)) / (2 * np.pi)
                
                # Frequency statistics
                if len(inst_frequency) > 0:
                    freq_mean = np.mean(inst_frequency)
                    freq_std = np.std(inst_frequency)
                    freq_stability = 1.0 / (1.0 + freq_std / (abs(freq_mean) + 1e-10))
                    
                    dominant_frequencies.append(freq_mean)
                    spectrum_scores.append(freq_stability)
            
            # Overall spectrum assessment
            spectrum_score = np.mean(spectrum_scores) if spectrum_scores else 0
            
            # Frequency clustering for dominant patterns
            if dominant_frequencies:
                freq_clusters = self._cluster_frequencies(dominant_frequencies)
            else:
                freq_clusters = []
            
            return {
                'spectrum_score': spectrum_score,
                'dominant_frequencies': dominant_frequencies,
                'frequency_clusters': freq_clusters,
                'frequency_stability': spectrum_score
            }
            
        except Exception as e:
            return {'spectrum_score': 0, 'dominant_frequencies': []}
    
    def _instantaneous_frequency_analysis(self, imfs: list) -> dict:
        """Detailed instantaneous frequency analysis."""
        try:
            if not imfs:
                return {'freq_score': 0, 'freq_patterns': []}
            
            freq_patterns = []
            
            for i, imf in enumerate(imfs):
                if len(imf) < 20:
                    continue
                
                # Hilbert transform for instantaneous frequency
                analytic_signal = signal.hilbert(imf)
                inst_phase = np.unwrap(np.angle(analytic_signal))
                inst_freq = np.gradient(inst_phase)
                
                # Remove outliers
                freq_median = np.median(inst_freq)
                freq_mad = np.median(np.abs(inst_freq - freq_median))
                freq_threshold = 3 * freq_mad
                
                valid_freq = inst_freq[np.abs(inst_freq - freq_median) < freq_threshold]
                
                if len(valid_freq) > 0:
                    pattern = {
                        'imf_index': i,
                        'mean_frequency': np.mean(valid_freq),
                        'frequency_variance': np.var(valid_freq),
                        'frequency_range': np.ptp(valid_freq),
                        'frequency_trend': np.polyfit(range(len(valid_freq)), valid_freq, 1)[0],
                        'cyclical_consistency': self._compute_cyclical_consistency(valid_freq)
                    }
                    freq_patterns.append(pattern)
            
            # Overall frequency score
            if freq_patterns:
                consistency_scores = [p['cyclical_consistency'] for p in freq_patterns]
                freq_score = np.mean(consistency_scores)
            else:
                freq_score = 0
            
            return {
                'freq_score': freq_score,
                'freq_patterns': freq_patterns,
                'n_consistent_patterns': sum(1 for p in freq_patterns if p['cyclical_consistency'] > 0.5)
            }
            
        except Exception as e:
            return {'freq_score': 0, 'freq_patterns': []}
    
    def _assess_cyclical_evidence(self, imf_analysis: dict, hilbert_analysis: dict, freq_analysis: dict) -> dict:
        """Assess cyclical evidence from multiple analyses."""
        try:
            # Weighted combination of evidence
            weights = {
                'imf': 0.4,
                'hilbert': 0.3,
                'frequency': 0.3
            }
            
            scores = {
                'imf': imf_analysis.get('cyclical_score', 0),
                'hilbert': hilbert_analysis.get('spectrum_score', 0),
                'frequency': freq_analysis.get('freq_score', 0)
            }
            
            combined_score = sum(weights[key] * scores[key] for key in weights)
            
            # Additional criteria
            n_cyclical_imfs = imf_analysis.get('n_cyclical_imfs', 0)
            n_consistent_patterns = freq_analysis.get('n_consistent_patterns', 0)
            
            # Decision logic
            is_cyclical = (combined_score > 0.4 and 
                          n_cyclical_imfs >= 1 and 
                          n_consistent_patterns >= 1)
            
            # Confidence calculation
            confidence = combined_score * (1 + 0.1 * n_cyclical_imfs) * (1 + 0.1 * n_consistent_patterns)
            confidence = min(0.95, max(0.05, confidence))
            
            return {
                'is_cyclical': is_cyclical,
                'confidence': confidence,
                'combined_score': combined_score,
                'individual_scores': scores
            }
            
        except Exception as e:
            return {'is_cyclical': False, 'confidence': 0.1}
    
    def _get_method_reliability_weights(self, decomposition_results: dict) -> list:
        """Determine reliability weights for different decomposition methods."""
        try:
            weights = []
            methods = list(decomposition_results.keys())
            
            # Method-specific reliability weights
            reliability_map = {
                'ceemdan': 0.35,      # Highest reliability for noise robustness
                'vmd': 0.25,          # Good for specific frequency bands
                'enhanced_emd': 0.25, # Traditional but enhanced
                'ewt': 0.15           # Newer but less established
            }
            
            for method in methods:
                weight = reliability_map.get(method, 0.1)
                
                # Adjust based on decomposition quality
                result = decomposition_results[method]
                if result and 'imfs' in result:
                    n_imfs = len(result['imfs'])
                    # Penalize too few or too many modes
                    if 2 <= n_imfs <= 8:
                        weight *= 1.0
                    elif n_imfs < 2:
                        weight *= 0.5
                    else:
                        weight *= 0.8
                
                weights.append(weight)
            
            return weights
            
        except Exception as e:
            return [1.0] * len(decomposition_results)
    
    def _statistical_significance_test(self, data: np.ndarray, decomposition_results: dict) -> dict:
        """Statistical significance testing of cyclical components."""
        try:
            from scipy.stats import chi2
            
            # Collect all dominant frequencies from decompositions
            all_frequencies = []
            
            for method, result in decomposition_results.items():
                if result and 'imfs' in result:
                    for imf in result['imfs']:
                        if len(imf) > 10:
                            # Power spectral density
                            freqs, psd = signal.welch(imf, nperseg=min(len(imf)//2, 64))
                            
                            if len(psd) > 0:
                                dominant_freq_idx = np.argmax(psd)
                                dominant_freq = freqs[dominant_freq_idx]
                                all_frequencies.append(dominant_freq)
            
            if not all_frequencies:
                return {'p_value': 1.0, 'dominant_frequencies': []}
            
            # Test against white noise hypothesis
            # Generate white noise with same statistics
            noise_frequencies = []
            for _ in range(100):  # Bootstrap samples
                noise = np.random.normal(np.mean(data), np.std(data), len(data))
                freqs, psd = signal.welch(noise, nperseg=min(len(data)//2, 64))
                
                if len(psd) > 0:
                    dominant_freq_idx = np.argmax(psd)
                    noise_freq = freqs[dominant_freq_idx]
                    noise_frequencies.append(noise_freq)
            
            # Statistical test (Kolmogorov-Smirnov)
            from scipy.stats import ks_2samp
            
            if noise_frequencies and all_frequencies:
                ks_stat, p_value = ks_2samp(all_frequencies, noise_frequencies)
            else:
                p_value = 1.0
            
            return {
                'p_value': p_value,
                'dominant_frequencies': list(set(all_frequencies)),
                'test_statistic': ks_stat if 'ks_stat' in locals() else 0
            }
            
        except Exception as e:
            return {'p_value': 1.0, 'dominant_frequencies': []}
    
    def _fallback_enhanced_emd(self, data: np.ndarray) -> dict:
        """Enhanced fallback EMD implementation."""
        try:
            # Simplified but robust EMD
            imfs = []
            residue = data.copy()
            
            for _ in range(6):  # Maximum 6 IMFs
                if len(residue) < 10:
                    break
                
                # Simple but effective sifting
                h = residue.copy()
                
                for _ in range(20):  # Sifting iterations
                    maxima_idx = signal.argrelmax(h, order=2)[0]
                    minima_idx = signal.argrelmin(h, order=2)[0]
                    
                    if len(maxima_idx) < 2 or len(minima_idx) < 2:
                        break
                    
                    # Linear envelope approximation
                    if len(maxima_idx) >= 2:
                        upper_env = np.interp(range(len(h)), maxima_idx, h[maxima_idx])
                    else:
                        upper_env = np.full_like(h, np.max(h))
                    
                    if len(minima_idx) >= 2:
                        lower_env = np.interp(range(len(h)), minima_idx, h[minima_idx])
                    else:
                        lower_env = np.full_like(h, np.min(h))
                    
                    mean_env = (upper_env + lower_env) / 2
                    h_new = h - mean_env
                    
                    # Simple stopping criterion
                    if np.std(h - h_new) / (np.std(h) + 1e-10) < 0.3:
                        break
                    
                    h = h_new
                
                imfs.append(h)
                residue = residue - h
                
                if np.var(residue) < 0.01 * np.var(data):
                    break
            
            # Simple cyclical assessment
            cyclical_imfs = 0
            total_energy = 0
            cyclical_energy = 0
            
            for imf in imfs:
                imf_energy = np.var(imf)
                total_energy += imf_energy
                
                zero_crossings = np.sum(np.diff(np.sign(imf)) != 0)
                normalized_crossings = zero_crossings / len(imf)
                
                if 0.08 < normalized_crossings < 0.5:
                    cyclical_imfs += 1
                    cyclical_energy += imf_energy
            
            if total_energy > 0:
                cyclical_ratio = cyclical_energy / total_energy
                is_cyclical = cyclical_ratio > 0.25 and cyclical_imfs >= 1
                confidence = min(0.8, cyclical_ratio * 1.5)
            else:
                is_cyclical = False
                confidence = 0.1
            
            return {'is_cyclical': is_cyclical, 'confidence': confidence}
            
        except Exception as e:
            return {'is_cyclical': False, 'confidence': 0.1}
    
    # Supporting utility methods for advanced EMD
    def _is_valid_imf(self, h: np.ndarray) -> bool:
        """Check if signal satisfies IMF conditions."""
        try:
            # IMF conditions: number of extrema and zero crossings should differ by at most 1
            maxima = signal.argrelmax(h, order=1)[0]
            minima = signal.argrelmin(h, order=1)[0]
            zero_crossings = np.sum(np.diff(np.sign(h)) != 0)
            
            extrema_count = len(maxima) + len(minima)
            
            return abs(extrema_count - zero_crossings) <= 1 and extrema_count >= 3
        except:
            return False
    
    def _is_monotonic_trend(self, residue: np.ndarray) -> bool:
        """Check if residue is a monotonic trend."""
        try:
            diff_signs = np.diff(np.sign(np.diff(residue)))
            return len(signal.argrelmax(residue, order=2)[0]) <= 1 and len(signal.argrelmin(residue, order=2)[0]) <= 1
        except:
            return True
    
    def _detect_enhanced_extrema(self, h: np.ndarray) -> dict:
        """Enhanced extrema detection with noise robustness."""
        try:
            from scipy.ndimage import gaussian_filter1d
            
            # Smooth signal to reduce noise effects
            h_smooth = gaussian_filter1d(h, sigma=0.5)
            
            # Multi-scale extrema detection
            maxima_list = []
            minima_list = []
            
            for order in [1, 2, 3]:
                maxima = signal.argrelmax(h_smooth, order=order)[0]
                minima = signal.argrelmin(h_smooth, order=order)[0]
                
                maxima_list.extend(maxima)
                minima_list.extend(minima)
            
            # Remove duplicates and sort
            maxima_idx = sorted(list(set(maxima_list)))
            minima_idx = sorted(list(set(minima_list)))
            
            return {
                'maxima': maxima_idx,
                'minima': minima_idx,
                'n_maxima': len(maxima_idx),
                'n_minima': len(minima_idx)
            }
        except:
            maxima = signal.argrelmax(h, order=2)[0]
            minima = signal.argrelmin(h, order=2)[0]
            return {
                'maxima': maxima,
                'minima': minima,
                'n_maxima': len(maxima),
                'n_minima': len(minima)
            }
    
    def _compute_enhanced_envelopes(self, h: np.ndarray, extrema: dict) -> dict:
        """Compute enhanced envelopes with robustness."""
        try:
            from scipy import interpolate
            
            maxima_idx = extrema['maxima']
            minima_idx = extrema['minima']
            
            if len(maxima_idx) < 3 or len(minima_idx) < 3:
                return None
            
            t = np.arange(len(h))
            
            # Robust spline interpolation with boundary conditions
            upper_spline = interpolate.CubicSpline(
                maxima_idx, h[maxima_idx], 
                bc_type='natural', extrapolate=True
            )
            upper_env = upper_spline(t)
            
            lower_spline = interpolate.CubicSpline(
                minima_idx, h[minima_idx], 
                bc_type='natural', extrapolate=True
            )
            lower_env = lower_spline(t)
            
            return {
                'upper': upper_env,
                'lower': lower_env,
                'mean': (upper_env + lower_env) / 2
            }
        except:
            return None
    
    def _compute_adaptive_mean_envelope(self, envelopes: dict) -> np.ndarray:
        """Compute adaptive mean envelope with outlier handling."""
        try:
            mean_env = envelopes['mean']
            
            # Detect and handle outliers in mean envelope
            median_env = np.median(mean_env)
            mad_env = np.median(np.abs(mean_env - median_env))
            
            outlier_threshold = 3 * mad_env
            outlier_mask = np.abs(mean_env - median_env) > outlier_threshold
            
            # Replace outliers with smoothed values
            if np.any(outlier_mask):
                from scipy.ndimage import gaussian_filter1d
                mean_env_smooth = gaussian_filter1d(mean_env, sigma=1)
                mean_env[outlier_mask] = mean_env_smooth[outlier_mask]
            
            return mean_env
        except:
            return envelopes['mean']
    
    def _evaluate_stopping_criteria(self, h: np.ndarray, h_new: np.ndarray) -> dict:
        """Evaluate multiple stopping criteria for sifting."""
        try:
            # Standard deviation criterion
            sd = np.sum((h - h_new)**2) / (np.sum(h**2) + 1e-10)
            
            # Energy criterion
            energy_ratio = np.var(h_new) / (np.var(h) + 1e-10)
            
            # Correlation criterion
            correlation = np.corrcoef(h, h_new)[0, 1] if len(h) > 1 else 0
            
            # Combined stopping decision
            stop_sd = sd < 0.15
            stop_energy = 0.9 < energy_ratio < 1.1
            stop_corr = correlation > 0.95
            
            stop = stop_sd and (stop_energy or stop_corr)
            
            return {
                'stop': stop,
                'sd': sd,
                'energy_ratio': energy_ratio,
                'correlation': correlation
            }
        except:
            return {'stop': True}
    
    def _advanced_imf_validation(self, h: np.ndarray, original_data: np.ndarray) -> bool:
        """Advanced IMF validation with multiple criteria."""
        try:
            # Basic IMF condition
            if not self._is_valid_imf(h):
                return False
            
            # Energy criterion
            energy_ratio = np.var(h) / (np.var(original_data) + 1e-10)
            if energy_ratio < 0.01:  # Too low energy
                return False
            
            # Frequency content validation
            freqs, psd = signal.welch(h, nperseg=min(len(h)//2, 32))
            if len(psd) > 0:
                # Check for reasonable frequency content
                dominant_freq = freqs[np.argmax(psd)]
                if dominant_freq > 0.48:  # Too high frequency (near Nyquist)
                    return False
            
            return True
        except:
            return self._is_valid_imf(h)
    
    def _is_enhanced_trend(self, residue: np.ndarray) -> bool:
        """Enhanced trend detection."""
        try:
            # Multiple trend indicators
            indicators = []
            
            # 1. Monotonicity check
            diff = np.diff(residue)
            monotonic_ratio = max(np.sum(diff > 0), np.sum(diff < 0)) / len(diff)
            indicators.append(monotonic_ratio > 0.8)
            
            # 2. Low frequency content
            freqs, psd = signal.welch(residue, nperseg=min(len(residue)//2, 32))
            if len(psd) > 0:
                low_freq_energy = np.sum(psd[:len(psd)//4]) / np.sum(psd)
                indicators.append(low_freq_energy > 0.7)
            
            # 3. Few extrema
            extrema_count = len(signal.argrelmax(residue, order=2)[0]) + len(signal.argrelmin(residue, order=2)[0])
            indicators.append(extrema_count < 3)
            
            return sum(indicators) >= 2
        except:
            return self._is_monotonic_trend(residue)
    
    def _compute_spectral_purity(self, imf: np.ndarray) -> float:
        """Compute spectral purity of IMF."""
        try:
            freqs, psd = signal.welch(imf, nperseg=min(len(imf)//2, 64))
            if len(psd) == 0:
                return 0
            
            # Normalize PSD
            psd_norm = psd / np.sum(psd)
            
            # Compute entropy (lower entropy = higher purity)
            entropy = -np.sum(psd_norm * np.log(psd_norm + 1e-10))
            max_entropy = np.log(len(psd))
            
            purity = 1.0 - entropy / max_entropy
            return max(0, min(1, purity))
        except:
            return 0
    
    def _compute_frequency_consistency(self, imf: np.ndarray) -> float:
        """Compute instantaneous frequency consistency."""
        try:
            analytic_signal = signal.hilbert(imf)
            inst_phase = np.unwrap(np.angle(analytic_signal))
            inst_freq = np.diff(inst_phase)
            
            if len(inst_freq) == 0:
                return 0
            
            # Coefficient of variation (lower = more consistent)
            cv = np.std(inst_freq) / (np.abs(np.mean(inst_freq)) + 1e-10)
            consistency = 1.0 / (1.0 + cv)
            
            return max(0, min(1, consistency))
        except:
            return 0
    
    def _compute_zero_crossing_regularity(self, imf: np.ndarray) -> float:
        """Compute zero-crossing regularity."""
        try:
            # Find zero crossings
            zero_crossings = np.where(np.diff(np.sign(imf)))[0]
            
            if len(zero_crossings) < 2:
                return 0
            
            # Compute intervals between zero crossings
            intervals = np.diff(zero_crossings)
            
            if len(intervals) == 0:
                return 0
            
            # Regularity based on coefficient of variation
            cv = np.std(intervals) / (np.mean(intervals) + 1e-10)
            regularity = 1.0 / (1.0 + cv)
            
            return max(0, min(1, regularity))
        except:
            return 0
    
    def _compute_imf_orthogonality(self, imf: np.ndarray, all_imfs: list, imf_index: int) -> float:
        """Compute orthogonality of IMF with other IMFs."""
        try:
            orthogonality_scores = []
            
            for i, other_imf in enumerate(all_imfs):
                if i != imf_index and len(other_imf) == len(imf):
                    # Correlation-based orthogonality
                    correlation = abs(np.corrcoef(imf, other_imf)[0, 1])
                    orthogonality = 1.0 - correlation
                    orthogonality_scores.append(orthogonality)
            
            return np.mean(orthogonality_scores) if orthogonality_scores else 1.0
        except:
            return 0.5
    
    def _cluster_frequencies(self, frequencies: list) -> list:
        """Cluster similar frequencies."""
        try:
            from sklearn.cluster import DBSCAN
            
            if len(frequencies) < 2:
                return frequencies
            
            freq_array = np.array(frequencies).reshape(-1, 1)
            
            # DBSCAN clustering
            clustering = DBSCAN(eps=0.05, min_samples=2)
            cluster_labels = clustering.fit_predict(freq_array)
            
            # Extract cluster centers
            clusters = []
            for label in set(cluster_labels):
                if label != -1:  # Exclude noise points
                    cluster_freqs = freq_array[cluster_labels == label]
                    cluster_center = np.mean(cluster_freqs)
                    clusters.append(cluster_center)
            
            return clusters
        except:
            return frequencies
    
    def _compute_cyclical_consistency(self, frequencies: np.ndarray) -> float:
        """Compute cyclical consistency of instantaneous frequencies."""
        try:
            if len(frequencies) < 5:
                return 0
            
            # Remove outliers
            q75, q25 = np.percentile(frequencies, [75, 25])
            iqr = q75 - q25
            lower_bound = q25 - 1.5 * iqr
            upper_bound = q75 + 1.5 * iqr
            
            clean_freq = frequencies[(frequencies >= lower_bound) & (frequencies <= upper_bound)]
            
            if len(clean_freq) < 3:
                return 0
            
            # Consistency based on coefficient of variation
            cv = np.std(clean_freq) / (np.abs(np.mean(clean_freq)) + 1e-10)
            consistency = 1.0 / (1.0 + cv)
            
            return max(0, min(1, consistency))
        except:
            return 0
    
    def _detect_spectrum_boundaries(self, power_spectrum: np.ndarray, freqs: np.ndarray) -> list:
        """Detect boundaries in power spectrum for EWT."""
        try:
            # Find significant peaks in power spectrum
            peaks, _ = signal.find_peaks(power_spectrum, height=np.mean(power_spectrum))
            
            if len(peaks) < 2:
                # Default boundaries
                n_bands = 3
                freq_max = np.max(np.abs(freqs[freqs >= 0]))
                boundaries = [(i * freq_max / n_bands, (i + 1) * freq_max / n_bands) 
                             for i in range(n_bands)]
                return boundaries
            
            # Create boundaries around peaks
            boundaries = []
            peak_freqs = freqs[peaks]
            peak_freqs = peak_freqs[peak_freqs >= 0]  # Keep only positive frequencies
            
            for i in range(len(peak_freqs)):
                if i == 0:
                    f_low = 0
                    f_high = (peak_freqs[i] + peak_freqs[i+1]) / 2 if i < len(peak_freqs) - 1 else peak_freqs[i] * 1.5
                elif i == len(peak_freqs) - 1:
                    f_low = (peak_freqs[i-1] + peak_freqs[i]) / 2
                    f_high = peak_freqs[i] * 1.5
                else:
                    f_low = (peak_freqs[i-1] + peak_freqs[i]) / 2
                    f_high = (peak_freqs[i] + peak_freqs[i+1]) / 2
                
                boundaries.append((f_low, f_high))
            
            return boundaries
        except:
            # Fallback: uniform frequency bands
            n_bands = 3
            freq_max = 0.5  # Nyquist frequency
            return [(i * freq_max / n_bands, (i + 1) * freq_max / n_bands) 
                   for i in range(n_bands)]
    
    def _ml_pattern_recognition(self, data: np.ndarray) -> dict:
        """Machine learning based pattern recognition for cyclical detection."""
        try:
            from sklearn.ensemble import IsolationForest
            from sklearn.preprocessing import StandardScaler
            
            # Feature extraction for cyclical pattern recognition
            features = []
            
            # Statistical features
            features.extend([
                np.mean(data), np.std(data), np.var(data),
                np.min(data), np.max(data), np.median(data)
            ])
            
            # Autocorrelation features at multiple lags
            for lag in [1, 2, 3, 5, 8, 13]:
                if lag < len(data):
                    corr = np.corrcoef(data[:-lag], data[lag:])[0,1]
                    features.append(corr if not np.isnan(corr) else 0)
            
            # Spectral features
            fft_vals = np.abs(np.fft.fft(data))[:len(data)//2]
            features.extend([
                np.argmax(fft_vals),  # Dominant frequency bin
                np.max(fft_vals),     # Peak spectral power
                np.mean(fft_vals),    # Average spectral power
                np.std(fft_vals)      # Spectral spread
            ])
            
            # Temporal structure features
            diff_data = np.diff(data)
            features.extend([
                np.mean(diff_data), np.std(diff_data),
                np.sum(diff_data > 0) / len(diff_data)  # Proportion of increases
            ])
            
            # Create feature vector
            feature_vector = np.array(features).reshape(1, -1)
            
            # Replace NaN/inf values
            feature_vector = np.nan_to_num(feature_vector, nan=0, posinf=1, neginf=-1)
            
            # Normalize features
            scaler = StandardScaler()
            try:
                feature_vector = scaler.fit_transform(feature_vector)
            except:
                pass  # Use raw features if normalization fails
            
            # Use isolation forest for anomaly-based pattern detection
            iso_forest = IsolationForest(contamination=0.1, random_state=42)
            iso_forest.fit(feature_vector)
            
            # Decision score (negative values indicate inliers/patterns)
            decision_score = iso_forest.decision_function(feature_vector)[0]
            
            # Convert to cyclical probability
            cyclical_prob = 1 / (1 + np.exp(decision_score * 5))  # Sigmoid transformation
            
            is_cyclical = cyclical_prob > 0.6
            confidence = cyclical_prob if is_cyclical else 1 - cyclical_prob
            
            return {'is_cyclical': is_cyclical, 'confidence': min(0.85, confidence)}
        except:
            return {'is_cyclical': False, 'confidence': 0.1}
    
    def _statistical_cyclical_test(self, data: np.ndarray) -> dict:
        """Statistical significance testing for cyclical patterns."""
        try:
            from scipy.stats import chi2, kstest
            
            # Ljung-Box test for serial correlation (cyclical patterns)
            def ljung_box_test(residuals, lags=10):
                n = len(residuals)
                acf_vals = []
                
                for lag in range(1, min(lags + 1, n//4)):
                    if lag < n:
                        acf = np.corrcoef(residuals[:-lag], residuals[lag:])[0,1]
                        acf_vals.append(acf if not np.isnan(acf) else 0)
                
                if not acf_vals:
                    return 0, 1
                
                # Ljung-Box statistic
                lb_stat = n * (n + 2) * sum((acf**2)/(n-lag) for lag, acf in enumerate(acf_vals, 1))
                p_value = 1 - chi2.cdf(lb_stat, len(acf_vals))
                
                return lb_stat, p_value
            
            # Test for cyclical patterns
            lb_stat, p_value = ljung_box_test(data)
            
            # Runs test for randomness
            def runs_test(data):
                median = np.median(data)
                runs = 0
                above = data > median
                
                for i in range(1, len(above)):
                    if above[i] != above[i-1]:
                        runs += 1
                
                n1 = np.sum(above)
                n2 = len(above) - n1
                
                if n1 == 0 or n2 == 0:
                    return 0, 1
                
                expected_runs = (2 * n1 * n2) / (n1 + n2) + 1
                variance = (2 * n1 * n2 * (2 * n1 * n2 - n1 - n2)) / \
                          ((n1 + n2)**2 * (n1 + n2 - 1))
                
                if variance <= 0:
                    return 0, 1
                
                z_stat = (runs - expected_runs) / np.sqrt(variance)
                p_value_runs = 2 * (1 - chi2.cdf(abs(z_stat), 1))
                
                return z_stat, p_value_runs
            
            runs_stat, runs_p = runs_test(data)
            
            # Combined statistical evidence
            cyclical_evidence = p_value < 0.05  # Ljung-Box significant
            random_evidence = runs_p > 0.05     # Runs test non-significant (structured)
            
            is_cyclical = cyclical_evidence and random_evidence
            
            # Confidence based on p-values
            confidence = (1 - p_value) * (1 - abs(runs_p - 0.5) * 2)
            confidence = max(0.1, min(0.8, confidence))
            
            return {'is_cyclical': is_cyclical, 'confidence': confidence}
        except:
            return {'is_cyclical': False, 'confidence': 0.1}
    
    def _fallback_autocorr_detection(self, data: np.ndarray) -> bool:
        """Enhanced fallback autocorrelation method."""
        try:
            n = len(data)
            if n < 10:
                return False
            
            max_lag = min(n // 3, 20)
            strong_correlations = 0
            correlation_sum = 0
            
            for lag in range(2, max_lag):
                if lag < n:
                    corr = abs(np.corrcoef(data[:-lag], data[lag:])[0,1])
                    if not np.isnan(corr):
                        correlation_sum += corr
                        if corr > 0.25:
                            strong_correlations += 1
            
            avg_correlation = correlation_sum / max(1, max_lag - 2)
            return strong_correlations >= 2 and avg_correlation > 0.15
        except:
            return False
    
    def _multiscale_morphological_edges(self, data: np.ndarray) -> np.ndarray:
        """Multi-scale morphological edge detection."""
        try:
            from scipy import ndimage
            from scipy.ndimage import grey_opening, grey_closing
            
            # Multi-scale structural elements
            scales = [1, 2, 3, 5]
            edge_maps = []
            
            for scale in scales:
                if scale < len(data) // 4:
                    # Morphological gradient
                    opened = grey_opening(data, size=scale)
                    closed = grey_closing(data, size=scale)
                    gradient = closed - opened
                    edge_maps.append(gradient)
            
            if edge_maps:
                # Combine multi-scale edges
                combined = np.mean(edge_maps, axis=0)
                return combined / (np.max(combined) + 1e-10)
            else:
                return np.abs(np.gradient(data))
        except:
            return np.abs(np.gradient(data))
    
    def _structure_tensor_edges(self, data: np.ndarray) -> np.ndarray:
        """Structure tensor based edge detection."""
        try:
            from scipy.ndimage import gaussian_filter, sobel
            
            # First derivatives
            dx = sobel(data.astype(float))
            
            # Structure tensor components
            Jxx = gaussian_filter(dx * dx, sigma=1)
            
            # Edge strength from structure tensor
            edge_strength = np.sqrt(Jxx)
            
            return edge_strength / (np.max(edge_strength) + 1e-10)
        except:
            return np.abs(np.gradient(data))
    
    def _gabor_filter_bank_edges(self, data: np.ndarray) -> np.ndarray:
        """Gabor filter bank for directional edge enhancement."""
        try:
            from scipy import signal
            
            # Gabor-like filter using complex exponential
            n = len(data)
            t = np.arange(n)
            
            # Multiple frequencies
            frequencies = [0.1, 0.2, 0.3]
            gabor_responses = []
            
            for freq in frequencies:
                if freq < 0.5:  # Nyquist limit
                    # Gabor kernel
                    sigma = min(n//8, 10)
                    kernel = np.exp(-0.5 * ((t - n//2) / sigma)**2) * \
                            np.cos(2 * np.pi * freq * (t - n//2))
                    
                    # Convolve with data
                    response = np.abs(signal.convolve(data, kernel, mode='same'))
                    gabor_responses.append(response)
            
            if gabor_responses:
                combined = np.max(gabor_responses, axis=0)
                return combined / (np.max(combined) + 1e-10)
            else:
                return np.abs(np.gradient(data))
        except:
            return np.abs(np.gradient(data))
    
    def _wavelet_multires_edges(self, data: np.ndarray) -> np.ndarray:
        """Wavelet-based multi-resolution edge detection."""
        try:
            import pywt
            
            # Wavelet decomposition
            wavelet = 'db4'
            coeffs = pywt.wavedec(data, wavelet, level=3)
            
            # Reconstruct detail coefficients (edges)
            edge_maps = []
            for i, detail in enumerate(coeffs[1:], 1):
                # Reconstruct from single detail level
                coeffs_single = [np.zeros_like(c) for c in coeffs]
                coeffs_single[i] = detail
                reconstructed = pywt.waverec(coeffs_single, wavelet)
                
                # Trim to original length
                if len(reconstructed) > len(data):
                    start = (len(reconstructed) - len(data)) // 2
                    reconstructed = reconstructed[start:start + len(data)]
                elif len(reconstructed) < len(data):
                    reconstructed = np.pad(reconstructed, 
                                         (0, len(data) - len(reconstructed)), 
                                         'constant')
                
                edge_maps.append(np.abs(reconstructed))
            
            if edge_maps:
                combined = np.sum(edge_maps, axis=0)
                return combined / (np.max(combined) + 1e-10)
            else:
                return np.abs(np.gradient(data))
        except:
            return np.abs(np.gradient(data))
    
    def _ml_edge_classification(self, original: np.ndarray, filtered: np.ndarray) -> np.ndarray:
        """Machine learning based edge classification."""
        try:
            from sklearn.cluster import KMeans
            
            # Feature extraction for each point
            features = []
            n = len(original)
            
            for i in range(n):
                point_features = []
                
                # Local gradient
                if i > 0 and i < n-1:
                    grad = abs(original[i+1] - original[i-1]) / 2
                else:
                    grad = abs(np.gradient(original)[i])
                point_features.append(grad)
                
                # Local variance
                window = 3
                start = max(0, i - window)
                end = min(n, i + window + 1)
                local_var = np.var(original[start:end])
                point_features.append(local_var)
                
                # Curvature approximation
                if i > 1 and i < n-2:
                    curvature = abs(original[i-2] - 2*original[i] + original[i+2])
                else:
                    curvature = 0
                point_features.append(curvature)
                
                # Difference from filtered
                diff_filtered = abs(original[i] - filtered[i])
                point_features.append(diff_filtered)
                
                features.append(point_features)
            
            features = np.array(features)
            
            # K-means clustering to classify edge vs non-edge points
            kmeans = KMeans(n_clusters=2, random_state=42, n_init=10)
            labels = kmeans.fit_predict(features)
            
            # Determine which cluster represents edges (higher gradient cluster)
            cluster_gradients = []
            for cluster in range(2):
                cluster_mask = labels == cluster
                if np.any(cluster_mask):
                    avg_gradient = np.mean(features[cluster_mask, 0])  # First feature is gradient
                    cluster_gradients.append(avg_gradient)
                else:
                    cluster_gradients.append(0)
            
            edge_cluster = np.argmax(cluster_gradients)
            edge_map = (labels == edge_cluster).astype(float)
            
            return edge_map
        except:
            return np.ones_like(original) * 0.5  # Uniform moderate edge probability
    
    def _anisotropic_edge_enhancement(self, filtered: np.ndarray, original: np.ndarray, 
                                    edge_mask: np.ndarray, enhancement_factor: float) -> np.ndarray:
        """Anisotropic diffusion based edge enhancement."""
        try:
            enhanced = filtered.copy()
            
            # Anisotropic diffusion parameters
            kappa = 0.25  # Conductance parameter
            gamma = 0.1   # Time step
            iterations = 5
            
            for _ in range(iterations):
                # Gradients
                grad = np.gradient(enhanced)
                
                # Conductance function
                conductance = np.exp(-(grad / kappa)**2)
                
                # Diffusion update
                laplacian = np.gradient(grad)
                enhanced = enhanced + gamma * conductance * laplacian
                
                # Preserve edges
                enhanced[edge_mask] = (1 - enhancement_factor) * enhanced[edge_mask] + \
                                     enhancement_factor * original[edge_mask]
            
            return enhanced
        except:
            # Fallback to simple blending
            enhanced = filtered.copy()
            enhanced[edge_mask] = (1 - enhancement_factor) * filtered[edge_mask] + \
                                 enhancement_factor * original[edge_mask]
            return enhanced
    
    def _nonlocal_means_edge_aware(self, enhanced: np.ndarray, original: np.ndarray, 
                                  edge_mask: np.ndarray) -> np.ndarray:
        """Non-local means filtering with edge awareness."""
        try:
            result = enhanced.copy()
            n = len(enhanced)
            
            # Non-local means parameters
            h = 0.1  # Filtering parameter
            search_window = min(7, n//4)
            patch_size = 3
            
            for i in range(n):
                if not edge_mask[i]:  # Apply only to non-edge regions
                    weights = []
                    values = []
                    
                    # Search window around current point
                    start = max(0, i - search_window)
                    end = min(n, i + search_window + 1)
                    
                    for j in range(start, end):
                        if j != i:
                            # Patch comparison
                            patch_i = enhanced[max(0, i-patch_size):min(n, i+patch_size+1)]
                            patch_j = enhanced[max(0, j-patch_size):min(n, j+patch_size+1)]
                            
                            # Make patches same length
                            min_len = min(len(patch_i), len(patch_j))
                            patch_i = patch_i[:min_len]
                            patch_j = patch_j[:min_len]
                            
                            if len(patch_i) > 0:
                                # Weighted Euclidean distance
                                distance = np.sum((patch_i - patch_j)**2) / len(patch_i)
                                weight = np.exp(-distance / (h**2))
                                
                                weights.append(weight)
                                values.append(enhanced[j])
                    
                    if weights:
                        weights = np.array(weights)
                        values = np.array(values)
                        total_weight = np.sum(weights)
                        
                        if total_weight > 0:
                            result[i] = np.sum(weights * values) / total_weight
            
            return result
        except:
            return enhanced
    
    def _structure_preserving_bilateral(self, enhanced: np.ndarray, original: np.ndarray, 
                                      edge_map: np.ndarray) -> np.ndarray:
        """Structure-preserving bilateral filtering."""
        try:
            from scipy.ndimage import gaussian_filter1d
            
            result = enhanced.copy()
            n = len(enhanced)
            
            # Bilateral filtering parameters
            sigma_space = 2.0
            sigma_range = 0.1
            
            for i in range(n):
                # Spatial weights (Gaussian)
                spatial_weights = np.exp(-0.5 * ((np.arange(n) - i) / sigma_space)**2)
                
                # Range weights (based on intensity difference)
                intensity_diff = np.abs(enhanced - enhanced[i])
                range_weights = np.exp(-0.5 * (intensity_diff / sigma_range)**2)
                
                # Structure weights (based on edge map)
                structure_weights = 1.0 - edge_map * 0.5  # Reduce filtering near edges
                
                # Combined weights
                combined_weights = spatial_weights * range_weights * structure_weights
                
                # Normalize
                total_weight = np.sum(combined_weights)
                if total_weight > 0:
                    result[i] = np.sum(combined_weights * enhanced) / total_weight
            
            return result
        except:
            return enhanced
    
    def _remove_enhancement_artifacts(self, enhanced: np.ndarray, original: np.ndarray, 
                                    filtered: np.ndarray) -> np.ndarray:
        """Remove artifacts from enhancement process."""
        try:
            # Detect and correct outliers
            result = enhanced.copy()
            
            # Statistical outlier detection
            q75, q25 = np.percentile(original, [75, 25])
            iqr = q75 - q25
            lower_bound = q25 - 1.5 * iqr
            upper_bound = q75 + 1.5 * iqr
            
            # Replace outliers with filtered values
            outlier_mask = (result < lower_bound) | (result > upper_bound)
            result[outlier_mask] = filtered[outlier_mask]
            
            # Smooth discontinuities
            diff = np.abs(np.diff(result))
            threshold = np.percentile(diff, 90)
            
            for i in range(1, len(result)-1):
                if diff[i-1] > threshold:
                    # Local smoothing
                    result[i] = 0.5 * result[i] + 0.25 * (result[i-1] + result[i+1])
            
            return result
        except:
            return enhanced
    
    def _fallback_edge_enhancement(self, filtered: np.ndarray, original: np.ndarray, 
                                  enhancement_factor: float) -> np.ndarray:
        """Robust fallback edge enhancement."""
        try:
            # Simple gradient-based edge detection
            edge_strength = np.abs(np.gradient(original))
            threshold = np.percentile(edge_strength, 70)
            edge_mask = edge_strength > threshold
            
            enhanced = filtered.copy()
            enhanced[edge_mask] = (1 - enhancement_factor) * filtered[edge_mask] + \
                                 enhancement_factor * original[edge_mask]
            
            return enhanced
        except:
            return filtered
    
    def _apply_seasonal_decomposition(self, values: List[float]) -> List[float]:
        """
        Advanced seasonal decomposition using multiple methods:
        - STL (Seasonal and Trend decomposition using Loess)
        - X-13ARIMA-SEATS when appropriate
        - Empirical Mode Decomposition for complex patterns
        - Custom adaptive seasonal detection
        """
        try:
            from scipy import signal
            from scipy.fft import fft, ifft, fftfreq
            from scipy.stats import pearsonr
            
            if len(values) < 12:  # Need minimum data for seasonal analysis
                return values
                
            data = np.array(values, dtype=np.float64)
            n = len(data)
            
            # Step 1: Detect seasonality automatically
            seasonal_info = self._detect_seasonality(data)
            
            if not seasonal_info['has_seasonality']:
                # No significant seasonality detected, return detrended signal
                return self._remove_trend_component(data).tolist()
            
            period = seasonal_info['dominant_period']
            
            # Step 2: Choose decomposition method based on signal characteristics
            if n >= 3 * period and period <= n // 3:
                # Use advanced STL-like decomposition
                decomposed = self._advanced_stl_decomposition(data, period)
            elif n >= 100:
                # Use EMD-based seasonal decomposition
                decomposed = self._emd_seasonal_decomposition(data, period)
            else:
                # Use Fourier-based decomposition for short series
                decomposed = self._fourier_seasonal_decomposition(data, period)
            
            # Step 3: Extract seasonal component with adaptive strength
            seasonal_component = decomposed.get('seasonal', np.zeros_like(data))
            trend_component = decomposed.get('trend', np.zeros_like(data))
            residual_component = decomposed.get('residual', data - seasonal_component - trend_component)
            
            # Step 4: Apply intelligent component selection
            seasonal_strength = self._calculate_seasonal_strength(
                seasonal_component, data - seasonal_component
            )
            
            if seasonal_strength > 0.3:
                # Strong seasonality: return deseasonalized signal (trend + residual)
                result = trend_component + residual_component
            elif seasonal_strength > 0.1:
                # Moderate seasonality: attenuate seasonal component
                attenuated_seasonal = seasonal_component * (1 - seasonal_strength)
                result = data - attenuated_seasonal
            else:
                # Weak seasonality: minimal processing
                result = data - 0.1 * seasonal_component
            
            # Step 5: Post-processing and quality control
            result = self._post_process_decomposition(result, data)
            
            return result.tolist()
            
        except Exception as e:
            # Fallback: Simple moving average detrending
            try:
                data = np.array(values, dtype=np.float64)
                if len(data) < 3:
                    return values
                    
                # Estimate period from autocorrelation
                period = self._estimate_period_fallback(data)
                
                # Simple seasonal removal using moving averages
                if period > 1:
                    seasonal = self._extract_seasonal_pattern(data, period)
                    deseasonalized = data - seasonal
                    return deseasonalized.tolist()
                else:
                    return values
            except:
                return values

    def _detect_seasonality(self, data: np.ndarray) -> Dict[str, Any]:
        """Advanced seasonality detection using multiple methods."""
        n = len(data)
        
        # Method 1: Autocorrelation analysis
        max_lag = min(n // 3, 100)
        autocorr_peaks = []
        
        for lag in range(2, max_lag):
            if lag < n:
                corr = self._calculate_autocorrelation(data.tolist(), lag)
                if corr > 0.3:  # Significant correlation
                    autocorr_peaks.append((lag, corr))
        
        # Method 2: FFT peak detection
        fft_data = np.abs(fft(data - np.mean(data)))
        freqs = fftfreq(n)[:n//2]
        power_spectrum = fft_data[:n//2]
        
        # Find dominant frequencies
        peak_indices = signal.find_peaks(power_spectrum, 
                                       height=np.max(power_spectrum) * 0.1,
                                       distance=max(1, n // 50))[0]
        
        fft_periods = []
        for idx in peak_indices:
            if freqs[idx] > 0:
                period = 1 / freqs[idx]
                if 2 <= period <= n // 3:
                    fft_periods.append((int(period), power_spectrum[idx]))
        
        # Method 3: Statistical tests for seasonality
        kpss_stat = self._kpss_seasonality_test(data)
        
        # Combine evidence
        has_seasonality = (len(autocorr_peaks) > 0 or len(fft_periods) > 0) and kpss_stat > 0.1
        
        # Select dominant period
        if autocorr_peaks and fft_periods:
            # Combine evidence from both methods
            autocorr_periods = [p[0] for p in sorted(autocorr_peaks, key=lambda x: x[1], reverse=True)]
            fft_period_vals = [p[0] for p in sorted(fft_periods, key=lambda x: x[1], reverse=True)]
            
            # Find consensus
            for ap in autocorr_periods[:3]:
                for fp in fft_period_vals[:3]:
                    if abs(ap - fp) <= max(1, min(ap, fp) * 0.1):
                        dominant_period = int((ap + fp) / 2)
                        break
                else:
                    continue
                break
            else:
                dominant_period = autocorr_periods[0] if autocorr_peaks else fft_period_vals[0]
        elif autocorr_peaks:
            dominant_period = autocorr_peaks[0][0]
        elif fft_periods:
            dominant_period = fft_periods[0][0]
        else:
            dominant_period = min(12, n // 4)  # Default assumption
        
        return {
            'has_seasonality': has_seasonality,
            'dominant_period': dominant_period,
            'autocorr_peaks': autocorr_peaks,
            'fft_periods': fft_periods,
            'strength': kpss_stat
        }
    
    def _advanced_stl_decomposition(self, data: np.ndarray, period: int) -> Dict[str, np.ndarray]:
        """STL-like seasonal decomposition with Loess smoothing."""
        n = len(data)
        
        # Initialize components
        seasonal = np.zeros_like(data)
        trend = np.zeros_like(data)
        
        # Iterative seasonal-trend decomposition
        residual = data.copy()
        
        for iteration in range(3):  # Multiple iterations for convergence
            # Step 1: Seasonal smoothing
            seasonal_subseries = self._extract_seasonal_subseries(residual + seasonal, period)
            seasonal = self._smooth_seasonal_subseries(seasonal_subseries, period, n)
            
            # Step 2: Trend smoothing with adaptive bandwidth
            deseasonalized = data - seasonal
            trend = self._loess_smoothing(deseasonalized, bandwidth=0.3)
            
            # Update residual
            residual = data - seasonal - trend
            
            # Convergence check
            if iteration > 0 and np.std(residual - prev_residual) < np.std(data) * 0.01:
                break
            prev_residual = residual.copy()
        
        return {
            'seasonal': seasonal,
            'trend': trend,
            'residual': residual
        }
    
    def _emd_seasonal_decomposition(self, data: np.ndarray, period: int) -> Dict[str, np.ndarray]:
        """Empirical Mode Decomposition for seasonal extraction."""
        # Use existing EMD implementation from the class
        try:
            emd_result = self.empirical_mode_decomposition(data)
            imfs = emd_result.get('IMFs', [data])
            
            if len(imfs) < 2:
                return {'seasonal': np.zeros_like(data), 'trend': data, 'residual': np.zeros_like(data)}
            
            # Identify seasonal and trend components based on periods
            seasonal_imfs = []
            trend_imfs = []
            
            for i, imf in enumerate(imfs):
                imf_period = self._estimate_imf_period(imf)
                if abs(imf_period - period) <= max(1, period * 0.2):
                    seasonal_imfs.append(imf)
                elif imf_period > 2 * period:
                    trend_imfs.append(imf)
            
            seasonal = np.sum(seasonal_imfs, axis=0) if seasonal_imfs else np.zeros_like(data)
            trend = np.sum(trend_imfs, axis=0) if trend_imfs else np.mean(data) * np.ones_like(data)
            residual = data - seasonal - trend
            
            return {
                'seasonal': seasonal,
                'trend': trend,
                'residual': residual
            }
        except:
            return self._fourier_seasonal_decomposition(data, period)
    
    def _fourier_seasonal_decomposition(self, data: np.ndarray, period: int) -> Dict[str, np.ndarray]:
        """Fourier-based seasonal decomposition."""
        n = len(data)
        
        # FFT decomposition
        fft_data = fft(data - np.mean(data))
        freqs = fftfreq(n)
        
        # Identify seasonal frequencies
        seasonal_freq = 1.0 / period
        seasonal_tolerance = 1.0 / (2 * period)
        
        seasonal_mask = np.abs(np.abs(freqs) - seasonal_freq) <= seasonal_tolerance
        trend_mask = np.abs(freqs) <= 1.0 / (3 * period)
        
        # Extract components
        seasonal_fft = fft_data * seasonal_mask
        trend_fft = fft_data * trend_mask
        
        seasonal = np.real(ifft(seasonal_fft))
        trend = np.real(ifft(trend_fft)) + np.mean(data)
        residual = data - seasonal - trend
        
        return {
            'seasonal': seasonal,
            'trend': trend,
            'residual': residual
        }
    
    def _calculate_seasonal_strength(self, seasonal: np.ndarray, remainder: np.ndarray) -> float:
        """Calculate the strength of seasonality in the decomposition."""
        try:
            seasonal_var = np.var(seasonal)
            remainder_var = np.var(remainder)
            total_var = seasonal_var + remainder_var
            
            if total_var == 0:
                return 0.0
                
            strength = seasonal_var / total_var
            return min(1.0, max(0.0, strength))
        except:
            return 0.0
    
    def _post_process_decomposition(self, result: np.ndarray, original: np.ndarray) -> np.ndarray:
        """Post-process decomposed signal for quality assurance."""
        # Preserve original signal statistics
        result_std = np.std(result)
        original_std = np.std(original)
        
        if result_std > 0 and original_std > 0:
            # Scale to preserve variance within reasonable bounds
            scale_factor = min(2.0, original_std / result_std)
            result = result * scale_factor
        
        # Remove extreme outliers
        result_median = np.median(result)
        result_mad = np.median(np.abs(result - result_median))
        
        if result_mad > 0:
            outlier_threshold = 3.5 * result_mad
            outlier_mask = np.abs(result - result_median) > outlier_threshold
            result[outlier_mask] = result_median + np.sign(result[outlier_mask] - result_median) * outlier_threshold
        
        return result
    
    def _estimate_period_fallback(self, data: np.ndarray) -> int:
        """Simple period estimation fallback."""
        n = len(data)
        max_period = min(n // 3, 50)
        
        best_period = 1
        best_score = 0
        
        for period in range(2, max_period + 1):
            score = 0
            count = 0
            
            for i in range(n - period):
                score += abs(data[i] - data[i + period])
                count += 1
            
            if count > 0:
                avg_diff = score / count
                period_score = 1.0 / (1.0 + avg_diff / np.std(data))
                
                if period_score > best_score:
                    best_score = period_score
                    best_period = period
        
        return best_period
    
    def _extract_seasonal_pattern(self, data: np.ndarray, period: int) -> np.ndarray:
        """Extract seasonal pattern using moving averages."""
        n = len(data)
        seasonal = np.zeros_like(data)
        
        # Calculate seasonal indices
        for phase in range(period):
            indices = list(range(phase, n, period))
            if len(indices) >= 2:
                phase_values = data[indices]
                phase_mean = np.mean(phase_values)
                seasonal[indices] = phase_mean - np.mean(data)
        
        return seasonal
    
    # Additional helper methods for advanced decomposition
    def _kpss_seasonality_test(self, data: np.ndarray) -> float:
        """Simplified KPSS-like test for seasonality presence."""
        n = len(data)
        if n < 10:
            return 0.0
            
        # Calculate cumulative sum of deviations
        cumsum = np.cumsum(data - np.mean(data))
        
        # Estimate variance
        variance_est = np.var(np.diff(data))
        
        if variance_est == 0:
            return 0.0
        
        # KPSS-like statistic
        kpss_stat = np.sum(cumsum**2) / (n**2 * variance_est)
        
        return min(1.0, kpss_stat)
    
    def _extract_seasonal_subseries(self, data: np.ndarray, period: int) -> Dict[int, List[float]]:
        """Extract subseries for each seasonal phase."""
        subseries = {phase: [] for phase in range(period)}
        
        for i, value in enumerate(data):
            phase = i % period
            subseries[phase].append(value)
        
        return subseries
    
    def _smooth_seasonal_subseries(self, subseries: Dict[int, List[float]], 
                                   period: int, data_length: int) -> np.ndarray:
        """Smooth seasonal subseries and reconstruct seasonal component."""
        seasonal = np.zeros(data_length)
        
        for phase in range(period):
            phase_data = np.array(subseries[phase])
            if len(phase_data) > 1:
                # Simple smoothing for each phase
                smoothed_phase = self._loess_smoothing(phase_data, bandwidth=0.3)
                
                # Map back to original indices
                phase_indices = list(range(phase, data_length, period))[:len(smoothed_phase)]
                seasonal[phase_indices] = smoothed_phase
            elif len(phase_data) == 1:
                phase_indices = list(range(phase, data_length, period))
                seasonal[phase_indices] = phase_data[0]
        
        return seasonal
    
    def _loess_smoothing(self, data: np.ndarray, bandwidth: float = 0.3) -> np.ndarray:
        """Simple Loess-like local regression smoothing."""
        n = len(data)
        smoothed = np.zeros_like(data)
        window_size = max(1, int(bandwidth * n))
        
        for i in range(n):
            # Define local window
            start = max(0, i - window_size // 2)
            end = min(n, i + window_size // 2 + 1)
            
            # Local linear regression (simplified)
            window_data = data[start:end]
            window_indices = np.arange(start, end)
            
            if len(window_data) >= 2:
                # Fit local linear trend
                coeffs = np.polyfit(window_indices, window_data, 1)
                smoothed[i] = coeffs[0] * i + coeffs[1]
            else:
                smoothed[i] = np.mean(window_data)
        
        return smoothed
    
    def _estimate_imf_period(self, imf: np.ndarray) -> float:
        """Estimate the dominant period of an Intrinsic Mode Function."""
        try:
            # Use zero-crossing method
            zero_crossings = np.where(np.diff(np.signbit(imf)))[0]
            
            if len(zero_crossings) >= 4:
                # Average period between zero crossings
                periods = np.diff(zero_crossings) * 2  # Full cycle = 2 half-cycles
                return np.median(periods)
            else:
                # Fallback: use FFT
                fft_imf = np.abs(fft(imf))
                freqs = fftfreq(len(imf))
                dominant_freq_idx = np.argmax(fft_imf[1:len(imf)//2]) + 1
                
                if freqs[dominant_freq_idx] > 0:
                    return 1.0 / freqs[dominant_freq_idx]
                else:
                    return len(imf) / 4  # Default assumption
        except:
            return len(imf) / 4
    
    def _remove_trend_component(self, data: np.ndarray) -> np.ndarray:
        """Remove trend component using robust methods."""
        n = len(data)
        
        if n <= 3:
            return data - np.mean(data)
        
        # Use robust trend estimation
        x = np.arange(n)
        
        # Fit polynomial trend (degree based on data length)
        degree = min(3, max(1, n // 20))
        trend_coeffs = np.polyfit(x, data, degree)
        trend = np.polyval(trend_coeffs, x)
        
        return data - trend
    
    def _apply_lowpass_filter(self, values: List[float]) -> List[float]:
        """
        Advanced low-pass filter with adaptive filtering techniques:
        - Multi-stage Butterworth filters for optimal smoothness
        - Savitzky-Golay filters for edge-preserving smoothing  
        - Adaptive Wiener filtering for noise reduction
        - Kalman-based filtering for temporal consistency
        - Automatic cutoff frequency optimization
        """
        try:
            from scipy import signal
            from scipy.fft import fft, ifft, fftfreq
            
            if len(values) < 4:
                return values
                
            data = np.array(values, dtype=np.float64)
            n = len(data)
            
            # Adaptive parameter selection
            filter_params = self._optimize_lowpass_parameters(data)
            cutoff_freq = filter_params['cutoff_frequency']
            filter_type = filter_params['filter_type']
            
            # Determine sampling parameters
            fs = max(100, n * 2)  # Adaptive sampling rate
            nyquist = fs / 2.0
            normalized_cutoff = min(0.49, max(0.01, cutoff_freq / nyquist))
            
            # Apply selected filtering method
            if filter_type == 'butterworth' and n >= 100:
                filtered = self._butterworth_lowpass(data, normalized_cutoff)
            elif filter_type == 'savgol' and n >= 20:
                filtered = self._savitzky_golay_filter(data, filter_params)
            elif filter_type == 'wiener' and n >= 50:
                filtered = self._adaptive_wiener_filter(data, filter_params)
            elif filter_type == 'kalman' and n >= 10:
                filtered = self._kalman_based_smoothing(data, filter_params)
            else:
                # Frequency domain method for fallback
                filtered = self._frequency_domain_lowpass(data, normalized_cutoff)
            
            # Post-processing quality control
            filtered = self._lowpass_quality_control(filtered, data, filter_params)
            
            return filtered.tolist()
            
        except Exception as e:
            # Multi-stage fallback with increasing sophistication
            try:
                data = np.array(values, dtype=np.float64)
                n = len(data)
                
                # Stage 1: Adaptive moving average
                if n >= 20:
                    # Variable window size based on local characteristics
                    filtered = self._adaptive_moving_average(data)
                elif n >= 5:
                    # Simple moving average with optimal window
                    optimal_window = max(3, min(n // 3, int(np.sqrt(n))))
                    filtered = self._apply_moving_average(data.tolist(), optimal_window)
                else:
                    # Very short signals - minimal smoothing
                    filtered = data.tolist()
                
                return filtered
                
            except:
                # Final fallback - basic moving average
                try:
                    window = max(1, min(len(values) // 4, 5))
                    return self._apply_moving_average(values, window)
                except:
                    return values

    def _optimize_lowpass_parameters(self, data: np.ndarray) -> Dict[str, Any]:
        """Optimize low-pass filter parameters based on signal analysis."""
        try:
            n = len(data)
            
            # Signal characteristic analysis
            noise_level = self._estimate_signal_noise(data)
            smoothness = self._calculate_signal_smoothness(data)
            stationarity = self._assess_stationarity(data)
            spectral_content = self._analyze_spectral_content(data)
            
            # Cutoff frequency optimization
            cutoff_freq = self._optimize_cutoff_frequency(data, spectral_content)
            
            # Filter type selection based on characteristics
            if stationarity > 0.8 and noise_level < 0.2:
                filter_type = 'butterworth'  # Clean, stationary signals
            elif smoothness < 0.3:
                filter_type = 'savgol'  # Preserve edges and features
            elif noise_level > 0.5:
                filter_type = 'wiener'   # Noisy signals
            elif n >= 50:
                filter_type = 'kalman'   # Temporal modeling
            else:
                filter_type = 'frequency'  # General purpose
            
            return {
                'cutoff_frequency': cutoff_freq,
                'filter_type': filter_type,
                'noise_level': noise_level,
                'smoothness': smoothness,
                'stationarity': stationarity,
                'signal_length': n,
                'savgol_window': min(max(5, n // 10), 51),
                'savgol_order': min(3, (min(max(5, n // 10), 51) - 1) // 2),
                'wiener_noise_var': noise_level ** 2
            }
            
        except:
            return {
                'cutoff_frequency': 0.1,
                'filter_type': 'frequency',
                'noise_level': 0.1,
                'smoothness': 0.5,
                'stationarity': 0.5,
                'signal_length': len(data),
                'savgol_window': 5,
                'savgol_order': 2,
                'wiener_noise_var': 0.01
            }
    
    def _butterworth_lowpass(self, data: np.ndarray, normalized_cutoff: float) -> np.ndarray:
        """Multi-stage Butterworth low-pass filtering."""
        try:
            from scipy import signal
            
            # Design cascaded Butterworth filters for optimal response
            order = min(8, max(2, len(data) // 50))  # Adaptive order
            
            # Stage 1: Primary filtering
            sos1 = signal.butter(order // 2, normalized_cutoff, btype='low', output='sos')
            filtered1 = signal.sosfiltfilt(sos1, data)
            
            # Stage 2: Secondary smoothing (lower order, slightly higher cutoff)
            if len(data) > 100:
                cutoff2 = min(0.49, normalized_cutoff * 1.2)
                sos2 = signal.butter(2, cutoff2, btype='low', output='sos')
                filtered = signal.sosfiltfilt(sos2, filtered1)
            else:
                filtered = filtered1
            
            return filtered
            
        except:
            # Fallback to simple Butterworth
            from scipy import signal
            sos = signal.butter(4, normalized_cutoff, btype='low', output='sos')
            return signal.sosfiltfilt(sos, data)
    
    def _savitzky_golay_filter(self, data: np.ndarray, params: Dict[str, Any]) -> np.ndarray:
        """Savitzky-Golay filter with adaptive parameters."""
        try:
            from scipy import signal
            
            window_length = params.get('savgol_window', 5)
            polyorder = params.get('savgol_order', 2)
            
            # Ensure valid parameters
            if window_length % 2 == 0:
                window_length += 1
            window_length = min(window_length, len(data))
            polyorder = min(polyorder, window_length - 1)
            
            # Apply Savitzky-Golay filtering
            if window_length >= 3 and polyorder >= 1:
                filtered = signal.savgol_filter(data, window_length, polyorder, mode='nearest')
            else:
                # Fallback for edge cases
                filtered = data
            
            return filtered
            
        except:
            # Manual implementation fallback
            return self._manual_savgol(data, params.get('savgol_window', 5))
    
    def _adaptive_wiener_filter(self, data: np.ndarray, params: Dict[str, Any]) -> np.ndarray:
        """Adaptive Wiener filtering for noise reduction."""
        try:
            n = len(data)
            noise_var = params.get('wiener_noise_var', 0.01)
            
            # Estimate signal power spectral density
            signal_fft = fft(data - np.mean(data))
            signal_power = np.abs(signal_fft) ** 2
            
            # Adaptive noise estimation
            noise_power = noise_var * np.mean(signal_power)
            
            # Wiener filter design
            wiener_response = signal_power / (signal_power + noise_power)
            
            # Apply filter in frequency domain
            filtered_fft = signal_fft * wiener_response
            filtered = np.real(ifft(filtered_fft)) + np.mean(data)
            
            return filtered
            
        except:
            # Fallback to moving average
            window = max(3, len(data) // 15)
            return self._apply_moving_average(data.tolist(), window)
    
    def _kalman_based_smoothing(self, data: np.ndarray, params: Dict[str, Any]) -> np.ndarray:
        """Kalman filter-based smoothing for temporal consistency."""
        try:
            n = len(data)
            noise_level = params.get('noise_level', 0.1)
            
            # Simple Kalman filter for smoothing
            # State: [position, velocity]
            # Measurement: position only
            
            # Filter parameters
            process_noise = noise_level * 0.1
            measurement_noise = noise_level
            
            # Initialize
            x = np.array([data[0], 0.0])  # [position, velocity]
            P = np.array([[1.0, 0.0], [0.0, 1.0]])  # Covariance
            
            # System matrices
            F = np.array([[1.0, 1.0], [0.0, 1.0]])  # State transition
            H = np.array([[1.0, 0.0]])  # Measurement model
            Q = np.array([[process_noise, 0.0], [0.0, process_noise]])  # Process noise
            R = np.array([[measurement_noise]])  # Measurement noise
            
            filtered = np.zeros(n)
            
            for i in range(n):
                # Predict
                x = F @ x
                P = F @ P @ F.T + Q
                
                # Update
                z = np.array([data[i]])  # Measurement
                y = z - H @ x  # Innovation
                S = H @ P @ H.T + R  # Innovation covariance
                K = P @ H.T @ np.linalg.inv(S)  # Kalman gain
                
                x = x + K @ y
                P = (np.eye(2) - K @ H) @ P
                
                filtered[i] = x[0]
            
            return filtered
            
        except:
            # Exponential smoothing fallback
            alpha = max(0.1, min(0.9, 1 - params.get('smoothness', 0.5)))
            smoothed = np.zeros_like(data)
            smoothed[0] = data[0]
            
            for i in range(1, len(data)):
                smoothed[i] = alpha * data[i] + (1 - alpha) * smoothed[i-1]
            
            return smoothed
    
    def _frequency_domain_lowpass(self, data: np.ndarray, normalized_cutoff: float) -> np.ndarray:
        """Frequency domain low-pass filtering with optimal windowing."""
        try:
            n = len(data)
            
            # FFT with zero padding for better frequency resolution
            padded_n = 2 ** int(np.ceil(np.log2(n * 2)))
            data_padded = np.pad(data - np.mean(data), (0, padded_n - n), mode='constant')
            
            fft_data = fft(data_padded)
            freqs = fftfreq(padded_n)
            
            # Design smooth low-pass mask
            mask = np.ones(padded_n, dtype=complex)
            transition_width = 0.05  # 5% transition band
            
            for i, freq in enumerate(freqs):
                abs_freq = abs(freq)
                if abs_freq > normalized_cutoff + transition_width:
                    mask[i] = 0.0
                elif abs_freq > normalized_cutoff - transition_width:
                    # Smooth transition using raised cosine
                    transition_pos = (abs_freq - (normalized_cutoff - transition_width)) / (2 * transition_width)
                    mask[i] = 0.5 * (1 + np.cos(np.pi * transition_pos))
            
            # Apply filter and extract original length
            filtered_fft = fft_data * mask
            filtered_padded = np.real(ifft(filtered_fft))
            filtered = filtered_padded[:n] + np.mean(data)
            
            return filtered
            
        except:
            # Simple FFT filtering
            fft_data = np.fft.fft(data)
            freqs = np.fft.fftfreq(len(data))
            mask = np.abs(freqs) <= normalized_cutoff
            return np.real(np.fft.ifft(fft_data * mask))
    
    def _lowpass_quality_control(self, filtered: np.ndarray, original: np.ndarray, 
                                params: Dict[str, Any]) -> np.ndarray:
        """Quality control and post-processing for low-pass filtered signals."""
        try:
            # Preserve DC component
            original_mean = np.mean(original)
            filtered_mean = np.mean(filtered)
            filtered = filtered - filtered_mean + original_mean
            
            # Amplitude scaling control
            original_std = np.std(original)
            filtered_std = np.std(filtered)
            
            if filtered_std > 0:
                # Conservative scaling to avoid over-smoothing
                scale_factor = min(1.2, max(0.5, original_std / filtered_std))
                filtered = (filtered - filtered_mean) * scale_factor + original_mean
            
            # Outlier protection
            outlier_threshold = 3 * original_std
            outlier_mask = np.abs(filtered - original_mean) > outlier_threshold
            
            if np.any(outlier_mask):
                filtered[outlier_mask] = np.sign(filtered[outlier_mask] - original_mean) * outlier_threshold + original_mean
            
            # Edge preservation for important features
            if params.get('smoothness', 0.5) < 0.3:  # Preserve edges for non-smooth signals
                edge_weight = 0.3
                filtered = (1 - edge_weight) * filtered + edge_weight * original
            
            return filtered
            
        except:
            return filtered
    
    # Helper methods for signal analysis
    def _estimate_signal_noise(self, data: np.ndarray) -> float:
        """Estimate noise level in the signal."""
        try:
            # Method 1: High-frequency content
            diff2 = np.diff(data, n=2)
            noise_est1 = np.std(diff2) / np.sqrt(6)
            
            # Method 2: Robust scale estimation
            mad = np.median(np.abs(data - np.median(data)))
            noise_est2 = mad * 1.4826 / np.std(data) if np.std(data) > 0 else 0
            
            # Combined estimate
            return min(1.0, max(0.01, (noise_est1 + noise_est2) / 2))
            
        except:
            return 0.1
    
    def _calculate_signal_smoothness(self, data: np.ndarray) -> float:
        """Calculate signal smoothness metric."""
        try:
            # Based on second derivatives
            second_diff = np.diff(data, n=2)
            smoothness = 1.0 / (1.0 + np.std(second_diff) / (np.std(data) + 1e-10))
            return max(0.0, min(1.0, smoothness))
        except:
            return 0.5
    
    def _assess_stationarity(self, data: np.ndarray) -> float:
        """Assess signal stationarity using simple statistics."""
        try:
            n = len(data)
            if n < 20:
                return 0.5
                
            # Split into segments and compare statistics
            n_segments = min(5, n // 10)
            segment_size = n // n_segments
            
            segment_means = []
            segment_vars = []
            
            for i in range(n_segments):
                start = i * segment_size
                end = (i + 1) * segment_size if i < n_segments - 1 else n
                segment = data[start:end]
                
                segment_means.append(np.mean(segment))
                segment_vars.append(np.var(segment))
            
            # Coefficient of variation for means and variances
            mean_stability = 1.0 / (1.0 + np.std(segment_means) / (np.mean(segment_means) + 1e-10))
            var_stability = 1.0 / (1.0 + np.std(segment_vars) / (np.mean(segment_vars) + 1e-10))
            
            stationarity = (mean_stability + var_stability) / 2
            return max(0.0, min(1.0, stationarity))
            
        except:
            return 0.5
    
    def _analyze_spectral_content(self, data: np.ndarray) -> Dict[str, float]:
        """Analyze spectral content of the signal."""
        try:
            fft_data = np.abs(fft(data - np.mean(data)))
            freqs = fftfreq(len(data))[:len(data)//2]
            power_spectrum = fft_data[:len(data)//2]
            
            if np.sum(power_spectrum) == 0:
                return {'centroid': 0.1, 'bandwidth': 0.2, 'rolloff': 0.15}
            
            # Spectral centroid
            centroid = np.sum(freqs * power_spectrum) / np.sum(power_spectrum)
            
            # Spectral bandwidth
            bandwidth = np.sqrt(np.sum((freqs - centroid) ** 2 * power_spectrum) / np.sum(power_spectrum))
            
            # Spectral rolloff (95% energy point)
            cumulative_energy = np.cumsum(power_spectrum)
            total_energy = cumulative_energy[-1]
            rolloff_idx = np.argmax(cumulative_energy >= 0.95 * total_energy)
            rolloff = freqs[rolloff_idx] if rolloff_idx < len(freqs) else freqs[-1]
            
            return {
                'centroid': abs(centroid),
                'bandwidth': bandwidth,
                'rolloff': abs(rolloff)
            }
            
        except:
            return {'centroid': 0.1, 'bandwidth': 0.2, 'rolloff': 0.15}
    
    def _optimize_cutoff_frequency(self, data: np.ndarray, spectral_info: Dict[str, float]) -> float:
        """Optimize cutoff frequency based on spectral analysis."""
        try:
            # Multiple criteria for cutoff selection
            centroid = spectral_info['centroid']
            bandwidth = spectral_info['bandwidth']
            rolloff = spectral_info['rolloff']
            
            # Conservative approach: preserve main signal content
            cutoff_candidates = [
                centroid + bandwidth,  # Include main content plus some bandwidth
                rolloff * 0.8,         # 80% of energy rolloff point
                0.3,                   # Conservative default
            ]
            
            # Remove invalid candidates
            cutoff_candidates = [c for c in cutoff_candidates if 0.01 <= c <= 0.45]
            
            if cutoff_candidates:
                optimal_cutoff = np.median(cutoff_candidates)
            else:
                optimal_cutoff = 0.15  # Safe default
                
            return max(0.01, min(0.4, optimal_cutoff))
            
        except:
            return 0.15
    
    def _adaptive_moving_average(self, data: np.ndarray) -> np.ndarray:
        """Adaptive moving average with variable window size."""
        try:
            n = len(data)
            filtered = np.zeros_like(data)
            
            for i in range(n):
                # Adaptive window size based on local variability
                local_start = max(0, i - 10)
                local_end = min(n, i + 11)
                local_data = data[local_start:local_end]
                local_var = np.var(local_data)
                
                # Variable window: smaller for high variability
                base_window = max(3, n // 20)
                adaptive_window = max(3, int(base_window * (1 / (1 + local_var))))
                
                # Apply moving average
                window_start = max(0, i - adaptive_window // 2)
                window_end = min(n, i + adaptive_window // 2 + 1)
                filtered[i] = np.mean(data[window_start:window_end])
            
            return filtered
            
        except:
            window = max(3, len(data) // 10)
            return np.convolve(data, np.ones(window)/window, mode='same')
    
    def _manual_savgol(self, data: np.ndarray, window_length: int) -> np.ndarray:
        """Manual Savitzky-Golay implementation fallback."""
        try:
            n = len(data)
            if window_length >= n:
                return data
                
            half_window = window_length // 2
            filtered = np.zeros_like(data)
            
            for i in range(n):
                start = max(0, i - half_window)
                end = min(n, i + half_window + 1)
                
                # Local polynomial fit (order 2)
                x_local = np.arange(start, end) - i
                y_local = data[start:end]
                
                if len(y_local) >= 3:
                    coeffs = np.polyfit(x_local, y_local, min(2, len(y_local) - 1))
                    filtered[i] = coeffs[-1]  # Constant term = value at center
                else:
                    filtered[i] = np.mean(y_local)
            
            return filtered
            
        except:
            return data
    
    # Advanced pattern detection methods with multi-scale analysis
    def _detect_spike_patterns(self, values: List[float]) -> List[Dict[str, Any]]:
        """
        Advanced spike detection using multi-scale wavelet analysis,
        statistical modeling, and machine learning-based validation.
        """
        try:
            patterns = []
            values = np.array(values)
            
            if len(values) < 10:
                return patterns
            
            # Multi-scale wavelet decomposition for spike detection
            from scipy import signal
            from scipy.stats import zscore, normaltest, jarque_bera
            
            # Wavelet-based multi-resolution analysis
            scales = np.arange(1, min(32, len(values)//4))
            coefficients, frequencies = signal.cwt(values, signal.ricker, scales)
            
            # Adaptive threshold based on robust statistics
            mad = np.median(np.abs(values - np.median(values)))
            robust_std = 1.4826 * mad
            
            # Multi-threshold analysis with different sensitivity levels
            thresholds = {
                'conservative': np.median(values) + 4 * robust_std,
                'moderate': np.median(values) + 3 * robust_std,
                'sensitive': np.median(values) + 2.5 * robust_std
            }
            
            # Statistical anomaly detection using multiple methods
            z_scores = zscore(values)
            modified_z_scores = 0.6745 * (values - np.median(values)) / mad
            
            # Isolation Forest for outlier detection
            from sklearn.ensemble import IsolationForest
            isolation_forest = IsolationForest(contamination=0.05, random_state=42)
            outlier_scores = isolation_forest.decision_function(values.reshape(-1, 1))
            
            # Local outlier factor
            from sklearn.neighbors import LocalOutlierFactor
            lof = LocalOutlierFactor(n_neighbors=min(20, len(values)//3))
            lof_scores = lof.fit_predict(values.reshape(-1, 1))
            
            # Advanced spike characteristics extraction
            for i, val in enumerate(values):
                spike_detected = False
                confidence = 0.0
                detection_methods = []
                
                # Multiple detection criteria
                if abs(z_scores[i]) > 3:
                    spike_detected = True
                    confidence += 0.3
                    detection_methods.append('zscore')
                
                if abs(modified_z_scores[i]) > 3.5:
                    spike_detected = True
                    confidence += 0.25
                    detection_methods.append('modified_zscore')
                
                if outlier_scores[i] < -0.1:
                    spike_detected = True
                    confidence += 0.2
                    detection_methods.append('isolation_forest')
                
                if lof_scores[i] == -1:
                    spike_detected = True
                    confidence += 0.15
                    detection_methods.append('lof')
                
                # Wavelet-based detection
                wavelet_energy = np.sum(np.abs(coefficients[:, max(0, i-2):min(len(values), i+3)]), axis=1)
                if np.max(wavelet_energy) > np.mean(wavelet_energy) + 2 * np.std(wavelet_energy):
                    spike_detected = True
                    confidence += 0.25
                    detection_methods.append('wavelet')
                
                if spike_detected and confidence > 0.4:
                    # Advanced spike characterization
                    spike_width = self._estimate_spike_width(values, i)
                    spike_asymmetry = self._calculate_spike_asymmetry(values, i, spike_width)
                    spike_sharpness = self._calculate_spike_sharpness(values, i)
                    
                    # Context analysis
                    local_context = values[max(0, i-10):min(len(values), i+11)]
                    background_level = np.median(local_context[local_context != val])
                    
                    # Spike classification
                    spike_type = self._classify_spike_type(values, i, spike_width, spike_asymmetry)
                    
                    patterns.append({
                        'type': 'spike',
                        'subtype': spike_type,
                        'location': i,
                        'value': float(val),
                        'strength': float(val - background_level),
                        'relative_strength': float((val - background_level) / robust_std),
                        'confidence': min(1.0, confidence),
                        'width': spike_width,
                        'asymmetry': spike_asymmetry,
                        'sharpness': spike_sharpness,
                        'background_level': float(background_level),
                        'detection_methods': detection_methods,
                        'statistical_significance': float(abs(modified_z_scores[i])),
                        'wavelet_energy': float(np.max(wavelet_energy)),
                        'isolation_score': float(outlier_scores[i]),
                        'local_outlier_factor': float(lof_scores[i])
                    })
            
            # Post-processing: merge nearby spikes and validate patterns
            patterns = self._merge_nearby_spikes(patterns)
            patterns = self._validate_spike_patterns(patterns, values)
            
            return sorted(patterns, key=lambda x: x['confidence'], reverse=True)
            
        except Exception as e:
            self.logger.error(f"Error in spike detection: {str(e)}")
            return []
    
    def _detect_burst_patterns(self, values: List[float]) -> List[Dict[str, Any]]:
        """
        Advanced burst detection using temporal dynamics analysis,
        hidden Markov models, and adaptive segmentation.
        """
        try:
            patterns = []
            values = np.array(values)
            
            if len(values) < 20:
                return patterns
            
            from scipy import signal, stats
            from sklearn.mixture import GaussianMixture
            from sklearn.cluster import DBSCAN
            
            # Preprocessing: adaptive smoothing and trend removal
            smoothed = signal.savgol_filter(values, 
                                          window_length=min(11, len(values)//4 if len(values)//4 % 2 == 1 else len(values)//4 - 1),
                                          polyorder=3)
            
            # Trend removal using robust regression
            from sklearn.linear_model import HuberRegressor
            X = np.arange(len(values)).reshape(-1, 1)
            robust_reg = HuberRegressor(epsilon=1.35)
            robust_reg.fit(X, values)
            detrended = values - robust_reg.predict(X)
            
            # Multi-scale burst detection using change point analysis
            from ruptures import Pelt, Binseg
            
            # Change point detection with multiple algorithms
            model_pelt = Pelt(model="rbf", min_size=5, jump=2).fit(detrended)
            model_binseg = Binseg(model="l2", min_size=5, jump=2).fit(detrended)
            
            change_points_pelt = model_pelt.predict(pen=np.var(detrended))
            change_points_binseg = model_binseg.predict(n_bkps=max(2, len(detrended)//50))
            
            # Combine change points from different methods
            all_change_points = sorted(set(change_points_pelt + change_points_binseg))
            
            # Gaussian Mixture Model for state identification
            gmm = GaussianMixture(n_components=3, random_state=42)
            states = gmm.fit_predict(detrended.reshape(-1, 1))
            
            # Hidden Markov Model for burst dynamics
            try:
                from hmmlearn import hmm
                model_hmm = hmm.GaussianHMM(n_components=3, covariance_type="full", random_state=42)
                model_hmm.fit(detrended.reshape(-1, 1))
                hidden_states = model_hmm.predict(detrended.reshape(-1, 1))
            except:
                hidden_states = states
            
            # Advanced burst characterization
            segments = []
            for i in range(len(all_change_points) - 1):
                start = all_change_points[i]
                end = all_change_points[i + 1]
                
                if end - start < 3:  # Skip very short segments
                    continue
                
                segment_data = detrended[start:end]
                segment_mean = np.mean(segment_data)
                segment_std = np.std(segment_data)
                segment_energy = np.sum(segment_data**2)
                
                # Burst criteria: elevated activity with temporal persistence
                baseline_level = np.median(detrended)
                baseline_std = np.std(detrended)
                
                # Multi-criteria burst detection
                is_burst = False
                burst_confidence = 0.0
                burst_characteristics = {}
                
                # Energy-based detection
                if segment_energy > np.mean([np.sum(detrended[max(0, start-50):start]**2),
                                           np.sum(detrended[end:min(len(detrended), end+50)]**2)]):
                    is_burst = True
                    burst_confidence += 0.3
                    burst_characteristics['energy_elevated'] = True
                
                # Statistical significance
                if segment_mean > baseline_level + 1.5 * baseline_std:
                    is_burst = True
                    burst_confidence += 0.25
                    burst_characteristics['statistically_significant'] = True
                
                # Temporal persistence
                if end - start >= 5:  # Minimum duration
                    burst_confidence += 0.15
                    burst_characteristics['persistent'] = True
                
                # State consistency (HMM-based)
                segment_states = hidden_states[start:end]
                dominant_state = stats.mode(segment_states, keepdims=True)[0][0]
                state_consistency = np.mean(segment_states == dominant_state)
                
                if state_consistency > 0.7 and dominant_state != stats.mode(hidden_states, keepdims=True)[0][0]:
                    burst_confidence += 0.2
                    burst_characteristics['state_consistent'] = True
                
                # Spectral analysis for burst characterization
                if len(segment_data) >= 8:
                    freqs, psd = signal.periodogram(segment_data)
                    dominant_freq = freqs[np.argmax(psd[1:])] if len(psd) > 1 else 0
                    spectral_entropy = -np.sum(psd * np.log(psd + 1e-12))
                    burst_characteristics['dominant_frequency'] = float(dominant_freq)
                    burst_characteristics['spectral_entropy'] = float(spectral_entropy)
                
                if is_burst and burst_confidence > 0.4:
                    # Advanced burst metrics
                    burst_intensity = self._calculate_burst_intensity(segment_data, baseline_level)
                    burst_shape = self._analyze_burst_shape(segment_data)
                    burst_onset_rate = self._calculate_onset_rate(detrended, start)
                    burst_decay_rate = self._calculate_decay_rate(detrended, end)
                    
                    # Contextual analysis
                    pre_burst_activity = np.mean(detrended[max(0, start-20):start])
                    post_burst_activity = np.mean(detrended[end:min(len(detrended), end+20)])
                    
                    patterns.append({
                        'type': 'burst',
                        'subtype': self._classify_burst_type(burst_shape, burst_intensity),
                        'start': int(start),
                        'end': int(end),
                        'duration': int(end - start),
                        'peak_location': int(start + np.argmax(segment_data)),
                        'strength': float(segment_mean - baseline_level),
                        'intensity': burst_intensity,
                        'confidence': min(1.0, burst_confidence),
                        'energy': float(segment_energy),
                        'shape_characteristics': burst_shape,
                        'onset_rate': burst_onset_rate,
                        'decay_rate': burst_decay_rate,
                        'dominant_state': int(dominant_state),
                        'state_consistency': float(state_consistency),
                        'pre_burst_level': float(pre_burst_activity),
                        'post_burst_level': float(post_burst_activity),
                        'statistical_significance': float((segment_mean - baseline_level) / baseline_std),
                        **burst_characteristics
                    })
            
            # Post-processing: merge overlapping bursts and validate
            patterns = self._merge_overlapping_bursts(patterns)
            patterns = self._validate_burst_patterns(patterns, values)
            
            return sorted(patterns, key=lambda x: x['confidence'], reverse=True)
            
        except Exception as e:
            self.logger.error(f"Error in burst detection: {str(e)}")
            return []
    
    # Supporting utility methods for advanced pattern analysis
    def _estimate_spike_width(self, values: np.ndarray, spike_idx: int) -> int:
        """Estimate the width of a spike using half-maximum criteria."""
        try:
            spike_value = values[spike_idx]
            half_max = (spike_value + np.median(values)) / 2
            
            # Search left and right for half-maximum points
            left_idx = spike_idx
            right_idx = spike_idx
            
            while left_idx > 0 and values[left_idx] > half_max:
                left_idx -= 1
            while right_idx < len(values) - 1 and values[right_idx] > half_max:
                right_idx += 1
                
            return right_idx - left_idx
        except:
            return 1
    
    def _calculate_spike_asymmetry(self, values: np.ndarray, spike_idx: int, width: int) -> float:
        """Calculate asymmetry of spike shape."""
        try:
            left_side = spike_idx - max(0, spike_idx - width//2)
            right_side = min(len(values), spike_idx + width//2) - spike_idx
            return (right_side - left_side) / max(right_side + left_side, 1)
        except:
            return 0.0
    
    def _calculate_spike_sharpness(self, values: np.ndarray, spike_idx: int) -> float:
        """Calculate sharpness using second derivative approximation."""
        try:
            if spike_idx == 0 or spike_idx == len(values) - 1:
                return 0.0
            second_derivative = values[spike_idx-1] - 2*values[spike_idx] + values[spike_idx+1]
            return abs(second_derivative)
        except:
            return 0.0
    
    def _classify_spike_type(self, values: np.ndarray, spike_idx: int, width: int, asymmetry: float) -> str:
        """Classify spike type based on characteristics."""
        try:
            if width <= 2:
                return 'impulse'
            elif asymmetry > 0.3:
                return 'slow_rise_fast_decay'
            elif asymmetry < -0.3:
                return 'fast_rise_slow_decay'
            else:
                return 'symmetric'
        except:
            return 'unknown'
    
    def _merge_nearby_spikes(self, patterns: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """Merge spikes that are very close to each other."""
        if not patterns:
            return patterns
        
        merged = []
        current_group = [patterns[0]]
        
        for pattern in patterns[1:]:
            if pattern['location'] - current_group[-1]['location'] <= 3:
                current_group.append(pattern)
            else:
                if len(current_group) == 1:
                    merged.append(current_group[0])
                else:
                    # Merge group into single spike with highest confidence
                    best_spike = max(current_group, key=lambda x: x['confidence'])
                    best_spike['detection_methods'] = list(set(sum([s['detection_methods'] for s in current_group], [])))
                    merged.append(best_spike)
                current_group = [pattern]
        
        # Handle last group
        if len(current_group) == 1:
            merged.append(current_group[0])
        else:
            best_spike = max(current_group, key=lambda x: x['confidence'])
            best_spike['detection_methods'] = list(set(sum([s['detection_methods'] for s in current_group], [])))
            merged.append(best_spike)
        
        return merged
    
    def _validate_spike_patterns(self, patterns: List[Dict[str, Any]], values: np.ndarray) -> List[Dict[str, Any]]:
        """Validate spike patterns using additional criteria."""
        validated = []
        for pattern in patterns:
            try:
                idx = pattern['location']
                # Check if spike is at boundary (likely artifact)
                if idx < 2 or idx >= len(values) - 2:
                    continue
                
                # Check if spike has sufficient contrast with neighbors
                neighbors = [values[idx-2], values[idx-1], values[idx+1], values[idx+2]]
                neighbor_mean = np.mean(neighbors)
                if abs(values[idx] - neighbor_mean) < np.std(neighbors):
                    continue
                
                validated.append(pattern)
            except:
                continue
        
        return validated
    
    def _calculate_burst_intensity(self, segment_data: np.ndarray, baseline: float) -> float:
        """Calculate burst intensity as integrated excess activity."""
        try:
            excess_activity = segment_data - baseline
            excess_activity[excess_activity < 0] = 0
            return float(np.trapz(excess_activity))
        except:
            return 0.0
    
    def _analyze_burst_shape(self, segment_data: np.ndarray) -> Dict[str, float]:
        """Analyze burst shape characteristics."""
        try:
            peak_idx = np.argmax(segment_data)
            peak_value = segment_data[peak_idx]
            
            # Calculate rise and fall times
            half_peak = peak_value / 2
            
            rise_time = 0
            for i in range(peak_idx):
                if segment_data[i] >= half_peak:
                    rise_time = peak_idx - i
                    break
            
            fall_time = 0
            for i in range(peak_idx + 1, len(segment_data)):
                if segment_data[i] <= half_peak:
                    fall_time = i - peak_idx
                    break
            
            # Calculate skewness and kurtosis
            from scipy.stats import skew, kurtosis
            shape_skew = float(skew(segment_data))
            shape_kurtosis = float(kurtosis(segment_data))
            
            return {
                'peak_position': float(peak_idx / len(segment_data)),
                'rise_time': float(rise_time),
                'fall_time': float(fall_time),
                'asymmetry': float((fall_time - rise_time) / max(fall_time + rise_time, 1)),
                'skewness': shape_skew,
                'kurtosis': shape_kurtosis,
                'peak_prominence': float(peak_value - np.median(segment_data))
            }
        except:
            return {'peak_position': 0.5, 'rise_time': 0, 'fall_time': 0, 'asymmetry': 0, 
                    'skewness': 0, 'kurtosis': 0, 'peak_prominence': 0}
    
    def _calculate_onset_rate(self, values: np.ndarray, start_idx: int) -> float:
        """Calculate burst onset rate."""
        try:
            if start_idx < 5:
                return 0.0
            
            pre_burst = values[start_idx-5:start_idx]
            burst_start = values[start_idx:min(len(values), start_idx+3)]
            
            if len(burst_start) == 0:
                return 0.0
            
            onset_rate = (np.mean(burst_start) - np.mean(pre_burst)) / 3
            return float(onset_rate)
        except:
            return 0.0
    
    def _calculate_decay_rate(self, values: np.ndarray, end_idx: int) -> float:
        """Calculate burst decay rate."""
        try:
            if end_idx >= len(values) - 5:
                return 0.0
            
            burst_end = values[max(0, end_idx-3):end_idx]
            post_burst = values[end_idx:end_idx+5]
            
            if len(burst_end) == 0:
                return 0.0
            
            decay_rate = (np.mean(burst_end) - np.mean(post_burst)) / 3
            return float(decay_rate)
        except:
            return 0.0
    
    def _classify_burst_type(self, shape_characteristics: Dict[str, float], intensity: float) -> str:
        """Classify burst type based on shape and intensity."""
        try:
            asymmetry = shape_characteristics.get('asymmetry', 0)
            kurtosis = shape_characteristics.get('kurtosis', 0)
            
            if intensity < 10:
                return 'weak'
            elif asymmetry > 0.5:
                return 'slow_rise_fast_decay'
            elif asymmetry < -0.5:
                return 'fast_rise_slow_decay'
            elif kurtosis > 3:
                return 'sharp_peaked'
            elif kurtosis < -1:
                return 'flat_topped'
            else:
                return 'symmetric'
        except:
            return 'unknown'
    
    def _merge_overlapping_bursts(self, patterns: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """Merge overlapping burst patterns."""
        if not patterns:
            return patterns
        
        # Sort by start time
        sorted_patterns = sorted(patterns, key=lambda x: x['start'])
        merged = []
        
        current = sorted_patterns[0]
        for next_burst in sorted_patterns[1:]:
            # Check for overlap
            if next_burst['start'] <= current['end'] + 5:  # Allow small gap
                # Merge bursts
                new_start = min(current['start'], next_burst['start'])
                new_end = max(current['end'], next_burst['end'])
                
                # Combine characteristics
                combined_confidence = max(current['confidence'], next_burst['confidence'])
                
                current = {
                    'type': 'burst',
                    'subtype': 'merged',
                    'start': new_start,
                    'end': new_end,
                    'duration': new_end - new_start,
                    'confidence': combined_confidence,
                    'strength': max(current.get('strength', 0), next_burst.get('strength', 0)),
                    'intensity': current.get('intensity', 0) + next_burst.get('intensity', 0)
                }
            else:
                merged.append(current)
                current = next_burst
        
        merged.append(current)
        return merged
    
    def _validate_burst_patterns(self, patterns: List[Dict[str, Any]], values: np.ndarray) -> List[Dict[str, Any]]:
        """Validate burst patterns using statistical criteria."""
        validated = []
        
        for pattern in patterns:
            try:
                start, end = pattern['start'], pattern['end']
                
                # Check minimum duration
                if end - start < 3:
                    continue
                
                # Check that burst is statistically significant
                if pattern.get('statistical_significance', 0) < 1.5:
                    continue
                
                # Check that burst has reasonable boundaries
                if start < 0 or end >= len(values):
                    continue
                
                validated.append(pattern)
            except:
                continue
        
        return validated
    
    # Additional utility methods for comprehensive pattern detection
    def _detect_daily_patterns(self, values: List[float]) -> List[Dict[str, Any]]: 
        """Advanced daily pattern detection using Fourier analysis and phase coherence."""
        try:
            if len(values) < 24 * 7:  # Need at least a week of hourly data
                return []
            
            values = np.array(values)
            
            # Fourier analysis for 24-hour periodicity
            from scipy.fft import fft, fftfreq
            
            fft_vals = fft(values)
            freqs = fftfreq(len(values))
            
            # Look for 24-hour cycle (assuming hourly data)
            daily_freq_idx = np.argmin(np.abs(freqs - 1/24))
            daily_power = np.abs(fft_vals[daily_freq_idx])**2
            
            # Phase analysis for consistency
            daily_phase = np.angle(fft_vals[daily_freq_idx])
            
            patterns = []
            if daily_power > np.mean(np.abs(fft_vals)**2) * 3:  # Significant daily component
                patterns.append({
                    'type': 'daily',
                    'power': float(daily_power),
                    'phase': float(daily_phase),
                    'peak_hour': float((daily_phase / (2 * np.pi) * 24) % 24),
                    'confidence': min(1.0, daily_power / np.sum(np.abs(fft_vals)**2))
                })
            
            return patterns
        except:
            return []
    
    def _detect_periodic_patterns(self, values: List[float], period_range: tuple = None) -> List[Dict[str, Any]]:
        """Advanced periodic pattern detection using multiple methods."""
        try:
            if len(values) < 50:
                return []
            
            values = np.array(values)
            patterns = []
            
            # Autocorrelation analysis
            from scipy.signal import correlate
            
            autocorr = correlate(values, values, mode='full')
            autocorr = autocorr[len(autocorr)//2:]
            
            # Find peaks in autocorrelation
            from scipy.signal import find_peaks
            peaks, properties = find_peaks(autocorr[1:], height=np.max(autocorr) * 0.3, distance=5)
            
            # Lomb-Scargle periodogram for irregular sampling
            from scipy.signal import lombscargle
            
            if period_range is None:
                period_range = (2, len(values)//4)
            
            frequencies = np.linspace(1/period_range[1], 1/period_range[0], 1000)
            pgram = lombscargle(np.arange(len(values)), values, frequencies, normalize=True)
            
            # Find significant periodicities
            threshold = np.mean(pgram) + 3 * np.std(pgram)
            significant_peaks = find_peaks(pgram, height=threshold)[0]
            
            for peak_idx in significant_peaks:
                period = 1 / frequencies[peak_idx]
                power = pgram[peak_idx]
                
                patterns.append({
                    'type': 'periodic',
                    'period': float(period),
                    'frequency': float(frequencies[peak_idx]),
                    'power': float(power),
                    'confidence': min(1.0, power / np.max(pgram))
                })
            
            return sorted(patterns, key=lambda x: x['confidence'], reverse=True)
        except:
            return []
    
    def _detect_weekly_patterns(self, values: List[float]) -> List[Dict[str, Any]]:
        """Advanced weekly pattern detection with day-of-week analysis."""
        try:
            if len(values) < 7 * 24 * 4:  # Need at least 4 weeks of hourly data
                return []
            
            values = np.array(values)
            
            # Reshape into weekly patterns (assuming hourly data)
            hours_per_week = 7 * 24
            n_complete_weeks = len(values) // hours_per_week
            
            if n_complete_weeks < 2:
                return []
            
            weekly_data = values[:n_complete_weeks * hours_per_week].reshape(n_complete_weeks, hours_per_week)
            
            # Calculate weekly statistics
            weekly_mean = np.mean(weekly_data, axis=0)
            weekly_std = np.std(weekly_data, axis=0)
            
            # Day-of-week analysis
            daily_means = []
            for day in range(7):
                day_hours = weekly_mean[day*24:(day+1)*24]
                daily_means.append(np.mean(day_hours))
            
            # Weekly periodicity test
            weekly_autocorr = np.corrcoef(weekly_data)[0, 1:].mean()
            
            patterns = []
            
            # Check for significant weekly pattern
            if np.std(daily_means) > np.mean(weekly_std):
                patterns.append({
                    'type': 'weekly',
                    'daily_means': [float(x) for x in daily_means],
                    'peak_day': int(np.argmax(daily_means)),
                    'trough_day': int(np.argmin(daily_means)),
                    'weekly_autocorr': float(weekly_autocorr),
                    'pattern_strength': float(np.std(daily_means) / np.mean(daily_means)),
                    'confidence': min(1.0, np.std(daily_means) / np.mean(weekly_std))
                })
            
            return patterns
        except:
            return []
            
    def _detect_monthly_patterns(self, values: List[float]) -> List[Dict[str, Any]]:
        """
        Detect monthly patterns using advanced spectral analysis and statistical methods
        """
        if len(values) < 24:  # Need at least 2 years of monthly data
            return []
        
        try:
            patterns = []
            values_array = np.array(values, dtype=float)
            
            # Remove NaN values and handle missing data
            valid_mask = ~np.isnan(values_array)
            if np.sum(valid_mask) < 12:
                return []
            
            values_clean = values_array[valid_mask]
            
            # Monthly periodogram analysis
            from scipy.signal import periodogram, find_peaks
            from scipy.stats import pearsonr
            
            # Calculate periodogram
            frequencies, psd = periodogram(values_clean, fs=12)  # 12 samples per year
            
            # Find peaks at monthly frequencies
            monthly_freq_range = (0.8, 1.2)  # Around 1 cycle per month
            monthly_indices = np.where((frequencies >= monthly_freq_range[0]) & 
                                     (frequencies <= monthly_freq_range[1]))[0]
            
            if len(monthly_indices) > 0:
                monthly_peaks, properties = find_peaks(psd[monthly_indices], 
                                                     height=np.percentile(psd, 75))
                
                for peak_idx in monthly_peaks:
                    freq_idx = monthly_indices[peak_idx]
                    freq = frequencies[freq_idx]
                    power = psd[freq_idx]
                    
                    # Calculate pattern strength
                    pattern_strength = power / np.mean(psd)
                    
                    # Monthly decomposition analysis
                    if len(values_clean) >= 24:
                        # Group by month and calculate statistics
                        months = np.arange(len(values_clean)) % 12
                        monthly_means = [np.mean(values_clean[months == m]) for m in range(12)]
                        monthly_stds = [np.std(values_clean[months == m]) for m in range(12)]
                        
                        # Calculate monthly variation coefficient
                        monthly_cv = np.std(monthly_means) / np.mean(monthly_means) if np.mean(monthly_means) > 0 else 0
                        
                        # Detect seasonal components within monthly patterns
                        seasonal_correlation = 0
                        if len(values_clean) >= 36:  # Need at least 3 years
                            seasonal_pattern = np.tile(monthly_means, len(values_clean) // 12 + 1)[:len(values_clean)]
                            seasonal_correlation, _ = pearsonr(values_clean, seasonal_pattern)
                        
                        patterns.append({
                            'type': 'monthly_spectral',
                            'frequency': float(freq),
                            'period_months': 12.0 / freq if freq > 0 else 0,
                            'power_density': float(power),
                            'strength': float(pattern_strength),
                            'monthly_means': monthly_means,
                            'monthly_stds': monthly_stds,
                            'coefficient_variation': float(monthly_cv),
                            'seasonal_correlation': float(seasonal_correlation),
                            'confidence': min(0.95, pattern_strength / 5.0),
                            'statistical_significance': float(power > np.percentile(psd, 90))
                        })
            
            # Additional monthly pattern detection using autocorrelation
            from statsmodels.tsa.stattools import acf
            
            if len(values_clean) >= 36:
                autocorr = acf(values_clean, nlags=24, fft=True)
                monthly_lags = [1, 12, 24]  # 1-month, 1-year, 2-year lags
                
                for lag in monthly_lags:
                    if lag < len(autocorr) and abs(autocorr[lag]) > 0.3:
                        patterns.append({
                            'type': 'monthly_autocorrelation',
                            'lag_months': lag,
                            'correlation': float(autocorr[lag]),
                            'strength': float(abs(autocorr[lag])),
                            'confidence': min(0.9, abs(autocorr[lag]) * 2),
                            'pattern_type': 'periodic' if lag >= 12 else 'short_term'
                        })
            
            return patterns
            
        except Exception as e:
            self.logger.error(f"Error in monthly pattern detection: {e}")
            return []
    def _detect_seasonal_patterns(self, values: List[float]) -> List[Dict[str, Any]]:
        """
        Detect seasonal patterns using harmonic analysis and climate modeling
        """
        if len(values) < 48:  # Need at least 4 years of data
            return []
        
        try:
            patterns = []
            values_array = np.array(values, dtype=float)
            
            # Handle missing data
            valid_mask = ~np.isnan(values_array)
            if np.sum(valid_mask) < 24:
                return []
            
            values_clean = values_array[valid_mask]
            
            # Seasonal decomposition using multiple methods
            from statsmodels.tsa.seasonal import seasonal_decompose, STL
            from scipy.signal import hilbert, butter, filtfilt
            from scipy.stats import pearsonr, spearmanr
            
            # Classical seasonal decomposition
            if len(values_clean) >= 24:
                try:
                    decomposition = seasonal_decompose(values_clean, model='additive', 
                                                     period=12, extrapolate_trend='freq')
                    
                    seasonal_component = decomposition.seasonal[:12]  # One seasonal cycle
                    seasonal_strength = np.std(seasonal_component) / np.std(values_clean)
                    
                    # Calculate seasonal indices
                    seasonal_indices = seasonal_component / np.mean(values_clean)
                    
                    patterns.append({
                        'type': 'classical_seasonal',
                        'seasonal_component': seasonal_component.tolist(),
                        'seasonal_indices': seasonal_indices.tolist(),
                        'strength': float(seasonal_strength),
                        'variance_explained': float((np.var(seasonal_component) / np.var(values_clean)) * 100),
                        'confidence': min(0.95, seasonal_strength * 2)
                    })
                except Exception as e:
                    self.logger.warning(f"Classical decomposition failed: {e}")
            
            # STL (Seasonal and Trend decomposition using Loess) decomposition
            if len(values_clean) >= 36:
                try:
                    stl = STL(values_clean, seasonal=13, trend=None, robust=True)
                    result = stl.fit()
                    
                    seasonal_stl = result.seasonal[:12]
                    seasonal_strength_stl = np.std(seasonal_stl) / np.std(values_clean)
                    
                    # Calculate seasonal phase and amplitude
                    seasonal_phase = np.argmax(seasonal_stl)
                    seasonal_amplitude = np.max(seasonal_stl) - np.min(seasonal_stl)
                    
                    patterns.append({
                        'type': 'stl_seasonal',
                        'seasonal_component': seasonal_stl.tolist(),
                        'strength': float(seasonal_strength_stl),
                        'phase_month': int(seasonal_phase),
                        'amplitude': float(seasonal_amplitude),
                        'robust_fit': True,
                        'confidence': min(0.9, seasonal_strength_stl * 1.8)
                    })
                except Exception as e:
                    self.logger.warning(f"STL decomposition failed: {e}")
            
            # Harmonic analysis for seasonal patterns
            from numpy.fft import fft, fftfreq
            
            # Apply FFT to detect harmonic seasonal patterns
            n = len(values_clean)
            fft_values = fft(values_clean)
            frequencies = fftfreq(n, 1/12)  # Monthly sampling
            
            # Focus on seasonal frequencies (annual, semi-annual, etc.)
            seasonal_freqs = [1.0, 2.0, 3.0, 4.0, 6.0]  # cycles per year
            
            for target_freq in seasonal_freqs:
                # Find closest frequency bin
                freq_idx = np.argmin(np.abs(frequencies - target_freq))
                if freq_idx < len(fft_values):
                    amplitude = np.abs(fft_values[freq_idx])
                    phase = np.angle(fft_values[freq_idx])
                    
                    # Calculate relative strength
                    total_power = np.sum(np.abs(fft_values)**2)
                    relative_power = (amplitude**2) / total_power
                    
                    if relative_power > 0.01:  # Threshold for significance
                        patterns.append({
                            'type': 'harmonic_seasonal',
                            'frequency_cycles_per_year': float(target_freq),
                            'period_months': 12.0 / target_freq,
                            'amplitude': float(amplitude),
                            'phase_radians': float(phase),
                            'phase_months': float((phase / (2 * np.pi)) * (12 / target_freq)),
                            'relative_power': float(relative_power),
                            'confidence': min(0.85, relative_power * 20)
                        })
            
            # Climate oscillation detection (e.g., ENSO-like patterns)
            if len(values_clean) >= 60:  # Need 5+ years for climate patterns
                # Detect quasi-periodic oscillations
                from scipy.signal import find_peaks, peak_widths
                
                # Calculate 3-7 year oscillations (climate-like)
                climate_frequencies = np.arange(3, 8)  # 3-7 year periods
                
                for period_years in climate_frequencies:
                    period_months = period_years * 12
                    if period_months < len(values_clean):
                        # Create synthetic climate signal for comparison
                        t = np.arange(len(values_clean))
                        synthetic_signal = np.sin(2 * np.pi * t / period_months)
                        
                        # Calculate correlation with synthetic signal
                        correlation, p_value = pearsonr(values_clean, synthetic_signal)
                        
                        if abs(correlation) > 0.2 and p_value < 0.05:
                            patterns.append({
                                'type': 'climate_oscillation',
                                'period_years': float(period_years),
                                'period_months': float(period_months),
                                'correlation': float(correlation),
                                'p_value': float(p_value),
                                'strength': float(abs(correlation)),
                                'confidence': float(1 - p_value),
                                'oscillation_type': 'enso_like' if 3 <= period_years <= 7 else 'other'
                            })
            
            # Seasonal trend analysis
            if len(values_clean) >= 36:
                # Calculate seasonal trends (is each season getting stronger/weaker?)
                years = len(values_clean) // 12
                seasonal_trends = []
                
                for season in range(12):  # For each month
                    seasonal_values = [values_clean[season + i*12] 
                                     for i in range(years) 
                                     if season + i*12 < len(values_clean)]
                    
                    if len(seasonal_values) >= 3:
                        # Linear trend in this season
                        x = np.arange(len(seasonal_values))
                        slope, intercept, r_value, p_value, std_err = stats.linregress(x, seasonal_values)
                        
                        seasonal_trends.append({
                            'month': season,
                            'trend_slope': float(slope),
                            'trend_r_squared': float(r_value**2),
                            'trend_p_value': float(p_value),
                            'trend_significance': float(p_value < 0.05)
                        })
                
                if seasonal_trends:
                    patterns.append({
                        'type': 'seasonal_trends',
                        'monthly_trends': seasonal_trends,
                        'overall_seasonal_change': float(np.mean([t['trend_slope'] for t in seasonal_trends])),
                        'confidence': 0.8
                    })
            
            return patterns
            
        except Exception as e:
            self.logger.error(f"Error in seasonal pattern detection: {e}")
            return []
    def _detect_annual_patterns(self, values: List[float]) -> List[Dict[str, Any]]:
        """
        Detect annual patterns using long-term trend analysis and periodogram methods
        """
        if len(values) < 36:  # Need at least 3 years
            return []
        
        try:
            patterns = []
            values_array = np.array(values, dtype=float)
            
            # Handle missing data
            valid_mask = ~np.isnan(values_array)
            if np.sum(valid_mask) < 24:
                return []
            
            values_clean = values_array[valid_mask]
            
            # Annual cycle detection using periodogram
            from scipy.signal import periodogram, welch, find_peaks
            from scipy.stats import pearsonr, kendalltau
            
            # Welch's method for robust spectral estimation
            frequencies, psd = welch(values_clean, fs=12, nperseg=min(len(values_clean)//4, 48))
            
            # Focus on annual frequency (1 cycle per year)
            annual_freq_target = 1.0
            annual_idx = np.argmin(np.abs(frequencies - annual_freq_target))
            
            if annual_idx < len(psd):
                annual_power = psd[annual_idx]
                total_power = np.sum(psd)
                annual_strength = annual_power / total_power
                
                # Find peaks in the power spectrum
                peaks, properties = find_peaks(psd, height=np.percentile(psd, 70))
                
                # Check if annual frequency is a significant peak
                is_annual_peak = annual_idx in peaks
                
                if annual_strength > 0.05 or is_annual_peak:
                    patterns.append({
                        'type': 'annual_spectral',
                        'frequency': float(frequencies[annual_idx]),
                        'period_months': 12.0,
                        'power_density': float(annual_power),
                        'relative_strength': float(annual_strength),
                        'is_significant_peak': bool(is_annual_peak),
                        'confidence': min(0.9, annual_strength * 10)
                    })
            
            # Year-over-year analysis
            years_data = len(values_clean) // 12
            if years_data >= 3:
                annual_means = []
                annual_sums = []
                annual_maxes = []
                annual_mins = []
                annual_ranges = []
                
                for year in range(years_data):
                    year_start = year * 12
                    year_end = min((year + 1) * 12, len(values_clean))
                    year_data = values_clean[year_start:year_end]
                    
                    if len(year_data) >= 9:  # At least 9 months of data
                        annual_means.append(np.mean(year_data))
                        annual_sums.append(np.sum(year_data))
                        annual_maxes.append(np.max(year_data))
                        annual_mins.append(np.min(year_data))
                        annual_ranges.append(np.max(year_data) - np.min(year_data))
                
                # Annual trend analysis
                if len(annual_means) >= 3:
                    years = np.arange(len(annual_means))
                    
                    # Linear trend in annual means
                    slope_mean, intercept_mean, r_mean, p_mean, se_mean = stats.linregress(years, annual_means)
                    
                    # Trend in annual variability (ranges)
                    if len(annual_ranges) >= 3:
                        slope_range, intercept_range, r_range, p_range, se_range = stats.linregress(years, annual_ranges)
                    else:
                        slope_range = r_range = p_range = 0
                    
                    # Mann-Kendall trend test (non-parametric)
                    from scipy.stats import kendalltau
                    tau_mean, p_mk_mean = kendalltau(years, annual_means)
                    
                    patterns.append({
                        'type': 'annual_trend',
                        'mean_trend_slope': float(slope_mean),
                        'mean_trend_r_squared': float(r_mean**2),
                        'mean_trend_p_value': float(p_mean),
                        'variability_trend_slope': float(slope_range),
                        'variability_trend_r_squared': float(r_range**2),
                        'mann_kendall_tau': float(tau_mean),
                        'mann_kendall_p_value': float(p_mk_mean),
                        'trend_direction': 'increasing' if slope_mean > 0 else 'decreasing',
                        'trend_significance': float(p_mean < 0.05),
                        'confidence': min(0.95, (1 - p_mean) if p_mean > 0 else 0.5)
                    })
            
            # Annual cycle consistency analysis
            if len(values_clean) >= 24:
                # Calculate average annual cycle
                monthly_averages = []
                monthly_stds = []
                
                for month in range(12):
                    month_values = [values_clean[month + i*12] 
                                  for i in range(len(values_clean)//12) 
                                  if month + i*12 < len(values_clean)]
                    
                    if len(month_values) >= 2:
                        monthly_averages.append(np.mean(month_values))
                        monthly_stds.append(np.std(month_values))
                    else:
                        monthly_averages.append(0)
                        monthly_stds.append(0)
                
                # Calculate annual cycle metrics
                annual_amplitude = max(monthly_averages) - min(monthly_averages)
                annual_mean = np.mean(monthly_averages)
                annual_cv = np.std(monthly_averages) / annual_mean if annual_mean > 0 else 0
                
                # Peak and trough months
                peak_month = np.argmax(monthly_averages)
                trough_month = np.argmin(monthly_averages)
                
                # Annual cycle shape analysis
                # Fit sinusoidal model: y = A*sin(2*pi*t/12 + phi) + C
                t = np.arange(12)
                
                # Optimize sinusoidal fit
                from scipy.optimize import curve_fit
                
                def sinusoidal_model(t, A, phi, C):
                    return A * np.sin(2 * np.pi * t / 12 + phi) + C
                
                try:
                    popt, pcov = curve_fit(sinusoidal_model, t, monthly_averages, 
                                         p0=[annual_amplitude/2, 0, annual_mean])
                    
                    fitted_amplitude, fitted_phase, fitted_mean = popt
                    
                    # Calculate R-squared for the fit
                    fitted_values = sinusoidal_model(t, *popt)
                    ss_res = np.sum((monthly_averages - fitted_values) ** 2)
                    ss_tot = np.sum((monthly_averages - np.mean(monthly_averages)) ** 2)
                    r_squared_fit = 1 - (ss_res / ss_tot) if ss_tot > 0 else 0
                    
                    patterns.append({
                        'type': 'annual_cycle',
                        'monthly_averages': monthly_averages,
                        'monthly_stds': monthly_stds,
                        'amplitude': float(annual_amplitude),
                        'coefficient_of_variation': float(annual_cv),
                        'peak_month': int(peak_month),
                        'trough_month': int(trough_month),
                        'sinusoidal_fit': {
                            'amplitude': float(fitted_amplitude),
                            'phase': float(fitted_phase),
                            'mean': float(fitted_mean),
                            'r_squared': float(r_squared_fit)
                        },
                        'cycle_regularity': float(r_squared_fit),
                        'confidence': min(0.9, r_squared_fit * 1.2)
                    })
                    
                except Exception as e:
                    self.logger.warning(f"Sinusoidal fit failed: {e}")
            
            # Multi-year cycle detection (2-10 year cycles)
            if len(values_clean) >= 60:  # Need 5+ years
                multi_year_periods = [24, 36, 48, 60, 72, 84, 96, 108, 120]  # 2-10 years in months
                
                for period in multi_year_periods:
                    if period < len(values_clean):
                        # Test for periodicity at this scale
                        n_cycles = len(values_clean) // period
                        if n_cycles >= 2:
                            # Calculate correlation between cycles
                            correlations = []
                            for i in range(n_cycles - 1):
                                cycle1 = values_clean[i*period:(i+1)*period]
                                cycle2 = values_clean[(i+1)*period:(i+2)*period]
                                
                                if len(cycle1) == len(cycle2) == period:
                                    corr, p_val = pearsonr(cycle1, cycle2)
                                    if not np.isnan(corr):
                                        correlations.append(corr)
                            
                            if correlations:
                                avg_correlation = np.mean(correlations)
                                if avg_correlation > 0.3:
                                    patterns.append({
                                        'type': 'multi_year_cycle',
                                        'period_months': int(period),
                                        'period_years': float(period / 12),
                                        'cycle_correlation': float(avg_correlation),
                                        'n_cycles_detected': int(n_cycles),
                                        'cycle_consistency': float(1 - np.std(correlations)) if len(correlations) > 1 else 1.0,
                                        'confidence': min(0.8, avg_correlation * 2)
                                    })
            
            return patterns
            
        except Exception as e:
            self.logger.error(f"Error in annual pattern detection: {e}")
            return []
    def _detect_longterm_trends(self, values: List[float]) -> List[Dict[str, Any]]:
        """
        Detect long-term trends using advanced regression and change point analysis
        """
        if len(values) < 24:  # Need at least 2 years
            return []
        
        try:
            patterns = []
            values_array = np.array(values, dtype=float)
            
            # Handle missing data
            valid_mask = ~np.isnan(values_array)
            if np.sum(valid_mask) < 12:
                return []
            
            values_clean = values_array[valid_mask]
            time_indices = np.arange(len(values_clean))
            
            # Linear trend analysis
            from scipy import stats
            from sklearn.linear_model import TheilSenRegressor, HuberRegressor, RANSACRegressor
            from sklearn.preprocessing import PolynomialFeatures
            from sklearn.pipeline import Pipeline
            
            # 1. Classical linear regression
            slope, intercept, r_value, p_value, std_err = stats.linregress(time_indices, values_clean)
            
            # Calculate trend metrics
            trend_strength = abs(r_value)
            trend_direction = 'increasing' if slope > 0 else 'decreasing' if slope < 0 else 'stable'
            
            # Calculate trend as percentage change over the entire period
            if len(values_clean) > 1:
                total_change_pct = ((slope * (len(values_clean) - 1)) / values_clean[0]) * 100 if values_clean[0] != 0 else 0
            else:
                total_change_pct = 0
            
            patterns.append({
                'type': 'linear_trend',
                'slope': float(slope),
                'intercept': float(intercept),
                'r_squared': float(r_value**2),
                'p_value': float(p_value),
                'standard_error': float(std_err),
                'direction': trend_direction,
                'strength': float(trend_strength),
                'total_change_percent': float(total_change_pct),
                'significance': float(p_value < 0.05),
                'confidence': min(0.95, (1 - p_value) if p_value > 0 else 0.5)
            })
            
            # 2. Robust regression methods
            try:
                # Theil-Sen estimator (robust to outliers)
                theil_sen = TheilSenRegressor(random_state=42)
                X = time_indices.reshape(-1, 1)
                theil_sen.fit(X, values_clean)
                
                theil_slope = theil_sen.coef_[0]
                theil_intercept = theil_sen.intercept_
                
                # Calculate R-squared for Theil-Sen
                theil_predictions = theil_sen.predict(X)
                ss_res = np.sum((values_clean - theil_predictions) ** 2)
                ss_tot = np.sum((values_clean - np.mean(values_clean)) ** 2)
                theil_r_squared = 1 - (ss_res / ss_tot) if ss_tot > 0 else 0
                
                patterns.append({
                    'type': 'robust_theil_sen_trend',
                    'slope': float(theil_slope),
                    'intercept': float(theil_intercept),
                    'r_squared': float(theil_r_squared),
                    'direction': 'increasing' if theil_slope > 0 else 'decreasing' if theil_slope < 0 else 'stable',
                    'outlier_resistant': True,
                    'confidence': min(0.9, theil_r_squared * 1.2)
                })
                
            except Exception as e:
                self.logger.warning(f"Theil-Sen regression failed: {e}")
            
            # 3. Polynomial trend detection
            if len(values_clean) >= 12:
                for degree in [2, 3]:  # Quadratic and cubic trends
                    try:
                        poly_features = PolynomialFeatures(degree=degree)
                        X_poly = poly_features.fit_transform(time_indices.reshape(-1, 1))
                        
                        # Fit polynomial regression
                        from sklearn.linear_model import LinearRegression
                        poly_reg = LinearRegression()
                        poly_reg.fit(X_poly, values_clean)
                        
                        poly_predictions = poly_reg.predict(X_poly)
                        
                        # Calculate R-squared
                        ss_res = np.sum((values_clean - poly_predictions) ** 2)
                        ss_tot = np.sum((values_clean - np.mean(values_clean)) ** 2)
                        poly_r_squared = 1 - (ss_res / ss_tot) if ss_tot > 0 else 0
                        
                        # Only include if significantly better than linear
                        if poly_r_squared > (r_value**2 + 0.05):
                            # Determine trend shape
                            if degree == 2:
                                second_coef = poly_reg.coef_[2]
                                trend_shape = 'accelerating' if second_coef > 0 else 'decelerating'
                            else:
                                trend_shape = 'complex_cubic'
                            
                            patterns.append({
                                'type': f'polynomial_trend_degree_{degree}',
                                'coefficients': poly_reg.coef_.tolist(),
                                'r_squared': float(poly_r_squared),
                                'trend_shape': trend_shape,
                                'improvement_over_linear': float(poly_r_squared - r_value**2),
                                'confidence': min(0.85, poly_r_squared)
                            })
                            
                    except Exception as e:
                        self.logger.warning(f"Polynomial trend degree {degree} failed: {e}")
            
            # 4. Piecewise linear trends (change point detection)
            if len(values_clean) >= 20:
                from scipy.signal import find_peaks
                from sklearn.linear_model import LinearRegression
                
                # Simple change point detection using residual analysis
                residuals = values_clean - (slope * time_indices + intercept)
                
                # Find potential change points based on residual patterns
                window_size = min(12, len(values_clean) // 4)
                change_points = []
                
                for i in range(window_size, len(values_clean) - window_size):
                    # Test if trend changes significantly at this point
                    left_data = values_clean[:i]
                    right_data = values_clean[i:]
                    left_indices = time_indices[:i]
                    right_indices = time_indices[i:]
                    
                    if len(left_data) >= 6 and len(right_data) >= 6:
                        # Fit trends to both segments
                        left_slope, _, left_r, left_p, _ = stats.linregress(left_indices, left_data)
                        right_slope, _, right_r, right_p, _ = stats.linregress(right_indices, right_data)
                        
                        # Check if slopes are significantly different
                        slope_diff = abs(left_slope - right_slope)
                        combined_r_squared = (left_r**2 + right_r**2) / 2
                        
                        # Threshold for detecting change point
                        if slope_diff > abs(slope) * 0.5 and combined_r_squared > r_value**2 + 0.1:
                            change_points.append({
                                'index': int(i),
                                'left_slope': float(left_slope),
                                'right_slope': float(right_slope),
                                'slope_difference': float(slope_diff),
                                'combined_r_squared': float(combined_r_squared)
                            })
                
                if change_points:
                    # Select the most significant change point
                    best_change_point = max(change_points, key=lambda x: x['combined_r_squared'])
                    
                    patterns.append({
                        'type': 'piecewise_linear_trend',
                        'change_point': best_change_point,
                        'trend_type': 'regime_change',
                        'confidence': min(0.8, best_change_point['combined_r_squared'])
                    })
            
            # 5. Mann-Kendall trend test (non-parametric)
            from scipy.stats import kendalltau
            
            # Mann-Kendall test
            tau, p_mk = kendalltau(time_indices, values_clean)
            
            # Sen's slope estimator
            n = len(values_clean)
            slopes = []
            for i in range(n-1):
                for j in range(i+1, n):
                    if time_indices[j] != time_indices[i]:
                        slope_ij = (values_clean[j] - values_clean[i]) / (time_indices[j] - time_indices[i])
                        slopes.append(slope_ij)
            
            if slopes:
                sen_slope = np.median(slopes)
                
                patterns.append({
                    'type': 'mann_kendall_trend',
                    'kendall_tau': float(tau),
                    'p_value': float(p_mk),
                    'sen_slope': float(sen_slope),
                    'direction': 'increasing' if sen_slope > 0 else 'decreasing' if sen_slope < 0 else 'no_trend',
                    'significance': float(p_mk < 0.05),
                    'non_parametric': True,
                    'confidence': min(0.95, (1 - p_mk) if p_mk > 0 else 0.5)
                })
            
            # 6. Detrended fluctuation analysis (DFA)
            if len(values_clean) >= 50:
                try:
                    def dfa_analysis(data, min_scale=4, max_scale=None):
                        if max_scale is None:
                            max_scale = len(data) // 4
                        
                        # Integrate the data
                        integrated = np.cumsum(data - np.mean(data))
                        
                        scales = np.logspace(np.log10(min_scale), np.log10(max_scale), 20).astype(int)
                        scales = np.unique(scales)
                        
                        fluctuations = []
                        
                        for scale in scales:
                            # Divide into non-overlapping segments
                            n_segments = len(integrated) // scale
                            if n_segments < 2:
                                continue
                            
                            segment_fluctuations = []
                            for i in range(n_segments):
                                start = i * scale
                                end = (i + 1) * scale
                                segment = integrated[start:end]
                                
                                # Fit linear trend to segment
                                x = np.arange(len(segment))
                                coeffs = np.polyfit(x, segment, 1)
                                trend = np.polyval(coeffs, x)
                                
                                # Calculate fluctuation
                                fluctuation = np.sqrt(np.mean((segment - trend)**2))
                                segment_fluctuations.append(fluctuation)
                            
                            if segment_fluctuations:
                                fluctuations.append(np.mean(segment_fluctuations))
                            else:
                                fluctuations.append(np.nan)
                        
                        # Remove NaN values
                        valid_indices = ~np.isnan(fluctuations)
                        scales = scales[valid_indices]
                        fluctuations = np.array(fluctuations)[valid_indices]
                        
                        if len(scales) < 3 or len(fluctuations) < 3:
                            return None, None
                        
                        # Fit power law: F(n) ~ n^alpha
                        log_scales = np.log10(scales)
                        log_fluctuations = np.log10(fluctuations)
                        
                        # Remove infinite or NaN values
                        valid = np.isfinite(log_scales) & np.isfinite(log_fluctuations)
                        if np.sum(valid) < 3:
                            return None, None
                        
                        alpha, intercept, r_value, p_value, std_err = stats.linregress(
                            log_scales[valid], log_fluctuations[valid])
                        
                        return alpha, r_value**2
                    
                    alpha, dfa_r_squared = dfa_analysis(values_clean)
                    
                    if alpha is not None and dfa_r_squared is not None:
                        # Interpret DFA exponent
                        if alpha < 0.5:
                            correlation_type = 'anti-correlated'
                        elif alpha > 0.5:
                            correlation_type = 'long-range_correlated'
                        else:
                            correlation_type = 'uncorrelated'
                        
                        patterns.append({
                            'type': 'detrended_fluctuation_analysis',
                            'dfa_exponent': float(alpha),
                            'r_squared': float(dfa_r_squared),
                            'correlation_type': correlation_type,
                            'long_memory': float(alpha > 0.5),
                            'confidence': min(0.8, dfa_r_squared)
                        })
                        
                except Exception as e:
                    self.logger.warning(f"DFA analysis failed: {e}")
            
            return patterns
            
        except Exception as e:
            self.logger.error(f"Error in long-term trend detection: {e}")
            return []
    def _detect_geological_cycles(self, values: List[float]) -> List[Dict[str, Any]]:
        """
        Detect geological cycles using wavelet analysis and geological time series methods
        """
        if len(values) < 50:  # Need sufficient data for geological cycles
            return []
        
        try:
            patterns = []
            values_array = np.array(values, dtype=float)
            
            # Handle missing data
            valid_mask = ~np.isnan(values_array)
            if np.sum(valid_mask) < 30:
                return []
            
            values_clean = values_array[valid_mask]
            
            # Wavelet analysis for multi-scale cycle detection
            try:
                import pywt
                
                # Continuous wavelet transform
                scales = np.arange(2, min(len(values_clean)//4, 100))
                wavelet = 'morl'  # Morlet wavelet for oscillatory patterns
                
                coefficients, frequencies = pywt.cwt(values_clean, scales, wavelet)
                
                # Power spectrum
                power = np.abs(coefficients) ** 2
                
                # Find dominant scales/periods
                scale_power = np.mean(power, axis=1)
                dominant_scales = scales[scale_power > np.percentile(scale_power, 80)]
                
                # Convert scales to periods (geological interpretation)
                for scale in dominant_scales:
                    # Approximate period in time units (assuming monthly data)
                    period_months = scale * 2  # Morlet wavelet scale-to-period conversion
                    period_years = period_months / 12
                    
                    # Geological cycle classification
                    if 0.5 <= period_years <= 2:
                        cycle_type = 'short_term_volcanic'
                    elif 2 <= period_years <= 10:
                        cycle_type = 'intermediate_magmatic'
                    elif 10 <= period_years <= 50:
                        cycle_type = 'long_term_tectonic'
                    elif 50 <= period_years <= 200:
                        cycle_type = 'super_cycle'
                    else:
                        cycle_type = 'unknown'
                    
                    # Calculate cycle strength and coherence
                    scale_idx = np.where(scales == scale)[0][0]
                    cycle_power = scale_power[scale_idx]
                    relative_power = cycle_power / np.sum(scale_power)
                    
                    # Phase coherence analysis
                    phase = np.angle(coefficients[scale_idx, :])
                    phase_coherence = np.abs(np.mean(np.exp(1j * phase)))
                    
                    patterns.append({
                        'type': 'geological_wavelet_cycle',
                        'scale': float(scale),
                        'period_months': float(period_months),
                        'period_years': float(period_years),
                        'cycle_type': cycle_type,
                        'power': float(cycle_power),
                        'relative_power': float(relative_power),
                        'phase_coherence': float(phase_coherence),
                        'confidence': min(0.9, relative_power * 5 + phase_coherence * 0.3)
                    })
                    
            except ImportError:
                self.logger.warning("PyWavelets not available, skipping wavelet analysis")
            except Exception as e:
                self.logger.warning(f"Wavelet analysis failed: {e}")
            
            # Geological time series analysis using spectral methods
            from scipy.signal import lombscargle, find_peaks
            from scipy.stats import pearsonr
            
            # Lomb-Scargle periodogram for unevenly sampled data
            time = np.arange(len(values_clean))
            
            # Define frequency range for geological processes
            # Focus on periods from months to decades
            min_period = 3  # 3 months
            max_period = min(len(values_clean) // 3, 240)  # Up to 20 years or 1/3 data length
            
            frequencies = np.linspace(1/max_period, 1/min_period, 200)
            
            try:
                pgram = lombscargle(time, values_clean, frequencies, normalize=True)
                
                # Find significant peaks
                peaks, properties = find_peaks(pgram, height=np.percentile(pgram, 75), distance=5)
                
                for peak_idx in peaks:
                    freq = frequencies[peak_idx]
                    period = 1 / freq
                    power = pgram[peak_idx]
                    
                    # Geological interpretation of periods
                    if period < 6:  # Less than 6 months
                        geological_process = 'short_term_unrest'
                    elif 6 <= period < 12:  # 6-12 months
                        geological_process = 'seasonal_geological'
                    elif 12 <= period < 60:  # 1-5 years
                        geological_process = 'eruption_cycle'
                    elif 60 <= period < 120:  # 5-10 years
                        geological_process = 'volcanic_cycle'
                    else:  # More than 10 years
                        geological_process = 'tectonic_cycle'
                    
                    # Calculate statistical significance
                    # Bootstrap significance test
                    n_bootstrap = 100
                    bootstrap_powers = []
                    
                    for _ in range(n_bootstrap):
                        shuffled_values = np.random.permutation(values_clean)
                        bootstrap_pgram = lombscargle(time, shuffled_values, frequencies, normalize=True)
                        bootstrap_powers.append(np.max(bootstrap_pgram))
                    
                    significance_threshold = np.percentile(bootstrap_powers, 95)
                    is_significant = power > significance_threshold
                    
                    patterns.append({
                        'type': 'geological_spectral_cycle',
                        'frequency': float(freq),
                        'period_months': float(period),
                        'period_years': float(period / 12),
                        'power': float(power),
                        'geological_process': geological_process,
                        'statistical_significance': bool(is_significant),
                        'significance_level': float(power / significance_threshold),
                        'confidence': min(0.95, power * 2) if is_significant else max(0.1, power)
                    })
                    
            except Exception as e:
                self.logger.warning(f"Lomb-Scargle analysis failed: {e}")
            
            # Geological cycle detection using autocorrelation and cross-correlation
            from scipy.signal import correlate
            from statsmodels.tsa.stattools import acf, ccf
            
            # Autocorrelation analysis for cyclic patterns
            if len(values_clean) >= 24:
                try:
                    # Calculate autocorrelation function
                    max_lags = min(len(values_clean) // 3, 60)  # Up to 5 years for monthly data
                    autocorr = acf(values_clean, nlags=max_lags, fft=True)
                    
                    # Find peaks in autocorrelation (indicating periodicity)
                    acf_peaks, acf_properties = find_peaks(autocorr[1:], height=0.2, distance=3)
                    acf_peaks += 1  # Adjust for skipped lag 0
                    
                    for peak_lag in acf_peaks:
                        correlation_value = autocorr[peak_lag]
                        period_months = peak_lag
                        period_years = period_months / 12
                        
                        # Geological interpretation
                        if period_years < 1:
                            cycle_category = 'short_term'
                        elif 1 <= period_years < 5:
                            cycle_category = 'intermediate_term'
                        else:
                            cycle_category = 'long_term'
                        
                        patterns.append({
                            'type': 'geological_autocorrelation_cycle',
                            'lag_months': int(peak_lag),
                            'period_years': float(period_years),
                            'correlation': float(correlation_value),
                            'cycle_category': cycle_category,
                            'strength': float(abs(correlation_value)),
                            'confidence': min(0.85, abs(correlation_value) * 2)
                        })
                        
                except Exception as e:
                    self.logger.warning(f"Autocorrelation analysis failed: {e}")
            
            # Detection of geological regime transitions
            if len(values_clean) >= 36:
                # Using change point detection for geological regimes
                from scipy.stats import f_oneway
                
                # Sliding window variance analysis
                window_size = min(12, len(values_clean) // 6)
                variances = []
                means = []
                
                for i in range(len(values_clean) - window_size + 1):
                    window = values_clean[i:i + window_size]
                    variances.append(np.var(window))
                    means.append(np.mean(window))
                
                # Detect significant changes in variance (regime changes)
                variance_changes = []
                mean_changes = []
                
                for i in range(6, len(variances) - 6):  # Avoid edges
                    before_var = variances[i-6:i]
                    after_var = variances[i:i+6]
                    
                    before_mean = means[i-6:i]
                    after_mean = means[i:i+6]
                    
                    # Statistical test for variance change
                    var_ratio = np.mean(after_var) / np.mean(before_var) if np.mean(before_var) > 0 else 1
                    mean_change = abs(np.mean(after_mean) - np.mean(before_mean))
                    
                    # Threshold for regime change detection
                    if var_ratio > 1.5 or var_ratio < 0.67 or mean_change > np.std(values_clean) * 0.5:
                        change_point = i + window_size // 2
                        
                        # Determine regime type
                        if var_ratio > 1.5:
                            regime_change = 'increasing_volatility'
                        elif var_ratio < 0.67:
                            regime_change = 'decreasing_volatility'
                        else:
                            regime_change = 'mean_shift'
                        
                        patterns.append({
                            'type': 'geological_regime_change',
                            'change_point_index': int(change_point),
                            'regime_change_type': regime_change,
                            'variance_ratio': float(var_ratio),
                            'mean_change_magnitude': float(mean_change),
                            'confidence': min(0.8, max(abs(np.log(var_ratio)), mean_change / np.std(values_clean)))
                        })
            
            # Milankovitch-like cycle detection (very long-term cycles)
            if len(values_clean) >= 120:  # Need 10+ years of data
                # Look for very long period cycles that might represent
                # geological or climate oscillations
                very_long_periods = [60, 84, 120, 180, 240]  # 5-20 years
                
                for test_period in very_long_periods:
                    if test_period < len(values_clean) // 2:
                        # Test for periodicity at this scale
                        n_cycles = len(values_clean) // test_period
                        
                        if n_cycles >= 2:
                            # Calculate correlation between cycles
                            cycle_correlations = []
                            
                            for i in range(n_cycles - 1):
                                cycle1 = values_clean[i*test_period:(i+1)*test_period]
                                cycle2 = values_clean[(i+1)*test_period:(i+2)*test_period]
                                
                                if len(cycle1) == len(cycle2) == test_period:
                                    try:
                                        corr, p_val = pearsonr(cycle1, cycle2)
                                        if not np.isnan(corr):
                                            cycle_correlations.append(corr)
                                    except:
                                        pass
                            
                            if cycle_correlations:
                                avg_correlation = np.mean(cycle_correlations)
                                
                                if avg_correlation > 0.3:  # Threshold for cycle detection
                                    patterns.append({
                                        'type': 'geological_long_cycle',
                                        'period_months': int(test_period),
                                        'period_years': float(test_period / 12),
                                        'n_cycles_detected': int(n_cycles),
                                        'cycle_correlation': float(avg_correlation),
                                        'cycle_consistency': float(1 - np.std(cycle_correlations)) if len(cycle_correlations) > 1 else 1.0,
                                        'geological_scale': 'decadal' if test_period < 120 else 'multi_decadal',
                                        'confidence': min(0.75, avg_correlation * 1.5)
                                    })
            
            return patterns
            
        except Exception as e:
            self.logger.error(f"Error in geological cycle detection: {e}")
            return []
    def _detect_trend_patterns(self, values: List[float]) -> List[Dict[str, Any]]:
        """
        Detect trend patterns using machine learning and statistical trend analysis
        """
        if len(values) < 12:
            return []
        
        try:
            patterns = []
            values_array = np.array(values, dtype=float)
            
            # Handle missing data
            valid_mask = ~np.isnan(values_array)
            if np.sum(valid_mask) < 6:
                return []
            
            values_clean = values_array[valid_mask]
            time_indices = np.arange(len(values_clean))
            
            # ML-based trend detection using various regressors
            from sklearn.ensemble import RandomForestRegressor, GradientBoostingRegressor
            from sklearn.linear_model import LinearRegression, Ridge, Lasso
            from sklearn.preprocessing import PolynomialFeatures
            from sklearn.metrics import r2_score
            from sklearn.model_selection import cross_val_score
            
            X = time_indices.reshape(-1, 1)
            
            # Test multiple models for trend detection
            models = {
                'linear': LinearRegression(),
                'ridge': Ridge(alpha=1.0),
                'lasso': Lasso(alpha=0.1),
                'random_forest': RandomForestRegressor(n_estimators=50, random_state=42),
                'gradient_boosting': GradientBoostingRegressor(n_estimators=50, random_state=42)
            }
            
            for model_name, model in models.items():
                try:
                    # Fit model
                    model.fit(X, values_clean)
                    predictions = model.predict(X)
                    
                    # Calculate metrics
                    r2 = r2_score(values_clean, predictions)
                    
                    # Cross-validation score
                    cv_scores = cross_val_score(model, X, values_clean, cv=min(5, len(values_clean)//3))
                    cv_mean = np.mean(cv_scores)
                    
                    # Extract trend characteristics
                    trend_direction = 'increasing' if predictions[-1] > predictions[0] else 'decreasing'
                    trend_strength = abs(predictions[-1] - predictions[0]) / np.std(values_clean)
                    
                    # Feature importance for tree-based models
                    feature_importance = None
                    if hasattr(model, 'feature_importances_'):
                        feature_importance = float(model.feature_importances_[0])
                    elif hasattr(model, 'coef_'):
                        feature_importance = float(abs(model.coef_[0]))
                    
                    patterns.append({
                        'type': f'ml_trend_{model_name}',
                        'model_type': model_name,
                        'r_squared': float(r2),
                        'cv_score': float(cv_mean),
                        'trend_direction': trend_direction,
                        'trend_strength': float(trend_strength),
                        'feature_importance': feature_importance,
                        'confidence': min(0.9, max(r2, cv_mean))
                    })
                    
                except Exception as e:
                    self.logger.warning(f"ML trend model {model_name} failed: {e}")
            
            # Statistical trend pattern classification
            from scipy.stats import linregress, pearsonr, spearmanr
            
            # Linear trend analysis
            slope, intercept, r_value, p_value, std_err = linregress(time_indices, values_clean)
            
            # Monotonicity test
            def check_monotonicity(values):
                increasing = all(values[i] <= values[i+1] for i in range(len(values)-1))
                decreasing = all(values[i] >= values[i+1] for i in range(len(values)-1))
                return 'monotonic_increasing' if increasing else 'monotonic_decreasing' if decreasing else 'non_monotonic'
            
            monotonicity = check_monotonicity(values_clean)
            
            # Trend acceleration analysis
            if len(values_clean) >= 6:
                # Second derivative approximation
                second_deriv = np.diff(values_clean, n=2)
                acceleration_trend = 'accelerating' if np.mean(second_deriv) > 0 else 'decelerating'
                acceleration_strength = abs(np.mean(second_deriv))
            else:
                acceleration_trend = 'unknown'
                acceleration_strength = 0
            
            # Trend persistence analysis
            trend_changes = 0
            window_size = max(3, len(values_clean) // 10)
            
            for i in range(window_size, len(values_clean) - window_size):
                before = np.mean(values_clean[i-window_size:i])
                after = np.mean(values_clean[i:i+window_size])
                current_trend = 'up' if after > before else 'down'
                
                if i == window_size:
                    prev_trend = current_trend
                elif current_trend != prev_trend:
                    trend_changes += 1
                    prev_trend = current_trend
            
            trend_persistence = 1 - (trend_changes / max(1, (len(values_clean) // window_size - 2)))
            
            patterns.append({
                'type': 'statistical_trend_analysis',
                'linear_slope': float(slope),
                'linear_r_squared': float(r_value**2),
                'linear_p_value': float(p_value),
                'monotonicity': monotonicity,
                'acceleration_trend': acceleration_trend,
                'acceleration_strength': float(acceleration_strength),
                'trend_persistence': float(trend_persistence),
                'trend_changes': int(trend_changes),
                'confidence': min(0.95, (1 - p_value) if p_value > 0 else 0.5)
            })
            
            return patterns
            
        except Exception as e:
            self.logger.error(f"Error in trend pattern detection: {e}")
            return []
    def _detect_cyclic_patterns(self, values: List[float]) -> List[Dict[str, Any]]:
        """
        Detect cyclic patterns using Fourier analysis and autocorrelation methods
        """
        if len(values) < 8:
            return []
        
        try:
            patterns = []
            values_array = np.array(values, dtype=float)
            
            # Handle missing data
            valid_mask = ~np.isnan(values_array)
            if np.sum(valid_mask) < 6:
                return []
            
            values_clean = values_array[valid_mask]
            
            # Fourier Transform Analysis
            from scipy.fft import fft, fftfreq
            from scipy.signal import find_peaks, hilbert
            
            # Compute FFT
            fft_values = fft(values_clean)
            frequencies = fftfreq(len(values_clean), 1.0)
            
            # Power spectrum
            power_spectrum = np.abs(fft_values)**2
            
            # Find peaks in power spectrum (positive frequencies only)
            positive_freq_mask = frequencies > 0
            pos_frequencies = frequencies[positive_freq_mask]
            pos_power = power_spectrum[positive_freq_mask]
            
            # Detect significant peaks
            peaks, properties = find_peaks(pos_power, height=np.percentile(pos_power, 70), distance=2)
            
            for peak_idx in peaks:
                freq = pos_frequencies[peak_idx]
                power = pos_power[peak_idx]
                period = 1.0 / freq if freq > 0 else float('inf')
                
                # Skip very long periods that might not be meaningful
                if period < len(values_clean):
                    relative_power = power / np.sum(pos_power)
                    
                    patterns.append({
                        'type': 'fourier_cyclic',
                        'frequency': float(freq),
                        'period': float(period),
                        'power': float(power),
                        'relative_power': float(relative_power),
                        'confidence': min(0.9, relative_power * 10)
                    })
            
            # Autocorrelation-based cycle detection
            from statsmodels.tsa.stattools import acf
            
            if len(values_clean) >= 6:
                max_lags = min(len(values_clean) - 1, len(values_clean) // 2)
                autocorr = acf(values_clean, nlags=max_lags, fft=True)
                
                # Find peaks in autocorrelation function
                acf_peaks, acf_properties = find_peaks(autocorr[1:], height=0.1, distance=1)
                acf_peaks += 1  # Adjust for skipped lag 0
                
                for peak_lag in acf_peaks:
                    correlation_value = autocorr[peak_lag]
                    period = peak_lag
                    
                    patterns.append({
                        'type': 'autocorrelation_cyclic',
                        'period': int(period),
                        'correlation': float(correlation_value),
                        'strength': float(abs(correlation_value)),
                        'confidence': min(0.85, abs(correlation_value) * 2)
                    })
            
            # Phase-based cycle analysis using Hilbert transform
            try:
                analytic_signal = hilbert(values_clean)
                amplitude_envelope = np.abs(analytic_signal)
                instantaneous_phase = np.unwrap(np.angle(analytic_signal))
                instantaneous_frequency = np.diff(instantaneous_phase) / (2.0 * np.pi)
                
                # Analyze phase consistency
                phase_consistency = np.std(instantaneous_frequency) if len(instantaneous_frequency) > 0 else 0
                mean_frequency = np.mean(instantaneous_frequency) if len(instantaneous_frequency) > 0 else 0
                mean_period = 1.0 / mean_frequency if mean_frequency > 0 else 0
                
                # Amplitude modulation analysis
                amplitude_cv = np.std(amplitude_envelope) / np.mean(amplitude_envelope) if np.mean(amplitude_envelope) > 0 else 0
                
                if mean_period > 2 and mean_period < len(values_clean) / 2:
                    patterns.append({
                        'type': 'hilbert_cyclic',
                        'mean_frequency': float(mean_frequency),
                        'mean_period': float(mean_period),
                        'phase_consistency': float(1.0 / (1.0 + phase_consistency)),  # Higher is more consistent
                        'amplitude_modulation': float(amplitude_cv),
                        'confidence': min(0.8, 1.0 / (1.0 + phase_consistency + amplitude_cv))
                    })
                    
            except Exception as e:
                self.logger.warning(f"Hilbert transform analysis failed: {e}")
            
            # Cycle detection using sliding window correlation
            if len(values_clean) >= 12:
                for test_period in range(2, min(len(values_clean) // 3, 20)):
                    # Create reference cycle
                    cycle_correlations = []
                    
                    # Test correlation with shifted versions
                    for shift in range(0, len(values_clean) - test_period, test_period):
                        if shift + 2 * test_period <= len(values_clean):
                            segment1 = values_clean[shift:shift + test_period]
                            segment2 = values_clean[shift + test_period:shift + 2 * test_period]
                            
                            if len(segment1) == len(segment2) == test_period:
                                corr = np.corrcoef(segment1, segment2)[0, 1]
                                if not np.isnan(corr):
                                    cycle_correlations.append(corr)
                    
                    if cycle_correlations:
                        mean_correlation = np.mean(cycle_correlations)
                        correlation_stability = 1.0 - np.std(cycle_correlations)
                        
                        if mean_correlation > 0.3:  # Threshold for meaningful cycles
                            patterns.append({
                                'type': 'sliding_window_cyclic',
                                'period': int(test_period),
                                'mean_correlation': float(mean_correlation),
                                'correlation_stability': float(correlation_stability),
                                'n_cycles_tested': len(cycle_correlations),
                                'confidence': min(0.8, mean_correlation * correlation_stability)
                            })
            
            return patterns
            
        except Exception as e:
            self.logger.error(f"Error in cyclic pattern detection: {e}")
            return []
    def _detect_anomaly_patterns(self, values: List[float]) -> List[Dict[str, Any]]:
        """
        Detect anomaly patterns using isolation forests and statistical methods
        """
        if len(values) < 5:
            return []
        
        try:
            patterns = []
            values_array = np.array(values, dtype=float)
            
            # Handle missing data
            valid_mask = ~np.isnan(values_array)
            if np.sum(valid_mask) < 3:
                return []
            
            values_clean = values_array[valid_mask]
            
            # Multiple anomaly detection methods
            from sklearn.ensemble import IsolationForest
            from sklearn.svm import OneClassSVM
            from sklearn.cluster import DBSCAN
            from scipy import stats
            
            # 1. Isolation Forest anomaly detection
            try:
                iso_forest = IsolationForest(contamination=0.1, random_state=42, n_estimators=100)
                X = values_clean.reshape(-1, 1)
                anomaly_labels = iso_forest.fit_predict(X)
                anomaly_scores = iso_forest.score_samples(X)
                
                anomaly_indices = np.where(anomaly_labels == -1)[0]
                
                if len(anomaly_indices) > 0:
                    anomaly_values = values_clean[anomaly_indices]
                    anomaly_scores_subset = anomaly_scores[anomaly_indices]
                    
                    patterns.append({
                        'type': 'isolation_forest_anomalies',
                        'anomaly_indices': anomaly_indices.tolist(),
                        'anomaly_values': anomaly_values.tolist(),
                        'anomaly_scores': anomaly_scores_subset.tolist(),
                        'n_anomalies': len(anomaly_indices),
                        'anomaly_rate': float(len(anomaly_indices) / len(values_clean)),
                        'confidence': 0.8
                    })
                    
            except Exception as e:
                self.logger.warning(f"Isolation Forest failed: {e}")
            
            # 2. Statistical anomaly detection (Z-score and modified Z-score)
            mean_val = np.mean(values_clean)
            std_val = np.std(values_clean)
            
            if std_val > 0:
                z_scores = np.abs((values_clean - mean_val) / std_val)
                z_anomalies = np.where(z_scores > 3.0)[0]  # 3-sigma rule
                
                if len(z_anomalies) > 0:
                    patterns.append({
                        'type': 'zscore_anomalies',
                        'anomaly_indices': z_anomalies.tolist(),
                        'anomaly_values': values_clean[z_anomalies].tolist(),
                        'z_scores': z_scores[z_anomalies].tolist(),
                        'n_anomalies': len(z_anomalies),
                        'threshold': 3.0,
                        'confidence': 0.85
                    })
            
            # 3. Modified Z-score using median absolute deviation (robust)
            median_val = np.median(values_clean)
            mad = np.median(np.abs(values_clean - median_val))
            
            if mad > 0:
                modified_z_scores = 0.6745 * (values_clean - median_val) / mad
                modified_z_anomalies = np.where(np.abs(modified_z_scores) > 3.5)[0]
                
                if len(modified_z_anomalies) > 0:
                    patterns.append({
                        'type': 'modified_zscore_anomalies',
                        'anomaly_indices': modified_z_anomalies.tolist(),
                        'anomaly_values': values_clean[modified_z_anomalies].tolist(),
                        'modified_z_scores': modified_z_scores[modified_z_anomalies].tolist(),
                        'n_anomalies': len(modified_z_anomalies),
                        'robust_method': True,
                        'confidence': 0.9
                    })
            
            # 4. Interquartile Range (IQR) method
            q75, q25 = np.percentile(values_clean, [75, 25])
            iqr = q75 - q25
            
            if iqr > 0:
                lower_bound = q25 - (1.5 * iqr)
                upper_bound = q75 + (1.5 * iqr)
                
                iqr_anomalies = np.where((values_clean < lower_bound) | (values_clean > upper_bound))[0]
                
                if len(iqr_anomalies) > 0:
                    patterns.append({
                        'type': 'iqr_anomalies',
                        'anomaly_indices': iqr_anomalies.tolist(),
                        'anomaly_values': values_clean[iqr_anomalies].tolist(),
                        'lower_bound': float(lower_bound),
                        'upper_bound': float(upper_bound),
                        'iqr': float(iqr),
                        'n_anomalies': len(iqr_anomalies),
                        'confidence': 0.75
                    })
            
            # 5. Local Outlier Factor (LOF) if sufficient data
            if len(values_clean) >= 10:
                try:
                    from sklearn.neighbors import LocalOutlierFactor
                    
                    lof = LocalOutlierFactor(n_neighbors=min(5, len(values_clean)-1), contamination=0.1)
                    X = values_clean.reshape(-1, 1)
                    lof_labels = lof.fit_predict(X)
                    lof_scores = -lof.negative_outlier_factor_
                    
                    lof_anomalies = np.where(lof_labels == -1)[0]
                    
                    if len(lof_anomalies) > 0:
                        patterns.append({
                            'type': 'local_outlier_factor_anomalies',
                            'anomaly_indices': lof_anomalies.tolist(),
                            'anomaly_values': values_clean[lof_anomalies].tolist(),
                            'lof_scores': lof_scores[lof_anomalies].tolist(),
                            'n_anomalies': len(lof_anomalies),
                            'local_density_based': True,
                            'confidence': 0.8
                        })
                        
                except Exception as e:
                    self.logger.warning(f"LOF anomaly detection failed: {e}")
            
            # 6. DBSCAN clustering for anomaly detection
            if len(values_clean) >= 8:
                try:
                    X = values_clean.reshape(-1, 1)
                    # Adaptive epsilon based on data spread
                    eps = np.std(values_clean) * 0.5
                    dbscan = DBSCAN(eps=eps, min_samples=max(2, len(values_clean)//10))
                    cluster_labels = dbscan.fit_predict(X)
                    
                    # Points labeled as -1 are outliers
                    dbscan_anomalies = np.where(cluster_labels == -1)[0]
                    
                    if len(dbscan_anomalies) > 0 and len(dbscan_anomalies) < len(values_clean) * 0.5:
                        patterns.append({
                            'type': 'dbscan_anomalies',
                            'anomaly_indices': dbscan_anomalies.tolist(),
                            'anomaly_values': values_clean[dbscan_anomalies].tolist(),
                            'n_anomalies': len(dbscan_anomalies),
                            'n_clusters': len(set(cluster_labels)) - (1 if -1 in cluster_labels else 0),
                            'density_based': True,
                            'confidence': 0.7
                        })
                        
                except Exception as e:
                    self.logger.warning(f"DBSCAN anomaly detection failed: {e}")
            
            # 7. Time series specific anomalies (if data has temporal structure)
            if len(values_clean) >= 6:
                # Moving average based anomaly detection
                window_size = max(3, len(values_clean) // 5)
                
                # Calculate rolling statistics
                rolling_means = []
                rolling_stds = []
                
                for i in range(len(values_clean)):
                    start_idx = max(0, i - window_size // 2)
                    end_idx = min(len(values_clean), i + window_size // 2 + 1)
                    window_data = values_clean[start_idx:end_idx]
                    
                    rolling_means.append(np.mean(window_data))
                    rolling_stds.append(np.std(window_data))
                
                rolling_means = np.array(rolling_means)
                rolling_stds = np.array(rolling_stds)
                
                # Detect points that deviate significantly from local trend
                deviations = np.abs(values_clean - rolling_means)
                threshold = rolling_stds * 2.5  # Adaptive threshold
                
                ts_anomalies = np.where(deviations > threshold)[0]
                
                if len(ts_anomalies) > 0:
                    patterns.append({
                        'type': 'time_series_anomalies',
                        'anomaly_indices': ts_anomalies.tolist(),
                        'anomaly_values': values_clean[ts_anomalies].tolist(),
                        'deviations': deviations[ts_anomalies].tolist(),
                        'local_thresholds': threshold[ts_anomalies].tolist(),
                        'n_anomalies': len(ts_anomalies),
                        'adaptive_threshold': True,
                        'confidence': 0.75
                    })
            
            # 8. Grubbs' test for outliers (if data is approximately normal)
            if len(values_clean) >= 7:
                try:
                    from scipy.stats import t
                    
                    def grubbs_test(data, alpha=0.05):
                        n = len(data)
                        mean = np.mean(data)
                        std = np.std(data, ddof=1)
                        
                        if std == 0:
                            return []
                        
                        # Calculate Grubbs statistic for each point
                        G = np.abs((data - mean) / std)
                        max_G_idx = np.argmax(G)
                        max_G = G[max_G_idx]
                        
                        # Critical value
                        t_critical = t.ppf(1 - alpha/(2*n), n-2)
                        G_critical = ((n-1) * np.sqrt(t_critical**2)) / np.sqrt(n * (n-2 + t_critical**2))
                        
                        if max_G > G_critical:
                            return [max_G_idx]
                        else:
                            return []
                    
                    grubbs_anomalies = grubbs_test(values_clean)
                    
                    if grubbs_anomalies:
                        patterns.append({
                            'type': 'grubbs_test_anomalies',
                            'anomaly_indices': grubbs_anomalies,
                            'anomaly_values': values_clean[grubbs_anomalies].tolist(),
                            'n_anomalies': len(grubbs_anomalies),
                            'statistical_test': True,
                            'assumes_normality': True,
                            'confidence': 0.95
                        })
                        
                except Exception as e:
                    self.logger.warning(f"Grubbs test failed: {e}")
            
            return patterns
            
        except Exception as e:
            self.logger.error(f"Error in anomaly pattern detection: {e}")
            return []
    def _detect_regime_changes(self, values: List[float]) -> List[Dict[str, Any]]:
        """
        Detect regime changes using change point algorithms and statistical tests
        """
        if len(values) < 10:
            return []
        
        try:
            patterns = []
            values_array = np.array(values, dtype=float)
            
            # Handle missing data
            valid_mask = ~np.isnan(values_array)
            if np.sum(valid_mask) < 8:
                return []
            
            values_clean = values_array[valid_mask]
            
            # Multiple change point detection methods
            from scipy import stats
            from scipy.stats import f_oneway, bartlett, levene
            
            # 1. CUSUM (Cumulative Sum) change point detection
            mean_val = np.mean(values_clean)
            cusum_pos = np.zeros(len(values_clean))
            cusum_neg = np.zeros(len(values_clean))
            
            # Threshold based on standard deviation
            threshold = 2 * np.std(values_clean)
            
            for i in range(1, len(values_clean)):
                cusum_pos[i] = max(0, cusum_pos[i-1] + (values_clean[i] - mean_val - threshold/2))
                cusum_neg[i] = max(0, cusum_neg[i-1] - (values_clean[i] - mean_val + threshold/2))
            
            # Detect change points
            cusum_changes = []
            for i in range(1, len(values_clean)):
                if cusum_pos[i] > threshold or cusum_neg[i] > threshold:
                    # Reset and record change point
                    cusum_changes.append({
                        'index': int(i),
                        'type': 'mean_shift_up' if cusum_pos[i] > threshold else 'mean_shift_down',
                        'magnitude': float(max(cusum_pos[i], cusum_neg[i])),
                        'confidence': min(0.8, max(cusum_pos[i], cusum_neg[i]) / threshold)
                    })
                    cusum_pos[i] = 0
                    cusum_neg[i] = 0
            
            if cusum_changes:
                patterns.append({
                    'type': 'cusum_regime_changes',
                    'change_points': cusum_changes,
                    'n_changes': len(cusum_changes),
                    'method': 'cumulative_sum',
                    'confidence': 0.8
                })
            
            # 2. Sliding window variance change detection
            window_size = max(5, len(values_clean) // 8)
            variance_changes = []
            
            for i in range(window_size, len(values_clean) - window_size):
                before_window = values_clean[i-window_size:i]
                after_window = values_clean[i:i+window_size]
                
                var_before = np.var(before_window)
                var_after = np.var(after_window)
                
                # F-test for variance change
                if var_before > 0 and var_after > 0:
                    f_stat = max(var_after, var_before) / min(var_after, var_before)
                    
                    # Critical value for F-test (simplified)
                    f_critical = 2.0  # Approximate for moderate sample sizes
                    
                    if f_stat > f_critical:
                        variance_changes.append({
                            'index': int(i),
                            'variance_before': float(var_before),
                            'variance_after': float(var_after),
                            'f_statistic': float(f_stat),
                            'change_type': 'variance_increase' if var_after > var_before else 'variance_decrease',
                            'confidence': min(0.9, f_stat / f_critical - 1)
                        })
            
            if variance_changes:
                patterns.append({
                    'type': 'variance_regime_changes',
                    'change_points': variance_changes,
                    'n_changes': len(variance_changes),
                    'method': 'sliding_window_variance',
                    'confidence': 0.75
                })
            
            # 3. Binary segmentation for mean change detection
            def binary_segmentation(data, min_size=5):
                def find_best_split(segment, start_idx):
                    n = len(segment)
                    if n < 2 * min_size:
                        return None
                    
                    best_split = None
                    best_stat = 0
                    
                    for split_point in range(min_size, n - min_size + 1):
                        left = segment[:split_point]
                        right = segment[split_point:]
                        
                        # T-test for mean difference
                        if len(left) >= 2 and len(right) >= 2:
                            t_stat, p_val = stats.ttest_ind(left, right)
                            if not np.isnan(t_stat) and abs(t_stat) > best_stat:
                                best_stat = abs(t_stat)
                                best_split = {
                                    'index': start_idx + split_point,
                                    't_statistic': float(t_stat),
                                    'p_value': float(p_val),
                                    'mean_before': float(np.mean(left)),
                                    'mean_after': float(np.mean(right)),
                                    'confidence': min(0.95, abs(t_stat) / 2)
                                }
                    
                    return best_split if best_stat > 2.0 else None  # Threshold for significance
                
                change_points = []
                segments_to_process = [(data, 0)]
                
                while segments_to_process:
                    segment, start_idx = segments_to_process.pop(0)
                    split = find_best_split(segment, start_idx)
                    
                    if split:
                        change_points.append(split)
                        split_idx = split['index'] - start_idx
                        
                        # Add left and right segments for further processing
                        left_segment = segment[:split_idx]
                        right_segment = segment[split_idx:]
                        
                        if len(left_segment) >= 2 * min_size:
                            segments_to_process.append((left_segment, start_idx))
                        if len(right_segment) >= 2 * min_size:
                            segments_to_process.append((right_segment, start_idx + split_idx))
                
                return change_points
            
            binary_changes = binary_segmentation(values_clean)
            
            if binary_changes:
                patterns.append({
                    'type': 'binary_segmentation_changes',
                    'change_points': binary_changes,
                    'n_changes': len(binary_changes),
                    'method': 'binary_segmentation',
                    'confidence': 0.85
                })
            
            # 4. Page-Hinkley test for online change detection
            ph_threshold = 3 * np.std(values_clean)
            ph_delta = np.std(values_clean) * 0.5  # Minimum change to detect
            
            page_hinkley_changes = []
            cumsum_ph = 0
            min_cumsum = 0
            
            for i in range(1, len(values_clean)):
                diff = values_clean[i] - values_clean[i-1]
                cumsum_ph += diff - ph_delta
                min_cumsum = min(min_cumsum, cumsum_ph)
                
                test_statistic = cumsum_ph - min_cumsum
                
                if test_statistic > ph_threshold:
                    page_hinkley_changes.append({
                        'index': int(i),
                        'test_statistic': float(test_statistic),
                        'threshold': float(ph_threshold),
                        'confidence': min(0.9, test_statistic / ph_threshold)
                    })
                    # Reset
                    cumsum_ph = 0
                    min_cumsum = 0
            
            if page_hinkley_changes:
                patterns.append({
                    'type': 'page_hinkley_changes',
                    'change_points': page_hinkley_changes,
                    'n_changes': len(page_hinkley_changes),
                    'method': 'page_hinkley_test',
                    'online_detection': True,
                    'confidence': 0.8
                })
            
            # 5. E-divisive method (energy-based change point detection)
            if len(values_clean) >= 20:
                try:
                    def energy_distance(x, y):
                        """Calculate energy distance between two samples"""
                        n, m = len(x), len(y)
                        if n == 0 or m == 0:
                            return 0
                        
                        # Calculate all pairwise distances
                        xx = np.sum([abs(x[i] - x[j]) for i in range(n) for j in range(n)]) / (n * n)
                        yy = np.sum([abs(y[i] - y[j]) for i in range(m) for j in range(m)]) / (m * m)
                        xy = np.sum([abs(x[i] - y[j]) for i in range(n) for j in range(m)]) / (n * m)
                        
                        return 2 * xy - xx - yy
                    
                    energy_changes = []
                    min_segment_size = 5
                    
                    for split_point in range(min_segment_size, len(values_clean) - min_segment_size):
                        left_segment = values_clean[:split_point]
                        right_segment = values_clean[split_point:]
                        
                        energy_stat = energy_distance(left_segment, right_segment)
                        
                        # Threshold based on data characteristics
                        energy_threshold = np.std(values_clean) * 0.1
                        
                        if energy_stat > energy_threshold:
                            energy_changes.append({
                                'index': int(split_point),
                                'energy_statistic': float(energy_stat),
                                'threshold': float(energy_threshold),
                                'confidence': min(0.8, energy_stat / energy_threshold)
                            })
                    
                    # Select most significant changes (to avoid too many detections)
                    if energy_changes:
                        energy_changes.sort(key=lambda x: x['energy_statistic'], reverse=True)
                        top_energy_changes = energy_changes[:min(5, len(energy_changes))]
                        
                        patterns.append({
                            'type': 'energy_based_changes',
                            'change_points': top_energy_changes,
                            'n_changes': len(top_energy_changes),
                            'method': 'energy_divisive',
                            'confidence': 0.75
                        })
                        
                except Exception as e:
                    self.logger.warning(f"Energy-based change detection failed: {e}")
            
            return patterns
            
        except Exception as e:
            self.logger.error(f"Error in regime change detection: {e}")
            return []
    def _detect_oscillatory_patterns(self, values: List[float]) -> List[Dict[str, Any]]:
        """
        Detect oscillatory patterns using signal processing and spectral methods
        """
        if len(values) < 6:
            return []
        
        try:
            patterns = []
            values_array = np.array(values, dtype=float)
            
            # Handle missing data
            valid_mask = ~np.isnan(values_array)
            if np.sum(valid_mask) < 4:
                return []
            
            values_clean = values_array[valid_mask]
            
            # Signal processing for oscillatory patterns
            from scipy.signal import hilbert, find_peaks, butter, filtfilt, welch
            from scipy.fft import fft, fftfreq
            
            # 1. Hilbert transform for instantaneous frequency/amplitude
            try:
                analytic_signal = hilbert(values_clean)
                amplitude_envelope = np.abs(analytic_signal)
                instantaneous_phase = np.unwrap(np.angle(analytic_signal))
                instantaneous_frequency = np.diff(instantaneous_phase) / (2.0 * np.pi)
                
                # Oscillation characteristics
                mean_amplitude = np.mean(amplitude_envelope)
                amplitude_stability = 1.0 - (np.std(amplitude_envelope) / mean_amplitude) if mean_amplitude > 0 else 0
                
                mean_frequency = np.mean(instantaneous_frequency) if len(instantaneous_frequency) > 0 else 0
                frequency_stability = 1.0 - (np.std(instantaneous_frequency) / abs(mean_frequency)) if abs(mean_frequency) > 1e-6 else 0
                
                patterns.append({
                    'type': 'hilbert_oscillatory',
                    'mean_amplitude': float(mean_amplitude),
                    'amplitude_stability': float(max(0, amplitude_stability)),
                    'mean_frequency': float(mean_frequency),
                    'frequency_stability': float(max(0, frequency_stability)),
                    'oscillation_strength': float((amplitude_stability + frequency_stability) / 2),
                    'confidence': min(0.85, (amplitude_stability + frequency_stability) / 2)
                })
                
            except Exception as e:
                self.logger.warning(f"Hilbert transform failed: {e}")
            
            # 2. Peak-based oscillation detection
            peaks, peak_properties = find_peaks(values_clean, distance=2)
            troughs, trough_properties = find_peaks(-values_clean, distance=2)
            
            if len(peaks) >= 2 and len(troughs) >= 2:
                # Calculate peak-to-peak intervals
                peak_intervals = np.diff(peaks)
                trough_intervals = np.diff(troughs)
                
                # Oscillation period consistency
                if len(peak_intervals) > 0:
                    mean_peak_interval = np.mean(peak_intervals)
                    peak_interval_cv = np.std(peak_intervals) / mean_peak_interval if mean_peak_interval > 0 else 1
                    
                    # Amplitude consistency
                    peak_amplitudes = values_clean[peaks]
                    amplitude_cv = np.std(peak_amplitudes) / np.mean(peak_amplitudes) if np.mean(peak_amplitudes) > 0 else 1
                    
                    patterns.append({
                        'type': 'peak_based_oscillatory',
                        'n_peaks': len(peaks),
                        'n_troughs': len(troughs),
                        'mean_period': float(mean_peak_interval),
                        'period_consistency': float(1.0 - min(1.0, peak_interval_cv)),
                        'amplitude_consistency': float(1.0 - min(1.0, amplitude_cv)),
                        'oscillation_regularity': float((1.0 - min(1.0, peak_interval_cv) + 1.0 - min(1.0, amplitude_cv)) / 2),
                        'confidence': min(0.8, (1.0 - min(1.0, peak_interval_cv) + 1.0 - min(1.0, amplitude_cv)) / 2)
                    })
            
            # 3. Spectral analysis for dominant oscillations
            frequencies, power_spectral_density = welch(values_clean, nperseg=min(len(values_clean), 16))
            
            # Find dominant frequencies
            dominant_peaks, _ = find_peaks(power_spectral_density, height=np.percentile(power_spectral_density, 70))
            
            for peak_idx in dominant_peaks[:3]:  # Top 3 dominant frequencies
                freq = frequencies[peak_idx]
                power = power_spectral_density[peak_idx]
                period = 1.0 / freq if freq > 0 else float('inf')
                
                if period < len(values_clean) and period > 2:  # Meaningful oscillation period
                    relative_power = power / np.sum(power_spectral_density)
                    
                    patterns.append({
                        'type': 'spectral_oscillatory',
                        'dominant_frequency': float(freq),
                        'dominant_period': float(period),
                        'spectral_power': float(power),
                        'relative_power': float(relative_power),
                        'confidence': min(0.9, relative_power * 5)
                    })
            
            # 4. Autocorrelation-based oscillation detection
            from statsmodels.tsa.stattools import acf
            
            if len(values_clean) >= 8:
                max_lags = min(len(values_clean) - 1, len(values_clean) // 2)
                autocorr = acf(values_clean, nlags=max_lags, fft=True)
                
                # Find oscillatory patterns in autocorrelation
                acf_peaks, _ = find_peaks(autocorr[1:], height=0.2, distance=1)
                acf_peaks += 1  # Adjust for skipped lag 0
                
                # Look for regular spacing in peaks (indicates oscillation)
                if len(acf_peaks) >= 2:
                    peak_intervals = np.diff(acf_peaks)
                    if len(peak_intervals) >= 2:
                        interval_consistency = 1.0 - (np.std(peak_intervals) / np.mean(peak_intervals)) if np.mean(peak_intervals) > 0 else 0
                        
                        if interval_consistency > 0.5:  # Threshold for regular oscillation
                            mean_period = np.mean(peak_intervals)
                            oscillation_strength = np.mean([autocorr[peak] for peak in acf_peaks])
                            
                            patterns.append({
                                'type': 'autocorrelation_oscillatory',
                                'oscillation_period': float(mean_period),
                                'period_consistency': float(interval_consistency),
                                'oscillation_strength': float(oscillation_strength),
                                'n_cycles_detected': len(acf_peaks),
                                'confidence': min(0.8, interval_consistency * oscillation_strength)
                            })
            
            # 5. Damped/Growing oscillation detection
            if len(values_clean) >= 10:
                # Fit exponential envelope to detect damping/growth
                try:
                    # Calculate local extrema amplitudes over time
                    all_extrema_indices = np.concatenate([peaks, troughs]) if len(peaks) > 0 and len(troughs) > 0 else []
                    
                    if len(all_extrema_indices) >= 4:
                        all_extrema_indices.sort()
                        extrema_amplitudes = np.abs(values_clean[all_extrema_indices])
                        extrema_times = all_extrema_indices
                        
                        # Fit exponential trend to amplitude envelope
                        log_amplitudes = np.log(extrema_amplitudes + 1e-10)  # Avoid log(0)
                        slope, intercept, r_value, p_value, std_err = stats.linregress(extrema_times, log_amplitudes)
                        
                        if abs(r_value) > 0.5:  # Significant trend in amplitude
                            damping_coefficient = -slope if slope < 0 else slope
                            oscillation_type = 'damped' if slope < 0 else 'growing'
                            
                            patterns.append({
                                'type': 'amplitude_modulated_oscillatory',
                                'oscillation_type': oscillation_type,
                                'damping_coefficient': float(damping_coefficient),
                                'amplitude_trend_r_squared': float(r_value**2),
                                'trend_significance': float(1 - p_value) if p_value > 0 else 0.5,
                                'confidence': min(0.8, abs(r_value))
                            })
                            
                except Exception as e:
                    self.logger.warning(f"Amplitude modulation analysis failed: {e}")
            
            return patterns
            
        except Exception as e:
            self.logger.error(f"Error in oscillatory pattern detection: {e}")
            return []
    def _detect_statistical_outliers(self, values: List[float]) -> List[int]:
        """
        Detect statistical outliers using multiple robust statistical methods
        """
        if len(values) < 3:
            return []
        
        try:
            values_array = np.array(values, dtype=float)
            
            # Handle missing data
            valid_mask = ~np.isnan(values_array)
            if np.sum(valid_mask) < 2:
                return []
            
            # Get valid indices for mapping back to original array
            valid_indices = np.where(valid_mask)[0]
            values_clean = values_array[valid_mask]
            
            outlier_sets = []
            
            # 1. Z-score method (3-sigma rule)
            if np.std(values_clean) > 0:
                z_scores = np.abs((values_clean - np.mean(values_clean)) / np.std(values_clean))
                z_outliers = np.where(z_scores > 3.0)[0]
                if len(z_outliers) > 0:
                    outlier_sets.append(set(valid_indices[z_outliers]))
            
            # 2. Modified Z-score using MAD (more robust)
            median_val = np.median(values_clean)
            mad = np.median(np.abs(values_clean - median_val))
            if mad > 0:
                modified_z_scores = 0.6745 * np.abs(values_clean - median_val) / mad
                mad_outliers = np.where(modified_z_scores > 3.5)[0]
                if len(mad_outliers) > 0:
                    outlier_sets.append(set(valid_indices[mad_outliers]))
            
            # 3. IQR method
            q75, q25 = np.percentile(values_clean, [75, 25])
            iqr = q75 - q25
            if iqr > 0:
                lower_bound = q25 - 1.5 * iqr
                upper_bound = q75 + 1.5 * iqr
                iqr_outliers = np.where((values_clean < lower_bound) | (values_clean > upper_bound))[0]
                if len(iqr_outliers) > 0:
                    outlier_sets.append(set(valid_indices[iqr_outliers]))
            
            # 4. Isolation Forest method
            if len(values_clean) >= 5:
                try:
                    from sklearn.ensemble import IsolationForest
                    iso_forest = IsolationForest(contamination=0.1, random_state=42)
                    X = values_clean.reshape(-1, 1)
                    iso_outliers = np.where(iso_forest.fit_predict(X) == -1)[0]
                    if len(iso_outliers) > 0:
                        outlier_sets.append(set(valid_indices[iso_outliers]))
                except:
                    pass
            
            # 5. Grubbs' test (assumes normal distribution)
            if len(values_clean) >= 7:
                try:
                    from scipy.stats import t
                    n = len(values_clean)
                    mean = np.mean(values_clean)
                    std = np.std(values_clean, ddof=1)
                    
                    if std > 0:
                        G = np.abs((values_clean - mean) / std)
                        max_G_idx = np.argmax(G)
                        max_G = G[max_G_idx]
                        
                        # Critical value for Grubbs' test
                        alpha = 0.05
                        t_critical = t.ppf(1 - alpha/(2*n), n-2)
                        G_critical = ((n-1) * np.sqrt(t_critical**2)) / np.sqrt(n * (n-2 + t_critical**2))
                        
                        if max_G > G_critical:
                            outlier_sets.append(set([valid_indices[max_G_idx]]))
                except:
                    pass
            
            # Combine results using majority voting or intersection
            if len(outlier_sets) == 0:
                return []
            
            # Use majority voting - outlier detected by at least 2 methods
            if len(outlier_sets) >= 2:
                all_outliers = set.union(*outlier_sets)
                consensus_outliers = set()
                
                for outlier in all_outliers:
                    count = sum(1 for outlier_set in outlier_sets if outlier in outlier_set)
                    if count >= 2:  # At least 2 methods agree
                        consensus_outliers.add(outlier)
                
                return sorted(list(consensus_outliers))
            else:
                # Only one method, return its results
                return sorted(list(outlier_sets[0]))
            
        except Exception as e:
            self.logger.error(f"Error in statistical outlier detection: {e}")
            return []
    def _detect_zscore_anomalies(self, values: List[float]) -> List[int]:
        """
        Detect Z-score anomalies with adaptive thresholding and robust statistics
        """
        if len(values) < 3:
            return []
        
        try:
            values_array = np.array(values, dtype=float)
            
            # Handle missing data
            valid_mask = ~np.isnan(values_array)
            if np.sum(valid_mask) < 2:
                return []
            
            valid_indices = np.where(valid_mask)[0]
            values_clean = values_array[valid_mask]
            
            anomalies = set()
            
            # 1. Standard Z-score with adaptive threshold
            mean_val = np.mean(values_clean)
            std_val = np.std(values_clean)
            
            if std_val > 0:
                z_scores = np.abs((values_clean - mean_val) / std_val)
                
                # Adaptive threshold based on data distribution
                base_threshold = 3.0
                
                # Adjust threshold based on data size (smaller samples need lower threshold)
                size_factor = max(0.7, min(1.2, len(values_clean) / 50))
                adaptive_threshold = base_threshold * size_factor
                
                # Detect anomalies
                z_anomaly_indices = np.where(z_scores > adaptive_threshold)[0]
                anomalies.update(valid_indices[z_anomaly_indices])
            
            # 2. Robust Z-score using median and MAD
            median_val = np.median(values_clean)
            mad = np.median(np.abs(values_clean - median_val))
            
            if mad > 0:
                # Modified Z-score formula
                modified_z_scores = 0.6745 * np.abs(values_clean - median_val) / mad
                
                # Threshold for modified Z-score (typically higher than standard Z-score)
                robust_threshold = 3.5
                
                robust_anomaly_indices = np.where(modified_z_scores > robust_threshold)[0]
                anomalies.update(valid_indices[robust_anomaly_indices])
            
            # 3. Rolling Z-score for local anomalies
            if len(values_clean) >= 6:
                window_size = max(3, len(values_clean) // 5)
                rolling_anomalies = []
                
                for i in range(len(values_clean)):
                    # Define local window
                    start_idx = max(0, i - window_size // 2)
                    end_idx = min(len(values_clean), i + window_size // 2 + 1)
                    window_data = values_clean[start_idx:end_idx]
                    
                    if len(window_data) >= 3:
                        window_mean = np.mean(window_data)
                        window_std = np.std(window_data)
                        
                        if window_std > 0:
                            local_z = abs(values_clean[i] - window_mean) / window_std
                            if local_z > 2.5:  # Lower threshold for local anomalies
                                rolling_anomalies.append(i)
                
                anomalies.update(valid_indices[rolling_anomalies])
            
            # 4. Percentile-based extreme value detection
            p1, p99 = np.percentile(values_clean, [1, 99])
            extreme_indices = np.where((values_clean < p1) | (values_clean > p99))[0]
            
            # Only include if they're also statistical outliers
            if std_val > 0:
                for idx in extreme_indices:
                    z_score = abs(values_clean[idx] - mean_val) / std_val
                    if z_score > 2.0:  # Lower threshold for extreme percentiles
                        anomalies.add(valid_indices[idx])
            
            # 5. Hampel filter (robust outlier detection)
            if len(values_clean) >= 5:
                def hampel_filter_outliers(data, window_size=None, n_sigmas=3):
                    if window_size is None:
                        window_size = max(3, len(data) // 10)
                    
                    outlier_indices = []
                    
                    for i in range(len(data)):
                        # Define window around current point
                        start = max(0, i - window_size // 2)
                        end = min(len(data), i + window_size // 2 + 1)
                        window = data[start:end]
                        
                        # Calculate median and MAD for window
                        window_median = np.median(window)
                        window_mad = np.median(np.abs(window - window_median))
                        
                        if window_mad > 0:
                            # Modified Z-score for current point
                            modified_z = 0.6745 * abs(data[i] - window_median) / window_mad
                            if modified_z > n_sigmas:
                                outlier_indices.append(i)
                    
                    return outlier_indices
                
                hampel_outliers = hampel_filter_outliers(values_clean)
                anomalies.update(valid_indices[hampel_outliers])
            
            return sorted(list(anomalies))
            
        except Exception as e:
            self.logger.error(f"Error in Z-score anomaly detection: {e}")
            return []
    def _detect_isolation_anomalies(self, values: List[float]) -> List[int]:
        """
        Detect isolation forest anomalies with ensemble methods
        """
        if len(values) < 5:  # Need minimum samples for isolation forest
            return []
        
        try:
            values_array = np.array(values, dtype=float)
            
            # Handle missing data
            valid_mask = ~np.isnan(values_array)
            if np.sum(valid_mask) < 4:
                return []
            
            valid_indices = np.where(valid_mask)[0]
            values_clean = values_array[valid_mask]
            
            from sklearn.ensemble import IsolationForest
            from sklearn.svm import OneClassSVM
            from sklearn.neighbors import LocalOutlierFactor
            
            anomalies = set()
            
            # 1. Standard Isolation Forest
            try:
                # Adaptive contamination based on data characteristics
                contamination_rate = min(0.2, max(0.05, len(values_clean) * 0.01))
                
                iso_forest = IsolationForest(
                    contamination=contamination_rate,
                    random_state=42,
                    n_estimators=100,
                    max_samples='auto'
                )
                
                X = values_clean.reshape(-1, 1)
                anomaly_labels = iso_forest.fit_predict(X)
                anomaly_scores = iso_forest.score_samples(X)
                
                iso_anomaly_indices = np.where(anomaly_labels == -1)[0]
                anomalies.update(valid_indices[iso_anomaly_indices])
                
            except Exception as e:
                self.logger.warning(f"Standard Isolation Forest failed: {e}")
            
            # 2. Extended Isolation Forest with multiple features
            if len(values_clean) >= 10:
                try:
                    # Create additional features for better anomaly detection
                    # Rolling statistics as features
                    window_size = max(3, len(values_clean) // 5)
                    
                    features = [values_clean]  # Original values
                    
                    # Add rolling mean as feature
                    rolling_means = []
                    for i in range(len(values_clean)):
                        start_idx = max(0, i - window_size // 2)
                        end_idx = min(len(values_clean), i + window_size // 2 + 1)
                        rolling_means.append(np.mean(values_clean[start_idx:end_idx]))
                    features.append(rolling_means)
                    
                    # Add rolling std as feature
                    rolling_stds = []
                    for i in range(len(values_clean)):
                        start_idx = max(0, i - window_size // 2)
                        end_idx = min(len(values_clean), i + window_size // 2 + 1)
                        rolling_stds.append(np.std(values_clean[start_idx:end_idx]))
                    features.append(rolling_stds)
                    
                    # Add position (temporal) feature
                    positions = np.arange(len(values_clean)) / len(values_clean)
                    features.append(positions)
                    
                    X_extended = np.column_stack(features)
                    
                    iso_forest_ext = IsolationForest(
                        contamination=contamination_rate * 0.8,  # Slightly lower for multi-feature
                        random_state=123,
                        n_estimators=150
                    )
                    
                    extended_labels = iso_forest_ext.fit_predict(X_extended)
                    extended_anomalies = np.where(extended_labels == -1)[0]
                    anomalies.update(valid_indices[extended_anomalies])
                    
                except Exception as e:
                    self.logger.warning(f"Extended Isolation Forest failed: {e}")
            
            # 3. One-Class SVM for comparison
            if len(values_clean) >= 8:
                try:
                    # Normalize data for SVM
                    from sklearn.preprocessing import StandardScaler
                    scaler = StandardScaler()
                    X_normalized = scaler.fit_transform(values_clean.reshape(-1, 1))
                    
                    # Adaptive nu parameter
                    nu_param = min(0.2, max(0.05, contamination_rate))
                    
                    one_class_svm = OneClassSVM(nu=nu_param, kernel='rbf', gamma='scale')
                    svm_labels = one_class_svm.fit_predict(X_normalized)
                    
                    svm_anomalies = np.where(svm_labels == -1)[0]
                    anomalies.update(valid_indices[svm_anomalies])
                    
                except Exception as e:
                    self.logger.warning(f"One-Class SVM failed: {e}")
            
            # 4. Local Outlier Factor
            if len(values_clean) >= 6:
                try:
                    n_neighbors = min(5, len(values_clean) - 1)
                    
                    lof = LocalOutlierFactor(
                        n_neighbors=n_neighbors,
                        contamination=contamination_rate,
                        novelty=False
                    )
                    
                    X = values_clean.reshape(-1, 1)
                    lof_labels = lof.fit_predict(X)
                    
                    lof_anomalies = np.where(lof_labels == -1)[0]
                    anomalies.update(valid_indices[lof_anomalies])
                    
                except Exception as e:
                    self.logger.warning(f"LOF failed: {e}")
            
            # 5. Ensemble voting - only keep anomalies detected by multiple methods
            if len(values_clean) >= 10:
                # Count how many methods detected each point as anomaly
                anomaly_counts = {}
                
                # Re-run each method and count detections
                methods_results = []
                
                # Isolation Forest results
                try:
                    iso_forest = IsolationForest(contamination=contamination_rate, random_state=42)
                    X = values_clean.reshape(-1, 1)
                    iso_labels = iso_forest.fit_predict(X)
                    iso_anomalies_set = set(np.where(iso_labels == -1)[0])
                    methods_results.append(iso_anomalies_set)
                except:
                    pass
                
                # Statistical Z-score results
                if np.std(values_clean) > 0:
                    z_scores = np.abs((values_clean - np.mean(values_clean)) / np.std(values_clean))
                    z_anomalies_set = set(np.where(z_scores > 2.5)[0])  # Lower threshold for ensemble
                    methods_results.append(z_anomalies_set)
                
                # IQR results
                q75, q25 = np.percentile(values_clean, [75, 25])
                iqr = q75 - q25
                if iqr > 0:
                    lower_bound = q25 - 1.5 * iqr
                    upper_bound = q75 + 1.5 * iqr
                    iqr_anomalies_set = set(np.where((values_clean < lower_bound) | (values_clean > upper_bound))[0])
                    methods_results.append(iqr_anomalies_set)
                
                # Ensemble voting
                if len(methods_results) >= 2:
                    final_anomalies = set()
                    all_detected = set.union(*methods_results) if methods_results else set()
                    
                    for idx in all_detected:
                        vote_count = sum(1 for method_result in methods_results if idx in method_result)
                        if vote_count >= 2:  # At least 2 methods agree
                            final_anomalies.add(valid_indices[idx])
                    
                    return sorted(list(final_anomalies))
            
            return sorted(list(anomalies))
            
        except Exception as e:
            self.logger.error(f"Error in isolation anomaly detection: {e}")
            return []
    def _detect_change_points(self, values: List[float]) -> List[int]:
        """
        Detect change points using multiple algorithms and statistical tests
        """
        if len(values) < 6:
            return []
        
        try:
            values_array = np.array(values, dtype=float)
            
            # Handle missing data
            valid_mask = ~np.isnan(values_array)
            if np.sum(valid_mask) < 4:
                return []
            
            valid_indices = np.where(valid_mask)[0]
            values_clean = values_array[valid_mask]
            
            change_points = set()
            
            # 1. PELT (Pruned Exact Linear Time) algorithm simulation
            def detect_mean_change_points(data, penalty=None):
                if penalty is None:
                    penalty = 2 * np.log(len(data))
                
                n = len(data)
                if n < 4:
                    return []
                
                # Dynamic programming approach for change point detection
                costs = np.inf * np.ones(n + 1)
                costs[0] = 0
                changepoints = [[] for _ in range(n + 1)]
                
                for t in range(2, n + 1):
                    for s in range(0, t - 1):
                        # Calculate cost of segment from s to t
                        segment = data[s:t]
                        if len(segment) > 1:
                            segment_cost = len(segment) * np.log(np.var(segment) + 1e-10)
                            total_cost = costs[s] + segment_cost + penalty
                            
                            if total_cost < costs[t]:
                                costs[t] = total_cost
                                changepoints[t] = changepoints[s] + [s] if s > 0 else []
                
                return changepoints[n]
            
            try:
                pelt_changes = detect_mean_change_points(values_clean)
                # Convert to valid indices and filter boundary effects
                filtered_changes = [cp for cp in pelt_changes if 2 <= cp <= len(values_clean) - 3]
                change_points.update(valid_indices[filtered_changes])
            except Exception as e:
                self.logger.warning(f"PELT algorithm failed: {e}")
            
            # 2. CUSUM-based change point detection
            def cusum_change_detection(data, threshold_factor=2.0):
                mean_val = np.mean(data)
                std_val = np.std(data)
                
                if std_val == 0:
                    return []
                
                threshold = threshold_factor * std_val
                cusum_pos = np.zeros(len(data))
                cusum_neg = np.zeros(len(data))
                change_indices = []
                
                for i in range(1, len(data)):
                    cusum_pos[i] = max(0, cusum_pos[i-1] + (data[i] - mean_val) - threshold/4)
                    cusum_neg[i] = max(0, cusum_neg[i-1] - (data[i] - mean_val) - threshold/4)
                    
                    if cusum_pos[i] > threshold or cusum_neg[i] > threshold:
                        change_indices.append(i)
                        cusum_pos[i] = 0
                        cusum_neg[i] = 0
                
                return change_indices
            
            cusum_changes = cusum_change_detection(values_clean)
            change_points.update(valid_indices[cusum_changes])
            
            # 3. Variance change detection using F-test
            def variance_change_detection(data, window_size=None, alpha=0.01):
                if window_size is None:
                    window_size = max(3, len(data) // 6)
                
                changes = []
                
                for i in range(window_size, len(data) - window_size):
                    before_window = data[i-window_size:i]
                    after_window = data[i:i+window_size]
                    
                    var_before = np.var(before_window, ddof=1) if len(before_window) > 1 else 0
                    var_after = np.var(after_window, ddof=1) if len(after_window) > 1 else 0
                    
                    if var_before > 0 and var_after > 0:
                        # F-statistic for variance change
                        f_stat = max(var_after, var_before) / min(var_after, var_before)
                        
                        # Simplified critical value (should use proper F-distribution)
                        f_critical = 3.0  # Approximate for small samples
                        
                        if f_stat > f_critical:
                            changes.append(i)
                
                return changes
            
            var_changes = variance_change_detection(values_clean)
            change_points.update(valid_indices[var_changes])
            
            # 4. Binary segmentation for change point detection
            def binary_segmentation(data, min_size=3, max_changes=5):
                def find_best_change_point(segment, start_idx):
                    n = len(segment)
                    if n < 2 * min_size:
                        return None
                    
                    best_change = None
                    best_stat = 0
                    
                    for cp in range(min_size, n - min_size + 1):
                        left = segment[:cp]
                        right = segment[cp:]
                        
                        if len(left) >= 2 and len(right) >= 2:
                            # T-test for mean difference
                            try:
                                t_stat, p_val = stats.ttest_ind(left, right)
                                if not np.isnan(t_stat) and abs(t_stat) > best_stat:
                                    best_stat = abs(t_stat)
                                    if p_val < 0.05:  # Significant change
                                        best_change = start_idx + cp
                            except:
                                pass
                    
                    return best_change
                
                changes = []
                segments_to_process = [(data, 0)]
                
                while segments_to_process and len(changes) < max_changes:
                    segment, start_idx = segments_to_process.pop(0)
                    change_point = find_best_change_point(segment, start_idx)
                    
                    if change_point is not None:
                        changes.append(change_point)
                        cp_in_segment = change_point - start_idx
                        
                        left_segment = segment[:cp_in_segment]
                        right_segment = segment[cp_in_segment:]
                        
                        if len(left_segment) >= 2 * min_size:
                            segments_to_process.append((left_segment, start_idx))
                        if len(right_segment) >= 2 * min_size:
                            segments_to_process.append((right_segment, change_point))
                
                return sorted(changes)
            
            binary_changes = binary_segmentation(values_clean)
            # Filter out boundary effects
            filtered_binary = [cp for cp in binary_changes if 2 <= cp <= len(values_clean) - 3]
            change_points.update(valid_indices[filtered_binary])
            
            # 5. Sliding window t-test for mean changes
            def sliding_t_test_changes(data, window_size=None, alpha=0.01):
                if window_size is None:
                    window_size = max(3, len(data) // 8)
                
                changes = []
                
                for i in range(window_size, len(data) - window_size):
                    before = data[i-window_size:i]
                    after = data[i:i+window_size]
                    
                    if len(before) >= 2 and len(after) >= 2:
                        try:
                            t_stat, p_val = stats.ttest_ind(before, after)
                            if not np.isnan(p_val) and p_val < alpha:
                                changes.append(i)
                        except:
                            pass
                
                # Remove too-close change points
                filtered_changes = []
                for change in changes:
                    if not filtered_changes or abs(change - filtered_changes[-1]) >= window_size:
                        filtered_changes.append(change)
                
                return filtered_changes
            
            t_test_changes = sliding_t_test_changes(values_clean)
            change_points.update(valid_indices[t_test_changes])
            
            # 6. Rank-based non-parametric change detection
            if len(values_clean) >= 10:
                def rank_based_changes(data, window_size=None):
                    if window_size is None:
                        window_size = max(4, len(data) // 6)
                    
                    changes = []
                    
                    for i in range(window_size, len(data) - window_size):
                        before = data[i-window_size:i]
                        after = data[i:i+window_size]
                        
                        # Mann-Whitney U test (rank-based)
                        try:
                            from scipy.stats import mannwhitneyu
                            statistic, p_val = mannwhitneyu(before, after, alternative='two-sided')
                            if p_val < 0.05:
                                changes.append(i)
                        except:
                            pass
                    
                    return changes
                
                rank_changes = rank_based_changes(values_clean)
                change_points.update(valid_indices[rank_changes])
            
            # Merge nearby change points (within 3 positions)
            if change_points:
                sorted_changes = sorted(list(change_points))
                merged_changes = [sorted_changes[0]]
                
                for change in sorted_changes[1:]:
                    if change - merged_changes[-1] > 3:  # Minimum distance
                        merged_changes.append(change)
                
                return merged_changes
            
            return []
            
        except Exception as e:
            self.logger.error(f"Error in change point detection: {e}")
            return []
    def _detect_temporal_outliers(self, values: List[float]) -> List[int]:
        """
        Detect temporal outliers using time series specific methods
        """
        if len(values) < 4:
            return []
        
        try:
            values_array = np.array(values, dtype=float)
            
            # Handle missing data
            valid_mask = ~np.isnan(values_array)
            if np.sum(valid_mask) < 3:
                return []
            
            valid_indices = np.where(valid_mask)[0]
            values_clean = values_array[valid_mask]
            
            temporal_outliers = set()
            
            # 1. Innovation outliers (based on prediction residuals)
            def detect_innovation_outliers(data, threshold_factor=2.5):
                outliers = []
                
                # Simple moving average prediction
                window_size = max(2, min(5, len(data) // 3))
                
                for i in range(window_size, len(data)):
                    # Predict using moving average
                    window = data[i-window_size:i]
                    prediction = np.mean(window)
                    residual = abs(data[i] - prediction)
                    
                    # Adaptive threshold based on historical residuals
                    historical_residuals = []
                    for j in range(max(0, i-10), i):
                        if j >= window_size:
                            hist_window = data[j-window_size:j]
                            hist_pred = np.mean(hist_window)
                            historical_residuals.append(abs(data[j] - hist_pred))
                    
                    if historical_residuals:
                        threshold = threshold_factor * np.std(historical_residuals)
                        if residual > threshold:
                            outliers.append(i)
                
                return outliers
            
            innovation_outliers = detect_innovation_outliers(values_clean)
            temporal_outliers.update(valid_indices[innovation_outliers])
            
            # 2. Additive outliers (sudden level shifts)
            def detect_additive_outliers(data, threshold_factor=3.0):
                outliers = []
                
                # Calculate first differences
                if len(data) < 2:
                    return outliers
                
                diffs = np.diff(data)
                if len(diffs) == 0:
                    return outliers
                
                # Detect large jumps
                diff_std = np.std(diffs)
                if diff_std > 0:
                    threshold = threshold_factor * diff_std
                    large_changes = np.where(np.abs(diffs) > threshold)[0]
                    
                    # The outlier is the point after the large change
                    outliers.extend([idx + 1 for idx in large_changes if idx + 1 < len(data)])
                
                return outliers
            
            additive_outliers = detect_additive_outliers(values_clean)
            temporal_outliers.update(valid_indices[additive_outliers])
            
            # 3. Temporal clustering outliers
            if len(values_clean) >= 6:
                def detect_temporal_clustering_outliers(data, window_size=None):
                    if window_size is None:
                        window_size = max(3, len(data) // 5)
                    
                    outliers = []
                    
                    for i in range(len(data)):
                        # Define temporal neighborhood
                        start_idx = max(0, i - window_size // 2)
                        end_idx = min(len(data), i + window_size // 2 + 1)
                        neighborhood = data[start_idx:end_idx]
                        
                        if len(neighborhood) >= 3:
                            # Remove current point from neighborhood for comparison
                            neighbor_values = np.concatenate([
                                neighborhood[:i-start_idx], 
                                neighborhood[i-start_idx+1:]
                            ]) if i-start_idx < len(neighborhood) else neighborhood
                            
                            if len(neighbor_values) > 0:
                                # Check if current point is outlier within its temporal neighborhood
                                neighbor_mean = np.mean(neighbor_values)
                                neighbor_std = np.std(neighbor_values)
                                
                                if neighbor_std > 0:
                                    z_score = abs(data[i] - neighbor_mean) / neighbor_std
                                    if z_score > 2.5:
                                        outliers.append(i)
                    
                    return outliers
                
                clustering_outliers = detect_temporal_clustering_outliers(values_clean)
                temporal_outliers.update(valid_indices[clustering_outliers])
            
            # 4. Trend-based outliers
            if len(values_clean) >= 5:
                def detect_trend_outliers(data, threshold_factor=2.0):
                    outliers = []
                    
                    # Fit local linear trends and detect deviations
                    window_size = max(3, len(data) // 4)
                    
                    for i in range(len(data)):
                        # Define local window
                        start_idx = max(0, i - window_size // 2)
                        end_idx = min(len(data), i + window_size // 2 + 1)
                        
                        if end_idx - start_idx >= 3:
                            window_data = data[start_idx:end_idx]
                            window_indices = np.arange(len(window_data))
                            
                            # Fit linear trend to local window
                            try:
                                slope, intercept, r_value, p_value, std_err = stats.linregress(
                                    window_indices, window_data
                                )
                                
                                # Predict value at current position
                                local_pos = i - start_idx
                                predicted = slope * local_pos + intercept
                                residual = abs(data[i] - predicted)
                                
                                # Calculate threshold based on trend fit quality
                                trend_residuals = window_data - (slope * window_indices + intercept)
                                trend_std = np.std(trend_residuals)
                                
                                if trend_std > 0 and residual > threshold_factor * trend_std:
                                    outliers.append(i)
                                    
                            except Exception:
                                pass
                    
                    return outliers
                
                trend_outliers = detect_trend_outliers(values_clean)
                temporal_outliers.update(valid_indices[trend_outliers])
            
            # 5. Seasonal outliers (if data length suggests seasonality)
            if len(values_clean) >= 12:  # At least one potential season
                def detect_seasonal_outliers(data, season_length=12):
                    outliers = []
                    
                    # Only proceed if we have at least 2 seasons
                    if len(data) < 2 * season_length:
                        return outliers
                    
                    # Calculate seasonal pattern
                    seasonal_values = [[] for _ in range(season_length)]
                    
                    for i, value in enumerate(data):
                        season_index = i % season_length
                        seasonal_values[season_index].append(value)
                    
                    # For each position, check if it's an outlier within its season
                    for i, value in enumerate(data):
                        season_index = i % season_length
                        season_data = seasonal_values[season_index]
                        
                        if len(season_data) >= 3:  # Need at least 3 observations
                            # Remove current observation from season data
                            other_season_values = [v for j, v in enumerate(season_data) 
                                                 if j != len([x for x in seasonal_values[season_index][:len(season_data)] if x == value]) - 1]
                            
                            if len(other_season_values) >= 2:
                                season_mean = np.mean(other_season_values)
                                season_std = np.std(other_season_values)
                                
                                if season_std > 0:
                                    z_score = abs(value - season_mean) / season_std
                                    if z_score > 2.5:
                                        outliers.append(i)
                    
                    return outliers
                
                seasonal_outliers = detect_seasonal_outliers(values_clean)
                temporal_outliers.update(valid_indices[seasonal_outliers])
            
            # 6. Context-sensitive outliers using sliding statistics
            def detect_context_sensitive_outliers(data, context_size=None):
                if context_size is None:
                    context_size = max(4, min(len(data) // 3, 10))
                
                outliers = []
                
                for i in range(len(data)):
                    # Define context window (excluding current point)
                    start_context = max(0, i - context_size)
                    end_context = min(len(data), i + context_size + 1)
                    
                    context_data = np.concatenate([
                        data[start_context:i],
                        data[i+1:end_context]
                    ])
                    
                    if len(context_data) >= 3:
                        # Use robust statistics for context
                        context_median = np.median(context_data)
                        context_mad = np.median(np.abs(context_data - context_median))
                        
                        if context_mad > 0:
                            # Modified z-score
                            modified_z = 0.6745 * abs(data[i] - context_median) / context_mad
                            if modified_z > 3.0:
                                outliers.append(i)
                
                return outliers
            
            context_outliers = detect_context_sensitive_outliers(values_clean)
            temporal_outliers.update(valid_indices[context_outliers])
            
            # Remove duplicates and return sorted list
            return sorted(list(temporal_outliers))
            
        except Exception as e:
            self.logger.error(f"Error in temporal outlier detection: {e}")
            return []
    def _forecast_moving_average(self, values: List[float]) -> Dict[str, Any]:
        """
        Advanced moving average forecasting with adaptive parameters
        """
        if len(values) < 3:
            return {'forecast': [], 'error': 'Insufficient data'}
        
        try:
            values_array = np.array(values, dtype=float)
            
            # Handle missing data
            valid_mask = ~np.isnan(values_array)
            if np.sum(valid_mask) < 2:
                return {'forecast': [], 'error': 'Insufficient valid data'}
            
            values_clean = values_array[valid_mask].tolist()
            
            # Multiple moving average approaches
            forecasts = {}
            
            # 1. Simple Moving Average with adaptive window
            def adaptive_window_size(data):
                # Use autocorrelation to determine optimal window
                if len(data) < 6:
                    return min(3, len(data))
                
                from statsmodels.tsa.stattools import acf
                try:
                    autocorrs = acf(data, nlags=min(len(data)//2, 12), fft=True)
                    # Find first significant drop in autocorrelation
                    for i, ac in enumerate(autocorrs[1:], 1):
                        if ac < 0.3:
                            return min(max(i, 2), len(data)//2)
                    return min(len(data)//3, 10)
                except:
                    return min(len(data)//3, 5)
            
            window_size = adaptive_window_size(values_clean)
            
            # Simple moving average
            if len(values_clean) >= window_size:
                sma_window = values_clean[-window_size:]
                sma_forecast = np.mean(sma_window)
                forecasts['simple_moving_average'] = {
                    'value': float(sma_forecast),
                    'window_size': window_size,
                    'method': 'simple_moving_average'
                }
            
            # 2. Weighted Moving Average (more weight to recent values)
            if len(values_clean) >= window_size:
                weights = np.arange(1, window_size + 1)
                weights = weights / np.sum(weights)
                wma_window = values_clean[-window_size:]
                wma_forecast = np.dot(wma_window, weights)
                forecasts['weighted_moving_average'] = {
                    'value': float(wma_forecast),
                    'weights': weights.tolist(),
                    'method': 'weighted_moving_average'
                }
            
            # 3. Exponential Moving Average
            alpha = 2.0 / (window_size + 1)  # Smoothing factor
            ema = values_clean[0]
            for value in values_clean[1:]:
                ema = alpha * value + (1 - alpha) * ema
            
            forecasts['exponential_moving_average'] = {
                'value': float(ema),
                'alpha': alpha,
                'method': 'exponential_moving_average'
            }
            
            # 4. Double Exponential Moving Average (Holt's method)
            if len(values_clean) >= 4:
                alpha = 0.3  # Level smoothing
                beta = 0.3   # Trend smoothing
                
                # Initialize
                level = values_clean[0]
                trend = values_clean[1] - values_clean[0]
                
                for i in range(1, len(values_clean)):
                    prev_level = level
                    level = alpha * values_clean[i] + (1 - alpha) * (level + trend)
                    trend = beta * (level - prev_level) + (1 - beta) * trend
                
                dema_forecast = level + trend
                forecasts['double_exponential_moving_average'] = {
                    'value': float(dema_forecast),
                    'level': float(level),
                    'trend': float(trend),
                    'alpha': alpha,
                    'beta': beta,
                    'method': 'double_exponential_moving_average'
                }
            
            # 5. Adaptive Moving Average (adjusts to volatility)
            if len(values_clean) >= 6:
                # Calculate volatility
                returns = np.diff(values_clean)
                volatility = np.std(returns[-min(10, len(returns)):]) if len(returns) > 0 else 0
                
                # Adaptive window based on volatility
                base_window = window_size
                volatility_factor = min(2.0, max(0.5, volatility / np.std(values_clean) if np.std(values_clean) > 0 else 1.0))
                adaptive_window = int(base_window * volatility_factor)
                adaptive_window = max(2, min(adaptive_window, len(values_clean)))
                
                ama_forecast = np.mean(values_clean[-adaptive_window:])
                forecasts['adaptive_moving_average'] = {
                    'value': float(ama_forecast),
                    'adaptive_window': adaptive_window,
                    'volatility_factor': float(volatility_factor),
                    'method': 'adaptive_moving_average'
                }
            
            # 6. Triangular Moving Average
            if len(values_clean) >= window_size:
                # First pass: simple moving average
                first_pass = []
                for i in range(window_size - 1, len(values_clean)):
                    first_pass.append(np.mean(values_clean[i-window_size+1:i+1]))
                
                # Second pass: moving average of first pass
                if len(first_pass) >= window_size:
                    tma_forecast = np.mean(first_pass[-window_size:])
                    forecasts['triangular_moving_average'] = {
                        'value': float(tma_forecast),
                        'method': 'triangular_moving_average'
                    }
            
            # Calculate forecast confidence based on recent prediction accuracy
            confidence_scores = {}
            if len(values_clean) >= window_size + 3:
                for method_name, forecast_data in forecasts.items():
                    # Backtest the method on recent data
                    errors = []
                    test_length = min(5, len(values_clean) - window_size)
                    
                    for i in range(test_length):
                        test_point = len(values_clean) - i - 1
                        test_data = values_clean[:test_point]
                        actual = values_clean[test_point]
                        
                        if method_name == 'simple_moving_average' and len(test_data) >= window_size:
                            pred = np.mean(test_data[-window_size:])
                        elif method_name == 'exponential_moving_average' and len(test_data) >= 2:
                            ema_test = test_data[0]
                            for val in test_data[1:]:
                                ema_test = alpha * val + (1 - alpha) * ema_test
                            pred = ema_test
                        else:
                            continue
                        
                        errors.append(abs(actual - pred))
                    
                    if errors:
                        mae = np.mean(errors)
                        data_std = np.std(values_clean)
                        confidence = max(0.1, 1.0 - (mae / data_std)) if data_std > 0 else 0.5
                        confidence_scores[method_name] = float(confidence)
            
            # Select best forecast based on method performance or use ensemble
            if confidence_scores:
                best_method = max(confidence_scores.items(), key=lambda x: x[1])[0]
                best_forecast = forecasts[best_method]
                best_forecast['confidence'] = confidence_scores[best_method]
            else:
                best_forecast = forecasts.get('simple_moving_average', list(forecasts.values())[0])
                best_forecast['confidence'] = 0.7
            
            return {
                'forecast': [best_forecast['value']],
                'best_method': best_forecast,
                'all_methods': forecasts,
                'confidence_scores': confidence_scores,
                'forecast_horizon': 1,
                'method_used': 'adaptive_moving_average_ensemble'
            }
            
        except Exception as e:
            self.logger.error(f"Error in moving average forecasting: {e}")
            return {'forecast': values[-3:] if len(values) >= 3 else values, 'error': str(e)}

    def _forecast_exponential_smoothing(self, values: List[float]) -> Dict[str, Any]:
        """
        Exponential smoothing forecasting with state space models
        """
        if len(values) < 3:
            return {'forecast': [], 'error': 'Insufficient data'}
        
        try:
            values_array = np.array(values, dtype=float)
            
            # Handle missing data
            valid_mask = ~np.isnan(values_array)
            if np.sum(valid_mask) < 2:
                return {'forecast': [], 'error': 'Insufficient valid data'}
            
            values_clean = values_array[valid_mask].tolist()
            
            forecasts = {}
            
            # 1. Simple Exponential Smoothing (SES)
            def simple_exponential_smoothing(data, alpha=None):
                if alpha is None:
                    # Optimize alpha using grid search
                    best_alpha = 0.3
                    best_mse = float('inf')
                    
                    for test_alpha in np.arange(0.1, 1.0, 0.1):
                        predictions = []
                        level = data[0]
                        
                        for i in range(1, len(data)):
                            predictions.append(level)
                            level = test_alpha * data[i] + (1 - test_alpha) * level
                        
                        if len(predictions) > 0:
                            mse = np.mean([(data[i+1] - predictions[i])**2 for i in range(len(predictions))])
                            if mse < best_mse:
                                best_mse = mse
                                best_alpha = test_alpha
                    
                    alpha = best_alpha
                
                # Fit the model
                level = data[0]
                for value in data[1:]:
                    level = alpha * value + (1 - alpha) * level
                
                return level, alpha
            
            ses_forecast, optimal_alpha = simple_exponential_smoothing(values_clean)
            forecasts['simple_exponential_smoothing'] = {
                'value': float(ses_forecast),
                'alpha': float(optimal_alpha),
                'method': 'simple_exponential_smoothing'
            }
            
            # 2. Holt's Linear Exponential Smoothing (Double Exponential)
            if len(values_clean) >= 4:
                def holts_linear_smoothing(data, alpha=None, beta=None):
                    if alpha is None or beta is None:
                        # Grid search for optimal parameters
                        best_params = (0.3, 0.3)
                        best_mse = float('inf')
                        
                        for test_alpha in [0.1, 0.3, 0.5, 0.7, 0.9]:
                            for test_beta in [0.1, 0.3, 0.5, 0.7, 0.9]:
                                try:
                                    # Initialize
                                    level = data[0]
                                    trend = data[1] - data[0] if len(data) > 1 else 0
                                    predictions = []
                                    
                                    for i in range(1, len(data)):
                                        predictions.append(level + trend)
                                        prev_level = level
                                        level = test_alpha * data[i] + (1 - test_alpha) * (level + trend)
                                        trend = test_beta * (level - prev_level) + (1 - test_beta) * trend
                                    
                                    if len(predictions) > 0:
                                        mse = np.mean([(data[i+1] - predictions[i])**2 for i in range(len(predictions))])
                                        if mse < best_mse:
                                            best_mse = mse
                                            best_params = (test_alpha, test_beta)
                                except:
                                    continue
                        
                        alpha, beta = best_params
                    
                    # Fit final model
                    level = data[0]
                    trend = data[1] - data[0] if len(data) > 1 else 0
                    
                    for i in range(1, len(data)):
                        prev_level = level
                        level = alpha * data[i] + (1 - alpha) * (level + trend)
                        trend = beta * (level - prev_level) + (1 - beta) * trend
                    
                    forecast = level + trend
                    return forecast, level, trend, alpha, beta
                
                holt_forecast, level, trend, alpha, beta = holts_linear_smoothing(values_clean)
                forecasts['holts_linear_smoothing'] = {
                    'value': float(holt_forecast),
                    'level': float(level),
                    'trend': float(trend),
                    'alpha': float(alpha),
                    'beta': float(beta),
                    'method': 'holts_linear_smoothing'
                }
            
            # 3. Holt-Winters Seasonal Exponential Smoothing
            if len(values_clean) >= 12:  # Need at least one season
                def holt_winters_seasonal(data, season_length=12, seasonal_type='additive'):
                    try:
                        from statsmodels.tsa.holtwinters import ExponentialSmoothing as StatsExponentialSmoothing
                        
                        # Fit Holt-Winters model
                        model = StatsExponentialSmoothing(
                            data, 
                            trend='add', 
                            seasonal=seasonal_type if len(data) >= 2 * season_length else None,
                            seasonal_periods=season_length if len(data) >= 2 * season_length else None
                        )
                        
                        fitted_model = model.fit(optimized=True)
                        forecast = fitted_model.forecast(steps=1)[0]
                        
                        return {
                            'value': float(forecast),
                            'alpha': float(fitted_model.params['smoothing_level']),
                            'beta': float(fitted_model.params.get('smoothing_trend', 0)),
                            'gamma': float(fitted_model.params.get('smoothing_seasonal', 0)),
                            'seasonal_type': seasonal_type,
                            'method': 'holt_winters_seasonal',
                            'aic': float(fitted_model.aic),
                            'bic': float(fitted_model.bic)
                        }
                    except Exception as e:
                        self.logger.warning(f"Holt-Winters failed: {e}")
                        return None
                
                # Try additive seasonality
                hw_additive = holt_winters_seasonal(values_clean, seasonal_type='additive')
                if hw_additive:
                    forecasts['holt_winters_additive'] = hw_additive
                
                # Try multiplicative seasonality if values are positive
                if all(v > 0 for v in values_clean):
                    hw_multiplicative = holt_winters_seasonal(values_clean, seasonal_type='multiplicative')
                    if hw_multiplicative:
                        forecasts['holt_winters_multiplicative'] = hw_multiplicative
            
            # 4. Damped Trend Exponential Smoothing
            if len(values_clean) >= 5:
                def damped_trend_smoothing(data, phi=0.8):
                    # Optimize parameters
                    best_params = (0.3, 0.3, phi)
                    best_mse = float('inf')
                    
                    for alpha in [0.1, 0.3, 0.5, 0.7]:
                        for beta in [0.1, 0.3, 0.5, 0.7]:
                            try:
                                level = data[0]
                                trend = data[1] - data[0] if len(data) > 1 else 0
                                predictions = []
                                
                                for i in range(1, len(data)):
                                    predictions.append(level + phi * trend)
                                    prev_level = level
                                    level = alpha * data[i] + (1 - alpha) * (level + phi * trend)
                                    trend = beta * (level - prev_level) + (1 - beta) * phi * trend
                                
                                if len(predictions) > 0:
                                    mse = np.mean([(data[i+1] - predictions[i])**2 for i in range(len(predictions))])
                                    if mse < best_mse:
                                        best_mse = mse
                                        best_params = (alpha, beta, phi)
                            except:
                                continue
                    
                    alpha, beta, phi = best_params
                    
                    # Fit final model
                    level = data[0]
                    trend = data[1] - data[0] if len(data) > 1 else 0
                    
                    for i in range(1, len(data)):
                        prev_level = level
                        level = alpha * data[i] + (1 - alpha) * (level + phi * trend)
                        trend = beta * (level - prev_level) + (1 - beta) * phi * trend
                    
                    forecast = level + phi * trend
                    return forecast, alpha, beta, phi
                
                damped_forecast, alpha_d, beta_d, phi_d = damped_trend_smoothing(values_clean)
                forecasts['damped_trend_smoothing'] = {
                    'value': float(damped_forecast),
                    'alpha': float(alpha_d),
                    'beta': float(beta_d),
                    'phi': float(phi_d),
                    'method': 'damped_trend_smoothing'
                }
            
            # 5. State Space Model approach
            if len(values_clean) >= 6:
                def state_space_exponential_smoothing(data):
                    # Simple state space representation
                    # State: [level, trend]
                    # Observation: level + trend
                    
                    from scipy.optimize import minimize
                    
                    def likelihood(params):
                        alpha, beta, sigma = params
                        if not (0 < alpha < 1 and 0 < beta < 1 and sigma > 0):
                            return 1e10
                        
                        level = data[0]
                        trend = 0
                        log_likelihood = 0
                        
                        for i in range(1, len(data)):
                            # Prediction
                            prediction = level + trend
                            error = data[i] - prediction
                            log_likelihood -= 0.5 * np.log(2 * np.pi * sigma**2) - (error**2) / (2 * sigma**2)
                            
                            # Update state
                            prev_level = level
                            level = alpha * data[i] + (1 - alpha) * (level + trend)
                            trend = beta * (level - prev_level) + (1 - beta) * trend
                        
                        return -log_likelihood
                    
                    try:
                        result = minimize(
                            likelihood, 
                            [0.3, 0.3, np.std(data)], 
                            bounds=[(0.01, 0.99), (0.01, 0.99), (0.01, None)],
                            method='L-BFGS-B'
                        )
                        
                        if result.success:
                            alpha_opt, beta_opt, sigma_opt = result.x
                            
                            # Final forecast
                            level = data[0]
                            trend = 0
                            for i in range(1, len(data)):
                                prev_level = level
                                level = alpha_opt * data[i] + (1 - alpha_opt) * (level + trend)
                                trend = beta_opt * (level - prev_level) + (1 - beta_opt) * trend
                            
                            forecast = level + trend
                            return {
                                'value': float(forecast),
                                'alpha': float(alpha_opt),
                                'beta': float(beta_opt),
                                'sigma': float(sigma_opt),
                                'log_likelihood': float(-result.fun),
                                'method': 'state_space_exponential_smoothing'
                            }
                    except:
                        pass
                    
                    return None
                
                ss_result = state_space_exponential_smoothing(values_clean)
                if ss_result:
                    forecasts['state_space_exponential_smoothing'] = ss_result
            
            # Select best model based on information criteria or cross-validation
            best_forecast = None
            if 'holt_winters_additive' in forecasts and 'holt_winters_multiplicative' in forecasts:
                # Choose based on AIC
                if forecasts['holt_winters_additive']['aic'] < forecasts['holt_winters_multiplicative']['aic']:
                    best_forecast = forecasts['holt_winters_additive']
                else:
                    best_forecast = forecasts['holt_winters_multiplicative']
            elif 'holt_winters_additive' in forecasts:
                best_forecast = forecasts['holt_winters_additive']
            elif 'holt_winters_multiplicative' in forecasts:
                best_forecast = forecasts['holt_winters_multiplicative']
            elif 'state_space_exponential_smoothing' in forecasts:
                best_forecast = forecasts['state_space_exponential_smoothing']
            elif 'damped_trend_smoothing' in forecasts:
                best_forecast = forecasts['damped_trend_smoothing']
            elif 'holts_linear_smoothing' in forecasts:
                best_forecast = forecasts['holts_linear_smoothing']
            else:
                best_forecast = forecasts['simple_exponential_smoothing']
            
            best_forecast['confidence'] = 0.8
            
            return {
                'forecast': [best_forecast['value']],
                'best_method': best_forecast,
                'all_methods': forecasts,
                'forecast_horizon': 1,
                'method_used': 'exponential_smoothing_ensemble'
            }
            
        except Exception as e:
            self.logger.error(f"Error in exponential smoothing forecasting: {e}")
            return {'forecast': values_clean[-3:] if len(values_clean) >= 3 else values_clean, 'error': str(e)}

    def _forecast_linear_trend(self, values: List[float]) -> Dict[str, Any]:
        """
        Linear trend forecasting with robust regression methods
        """
        if len(values) < 3:
            return {'forecast': [], 'error': 'Insufficient data'}
        
        try:
            values_array = np.array(values, dtype=float)
            
            # Handle missing data
            valid_mask = ~np.isnan(values_array)
            if np.sum(valid_mask) < 2:
                return {'forecast': [], 'error': 'Insufficient valid data'}
            
            values_clean = values_array[valid_mask].tolist()
            time_indices = np.arange(len(values_clean))
            
            forecasts = {}
            
            # 1. Ordinary Least Squares (OLS) Linear Regression
            from scipy import stats
            from sklearn.linear_model import LinearRegression, TheilSenRegressor, HuberRegressor, RANSACRegressor
            from sklearn.preprocessing import PolynomialFeatures
            from sklearn.metrics import r2_score, mean_absolute_error
            
            slope, intercept, r_value, p_value, std_err = stats.linregress(time_indices, values_clean)
            next_time = len(values_clean)
            ols_forecast = slope * next_time + intercept
            
            forecasts['ols_linear'] = {
                'value': float(ols_forecast),
                'slope': float(slope),
                'intercept': float(intercept),
                'r_squared': float(r_value**2),
                'p_value': float(p_value),
                'std_error': float(std_err),
                'method': 'ordinary_least_squares'
            }
            
            # 2. Theil-Sen Robust Regression
            try:
                theil_sen = TheilSenRegressor(random_state=42)
                X = time_indices.reshape(-1, 1)
                theil_sen.fit(X, values_clean)
                
                theil_forecast = theil_sen.predict([[next_time]])[0]
                
                # Calculate R-squared manually
                predictions = theil_sen.predict(X)
                theil_r2 = r2_score(values_clean, predictions)
                
                forecasts['theil_sen'] = {
                    'value': float(theil_forecast),
                    'slope': float(theil_sen.coef_[0]),
                    'intercept': float(theil_sen.intercept_),
                    'r_squared': float(theil_r2),
                    'method': 'theil_sen_robust',
                    'robust': True
                }
            except Exception as e:
                self.logger.warning(f"Theil-Sen regression failed: {e}")
            
            # 3. Huber Robust Regression
            try:
                huber = HuberRegressor(epsilon=1.35, alpha=0.0001)
                X = time_indices.reshape(-1, 1)
                huber.fit(X, values_clean)
                
                huber_forecast = huber.predict([[next_time]])[0]
                predictions = huber.predict(X)
                huber_r2 = r2_score(values_clean, predictions)
                
                forecasts['huber'] = {
                    'value': float(huber_forecast),
                    'slope': float(huber.coef_[0]),
                    'intercept': float(huber.intercept_),
                    'r_squared': float(huber_r2),
                    'method': 'huber_robust',
                    'robust': True
                }
            except Exception as e:
                self.logger.warning(f"Huber regression failed: {e}")
            
            # 4. RANSAC Robust Regression
            if len(values_clean) >= 6:
                try:
                    ransac = RANSACRegressor(random_state=42, min_samples=max(2, len(values_clean)//3))
                    X = time_indices.reshape(-1, 1)
                    ransac.fit(X, values_clean)
                    
                    ransac_forecast = ransac.predict([[next_time]])[0]
                    predictions = ransac.predict(X)
                    ransac_r2 = r2_score(values_clean, predictions)
                    
                    # RANSAC provides inlier information
                    inlier_mask = ransac.inlier_mask_
                    n_inliers = np.sum(inlier_mask)
                    
                    forecasts['ransac'] = {
                        'value': float(ransac_forecast),
                        'slope': float(ransac.estimator_.coef_[0]),
                        'intercept': float(ransac.estimator_.intercept_),
                        'r_squared': float(ransac_r2),
                        'n_inliers': int(n_inliers),
                        'inlier_fraction': float(n_inliers / len(values_clean)),
                        'method': 'ransac_robust',
                        'robust': True
                    }
                except Exception as e:
                    self.logger.warning(f"RANSAC regression failed: {e}")
            
            # 5. Polynomial Trend (if data suggests non-linearity)
            if len(values_clean) >= 6:
                for degree in [2, 3]:
                    try:
                        poly_features = PolynomialFeatures(degree=degree)
                        X_poly = poly_features.fit_transform(time_indices.reshape(-1, 1))
                        
                        poly_reg = LinearRegression()
                        poly_reg.fit(X_poly, values_clean)
                        
                        # Forecast
                        next_time_poly = poly_features.transform([[next_time]])
                        poly_forecast = poly_reg.predict(next_time_poly)[0]
                        
                        # Calculate R-squared
                        predictions = poly_reg.predict(X_poly)
                        poly_r2 = r2_score(values_clean, predictions)
                        
                        # Only include if significantly better than linear
                        if poly_r2 > (r_value**2 + 0.05):
                            forecasts[f'polynomial_degree_{degree}'] = {
                                'value': float(poly_forecast),
                                'coefficients': poly_reg.coef_.tolist(),
                                'intercept': float(poly_reg.intercept_),
                                'r_squared': float(poly_r2),
                                'degree': degree,
                                'improvement_over_linear': float(poly_r2 - r_value**2),
                                'method': f'polynomial_trend_degree_{degree}'
                            }
                    except Exception as e:
                        self.logger.warning(f"Polynomial degree {degree} failed: {e}")
            
            # 6. Segmented Linear Regression (if change points exist)
            if len(values_clean) >= 10:
                def segmented_regression(data, time_idx):
                    from scipy.optimize import minimize_scalar
                    
                    def segment_fit_error(break_point):
                        bp = int(break_point)
                        if bp <= 2 or bp >= len(data) - 2:
                            return float('inf')
                        
                        # Fit two segments
                        t1, y1 = time_idx[:bp], data[:bp]
                        t2, y2 = time_idx[bp:], data[bp:]
                        
                        if len(t1) < 2 or len(t2) < 2:
                            return float('inf')
                        
                        try:
                            slope1, int1, _, _, _ = stats.linregress(t1, y1)
                            slope2, int2, _, _, _ = stats.linregress(t2, y2)
                            
                            # Calculate total error
                            pred1 = slope1 * t1 + int1
                            pred2 = slope2 * t2 + int2
                            
                            error = np.sum((y1 - pred1)**2) + np.sum((y2 - pred2)**2)
                            return error
                        except:
                            return float('inf')
                    
                    # Find optimal break point
                    result = minimize_scalar(segment_fit_error, bounds=(3, len(data)-3), method='bounded')
                    
                    if result.success:
                        bp = int(result.x)
                        t1, y1 = time_idx[:bp], data[:bp]
                        t2, y2 = time_idx[bp:], data[bp:]
                        
                        slope1, int1, r1, _, _ = stats.linregress(t1, y1)
                        slope2, int2, r2, _, _ = stats.linregress(t2, y2)
                        
                        # Forecast using second segment
                        next_forecast = slope2 * len(data) + int2
                        
                        return {
                            'break_point': bp,
                            'slope1': slope1, 'intercept1': int1, 'r_squared1': r1**2,
                            'slope2': slope2, 'intercept2': int2, 'r_squared2': r2**2,
                            'forecast': next_forecast
                        }
                    
                    return None
                
                try:
                    seg_result = segmented_regression(values_clean, time_indices)
                    if seg_result:
                        forecasts['segmented_linear'] = {
                            'value': float(seg_result['forecast']),
                            'break_point': int(seg_result['break_point']),
                            'segment1': {
                                'slope': float(seg_result['slope1']),
                                'intercept': float(seg_result['intercept1']),
                                'r_squared': float(seg_result['r_squared1'])
                            },
                            'segment2': {
                                'slope': float(seg_result['slope2']),
                                'intercept': float(seg_result['intercept2']),
                                'r_squared': float(seg_result['r_squared2'])
                            },
                            'method': 'segmented_linear_regression'
                        }
                except Exception as e:
                    self.logger.warning(f"Segmented regression failed: {e}")
            
            # 7. Weighted Linear Regression (more weight to recent points)
            try:
                # Exponential weights (more recent = higher weight)
                weights = np.exp(np.linspace(-1, 0, len(values_clean)))
                weights = weights / np.sum(weights) * len(weights)  # Normalize but keep sum > 1
                
                # Weighted least squares manually
                W = np.diag(weights)
                X = np.column_stack([np.ones(len(time_indices)), time_indices])
                
                # Normal equation: (X^T W X)^{-1} X^T W y
                XTW = X.T @ W
                XTWX = XTW @ X
                XTWy = XTW @ values_clean
                
                coeffs = np.linalg.solve(XTWX, XTWy)
                weighted_intercept, weighted_slope = coeffs
                
                weighted_forecast = weighted_slope * next_time + weighted_intercept
                
                # Calculate weighted R-squared
                predictions = weighted_slope * time_indices + weighted_intercept
                ss_res = np.sum(weights * (values_clean - predictions)**2)
                ss_tot = np.sum(weights * (values_clean - np.average(values_clean, weights=weights))**2)
                weighted_r2 = 1 - (ss_res / ss_tot) if ss_tot > 0 else 0
                
                forecasts['weighted_linear'] = {
                    'value': float(weighted_forecast),
                    'slope': float(weighted_slope),
                    'intercept': float(weighted_intercept),
                    'r_squared': float(weighted_r2),
                    'method': 'weighted_linear_regression',
                    'weights': 'exponential_recent_bias'
                }
            except Exception as e:
                self.logger.warning(f"Weighted regression failed: {e}")
            
            # Select best model based on robustness and fit quality
            best_forecast = None
            
            # Prioritize robust methods if they exist and have good fit
            robust_methods = ['ransac', 'theil_sen', 'huber']
            for method in robust_methods:
                if method in forecasts and forecasts[method].get('r_squared', 0) > 0.5:
                    best_forecast = forecasts[method]
                    break
            
            # If no good robust method, use best fitting method
            if best_forecast is None:
                best_method_name = max(forecasts.keys(), 
                                     key=lambda k: forecasts[k].get('r_squared', 0))
                best_forecast = forecasts[best_method_name]
            
            # Add confidence based on fit quality
            r_squared = best_forecast.get('r_squared', 0)
            best_forecast['confidence'] = min(0.95, max(0.3, r_squared))
            
            # Calculate prediction interval
            if 'std_error' in best_forecast:
                std_err = best_forecast['std_error']
                prediction_interval = 1.96 * std_err  # 95% confidence interval
                best_forecast['prediction_interval'] = {
                    'lower': float(best_forecast['value'] - prediction_interval),
                    'upper': float(best_forecast['value'] + prediction_interval)
                }
            
            return {
                'forecast': [best_forecast['value']],
                'best_method': best_forecast,
                'all_methods': forecasts,
                'forecast_horizon': 1,
                'method_used': 'robust_linear_trend_ensemble'
            }
            
        except Exception as e:
            self.logger.error(f"Error in linear trend forecasting: {e}")
            return {'forecast': values[-3:] if len(values) >= 3 else values, 'error': str(e)}

    def _forecast_seasonal_naive(self, values: List[float]) -> Dict[str, Any]:
        """
        Seasonal naive forecasting with advanced seasonal decomposition
        """
        if len(values) < 6:
            return {'forecast': [], 'error': 'Insufficient data'}
        
        try:
            values_array = np.array(values, dtype=float)
            
            # Handle missing data
            valid_mask = ~np.isnan(values_array)
            if np.sum(valid_mask) < 4:
                return {'forecast': [], 'error': 'Insufficient valid data'}
            
            values_clean = values_array[valid_mask].tolist()
            
            forecasts = {}
            
            # 1. Simple Seasonal Naive (assume annual seasonality)
            seasonal_periods = [12, 6, 4, 3]  # Test different seasonal lengths
            
            for period in seasonal_periods:
                if len(values_clean) >= 2 * period:
                    # Get the value from the same season last year/cycle
                    seasonal_index = (len(values_clean) - 1) % period
                    
                    # Collect all values from this seasonal position
                    seasonal_values = []
                    for i in range(seasonal_index, len(values_clean), period):
                        seasonal_values.append(values_clean[i])
                    
                    if len(seasonal_values) >= 2:
                        # Simple seasonal naive: use last value from same season
                        naive_forecast = seasonal_values[-1]
                        
                        # Calculate seasonal stability
                        seasonal_mean = np.mean(seasonal_values)
                        seasonal_std = np.std(seasonal_values)
                        stability = 1.0 - (seasonal_std / abs(seasonal_mean)) if abs(seasonal_mean) > 0 else 0
                        
                        forecasts[f'seasonal_naive_period_{period}'] = {
                            'value': float(naive_forecast),
                            'period': period,
                            'seasonal_values': seasonal_values,
                            'seasonal_stability': float(max(0, stability)),
                            'n_observations': len(seasonal_values),
                            'method': f'seasonal_naive_period_{period}'
                        }
            
            # 2. Seasonal Naive with Trend Adjustment
            for period in seasonal_periods:
                if len(values_clean) >= 3 * period:
                    seasonal_index = (len(values_clean) - 1) % period
                    
                    # Get seasonal values
                    seasonal_values = []
                    seasonal_times = []
                    for i in range(seasonal_index, len(values_clean), period):
                        seasonal_values.append(values_clean[i])
                        seasonal_times.append(i)
                    
                    if len(seasonal_values) >= 3:
                        # Fit trend to seasonal values
                        from scipy import stats
                        slope, intercept, r_value, p_value, std_err = stats.linregress(
                            seasonal_times, seasonal_values
                        )
                        
                        # Project trend forward
                        next_seasonal_time = len(values_clean)
                        trend_adjusted_forecast = slope * next_seasonal_time + intercept
                        
                        forecasts[f'seasonal_trend_adjusted_period_{period}'] = {
                            'value': float(trend_adjusted_forecast),
                            'period': period,
                            'seasonal_trend_slope': float(slope),
                            'seasonal_trend_r_squared': float(r_value**2),
                            'trend_significance': float(1 - p_value) if p_value > 0 else 0.5,
                            'method': f'seasonal_trend_adjusted_period_{period}'
                        }
            
            # 3. Advanced Seasonal Decomposition
            if len(values_clean) >= 24:  # Need sufficient data
                try:
                    from statsmodels.tsa.seasonal import seasonal_decompose, STL
                    
                    # Try multiple decomposition methods
                    decomposition_methods = ['additive', 'multiplicative']
                    
                    for method in decomposition_methods:
                        try:
                            # Classical seasonal decomposition
                            decomp = seasonal_decompose(
                                values_clean, 
                                model=method, 
                                period=12,
                                extrapolate_trend='freq'
                            )
                            
                            # Extract components
                            trend = decomp.trend[-1] if not np.isnan(decomp.trend[-1]) else np.nanmean(decomp.trend)
                            seasonal = decomp.seasonal[-1]
                            
                            if method == 'additive':
                                forecast = trend + seasonal
                            else:  # multiplicative
                                forecast = trend * seasonal
                            
                            # Calculate component strengths
                            trend_strength = 1 - np.var(decomp.resid[~np.isnan(decomp.resid)]) / np.var(values_clean)
                            seasonal_strength = np.var(decomp.seasonal) / np.var(values_clean)
                            
                            forecasts[f'seasonal_decomp_{method}'] = {
                                'value': float(forecast),
                                'trend_component': float(trend),
                                'seasonal_component': float(seasonal),
                                'decomposition_method': method,
                                'trend_strength': float(max(0, trend_strength)),
                                'seasonal_strength': float(seasonal_strength),
                                'method': f'seasonal_decomposition_{method}'
                            }
                        except Exception as e:
                            self.logger.warning(f"Seasonal decomposition {method} failed: {e}")
                    
                    # STL decomposition (more robust)
                    try:
                        stl = STL(values_clean, seasonal=13, robust=True)
                        stl_result = stl.fit()
                        
                        trend_stl = stl_result.trend[-1]
                        seasonal_stl = stl_result.seasonal[-1]
                        stl_forecast = trend_stl + seasonal_stl
                        
                        # Calculate STL component strengths
                        stl_trend_strength = 1 - np.var(stl_result.resid) / np.var(values_clean)
                        stl_seasonal_strength = np.var(stl_result.seasonal) / np.var(values_clean)
                        
                        forecasts['stl_seasonal'] = {
                            'value': float(stl_forecast),
                            'trend_component': float(trend_stl),
                            'seasonal_component': float(seasonal_stl),
                            'decomposition_method': 'STL',
                            'trend_strength': float(max(0, stl_trend_strength)),
                            'seasonal_strength': float(stl_seasonal_strength),
                            'robust': True,
                            'method': 'stl_seasonal_decomposition'
                        }
                    except Exception as e:
                        self.logger.warning(f"STL decomposition failed: {e}")
                        
                except Exception as e:
                    self.logger.warning(f"Seasonal decomposition failed: {e}")
            
            # 4. Multiple Seasonality Detection and Forecasting
            if len(values_clean) >= 36:
                from scipy.fft import fft, fftfreq
                
                # Use FFT to detect multiple seasonal patterns
                fft_values = fft(values_clean)
                frequencies = fftfreq(len(values_clean))
                power_spectrum = np.abs(fft_values)**2
                
                # Find dominant frequencies (skip DC component)
                dominant_indices = np.argsort(power_spectrum[1:len(power_spectrum)//2])[-3:] + 1
                
                detected_periods = []
                for idx in dominant_indices:
                    freq = frequencies[idx]
                    if freq > 0:
                        period = 1.0 / freq
                        if 2 <= period <= len(values_clean) / 3:
                            detected_periods.append(int(round(period)))
                
                # Multi-seasonal naive forecast
                if detected_periods:
                    multi_seasonal_forecasts = []
                    
                    for period in detected_periods:
                        seasonal_idx = (len(values_clean) - 1) % period
                        seasonal_vals = [values_clean[i] for i in range(seasonal_idx, len(values_clean), period)]
                        
                        if len(seasonal_vals) >= 2:
                            # Weight recent seasonal observations more
                            weights = np.exp(np.linspace(-1, 0, len(seasonal_vals)))
                            weights = weights / np.sum(weights)
                            
                            weighted_forecast = np.dot(seasonal_vals, weights)
                            multi_seasonal_forecasts.append(weighted_forecast)
                    
                    if multi_seasonal_forecasts:
                        # Average multiple seasonal forecasts
                        multi_seasonal_avg = np.mean(multi_seasonal_forecasts)
                        
                        forecasts['multi_seasonal'] = {
                            'value': float(multi_seasonal_avg),
                            'detected_periods': detected_periods,
                            'individual_forecasts': [float(f) for f in multi_seasonal_forecasts],
                            'method': 'multi_seasonal_fft_based'
                        }
            
            # 5. Seasonal Ensemble with Weights
            if len(forecasts) >= 2:
                # Weight forecasts based on their seasonal strength and stability
                weighted_forecast = 0
                total_weight = 0
                
                for method_name, forecast_data in forecasts.items():
                    weight = 1.0
                    
                    # Increase weight for higher seasonal strength
                    if 'seasonal_strength' in forecast_data:
                        weight *= (1 + forecast_data['seasonal_strength'])
                    
                    # Increase weight for higher seasonal stability
                    if 'seasonal_stability' in forecast_data:
                        weight *= (1 + forecast_data['seasonal_stability'])
                    
                    # Increase weight for more observations
                    if 'n_observations' in forecast_data:
                        weight *= (1 + np.log(forecast_data['n_observations']) / 10)
                    
                    # Increase weight for robust methods
                    if forecast_data.get('robust', False):
                        weight *= 1.2
                    
                    weighted_forecast += weight * forecast_data['value']
                    total_weight += weight
                
                if total_weight > 0:
                    ensemble_forecast = weighted_forecast / total_weight
                    
                    forecasts['seasonal_ensemble'] = {
                        'value': float(ensemble_forecast),
                        'method': 'weighted_seasonal_ensemble',
                        'n_methods': len(forecasts) - 1  # Excluding self
                    }
            
            # Select best forecast
            best_forecast = None
            
            # Prioritize ensemble if available
            if 'seasonal_ensemble' in forecasts:
                best_forecast = forecasts['seasonal_ensemble']
            # Then STL (most robust)
            elif 'stl_seasonal' in forecasts:
                best_forecast = forecasts['stl_seasonal']
            # Then multi-seasonal
            elif 'multi_seasonal' in forecasts:
                best_forecast = forecasts['multi_seasonal']
            # Then best decomposition
            elif any('seasonal_decomp' in k for k in forecasts.keys()):
                decomp_methods = [k for k in forecasts.keys() if 'seasonal_decomp' in k]
                best_decomp = max(decomp_methods, key=lambda k: forecasts[k].get('seasonal_strength', 0))
                best_forecast = forecasts[best_decomp]
            # Then best trend-adjusted
            elif any('seasonal_trend_adjusted' in k for k in forecasts.keys()):
                trend_methods = [k for k in forecasts.keys() if 'seasonal_trend_adjusted' in k]
                best_trend = max(trend_methods, key=lambda k: forecasts[k].get('seasonal_trend_r_squared', 0))
                best_forecast = forecasts[best_trend]
            # Finally, best naive
            else:
                naive_methods = [k for k in forecasts.keys() if 'seasonal_naive_period' in k]
                if naive_methods:
                    best_naive = max(naive_methods, key=lambda k: forecasts[k].get('seasonal_stability', 0))
                    best_forecast = forecasts[best_naive]
            
            if best_forecast is None and forecasts:
                best_forecast = list(forecasts.values())[0]
            
            if best_forecast is None:
                return {'forecast': [values_clean[-1]], 'error': 'No suitable seasonal method found'}
            
            # Set confidence based on seasonal strength
            seasonal_strength = best_forecast.get('seasonal_strength', 0.5)
            best_forecast['confidence'] = min(0.9, max(0.4, seasonal_strength))
            
            return {
                'forecast': [best_forecast['value']],
                'best_method': best_forecast,
                'all_methods': forecasts,
                'forecast_horizon': 1,
                'method_used': 'seasonal_naive_ensemble'
            }
            
        except Exception as e:
            self.logger.error(f"Error in seasonal naive forecasting: {e}")
            return {'forecast': values[-3:] if len(values) >= 3 else values, 'error': str(e)}

    def _calculate_spectral_rolloff(self, frequencies, power_spectrum):
        """
        Calculate spectral rolloff with advanced signal processing
        """
        try:
            frequencies = np.array(frequencies, dtype=float)
            power_spectrum = np.array(power_spectrum, dtype=float)
            
            # Handle edge cases
            if len(frequencies) == 0 or len(power_spectrum) == 0:
                return 0.0
            
            if len(frequencies) != len(power_spectrum):
                return 0.0
            
            # Remove negative frequencies and corresponding power values
            positive_mask = frequencies >= 0
            frequencies = frequencies[positive_mask]
            power_spectrum = power_spectrum[positive_mask]
            
            if len(frequencies) == 0:
                return 0.0
            
            # Ensure power spectrum is non-negative
            power_spectrum = np.abs(power_spectrum)
            
            # Calculate cumulative energy
            total_energy = np.sum(power_spectrum)
            
            if total_energy == 0:
                return 0.0
            
            # Calculate multiple rolloff points
            rolloff_percentiles = [0.85, 0.90, 0.95, 0.99]  # Different rolloff thresholds
            rolloff_results = {}
            
            for percentile in rolloff_percentiles:
                target_energy = percentile * total_energy
                cumulative_energy = np.cumsum(power_spectrum)
                
                # Find the frequency where cumulative energy exceeds target
                rolloff_indices = np.where(cumulative_energy >= target_energy)[0]
                
                if len(rolloff_indices) > 0:
                    rolloff_idx = rolloff_indices[0]
                    
                    # Interpolate for more precise rolloff frequency
                    if rolloff_idx > 0 and rolloff_idx < len(frequencies):
                        # Linear interpolation between adjacent points
                        energy_before = cumulative_energy[rolloff_idx - 1]
                        energy_after = cumulative_energy[rolloff_idx]
                        freq_before = frequencies[rolloff_idx - 1]
                        freq_after = frequencies[rolloff_idx]
                        
                        if energy_after != energy_before:
                            # Interpolation factor
                            alpha = (target_energy - energy_before) / (energy_after - energy_before)
                            rolloff_freq = freq_before + alpha * (freq_after - freq_before)
                        else:
                            rolloff_freq = frequencies[rolloff_idx]
                    else:
                        rolloff_freq = frequencies[rolloff_idx] if rolloff_idx < len(frequencies) else frequencies[-1]
                    
                    rolloff_results[f'rolloff_{int(percentile*100)}'] = float(rolloff_freq)
                else:
                    # If target energy is not reached, use maximum frequency
                    rolloff_results[f'rolloff_{int(percentile*100)}'] = float(frequencies[-1])
            
            # Calculate additional spectral characteristics
            
            # Spectral centroid (weighted mean frequency)
            spectral_centroid = np.sum(frequencies * power_spectrum) / total_energy
            
            # Spectral spread (spectral standard deviation)
            spectral_spread = np.sqrt(np.sum(((frequencies - spectral_centroid) ** 2) * power_spectrum) / total_energy)
            
            # Spectral skewness (asymmetry of the spectrum)
            normalized_freqs = (frequencies - spectral_centroid) / spectral_spread if spectral_spread > 0 else frequencies
            spectral_skewness = np.sum((normalized_freqs ** 3) * power_spectrum) / total_energy
            
            # Spectral kurtosis (peakedness of the spectrum)
            spectral_kurtosis = np.sum((normalized_freqs ** 4) * power_spectrum) / total_energy - 3
            
            # Spectral entropy (measure of spectral randomness)
            # Normalize power spectrum to probability distribution
            power_prob = power_spectrum / total_energy
            # Avoid log(0) by adding small epsilon
            power_prob_safe = power_prob + 1e-12
            spectral_entropy = -np.sum(power_prob_safe * np.log2(power_prob_safe))
            
            # Spectral flatness (Wiener entropy)
            geometric_mean = np.exp(np.mean(np.log(power_spectrum + 1e-12)))
            arithmetic_mean = np.mean(power_spectrum)
            spectral_flatness = geometric_mean / arithmetic_mean if arithmetic_mean > 0 else 0
            
            # High-frequency content ratio
            median_freq = np.median(frequencies)
            high_freq_mask = frequencies > median_freq
            high_freq_energy = np.sum(power_spectrum[high_freq_mask])
            high_freq_ratio = high_freq_energy / total_energy
            
            # Spectral decrease (measure of how much the spectrum decreases)
            if len(power_spectrum) > 1:
                spectral_decrease = np.sum((power_spectrum[1:] - power_spectrum[0]) / np.arange(1, len(power_spectrum))) / np.sum(power_spectrum[1:])
            else:
                spectral_decrease = 0
            
            # Edge frequency (frequency at which spectrum drops significantly)
            if len(power_spectrum) > 5:
                # Find the frequency where power drops below 10% of maximum
                max_power = np.max(power_spectrum)
                threshold = 0.1 * max_power
                
                # Find last frequency above threshold
                above_threshold = power_spectrum > threshold
                if np.any(above_threshold):
                    edge_indices = np.where(above_threshold)[0]
                    edge_frequency = frequencies[edge_indices[-1]]
                else:
                    edge_frequency = frequencies[0]
            else:
                edge_frequency = frequencies[-1] if len(frequencies) > 0 else 0
            
            # Compile comprehensive spectral rolloff analysis
            spectral_analysis = {
                'rolloff_frequencies': rolloff_results,
                'spectral_centroid': float(spectral_centroid),
                'spectral_spread': float(spectral_spread),
                'spectral_skewness': float(spectral_skewness),
                'spectral_kurtosis': float(spectral_kurtosis),
                'spectral_entropy': float(spectral_entropy),
                'spectral_flatness': float(spectral_flatness),
                'high_frequency_ratio': float(high_freq_ratio),
                'spectral_decrease': float(spectral_decrease),
                'edge_frequency': float(edge_frequency),
                'total_energy': float(total_energy),
                'frequency_range': {
                    'min': float(frequencies[0]),
                    'max': float(frequencies[-1]),
                    'bandwidth': float(frequencies[-1] - frequencies[0])
                }
            }
            
            # Return the 85% rolloff frequency as the main result (most commonly used)
            # but store the full analysis in the logger for advanced usage
            self.spectral_analysis_cache = spectral_analysis
            
            return rolloff_results.get('rolloff_85', 0.0)
            
        except Exception as e:
            self.logger.error(f"Error in spectral rolloff calculation: {e}")
            return 0.0

    def _calculate_spectral_bandwidth(self, frequencies, power_spectrum):
        """
        Calculate spectral bandwidth with comprehensive frequency analysis
        """
        try:
            frequencies = np.array(frequencies, dtype=float)
            power_spectrum = np.array(power_spectrum, dtype=float)
            
            # Handle edge cases
            if len(frequencies) == 0 or len(power_spectrum) == 0:
                return 0.0
            
            if len(frequencies) != len(power_spectrum):
                return 0.0
            
            # Remove negative frequencies and corresponding power values
            positive_mask = frequencies >= 0
            frequencies = frequencies[positive_mask]
            power_spectrum = power_spectrum[positive_mask]
            
            if len(frequencies) == 0:
                return 0.0
            
            # Ensure power spectrum is non-negative
            power_spectrum = np.abs(power_spectrum)
            total_energy = np.sum(power_spectrum)
            
            if total_energy == 0:
                return 0.0
            
            # Multiple bandwidth calculation methods
            bandwidth_metrics = {}
            
            # 1. RMS (Root Mean Square) Bandwidth
            spectral_centroid = np.sum(frequencies * power_spectrum) / total_energy
            rms_bandwidth = np.sqrt(np.sum(((frequencies - spectral_centroid) ** 2) * power_spectrum) / total_energy)
            bandwidth_metrics['rms_bandwidth'] = float(rms_bandwidth)
            
            # 2. 3dB Bandwidth (Half-power bandwidth)
            max_power = np.max(power_spectrum)
            half_power = max_power / 2
            
            # Find frequencies where power is above half maximum
            above_half_power = power_spectrum >= half_power
            if np.any(above_half_power):
                half_power_indices = np.where(above_half_power)[0]
                bandwidth_3db = frequencies[half_power_indices[-1]] - frequencies[half_power_indices[0]]
            else:
                bandwidth_3db = 0.0
            bandwidth_metrics['bandwidth_3db'] = float(bandwidth_3db)
            
            # 3. 6dB Bandwidth (Quarter-power bandwidth)
            quarter_power = max_power / 4
            above_quarter_power = power_spectrum >= quarter_power
            if np.any(above_quarter_power):
                quarter_power_indices = np.where(above_quarter_power)[0]
                bandwidth_6db = frequencies[quarter_power_indices[-1]] - frequencies[quarter_power_indices[0]]
            else:
                bandwidth_6db = 0.0
            bandwidth_metrics['bandwidth_6db'] = float(bandwidth_6db)
            
            # 4. Percentile-based Bandwidth (90% energy bandwidth)
            cumulative_energy = np.cumsum(power_spectrum)
            energy_5_percent = 0.05 * total_energy
            energy_95_percent = 0.95 * total_energy
            
            # Find frequencies containing 90% of energy (5% to 95%)
            freq_5_percent = frequencies[0]
            freq_95_percent = frequencies[-1]
            
            for i, cum_energy in enumerate(cumulative_energy):
                if cum_energy >= energy_5_percent and freq_5_percent == frequencies[0]:
                    freq_5_percent = frequencies[i]
                if cum_energy >= energy_95_percent:
                    freq_95_percent = frequencies[i]
                    break
            
            bandwidth_90_percent = freq_95_percent - freq_5_percent
            bandwidth_metrics['bandwidth_90_percent'] = float(bandwidth_90_percent)
            
            # 5. Equivalent Rectangular Bandwidth (ERB)
            # ERB approximates the bandwidth of auditory filters
            if spectral_centroid > 0:
                erb = 24.7 * (4.37 * spectral_centroid / 1000 + 1)  # ERB formula for Hz
                bandwidth_metrics['equivalent_rectangular_bandwidth'] = float(erb)
            
            # 6. Effective Bandwidth (based on spectral concentration)
            # Measure how concentrated the spectrum is
            spectral_spread = np.sqrt(np.sum(((frequencies - spectral_centroid) ** 2) * power_spectrum) / total_energy)
            effective_bandwidth = 2 * spectral_spread  # 2-sigma bandwidth
            bandwidth_metrics['effective_bandwidth'] = float(effective_bandwidth)
            
            # 7. Fractional Bandwidth
            if spectral_centroid > 0:
                fractional_bandwidth = rms_bandwidth / spectral_centroid
                bandwidth_metrics['fractional_bandwidth'] = float(fractional_bandwidth)
            
            # 8. Peak-to-Peak Bandwidth
            from scipy.signal import find_peaks
            
            # Find significant peaks in the spectrum
            peaks, properties = find_peaks(power_spectrum, height=max_power * 0.1, distance=max(1, len(power_spectrum)//20))
            
            if len(peaks) >= 2:
                peak_to_peak_bandwidth = frequencies[peaks[-1]] - frequencies[peaks[0]]
                bandwidth_metrics['peak_to_peak_bandwidth'] = float(peak_to_peak_bandwidth)
                bandwidth_metrics['n_significant_peaks'] = len(peaks)
            else:
                bandwidth_metrics['peak_to_peak_bandwidth'] = float(frequencies[-1] - frequencies[0])
                bandwidth_metrics['n_significant_peaks'] = len(peaks)
            
            # 9. Coherence Bandwidth (frequency correlation bandwidth)
            # Estimate based on spectral autocorrelation
            if len(power_spectrum) > 10:
                # Calculate spectral autocorrelation
                spectrum_normalized = (power_spectrum - np.mean(power_spectrum)) / np.std(power_spectrum)
                autocorr = np.correlate(spectrum_normalized, spectrum_normalized, mode='full')
                autocorr = autocorr[autocorr.size // 2:]
                
                # Find first zero crossing or significant drop
                coherence_bandwidth_idx = 1
                for i in range(1, min(len(autocorr), len(frequencies) // 2)):
                    if autocorr[i] < 0.1 * autocorr[0]:  # 10% of maximum correlation
                        coherence_bandwidth_idx = i
                        break
                
                if coherence_bandwidth_idx < len(frequencies):
                    coherence_bandwidth = frequencies[coherence_bandwidth_idx] - frequencies[0]
                    bandwidth_metrics['coherence_bandwidth'] = float(coherence_bandwidth)
            
            # 10. Quality Factor (Q-factor)
            if bandwidth_3db > 0:
                q_factor = spectral_centroid / bandwidth_3db
                bandwidth_metrics['q_factor'] = float(q_factor)
            
            # 11. Spectral Roll-off Bandwidth
            # Bandwidth from DC to 85% energy rolloff
            cumulative_energy_norm = cumulative_energy / total_energy
            rolloff_85_indices = np.where(cumulative_energy_norm >= 0.85)[0]
            
            if len(rolloff_85_indices) > 0:
                rolloff_bandwidth = frequencies[rolloff_85_indices[0]] - frequencies[0]
                bandwidth_metrics['rolloff_bandwidth'] = float(rolloff_bandwidth)
            
            # 12. Instantaneous Bandwidth (for time-varying signals)
            # Approximate using spectral spread weighted by time
            if len(power_spectrum) > 5:
                # Create synthetic time vector
                time_vector = np.arange(len(power_spectrum))
                
                # Time-weighted spectral spread
                time_weighted_spread = np.sqrt(
                    np.sum(((frequencies - spectral_centroid) ** 2) * power_spectrum * (time_vector + 1)) / 
                    np.sum(power_spectrum * (time_vector + 1))
                )
                bandwidth_metrics['instantaneous_bandwidth'] = float(time_weighted_spread)
            
            # Advanced spectral characteristics
            additional_metrics = {
                'spectral_centroid': float(spectral_centroid),
                'spectral_spread': float(spectral_spread),
                'spectral_concentration': float(max_power / np.mean(power_spectrum)) if np.mean(power_spectrum) > 0 else 0,
                'bandwidth_ratio_3db_to_total': float(bandwidth_3db / (frequencies[-1] - frequencies[0])) if len(frequencies) > 1 else 0,
                'dominant_frequency': float(frequencies[np.argmax(power_spectrum)]),
                'frequency_range': {
                    'min': float(frequencies[0]),
                    'max': float(frequencies[-1]),
                    'span': float(frequencies[-1] - frequencies[0])
                }
            }
            
            # Combine all metrics
            comprehensive_analysis = {
                **bandwidth_metrics,
                **additional_metrics
            }
            
            # Store comprehensive analysis for advanced usage
            self.spectral_bandwidth_analysis_cache = comprehensive_analysis
            
            # Return RMS bandwidth as the primary measure (most commonly used)
            return bandwidth_metrics.get('rms_bandwidth', 0.0)
            
        except Exception as e:
            self.logger.error(f"Error in spectral bandwidth calculation: {e}")
            return 0.0

    def _calculate_skewness(self, values):
        """Calculate advanced skewness with robust estimators and confidence intervals"""
        try:
            values = np.array(values, dtype=np.float64)
            if len(values) < 3:
                return 0.0
                
            # Remove NaN values
            values = values[~np.isnan(values)]
            if len(values) < 3:
                return 0.0
            
            # Calculate multiple skewness measures
            results = {
                'pearson_skewness': skew(values, bias=False),  # Sample skewness
                'robust_skewness': self._robust_skewness(values),
                'adjusted_skewness': skew(values, bias=True),
                'bowley_skewness': self._bowley_skewness(values),
                'galton_skewness': self._galton_skewness(values)
            }
            
            # Calculate confidence interval for skewness
            n = len(values)
            se_skew = np.sqrt(6 * n * (n - 1) / ((n - 2) * (n + 1) * (n + 3)))
            results['skewness_ci_lower'] = results['pearson_skewness'] - 1.96 * se_skew
            results['skewness_ci_upper'] = results['pearson_skewness'] + 1.96 * se_skew
            
            # Test for significant skewness
            z_score = results['pearson_skewness'] / se_skew
            results['skewness_pvalue'] = 2 * (1 - stats.norm.cdf(abs(z_score)))
            results['is_significantly_skewed'] = results['skewness_pvalue'] < 0.05
            
            return results['pearson_skewness']  # Return primary measure
            
        except Exception as e:
            self.logger.error(f"Error calculating skewness: {e}")
            return 0.0
    
    def _robust_skewness(self, values):
        """Calculate robust skewness using Groeneveld and Meeden method"""
        q1, q2, q3 = np.percentile(values, [25, 50, 75])
        if q3 - q1 == 0:
            return 0.0
        return ((q3 + q1 - 2*q2) / (q3 - q1))
    
    def _bowley_skewness(self, values):
        """Calculate Bowley skewness (quartile skewness)"""
        q1, q2, q3 = np.percentile(values, [25, 50, 75])
        if q3 + q1 - 2*q2 == 0:
            return 0.0
        return (q3 + q1 - 2*q2) / (q3 - q1)
    
    def _galton_skewness(self, values):
        """Calculate Galton skewness (based on mean, median, std)"""
        mean_val = np.mean(values)
        median_val = np.median(values)
        std_val = np.std(values)
        if std_val == 0:
            return 0.0
        return (mean_val - median_val) / std_val
    def _calculate_kurtosis(self, values):
        """Calculate advanced kurtosis with multiple estimators and statistical tests"""
        try:
            values = np.array(values, dtype=np.float64)
            if len(values) < 4:
                return 0.0
                
            # Remove NaN values
            values = values[~np.isnan(values)]
            if len(values) < 4:
                return 0.0
            
            # Calculate multiple kurtosis measures
            results = {
                'excess_kurtosis': kurtosis(values, bias=False),  # Excess kurtosis (normal = 0)
                'raw_kurtosis': kurtosis(values, bias=False) + 3,  # Raw kurtosis (normal = 3)
                'robust_kurtosis': self._robust_kurtosis(values),
                'adjusted_kurtosis': kurtosis(values, bias=True),
                'crow_siddiqui_kurtosis': self._crow_siddiqui_kurtosis(values)
            }
            
            # Calculate confidence interval for kurtosis
            n = len(values)
            se_kurt = np.sqrt(24 * n * (n - 1)**2 / ((n - 3) * (n - 2) * (n + 3) * (n + 5)))
            results['kurtosis_ci_lower'] = results['excess_kurtosis'] - 1.96 * se_kurt
            results['kurtosis_ci_upper'] = results['excess_kurtosis'] + 1.96 * se_kurt
            
            # Test for significant kurtosis
            z_score = results['excess_kurtosis'] / se_kurt
            results['kurtosis_pvalue'] = 2 * (1 - stats.norm.cdf(abs(z_score)))
            results['is_significantly_kurtotic'] = results['kurtosis_pvalue'] < 0.05
            
            # Classify distribution shape
            if results['excess_kurtosis'] > 0:
                results['distribution_shape'] = 'leptokurtic'  # Heavy tails
            elif results['excess_kurtosis'] < 0:
                results['distribution_shape'] = 'platykurtic'  # Light tails
            else:
                results['distribution_shape'] = 'mesokurtic'   # Normal-like
            
            # Perform Jarque-Bera test for normality
            try:
                jb_stat, jb_pvalue = jarque_bera(values)
                results['jarque_bera_stat'] = jb_stat
                results['jarque_bera_pvalue'] = jb_pvalue
                results['is_normal_distribution'] = jb_pvalue > 0.05
            except:
                results['is_normal_distribution'] = False
                
            return results['excess_kurtosis']  # Return primary measure
            
        except Exception as e:
            self.logger.error(f"Error calculating kurtosis: {e}")
            return 0.0
    
    def _robust_kurtosis(self, values):
        """Calculate robust kurtosis using octiles"""
        try:
            octiles = np.percentile(values, [12.5, 25, 50, 75, 87.5])
            q1, q3 = octiles[1], octiles[3]
            o1, o7 = octiles[0], octiles[4]
            if q3 - q1 == 0:
                return 0.0
            return (o7 - o1) / (q3 - q1)
        except:
            return 0.0
    
    def _crow_siddiqui_kurtosis(self, values):
        """Calculate Crow-Siddiqui kurtosis (L-kurtosis)"""
        try:
            sorted_vals = np.sort(values)
            n = len(sorted_vals)
            if n < 4:
                return 0.0
            
            # Calculate L-moments
            l1 = np.mean(sorted_vals)
            l2 = np.mean([sorted_vals[i] * (2*i - n + 1) for i in range(n)]) / n
            if l2 == 0:
                return 0.0
                
            l4_num = sum([
                sorted_vals[i] * (i*(i-1)*(i-2) - 3*i*(i-1)*(n-i-1) + 3*i*(n-i-1)*(n-i-2) - (n-i-1)*(n-i-2)*(n-i-3))
                for i in range(n)
            ])
            l4 = l4_num / (n * (n-1) * (n-2) * (n-3))
            
            return l4 / l2  # L-kurtosis
        except:
            return 0.0
    def _count_zero_crossings(self, values):
        """Advanced zero-crossing detection with filtering and trend analysis"""
        try:
            values = np.array(values, dtype=np.float64)
            if len(values) < 3:
                return 0
                
            # Remove NaN values
            values = values[~np.isnan(values)]
            if len(values) < 3:
                return 0
            
            # Center the signal around zero (remove DC component)
            values_centered = values - np.mean(values)
            
            # Apply different preprocessing methods
            results = {
                'raw_crossings': self._count_raw_zero_crossings(values_centered),
                'filtered_crossings': self._count_filtered_zero_crossings(values_centered),
                'detrended_crossings': self._count_detrended_zero_crossings(values),
                'threshold_crossings': self._count_threshold_crossings(values_centered),
                'slope_weighted_crossings': self._count_slope_weighted_crossings(values_centered)
            }
            
            # Calculate zero-crossing rate (ZCR)
            results['zero_crossing_rate'] = results['raw_crossings'] / (len(values) - 1)
            
            # Analyze crossing patterns
            crossings = self._find_zero_crossing_positions(values_centered)
            if len(crossings) > 1:
                intervals = np.diff(crossings)
                results['mean_crossing_interval'] = np.mean(intervals)
                results['std_crossing_interval'] = np.std(intervals)
                results['crossing_regularity'] = 1.0 / (1.0 + results['std_crossing_interval'] / results['mean_crossing_interval'])
            else:
                results['mean_crossing_interval'] = 0
                results['std_crossing_interval'] = 0
                results['crossing_regularity'] = 0
            
            # Detect crossing clusters
            results['crossing_clusters'] = self._detect_crossing_clusters(crossings)
            
            return results['filtered_crossings']  # Return primary measure
            
        except Exception as e:
            self.logger.error(f"Error counting zero crossings: {e}")
            return 0
    
    def _count_raw_zero_crossings(self, values):
        """Count raw zero crossings without preprocessing"""
        return np.sum(np.diff(np.sign(values)) != 0)
    
    def _count_filtered_zero_crossings(self, values):
        """Count zero crossings after noise filtering"""
        try:
            # Apply Gaussian smoothing to reduce noise
            if len(values) > 10:
                sigma = max(1, len(values) // 50)  # Adaptive smoothing
                filtered = gaussian_filter1d(values, sigma=sigma)
            else:
                filtered = values
            return np.sum(np.diff(np.sign(filtered)) != 0)
        except:
            return self._count_raw_zero_crossings(values)
    
    def _count_detrended_zero_crossings(self, values):
        """Count zero crossings after detrending"""
        try:
            # Remove linear trend
            detrended = detrend(values, type='linear')
            detrended = detrended - np.mean(detrended)  # Center around zero
            return np.sum(np.diff(np.sign(detrended)) != 0)
        except:
            return self._count_raw_zero_crossings(values - np.mean(values))
    
    def _count_threshold_crossings(self, values, threshold_factor=0.1):
        """Count crossings with hysteresis threshold to avoid noise"""
        threshold = threshold_factor * np.std(values)
        crossings = 0
        above_threshold = values[0] > threshold
        
        for value in values[1:]:
            if above_threshold and value < -threshold:
                crossings += 1
                above_threshold = False
            elif not above_threshold and value > threshold:
                crossings += 1
                above_threshold = True
                
        return crossings
    
    def _count_slope_weighted_crossings(self, values):
        """Count zero crossings weighted by slope magnitude"""
        try:
            # Calculate derivatives (slopes)
            slopes = np.gradient(values)
            sign_changes = np.diff(np.sign(values)) != 0
            
            if len(slopes) > len(sign_changes):
                slopes = slopes[:-1]
            elif len(slopes) < len(sign_changes):
                sign_changes = sign_changes[:len(slopes)]
            
            # Weight crossings by slope magnitude
            weighted_crossings = np.sum(np.abs(slopes[sign_changes]))
            return int(np.round(weighted_crossings))
        except:
            return self._count_raw_zero_crossings(values)
    
    def _find_zero_crossing_positions(self, values):
        """Find positions of zero crossings"""
        sign_changes = np.where(np.diff(np.sign(values)) != 0)[0]
        return sign_changes
    
    def _detect_crossing_clusters(self, crossings):
        """Detect clusters of zero crossings"""
        if len(crossings) < 2:
            return 0
        
        intervals = np.diff(crossings)
        median_interval = np.median(intervals)
        cluster_threshold = median_interval / 3  # Threshold for cluster detection
        
        clusters = 0
        in_cluster = False
        
        for interval in intervals:
            if interval < cluster_threshold:
                if not in_cluster:
                    clusters += 1
                    in_cluster = True
            else:
                in_cluster = False
                
        return clusters
    def _count_peaks(self, values):
        """Advanced peak detection using multiple algorithms and filtering"""
        try:
            values = np.array(values, dtype=np.float64)
            if len(values) < 3:
                return 0
                
            # Remove NaN values
            values = values[~np.isnan(values)]
            if len(values) < 3:
                return 0
            
            # Multiple peak detection methods
            results = {
                'scipy_peaks': self._count_scipy_peaks(values),
                'prominence_peaks': self._count_prominence_peaks(values),
                'adaptive_peaks': self._count_adaptive_peaks(values),
                'wavelet_peaks': self._count_wavelet_peaks(values),
                'local_maxima': self._count_local_maxima(values),
                'significant_peaks': self._count_significant_peaks(values)
            }
            
            # Analyze peak characteristics
            peaks, properties = find_peaks(values, height=np.std(values) * 0.5)
            if len(peaks) > 0:
                # Peak prominence analysis
                prominences = peak_prominences(values, peaks)[0]
                widths = peak_widths(values, peaks)[0]
                
                results['mean_peak_prominence'] = np.mean(prominences)
                results['std_peak_prominence'] = np.std(prominences)
                results['mean_peak_width'] = np.mean(widths)
                results['std_peak_width'] = np.std(widths)
                results['peak_density'] = len(peaks) / len(values)
                
                # Peak regularity analysis
                if len(peaks) > 1:
                    intervals = np.diff(peaks)
                    results['mean_peak_interval'] = np.mean(intervals)
                    results['std_peak_interval'] = np.std(intervals)
                    results['peak_regularity'] = 1.0 / (1.0 + results['std_peak_interval'] / max(results['mean_peak_interval'], 1e-6))
                else:
                    results['peak_regularity'] = 0
                    
                # Peak amplitude distribution
                peak_heights = values[peaks]
                results['mean_peak_height'] = np.mean(peak_heights)
                results['std_peak_height'] = np.std(peak_heights)
                
            else:
                # No peaks found
                for key in ['mean_peak_prominence', 'std_peak_prominence', 'mean_peak_width', 'std_peak_width',
                           'peak_density', 'mean_peak_interval', 'std_peak_interval', 'peak_regularity',
                           'mean_peak_height', 'std_peak_height']:
                    results[key] = 0.0
            
            return results['prominence_peaks']  # Return primary measure
            
        except Exception as e:
            self.logger.error(f"Error counting peaks: {e}")
            return 0
    
    def _count_scipy_peaks(self, values):
        """Count peaks using scipy.signal.find_peaks with basic parameters"""
        try:
            peaks, _ = find_peaks(values, distance=max(1, len(values)//50))
            return len(peaks)
        except:
            return 0
    
    def _count_prominence_peaks(self, values):
        """Count peaks using prominence-based filtering"""
        try:
            # Use adaptive prominence threshold based on signal statistics
            prominence_threshold = np.std(values) * 0.5
            peaks, _ = find_peaks(values, prominence=prominence_threshold)
            return len(peaks)
        except:
            return 0
    
    def _count_adaptive_peaks(self, values):
        """Count peaks using adaptive thresholding"""
        try:
            # Calculate adaptive parameters
            signal_std = np.std(values)
            signal_mean = np.mean(values)
            
            # Adaptive height threshold
            height_threshold = signal_mean + signal_std * 0.5
            
            # Adaptive distance (prevent close peaks)
            min_distance = max(1, len(values) // 20)
            
            peaks, _ = find_peaks(values, 
                                height=height_threshold,
                                distance=min_distance,
                                prominence=signal_std * 0.3)
            return len(peaks)
        except:
            return 0
    
    def _count_wavelet_peaks(self, values):
        """Count peaks using continuous wavelet transform"""
        try:
            # Use continuous wavelet transform for peak detection
            widths = np.arange(1, min(len(values)//4, 31))
            cwt_matrix = np.abs(np.array([np.convolve(values, np.exp(-0.5 * ((np.arange(len(values)) - len(values)//2) / w)**2), mode='same') for w in widths]))
            
            # Find peaks in the CWT coefficients
            peaks = []
            for i, row in enumerate(cwt_matrix):
                row_peaks, _ = find_peaks(row, height=np.max(row) * 0.3)
                peaks.extend(row_peaks)
            
            # Remove duplicates and return count
            unique_peaks = len(set(peaks))
            return unique_peaks
        except:
            return self._count_prominence_peaks(values)
    
    def _count_local_maxima(self, values):
        """Count local maxima (simple peak detection)"""
        try:
            local_maxima = []
            for i in range(1, len(values) - 1):
                if values[i] > values[i-1] and values[i] > values[i+1]:
                    local_maxima.append(i)
            return len(local_maxima)
        except:
            return 0
    
    def _count_significant_peaks(self, values):
        """Count statistically significant peaks"""
        try:
            # Calculate z-scores for peak significance
            mean_val = np.mean(values)
            std_val = np.std(values)
            z_scores = np.abs((values - mean_val) / std_val)
            
            # Find local maxima that are statistically significant
            significant_peaks = 0
            for i in range(1, len(values) - 1):
                if (values[i] > values[i-1] and values[i] > values[i+1] and 
                    z_scores[i] > 2.0):  # 95% confidence
                    significant_peaks += 1
            
            return significant_peaks
        except:
            return 0
    def _calculate_temporal_entropy(self, values):
        """Calculate comprehensive temporal entropy measures"""
        try:
            values = np.array(values, dtype=np.float64)
            if len(values) < 3:
                return 0.0
                
            # Remove NaN values
            values = values[~np.isnan(values)]
            if len(values) < 3:
                return 0.0
            
            # Normalize values to [0, 1] range for entropy calculations
            values_norm = (values - np.min(values)) / (np.max(values) - np.min(values) + 1e-10)
            
            # Multiple entropy measures
            results = {
                'shannon_entropy': self._calculate_shannon_entropy(values_norm),
                'spectral_entropy': self._calculate_spectral_entropy(values),
                'svd_entropy': self._calculate_svd_entropy(values),
                'approximate_entropy': self._calculate_approximate_entropy(values),
                'sample_entropy': self._calculate_sample_entropy(values),
                'permutation_entropy': self._calculate_permutation_entropy(values),
                'differential_entropy': self._calculate_differential_entropy(values),
                'renyi_entropy': self._calculate_renyi_entropy(values_norm)
            }
            
            # Temporal complexity measures
            results['lempel_ziv_complexity'] = self._calculate_lempel_ziv_complexity(values)
            results['fractal_dimension'] = self._calculate_fractal_dimension(values)
            
            # Multi-scale entropy
            results['multiscale_entropy'] = self._calculate_multiscale_entropy(values)
            
            # Return primary entropy measure
            return results['sample_entropy'] if results['sample_entropy'] > 0 else results['shannon_entropy']
            
        except Exception as e:
            self.logger.error(f"Error calculating temporal entropy: {e}")
            return 0.0
    
    def _calculate_shannon_entropy(self, values):
        """Calculate Shannon entropy from histogram"""
        try:
            # Create histogram
            hist, _ = np.histogram(values, bins=min(50, len(values)//5), density=True)
            hist = hist[hist > 0]  # Remove zero bins
            
            # Calculate Shannon entropy
            return -np.sum(hist * np.log2(hist + 1e-10))
        except:
            return 0.0
    
    def _calculate_spectral_entropy(self, values):
        """Calculate spectral entropy from power spectrum"""
        try:
            if not ENTROPY_AVAILABLE:
                return self._calculate_spectral_entropy_fallback(values)
            return float(spectral_entropy(values, sf=1.0, nperseg=min(256, len(values)//4)))
        except:
            return self._calculate_spectral_entropy_fallback(values)
    
    def _calculate_spectral_entropy_fallback(self, values):
        """Fallback spectral entropy calculation"""
        try:
            # Calculate power spectral density
            freqs, psd = periodogram(values)
            psd_norm = psd / np.sum(psd)
            psd_norm = psd_norm[psd_norm > 0]  # Remove zero values
            
            # Calculate entropy of normalized PSD
            return -np.sum(psd_norm * np.log2(psd_norm + 1e-10))
        except:
            return 0.0
    
    def _calculate_svd_entropy(self, values):
        """Calculate SVD entropy"""
        try:
            if not ENTROPY_AVAILABLE:
                return self._calculate_svd_entropy_fallback(values)
            return float(svd_entropy(values))
        except:
            return self._calculate_svd_entropy_fallback(values)
    
    def _calculate_svd_entropy_fallback(self, values):
        """Fallback SVD entropy calculation"""
        try:
            # Create Hankel matrix for SVD
            n = len(values)
            m = min(n//2, 50)  # Embedding dimension
            
            # Create trajectory matrix
            X = np.array([values[i:i+m] for i in range(n-m+1)])
            
            # SVD decomposition
            _, s, _ = np.linalg.svd(X)
            
            # Normalize singular values
            s_norm = s / np.sum(s)
            s_norm = s_norm[s_norm > 0]
            
            # Calculate entropy
            return -np.sum(s_norm * np.log2(s_norm + 1e-10))
        except:
            return 0.0
    
    def _calculate_approximate_entropy(self, values, m=2, r=None):
        """Calculate approximate entropy"""
        try:
            if not ENTROPY_AVAILABLE:
                return self._calculate_approximate_entropy_fallback(values, m, r)
            
            if r is None:
                r = 0.2 * np.std(values)
            
            return float(approximate_entropy(values, m, r))
        except:
            return self._calculate_approximate_entropy_fallback(values, m, r)
    
    def _calculate_approximate_entropy_fallback(self, values, m=2, r=None):
        """Fallback approximate entropy calculation"""
        try:
            N = len(values)
            if N < m + 1:
                return 0.0
            
            if r is None:
                r = 0.2 * np.std(values)
            
            def _maxdist(xi, xj, m):
                return max([abs(ua - va) for ua, va in zip(xi, xj)])
            
            def _phi(m):
                patterns = np.array([values[i:i+m] for i in range(N-m+1)])
                C = np.zeros(N-m+1)
                
                for i in range(N-m+1):
                    template_i = patterns[i]
                    for j in range(N-m+1):
                        if _maxdist(template_i, patterns[j], m) <= r:
                            C[i] += 1.0
                
                C = C / (N - m + 1.0)
                phi = np.mean(np.log(C + 1e-10))
                return phi
            
            return _phi(m) - _phi(m + 1)
        except:
            return 0.0
    
    def _calculate_sample_entropy(self, values, m=2, r=None):
        """Calculate sample entropy"""
        try:
            if not ENTROPY_AVAILABLE:
                return self._calculate_sample_entropy_fallback(values, m, r)
            
            if r is None:
                r = 0.2 * np.std(values)
            
            return float(sample_entropy(values, m, r))
        except:
            return self._calculate_sample_entropy_fallback(values, m, r)
    
    def _calculate_sample_entropy_fallback(self, values, m=2, r=None):
        """Fallback sample entropy calculation"""
        try:
            N = len(values)
            if N < m + 1:
                return 0.0
            
            if r is None:
                r = 0.2 * np.std(values)
            
            def _maxdist(xi, xj, m):
                return max([abs(ua - va) for ua, va in zip(xi, xj)])
            
            def _phi(m):
                patterns = np.array([values[i:i+m] for i in range(N-m+1)])
                matches = 0
                
                for i in range(N-m):
                    template_i = patterns[i]
                    for j in range(i+1, N-m+1):
                        if _maxdist(template_i, patterns[j], m) <= r:
                            matches += 1
                
                return matches
            
            phi_m = _phi(m)
            phi_m1 = _phi(m + 1)
            
            if phi_m == 0 or phi_m1 == 0:
                return 0.0
            
            return -np.log(phi_m1 / phi_m)
        except:
            return 0.0
    
    def _calculate_permutation_entropy(self, values, order=3):
        """Calculate permutation entropy"""
        try:
            if not ENTROPY_AVAILABLE:
                return self._calculate_permutation_entropy_fallback(values, order)
            
            return float(permutation_entropy(values, order=order))
        except:
            return self._calculate_permutation_entropy_fallback(values, order)
    
    def _calculate_permutation_entropy_fallback(self, values, order=3):
        """Fallback permutation entropy calculation"""
        try:
            from itertools import permutations
            from collections import Counter
            
            N = len(values)
            if N < order:
                return 0.0
            
            # Generate all possible ordinal patterns
            ordinal_patterns = []
            for i in range(N - order + 1):
                segment = values[i:i+order]
                # Get the ordinal pattern
                ordinal_pattern = tuple(np.argsort(segment))
                ordinal_patterns.append(ordinal_pattern)
            
            # Count pattern frequencies
            pattern_counts = Counter(ordinal_patterns)
            total_patterns = len(ordinal_patterns)
            
            # Calculate probabilities
            probabilities = [count / total_patterns for count in pattern_counts.values()]
            
            # Calculate permutation entropy
            return -sum(p * np.log2(p) for p in probabilities if p > 0)
        except:
            return 0.0
    
    def _calculate_differential_entropy(self, values):
        """Calculate differential entropy using kernel density estimation"""
        try:
            from sklearn.neighbors import KernelDensity
            
            # Fit kernel density estimator
            kde = KernelDensity(bandwidth=0.2, kernel='gaussian')
            kde.fit(values.reshape(-1, 1))
            
            # Estimate density at data points
            log_density = kde.score_samples(values.reshape(-1, 1))
            
            # Calculate differential entropy
            return -np.mean(log_density)
        except:
            return 0.0
    
    def _calculate_renyi_entropy(self, values, alpha=2.0):
        """Calculate Renyi entropy"""
        try:
            # Create histogram
            hist, _ = np.histogram(values, bins=min(50, len(values)//5), density=True)
            hist = hist[hist > 0]  # Remove zero bins
            
            if alpha == 1.0:
                # Shannon entropy case
                return -np.sum(hist * np.log2(hist + 1e-10))
            else:
                # Renyi entropy
                return (1.0 / (1.0 - alpha)) * np.log2(np.sum(hist ** alpha) + 1e-10)
        except:
            return 0.0
    
    def _calculate_lempel_ziv_complexity(self, values):
        """Calculate Lempel-Ziv complexity"""
        try:
            # Binarize the signal
            median_val = np.median(values)
            binary_string = ''.join(['1' if x > median_val else '0' for x in values])
            
            # Calculate Lempel-Ziv complexity
            complexity = 0
            i = 0
            while i < len(binary_string):
                j = i + 1
                while j <= len(binary_string):
                    substring = binary_string[i:j]
                    if substring not in binary_string[:i]:
                        complexity += 1
                        i = j
                        break
                    j += 1
                else:
                    complexity += 1
                    break
            
            # Normalize by string length
            return complexity / len(binary_string)
        except:
            return 0.0
    
    def _calculate_fractal_dimension(self, values):
        """Calculate fractal dimension using box-counting method"""
        try:
            if not ENTROPY_AVAILABLE:
                return self._calculate_fractal_dimension_fallback(values)
            return float(higuchi_fd(values))
        except:
            return self._calculate_fractal_dimension_fallback(values)
    
    def _calculate_fractal_dimension_fallback(self, values):
        """Fallback fractal dimension calculation"""
        try:
            # Simple fractal dimension estimation using variation
            N = len(values)
            scales = np.logspace(0, np.log10(N//4), 10, dtype=int)
            scales = np.unique(scales)
            
            fluctuations = []
            for scale in scales:
                # Calculate fluctuation at this scale
                n_segments = N // scale
                if n_segments < 2:
                    continue
                    
                segment_vars = []
                for i in range(n_segments):
                    segment = values[i*scale:(i+1)*scale]
                    if len(segment) > 1:
                        segment_vars.append(np.var(segment))
                
                if segment_vars:
                    fluctuations.append(np.mean(segment_vars))
            
            if len(fluctuations) > 1:
                # Fit power law
                log_scales = np.log(scales[:len(fluctuations)])
                log_fluctuations = np.log(np.array(fluctuations) + 1e-10)
                
                # Linear regression in log space
                slope = np.polyfit(log_scales, log_fluctuations, 1)[0]
                return 1 - slope  # Fractal dimension
            else:
                return 1.0
        except:
            return 1.0
    
    def _calculate_multiscale_entropy(self, values, max_scale=5):
        """Calculate multiscale entropy"""
        try:
            entropies = []
            for scale in range(1, min(max_scale + 1, len(values)//10)):
                # Coarse-grain the series
                coarse_grained = []
                for i in range(len(values) // scale):
                    segment = values[i*scale:(i+1)*scale]
                    coarse_grained.append(np.mean(segment))
                
                if len(coarse_grained) > 10:
                    # Calculate sample entropy for this scale
                    entropy_val = self._calculate_sample_entropy(np.array(coarse_grained))
                    entropies.append(entropy_val)
            
            return np.mean(entropies) if entropies else 0.0
        except:
            return 0.0
    def _calculate_spike_rate(self, values):
        """Advanced spike detection and rate analysis"""
        try:
            values = np.array(values, dtype=np.float64)
            if len(values) < 3:
                return 0.0
                
            # Remove NaN values
            values = values[~np.isnan(values)]
            if len(values) < 3:
                return 0.0
            
            # Multiple spike detection methods
            results = {
                'z_score_spikes': self._detect_z_score_spikes(values),
                'mad_spikes': self._detect_mad_spikes(values),
                'isolation_forest_spikes': self._detect_isolation_forest_spikes(values),
                'statistical_spikes': self._detect_statistical_spikes(values),
                'derivative_spikes': self._detect_derivative_spikes(values),
                'wavelet_spikes': self._detect_wavelet_spikes(values)
            }
            
            # Calculate spike rates (spikes per unit time)
            total_spikes = results['mad_spikes']['count']  # Use MAD as primary method
            spike_rate = total_spikes / len(values)
            
            # Analyze spike characteristics
            if total_spikes > 0:
                spike_positions = results['mad_spikes']['positions']
                spike_amplitudes = results['mad_spikes']['amplitudes']
                
                # Spike timing analysis
                if len(spike_positions) > 1:
                    intervals = np.diff(spike_positions)
                    results['mean_spike_interval'] = np.mean(intervals)
                    results['std_spike_interval'] = np.std(intervals)
                    results['spike_regularity'] = 1.0 / (1.0 + results['std_spike_interval'] / max(results['mean_spike_interval'], 1e-6))
                else:
                    results['mean_spike_interval'] = 0
                    results['std_spike_interval'] = 0
                    results['spike_regularity'] = 0
                
                # Spike amplitude analysis
                results['mean_spike_amplitude'] = np.mean(spike_amplitudes)
                results['std_spike_amplitude'] = np.std(spike_amplitudes)
                results['max_spike_amplitude'] = np.max(spike_amplitudes)
                
                # Spike clustering analysis
                results['spike_clusters'] = self._analyze_spike_clusters(spike_positions)
                
            else:
                for key in ['mean_spike_interval', 'std_spike_interval', 'spike_regularity',
                           'mean_spike_amplitude', 'std_spike_amplitude', 'max_spike_amplitude', 'spike_clusters']:
                    results[key] = 0
            
            results['spike_rate'] = spike_rate
            return spike_rate
            
        except Exception as e:
            self.logger.error(f"Error calculating spike rate: {e}")
            return 0.0
    
    def _detect_z_score_spikes(self, values, threshold=3.0):
        """Detect spikes using z-score method"""
        try:
            z_scores = np.abs(zscore(values))
            spike_mask = z_scores > threshold
            positions = np.where(spike_mask)[0]
            amplitudes = np.abs(values[positions] - np.median(values))
            
            return {
                'count': len(positions),
                'positions': positions,
                'amplitudes': amplitudes,
                'z_scores': z_scores[positions]
            }
        except:
            return {'count': 0, 'positions': np.array([]), 'amplitudes': np.array([]), 'z_scores': np.array([])}
    
    def _detect_mad_spikes(self, values, threshold=3.5):
        """Detect spikes using Median Absolute Deviation (MAD) method"""
        try:
            median_val = np.median(values)
            mad = np.median(np.abs(values - median_val))
            
            if mad == 0:
                # Use standard deviation if MAD is zero
                mad = np.std(values)
            
            modified_z_scores = 0.6745 * (values - median_val) / mad
            spike_mask = np.abs(modified_z_scores) > threshold
            positions = np.where(spike_mask)[0]
            amplitudes = np.abs(values[positions] - median_val)
            
            return {
                'count': len(positions),
                'positions': positions,
                'amplitudes': amplitudes,
                'mad_scores': np.abs(modified_z_scores[positions])
            }
        except:
            return {'count': 0, 'positions': np.array([]), 'amplitudes': np.array([]), 'mad_scores': np.array([])}
    
    def _detect_isolation_forest_spikes(self, values, contamination=0.1):
        """Detect spikes using Isolation Forest"""
        try:
            if len(values) < 10:
                return {'count': 0, 'positions': np.array([]), 'amplitudes': np.array([]), 'scores': np.array([])}
            
            # Reshape for sklearn
            X = values.reshape(-1, 1)
            
            # Fit Isolation Forest
            iso_forest = IsolationForest(contamination=contamination, random_state=42)
            outliers = iso_forest.fit_predict(X)
            scores = iso_forest.score_samples(X)
            
            # Find outlier positions
            positions = np.where(outliers == -1)[0]
            amplitudes = np.abs(values[positions] - np.median(values))
            
            return {
                'count': len(positions),
                'positions': positions,
                'amplitudes': amplitudes,
                'scores': -scores[positions]  # More negative = more outlier-like
            }
        except:
            return {'count': 0, 'positions': np.array([]), 'amplitudes': np.array([]), 'scores': np.array([])}
    
    def _detect_statistical_spikes(self, values, significance=0.01):
        """Detect spikes using statistical tests"""
        try:
            spikes = []
            amplitudes = []
            p_values = []
            
            # Moving window statistical test
            window_size = max(5, len(values) // 20)
            
            for i in range(window_size, len(values) - window_size):
                # Create window around point
                window = np.concatenate([
                    values[i-window_size:i],
                    values[i+1:i+window_size+1]
                ])
                
                # Perform t-test against window
                if len(window) > 0:
                    t_stat, p_value = stats.ttest_1samp([values[i]], np.mean(window))
                    
                    if p_value < significance:
                        spikes.append(i)
                        amplitudes.append(abs(values[i] - np.mean(window)))
                        p_values.append(p_value)
            
            return {
                'count': len(spikes),
                'positions': np.array(spikes),
                'amplitudes': np.array(amplitudes),
                'p_values': np.array(p_values)
            }
        except:
            return {'count': 0, 'positions': np.array([]), 'amplitudes': np.array([]), 'p_values': np.array([])}
    
    def _detect_derivative_spikes(self, values, threshold_factor=3.0):
        """Detect spikes using derivative analysis"""
        try:
            # Calculate first and second derivatives
            first_deriv = np.gradient(values)
            second_deriv = np.gradient(first_deriv)
            
            # Detect rapid changes in derivatives
            deriv_threshold = threshold_factor * np.std(first_deriv)
            
            spike_candidates = []
            for i in range(1, len(values) - 1):
                # Check for sharp transitions
                if (abs(first_deriv[i]) > deriv_threshold and
                    abs(second_deriv[i]) > threshold_factor * np.std(second_deriv)):
                    spike_candidates.append(i)
            
            positions = np.array(spike_candidates)
            amplitudes = np.abs(values[positions] - np.median(values)) if len(positions) > 0 else np.array([])
            
            return {
                'count': len(positions),
                'positions': positions,
                'amplitudes': amplitudes,
                'first_derivatives': first_deriv[positions] if len(positions) > 0 else np.array([]),
                'second_derivatives': second_deriv[positions] if len(positions) > 0 else np.array([])
            }
        except:
            return {'count': 0, 'positions': np.array([]), 'amplitudes': np.array([]), 
                   'first_derivatives': np.array([]), 'second_derivatives': np.array([])}
    
    def _detect_wavelet_spikes(self, values, wavelet='db4'):
        """Detect spikes using wavelet analysis"""
        try:
            # Wavelet decomposition
            coeffs = pywt.wavedec(values, wavelet, level=3)
            
            # Analyze detail coefficients for spikes
            spike_positions = []
            
            for level, detail in enumerate(coeffs[1:], 1):  # Skip approximation
                # Threshold detail coefficients
                threshold = 3 * np.std(detail)
                spikes_at_level = np.where(np.abs(detail) > threshold)[0]
                
                # Convert to original scale positions
                scale_factor = 2 ** level
                original_positions = spikes_at_level * scale_factor
                
                # Filter positions within bounds
                valid_positions = original_positions[original_positions < len(values)]
                spike_positions.extend(valid_positions)
            
            # Remove duplicates and sort
            positions = np.unique(np.array(spike_positions, dtype=int))
            amplitudes = np.abs(values[positions] - np.median(values)) if len(positions) > 0 else np.array([])
            
            return {
                'count': len(positions),
                'positions': positions,
                'amplitudes': amplitudes,
                'wavelet_coeffs': coeffs
            }
        except:
            return {'count': 0, 'positions': np.array([]), 'amplitudes': np.array([]), 'wavelet_coeffs': []}
    
    def _analyze_spike_clusters(self, positions):
        """Analyze clustering of spike positions"""
        try:
            if len(positions) < 2:
                return {'num_clusters': 0, 'cluster_sizes': [], 'inter_cluster_distances': []}
            
            # Use DBSCAN for clustering
            positions_reshaped = positions.reshape(-1, 1)
            
            # Adaptive epsilon based on data characteristics
            mean_interval = np.mean(np.diff(np.sort(positions)))
            eps = mean_interval / 3  # Cluster if spikes are within 1/3 of mean interval
            
            clustering = DBSCAN(eps=eps, min_samples=2).fit(positions_reshaped)
            labels = clustering.labels_
            
            # Analyze clusters
            unique_labels = set(labels)
            if -1 in unique_labels:  # Remove noise label
                unique_labels.remove(-1)
            
            num_clusters = len(unique_labels)
            cluster_sizes = [np.sum(labels == label) for label in unique_labels]
            
            # Calculate inter-cluster distances
            inter_cluster_distances = []
            if num_clusters > 1:
                cluster_centers = []
                for label in unique_labels:
                    cluster_positions = positions[labels == label]
                    cluster_centers.append(np.mean(cluster_positions))
                
                for i in range(len(cluster_centers)):
                    for j in range(i + 1, len(cluster_centers)):
                        inter_cluster_distances.append(abs(cluster_centers[i] - cluster_centers[j]))
            
            return {
                'num_clusters': num_clusters,
                'cluster_sizes': cluster_sizes,
                'inter_cluster_distances': inter_cluster_distances,
                'mean_cluster_size': np.mean(cluster_sizes) if cluster_sizes else 0,
                'mean_inter_cluster_distance': np.mean(inter_cluster_distances) if inter_cluster_distances else 0
            }
        except:
            return {'num_clusters': 0, 'cluster_sizes': [], 'inter_cluster_distances': [],
                   'mean_cluster_size': 0, 'mean_inter_cluster_distance': 0}
    def _calculate_burst_duration(self, values):
        """Advanced burst detection and duration analysis"""
        try:
            values = np.array(values, dtype=np.float64)
            if len(values) < 5:
                return 0.0
                
            # Remove NaN values
            values = values[~np.isnan(values)]
            if len(values) < 5:
                return 0.0
            
            # Multiple burst detection methods
            results = {
                'amplitude_bursts': self._detect_amplitude_bursts(values),
                'energy_bursts': self._detect_energy_bursts(values),
                'statistical_bursts': self._detect_statistical_bursts(values),
                'adaptive_bursts': self._detect_adaptive_bursts(values),
                'wavelet_bursts': self._detect_wavelet_bursts(values)
            }
            
            # Use energy bursts as primary method
            primary_bursts = results['energy_bursts']
            
            if len(primary_bursts['durations']) > 0:
                mean_duration = np.mean(primary_bursts['durations'])
                
                # Additional burst characteristics
                results['mean_burst_duration'] = mean_duration
                results['std_burst_duration'] = np.std(primary_bursts['durations'])
                results['max_burst_duration'] = np.max(primary_bursts['durations'])
                results['min_burst_duration'] = np.min(primary_bursts['durations'])
                
                # Burst frequency analysis
                results['burst_rate'] = len(primary_bursts['durations']) / len(values)
                
                # Inter-burst intervals
                if len(primary_bursts['start_positions']) > 1:
                    inter_burst_intervals = []
                    for i in range(len(primary_bursts['start_positions']) - 1):
                        interval = (primary_bursts['start_positions'][i+1] - 
                                  primary_bursts['end_positions'][i])
                        if interval > 0:
                            inter_burst_intervals.append(interval)
                    
                    if inter_burst_intervals:
                        results['mean_inter_burst_interval'] = np.mean(inter_burst_intervals)
                        results['std_inter_burst_interval'] = np.std(inter_burst_intervals)
                    else:
                        results['mean_inter_burst_interval'] = 0
                        results['std_inter_burst_interval'] = 0
                else:
                    results['mean_inter_burst_interval'] = 0
                    results['std_inter_burst_interval'] = 0
                
                # Burst intensity analysis
                results['mean_burst_intensity'] = np.mean(primary_bursts['intensities'])
                results['std_burst_intensity'] = np.std(primary_bursts['intensities'])
                
                return mean_duration
            else:
                return 0.0
                
        except Exception as e:
            self.logger.error(f"Error calculating burst duration: {e}")
            return 0.0
    
    def _detect_amplitude_bursts(self, values, threshold_factor=2.0):
        """Detect bursts based on amplitude thresholding"""
        try:
            # Calculate adaptive threshold
            baseline = np.median(values)
            threshold = baseline + threshold_factor * np.std(values)
            
            # Find periods above threshold
            above_threshold = values > threshold
            
            # Find burst boundaries
            burst_starts = []
            burst_ends = []
            durations = []
            intensities = []
            
            in_burst = False
            burst_start = 0
            
            for i, is_above in enumerate(above_threshold):
                if is_above and not in_burst:
                    # Start of burst
                    burst_start = i
                    in_burst = True
                elif not is_above and in_burst:
                    # End of burst
                    burst_end = i - 1
                    duration = burst_end - burst_start + 1
                    
                    if duration >= 3:  # Minimum burst duration
                        burst_starts.append(burst_start)
                        burst_ends.append(burst_end)
                        durations.append(duration)
                        intensities.append(np.mean(values[burst_start:burst_end+1]))
                    
                    in_burst = False
            
            # Handle burst that extends to end
            if in_burst:
                duration = len(values) - burst_start
                if duration >= 3:
                    burst_starts.append(burst_start)
                    burst_ends.append(len(values) - 1)
                    durations.append(duration)
                    intensities.append(np.mean(values[burst_start:]))
            
            return {
                'start_positions': np.array(burst_starts),
                'end_positions': np.array(burst_ends),
                'durations': np.array(durations),
                'intensities': np.array(intensities)
            }
        except:
            return {'start_positions': np.array([]), 'end_positions': np.array([]), 
                   'durations': np.array([]), 'intensities': np.array([])}
    
    def _detect_energy_bursts(self, values, window_size=None, threshold_factor=2.5):
        """Detect bursts based on local energy content"""
        try:
            if window_size is None:
                window_size = max(3, len(values) // 50)
            
            # Calculate local energy using sliding window
            energy = np.zeros(len(values))
            half_window = window_size // 2
            
            for i in range(len(values)):
                start_idx = max(0, i - half_window)
                end_idx = min(len(values), i + half_window + 1)
                window = values[start_idx:end_idx]
                energy[i] = np.sum(window ** 2)  # Energy as sum of squares
            
            # Smooth energy signal
            energy_smooth = gaussian_filter1d(energy, sigma=1.0)
            
            # Calculate adaptive threshold
            baseline_energy = np.median(energy_smooth)
            threshold = baseline_energy + threshold_factor * np.std(energy_smooth)
            
            # Detect bursts
            above_threshold = energy_smooth > threshold
            
            # Find burst boundaries
            burst_starts = []
            burst_ends = []
            durations = []
            intensities = []
            
            in_burst = False
            burst_start = 0
            
            for i, is_above in enumerate(above_threshold):
                if is_above and not in_burst:
                    burst_start = i
                    in_burst = True
                elif not is_above and in_burst:
                    burst_end = i - 1
                    duration = burst_end - burst_start + 1
                    
                    if duration >= 3:
                        burst_starts.append(burst_start)
                        burst_ends.append(burst_end)
                        durations.append(duration)
                        intensities.append(np.mean(energy_smooth[burst_start:burst_end+1]))
                    
                    in_burst = False
            
            # Handle burst that extends to end
            if in_burst:
                duration = len(values) - burst_start
                if duration >= 3:
                    burst_starts.append(burst_start)
                    burst_ends.append(len(values) - 1)
                    durations.append(duration)
                    intensities.append(np.mean(energy_smooth[burst_start:]))
            
            return {
                'start_positions': np.array(burst_starts),
                'end_positions': np.array(burst_ends),
                'durations': np.array(durations),
                'intensities': np.array(intensities),
                'energy_signal': energy_smooth
            }
        except:
            return {'start_positions': np.array([]), 'end_positions': np.array([]), 
                   'durations': np.array([]), 'intensities': np.array([])}
    
    def _detect_statistical_bursts(self, values, window_size=None, significance=0.01):
        """Detect bursts using statistical change point detection"""
        try:
            if window_size is None:
                window_size = max(5, len(values) // 30)
            
            # Calculate moving statistics
            moving_mean = []
            moving_std = []
            
            for i in range(len(values) - window_size + 1):
                window = values[i:i+window_size]
                moving_mean.append(np.mean(window))
                moving_std.append(np.std(window))
            
            moving_mean = np.array(moving_mean)
            moving_std = np.array(moving_std)
            
            # Detect significant changes using t-tests
            change_points = []
            baseline_mean = np.median(moving_mean)
            baseline_std = np.median(moving_std)
            
            for i in range(len(moving_mean)):
                # Test if current window is significantly different
                t_stat = abs(moving_mean[i] - baseline_mean) / (baseline_std + 1e-10)
                p_value = 2 * (1 - stats.norm.cdf(t_stat))  # Two-tailed test
                
                if p_value < significance:
                    change_points.append(i)
            
            # Group change points into bursts
            if not change_points:
                return {'start_positions': np.array([]), 'end_positions': np.array([]), 
                       'durations': np.array([]), 'intensities': np.array([])}
            
            bursts = self._group_change_points_into_bursts(change_points, moving_mean)
            
            return bursts
        except:
            return {'start_positions': np.array([]), 'end_positions': np.array([]), 
                   'durations': np.array([]), 'intensities': np.array([])}
    
    def _detect_adaptive_bursts(self, values, adaptation_rate=0.1):
        """Detect bursts using adaptive threshold"""
        try:
            # Initialize adaptive parameters
            threshold = np.mean(values[:min(10, len(values))])
            threshold_std = np.std(values[:min(10, len(values))])
            
            burst_starts = []
            burst_ends = []
            durations = []
            intensities = []
            
            in_burst = False
            burst_start = 0
            
            for i, value in enumerate(values):
                # Update adaptive threshold
                if i > 0:
                    threshold = (1 - adaptation_rate) * threshold + adaptation_rate * value
                    threshold_std = (1 - adaptation_rate) * threshold_std + adaptation_rate * abs(value - threshold)
                
                # Check burst condition
                burst_threshold = threshold + 2 * threshold_std
                
                if value > burst_threshold and not in_burst:
                    # Start of burst
                    burst_start = i
                    in_burst = True
                elif value <= burst_threshold and in_burst:
                    # End of burst
                    burst_end = i - 1
                    duration = burst_end - burst_start + 1
                    
                    if duration >= 3:
                        burst_starts.append(burst_start)
                        burst_ends.append(burst_end)
                        durations.append(duration)
                        intensities.append(np.mean(values[burst_start:burst_end+1]))
                    
                    in_burst = False
            
            # Handle burst that extends to end
            if in_burst:
                duration = len(values) - burst_start
                if duration >= 3:
                    burst_starts.append(burst_start)
                    burst_ends.append(len(values) - 1)
                    durations.append(duration)
                    intensities.append(np.mean(values[burst_start:]))
            
            return {
                'start_positions': np.array(burst_starts),
                'end_positions': np.array(burst_ends),
                'durations': np.array(durations),
                'intensities': np.array(intensities)
            }
        except:
            return {'start_positions': np.array([]), 'end_positions': np.array([]), 
                   'durations': np.array([]), 'intensities': np.array([])}
    
    def _detect_wavelet_bursts(self, values, wavelet='db4', level=3):
        """Detect bursts using wavelet decomposition"""
        try:
            # Wavelet decomposition
            coeffs = pywt.wavedec(values, wavelet, level=level)
            
            # Reconstruct signal from detail coefficients
            detail_reconstruction = np.zeros_like(values)
            
            for i, detail in enumerate(coeffs[1:], 1):
                # Upsample detail coefficients to original length
                upsampled = np.repeat(detail, 2**i)
                if len(upsampled) > len(detail_reconstruction):
                    upsampled = upsampled[:len(detail_reconstruction)]
                elif len(upsampled) < len(detail_reconstruction):
                    upsampled = np.pad(upsampled, (0, len(detail_reconstruction) - len(upsampled)), 'constant')
                
                detail_reconstruction += upsampled
            
            # Detect bursts in reconstructed detail signal
            return self._detect_energy_bursts(np.abs(detail_reconstruction))
        except:
            return {'start_positions': np.array([]), 'end_positions': np.array([]), 
                   'durations': np.array([]), 'intensities': np.array([])}
    
    def _group_change_points_into_bursts(self, change_points, moving_mean):
        """Group change points into continuous bursts"""
        try:
            if not change_points:
                return {'start_positions': np.array([]), 'end_positions': np.array([]), 
                       'durations': np.array([]), 'intensities': np.array([])}
            
            # Group consecutive change points
            burst_starts = []
            burst_ends = []
            durations = []
            intensities = []
            
            current_start = change_points[0]
            current_end = change_points[0]
            
            for i in range(1, len(change_points)):
                if change_points[i] <= current_end + 2:  # Allow small gaps
                    current_end = change_points[i]
                else:
                    # End current burst, start new one
                    duration = current_end - current_start + 1
                    if duration >= 3:
                        burst_starts.append(current_start)
                        burst_ends.append(current_end)
                        durations.append(duration)
                        intensities.append(np.mean(moving_mean[current_start:current_end+1]))
                    
                    current_start = change_points[i]
                    current_end = change_points[i]
            
            # Handle last burst
            duration = current_end - current_start + 1
            if duration >= 3:
                burst_starts.append(current_start)
                burst_ends.append(current_end)
                durations.append(duration)
                intensities.append(np.mean(moving_mean[current_start:current_end+1]))
            
            return {
                'start_positions': np.array(burst_starts),
                'end_positions': np.array(burst_ends),
                'durations': np.array(durations),
                'intensities': np.array(intensities)
            }
        except:
            return {'start_positions': np.array([]), 'end_positions': np.array([]), 
                   'durations': np.array([]), 'intensities': np.array([])}
                   
    def _calculate_periodicity_strength(self, values):
        """Advanced periodicity analysis using multiple methods"""
        try:
            values = np.array(values, dtype=np.float64)
            if len(values) < 10:
                return 0.0
                
            # Remove NaN values
            values = values[~np.isnan(values)]
            if len(values) < 10:
                return 0.0
            
            # Multiple periodicity detection methods
            results = {
                'autocorr_periodicity': self._calculate_autocorr_periodicity(values),
                'fft_periodicity': self._calculate_fft_periodicity(values),
                'wavelet_periodicity': self._calculate_wavelet_periodicity(values),
                'lomb_scargle_periodicity': self._calculate_lomb_scargle_periodicity(values),
                'spectral_peak_ratio': self._calculate_spectral_peak_ratio(values),
                'phase_coherence': self._calculate_phase_coherence(values)
            }
            
            # Combine different measures for robust periodicity strength
            weights = {'autocorr_periodicity': 0.3, 'fft_periodicity': 0.25, 
                      'wavelet_periodicity': 0.2, 'lomb_scargle_periodicity': 0.15,
                      'spectral_peak_ratio': 0.05, 'phase_coherence': 0.05}
            
            weighted_strength = sum(results[key] * weights[key] for key in weights.keys()
                                  if results[key] is not None and not np.isnan(results[key]))
            
            # Normalize to [0, 1] range
            periodicity_strength = min(max(weighted_strength, 0.0), 1.0)
            
            # Additional periodicity characteristics
            results['dominant_period'] = self._find_dominant_period(values)
            results['period_stability'] = self._calculate_period_stability(values)
            results['harmonic_strength'] = self._calculate_harmonic_strength(values)
            
            return periodicity_strength
            
        except Exception as e:
            self.logger.error(f"Error calculating periodicity strength: {e}")
            return 0.0
    
    def _calculate_autocorr_periodicity(self, values, max_lag=None):
        """Calculate periodicity using autocorrelation"""
        try:
            if max_lag is None:
                max_lag = min(len(values) // 3, 100)
            
            # Calculate autocorrelation
            autocorr = np.correlate(values - np.mean(values), values - np.mean(values), mode='full')
            autocorr = autocorr[autocorr.size // 2:]
            autocorr = autocorr / autocorr[0]  # Normalize
            
            # Find peaks in autocorrelation (excluding lag 0)
            if len(autocorr) > max_lag:
                autocorr_subset = autocorr[1:max_lag]
            else:
                autocorr_subset = autocorr[1:]
            
            if len(autocorr_subset) == 0:
                return 0.0
            
            # Find the maximum autocorrelation value (excluding lag 0)
            max_autocorr = np.max(autocorr_subset)
            
            # Calculate periodicity strength based on max autocorrelation
            return max(0.0, max_autocorr)
            
        except:
            return 0.0
    
    def _calculate_fft_periodicity(self, values):
        """Calculate periodicity using FFT spectral analysis"""
        try:
            # Remove trend and apply window
            detrended = detrend(values)
            windowed = detrended * hann(len(detrended))
            
            # Calculate FFT
            fft_vals = np.abs(fft(windowed))
            freqs = fftfreq(len(windowed))
            
            # Consider only positive frequencies
            pos_freqs = freqs[:len(freqs)//2]
            pos_fft = fft_vals[:len(fft_vals)//2]
            
            if len(pos_fft) == 0:
                return 0.0
            
            # Calculate spectral centroid and spread
            total_power = np.sum(pos_fft)
            if total_power == 0:
                return 0.0
                
            # Find dominant frequency
            max_power_idx = np.argmax(pos_fft)
            max_power = pos_fft[max_power_idx]
            
            # Calculate periodicity as ratio of max power to total power
            periodicity = max_power / total_power
            
            return min(periodicity, 1.0)
            
        except:
            return 0.0
    
    def _calculate_wavelet_periodicity(self, values, wavelet='morlet'):
        """Calculate periodicity using continuous wavelet transform"""
        try:
            # Define scales for CWT
            scales = np.arange(1, min(len(values)//4, 50))
            
            # Compute CWT
            coefficients, frequencies = pywt.cwt(values, scales, wavelet)
            
            # Calculate power spectrum
            power = np.abs(coefficients) ** 2
            
            # Find the scale with maximum power
            max_power_scale_idx = np.unravel_index(np.argmax(power), power.shape)[0]
            max_power = np.max(power[max_power_scale_idx, :])
            
            # Calculate average power
            avg_power = np.mean(power)
            
            if avg_power == 0:
                return 0.0
            
            # Periodicity strength as ratio of max to average power
            periodicity = max_power / (avg_power * len(scales))
            
            return min(periodicity, 1.0)
            
        except:
            return 0.0
    
    def _calculate_lomb_scargle_periodicity(self, values):
        """Calculate periodicity using Lomb-Scargle for unevenly sampled data"""
        try:
            # Create time array
            time = np.arange(len(values))
            
            # Define frequency range
            min_freq = 1.0 / len(values)
            max_freq = 0.5  # Nyquist frequency
            frequencies = np.linspace(min_freq, max_freq, min(100, len(values)//4))
            
            if len(frequencies) == 0:
                return 0.0
            
            # Calculate Lomb-Scargle periodogram
            from scipy.signal import lombscargle
            power = lombscargle(time, values - np.mean(values), frequencies)
            
            # Find maximum power
            max_power = np.max(power)
            avg_power = np.mean(power)
            
            if avg_power == 0:
                return 0.0
            
            # Periodicity strength
            periodicity = max_power / avg_power / len(frequencies)
            
            return min(periodicity, 1.0)
            
        except:
            return 0.0
    
    def _calculate_spectral_peak_ratio(self, values):
        """Calculate ratio of dominant spectral peak to background"""
        try:
            # Calculate power spectral density
            freqs, psd = welch(values, nperseg=min(256, len(values)//4))
            
            if len(psd) == 0:
                return 0.0
            
            # Find dominant peak
            max_idx = np.argmax(psd)
            max_power = psd[max_idx]
            
            # Calculate background power (excluding peak region)
            peak_width = max(1, len(psd) // 20)
            background_mask = np.ones(len(psd), dtype=bool)
            start_idx = max(0, max_idx - peak_width)
            end_idx = min(len(psd), max_idx + peak_width + 1)
            background_mask[start_idx:end_idx] = False
            
            if np.sum(background_mask) == 0:
                return 0.0
            
            background_power = np.mean(psd[background_mask])
            
            if background_power == 0:
                return min(max_power / (np.mean(psd) + 1e-10), 1.0)
            
            # Peak-to-background ratio
            ratio = max_power / background_power
            
            # Normalize to [0, 1]
            return min(1.0 / (1.0 + np.exp(-0.1 * (ratio - 10))), 1.0)
            
        except:
            return 0.0
    
    def _calculate_phase_coherence(self, values):
        """Calculate phase coherence as measure of periodicity"""
        try:
            # Apply Hilbert transform to get instantaneous phase
            analytic_signal = hilbert(values)
            phase = np.unwrap(np.angle(analytic_signal))
            
            # Calculate instantaneous frequency
            inst_freq = np.diff(phase) / (2 * np.pi)
            
            if len(inst_freq) == 0:
                return 0.0
            
            # Calculate phase coherence as inverse of frequency variability
            freq_std = np.std(inst_freq)
            mean_freq = np.mean(np.abs(inst_freq))
            
            if mean_freq == 0:
                return 0.0
            
            # Coherence as inverse coefficient of variation
            coherence = 1.0 / (1.0 + freq_std / mean_freq)
            
            return min(coherence, 1.0)
            
        except:
            return 0.0
    
    def _find_dominant_period(self, values):
        """Find the dominant period in the signal"""
        try:
            # Use autocorrelation to find dominant period
            autocorr = np.correlate(values - np.mean(values), values - np.mean(values), mode='full')
            autocorr = autocorr[autocorr.size // 2:]
            autocorr = autocorr / autocorr[0]
            
            # Find first significant peak (excluding lag 0)
            threshold = 0.1  # Minimum correlation for significant peak
            for lag in range(1, min(len(autocorr), len(values)//3)):
                if (autocorr[lag] > threshold and 
                    lag > 1 and autocorr[lag] > autocorr[lag-1] and 
                    lag < len(autocorr)-1 and autocorr[lag] > autocorr[lag+1]):
                    return lag
            
            return 0  # No significant period found
            
        except:
            return 0
    
    def _calculate_period_stability(self, values):
        """Calculate stability of the dominant period over time"""
        try:
            # Divide signal into segments and find period in each
            segment_size = max(20, len(values) // 5)
            periods = []
            
            for i in range(0, len(values) - segment_size + 1, segment_size // 2):
                segment = values[i:i+segment_size]
                period = self._find_dominant_period(segment)
                if period > 0:
                    periods.append(period)
            
            if len(periods) < 2:
                return 0.0
            
            # Calculate stability as inverse coefficient of variation
            mean_period = np.mean(periods)
            std_period = np.std(periods)
            
            if mean_period == 0:
                return 0.0
            
            stability = 1.0 / (1.0 + std_period / mean_period)
            
            return min(stability, 1.0)
            
        except:
            return 0.0
    
    def _calculate_harmonic_strength(self, values):
        """Calculate strength of harmonic content"""
        try:
            # Calculate FFT
            fft_vals = np.abs(fft(values - np.mean(values)))
            freqs = fftfreq(len(values))
            
            # Consider only positive frequencies
            pos_freqs = freqs[:len(freqs)//2]
            pos_fft = fft_vals[:len(fft_vals)//2]
            
            if len(pos_fft) < 4:
                return 0.0
            
            # Find fundamental frequency (dominant peak)
            fundamental_idx = np.argmax(pos_fft[1:]) + 1  # Exclude DC component
            fundamental_freq = pos_freqs[fundamental_idx]
            
            if fundamental_freq == 0:
                return 0.0
            
            # Look for harmonics (2f, 3f, 4f, etc.)
            harmonic_power = 0
            fundamental_power = pos_fft[fundamental_idx]
            
            for harmonic in range(2, 5):  # Check up to 4th harmonic
                harmonic_freq = harmonic * fundamental_freq
                
                # Find closest frequency bin
                harmonic_idx = np.argmin(np.abs(pos_freqs - harmonic_freq))
                
                if harmonic_idx < len(pos_fft):
                    harmonic_power += pos_fft[harmonic_idx]
            
            # Harmonic strength as ratio of harmonic power to fundamental power
            if fundamental_power == 0:
                return 0.0
            
            harmonic_strength = harmonic_power / fundamental_power
            
            return min(harmonic_strength, 1.0)
            
        except:
            return 0.0
            
    def _calculate_cycle_regularity(self, values):
        """Comprehensive cycle analysis and regularity metrics"""
        try:
            values = np.array(values, dtype=np.float64)
            if len(values) < 10:
                return 0.0
                
            # Remove NaN values
            values = values[~np.isnan(values)]
            if len(values) < 10:
                return 0.0
            
            # Multiple cycle regularity measures
            results = {
                'peak_to_peak_regularity': self._calculate_peak_to_peak_regularity(values),
                'zero_crossing_regularity': self._calculate_zero_crossing_regularity(values),
                'phase_regularity': self._calculate_phase_regularity(values),
                'amplitude_regularity': self._calculate_amplitude_regularity(values),
                'frequency_stability': self._calculate_frequency_stability(values),
                'cycle_shape_consistency': self._calculate_cycle_shape_consistency(values)
            }
            
            # Weighted combination of regularity measures
            weights = {
                'peak_to_peak_regularity': 0.25,
                'zero_crossing_regularity': 0.20,
                'phase_regularity': 0.20,
                'amplitude_regularity': 0.15,
                'frequency_stability': 0.15,
                'cycle_shape_consistency': 0.05
            }
            
            regularity_score = sum(results[key] * weights[key] for key in weights.keys()
                                 if results[key] is not None and not np.isnan(results[key]))
            
            # Additional cycle characteristics
            results['cycle_count'] = self._count_complete_cycles(values)
            results['average_cycle_length'] = self._calculate_average_cycle_length(values)
            results['cycle_symmetry'] = self._calculate_cycle_symmetry(values)
            
            return min(max(regularity_score, 0.0), 1.0)
            
        except Exception as e:
            self.logger.error(f"Error calculating cycle regularity: {e}")
            return 0.0
    
    def _calculate_peak_to_peak_regularity(self, values):
        """Calculate regularity based on peak-to-peak intervals"""
        try:
            # Find peaks
            peaks, _ = find_peaks(values, height=np.mean(values) + 0.5 * np.std(values))
            
            if len(peaks) < 3:
                return 0.0
            
            # Calculate peak-to-peak intervals
            intervals = np.diff(peaks)
            
            if len(intervals) == 0:
                return 0.0
            
            # Regularity as inverse coefficient of variation
            mean_interval = np.mean(intervals)
            std_interval = np.std(intervals)
            
            if mean_interval == 0:
                return 0.0
            
            regularity = 1.0 / (1.0 + std_interval / mean_interval)
            
            return min(regularity, 1.0)
            
        except:
            return 0.0
    
    def _calculate_zero_crossing_regularity(self, values):
        """Calculate regularity based on zero crossings"""
        try:
            # Center the signal
            centered = values - np.mean(values)
            
            # Find zero crossings
            crossings = np.where(np.diff(np.sign(centered)) != 0)[0]
            
            if len(crossings) < 4:  # Need at least 2 complete cycles
                return 0.0
            
            # Calculate intervals between crossings
            intervals = np.diff(crossings)
            
            if len(intervals) == 0:
                return 0.0
            
            # Look at every other interval (full cycle)
            if len(intervals) >= 2:
                full_cycle_intervals = intervals[::2]  # Every other interval
                if len(full_cycle_intervals) > 1:
                    mean_interval = np.mean(full_cycle_intervals)
                    std_interval = np.std(full_cycle_intervals)
                else:
                    mean_interval = np.mean(intervals)
                    std_interval = np.std(intervals)
            else:
                mean_interval = np.mean(intervals)
                std_interval = np.std(intervals)
            
            if mean_interval == 0:
                return 0.0
            
            regularity = 1.0 / (1.0 + std_interval / mean_interval)
            
            return min(regularity, 1.0)
            
        except:
            return 0.0
    
    def _calculate_phase_regularity(self, values):
        """Calculate regularity based on instantaneous phase"""
        try:
            # Apply Hilbert transform
            analytic_signal = hilbert(values)
            phase = np.unwrap(np.angle(analytic_signal))
            
            # Calculate instantaneous frequency
            inst_freq = np.diff(phase) / (2 * np.pi)
            
            if len(inst_freq) == 0:
                return 0.0
            
            # Remove outliers in instantaneous frequency
            q75, q25 = np.percentile(inst_freq, [75, 25])
            iqr = q75 - q25
            lower_bound = q25 - 1.5 * iqr
            upper_bound = q75 + 1.5 * iqr
            filtered_freq = inst_freq[(inst_freq >= lower_bound) & (inst_freq <= upper_bound)]
            
            if len(filtered_freq) == 0:
                return 0.0
            
            # Calculate frequency stability
            mean_freq = np.mean(filtered_freq)
            std_freq = np.std(filtered_freq)
            
            if mean_freq == 0:
                return 0.0
            
            regularity = 1.0 / (1.0 + std_freq / abs(mean_freq))
            
            return min(regularity, 1.0)
            
        except:
            return 0.0
    
    def _calculate_amplitude_regularity(self, values):
        """Calculate regularity based on amplitude variations"""
        try:
            # Calculate envelope using Hilbert transform
            analytic_signal = hilbert(values)
            envelope = np.abs(analytic_signal)
            
            # Find local maxima in envelope
            peaks, _ = find_peaks(envelope)
            
            if len(peaks) < 3:
                return 0.0
            
            # Calculate amplitude variations
            peak_amplitudes = envelope[peaks]
            
            if len(peak_amplitudes) == 0:
                return 0.0
            
            # Regularity as inverse coefficient of variation
            mean_amplitude = np.mean(peak_amplitudes)
            std_amplitude = np.std(peak_amplitudes)
            
            if mean_amplitude == 0:
                return 0.0
            
            regularity = 1.0 / (1.0 + std_amplitude / mean_amplitude)
            
            return min(regularity, 1.0)
            
        except:
            return 0.0
    
    def _calculate_frequency_stability(self, values):
        """Calculate frequency stability over time"""
        try:
            # Use short-time Fourier transform for time-frequency analysis
            nperseg = min(64, len(values) // 4)
            if nperseg < 8:
                return 0.0
            
            f, t, Zxx = spectrogram(values, nperseg=nperseg, noverlap=nperseg//2)
            
            if Zxx.size == 0:
                return 0.0
            
            # Find dominant frequency in each time window
            dominant_freqs = []
            for time_idx in range(Zxx.shape[1]):
                spectrum = np.abs(Zxx[:, time_idx])
                if np.sum(spectrum) > 0:
                    dominant_freq_idx = np.argmax(spectrum)
                    dominant_freqs.append(f[dominant_freq_idx])
            
            if len(dominant_freqs) < 2:
                return 0.0
            
            # Calculate frequency stability
            mean_freq = np.mean(dominant_freqs)
            std_freq = np.std(dominant_freqs)
            
            if mean_freq == 0:
                return 0.0
            
            stability = 1.0 / (1.0 + std_freq / mean_freq)
            
            return min(stability, 1.0)
            
        except:
            return 0.0
    
    def _calculate_cycle_shape_consistency(self, values):
        """Calculate consistency of cycle shapes"""
        try:
            # Find cycle boundaries using zero crossings
            centered = values - np.mean(values)
            crossings = np.where(np.diff(np.sign(centered)) != 0)[0]
            
            if len(crossings) < 4:  # Need at least 2 complete cycles
                return 0.0
            
            # Extract individual cycles
            cycles = []
            for i in range(len(crossings) - 2):
                start_idx = crossings[i]
                end_idx = crossings[i + 2]  # Full cycle (two zero crossings)
                cycle = values[start_idx:end_idx + 1]
                if len(cycle) > 3:  # Minimum cycle length
                    cycles.append(cycle)
            
            if len(cycles) < 2:
                return 0.0
            
            # Normalize cycle lengths by interpolation
            target_length = min(50, max(len(cycle) for cycle in cycles))
            normalized_cycles = []
            
            for cycle in cycles:
                if len(cycle) > 1:
                    # Interpolate to target length
                    old_indices = np.linspace(0, 1, len(cycle))
                    new_indices = np.linspace(0, 1, target_length)
                    interpolated = np.interp(new_indices, old_indices, cycle)
                    normalized_cycles.append(interpolated)
            
            if len(normalized_cycles) < 2:
                return 0.0
            
            # Calculate pairwise correlations between cycles
            correlations = []
            for i in range(len(normalized_cycles)):
                for j in range(i + 1, len(normalized_cycles)):
                    corr = np.corrcoef(normalized_cycles[i], normalized_cycles[j])[0, 1]
                    if not np.isnan(corr):
                        correlations.append(abs(corr))
            
            if len(correlations) == 0:
                return 0.0
            
            # Average correlation as measure of shape consistency
            consistency = np.mean(correlations)
            
            return min(consistency, 1.0)
            
        except:
            return 0.0
    
    def _count_complete_cycles(self, values):
        """Count the number of complete cycles in the signal"""
        try:
            # Use zero crossings to identify cycles
            centered = values - np.mean(values)
            crossings = np.where(np.diff(np.sign(centered)) != 0)[0]
            
            # Each pair of crossings represents a half-cycle
            # So number of complete cycles is (number of crossings - 1) // 2
            if len(crossings) >= 2:
                return max(0, (len(crossings) - 1) // 2)
            else:
                return 0
        except:
            return 0
    
    def _calculate_average_cycle_length(self, values):
        """Calculate the average length of cycles in the signal"""
        try:
            # Use zero crossings to identify cycle boundaries
            centered = values - np.mean(values)
            crossings = np.where(np.diff(np.sign(centered)) != 0)[0]
            
            if len(crossings) < 2:
                return 0.0
            
            # Calculate intervals between every other crossing (full cycles)
            full_cycle_intervals = []
            for i in range(0, len(crossings) - 2, 2):
                interval = crossings[i + 2] - crossings[i]
                full_cycle_intervals.append(interval)
            
            if len(full_cycle_intervals) == 0:
                return 0.0
            
            return np.mean(full_cycle_intervals)
            
        except:
            return 0.0
    
    def _calculate_cycle_symmetry(self, values):
        """Calculate symmetry of individual cycles"""
        try:
            # Find cycle boundaries
            centered = values - np.mean(values)
            crossings = np.where(np.diff(np.sign(centered)) != 0)[0]
            
            if len(crossings) < 4:  # Need at least 2 complete cycles
                return 0.0
            
            # Extract individual cycles and calculate symmetry
            symmetries = []
            
            for i in range(len(crossings) - 2):
                start_idx = crossings[i]
                end_idx = crossings[i + 2]
                cycle = values[start_idx:end_idx + 1]
                
                if len(cycle) > 3:
                    # Calculate symmetry as correlation with time-reversed cycle
                    reversed_cycle = cycle[::-1]
                    if len(cycle) == len(reversed_cycle):
                        corr = np.corrcoef(cycle, reversed_cycle)[0, 1]
                        if not np.isnan(corr):
                            symmetries.append(abs(corr))
            
            if len(symmetries) == 0:
                return 0.0
            
            return np.mean(symmetries)
            
        except:
            return 0.0

    def _calculate_seasonal_strength(self, values):
        """Advanced seasonal decomposition and strength analysis"""
        try:
            values = np.array(values, dtype=np.float64)
            if len(values) < 20:  # Need minimum length for seasonal analysis
                return 0.0
                
            # Remove NaN values
            values = values[~np.isnan(values)]
            if len(values) < 20:
                return 0.0
            
            # Multiple seasonal analysis methods
            results = {
                'stl_seasonal_strength': self._calculate_stl_seasonal_strength(values),
                'classical_seasonal_strength': self._calculate_classical_seasonal_strength(values),
                'x13_seasonal_strength': self._calculate_x13_seasonal_strength(values),
                'wavelet_seasonal_strength': self._calculate_wavelet_seasonal_strength(values),
                'autocorr_seasonal_strength': self._calculate_autocorr_seasonal_strength(values),
                'spectral_seasonal_strength': self._calculate_spectral_seasonal_strength(values)
            }
            
            # Remove None values and calculate weighted average
            valid_results = {k: v for k, v in results.items() if v is not None and not np.isnan(v)}
            
            if not valid_results:
                return 0.0
            
            # Weights for different methods
            weights = {
                'stl_seasonal_strength': 0.3,
                'classical_seasonal_strength': 0.2,
                'x13_seasonal_strength': 0.15,
                'wavelet_seasonal_strength': 0.15,
                'autocorr_seasonal_strength': 0.1,
                'spectral_seasonal_strength': 0.1
            }
            
            # Calculate weighted average
            total_weight = sum(weights[k] for k in valid_results.keys())
            if total_weight == 0:
                return 0.0
            
            seasonal_strength = sum(valid_results[k] * weights.get(k, 0) for k in valid_results.keys()) / total_weight
            
            # Additional seasonal characteristics
            results['seasonal_period'] = self._estimate_seasonal_period(values)
            results['seasonal_stability'] = self._calculate_seasonal_stability(values)
            results['seasonal_amplitude'] = self._calculate_seasonal_amplitude(values)
            
            return min(max(seasonal_strength, 0.0), 1.0)
            
        except Exception as e:
            self.logger.error(f"Error calculating seasonal strength: {e}")
            return 0.0

