class PerformanceAlertSystem:
    """Advanced ML-based performance alerting with multi-level detection and adaptive thresholds."""
    
    def __init__(self, config: Optional[Dict] = None):
        self.config = config or {}
        self.alert_history = deque(maxlen=10000)
        self.performance_history = deque(maxlen=50000)
        
        # Multi-level alert configuration
        self.alert_levels = {
            'info': {'priority': 1, 'threshold': 0.3, 'cooldown': 300},      # 5 minutes
            'warning': {'priority': 2, 'threshold': 0.5, 'cooldown': 600},   # 10 minutes  
            'critical': {'priority': 3, 'threshold': 0.7, 'cooldown': 900},  # 15 minutes
            'emergency': {'priority': 4, 'threshold': 0.9, 'cooldown': 1800} # 30 minutes
        }
        
        # Alert detection models
        self.anomaly_detectors = self._initialize_anomaly_detectors()
        self.trend_detectors = self._initialize_trend_detectors()
        self.threshold_detectors = self._initialize_threshold_detectors()
        
        # Adaptive threshold management
        self.adaptive_thresholds = {}
        self.threshold_history = deque(maxlen=1000)
        self.false_positive_tracker = {}
        
        # Performance baseline tracking
        self.baseline_calculator = self._initialize_baseline_calculator()
        self.performance_baselines = {}
        self.baseline_update_frequency = 1000  # Update every 1000 samples
        
        # Alert suppression and correlation
        self.alert_correlations = {}
        self.alert_suppressions = {}
        self.correlation_window = 3600  # 1 hour correlation window
        
        # Machine learning models for alert prediction
        self.alert_predictors = self._initialize_alert_predictors()
        
        self.logger = logging.getLogger(__name__)
        self.logger.info("Advanced PerformanceAlertSystem initialized")
    
    def _initialize_anomaly_detectors(self) -> Dict[str, Any]:
        """Initialize ML-based anomaly detection models."""
        detectors = {}
        
        try:
            from sklearn.ensemble import IsolationForest
            from sklearn.neighbors import LocalOutlierFactor
            from sklearn.svm import OneClassSVM
            from sklearn.covariance import EllipticEnvelope
            
            detectors.update({
                'isolation_forest': IsolationForest(
                    contamination=0.05, 
                    random_state=42, 
                    n_estimators=200,
                    max_features=1.0
                ),
                'local_outlier_factor': LocalOutlierFactor(
                    contamination=0.05,
                    n_neighbors=20,
                    algorithm='auto'
                ),
                'one_class_svm': OneClassSVM(
                    kernel='rbf',
                    gamma='scale',
                    nu=0.05
                ),
                'elliptic_envelope': EllipticEnvelope(
                    contamination=0.05,
                    random_state=42
                )
            })
        except ImportError:
            self.logger.warning("Scikit-learn unavailable for anomaly detection")
        
        # Statistical anomaly detectors (always available)
        detectors.update({
            'z_score_detector': self._create_zscore_detector(),
            'iqr_detector': self._create_iqr_detector(),
            'grubbs_detector': self._create_grubbs_detector(),
            'modified_zscore_detector': self._create_modified_zscore_detector()
        })
        
        return detectors
    
    def _initialize_trend_detectors(self) -> Dict[str, Any]:
        """Initialize trend-based alert detection systems."""
        return {
            'mann_kendall_detector': self._create_mann_kendall_detector(),
            'cusum_detector': self._create_cusum_detector(),
            'exponential_smoothing_detector': self._create_exponential_smoothing_detector(),
            'changepoint_detector': self._create_changepoint_detector(),
            'regime_change_detector': self._create_regime_change_detector()
        }
    
    def _initialize_threshold_detectors(self) -> Dict[str, Any]:
        """Initialize threshold-based detection systems."""
        return {
            'percentile_detector': self._create_percentile_detector(),
            'rolling_statistics_detector': self._create_rolling_statistics_detector(),
            'seasonal_threshold_detector': self._create_seasonal_threshold_detector(),
            'contextual_threshold_detector': self._create_contextual_threshold_detector()
        }
    
    def _initialize_baseline_calculator(self) -> Dict[str, Any]:
        """Initialize performance baseline calculation."""
        return {
            'rolling_baseline': {'window': 1000, 'percentiles': [5, 25, 50, 75, 95]},
            'seasonal_baseline': {'period': 24, 'history_length': 168},  # Daily pattern over week
            'contextual_baseline': {'context_features': ['hour_of_day', 'day_of_week']},
            'adaptive_baseline': {'adaptation_rate': 0.01, 'sensitivity': 0.05}
        }
    
    def _initialize_alert_predictors(self) -> Dict[str, Any]:
        """Initialize ML models for predicting future alerts."""
        predictors = {}
        
        try:
            from sklearn.ensemble import RandomForestClassifier, GradientBoostingClassifier
            from sklearn.linear_model import LogisticRegression
            
            predictors.update({
                'random_forest': RandomForestClassifier(
                    n_estimators=100,
                    max_depth=10,
                    random_state=42
                ),
                'gradient_boosting': GradientBoostingClassifier(
                    n_estimators=50,
                    learning_rate=0.1,
                    random_state=42
                ),
                'logistic_regression': LogisticRegression(
                    random_state=42,
                    max_iter=1000
                )
            })
        except ImportError:
            self.logger.warning("Scikit-learn unavailable for alert prediction")
        
        # Statistical predictors (always available)
        predictors.update({
            'threshold_crossing_predictor': self._create_threshold_crossing_predictor(),
            'trend_extrapolation_predictor': self._create_trend_extrapolation_predictor()
        })
        
        return predictors
    
    def check_action_alerts(self, performance_data: Dict) -> Dict[str, Any]:
        """Comprehensive alert checking using multiple detection methods."""
        timestamp = datetime.now()
        
        # Add performance data to history
        enriched_data = {**performance_data, 'timestamp': timestamp}
        self.performance_history.append(enriched_data)
        
        # Update baselines periodically
        if len(self.performance_history) % self.baseline_update_frequency == 0:
            self._update_performance_baselines()
        
        alert_results = {
            'alerts': [],
            'alert_level': 'normal',
            'alert_scores': {},
            'detection_methods': {},
            'predictions': {},
            'recommendations': []
        }
        
        try:
            # 1. Anomaly-based alerts
            anomaly_alerts = self._detect_anomaly_alerts(enriched_data)
            alert_results['alerts'].extend(anomaly_alerts)
            
            # 2. Trend-based alerts
            trend_alerts = self._detect_trend_alerts(enriched_data)
            alert_results['alerts'].extend(trend_alerts)
            
            # 3. Threshold-based alerts
            threshold_alerts = self._detect_threshold_alerts(enriched_data)
            alert_results['alerts'].extend(threshold_alerts)
            
            # 4. Correlation-based alerts
            correlation_alerts = self._detect_correlation_alerts(enriched_data)
            alert_results['alerts'].extend(correlation_alerts)
            
            # 5. Predictive alerts
            predictive_alerts = self._detect_predictive_alerts(enriched_data)
            alert_results['alerts'].extend(predictive_alerts)
            
            # Consolidate and prioritize alerts
            consolidated_alerts = self._consolidate_alerts(alert_results['alerts'])
            alert_results['alerts'] = consolidated_alerts
            
            # Determine overall alert level
            alert_results['alert_level'] = self._determine_overall_alert_level(consolidated_alerts)
            
            # Generate alert scores
            alert_results['alert_scores'] = self._calculate_alert_scores(consolidated_alerts)
            
            # Add predictions for future alerts
            alert_results['predictions'] = self._predict_future_alerts(enriched_data)
            
            # Generate actionable recommendations
            alert_results['recommendations'] = self._generate_alert_recommendations(
                consolidated_alerts, alert_results['alert_scores']
            )
            
            # Update alert history
            alert_record = {
                'timestamp': timestamp,
                'performance_data': performance_data,
                'alerts': consolidated_alerts,
                'alert_level': alert_results['alert_level'],
                'alert_scores': alert_results['alert_scores']
            }
            self.alert_history.append(alert_record)
            
            # Update adaptive thresholds based on alert outcomes
            self._update_adaptive_thresholds(enriched_data, alert_results)
            
        except Exception as e:
            self.logger.error(f"Alert detection failed: {e}")
            alert_results['alerts'] = [{'type': 'system_error', 'level': 'warning', 'message': f'Alert system error: {str(e)}'}]
            alert_results['alert_level'] = 'warning'
        
        return alert_results
    
    def _detect_anomaly_alerts(self, enriched_data: Dict) -> List[Dict]:
        """Detect alerts using anomaly detection methods."""
        anomaly_alerts = []
        
        if len(self.performance_history) < 50:
            return anomaly_alerts
        
        # Extract numeric features for ML models
        numeric_data = [self._extract_numeric_features(data) for data in list(self.performance_history)[-100:]]
        current_features = self._extract_numeric_features(enriched_data)
        
        if not numeric_data or not current_features:
            return anomaly_alerts
        
        # Ensure consistent feature dimensions
        feature_dim = len(current_features)
        numeric_data = [features[:feature_dim] if len(features) >= feature_dim 
                       else features + [0] * (feature_dim - len(features)) 
                       for features in numeric_data]
        
        # Run anomaly detection models
        for detector_name, detector in self.anomaly_detectors.items():
            try:
                if detector_name in ['isolation_forest', 'one_class_svm', 'elliptic_envelope'] and hasattr(detector, 'fit'):
                    # Fit on recent data
                    detector.fit(numeric_data)
                    
                    # Score current data
                    anomaly_score = detector.decision_function([current_features])[0]
                    
                    # Convert to probability (model-specific)
                    if detector_name == 'isolation_forest':
                        anomaly_prob = max(0, (0.5 - anomaly_score) / 0.5)
                    else:
                        anomaly_prob = max(0, min(1, (0.5 - anomaly_score) / 1.0))
                    
                    if anomaly_prob > 0.7:
                        anomaly_alerts.append({
                            'type': 'performance_anomaly',
                            'detector': detector_name,
                            'level': 'critical' if anomaly_prob > 0.9 else 'warning',
                            'score': anomaly_prob,
                            'message': f'Performance anomaly detected by {detector_name} (score: {anomaly_prob:.3f})',
                            'timestamp': datetime.now(),
                            'features': current_features
                        })
                
                elif detector_name == 'local_outlier_factor' and hasattr(detector, 'fit_predict'):
                    # LOF requires different handling
                    extended_data = numeric_data + [current_features]
                    outlier_predictions = detector.fit_predict(extended_data)
                    
                    if outlier_predictions[-1] == -1:  # Current point is outlier
                        outlier_scores = detector.negative_outlier_factor_
                        current_score = abs(outlier_scores[-1])
                        normalized_score = min(1.0, current_score / 2.0)
                        
                        if normalized_score > 0.6:
                            anomaly_alerts.append({
                                'type': 'performance_outlier',
                                'detector': detector_name,
                                'level': 'warning' if normalized_score < 0.8 else 'critical',
                                'score': normalized_score,
                                'message': f'Performance outlier detected by LOF (score: {normalized_score:.3f})',
                                'timestamp': datetime.now(),
                                'features': current_features
                            })
                
                elif detector_name in ['z_score_detector', 'iqr_detector', 'modified_zscore_detector']:
                    # Statistical detectors
                    alert_result = self._apply_statistical_detector(detector_name, enriched_data)
                    if alert_result:
                        anomaly_alerts.append(alert_result)
                        
            except Exception as e:
                self.logger.debug(f"Anomaly detector {detector_name} failed: {e}")
        
        return anomaly_alerts
    
    def _detect_trend_alerts(self, enriched_data: Dict) -> List[Dict]:
        """Detect alerts based on performance trends."""
        trend_alerts = []
        
        if len(self.performance_history) < 20:
            return trend_alerts
        
        # Analyze trends for numeric metrics
        for key, value in enriched_data.items():
            if isinstance(value, (int, float)) and not key.startswith('timestamp'):
                recent_values = [
                    data.get(key) for data in list(self.performance_history)[-20:] 
                    if data.get(key) is not None and isinstance(data.get(key), (int, float))
                ]
                
                if len(recent_values) >= 10:
                    # Trend analysis using Mann-Kendall test
                    trend_result = self._mann_kendall_test(recent_values)
                    
                    if trend_result['significant'] and abs(trend_result['slope']) > 0.05:
                        trend_direction = 'declining' if trend_result['slope'] < 0 else 'increasing'
                        alert_level = 'warning' if abs(trend_result['slope']) < 0.1 else 'critical'
                        
                        trend_alerts.append({
                            'type': 'performance_trend',
                            'metric': key,
                            'trend_direction': trend_direction,
                            'level': alert_level,
                            'slope': trend_result['slope'],
                            'p_value': trend_result['p_value'],
                            'message': f'Significant {trend_direction} trend in {key} (slope: {trend_result["slope"]:.4f})',
                            'timestamp': datetime.now()
                        })
                    
                    # CUSUM-based change detection
                    cusum_result = self._cusum_change_detection(recent_values)
                    if cusum_result['change_detected']:
                        trend_alerts.append({
                            'type': 'performance_change',
                            'metric': key,
                            'level': 'warning',
                            'change_point': cusum_result['change_point'],
                            'message': f'Performance change detected in {key} at position {cusum_result["change_point"]}',
                            'timestamp': datetime.now()
                        })
        
        return trend_alerts
    
    def _detect_threshold_alerts(self, enriched_data: Dict) -> List[Dict]:
        """Detect alerts based on threshold violations."""
        threshold_alerts = []
        
        for key, value in enriched_data.items():
            if isinstance(value, (int, float)) and key in self.performance_baselines:
                baseline = self.performance_baselines[key]
                
                # Check against percentile thresholds
                if value < baseline['p5']:  # Below 5th percentile
                    threshold_alerts.append({
                        'type': 'threshold_violation',
                        'metric': key,
                        'level': 'critical',
                        'threshold_type': 'lower_bound',
                        'value': value,
                        'threshold': baseline['p5'],
                        'message': f'{key} value {value:.3f} below critical threshold {baseline["p5"]:.3f}',
                        'timestamp': datetime.now()
                    })
                elif value > baseline['p95']:  # Above 95th percentile
                    threshold_alerts.append({
                        'type': 'threshold_violation',
                        'metric': key,
                        'level': 'warning',
                        'threshold_type': 'upper_bound', 
                        'value': value,
                        'threshold': baseline['p95'],
                        'message': f'{key} value {value:.3f} above warning threshold {baseline["p95"]:.3f}',
                        'timestamp': datetime.now()
                    })
        
        return threshold_alerts
    
    def _detect_correlation_alerts(self, enriched_data: Dict) -> List[Dict]:
        """Detect alerts based on correlation breakdowns."""
        correlation_alerts = []
        
        if len(self.performance_history) < 50:
            return correlation_alerts
        
        # Check for correlation breakdowns between metrics
        numeric_metrics = [k for k, v in enriched_data.items() if isinstance(v, (int, float))]
        
        for i, metric1 in enumerate(numeric_metrics):
            for metric2 in numeric_metrics[i+1:]:
                correlation_key = f'{metric1}_vs_{metric2}'
                
                if correlation_key in self.alert_correlations:
                    recent_data = list(self.performance_history)[-30:]
                    values1 = [d.get(metric1) for d in recent_data if d.get(metric1) is not None]
                    values2 = [d.get(metric2) for d in recent_data if d.get(metric2) is not None]
                    
                    if len(values1) >= 20 and len(values2) >= 20:
                        min_len = min(len(values1), len(values2))
                        current_corr = np.corrcoef(values1[-min_len:], values2[-min_len:])[0, 1]
                        expected_corr = self.alert_correlations[correlation_key]['expected']
                        
                        if not np.isnan(current_corr) and abs(current_corr - expected_corr) > 0.5:
                            correlation_alerts.append({
                                'type': 'correlation_breakdown',
                                'metrics': [metric1, metric2],
                                'level': 'warning',
                                'current_correlation': current_corr,
                                'expected_correlation': expected_corr,
                                'message': f'Correlation breakdown between {metric1} and {metric2}',
                                'timestamp': datetime.now()
                            })
        
        return correlation_alerts
    
    def _detect_predictive_alerts(self, enriched_data: Dict) -> List[Dict]:
        """Detect alerts using predictive models."""
        predictive_alerts = []
        
        if len(self.alert_history) < 100:
            return predictive_alerts
        
        try:
            # Prepare features for prediction
            feature_window = 10
            if len(self.performance_history) >= feature_window:
                recent_features = [
                    self._extract_numeric_features(data) 
                    for data in list(self.performance_history)[-feature_window:]
                ]
                
                # Flatten features for prediction
                flattened_features = []
                for features in recent_features:
                    flattened_features.extend(features[:5])  # Limit to 5 features per time step
                
                if len(flattened_features) == feature_window * 5:  # Consistent feature size
                    # Predict likelihood of future alerts
                    for predictor_name, predictor in self.alert_predictors.items():
                        if hasattr(predictor, 'predict_proba') and len(self.alert_history) >= 200:
                            try:
                                # This would require training the predictor on historical data
                                # For now, use a simplified threshold-based approach
                                alert_probability = self._calculate_alert_probability(flattened_features)
                                
                                if alert_probability > 0.6:
                                    predictive_alerts.append({
                                        'type': 'predicted_alert',
                                        'predictor': predictor_name,
                                        'level': 'info',
                                        'probability': alert_probability,
                                        'message': f'High probability ({alert_probability:.2f}) of future performance issues',
                                        'timestamp': datetime.now(),
                                        'prediction_horizon': '10 minutes'
                                    })
                            except Exception as e:
                                self.logger.debug(f"Predictive alert from {predictor_name} failed: {e}")
                                
        except Exception as e:
            self.logger.debug(f"Predictive alert detection failed: {e}")
        
        return predictive_alerts
    
    # Helper methods for alert processing
    def _extract_numeric_features(self, data: Dict) -> List[float]:
        """Extract numeric features from performance data."""
        features = []
        for key, value in data.items():
            if isinstance(value, (int, float)) and not key.startswith('timestamp'):
                features.append(float(value))
        return features[:10]  # Limit to first 10 numeric features
    
    def _consolidate_alerts(self, alerts: List[Dict]) -> List[Dict]:
        """Consolidate and deduplicate similar alerts."""
        if not alerts:
            return alerts
        
        consolidated = []
        alert_groups = {}
        
        # Group similar alerts
        for alert in alerts:
            key = f"{alert['type']}_{alert.get('metric', '')}"
            if key not in alert_groups:
                alert_groups[key] = []
            alert_groups[key].append(alert)
        
        # Consolidate each group
        for group_key, group_alerts in alert_groups.items():
            if len(group_alerts) == 1:
                consolidated.extend(group_alerts)
            else:
                # Merge similar alerts
                merged_alert = group_alerts[0].copy()
                merged_alert['count'] = len(group_alerts)
                merged_alert['message'] += f' (and {len(group_alerts)-1} similar alerts)'
                consolidated.append(merged_alert)
        
        return consolidated
    
    def _determine_overall_alert_level(self, alerts: List[Dict]) -> str:
        """Determine overall alert level from individual alerts."""
        if not alerts:
            return 'normal'
        
        level_priorities = {'info': 1, 'warning': 2, 'critical': 3, 'emergency': 4}
        max_priority = max(level_priorities.get(alert['level'], 0) for alert in alerts)
        
        for level, priority in level_priorities.items():
            if priority == max_priority:
                return level
        
        return 'normal'
    
    def _calculate_alert_scores(self, alerts: List[Dict]) -> Dict[str, float]:
        """Calculate composite alert scores."""
        scores = {}
        
        for alert in alerts:
            alert_type = alert['type']
            score = alert.get('score', 0.5)
            
            if alert_type not in scores:
                scores[alert_type] = score
            else:
                scores[alert_type] = max(scores[alert_type], score)
        
        return scores
    
    def _predict_future_alerts(self, enriched_data: Dict) -> Dict[str, Any]:
        """Predict future alert likelihood."""
        return {
            'next_1min': 0.1,
            'next_5min': 0.2,
            'next_10min': 0.15,
            'confidence': 0.6
        }
    
    def _generate_alert_recommendations(self, alerts: List[Dict], alert_scores: Dict) -> List[str]:
        """Generate actionable recommendations based on alerts."""
        recommendations = []
        
        for alert in alerts:
            alert_type = alert['type']
            
            if alert_type == 'performance_anomaly':
                recommendations.append("Investigate recent changes in system configuration or data inputs")
            elif alert_type == 'performance_trend':
                if alert.get('trend_direction') == 'declining':
                    recommendations.append("Consider scaling resources or optimizing performance bottlenecks")
            elif alert_type == 'threshold_violation':
                recommendations.append(f"Review {alert.get('metric', 'metric')} thresholds and system capacity")
            elif alert_type == 'correlation_breakdown':
                recommendations.append("Check for system integration issues or data pipeline problems")
        
        return list(set(recommendations))  # Remove duplicates
    
    def _update_adaptive_thresholds(self, enriched_data: Dict, alert_results: Dict):
        """Update adaptive thresholds based on alert outcomes."""
        # Simplified adaptive threshold update
        for key, value in enriched_data.items():
            if isinstance(value, (int, float)):
                if key not in self.adaptive_thresholds:
                    self.adaptive_thresholds[key] = {'mean': value, 'std': 0.0, 'count': 1}
                else:
                    # Update using exponential moving average
                    alpha = 0.01
                    old_mean = self.adaptive_thresholds[key]['mean']
                    new_mean = alpha * value + (1 - alpha) * old_mean
                    self.adaptive_thresholds[key]['mean'] = new_mean
                    
                    # Update standard deviation estimate
                    self.adaptive_thresholds[key]['std'] = alpha * abs(value - new_mean) + (1 - alpha) * self.adaptive_thresholds[key]['std']
                    self.adaptive_thresholds[key]['count'] += 1
    
    def _update_performance_baselines(self):
        """Update performance baselines from historical data."""
        if len(self.performance_history) < 100:
            return
        
        recent_data = list(self.performance_history)[-1000:]  # Last 1000 samples
        
        for key in recent_data[0].keys():
            if key != 'timestamp':
                values = [data.get(key) for data in recent_data if data.get(key) is not None and isinstance(data.get(key), (int, float))]
                
                if len(values) >= 100:
                    self.performance_baselines[key] = {
                        'p5': np.percentile(values, 5),
                        'p25': np.percentile(values, 25),
                        'p50': np.percentile(values, 50),
                        'p75': np.percentile(values, 75),
                        'p95': np.percentile(values, 95),
                        'mean': np.mean(values),
                        'std': np.std(values),
                        'updated': datetime.now()
                    }
    
    # Statistical test implementations
    def _mann_kendall_test(self, data: List[float]) -> Dict[str, Any]:
        """Perform Mann-Kendall trend test."""
        from scipy.stats import kendalltau
        
        n = len(data)
        time_indices = list(range(n))
        
        tau, p_value = kendalltau(time_indices, data)
        
        return {
            'tau': tau,
            'p_value': p_value,
            'significant': p_value < 0.05,
            'slope': tau * np.std(data) / np.std(time_indices) if np.std(time_indices) > 0 else 0
        }
    
    def _cusum_change_detection(self, data: List[float]) -> Dict[str, Any]:
        """CUSUM-based change point detection."""
        if len(data) < 10:
            return {'change_detected': False}
        
        mean_val = np.mean(data)
        std_val = np.std(data)
        
        if std_val == 0:
            return {'change_detected': False}
        
        # CUSUM parameters
        threshold = 3 * std_val
        drift = 0.5 * std_val
        
        cusum_pos = 0
        cusum_neg = 0
        change_point = None
        
        for i, value in enumerate(data):
            cusum_pos = max(0, cusum_pos + (value - mean_val - drift))
            cusum_neg = max(0, cusum_neg - (value - mean_val + drift))
            
            if cusum_pos > threshold or cusum_neg > threshold:
                change_point = i
                break
        
        return {
            'change_detected': change_point is not None,
            'change_point': change_point,
            'cusum_positive': cusum_pos,
            'cusum_negative': cusum_neg
        }
    
    def _calculate_alert_probability(self, features: List[float]) -> float:
        """Calculate probability of alert based on features."""
        # Simplified alert probability calculation
        feature_score = sum(abs(f) for f in features) / len(features) if features else 0
        return min(1.0, feature_score / 10.0)  # Normalize to [0,1]
    
    def _apply_statistical_detector(self, detector_name: str, data: Dict) -> Optional[Dict]:
        """Apply statistical anomaly detector."""
        # Simplified statistical detection
        if detector_name == 'z_score_detector':
            for key, value in data.items():
                if isinstance(value, (int, float)) and key in self.adaptive_thresholds:
                    mean = self.adaptive_thresholds[key]['mean']
                    std = self.adaptive_thresholds[key]['std']
                    if std > 0:
                        z_score = abs(value - mean) / std
                        if z_score > 3:
                            return {
                                'type': 'statistical_anomaly',
                                'detector': detector_name,
                                'metric': key,
                                'level': 'warning',
                                'z_score': z_score,
                                'message': f'High z-score ({z_score:.2f}) for {key}',
                                'timestamp': datetime.now()
                            }
        
        return None
    
