    def _generate_geological_domain_salt(self, geological_context: Dict[str, Any]) -> bytes:
        """Generate domain-specific cryptographic salt from geological context."""
        domain_features = [
            geological_context.get('volcano_type', 'unknown'),
            geological_context.get('tectonic_setting', 'unknown'),
            geological_context.get('latitude_zone', 'unknown'),
            geological_context.get('elevation_zone', 'unknown')
        ]
        return hashlib.blake2b(''.join(domain_features).encode(), digest_size=16).digest()
    
    def _compute_graph_embedding(self, causal_graph, embedding_dim: int = 256, method: str = 'GraphSAGE'):
        """Compute advanced graph embeddings using neural network methods."""
        if method == 'GraphSAGE':
            return GraphSAGEEmbedder(embedding_dim).embed_causal_graph(causal_graph)
        elif method == 'GraphAttention':
            return GraphAttentionEmbedder(embedding_dim).embed_causal_graph(causal_graph)
        else:
            return Node2VecEmbedder(embedding_dim).embed_causal_graph(causal_graph)
    
