    async def _get_causal_information_data(self, experience_id: str) -> Dict[str, Any]:
        """Retrieve causal relationship data from causal inference database."""
        try:
            causal_data = {}
            
            if self.db_manager:
                # Query causal relationships and strength metrics
                query = """
                    SELECT 
                        causal_strength,
                        causal_confidence,
                        array_agg(DISTINCT variable_name) as causal_variables,
                        array_agg(DISTINCT mechanism) as causal_mechanisms,
                        intervention_type,
                        effect_size,
                        p_value,
                        confidence_interval_lower,
                        confidence_interval_upper
                    FROM causal_relationships cr
                    LEFT JOIN causal_variables cv ON cr.id = cv.relationship_id
                    WHERE cr.experience_id = $1
                    GROUP BY cr.causal_strength, cr.causal_confidence, cr.intervention_type,
                             cr.effect_size, cr.p_value, cr.confidence_interval_lower,
                             cr.confidence_interval_upper
                """
                
                result = await self.db_manager.execute_query(query, [experience_id])
                
                if result:
                    row = result[0]
                    causal_data = {
                        'causal_strength': row.get('causal_strength', 0.0),
                        'causal_confidence': row.get('causal_confidence', 0.0),
                        'causal_variables': row.get('causal_variables', []) or [],
                        'causal_mechanisms': row.get('causal_mechanisms', []) or [],
                        'intervention_effects': {
                            'type': row.get('intervention_type', ''),
                            'effect_size': row.get('effect_size', 0.0),
                            'p_value': row.get('p_value', 1.0),
                            'confidence_interval': [
                                row.get('confidence_interval_lower', 0.0),
                                row.get('confidence_interval_upper', 0.0)
                            ]
                        }
                    }
                    
            return causal_data
            
        except Exception as e:
            logging.warning(f"Failed to retrieve causal information for {experience_id}: {e}")
            return {}
    
    async def _get_sample_and_geochemical_data(self, experience_id: str) -> Dict[str, Any]:
        """Retrieve sample locations and geochemical analysis data."""
        try:
            sample_data = {'locations': [], 'geochemistry': {}}
            
            if self.db_manager:
                # Query sample locations
                location_query = """
                    SELECT 
                        sample_id,
                        ST_X(location) as longitude,
                        ST_Y(location) as latitude,
                        elevation,
                        sample_type,
                        collection_date
                    FROM sample_locations
                    WHERE experience_id = $1
                """
                
                locations = await self.db_manager.execute_query(location_query, [experience_id])
                
                if locations:
                    sample_data['locations'] = [
                        {
                            'sample_id': loc['sample_id'],
                            'latitude': loc['latitude'],
                            'longitude': loc['longitude'],
                            'elevation': loc['elevation'],
                            'sample_type': loc['sample_type'],
                            'collection_date': loc['collection_date']
                        }
                        for loc in locations
                    ]
                    
                # Query geochemical data
                geochem_query = """
                    SELECT 
                        element,
                        concentration,
                        unit,
                        analytical_method,
                        detection_limit,
                        uncertainty
                    FROM geochemical_analyses
                    WHERE experience_id = $1
                """
                
                geochem_results = await self.db_manager.execute_query(geochem_query, [experience_id])
                
                if geochem_results:
                    elements = {}
                    for result in geochem_results:
                        element = result['element']
                        elements[element] = {
                            'concentration': result['concentration'],
                            'unit': result['unit'],
                            'method': result['analytical_method'],
                            'detection_limit': result['detection_limit'],
                            'uncertainty': result['uncertainty']
                        }
                    sample_data['geochemistry'] = elements
                    
            return sample_data
            
        except Exception as e:
            logging.warning(f"Failed to retrieve sample/geochemical data for {experience_id}: {e}")
            return {'locations': [], 'geochemistry': {}}
    
    async def _get_geological_process_data(self, experience_id: str) -> Dict[str, Any]:
        """Retrieve geological process and environmental condition data."""
        try:
            process_data = {'processes': [], 'environment': {}}
            
            if self.db_manager:
                # Query geological processes
                process_query = """
                    SELECT 
                        process_name,
                        process_type,
                        characteristic_timescale_ma,
                        spatial_scale_km,
                        intensity,
                        environmental_conditions
                    FROM geological_processes
                    WHERE experience_id = $1
                """
                
                processes = await self.db_manager.execute_query(process_query, [experience_id])
                
                if processes:
                    process_data['processes'] = [
                        {
                            'name': proc['process_name'],
                            'type': proc['process_type'],
                            'characteristic_timescale_ma': proc['characteristic_timescale_ma'],
                            'spatial_scale_km': proc['spatial_scale_km'],
                            'intensity': proc['intensity']
                        }
                        for proc in processes
                    ]
                    
                    # Aggregate environmental conditions
                    env_conditions = {}
                    for proc in processes:
                        if proc.get('environmental_conditions'):
                            env_conditions.update(proc['environmental_conditions'])
                    process_data['environment'] = env_conditions
                    
            return process_data
            
        except Exception as e:
            logging.warning(f"Failed to retrieve geological process data for {experience_id}: {e}")
            return {'processes': [], 'environment': {}}
    
    async def _get_experience_metadata(self, experience_id: str) -> Dict[str, Any]:
        """Retrieve experience metadata and descriptions."""
        try:
            metadata = {}
            
            if self.model_db:
                # Query experience metadata
                metadata_record = await self.model_db.get_experience_metadata(experience_id)
                
                if metadata_record:
                    metadata = {
                        'description': metadata_record.get('description', ''),
                        'collection_date': metadata_record.get('collection_date'),
                        'type': metadata_record.get('experience_type', 'unknown'),
                        'author': metadata_record.get('author', ''),
                        'institution': metadata_record.get('institution', ''),
                        'doi': metadata_record.get('doi'),
                        'keywords': metadata_record.get('keywords', []),
                        'processing_history': metadata_record.get('processing_history', [])
                    }
                    
            return metadata
            
        except Exception as e:
            logging.warning(f"Failed to retrieve metadata for {experience_id}: {e}")
            return {}
    
    def _validate_experience_completeness(self, experience_data: Dict[str, Any]) -> bool:
        """Validate that retrieved experience data meets minimum completeness requirements."""
        try:
            # Check essential fields
            essential_fields = [
                'geological_context',
                'spatial_extent', 
                'temporal_information',
                'quality_score'
            ]
            
            for field in essential_fields:
                if field not in experience_data or not experience_data[field]:
                    return False
                    
            # Check geological context completeness
            geo_context = experience_data.get('geological_context', {})
            if not geo_context.get('age_ma') and not geo_context.get('lithologies'):
                return False
                
            # Check spatial extent completeness
            spatial = experience_data.get('spatial_extent', {})
            if not spatial.get('latitude') and not spatial.get('longitude'):
                return False
                
            return True
            
        except Exception:
            return False
    
    async def _reconstruct_experience_from_attributes(self, existing_attrs: Dict) -> Dict[str, Any]:
        """Fallback method to reconstruct experience from node attributes when database fails."""
        return {
            'id': existing_attrs.get('id', ''),
            'geological_context': {
                'age_ma': existing_attrs.get('geological_age', 0),
                'lithologies': existing_attrs.get('lithologies', []),
                'complexity_score': existing_attrs.get('complexity_score', 0.0)
            },
            'spatial_extent': existing_attrs.get('spatial_location', {}),
            'temporal_information': {
                'duration_ma': existing_attrs.get('duration_ma', 0),
                'temporal_resolution_ma': existing_attrs.get('temporal_resolution', 1.0)
            },
            'quality_score': existing_attrs.get('quality_score', 0.5),
            'causal_information': {
                'causal_strength': existing_attrs.get('causal_strength', 0.0),
                'causal_confidence': existing_attrs.get('causal_confidence', 0.0)
            },
            'type': existing_attrs.get('experience_type', 'unknown'),
            'methods': existing_attrs.get('methods', {}),
            'environmental_conditions': existing_attrs.get('environmental_conditions', {}),
            'sample_locations': existing_attrs.get('sample_locations', []),
            'geochemical_data': existing_attrs.get('geochemical_data', {}),
            'geological_processes': existing_attrs.get('geological_processes', []),
            'description': existing_attrs.get('description', '')
        }

