    def _initialize_ml_property_predictor(self):
        """Initialize ML-based rock property prediction system"""
        
        class PropertyPredictor(nn.Module):
            def __init__(self, input_features=10, hidden_dim=256, output_features=30):
                super().__init__()
                self.encoder = nn.Sequential(
                    nn.Linear(input_features, hidden_dim),
                    nn.ReLU(),
                    nn.BatchNorm1d(hidden_dim),
                    nn.Dropout(0.2),
                    nn.Linear(hidden_dim, hidden_dim * 2),
                    nn.ReLU(),
                    nn.BatchNorm1d(hidden_dim * 2),
                    nn.Dropout(0.2),
                    nn.Linear(hidden_dim * 2, hidden_dim),
                    nn.ReLU(),
                    nn.BatchNorm1d(hidden_dim)
                )
                
                # Separate heads for different property types
                self.mechanical_head = nn.Linear(hidden_dim, 15)
                self.thermal_head = nn.Linear(hidden_dim, 5)
                self.dynamic_head = nn.Linear(hidden_dim, 10)
                
            def forward(self, x):
                features = self.encoder(x)
                mechanical = self.mechanical_head(features)
                thermal = self.thermal_head(features)
                dynamic = self.dynamic_head(features)
                return mechanical, thermal, dynamic
        
        self.property_predictor_model = PropertyPredictor()
        
        # Load pre-trained weights if available
        model_path = os.path.join(os.environ.get('MODEL_PATH', './models'), 
                                 'rock_property_predictor.pth')
        if os.path.exists(model_path):
            self.property_predictor_model.load_state_dict(torch.load(model_path))
            self.logger.info("Loaded pre-trained rock property predictor")
        else:
            self.logger.info("Initialized new rock property predictor")
    
