    async def _load_comprehensive_rock_database(self) -> Dict[str, Dict]:
        """Load comprehensive rock properties from multiple integrated sources"""
        try:
            rock_properties = {}
            
            # 1. Query PostgreSQL geological database
            database_properties = await self._query_geological_database()
            rock_properties.update(database_properties)
            
            # 2. Integrate USGS mineral resources data
            usgs_properties = await self._integrate_usgs_mineral_data()
            rock_properties = self._merge_rock_properties(rock_properties, usgs_properties)
            
            # 3. ML-based property prediction for missing data
            ml_predictions = await self._predict_missing_properties(rock_properties)
            rock_properties = self._merge_rock_properties(rock_properties, ml_predictions)
            
            # 4. Real-time geochemical analysis integration
            geochemical_props = await self._integrate_geochemical_analysis()
            rock_properties = self._merge_rock_properties(rock_properties, geochemical_props)
            
            # 5. Literature database integration with confidence weighting
            literature_props = await self._integrate_literature_database()
            rock_properties = self._merge_rock_properties(rock_properties, literature_props)
            
            # 6. Apply uncertainty quantification to all properties
            rock_properties = await self._apply_uncertainty_quantification(rock_properties)
            
            return rock_properties
            
        except Exception as e:
            self.logger.error(f"Comprehensive database loading failed: {e}")
            return await self._load_fallback_comprehensive_properties()
    
    async def _query_geological_database(self) -> Dict[str, Dict]:
        """Query comprehensive geological database for rock properties"""
        try:
            query = """
            SELECT DISTINCT
                rmp.lithology,
                rmp.ucs_mpa * 1e6 as ucs,
                rmp.tensile_strength_mpa * 1e6 as tensile_strength,
                rmp.cohesion_mpa * 1e6 as cohesion,
                rmp.friction_angle_degrees as friction_angle,
                rmp.elastic_modulus_gpa * 1e9 as elastic_modulus,
                rmp.poisson_ratio,
                rmp.bulk_modulus_gpa * 1e9 as bulk_modulus,
                rmp.shear_modulus_gpa * 1e9 as shear_modulus,
                rmp.density_kg_m3 as density,
                rmp.porosity_fraction,
                rmp.permeability_m2,
                gf.age_ma,
                gf.structural_setting,
                gf.alteration_grade,
                ST_X(gf.location::geometry) as longitude,
                ST_Y(gf.location::geometry) as latitude,
                ST_Z(gf.location::geometry) as depth_m,
                rmp.confidence_level,
                rmp.quality_index
            FROM rock_mechanical_properties rmp
            LEFT JOIN geological_formations gf ON rmp.formation_id = gf.formation_id
            WHERE rmp.quality_index >= 0.7
            AND rmp.confidence_level >= 0.8
            ORDER BY rmp.quality_index DESC, rmp.confidence_level DESC;
            """
            
            async with self.db_manager.get_async_session() as session:
                result = await session.execute(query)
                rows = result.fetchall()
                
                rock_properties = {}
                for row in rows:
                    lithology = row['lithology'].lower()
                    if lithology not in rock_properties:
                        rock_properties[lithology] = {
                            'mechanical': {},
                            'thermal': {},
                            'geochemical': {},
                            'metadata': {}
                        }
                    
                    # Mechanical properties with uncertainty bounds
                    rock_properties[lithology]['mechanical'].update({
                        'ucs': float(row['ucs']) if row['ucs'] else None,
                        'tensile_strength': float(row['tensile_strength']) if row['tensile_strength'] else None,
                        'cohesion': float(row['cohesion']) if row['cohesion'] else None,
                        'friction_angle': float(row['friction_angle']) if row['friction_angle'] else None,
                        'elastic_modulus': float(row['elastic_modulus']) if row['elastic_modulus'] else None,
                        'poisson_ratio': float(row['poisson_ratio']) if row['poisson_ratio'] else None,
                        'bulk_modulus': float(row['bulk_modulus']) if row['bulk_modulus'] else None,
                        'shear_modulus': float(row['shear_modulus']) if row['shear_modulus'] else None,
                        'density': float(row['density']) if row['density'] else None,
                        'porosity': float(row['porosity_fraction']) if row['porosity_fraction'] else None,
                        'permeability': float(row['permeability_m2']) if row['permeability_m2'] else None
                    })
                    
                    # Metadata for contextual analysis
                    rock_properties[lithology]['metadata'].update({
                        'geological_age_ma': float(row['age_ma']) if row['age_ma'] else None,
                        'structural_setting': row['structural_setting'],
                        'alteration_grade': row['alteration_grade'],
                        'location': [row['latitude'], row['longitude'], row['depth_m']] if all([row['latitude'], row['longitude']]) else None,
                        'confidence_level': float(row['confidence_level']),
                        'quality_index': float(row['quality_index']),
                        'data_source': 'prometheus_geological_database'
                    })
                
                return rock_properties
                
        except Exception as e:
            self.logger.error(f"Database query failed: {e}")
            return {}
    
    async def _integrate_usgs_mineral_data(self) -> Dict[str, Dict]:
        """Integrate USGS mineral resources and geological data"""
        try:
            # Query USGS mineral resources database
            mineral_data = await self.usgs_connector.get_mineral_resources_data(
                bbox=(-180, -90, 180, 90),  # Global coverage
                commodity_types=['granite', 'basalt', 'andesite', 'rhyolite', 'dacite'],
                include_properties=['mechanical', 'physical', 'geochemical']
            )
            
            rock_properties = {}
            for record in mineral_data:
                rock_type = record.properties.get('lithology', '').lower()
                if rock_type:
                    if rock_type not in rock_properties:
                        rock_properties[rock_type] = {'mechanical': {}, 'metadata': {}}
                    
                    # Extract USGS mechanical properties
                    usgs_props = record.properties.get('mechanical_properties', {})
                    rock_properties[rock_type]['mechanical'].update({
                        'ucs': usgs_props.get('compressive_strength_psi', 0) * 6894.76,  # Convert PSI to Pa
                        'tensile_strength': usgs_props.get('tensile_strength_psi', 0) * 6894.76,
                        'elastic_modulus': usgs_props.get('elastic_modulus_psi', 0) * 6894.76,
                        'density': usgs_props.get('specific_gravity', 2.65) * 1000  # Convert to kg/m³
                    })
                    
                    rock_properties[rock_type]['metadata'].update({
                        'usgs_commodity_code': record.properties.get('commodity_code'),
                        'data_source': 'usgs_mineral_resources',
                        'usgs_confidence': record.quality_score
                    })
            
            return rock_properties
            
        except Exception as e:
            self.logger.error(f"USGS integration failed: {e}")
            return {}
    
    async def _predict_missing_properties(self, existing_properties: Dict) -> Dict[str, Dict]:
        """Use ML models to predict missing rock properties"""
        try:
            if not hasattr(self, 'model_manager') or not self.model_manager:
                return {}
            
            # Load pre-trained rock property prediction models
            property_models = await self.model_manager.load_models([
                'rock_property_predictor_v2.3',
                'geomechanical_ensemble_v1.8',
                'uncertainty_quantifier_v1.5'
            ])
            
            enhanced_properties = {}
            
            for rock_type, props in existing_properties.items():
                try:
                    # Prepare feature vector for ML prediction
                    features = self._extract_ml_features(rock_type, props)
                    
                    # Predict missing mechanical properties
                    predicted_props = await property_models['rock_property_predictor_v2.3'].predict(
                        features, uncertainty_estimation=True
                    )
                    
                    # Ensemble prediction for validation
                    ensemble_props = await property_models['geomechanical_ensemble_v1.8'].predict(
                        features, return_confidence=True
                    )
                    
                    # Combine predictions with uncertainty quantification
                    combined_props = self._combine_ml_predictions(
                        predicted_props, ensemble_props, existing_props=props
                    )
                    
                    enhanced_properties[rock_type] = combined_props
                    
                except Exception as e:
                    self.logger.warning(f"ML prediction failed for {rock_type}: {e}")
                    enhanced_properties[rock_type] = props
            
            return enhanced_properties
            
        except Exception as e:
            self.logger.error(f"ML property prediction failed: {e}")
            return existing_properties
    
