    def _apply_environmental_corrections(self, slip_systems):
        """Apply real-time temperature and pressure corrections to slip systems"""
        try:
            corrected_systems = []
            context = self.current_geological_context
            
            temperature = context.get('temperature', 298.15)
            pressure = context.get('pressure', 1e5)
            
            for system in slip_systems:
                corrected_system = system.copy()
                
                # Temperature correction for activation stress
                if 'activation_energy' in system:
                    temp_factor = np.exp(
                        system['activation_energy'] / (8.314 * temperature) - 
                        system['activation_energy'] / (8.314 * 298.15)
                    )
                    corrected_system['activation_stress'] *= temp_factor
                
                # Pressure correction
                if 'activation_volume' in system:
                    pressure_factor = np.exp(
                        system['activation_volume'] * pressure / (8.314 * temperature)
                    )
                    corrected_system['activation_stress'] *= pressure_factor
                
                corrected_systems.append(corrected_system)
            
            return corrected_systems
            
        except Exception as e:
            self.logger.warning(f"Environmental corrections failed: {e}")
            return slip_systems
    
