    def _query_cod_slip_systems(self, mineral):
        """Query Crystallography Open Database for slip systems with comprehensive analysis"""
        try:
            import requests
            
            # COD API endpoint
            base_url = "http://www.crystallography.net/cod/search"
            
            # Search parameters for multiple crystal structure variants
            mineral_variants = {
                'quartz': ['quartz', 'SiO2', 'alpha-quartz', 'beta-quartz'],
                'olivine': ['olivine', 'forsterite', 'fayalite', 'Mg2SiO4', 'Fe2SiO4'],
                'feldspar': ['feldspar', 'plagioclase', 'orthoclase', 'albite', 'anorthite'],
                'pyroxene': ['pyroxene', 'diopside', 'augite', 'enstatite', 'CaMgSi2O6'],
                'calcite': ['calcite', 'CaCO3'],
                'mica': ['mica', 'muscovite', 'biotite', 'phlogopite']
            }
            
            search_terms = mineral_variants.get(mineral.lower(), [mineral])
            all_slip_systems = []
            
            for term in search_terms:
                params = {
                    'text': term,
                    'format': 'json',
                    'limit': 10  # Limit results per search
                }
                
                try:
                    response = requests.get(base_url, params=params, timeout=15)
                    
                    if response.status_code == 200:
                        cod_data = response.json()
                        parsed_systems = self._parse_cod_slip_systems(cod_data, mineral)
                        if parsed_systems:
                            all_slip_systems.extend(parsed_systems)
                            
                except requests.RequestException as e:
                    self.logger.debug(f"COD query for {term} failed: {e}")
                    continue
                    
            # Remove duplicates and return unique slip systems
            unique_systems = self._deduplicate_slip_systems(all_slip_systems)
            
            if unique_systems:
                self.logger.info(f"Retrieved {len(unique_systems)} unique slip systems from COD for {mineral}")
                return unique_systems
                
            return None
                
        except Exception as e:
            self.logger.warning(f"COD database query failed: {e}")
            
        return None
    
    def _parse_cod_slip_systems(self, cod_data, mineral):
        """Parse COD database response to extract slip system information"""
        try:
            if not cod_data or 'data' not in cod_data:
                return None
                
            slip_systems = []
            
            for entry in cod_data['data'][:5]:  # Limit to first 5 entries
                if 'crystal_system' in entry and 'space_group' in entry:
                    crystal_system = entry['crystal_system'].lower()
                    space_group = entry.get('space_group', '')
                    
                    # Extract lattice parameters
                    a = entry.get('a', 5.0)
                    b = entry.get('b', 5.0) 
                    c = entry.get('c', 5.0)
                    
                    # Generate likely slip systems based on crystal system
                    if crystal_system == 'hexagonal':
                        slip_systems.append({
                            'name': f'cod_basal_{entry.get("cod_id", "unknown")}',
                            'plane': [0,0,0,1], 'direction': [2,-1,-1,0],
                            'miller_notation': '(0001)<11-20>',
                            'crystal_system': 'hexagonal',
                            'activation_stress': 120e6,  # Typical estimate
                            'c_over_a_ratio': c / a if a > 0 else 1.6,
                            'source': 'COD',
                            'cod_id': entry.get('cod_id'),
                            'space_group': space_group
                        })
                    
                    elif crystal_system == 'orthorhombic':
                        slip_systems.append({
                            'name': f'cod_010_100_{entry.get("cod_id", "unknown")}',
                            'plane': [0,1,0], 'direction': [1,0,0],
                            'miller_notation': '(010)[100]',
                            'crystal_system': 'orthorhombic',
                            'activation_stress': 80e6,
                            'lattice_ratios': {'b_over_a': b/a if a > 0 else 1.0, 'c_over_a': c/a if a > 0 else 1.0},
                            'source': 'COD',
                            'cod_id': entry.get('cod_id'),
                            'space_group': space_group
                        })
                        
            return slip_systems if slip_systems else None
            
        except Exception as e:
            self.logger.warning(f"COD data parsing failed: {e}")
            return None
    
    def _deduplicate_slip_systems(self, slip_systems):
        """Remove duplicate slip systems based on Miller notation and crystal system"""
        try:
            unique_systems = []
            seen_signatures = set()
            
            for system in slip_systems:
                # Create signature based on Miller notation and crystal system
                signature = (
                    system.get('miller_notation', ''),
                    system.get('crystal_system', ''),
                    tuple(system.get('plane', [])),
                    tuple(system.get('direction', []))
                )
                
                if signature not in seen_signatures:
                    seen_signatures.add(signature)
                    unique_systems.append(system)
            
            return unique_systems
            
        except Exception as e:
            self.logger.warning(f"Slip system deduplication failed: {e}")
            return slip_systems
    
    def _calculate_texture_evolution(self, slip_system_activity, strain_history, **kwargs):
        """Calculate texture evolution using Orientation Distribution Functions (ODFs)"""
        try:
            # Initialize texture parameters
            initial_texture_strength = kwargs.get('initial_texture_strength', 1.0)
            temperature = kwargs.get('temperature', 298.15)
            strain_rate = kwargs.get('strain_rate', 1e-15)
            
            # Calculate texture development based on slip system activity
            texture_components = {}
            
            for system_name, activity in slip_system_activity.items():
                if activity > 0.1:  # Only consider active slip systems
                    # Calculate texture component strength
                    component_strength = self._calculate_texture_component_strength(
                        system_name, activity, strain_history, temperature
                    )
                    
                    # Calculate orientation matrix for this slip system
                    orientation_matrix = self._get_slip_system_orientation_matrix(system_name)
                    
                    texture_components[system_name] = {
                        'strength': component_strength,
                        'orientation_matrix': orientation_matrix,
                        'volume_fraction': activity / sum(slip_system_activity.values())
                    }
            
            # Calculate overall fabric tensor from texture components
            fabric_tensor = self._calculate_fabric_tensor(texture_components)
            
            # Calculate texture index (J-index)
            texture_index = self._calculate_texture_index(texture_components)
            
            return {
                'texture_components': texture_components,
                'fabric_tensor': fabric_tensor,
                'texture_index': texture_index,
                'texture_strength': initial_texture_strength * (1.0 + 0.1 * np.log(1.0 + sum(strain_history))),
                'dominant_orientation': self._get_dominant_texture_orientation(texture_components)
            }
            
        except Exception as e:
            self.logger.warning(f"Texture evolution calculation failed: {e}")
            return {'texture_components': {}, 'fabric_tensor': np.eye(3), 'texture_index': 1.0}
    
    def _calculate_texture_component_strength(self, system_name, activity, strain_history, temperature):
        """Calculate strength of individual texture component"""
        try:
            # Base strength proportional to slip system activity
            base_strength = activity ** 0.5
            
            # Strain hardening/softening effects
            total_strain = sum(strain_history) if strain_history else 0.0
            strain_effect = np.exp(-total_strain * 0.5)  # Strain softening
            
            # Temperature effect on texture development
            temp_effect = np.exp(-(temperature - 298.15) / 1000.0) if temperature > 298.15 else 1.0
            
            # Dynamic recrystallization effect
            if temperature > 673.15 and total_strain > 0.3:  # High T, high strain
                recryst_softening = 0.5  # Strong texture weakening
            else:
                recryst_softening = 1.0
            
            component_strength = base_strength * strain_effect * temp_effect * recryst_softening
            
            return np.clip(component_strength, 0.1, 5.0)
            
        except Exception as e:
            self.logger.warning(f"Texture component strength calculation failed: {e}")
            return 1.0
    
    def _get_slip_system_orientation_matrix(self, system_name):
        """Get orientation matrix for slip system texture component"""
        try:
            # Common orientation matrices for slip systems (Euler angles in radians)
            orientation_matrices = {
                'basal': np.array([[1, 0, 0], [0, 1, 0], [0, 0, 1]]),  # No rotation
                'prism': np.array([[0, 1, 0], [-1, 0, 0], [0, 0, 1]]),  # 90° rotation around z
                '010_100': np.array([[1, 0, 0], [0, 0, 1], [0, -1, 0]]),  # 90° rotation around x
                '001_100': np.array([[0, 0, 1], [0, 1, 0], [-1, 0, 0]]),  # 90° rotation around y
                'r_twin': np.array([[0.707, 0.707, 0], [-0.707, 0.707, 0], [0, 0, 1]]),  # 45° rotation
            }
            
            # Find matching orientation or use default
            for key in orientation_matrices:
                if key in system_name.lower():
                    return orientation_matrices[key]
            
            # Default identity matrix
            return np.eye(3)
            
        except Exception as e:
            self.logger.warning(f"Orientation matrix calculation failed: {e}")
            return np.eye(3)
    
    def _calculate_fabric_tensor(self, texture_components):
        """Calculate overall fabric tensor from texture components"""
        try:
            fabric_tensor = np.zeros((3, 3))
            total_volume = sum(comp['volume_fraction'] for comp in texture_components.values())
            
            if total_volume > 0:
                for component in texture_components.values():
                    # Weight by volume fraction and strength
                    weight = component['volume_fraction'] * component['strength']
                    orientation = component['orientation_matrix']
                    
                    # Add contribution to fabric tensor
                    fabric_tensor += weight * np.outer(orientation[:, 0], orientation[:, 0])
                
                fabric_tensor /= total_volume
            else:
                fabric_tensor = np.eye(3)  # Isotropic fabric
            
            return fabric_tensor
            
        except Exception as e:
            self.logger.warning(f"Fabric tensor calculation failed: {e}")
            return np.eye(3)
    
    def _calculate_texture_index(self, texture_components):
        """Calculate texture index (J-index) for texture strength quantification"""
        try:
            if not texture_components:
                return 1.0  # Random texture
            
            # Calculate J-index based on component strengths
            total_strength = sum(comp['strength'] for comp in texture_components.values())
            n_components = len(texture_components)
            
            if n_components > 0:
                # J-index: 1 = random, >1 = textured
                j_index = 1.0 + (total_strength / n_components - 1.0) * 0.5
                return max(j_index, 1.0)
            else:
                return 1.0
                
        except Exception as e:
            self.logger.warning(f"Texture index calculation failed: {e}")
            return 1.0
    
    def _get_dominant_texture_orientation(self, texture_components):
        """Get dominant texture orientation from components"""
        try:
            if not texture_components:
                return np.eye(3)
            
            # Find component with highest strength * volume fraction
            max_weight = 0.0
            dominant_orientation = np.eye(3)
            
            for component in texture_components.values():
                weight = component['strength'] * component['volume_fraction']
                if weight > max_weight:
                    max_weight = weight
                    dominant_orientation = component['orientation_matrix']
            
            return dominant_orientation
            
        except Exception as e:
            self.logger.warning(f"Dominant texture orientation calculation failed: {e}")
            return np.eye(3)
    
    # Multi-scale crystal plasticity methods
    def _analyze_grain_microstructure(self, location, stress_tensor, **kwargs):
        """Analyze grain-scale microstructure with comprehensive multi-scale integration"""
        try:
            temperature = kwargs.get('temperature', 298.15)
            pressure = kwargs.get('pressure', 1e5)
            depth = kwargs.get('depth', 0.0)
            strain_rate = kwargs.get('strain_rate', 1e-15)
            
            # Calculate grain size distribution
            grain_distribution = self._calculate_grain_size_distribution(location, **kwargs)
            
            # Calculate dislocation density distribution
            dislocation_density = self._calculate_dislocation_density(stress_tensor, temperature, strain_rate)
            
            # Calculate grain boundary network properties
            gb_network = self._calculate_grain_boundary_network(grain_distribution, temperature, pressure)
            
            # Grain-scale plasticity analysis
            grain_plasticity = self._calculate_grain_scale_plasticity(
                grain_distribution, dislocation_density, stress_tensor, temperature
            )
            
            # Homogenize to polycrystal response
            polycrystal_response = self._homogenize_polycrystal_response(
                grain_plasticity, gb_network, stress_tensor
            )
            
            return {
                'microstructure': {
                    'grain_size_distribution': grain_distribution,
                    'dislocation_density': dislocation_density,
                    'grain_boundary_network': gb_network,
                    'texture_evolution': self._calculate_texture_evolution_microstructure(grain_plasticity)
                },
                'grain_plasticity': grain_plasticity,
                'polycrystal_response': polycrystal_response,
                'homogenization_quality': self._assess_homogenization_quality(grain_plasticity, polycrystal_response)
            }
            
        except Exception as e:
            self.logger.warning(f"Grain microstructure analysis failed: {e}")
            return {'microstructure': {}, 'grain_plasticity': {}, 'polycrystal_response': {}}
    
    def _calculate_grain_size_distribution(self, location, **kwargs):
        """Calculate grain size distribution using multi-modal statistical approach"""
        try:
            # Base grain sizes for different geological contexts
            depth = kwargs.get('depth', 0.0)
            temperature = kwargs.get('temperature', 298.15)
            pressure = kwargs.get('pressure', 0.1)
            
            # Depth-dependent grain size evolution
            base_grain_size = 0.1 + depth * 0.001  # mm, increases with depth
            
            # Temperature effects on recrystallization
            temp_factor = np.exp(-(temperature - 673.15) / 200.0) if temperature > 673.15 else 1.0
            recrystallized_grain_size = base_grain_size * temp_factor
            
            # Generate lognormal distribution
            mean_log_size = np.log(recrystallized_grain_size)
            std_log_size = 0.5  # Standard deviation in log space
            
            # Multi-modal distribution for different grain populations
            primary_grains = np.random.lognormal(mean_log_size, std_log_size, 1000)
            secondary_grains = np.random.lognormal(mean_log_size - 1.0, std_log_size * 0.3, 300)
            
            all_grain_sizes = np.concatenate([primary_grains, secondary_grains])
            
            return {
                'grain_sizes': all_grain_sizes,
                'mean_grain_size': np.mean(all_grain_sizes),
                'median_grain_size': np.median(all_grain_sizes),
                'grain_size_std': np.std(all_grain_sizes),
                'size_distribution_type': 'lognormal_bimodal',
                'recrystallization_fraction': min(1.0, max(0.0, (temperature - 573.15) / 400.0))
            }
            
        except Exception as e:
            self.logger.warning(f"Grain size distribution calculation failed: {e}")
            return {'grain_sizes': [0.1], 'mean_grain_size': 0.1, 'median_grain_size': 0.1}
    
    def _calculate_dislocation_density(self, stress_tensor, temperature, strain_rate):
        """Calculate comprehensive dislocation density distribution"""
        try:
            # Convert stress tensor magnitude
            stress_magnitude = self._calculate_tensor_magnitude(stress_tensor)
            
            # Base dislocation density using Taylor relation
            shear_modulus = 30e9  # GPa, typical for rock minerals
            burgers_vector = 3e-10  # m, typical
            
            # Taylor relation: ρ = (stress / (α * G * b))^2
            taylor_factor = 0.3  # geometric factor
            base_density = (stress_magnitude / (taylor_factor * shear_modulus * burgers_vector))**2
            
            # Temperature-dependent recovery
            recovery_rate = np.exp(-(2.0e-19) / (8.314 * temperature)) if temperature > 298.15 else 0.0
            recovered_density = base_density * (1.0 - 0.8 * recovery_rate)
            
            # Strain rate dependent multiplication
            multiplication_factor = 1.0 + 0.5 * np.log10(max(strain_rate, 1e-20) / 1e-15)
            final_density = recovered_density * max(multiplication_factor, 0.1)
            
            # Different dislocation types
            edge_fraction = 0.7  # 70% edge dislocations
            screw_fraction = 0.3  # 30% screw dislocations
            
            return {
                'total_density': max(final_density, 1e10),  # m^-2, minimum density
                'edge_density': max(final_density * edge_fraction, 7e9),
                'screw_density': max(final_density * screw_fraction, 3e9),
                'mobile_fraction': min(0.1, 1e-6 * np.sqrt(strain_rate / 1e-15)),
                'forest_density': max(final_density * 0.8, 8e9),
                'recovery_rate': recovery_rate,
                'temperature': temperature
            }
            
        except Exception as e:
            self.logger.warning(f"Dislocation density calculation failed: {e}")
            return {'total_density': 1e12, 'edge_density': 7e11, 'screw_density': 3e11}
    
    def _calculate_grain_boundary_network(self, grain_distribution, temperature, pressure):
        """Calculate grain boundary network properties"""
        try:
            mean_grain_size = grain_distribution.get('mean_grain_size', 1e-3)  # m
            
            # Grain boundary area per unit volume
            gb_area_per_volume = 3.0 / mean_grain_size  # m^2/m^3 for spherical grains
            
            # Grain boundary energy (temperature dependent)
            base_gb_energy = 1.0  # J/m^2
            temp_factor = 1.0 - 0.0002 * (temperature - 298.15)  # slight decrease with T
            gb_energy = base_gb_energy * max(temp_factor, 0.5)
            
            # Grain boundary thickness
            gb_thickness = 1e-9  # nm, typical
            
            # Grain boundary diffusivity
            gb_diffusivity = 1e-14 * np.exp(-1.5e-19 / (8.314 * temperature))  # m^2/s
            
            # Triple junction density
            # Assuming tetrakaidecahedron grains: ~1.4 junctions per grain
            grain_density = 1.0 / (mean_grain_size**3)  # grains/m^3
            triple_junction_density = 1.4 * grain_density
            
            return {
                'grain_boundary_area_density': gb_area_per_volume,
                'grain_boundary_energy': gb_energy,
                'grain_boundary_thickness': gb_thickness,
                'grain_boundary_diffusivity': gb_diffusivity,
                'triple_junction_density': triple_junction_density,
                'connectivity': 3.0,  # Average coordination number
                'tortuosity': 1.4,    # Path complexity factor
                'pinning_pressure': 2 * gb_energy / mean_grain_size  # Zener pinning
            }
            
        except Exception as e:
            self.logger.warning(f"Grain boundary network calculation failed: {e}")
            return {'grain_boundary_area_density': 3e6, 'grain_boundary_energy': 1.0}
    
    def _calculate_tensor_magnitude(self, tensor):
        """Calculate tensor magnitude"""
        try:
            if isinstance(tensor, dict):
                magnitude = np.sqrt(sum(v**2 for v in tensor.values()))
            else:
                magnitude = np.linalg.norm(tensor)
            return magnitude
        except Exception:
            return 1.0
    
