    def _integrate_geochemical_databases(self, composition_data, **kwargs):
        """Integrate composition data from multiple databases with weighting"""
        try:
            # Weighted integration based on data quality and sample count
            weights = {
                'petdb_analysis': 0.3,
                'georoc_analysis': 0.25,
                'earthchem_analysis': 0.2,
                'usgs_analysis': 0.25
            }
            
            # Integrate major elements
            major_elements = {}
            all_elements = set()
            for source, data in composition_data.items():
                if 'major_elements' in data:
                    all_elements.update(data['major_elements'].keys())
            
            for element in all_elements:
                weighted_sum = 0.0
                total_weight = 0.0
                
                for source, data in composition_data.items():
                    if 'major_elements' in data and element in data['major_elements']:
                        weight = weights.get(source, 0.1)
                        weighted_sum += data['major_elements'][element] * weight
                        total_weight += weight
                
                if total_weight > 0:
                    major_elements[element] = weighted_sum / total_weight
            
            # Calculate confidence scores
            confidence_scores = {}
            for element in major_elements:
                # Calculate standard deviation across sources
                values = []
                for source, data in composition_data.items():
                    if 'major_elements' in data and element in data['major_elements']:
                        values.append(data['major_elements'][element])
                
                if len(values) > 1:
                    std_dev = np.std(values)
                    mean_val = np.mean(values)
                    cv = std_dev / mean_val if mean_val > 0 else 1.0
                    confidence_scores[element] = max(0.0, 1.0 - cv)
                else:
                    confidence_scores[element] = 0.5
            
            return {
                'major_elements': major_elements,
                'confidence_scores': confidence_scores,
                'source_weights': weights,
                'integration_quality': np.mean(list(confidence_scores.values()))
            }
            
        except Exception as e:
            self.logger.warning(f"Database integration failed: {e}")
            return {'major_elements': {}, 'confidence_scores': {}}

