    # Advanced weather station integration with real-time API sources
    async def _fetch_comprehensive_weather_stations(self, lat, lon, radius_km=100):
        """Advanced weather station data collection with ML validation and multi-source integration"""
        try:
            # Initialize results container
            station_results = {
                'stations': [],
                'data_sources': [],
            'quality_metrics': {},
                'spatial_coverage': 0.0,
                'temporal_reliability': 0.0
            }
            
            # 1. Query local database first for existing stations
            db_stations = await self._query_database_weather_stations(lat, lon, radius_km)
            if db_stations:
                station_results['stations'].extend(db_stations)
                station_results['data_sources'].append('local_database')
            
            # 2. Real-time NOAA Weather Station Network
            noaa_stations = await self._fetch_noaa_stations_advanced(lat, lon, radius_km)
            if noaa_stations:
                station_results['stations'].extend(noaa_stations)
                station_results['data_sources'].append('noaa_network')
            
            # 3. ECMWF Global Weather Station Network
            ecmwf_stations = await self._fetch_ecmwf_stations(lat, lon, radius_km)
            if ecmwf_stations:
                station_results['stations'].extend(ecmwf_stations)
                station_results['data_sources'].append('ecmwf_global')
            
            # 4. Regional weather networks (MADIS, SYNOP, METAR)
            regional_stations = await self._fetch_regional_weather_networks(lat, lon, radius_km)
            if regional_stations:
                station_results['stations'].extend(regional_stations)
                station_results['data_sources'].append('regional_networks')
            
            # 5. Apply ML-based quality assessment and filtering
            if station_results['stations']:
                station_results['stations'] = await self._apply_ml_station_quality_filter(
                    station_results['stations'], lat, lon
                )
                
                # 6. Spatial-temporal interpolation for data gaps
                station_results = await self._apply_spatial_temporal_interpolation(
                    station_results, lat, lon
                )
                
                # 7. Calculate comprehensive quality metrics
                station_results['quality_metrics'] = await self._calculate_station_quality_metrics(
                    station_results['stations']
                )
            
            # 8. Emergency fallback with graceful degradation
            if not station_results['stations']:
                station_results = await self._emergency_weather_fallback(lat, lon)
            
            return station_results
            
        except Exception as e:
            self.logger.error(f"Advanced weather station fetch failed: {e}")
            return await self._emergency_weather_fallback(lat, lon)
    
    async def _query_database_weather_stations(self, lat, lon, radius_km):
        """Query local PostGIS database for weather monitoring stations"""
        try:
            query = """
            SELECT 
                station_code,
                ST_X(location::geometry) as longitude,
                ST_Y(location::geometry) as latitude,
                ST_Distance(location::geography, ST_Point(%s, %s)::geography) / 1000.0 as distance_km,
                network_code,
                station_type,
                operational_status,
                data_quality_score,
                last_update
            FROM seismic_stations s
            WHERE ST_DWithin(s.location::geography, ST_Point(%s, %s)::geography, %s * 1000)
            AND operational_status = 'active'
            AND data_quality_score > 0.6
            ORDER BY distance_km ASC
            LIMIT 20;
            """
            
            if hasattr(self, 'data_integration_manager'):
                result = await self.data_integration_manager.execute_spatial_query(
                    query, (lon, lat, lon, lat, radius_km)
                )
                
                stations = []
                for row in result:
                    station = {
                        'station_id': row['station_code'],
                        'location': {'lat': row['latitude'], 'lon': row['longitude']},
                        'distance_km': row['distance_km'],
                        'network': row['network_code'],
                        'station_type': row['station_type'],
                        'quality_grade': self._numeric_to_quality_grade(row['data_quality_score']),
                        'data_source': 'local_database',
                        'last_update': row['last_update'],
                        'measurements': await self._fetch_station_measurements(row['station_code'])
                    }
                    stations.append(station)
                
                return stations
        
        except Exception as e:
            self.logger.warning(f"Database weather station query failed: {e}")
            return []
    
    async def _fetch_noaa_stations_advanced(self, lat, lon, radius_km):
        """Advanced NOAA weather station integration with real API calls"""
        try:
            # Use DataIntegrationManager for NOAA API access
            if hasattr(self, 'data_integration_manager'):
                # NOAA Weather API endpoint
                base_url = "https://www.ncdc.noaa.gov/cdo-web/api/v2/stations"
                
                params = {
                    'limit': 100,
                    'offset': 0,
                    'locationid': f'FIPS:{self._get_fips_code(lat, lon)}',
                    'datasetid': 'NORMAL_DLY',
                    'extent': f'{lat-0.5},{lon-0.5},{lat+0.5},{lon+0.5}'
                }
                
                async with aiohttp.ClientSession() as session:
                    headers = {
                        'token': os.getenv('NOAA_API_TOKEN', 'default_token'),
                        'User-Agent': 'Prometheus-Geological-System/1.0'
                    }
                    
                    async with session.get(base_url, params=params, headers=headers) as response:
                        if response.status == 200:
                            data = await response.json()
                            return await self._process_noaa_station_data(data, lat, lon)
                        else:
                            self.logger.warning(f"NOAA API returned status {response.status}")
            
            return await self._fallback_noaa_stations(lat, lon, radius_km)
        
        except Exception as e:
            self.logger.warning(f"NOAA station fetch failed, using fallback: {e}")
            return await self._fallback_noaa_stations(lat, lon, radius_km)
    
    async def _process_noaa_station_data(self, data, target_lat, target_lon):
        """Process NOAA API response into standardized station format"""
        stations = []
        
        for station_info in data.get('results', []):
            try:
                lat = station_info.get('latitude', 0)
                lon = station_info.get('longitude', 0)
                
                # Calculate precise distance using advanced geodesic methods
                distance_km = self._calculate_geodesic_distance_advanced(
                    target_lat, target_lon, lat, lon
                )
                
                station = {
                    'station_id': station_info.get('id', 'unknown'),
                    'location': {'lat': lat, 'lon': lon},
                    'distance_km': distance_km,
                    'elevation_m': station_info.get('elevation', 0),
                    'network': 'NOAA',
                    'station_name': station_info.get('name', ''),
                    'quality_grade': self._assess_noaa_station_quality(station_info),
                    'data_source': 'noaa_api',
                    'measurements': await self._fetch_noaa_measurements(station_info.get('id'))
                }
                
                stations.append(station)
            
            except Exception as e:
                self.logger.warning(f"Failed to process NOAA station: {e}")
                continue
        
        return stations
    
    async def _fetch_ecmwf_stations(self, lat, lon, radius_km):
        """Fetch ECMWF Global Weather Station Network data"""
        try:
            # ECMWF Mars archive API integration
            ecmwf_stations = []
            
            # Grid-based approach for ECMWF data
            grid_points = self._generate_ecmwf_grid_points(lat, lon, radius_km)
            
            for grid_point in grid_points:
                station_data = await self._query_ecmwf_grid_point(grid_point)
                if station_data:
                    ecmwf_stations.append({
                        'station_id': f'ECMWF_{grid_point["grid_id"]}',
                        'location': {'lat': grid_point['lat'], 'lon': grid_point['lon']},
                        'distance_km': self._calculate_geodesic_distance_advanced(
                            lat, lon, grid_point['lat'], grid_point['lon']
                        ),
                        'network': 'ECMWF',
                        'data_source': 'ecmwf_mars',
                        'grid_resolution': grid_point['resolution'],
                        'quality_grade': 'A',  # ECMWF has high quality standards
                        'measurements': station_data
                    })
            
            return ecmwf_stations
        
        except Exception as e:
            self.logger.warning(f"ECMWF station fetch failed: {e}")
            return []
    
    async def _fetch_regional_weather_networks(self, lat, lon, radius_km):
        """Fetch data from regional weather networks (MADIS, SYNOP, METAR)"""
        regional_stations = []
        
        try:
            # MADIS (Meteorological Assimilation Data Ingest System)
            madis_stations = await self._fetch_madis_stations(lat, lon, radius_km)
            regional_stations.extend(madis_stations)
            
            # SYNOP (Surface Synoptic Observations)
            synop_stations = await self._fetch_synop_stations(lat, lon, radius_km)
            regional_stations.extend(synop_stations)
            
            # METAR (Meteorological Aerodrome Report)
            metar_stations = await self._fetch_metar_stations(lat, lon, radius_km)
            regional_stations.extend(metar_stations)
            
            return regional_stations
        
        except Exception as e:
            self.logger.warning(f"Regional network fetch failed: {e}")
