    async def _get_fips_code(self, lat: float, lon: float) -> Dict[str, Any]:
        """
        Advanced FIPS code geocoding system with real-time API integration
        
        Uses multiple authoritative data sources with fallback mechanisms:
        1. US Census Bureau Geocoding API (primary)
        2. USGS Geographic Names Information System
        3. PostGIS spatial database queries
        4. FCC Area API for telecommunications regions
        5. Emergency fallback with offline spatial database
        
        Args:
            lat: Latitude coordinate
            lon: Longitude coordinate
            
        Returns:
            Dict containing FIPS codes, administrative boundaries, and metadata
        """
        try:
            # Input validation and coordinate normalization
            if not (-90 <= lat <= 90) or not (-180 <= lon <= 180):
                raise ValueError(f"Invalid coordinates: lat={lat}, lon={lon}")
            
            # Normalize coordinates to 6 decimal places for consistency
            lat_norm = round(float(lat), 6)
            lon_norm = round(float(lon), 6)
            
            # Initialize result structure
            geocoding_result = {
                'fips_state': None,
                'fips_county': None,
                'fips_tract': None,
                'fips_block_group': None,
                'fips_block': None,
                'administrative_hierarchy': {},
                'confidence_score': 0.0,
                'data_sources_used': [],
                'spatial_accuracy_meters': None,
                'geocoding_timestamp': datetime.utcnow().isoformat(),
                'coordinate_reference_system': 'EPSG:4326'
            }
            
            # Method 1: US Census Bureau Geocoding API (highest accuracy)
            census_result = await self._query_census_geocoding_api(lat_norm, lon_norm)
            if census_result and census_result.get('confidence_score', 0) > 0.8:
                geocoding_result.update(census_result)
                geocoding_result['data_sources_used'].append('census_bureau')
                self.logger.info(f"High-confidence FIPS from Census Bureau: {census_result.get('fips_county')}")
                return geocoding_result
            
            # Method 2: USGS GNIS enhanced with spatial analysis
            usgs_result = await self._query_usgs_gnis_enhanced(lat_norm, lon_norm)
            if usgs_result and usgs_result.get('confidence_score', 0) > 0.7:
                geocoding_result.update(usgs_result)
                geocoding_result['data_sources_used'].append('usgs_gnis')
                self.logger.info(f"FIPS from USGS GNIS: {usgs_result.get('fips_county')}")
                return geocoding_result
            
            # Method 3: PostGIS spatial database query with Tiger/Line data
            spatial_result = await self._query_spatial_database_fips(lat_norm, lon_norm)
            if spatial_result and spatial_result.get('confidence_score', 0) > 0.6:
                geocoding_result.update(spatial_result)
                geocoding_result['data_sources_used'].append('postgis_spatial')
                self.logger.info(f"FIPS from PostGIS: {spatial_result.get('fips_county')}")
                return geocoding_result
            
            # Method 4: FCC Area API for telecommunications-based lookup
            fcc_result = await self._query_fcc_area_api(lat_norm, lon_norm)
            if fcc_result and fcc_result.get('confidence_score', 0) > 0.5:
                geocoding_result.update(fcc_result)
                geocoding_result['data_sources_used'].append('fcc_area_api')
                self.logger.info(f"FIPS from FCC Area API: {fcc_result.get('fips_county')}")
                return geocoding_result
            
            # Method 5: Machine learning-based spatial interpolation
            ml_result = await self._ml_spatial_interpolation_fips(lat_norm, lon_norm)
            if ml_result and ml_result.get('confidence_score', 0) > 0.4:
                geocoding_result.update(ml_result)
                geocoding_result['data_sources_used'].append('ml_interpolation')
                self.logger.warning(f"FIPS from ML interpolation: {ml_result.get('fips_county')}")
                return geocoding_result
            
            # Emergency fallback: Use nearest known point with uncertainty quantification
            fallback_result = await self._emergency_fips_fallback(lat_norm, lon_norm)
            geocoding_result.update(fallback_result)
            geocoding_result['data_sources_used'].append('emergency_fallback')
            
            self.logger.error(f"All geocoding methods failed, using fallback for {lat_norm}, {lon_norm}")
            return geocoding_result
            
        except Exception as e:
            self.logger.error(f"Critical failure in FIPS geocoding for {lat}, {lon}: {e}")
            # Return minimal fallback structure
            return {
                'fips_state': None,
                'fips_county': None,
                'confidence_score': 0.0,
                'error': str(e),
                'data_sources_used': ['error_fallback'],
                'geocoding_timestamp': datetime.utcnow().isoformat()
            }

    async def _query_census_geocoding_api(self, lat: float, lon: float) -> Dict[str, Any]:
        """Query US Census Bureau Geocoding API for authoritative FIPS codes"""
        try:
            # Census Bureau Geographic Locations API
            base_url = "https://geo.fcc.gov/api/census/area"
            params = {
                'lat': lat,
                'lon': lon,
                'format': 'json',
                'showall': 'true'  # Include all administrative levels
            }
            
            async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=10)) as session:
                async with session.get(base_url, params=params) as response:
                    if response.status == 200:
                        data = await response.json()
                        
                        if 'results' in data and len(data['results']) > 0:
                            result = data['results'][0]
                            
                            # Extract FIPS codes from Census response
                            fips_data = {
                                'fips_state': result.get('state_fips'),
                                'fips_county': result.get('county_fips'),
                                'fips_tract': result.get('tract_fips'),
                                'fips_block_group': result.get('block_group_fips'),
                                'fips_block': result.get('block_fips'),
                                'administrative_hierarchy': {
                                    'state_name': result.get('state_name'),
                                    'county_name': result.get('county_name'),
                                    'place_name': result.get('place_name'),
                                    'msa_name': result.get('msa_name')
                                },
                                'confidence_score': 0.95,  # Census data is highly authoritative
                                'spatial_accuracy_meters': 10  # Census blocks are ~10m accurate
                            }
                            
                            # Additional validation
                            if fips_data['fips_state'] and fips_data['fips_county']:
                                return fips_data
                    
        except asyncio.TimeoutError:
            self.logger.warning(f"Census API timeout for coordinates {lat}, {lon}")
        except Exception as e:
            self.logger.error(f"Census API error: {e}")
        
        return None

    async def _query_usgs_gnis_enhanced(self, lat: float, lon: float) -> Dict[str, Any]:
        """Enhanced USGS Geographic Names Information System query with spatial analysis"""
        try:
            # USGS GNIS Feature Service
            base_url = "https://geonames.usgs.gov/apex/f"
            params = {
                'p': 'gnispq:gnispq',
                'gnispq_lat': lat,
                'gnispq_lon': lon,
                'gnispq_dist': '5',  # 5-mile radius
                'gnispq_feature_type': 'Civil'
            }
            
            async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=15)) as session:
                async with session.get(base_url, params=params) as response:
                    if response.status == 200:
                        data = await response.json()
                        
                        # Process GNIS response and extract administrative data
                        if 'features' in data and len(data['features']) > 0:
                            closest_feature = min(data['features'], 
                                                key=lambda f: self._calculate_distance(
                                                    lat, lon, 
                                                    f['properties'].get('latitude', 0),
                                                    f['properties'].get('longitude', 0)
                                                ))
                            
                            # Cross-reference with known FIPS mapping
                            county_name = closest_feature['properties'].get('county_name')
                            state_name = closest_feature['properties'].get('state_name')
                            
                            if county_name and state_name:
                                fips_mapping = await self._lookup_fips_by_names(state_name, county_name)
                                if fips_mapping:
                                    fips_mapping['confidence_score'] = 0.8
                                    fips_mapping['spatial_accuracy_meters'] = 100
                                    return fips_mapping
                                    
        except Exception as e:
            self.logger.error(f"USGS GNIS API error: {e}")
        
        return None

    async def _query_spatial_database_fips(self, lat: float, lon: float) -> Dict[str, Any]:
        """Query PostGIS spatial database for FIPS codes using Tiger/Line boundaries"""
        try:
            if not hasattr(self, 'db_manager'):
                from .database_integration import DatabaseManager
                self.db_manager = DatabaseManager()
            
            # PostGIS spatial query for administrative boundaries
            spatial_query = """
            SELECT 
                cb.statefp as state_fips,
                cb.countyfp as county_fips,
                cb.name as county_name,
                st.name as state_name,
                ST_Distance(
                    ST_SetSRID(ST_MakePoint(%s, %s), 4326)::geography,
                    cb.geom::geography
                ) as distance_meters
            FROM census_boundaries.counties cb
            JOIN census_boundaries.states st ON cb.statefp = st.statefp
            WHERE ST_Contains(cb.geom, ST_SetSRID(ST_MakePoint(%s, %s), 4326))
            ORDER BY distance_meters ASC
            LIMIT 1;
            """
            
            result = await self.db_manager.execute_query(
                spatial_query, 
                (lon, lat, lon, lat)
            )
            
            if result and len(result) > 0:
                row = result[0]
                return {
                    'fips_state': row['state_fips'],
                    'fips_county': f"{row['state_fips']}{row['county_fips']}",
                    'administrative_hierarchy': {
                        'state_name': row['state_name'],
                        'county_name': row['county_name']
                    },
                    'confidence_score': 0.9 if row['distance_meters'] == 0 else 0.7,
                    'spatial_accuracy_meters': row['distance_meters']
                }
                
        except Exception as e:
            self.logger.error(f"PostGIS spatial query error: {e}")
        
        return None

    async def _query_fcc_area_api(self, lat: float, lon: float) -> Dict[str, Any]:
        """Query FCC Area API for telecommunications-based FIPS lookup"""
        try:
            base_url = "https://geo.fcc.gov/api/census/block/find"
            params = {
                'latitude': lat,
                'longitude': lon,
                'format': 'json',
                'showall': 'false'
            }
            
            async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=12)) as session:
                async with session.get(base_url, params=params) as response:
                    if response.status == 200:
                        data = await response.json()
                        
                        if 'Block' in data and 'FIPS' in data['Block']:
                            fips_full = data['Block']['FIPS']
                            
                            # Parse full FIPS code (15 digits: 2 state + 3 county + 6 tract + 4 block)
                            if len(fips_full) >= 5:
                                state_fips = fips_full[:2]
                                county_fips = fips_full[2:5]
                                full_county_fips = f"{state_fips}{county_fips}"
                                
                                return {
                                    'fips_state': state_fips,
                                    'fips_county': full_county_fips,
                                    'fips_tract': fips_full[:11] if len(fips_full) >= 11 else None,
                                    'fips_block': fips_full if len(fips_full) == 15 else None,
                                    'confidence_score': 0.75,
                                    'spatial_accuracy_meters': 50
                                }
                                
        except Exception as e:
            self.logger.error(f"FCC Area API error: {e}")
        
        return None

    async def _ml_spatial_interpolation_fips(self, lat: float, lon: float) -> Dict[str, Any]:
        """Machine learning-based spatial interpolation for FIPS code prediction"""
        try:
            # Use existing ML models if available
            if hasattr(self, 'spatial_ml_model'):
                # Prepare feature vector: [lat, lon, elevation, distance_to_coast, etc.]
                features = await self._extract_spatial_features(lat, lon)
                
                # Predict FIPS codes using trained model
                prediction = self.spatial_ml_model.predict([features])
                confidence = self.spatial_ml_model.predict_proba([features]).max()
                
                if confidence > 0.4:
                    return {
                        'fips_state': prediction[0][:2],
                        'fips_county': prediction[0][:5],
                        'confidence_score': float(confidence),
                        'spatial_accuracy_meters': 1000,  # Lower accuracy for ML predictions
                        'ml_model_version': getattr(self.spatial_ml_model, 'version', 'unknown')
                    }
            
            # If no trained model, use statistical interpolation
            return await self._statistical_fips_interpolation(lat, lon)
            
        except Exception as e:
            self.logger.error(f"ML spatial interpolation error: {e}")
        
        return None

    async def _statistical_fips_interpolation(self, lat: float, lon: float) -> Dict[str, Any]:
        """Statistical interpolation based on nearest known points"""
        try:
            # Query database for nearest known FIPS locations
            if hasattr(self, 'db_manager'):
                nearest_query = """
                SELECT 
                    fips_state, fips_county, latitude, longitude,
                    ST_Distance(
                        ST_SetSRID(ST_MakePoint(%s, %s), 4326)::geography,
                        ST_SetSRID(ST_MakePoint(longitude, latitude), 4326)::geography
                    ) as distance_meters
                FROM known_fips_locations
                ORDER BY distance_meters ASC
                LIMIT 5;
                """
                
                nearby_points = await self.db_manager.execute_query(
                    nearest_query, (lon, lat)
                )
                
                if nearby_points and len(nearby_points) >= 3:
                    # Weighted interpolation based on inverse distance
                    weights = []
                    fips_counties = []
                    
                    for point in nearby_points:
                        distance = max(point['distance_meters'], 1)  # Avoid division by zero
                        weight = 1.0 / distance
                        weights.append(weight)
                        fips_counties.append(point['fips_county'])
                    
                    # Find most probable FIPS code
                    from collections import Counter
                    weighted_counts = Counter()
                    
                    for fips, weight in zip(fips_counties, weights):
                        weighted_counts[fips] += weight
                    
                    most_likely_fips = weighted_counts.most_common(1)[0][0]
                    confidence = weighted_counts[most_likely_fips] / sum(weights)
                    
                    return {
                        'fips_state': most_likely_fips[:2],
                        'fips_county': most_likely_fips,
                        'confidence_score': min(confidence, 0.6),  # Cap statistical confidence
                        'spatial_accuracy_meters': nearby_points[0]['distance_meters'],
                        'interpolation_method': 'inverse_distance_weighted'
                    }
                    
        except Exception as e:
            self.logger.error(f"Statistical interpolation error: {e}")
        
        return None

    async def _emergency_fips_fallback(self, lat: float, lon: float) -> Dict[str, Any]:
        """Emergency fallback system for FIPS code determination"""
        try:
            # Simple geographic region mapping for continental US
            region_mapping = {
                # Northeast
                (lat >= 39 and lat <= 47 and lon >= -80 and lon <= -66): {'state': '09', 'region': 'northeast'},
                # Southeast
                (lat >= 24 and lat <= 39 and lon >= -87 and lon <= -75): {'state': '12', 'region': 'southeast'},
                # Midwest
                (lat >= 36 and lat <= 49 and lon >= -104 and lon <= -80): {'state': '17', 'region': 'midwest'},
                # Southwest
                (lat >= 25 and lat <= 42 and lon >= -125 and lon <= -87): {'state': '06', 'region': 'southwest'},
                # Northwest
                (lat >= 42 and lat <= 49 and lon >= -125 and lon <= -104): {'state': '53', 'region': 'northwest'}
            }
            
            # Find matching region
            for (condition, region_data) in region_mapping.items():
                if condition:
                    fallback_county = f"{region_data['state']}999"  # Generic county code
                    
                    return {
                        'fips_state': region_data['state'],
                        'fips_county': fallback_county,
                        'confidence_score': 0.1,  # Very low confidence
                        'spatial_accuracy_meters': 100000,  # ~100km uncertainty
                        'fallback_reason': f"Geographic region: {region_data['region']}",
                        'warning': 'This is an emergency fallback - accuracy not guaranteed'
                    }
            
            # Ultimate fallback for coordinates outside continental US
            return {
                'fips_state': '99',  # Unknown/other
                'fips_county': '99999',  # Unknown/other
                'confidence_score': 0.0,
                'spatial_accuracy_meters': None,
                'fallback_reason': 'Coordinates outside continental US or unknown region',
                'warning': 'Emergency fallback used - no reliable FIPS determination possible'
            }
            
        except Exception as e:
            self.logger.error(f"Emergency fallback error: {e}")
            return {
                'fips_state': None,
                'fips_county': None,
                'confidence_score': 0.0,
                'error': str(e)
            }

    async def _lookup_fips_by_names(self, state_name: str, county_name: str) -> Dict[str, Any]:
        """Lookup FIPS codes by state and county names using reference database"""
        try:
            if hasattr(self, 'db_manager'):
                name_lookup_query = """
                SELECT 
                    c.statefp as state_fips,
                    CONCAT(c.statefp, c.countyfp) as county_fips,
                    c.name as county_name,
                    s.name as state_name
                FROM census_reference.counties c
                JOIN census_reference.states s ON c.statefp = s.statefp
                WHERE 
                    LOWER(s.name) = LOWER(%s) AND 
                    LOWER(c.name) LIKE LOWER(%s)
                LIMIT 1;
                """
                
                result = await self.db_manager.execute_query(
                    name_lookup_query, 
                    (state_name, f"%{county_name}%")
                )
                
                if result and len(result) > 0:
                    row = result[0]
                    return {
                        'fips_state': row['state_fips'],
                        'fips_county': row['county_fips'],
                        'administrative_hierarchy': {
                            'state_name': row['state_name'],
                            'county_name': row['county_name']
                        }
                    }
                    
        except Exception as e:
            self.logger.error(f"Name-based FIPS lookup error: {e}")
        
        return None

    async def _extract_spatial_features(self, lat: float, lon: float) -> List[float]:
        """Extract spatial features for machine learning model input"""
        try:
            features = [lat, lon]
            
            # Add elevation data if available
            if hasattr(self, 'elevation_service'):
                elevation = await self.elevation_service.get_elevation(lat, lon)
                features.append(elevation if elevation is not None else 0.0)
            else:
                features.append(0.0)
            
            # Add distance to coast (simplified calculation)
            coast_distance = self._approximate_distance_to_coast(lat, lon)
            features.append(coast_distance)
            
            # Add population density estimate
            pop_density = await self._estimate_population_density(lat, lon)
            features.append(pop_density)
            
            # Add additional geographic features as needed
            return features
            
        except Exception as e:
            self.logger.error(f"Feature extraction error: {e}")
            return [lat, lon, 0.0, 0.0, 0.0]  # Fallback minimal features

    async def _approximate_distance_to_coast(self, lat: float, lon: float) -> Dict[str, Any]:
        """
        Advanced coastal distance calculation with multi-source integration
        
        Uses high-resolution bathymetry, satellite imagery, and ML-based coastal detection:
        1. NOAA Coastal Relief Model (CRM) - 3 arc-second resolution
        2. NASA SRTM Water Body Dataset - global coverage  
        3. USGS National Hydrography Dataset - high accuracy US coastlines
        4. GEBCO Bathymetric Compilation - global ocean bathymetry
        5. PostGIS spatial analysis with coastline vector data
        6. Machine learning coastal feature classification
        7. Multi-spectral satellite imagery analysis (Landsat 8/9, Sentinel-2)
        
        Args:
            lat: Latitude coordinate
            lon: Longitude coordinate
            
        Returns:
            Dict containing distance metrics, coastal features, and confidence scores
        """
        try:
            # Input validation and coordinate normalization
            if not (-90 <= lat <= 90) or not (-180 <= lon <= 180):
                raise ValueError(f"Invalid coordinates: lat={lat}, lon={lon}")
                
            lat_norm = round(float(lat), 6)
            lon_norm = round(float(lon), 6)
            
            # Initialize comprehensive result structure
            coastal_analysis = {
                'distance_to_coast_km': None,
                'nearest_water_body': None,
                'coastal_type': None,  # 'ocean', 'gulf', 'bay', 'lake', 'river', 'inland'
                'water_depth_m': None,
                'bathymetric_profile': {},
                'coastal_features': [],
                'confidence_score': 0.0,
                'data_sources_used': [],
                'analysis_methods': [],
                'uncertainty_km': None,
                'processing_timestamp': datetime.utcnow().isoformat(),
                'spatial_resolution_m': None
            }
            
            # Method 1: High-resolution PostGIS coastline vector analysis (highest accuracy)
            postgis_result = await self._query_postgis_coastline_vectors(lat_norm, lon_norm)
            if postgis_result and postgis_result.get('confidence_score', 0) > 0.9:
                coastal_analysis.update(postgis_result)
                coastal_analysis['data_sources_used'].append('postgis_vectors')
                coastal_analysis['analysis_methods'].append('vector_geometry')
                self.logger.info(f"High-accuracy coastline distance from PostGIS: {postgis_result.get('distance_to_coast_km')}km")
                return coastal_analysis
            
            # Method 2: NOAA Coastal Relief Model integration
            noaa_result = await self._query_noaa_coastal_relief_model(lat_norm, lon_norm)
            if noaa_result and noaa_result.get('confidence_score', 0) > 0.8:
                coastal_analysis.update(noaa_result)
                coastal_analysis['data_sources_used'].append('noaa_crm')
                coastal_analysis['analysis_methods'].append('bathymetric_contours')
                self.logger.info(f"Coastal distance from NOAA CRM: {noaa_result.get('distance_to_coast_km')}km")
                return coastal_analysis
            
            # Method 3: NASA SRTM Water Body Dataset analysis
            nasa_result = await self._query_nasa_srtm_water_bodies(lat_norm, lon_norm)
            if nasa_result and nasa_result.get('confidence_score', 0) > 0.7:
                coastal_analysis.update(nasa_result)
                coastal_analysis['data_sources_used'].append('nasa_srtm')
                coastal_analysis['analysis_methods'].append('elevation_water_mask')
                self.logger.info(f"Coastal distance from NASA SRTM: {nasa_result.get('distance_to_coast_km')}km")
                return coastal_analysis
            
            # Method 4: GEBCO Global Bathymetry integration
            gebco_result = await self._query_gebco_bathymetry(lat_norm, lon_norm)
            if gebco_result and gebco_result.get('confidence_score', 0) > 0.6:
                coastal_analysis.update(gebco_result)
                coastal_analysis['data_sources_used'].append('gebco_bathymetry')
                coastal_analysis['analysis_methods'].append('global_bathymetry')
                self.logger.info(f"Coastal distance from GEBCO: {gebco_result.get('distance_to_coast_km')}km")
                return coastal_analysis
            
            # Method 5: Multi-spectral satellite imagery analysis
            satellite_result = await self._analyze_satellite_coastal_imagery(lat_norm, lon_norm)
            if satellite_result and satellite_result.get('confidence_score', 0) > 0.5:
                coastal_analysis.update(satellite_result)
                coastal_analysis['data_sources_used'].append('satellite_imagery')
                coastal_analysis['analysis_methods'].append('multispectral_classification')
                self.logger.info(f"Coastal distance from satellite analysis: {satellite_result.get('distance_to_coast_km')}km")
                return coastal_analysis
            
            # Method 6: Machine learning coastal feature detection
            ml_result = await self._ml_coastal_feature_detection(lat_norm, lon_norm)
            if ml_result and ml_result.get('confidence_score', 0) > 0.4:
                coastal_analysis.update(ml_result)
                coastal_analysis['data_sources_used'].append('ml_detection')
                coastal_analysis['analysis_methods'].append('neural_network')
                self.logger.warning(f"Coastal distance from ML detection: {ml_result.get('distance_to_coast_km')}km")
                return coastal_analysis
            
            # Method 7: Hydrological network analysis
            hydro_result = await self._analyze_hydrological_networks(lat_norm, lon_norm)
            if hydro_result and hydro_result.get('confidence_score', 0) > 0.3:
                coastal_analysis.update(hydro_result)
                coastal_analysis['data_sources_used'].append('hydro_networks')
                coastal_analysis['analysis_methods'].append('drainage_analysis')
                self.logger.warning(f"Coastal distance from hydro analysis: {hydro_result.get('distance_to_coast_km')}km")
                return coastal_analysis
            
            # Emergency fallback: Enhanced geometric approximation
            fallback_result = await self._enhanced_geometric_coastal_approximation(lat_norm, lon_norm)
            coastal_analysis.update(fallback_result)
            coastal_analysis['data_sources_used'].append('geometric_fallback')
            coastal_analysis['analysis_methods'].append('enhanced_approximation')
            
            self.logger.error(f"All coastal analysis methods failed, using enhanced fallback for {lat_norm}, {lon_norm}")
            return coastal_analysis
            
        except Exception as e:
            self.logger.error(f"Critical failure in coastal distance analysis for {lat}, {lon}: {e}")
            return {
                'distance_to_coast_km': None,
                'confidence_score': 0.0,
                'error': str(e),
                'data_sources_used': ['error_fallback'],
                'processing_timestamp': datetime.utcnow().isoformat()
            }

    async def _query_postgis_coastline_vectors(self, lat: float, lon: float) -> Dict[str, Any]:
        """Query high-resolution PostGIS coastline vector database"""
        try:
            if not hasattr(self, 'db_manager'):
                from .database_integration import DatabaseManager
                self.db_manager = DatabaseManager()
            
            # Multi-level PostGIS spatial query for coastline analysis
            coastline_query = """
            WITH point_geom AS (
                SELECT ST_SetSRID(ST_MakePoint(%s, %s), 4326) as pt
            ),
            nearest_coastline AS (
                SELECT 
                    cl.coastline_type,
                    cl.feature_name,
                    cl.water_body_type,
                    cl.geom as coastline_geom,
                    ST_Distance(
                        ST_Transform(pt.pt, 3857)::geography,
                        ST_Transform(cl.geom, 3857)::geography
                    ) / 1000.0 as distance_km,
                    ST_ClosestPoint(cl.geom, pt.pt) as closest_point,
                    cl.confidence_level,
                    cl.data_resolution_m
                FROM coastline_vectors cl, point_geom pt
                WHERE ST_DWithin(
                    ST_Transform(pt.pt, 3857)::geography, 
                    ST_Transform(cl.geom, 3857)::geography, 
                    1000000  -- 1000km search radius
                )
                ORDER BY distance_km ASC
                LIMIT 5
            ),
            bathymetry_profile AS (
                SELECT 
                    AVG(b.depth_m) as avg_depth,
                    MIN(b.depth_m) as min_depth,
                    MAX(b.depth_m) as max_depth,
                    COUNT(*) as sample_count
                FROM bathymetry_points b, point_geom pt
                WHERE ST_DWithin(
                    ST_Transform(pt.pt, 3857)::geography,
                    ST_Transform(b.location, 3857)::geography,
                    50000  -- 50km radius for bathymetry
                )
                AND b.depth_m IS NOT NULL
            ),
            coastal_features AS (
                SELECT 
                    array_agg(DISTINCT cf.feature_type) as feature_types,
                    array_agg(DISTINCT cf.feature_name) as feature_names
                FROM coastal_features cf, point_geom pt
                WHERE ST_DWithin(
                    ST_Transform(pt.pt, 3857)::geography,
                    ST_Transform(cf.location, 3857)::geography,
                    25000  -- 25km radius for coastal features
                )
            )
            SELECT 
                nc.distance_km,
                nc.coastline_type,
                nc.feature_name,
                nc.water_body_type,
                nc.confidence_level,
                nc.data_resolution_m,
                ST_X(nc.closest_point) as closest_lon,
                ST_Y(nc.closest_point) as closest_lat,
                bp.avg_depth,
                bp.min_depth,
                bp.max_depth,
                bp.sample_count,
                cf.feature_types,
                cf.feature_names
            FROM nearest_coastline nc
            CROSS JOIN bathymetry_profile bp
            CROSS JOIN coastal_features cf
            ORDER BY nc.distance_km ASC
            LIMIT 1;
            """
            
            result = await self.db_manager.execute_query(coastline_query, (lon, lat))
            
            if result and len(result) > 0:
                row = result[0]
                
                # Calculate uncertainty based on data resolution
                resolution_m = row.get('data_resolution_m', 30.0)
                uncertainty_km = (resolution_m / 1000.0) * 2  # 2x resolution as uncertainty
                
                return {
                    'distance_to_coast_km': round(row['distance_km'], 3),
                    'nearest_water_body': row['feature_name'],
                    'coastal_type': row['water_body_type'],
                    'water_depth_m': row.get('avg_depth'),
                    'bathymetric_profile': {
                        'average_depth_m': row.get('avg_depth'),
                        'min_depth_m': row.get('min_depth'),
                        'max_depth_m': row.get('max_depth'),
                        'sample_points': row.get('sample_count', 0)
                    },
                    'coastal_features': list(row.get('feature_types', [])) if row.get('feature_types') else [],
                    'closest_point': {
                        'latitude': row.get('closest_lat'),
                        'longitude': row.get('closest_lon')
                    },
                    'confidence_score': min(row.get('confidence_level', 0.5), 0.95),
                    'uncertainty_km': uncertainty_km,
                    'spatial_resolution_m': resolution_m
                }
        
        except Exception as e:
            self.logger.error(f"PostGIS coastline query error: {e}")
        
        return None

    async def _query_noaa_coastal_relief_model(self, lat: float, lon: float) -> Dict[str, Any]:
        """Query NOAA Coastal Relief Model for high-resolution bathymetry"""
        try:
            # NOAA Digital Coast API integration
            base_url = "https://coast.noaa.gov/htdata/raster2/elevation"
            
            # Determine appropriate CRM dataset based on location
            crm_dataset = self._determine_noaa_crm_dataset(lat, lon)
            if not crm_dataset:
                return None
            
            # Multi-resolution analysis: 3 arc-second, 9 arc-second grids
            for resolution in ['3_arc_second', '9_arc_second']:
                try:
                    # WCS (Web Coverage Service) request for elevation/bathymetry data
                    wcs_params = {
                        'service': 'WCS',
                        'version': '2.0.1',
                        'request': 'GetCoverage',
                        'coverageId': f"{crm_dataset}_{resolution}",
                        'subset': [
                            f'Lat({lat-0.01},{lat+0.01})',  # ~1km grid around point
                            f'Long({lon-0.01},{lon+0.01})'
                        ],
                        'format': 'image/tiff',
                        'outputCrs': 'EPSG:4326'
                    }
                    
                    async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=20)) as session:
                        async with session.get(f"{base_url}/wcs", params=wcs_params) as response:
                            if response.status == 200:
                                # Process elevation/bathymetry data
                                elevation_data = await self._process_noaa_elevation_data(
                                    await response.read(), lat, lon
                                )
                                
                                if elevation_data:
                                    # Find coastline from elevation data (0m contour)
                                    coastal_metrics = await self._extract_coastal_metrics_from_elevation(
                                        elevation_data, lat, lon
                                    )
                                    
                                    if coastal_metrics:
                                        coastal_metrics['confidence_score'] = 0.9 if resolution == '3_arc_second' else 0.8
                                        coastal_metrics['spatial_resolution_m'] = 90 if resolution == '3_arc_second' else 270
                                        return coastal_metrics
                                        
                except Exception as res_e:
                    self.logger.warning(f"NOAA CRM {resolution} failed: {res_e}")
                    continue
            
        except Exception as e:
            self.logger.error(f"NOAA Coastal Relief Model error: {e}")
        
        return None

    async def _query_nasa_srtm_water_bodies(self, lat: float, lon: float) -> Dict[str, Any]:
        """Query NASA SRTM Water Body Dataset for water feature analysis"""
        try:
            # NASA Earthdata API integration
            if hasattr(self, 'data_integration_manager'):
                nasa_connector = self.data_integration_manager.connectors.get('nasa')
                if nasa_connector:
                    # SRTM Water Body Data (SWBD) query
                    water_body_params = {
                        'collection': 'C1220567270-LPDAAC_ECS',  # SRTM SWBD Collection
                        'spatial': f'{lon-0.1},{lat-0.1},{lon+0.1},{lat+0.1}',  # ~10km grid
                        'temporal': '2000-02-11T00:00:00Z,2000-02-22T23:59:59Z'
                    }
                    
                    srtm_data = await nasa_connector.query_earthdata(water_body_params)
                    
                    if srtm_data and 'hits' in srtm_data:
                        # Process water body polygons
                        water_analysis = await self._analyze_srtm_water_bodies(
                            srtm_data, lat, lon
                        )
                        
                        if water_analysis:
                            water_analysis['confidence_score'] = 0.75
                            water_analysis['spatial_resolution_m'] = 90  # SRTM 3 arc-second
                            return water_analysis
            
            # Fallback: Direct USGS EarthExplorer API
            earthexplorer_result = await self._query_usgs_earthexplorer_srtm(lat, lon)
            if earthexplorer_result:
                return earthexplorer_result
                
        except Exception as e:
            self.logger.error(f"NASA SRTM water body query error: {e}")
        
        return None

    async def _query_gebco_bathymetry(self, lat: float, lon: float) -> Dict[str, Any]:
        """Query GEBCO Global Bathymetric Compilation"""
        try:
            # GEBCO Web Map Service integration
            gebco_wms_url = "https://www.gebco.net/data_and_products/gebco_web_services/web_map_service/mapserv"
            
            # Multi-resolution GEBCO datasets
            gebco_layers = [
                'GEBCO_LATEST_SUB_ICE_TOPO',  # Latest high-resolution
                'GEBCO_2023_GRID',            # 2023 compilation
                'GEBCO_2021_GRID'             # Fallback
            ]
            
            for layer in gebco_layers:
                try:
                    wms_params = {
                        'service': 'WMS',
                        'version': '1.3.0',
                        'request': 'GetMap',
                        'layers': layer,
                        'crs': 'EPSG:4326',
                        'bbox': f'{lat-0.05},{lon-0.05},{lat+0.05},{lon+0.05}',  # ~5km grid
                        'width': '512',
                        'height': '512',
                        'format': 'image/geotiff',
                        'time': 'default'
                    }
                    
                    async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=15)) as session:
                        async with session.get(gebco_wms_url, params=wms_params) as response:
                            if response.status == 200:
                                # Process GEBCO bathymetry data
                                bathymetry_data = await self._process_gebco_bathymetry_data(
                                    await response.read(), lat, lon
                                )
                                
                                if bathymetry_data:
                                    # Extract coastal distance from bathymetry
                                    coastal_analysis = await self._extract_coastal_distance_from_bathymetry(
                                        bathymetry_data, lat, lon
                                    )
                                    
                                    if coastal_analysis:
                                        coastal_analysis['confidence_score'] = 0.7
                                        coastal_analysis['spatial_resolution_m'] = 450  # GEBCO ~15 arc-second
                                        return coastal_analysis
                                        
                except Exception as layer_e:
                    self.logger.warning(f"GEBCO layer {layer} failed: {layer_e}")
                    continue
            
        except Exception as e:
            self.logger.error(f"GEBCO bathymetry query error: {e}")
        
        return None

