    async def _analyze_hydrological_networks(self, lat: float, lon: float) -> Dict[str, Any]:
        """Analyze hydrological drainage networks to determine coastal connectivity"""
        try:
            if hasattr(self, 'db_manager'):
                # Query hydrological network database
                hydro_query = """
                WITH point_geom AS (
                    SELECT ST_SetSRID(ST_MakePoint(%s, %s), 4326) as pt
                ),
                nearest_drainage AS (
                    SELECT 
                        hn.stream_order,
                        hn.flow_direction,
                        hn.discharge_cms,
                        hn.drainage_area_km2,
                        hn.outlet_type,
                        hn.outlet_coordinates,
                        ST_Distance(
                            ST_Transform(pt.pt, 3857)::geography,
                            ST_Transform(hn.geom, 3857)::geography
                        ) / 1000.0 as distance_km
                    FROM hydrological_networks hn, point_geom pt
                    WHERE ST_DWithin(
                        ST_Transform(pt.pt, 3857)::geography,
                        ST_Transform(hn.geom, 3857)::geography,
                        100000  -- 100km search radius
                    )
                    AND hn.stream_order >= 4  -- Major streams only
                    ORDER BY distance_km ASC, stream_order DESC
                    LIMIT 3
                )
                SELECT 
                    nd.outlet_type,
                    nd.outlet_coordinates,
                    nd.distance_km as stream_distance,
                    nd.stream_order,
                    ST_Distance(
                        ST_SetSRID(ST_GeomFromText(nd.outlet_coordinates), 4326)::geography,
                        pt.pt::geography
                    ) / 1000.0 as outlet_distance
                FROM nearest_drainage nd, point_geom pt
                WHERE nd.outlet_type IN ('ocean', 'sea', 'gulf', 'bay', 'great_lake')
                ORDER BY outlet_distance ASC
                LIMIT 1;
                """
                
                result = await self.db_manager.execute_query(hydro_query, (lon, lat))
                
                if result and len(result) > 0:
                    row = result[0]
                    
                    # Hydrological distance approximation
                    stream_dist = row.get('stream_distance', 0)
                    outlet_dist = row.get('outlet_distance', 0)
                    total_distance = stream_dist + outlet_dist
                    
                    return {
                        'distance_to_coast_km': round(total_distance, 2),
                        'coastal_type': row.get('outlet_type'),
                        'drainage_pathway': {
                            'stream_distance_km': stream_dist,
                            'outlet_distance_km': outlet_dist,
                            'stream_order': row.get('stream_order')
                        },
                        'confidence_score': 0.4,  # Lower confidence for drainage-based estimates
                        'uncertainty_km': total_distance * 0.3  # 30% uncertainty
                    }
                    
        except Exception as e:
            self.logger.error(f"Hydrological network analysis error: {e}")
        
        return None

    async def _enhanced_geometric_coastal_approximation(self, lat: float, lon: float) -> Dict[str, Any]:
        """Enhanced geometric approximation with refined coastal boundaries"""
        try:
            # High-resolution continental boundary database
            continental_coastlines = {
                # North American coastlines (detailed)
                'pacific_coast': [
                    {'lat_range': (32.0, 49.0), 'lon_approx': -124.5, 'type': 'ocean'},
                    {'lat_range': (25.0, 32.0), 'lon_approx': -117.0, 'type': 'ocean'}  # California coast
                ],
                'atlantic_coast': [
                    {'lat_range': (25.0, 45.0), 'lon_approx': -70.0, 'type': 'ocean'},
                    {'lat_range': (45.0, 70.0), 'lon_approx': -65.0, 'type': 'ocean'}   # Maritime provinces
                ],
                'gulf_coast': [
                    {'lat_range': (25.0, 30.5), 'lon_range': (-97.0, -80.0), 'lat_approx': 26.0, 'type': 'gulf'}
                ],
                # Great Lakes (detailed boundaries)
                'great_lakes': [
                    {'name': 'Superior', 'center': (47.7, -87.5), 'radius': 2.5},
                    {'name': 'Michigan', 'center': (44.0, -87.0), 'radius': 2.0},
                    {'name': 'Huron', 'center': (44.8, -82.4), 'radius': 1.5},
                    {'name': 'Erie', 'center': (42.0, -81.0), 'radius': 1.2},
                    {'name': 'Ontario', 'center': (43.7, -77.9), 'radius': 1.0}
                ]
            }
            
            min_distance = float('inf')
            nearest_feature = None
            coastal_type = 'inland'
            
            # Analyze Pacific coast
            for coast_segment in continental_coastlines['pacific_coast']:
                if coast_segment['lat_range'][0] <= lat <= coast_segment['lat_range'][1]:
                    distance = abs(lon - coast_segment['lon_approx']) * self._longitude_to_km_factor(lat)
                    if distance < min_distance:
                        min_distance = distance
                        nearest_feature = 'Pacific Ocean'
                        coastal_type = coast_segment['type']
            
            # Analyze Atlantic coast
            for coast_segment in continental_coastlines['atlantic_coast']:
                if coast_segment['lat_range'][0] <= lat <= coast_segment['lat_range'][1]:
                    distance = abs(lon - coast_segment['lon_approx']) * self._longitude_to_km_factor(lat)
                    if distance < min_distance:
                        min_distance = distance
                        nearest_feature = 'Atlantic Ocean'
                        coastal_type = coast_segment['type']
            
            # Analyze Gulf coast
            for gulf_segment in continental_coastlines['gulf_coast']:
                if (gulf_segment['lat_range'][0] <= lat <= gulf_segment['lat_range'][1] and
                    gulf_segment['lon_range'][0] <= lon <= gulf_segment['lon_range'][1]):
                    distance = abs(lat - gulf_segment['lat_approx']) * 111.0  # Latitude to km
                    if distance < min_distance:
                        min_distance = distance
                        nearest_feature = 'Gulf of Mexico'
                        coastal_type = gulf_segment['type']
            
            # Analyze Great Lakes
            for lake in continental_coastlines['great_lakes']:
                lake_distance = self._calculate_distance(
                    lat, lon, lake['center'][0], lake['center'][1]
                )
                # Account for lake radius
                adjusted_distance = max(0, lake_distance - lake['radius'] * 111.0)
                
                if adjusted_distance < min_distance:
                    min_distance = adjusted_distance
                    nearest_feature = f"Lake {lake['name']}"
                    coastal_type = 'lake'
            
            # Calculate uncertainty based on method limitations
            uncertainty_km = min_distance * 0.4 if min_distance < 100 else min_distance * 0.2
            
            return {
                'distance_to_coast_km': round(min_distance, 2) if min_distance != float('inf') else 500.0,
                'nearest_water_body': nearest_feature,
                'coastal_type': coastal_type,
                'confidence_score': 0.3,  # Low confidence for geometric approximation
                'uncertainty_km': round(uncertainty_km, 2),
                'spatial_resolution_m': 10000,  # ~10km accuracy
                'approximation_method': 'enhanced_geometric'
            }
            
        except Exception as e:
            self.logger.error(f"Enhanced geometric approximation error: {e}")
            return {
                'distance_to_coast_km': 200.0,
                'coastal_type': 'inland',
                'confidence_score': 0.1,
                'error': str(e)
            }

    def _longitude_to_km_factor(self, lat: float) -> float:
        """Calculate longitude-to-kilometers conversion factor at given latitude"""
        import math
        return 111.0 * math.cos(math.radians(lat))

    def _determine_noaa_crm_dataset(self, lat: float, lon: float) -> str:
        """Determine appropriate NOAA CRM dataset based on geographic location"""
        # NOAA CRM regional datasets
        crm_datasets = {
            'atlantic': {'lat_range': (24, 45), 'lon_range': (-85, -65)},
            'gulf_mexico': {'lat_range': (24, 31), 'lon_range': (-98, -80)},
            'pacific': {'lat_range': (32, 50), 'lon_range': (-130, -115)},
            'great_lakes': {'lat_range': (41, 49), 'lon_range': (-93, -75)},
            'alaska': {'lat_range': (55, 72), 'lon_range': (-170, -130)},
            'hawaii': {'lat_range': (18, 23), 'lon_range': (-162, -154)}
        }
        
        for dataset, bounds in crm_datasets.items():
            if (bounds['lat_range'][0] <= lat <= bounds['lat_range'][1] and
                bounds['lon_range'][0] <= lon <= bounds['lon_range'][1]):
                return dataset
        
        return None  # No appropriate dataset found

