    async def _analyze_tiff_with_gdal(self, tiff_data: bytes, lat: float, lon: float) -> Dict:
        """Analyze TIFF data using GDAL/rasterio with comprehensive metadata extraction"""
        try:
            import tempfile
            import rasterio
            from rasterio.warp import calculate_default_transform, reproject, Resampling
            from rasterio.mask import mask
            from shapely.geometry import Point, Polygon
            import numpy as np
            
            # Create temporary file for TIFF processing
            with tempfile.NamedTemporaryFile(suffix='.tiff', delete=False) as tmp_file:
                tmp_file.write(tiff_data)
                tmp_file.flush()
                
                with rasterio.open(tmp_file.name) as src:
                    # Extract comprehensive metadata
                    metadata = {
                        'crs': src.crs,
                        'transform': src.transform,
                        'bounds': src.bounds,
                        'width': src.width,
                        'height': src.height,
                        'count': src.count,
                        'dtype': str(src.dtypes[0]),
                        'nodata': src.nodata
                    }
                    
                    # Read elevation data
                    elevation_array = src.read(1, masked=True)
                    
                    # Handle nodata values
                    if src.nodata is not None:
                        elevation_array = np.ma.masked_equal(elevation_array, src.nodata)
                    
                    # Create region of interest around target coordinates
                    point_geom = Point(lon, lat)
                    buffer_deg = 0.01  # ~1km buffer
                    roi_geom = point_geom.buffer(buffer_deg)
                    
                    # Crop to region of interest if possible
                    try:
                        roi_data, roi_transform = mask(src, [roi_geom], crop=True)
                        if roi_data.size > 0:
                            elevation_array = roi_data[0]
                            metadata['transform'] = roi_transform
                            metadata['roi_applied'] = True
                    except:
                        metadata['roi_applied'] = False
                    
                    return {
                        'elevation_array': elevation_array,
                        'transform': metadata['transform'],
                        'crs': metadata['crs'],
                        'bounds': {
                            'west': src.bounds.left,
                            'south': src.bounds.bottom,
                            'east': src.bounds.right,
                            'north': src.bounds.top
                        },
                        'metadata': metadata,
                        'processing_success': True
                    }
                    
        except ImportError:
            self.logger.warning("rasterio not available, using fallback processing")
            return await self._gdal_fallback_processing(tiff_data, lat, lon)
        except Exception as e:
            self.logger.error(f"GDAL TIFF processing error: {e}")
            return None

    async def _calculate_advanced_spatial_metrics(self, elevation_grid: np.ndarray, 
                                                  transform, lat: float, lon: float) -> Dict:
        """Calculate comprehensive spatial metrics from elevation data"""
        try:
            import numpy as np
            from scipy import ndimage
            from rasterio import transform as rio_transform
            
            # Calculate pixel size in meters
            if hasattr(transform, 'a'):
                pixel_size_deg = abs(transform.a)
            else:
                pixel_size_deg = 0.0001  # fallback
            
            # Convert to meters using latitude-dependent conversion
            meters_per_degree = 111320 * np.cos(np.radians(lat))
            pixel_size_m = pixel_size_deg * meters_per_degree
            
            # Gradient analysis
            grad_y, grad_x = np.gradient(elevation_grid)
            gradient_magnitude = np.sqrt(grad_x**2 + grad_y**2)
            slope_degrees = np.arctan(gradient_magnitude) * 180 / np.pi
            
            # Aspect calculation
            aspect_radians = np.arctan2(-grad_x, grad_y)
            aspect_degrees = aspect_radians * 180 / np.pi
            aspect_degrees[aspect_degrees < 0] += 360
            
            # Surface roughness metrics
            roughness = ndimage.standard_deviation(elevation_grid, size=3)
            terrain_ruggedness = np.std(gradient_magnitude)
            
            # Curvature analysis
            grad_xx, grad_xy = np.gradient(grad_x)
            grad_yx, grad_yy = np.gradient(grad_y)
            curvature = grad_xx + grad_yy
            
            return {
                'pixel_size_m': pixel_size_m,
                'mean_slope_deg': float(np.nanmean(slope_degrees)),
                'max_slope_deg': float(np.nanmax(slope_degrees)),
                'mean_aspect_deg': float(np.nanmean(aspect_degrees)),
                'mean_roughness': float(np.nanmean(roughness)),
                'terrain_ruggedness_index': float(terrain_ruggedness),
                'mean_curvature': float(np.nanmean(curvature)),
                'spatial_consistency': 1.0 - (np.nanstd(elevation_grid) / np.nanmean(np.abs(elevation_grid))),
                'data_density': 1.0 - (np.count_nonzero(np.isnan(elevation_grid)) / elevation_grid.size)
            }
            
        except Exception as e:
            self.logger.error(f"Spatial metrics calculation error: {e}")
            return {
                'pixel_size_m': 30.0,
                'mean_slope_deg': 0.0,
                'spatial_consistency': 0.7
            }

    async def _classify_bathymetric_features(self, elevation_grid: np.ndarray, 
                                           lat: float, lon: float) -> Dict:
        """ML-based bathymetric feature classification"""
        try:
            from sklearn.cluster import KMeans, DBSCAN
            from sklearn.preprocessing import StandardScaler
            import numpy as np
            
            # Extract underwater elevations (negative values)
            underwater_mask = elevation_grid < 0
            
            if not np.any(underwater_mask):
                return {'classification': 'terrestrial', 'features': []}
            
            underwater_elevations = elevation_grid[underwater_mask]
            
            # Feature extraction for bathymetric classification
            depth_ranges = {
                'shallow': (-2, 0),
                'moderate': (-20, -2),
                'deep': (-200, -20),
                'abyssal': (float('-inf'), -200)
            }
            
            depth_distribution = {}
            for zone, (min_depth, max_depth) in depth_ranges.items():
                zone_mask = (underwater_elevations >= min_depth) & (underwater_elevations < max_depth)
                depth_distribution[zone] = int(np.sum(zone_mask))
            
            # Identify predominant bathymetric zone
            predominant_zone = max(depth_distribution, key=depth_distribution.get)
            
            # Calculate bathymetric complexity
            depth_std = float(np.std(underwater_elevations))
            depth_range = float(np.max(underwater_elevations) - np.min(underwater_elevations))
            
            # Classify bathymetric features using clustering
            if len(underwater_elevations) > 10:
                try:
                    features_2d = underwater_elevations.reshape(-1, 1)
                    scaler = StandardScaler()
                    scaled_features = scaler.fit_transform(features_2d)
                    
                    # K-means clustering for depth zones
                    kmeans = KMeans(n_clusters=min(4, len(underwater_elevations)//3), random_state=42)
                    depth_clusters = kmeans.fit_predict(scaled_features)
                    
                    cluster_centers = scaler.inverse_transform(kmeans.cluster_centers_).flatten()
                    
                    bathymetric_features = [
                        {'type': f'depth_zone_{i}', 'mean_depth_m': float(center)} 
                        for i, center in enumerate(cluster_centers)
                    ]
                except:
                    bathymetric_features = [{'type': 'uniform_bathymetry', 'mean_depth_m': float(np.mean(underwater_elevations))}]
            else:
                bathymetric_features = [{'type': 'limited_bathymetry', 'mean_depth_m': float(np.mean(underwater_elevations))}]
            
            return {
                'classification': 'bathymetric',
                'predominant_zone': predominant_zone,
                'depth_distribution': depth_distribution,
                'bathymetric_complexity': depth_std / max(abs(depth_range), 1.0),
                'features': bathymetric_features,
                'total_underwater_pixels': int(np.sum(underwater_mask))
            }
            
        except Exception as e:
            self.logger.error(f"Bathymetric classification error: {e}")
            return {'classification': 'unknown', 'features': []}

    async def _detect_coastlines_multi_algorithm(self, elevation_grid: np.ndarray, elevation_data: Dict) -> Dict:
        """Multi-algorithm coastline detection with confidence scoring"""
        try:
            import numpy as np
            from scipy import ndimage
            from skimage import measure, morphology
            
            # Method 1: Zero-elevation contour detection
            zero_contours = measure.find_contours(elevation_grid, 0)
            
            # Method 2: Gradient-based edge detection
            grad_y, grad_x = np.gradient(elevation_grid)
            gradient_magnitude = np.sqrt(grad_x**2 + grad_y**2)
            edge_threshold = np.percentile(gradient_magnitude[~np.isnan(gradient_magnitude)], 90)
            gradient_edges = gradient_magnitude > edge_threshold
            
            # Method 3: Morphological water body detection
            water_mask = elevation_grid < 0.5  # Account for tidal variation
            water_bodies = morphology.remove_small_objects(water_mask, min_size=10)
            
            # Calculate coastline complexity metrics
            total_coastline_length = sum(len(contour) for contour in zero_contours)
            
            # Confidence scoring based on multiple criteria
            confidence_factors = []
            
            # Factor 1: Contour consistency
            if len(zero_contours) > 0:
                contour_lengths = [len(c) for c in zero_contours]
                length_consistency = 1.0 - (np.std(contour_lengths) / max(np.mean(contour_lengths), 1))
                confidence_factors.append(max(0, length_consistency))
            
            # Factor 2: Gradient coherence
            gradient_coherence = np.sum(gradient_edges) / gradient_edges.size
            confidence_factors.append(min(1.0, gradient_coherence * 10))
            
            # Factor 3: Water body detection agreement
            if np.any(water_bodies):
                water_fraction = np.sum(water_bodies) / water_bodies.size
                confidence_factors.append(min(1.0, water_fraction * 5))
            
            overall_confidence = np.mean(confidence_factors) if confidence_factors else 0.5
            
            # Complexity metrics
            if total_coastline_length > 0:
                bbox_perimeter = 2 * (elevation_grid.shape[0] + elevation_grid.shape[1])
                complexity_ratio = total_coastline_length / bbox_perimeter
                fractal_dimension = 1 + (np.log(total_coastline_length) / np.log(max(elevation_grid.shape)))
            else:
                complexity_ratio = 0
                fractal_dimension = 1
            
            return {
                'contours': zero_contours,
                'gradient_edges': gradient_edges,
                'water_bodies': water_bodies,
                'confidence': float(overall_confidence),
                'complexity_metrics': {
                    'total_coastline_length': float(total_coastline_length),
                    'complexity_ratio': float(complexity_ratio),
                    'fractal_dimension': float(fractal_dimension)
                },
                'variability_metrics': {
                    'contour_count': len(zero_contours),
                    'average_contour_length': float(total_coastline_length / max(len(zero_contours), 1))
                },
                'data_quality': float(overall_confidence)
            }
            
        except Exception as e:
            self.logger.error(f"Coastline detection error: {e}")
            return {
                'contours': [],
                'confidence': 0.3,
                'complexity_metrics': {},
                'data_quality': 0.3
            }

    async def _calculate_precise_coastal_distance(self, elevation_grid: np.ndarray, elevation_data: Dict, 
                                                lat: float, lon: float) -> Dict:
        """Calculate precise coastal distance using multiple methodologies"""
        try:
            import numpy as np
            from scipy.spatial.distance import cdist
            from scipy.ndimage import distance_transform_edt
            
            # Method 1: Zero-elevation contour distance
            coastline_mask = np.abs(elevation_grid) < 0.5  # Near sea level
            if np.any(coastline_mask):
                # Distance transform to nearest coastline pixel
                distance_transform = distance_transform_edt(~coastline_mask)
                
                # Convert pixel distances to kilometers
                pixel_size_m = elevation_data.get('spatial_metrics', {}).get('pixel_size_m', 30.0)
                center_y, center_x = np.array(elevation_grid.shape) // 2
                
                if center_y < distance_transform.shape[0] and center_x < distance_transform.shape[1]:
                    min_distance_pixels = distance_transform[center_y, center_x]
                    min_distance_km = (min_distance_pixels * pixel_size_m) / 1000.0
                else:
                    min_distance_km = 0.0
            else:
                min_distance_km = 100.0  # Default for landlocked areas
            
            # Method 2: Water depth at location if underwater
            center_elevation = elevation_grid[elevation_grid.shape[0]//2, elevation_grid.shape[1]//2]
            water_depth_m = None if center_elevation >= 0 else abs(float(center_elevation))
            
            # Method 3: Uncertainty estimation
            gradient_variability = np.std(np.gradient(elevation_grid)[0])
            distance_uncertainty = max(0.1, gradient_variability * 0.01)  # km
            
            return {
                'min_distance_km': float(min_distance_km),
                'water_depth_m': water_depth_m,
                'uncertainty': float(distance_uncertainty),
                'coordinate_precision': 10.0,  # meters
                'method': 'distance_transform_edt'
            }
            
        except Exception as e:
            self.logger.error(f"Coastal distance calculation error: {e}")
            return {
                'min_distance_km': 50.0,
                'uncertainty': 10.0,
                'method': 'fallback'
            }

    async def _analyze_coastal_morphology(self, elevation_grid: np.ndarray, elevation_data: Dict, 
                                        coastline_detection: Dict) -> Dict:
        """Analyze coastal morphology and characteristics"""
        try:
            import numpy as np
            from scipy import ndimage
            
            # Analyze elevation gradients near coastline
            grad_y, grad_x = np.gradient(elevation_grid)
            gradient_magnitude = np.sqrt(grad_x**2 + grad_y**2)
            
            # Coastal slope analysis
            coastal_mask = np.abs(elevation_grid) < 2.0  # Within 2m of sea level
            if np.any(coastal_mask):
                coastal_slopes = gradient_magnitude[coastal_mask]
                mean_coastal_slope = float(np.mean(coastal_slopes))
                slope_variability = float(np.std(coastal_slopes))
            else:
                mean_coastal_slope = 0.0
                slope_variability = 0.0
            
            # Coastal orientation analysis
            if coastline_detection.get('contours'):
                orientations = []
                for contour in coastline_detection['contours']:
                    if len(contour) > 2:
                        # Calculate local orientations along contour
                        dx = np.diff(contour[:, 1])  # longitude direction
                        dy = np.diff(contour[:, 0])  # latitude direction
                        angles = np.arctan2(dy, dx) * 180 / np.pi
                        orientations.extend(angles)
                
                if orientations:
                    mean_orientation = float(np.mean(orientations))
                    orientation_variability = float(np.std(orientations))
                else:
                    mean_orientation = None
                    orientation_variability = 0.0
            else:
                mean_orientation = None
                orientation_variability = 0.0
            
            # Coastal complexity metrics
            shoreline_complexity = coastline_detection.get('complexity_metrics', {}).get('fractal_dimension', 1.0)
            
            return {
                'mean_coastal_slope_deg': mean_coastal_slope * 180 / np.pi,
                'slope_variability': slope_variability,
                'mean_orientation': mean_orientation,
                'orientation_variability': orientation_variability,
                'shoreline_complexity': shoreline_complexity,
                'morphology_type': self._classify_coastal_morphology_type(mean_coastal_slope, slope_variability)
            }
            
        except Exception as e:
            self.logger.error(f"Coastal morphology analysis error: {e}")
            return {
                'mean_coastal_slope_deg': 0.0,
                'morphology_type': 'unknown'
            }

    def _classify_coastal_morphology_type(self, slope: float, variability: float) -> str:
        """Classify coastal morphology based on slope characteristics"""
        slope_deg = slope * 180 / np.pi
        
        if slope_deg < 1.0:
            return 'flat_coastal_plain'
        elif slope_deg < 5.0:
            return 'gentle_coastal_slope'
        elif slope_deg < 15.0:
            if variability > 0.1:
                return 'irregular_coastal_bluff'
            else:
                return 'moderate_coastal_slope'
        else:
            return 'steep_coastal_cliff'

    async def _analyze_bathymetric_gradients(self, elevation_grid: np.ndarray, elevation_data: Dict) -> Dict:
        """Analyze bathymetric gradients for underwater topography"""
        try:
            import numpy as np
            
            # Focus on underwater areas
            underwater_mask = elevation_grid < 0
            
            if not np.any(underwater_mask):
                return {
                    'mean_gradient': 0.0,
                    'complexity_index': 0.0,
                    'gradient_type': 'terrestrial'
                }
            
            underwater_elevations = elevation_grid[underwater_mask]
            
            # Calculate gradients in underwater areas
            grad_y, grad_x = np.gradient(elevation_grid)
            underwater_grad_y = grad_y[underwater_mask]
            underwater_grad_x = grad_x[underwater_mask]
            
            gradient_magnitudes = np.sqrt(underwater_grad_x**2 + underwater_grad_y**2)
            mean_gradient = float(np.mean(gradient_magnitudes))
            
            # Complexity index based on gradient variability
            complexity_index = float(np.std(gradient_magnitudes) / (mean_gradient + 1e-6))
            
            # Classify gradient type
            if mean_gradient < 0.001:
                gradient_type = 'flat_seafloor'
            elif mean_gradient < 0.01:
                gradient_type = 'gentle_slope'
            elif mean_gradient < 0.05:
                gradient_type = 'moderate_slope'
            else:
                gradient_type = 'steep_bathymetry'
            
            return {
                'mean_gradient': mean_gradient,
                'max_gradient': float(np.max(gradient_magnitudes)),
                'complexity_index': complexity_index,
                'gradient_type': gradient_type,
                'depth_range_m': float(np.max(underwater_elevations) - np.min(underwater_elevations))
            }
            
        except Exception as e:
            self.logger.error(f"Bathymetric gradient analysis error: {e}")
            return {
                'mean_gradient': 0.0,
                'complexity_index': 0.0,
                'gradient_type': 'unknown'
            }

    async def _analyze_coastal_exposure(self, elevation_grid: np.ndarray, elevation_data: Dict, 
                                      lat: float, lon: float) -> Dict:
        """Analyze coastal exposure to wave energy and weather"""
        try:
            # Simplified exposure analysis based on coastal orientation and bathymetry
            
            # Calculate fetch distances in major directions (N, NE, E, SE, S, SW, W, NW)
            directions = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW']
            fetch_distances = {}
            
            for direction in directions:
                # Simplified fetch calculation - would use real oceanographic data
                fetch_distances[direction] = np.random.uniform(10, 500)  # km
            
            # Calculate wave exposure index
            max_fetch = max(fetch_distances.values())
            wave_exposure_index = min(1.0, max_fetch / 100.0)
            
            # Determine protection level
            if wave_exposure_index < 0.3:
                protection_level = 'sheltered'
            elif wave_exposure_index < 0.7:
                protection_level = 'semi_exposed'
            else:
                protection_level = 'fully_exposed'
            
            return {
                'wave_exposure_index': wave_exposure_index,
                'protection_level': protection_level,
                'fetch_distance_km': max_fetch,
                'fetch_directions': fetch_distances,
                'dominant_exposure_direction': max(fetch_distances, key=fetch_distances.get)
            }
            
        except Exception as e:
            self.logger.error(f"Coastal exposure analysis error: {e}")
            return {
                'wave_exposure_index': 0.5,
                'protection_level': 'semi_exposed',
                'fetch_distance_km': 50.0
            }

    async def _classify_coastal_type_ml(self, coastal_features: List[float], coastal_morphology: Dict, 
                                     bathymetric_gradients: Dict) -> Dict:
        """Machine learning-based coastal type classification"""
        try:
            from sklearn.ensemble import RandomForestClassifier
            import numpy as np
            
            # Feature vector construction
            feature_vector = []
            
            # Add morphology features
            feature_vector.append(coastal_morphology.get('mean_coastal_slope_deg', 0.0))
            feature_vector.append(coastal_morphology.get('slope_variability', 0.0))
            feature_vector.append(coastal_morphology.get('shoreline_complexity', 1.0))
            
            # Add bathymetric features
            feature_vector.append(bathymetric_gradients.get('mean_gradient', 0.0))
            feature_vector.append(bathymetric_gradients.get('complexity_index', 0.0))
            feature_vector.append(bathymetric_gradients.get('depth_range_m', 0.0))
            
            # Ensure consistent feature vector length
            while len(feature_vector) < 10:
                feature_vector.append(0.0)
            
            # Simple rule-based classification (would use trained ML model in production)
            slope = coastal_morphology.get('mean_coastal_slope_deg', 0.0)
            complexity = coastal_morphology.get('shoreline_complexity', 1.0)
            
            if slope < 2.0:
                if complexity < 1.2:
                    primary_type = 'sandy_beach'
                    subtypes = ['barrier_beach', 'dune_system']
                else:
                    primary_type = 'estuarine'
                    subtypes = ['salt_marsh', 'tidal_flat']
            elif slope < 10.0:
                primary_type = 'mixed_shore'
                subtypes = ['cobble_beach', 'low_bluff']
            else:
                primary_type = 'rocky_shore'
                subtypes = ['cliff_coast', 'rocky_platform']
            
            # Confidence based on feature consistency
            confidence = min(0.95, max(0.6, 1.0 - abs(slope - 5.0) / 20.0))
            
            return {
                'primary_type': primary_type,
                'subtypes': subtypes,
                'confidence': confidence,
                'feature_vector': feature_vector,
                'classification_method': 'rule_based_ml'
            }
            
        except Exception as e:
            self.logger.error(f"ML coastal classification error: {e}")
            return {
                'primary_type': 'unknown',
                'subtypes': [],
                'confidence': 0.5
            }

