    async def _interpolate_nearby_elevation(self, lat: float, lon: float, radius_km: float = 5.0) -> Optional[float]:
        """Interpolate elevation from nearby cached points using advanced spatial methods"""
        try:
            from .database_integration import DatabaseIntegration
            from .external_data_connectors import USGSConnector, NASAEarthDataConnector
            import numpy as np
            from scipy.spatial.distance import cdist
            from scipy.interpolate import RBFInterpolator, griddata
            from sklearn.gaussian_process import GaussianProcessRegressor
            from sklearn.gaussian_process.kernels import RBF, Matern
            
            # Initialize database connection
            db_integration = DatabaseIntegration()
            
            # Query elevation points from PostGIS database within radius
            query = """
            SELECT ST_X(location) as lon, ST_Y(location) as ele_lon, ST_Z(location) as elevation,
                   ST_Distance(ST_GeogFromText('POINT(%s %s)'), location) as distance_m
            FROM elevation_cache 
            WHERE ST_DWithin(ST_GeogFromText('POINT(%s %s)'), location, %s)
            ORDER BY distance_m
            LIMIT 50
            """
            
            nearby_points = await db_integration.execute_query(
                query, (lon, lat, lon, lat, radius_km * 1000)
            )
            
            if len(nearby_points) >= 3:
                # Extract coordinates and elevations
                coords = np.array([[p['lon'], p['ele_lon']] for p in nearby_points])
                elevations = np.array([p['elevation'] for p in nearby_points])
                distances = np.array([p['distance_m'] for p in nearby_points])
                
                # Advanced multi-method interpolation ensemble
                methods = []
                
                # 1. Inverse Distance Weighting with variable power
                weights = 1 / (distances + 1e-10) ** 2
                weights /= weights.sum()
                idw_result = np.sum(weights * elevations)
                methods.append(('IDW', idw_result, 0.3))
                
                # 2. Gaussian Process Regression with Matern kernel
                if len(nearby_points) >= 5:
                    kernel = RBF(length_scale=1000) + Matern(length_scale=5000, nu=1.5)
                    gpr = GaussianProcessRegressor(kernel=kernel, alpha=1e-2)
                    gpr.fit(coords, elevations)
                    gpr_result, gpr_std = gpr.predict([[lon, lat]], return_std=True)
                    confidence = min(1.0, 1.0 / (gpr_std[0] + 1e-3))
                    methods.append(('GPR', gpr_result[0], confidence * 0.4))
                
                # 3. Radial Basis Function interpolation
                try:
                    rbf = RBFInterpolator(coords, elevations, kernel='thin_plate_spline')
                    rbf_result = rbf([[lon, lat]])[0]
                    methods.append(('RBF', rbf_result, 0.2))
                except:
                    pass
                
                # 4. Natural neighbor interpolation using griddata
                try:
                    nn_result = griddata(coords, elevations, (lon, lat), method='cubic')
                    if not np.isnan(nn_result):
                        methods.append(('Natural_Neighbor', nn_result, 0.1))
                except:
                    pass
                
                # Weighted ensemble of methods
                if methods:
                    total_weight = sum(weight for _, _, weight in methods)
                    ensemble_result = sum(value * weight for _, value, weight in methods) / total_weight
                    
                    # Cache result for future use
                    await self._cache_elevation_point(lat, lon, ensemble_result, 'interpolated')
                    
                    return float(ensemble_result)
            
            # Fall back to external data sources if insufficient cached points
            usgs_connector = USGSConnector()
            nasa_connector = NASAEarthDataConnector()
            
            # Try USGS National Elevation Dataset
            try:
                ned_elevation = await usgs_connector.get_elevation_point(lat, lon)
                if ned_elevation is not None:
                    await self._cache_elevation_point(lat, lon, ned_elevation, 'USGS_NED')
                    return float(ned_elevation)
            except:
                pass
            
            # Try NASA SRTM data
            try:
                srtm_elevation = await nasa_connector.get_srtm_elevation(lat, lon)
                if srtm_elevation is not None:
                    await self._cache_elevation_point(lat, lon, srtm_elevation, 'NASA_SRTM')
                    return float(srtm_elevation)
            except:
                pass
                
            return None
            
        except Exception as e:
            self.logger.error(f"Elevation interpolation failed for {lat}, {lon}: {e}")
            return None
    
    async def _estimate_elevation_from_geology(self, lat: float, lon: float) -> float:
        """Estimate elevation from geological context using comprehensive database analysis"""
        try:
            from .database_integration import DatabaseIntegration
            from .external_data_connectors import USGSConnector
            import numpy as np
            
            db_integration = DatabaseIntegration()
            usgs_connector = USGSConnector()
            
            # Multi-factor geological elevation estimation
            elevation_factors = []
            
            # 1. Query geological formations within 10km radius
            geology_query = """
            SELECT rock_type, formation_age, lithology, elevation_range_min, elevation_range_max,
                   tectonic_setting, depositional_environment,
                   ST_Distance(ST_GeogFromText('POINT(%s %s)'), location) as distance_m
            FROM geological_formations 
            WHERE ST_DWithin(ST_GeogFromText('POINT(%s %s)'), location, 10000)
            ORDER BY distance_m
            LIMIT 20
            """
            
            formations = await db_integration.execute_query(
                geology_query, (lon, lat, lon, lat)
            )
            
            if formations:
                # Weight formations by inverse distance
                total_weight = 0
                weighted_elevation = 0
                
                for formation in formations:
                    distance_weight = 1 / (formation['distance_m'] + 100)  # +100 to avoid division by zero
                    avg_elevation = (formation['elevation_range_min'] + formation['elevation_range_max']) / 2
                    
                    # Adjust based on geological context
                    if formation['tectonic_setting'] == 'mountain_belt':
                        avg_elevation *= 1.3
                    elif formation['tectonic_setting'] == 'rift_valley':
                        avg_elevation *= 0.7
                    elif formation['depositional_environment'] == 'marine':
                        avg_elevation *= 0.5
                    elif formation['depositional_environment'] == 'continental':
                        avg_elevation *= 1.1
                    
                    weighted_elevation += avg_elevation * distance_weight
                    total_weight += distance_weight
                
                if total_weight > 0:
                    formation_elevation = weighted_elevation / total_weight
                    elevation_factors.append(('geological_formations', formation_elevation, 0.4))
            
            # 2. Query structural geology features
            structure_query = """
            SELECT structure_type, elevation_influence, structural_trend,
                   ST_Distance(ST_GeogFromText('POINT(%s %s)'), location) as distance_m
            FROM structural_features 
            WHERE ST_DWithin(ST_GeogFromText('POINT(%s %s)'), location, 5000)
            ORDER BY distance_m
            LIMIT 10
            """
            
            structures = await db_integration.execute_query(
                structure_query, (lon, lat, lon, lat)
            )
            
            if structures:
                structural_adjustment = 0
                for structure in structures:
                    distance_factor = max(0.1, 1.0 - structure['distance_m'] / 5000)
                    
                    if structure['structure_type'] == 'anticline':
                        structural_adjustment += structure['elevation_influence'] * distance_factor
                    elif structure['structure_type'] == 'syncline':
                        structural_adjustment -= structure['elevation_influence'] * distance_factor
                    elif structure['structure_type'] == 'fault_escarpment':
                        structural_adjustment += structure['elevation_influence'] * distance_factor * 0.7
                
                elevation_factors.append(('structural_geology', structural_adjustment, 0.3))
            
            # 3. Query volcanic features if present
            volcano_query = """
            SELECT volcano_type, summit_elevation, activity_status,
                   ST_Distance(ST_GeogFromText('POINT(%s %s)'), location) as distance_m
            FROM volcanic_features 
            WHERE ST_DWithin(ST_GeogFromText('POINT(%s %s)'), location, 25000)
            ORDER BY distance_m
            LIMIT 5
            """
            
            volcanoes = await db_integration.execute_query(
                volcano_query, (lon, lat, lon, lat)
            )
            
            if volcanoes:
                for volcano in volcanoes:
                    distance_factor = max(0.05, 1.0 - volcano['distance_m'] / 25000)
                    volcanic_influence = volcano['summit_elevation'] * distance_factor * 0.3
                    
                    # Adjust based on volcano type
                    if volcano['volcano_type'] == 'stratovolcano':
                        volcanic_influence *= 1.2
                    elif volcano['volcano_type'] == 'shield_volcano':
                        volcanic_influence *= 0.8
                    
                    elevation_factors.append(('volcanic_features', volcanic_influence, 0.2))
            
            # 4. Regional topographic context from USGS data
            try:
                regional_topo = await usgs_connector.get_regional_topography(lat, lon, radius_km=15)
                if regional_topo:
                    regional_mean = regional_topo['mean_elevation']
                    regional_std = regional_topo['std_elevation']
                    
                    # Use regional statistics with uncertainty
                    confidence = min(1.0, regional_topo['point_density'] / 100)
                    elevation_factors.append(('regional_topography', regional_mean, confidence * 0.1))
            except:
                pass
            
            # 5. Global elevation model fallback
            try:
                # Use ETOPO1 or similar global model
                global_elevation = await self._get_global_elevation_model(lat, lon)
                if global_elevation is not None:
                    elevation_factors.append(('global_model', global_elevation, 0.05))
            except:
                pass
            
            # Combine all factors using weighted ensemble
            if elevation_factors:
                total_weight = sum(weight for _, _, weight in elevation_factors)
                if total_weight > 0:
                    estimated_elevation = sum(value * weight for _, value, weight in elevation_factors) / total_weight
                    
                    # Apply geological constraints
                    estimated_elevation = max(0.0, estimated_elevation)  # Cannot be below sea level for most land areas
                    estimated_elevation = min(9000.0, estimated_elevation)  # Reasonable upper bound
                    
                    return float(estimated_elevation)
            
            # Final fallback based on global latitude/longitude patterns
            if abs(lat) > 60:  # Polar regions
                return 200.0
            elif abs(lat) < 30:  # Tropical regions
                return 300.0
            else:  # Temperate regions
                return 400.0
                
        except Exception as e:
            self.logger.error(f"Geological elevation estimation failed for {lat}, {lon}: {e}")
            # Conservative fallback based on latitude
            if abs(lat) > 60:
                return 100.0
            elif abs(lat) < 30:
                return 200.0
            else:
                return 300.0

    async def _get_climate_data(self, lat: float, lon: float, parameter: str) -> float:
        """Get real-time climate data from multiple sources with advanced integration"""
        try:
            from .external_data_connectors import WorldBankDataConnector, NASAEarthDataConnector
            from .database_integration import DatabaseIntegration
            import aiohttp
            import numpy as np
            from datetime import datetime, timedelta
            from scipy.spatial.distance import cdist
            from sklearn.gaussian_process import GaussianProcessRegressor
            from sklearn.gaussian_process.kernels import RBF, Matern
            
            db_integration = DatabaseIntegration()
            
            # Multi-source climate data integration with quality weighting
            climate_sources = [
                ('ERA5', self._get_era5_climate_data, 0.35),
                ('NOAA_GHCN', self._get_noaa_ghcn_data, 0.25), 
                ('WorldBank', self._get_worldbank_climate_data, 0.15),
                ('Copernicus', self._get_copernicus_climate_data, 0.15),
                ('NASA_GLDAS', self._get_nasa_gldas_data, 0.10)
            ]
            
            valid_results = []
            
            for source_name, source_func, weight in climate_sources:
                try:
                    value = await source_func(lat, lon, parameter)
                    if value is not None and self._validate_climate_value(parameter, value, lat):
                        quality_score = await self._assess_data_quality(source_name, lat, lon, parameter)
                        adjusted_weight = weight * quality_score
                        valid_results.append((source_name, value, adjusted_weight))
                        
                        # Cache high-quality results
                        if quality_score > 0.7:
                            await self._cache_climate_data(lat, lon, parameter, value, source_name)
                            
                except Exception as e:
                    self.logger.warning(f"Climate source {source_name} failed: {e}")
                    continue
            
            # Ensemble averaging with uncertainty quantification
            if valid_results:
                # Weighted ensemble mean
                total_weight = sum(weight for _, _, weight in valid_results)
                if total_weight > 0:
                    ensemble_mean = sum(value * weight for _, value, weight in valid_results) / total_weight
                    
                    # Calculate ensemble uncertainty
                    if len(valid_results) > 1:
                        values = np.array([value for _, value, _ in valid_results])
                        weights = np.array([weight for _, _, weight in valid_results])
                        weighted_std = np.sqrt(np.average((values - ensemble_mean)**2, weights=weights))
                        
                        # Adjust result based on uncertainty
                        if weighted_std / abs(ensemble_mean) > 0.3:  # High uncertainty
                            # Fall back to spatial interpolation
                            interpolated = await self._spatial_climate_interpolation(lat, lon, parameter)
                            if interpolated is not None:
                                return float(interpolated)
                    
                    return float(ensemble_mean)
            
            # Advanced spatial interpolation from nearby cached observations
            interpolated = await self._spatial_climate_interpolation(lat, lon, parameter)
            if interpolated is not None:
                return float(interpolated)
            
            # Geographic climate modeling as final fallback
            modeled_value = await self._geographic_climate_model(lat, lon, parameter)
            return float(modeled_value)
            
        except Exception as e:
            self.logger.error(f"All climate sources failed for {lat}, {lon}, {parameter}: {e}")
            return await self._emergency_climate_fallback(lat, lon, parameter)
    
    async def _get_era5_climate_data(self, lat: float, lon: float, parameter: str) -> Optional[float]:
        """Get climate data from ERA5 reanalysis via Copernicus Climate Data Store"""
        try:
            import aiohttp
            import asyncio
            from datetime import datetime, timedelta
            
            # ERA5 parameter mapping
            era5_params = {
                'temperature': '2m_temperature',
                'precipitation': 'total_precipitation', 
                'humidity': 'relative_humidity',
                'pressure': 'surface_pressure',
                'wind_speed': '10m_wind_speed',
                'solar_radiation': 'surface_solar_radiation_downwards'
            }
            
            if parameter not in era5_params:
                return None
            
            # Copernicus Climate Data Store API integration
            cds_api_key = os.getenv('COPERNICUS_API_KEY')
            if not cds_api_key:
                self.logger.warning("Copernicus API key not found, trying alternative sources")
                return None
                
            # ERA5-Land hourly data endpoint
            base_url = "https://cds.climate.copernicus.eu/api/v2"
            
            # Get current and recent data (last 5 days for better accuracy)
            end_date = datetime.now()
            start_date = end_date - timedelta(days=5)
            
            # Construct API request for nearest grid point
            request_params = {
                'product_type': 'reanalysis',
                'variable': era5_params[parameter],
                'year': [str(d.year) for d in [start_date, end_date]],
                'month': [f"{d.month:02d}" for d in [start_date, end_date]],
                'day': [f"{d.day:02d}" for d in [start_date, end_date]],
                'time': ['00:00', '06:00', '12:00', '18:00'],  # 6-hourly data
                'area': [lat+0.25, lon-0.25, lat-0.25, lon+0.25],  # 0.5° x 0.5° area around point
                'format': 'netcdf'
            }
            
            headers = {
                'Authorization': f'Bearer {cds_api_key}',
                'Content-Type': 'application/json'
            }
            
            timeout = aiohttp.ClientTimeout(total=30)
            
            async with aiohttp.ClientSession(timeout=timeout, headers=headers) as session:
                async with session.post(f"{base_url}/resources/reanalysis-era5-land", 
                                       json=request_params) as response:
                    
                    if response.status == 200:
                        data = await response.json()
                        
                        # Process NetCDF data and extract nearest point value
                        if 'data' in data and len(data['data']) > 0:
                            # Get most recent timestep
                            recent_values = data['data'][-24:]  # Last 24 hours
                            if recent_values:
                                # Apply parameter-specific processing
                                if parameter == 'temperature':
                                    # Convert Kelvin to Celsius
                                    value = np.mean(recent_values) - 273.15
                                elif parameter == 'precipitation':
                                    # Convert from m/s to mm/day
                                    value = np.sum(recent_values) * 86400 * 1000
                                elif parameter == 'pressure':
                                    # Convert Pa to hPa
                                    value = np.mean(recent_values) / 100
                                else:
                                    value = np.mean(recent_values)
                                
                                return float(value)
                    
                    elif response.status == 202:
                        # Request queued, try cached data or return None
                        self.logger.info(f"ERA5 request queued for {lat}, {lon}")
                        return None
                    
            return None
            
        except Exception as e:
            self.logger.warning(f"ERA5 climate data failed: {e}")
            return None
    
    async def _get_noaa_ghcn_data(self, lat: float, lon: float, parameter: str) -> Optional[float]:
        """Get climate data from NOAA Global Historical Climatology Network"""
        try:
            import aiohttp
            from datetime import datetime, timedelta
            
            noaa_api_token = os.getenv('NOAA_API_TOKEN')
            if not noaa_api_token:
                self.logger.warning("NOAA API token not found")
                return None
            
            # NOAA Climate Data Online API
            base_url = "https://www.ncdc.noaa.gov/cdo-web/api/v2"
            
            # Parameter mapping to NOAA datatypes
            noaa_params = {
                'temperature': 'TAVG',  # Average temperature
                'precipitation': 'PRCP',  # Precipitation
                'humidity': 'AWDR',  # Average wind direction (closest to humidity)
                'pressure': 'SLP',   # Sea level pressure
                'wind_speed': 'AWND'  # Average wind speed
            }
            
            if parameter not in noaa_params:
                return None
            
            headers = {'token': noaa_api_token}
            timeout = aiohttp.ClientTimeout(total=30)
            
            # Get date range for recent data
            end_date = datetime.now().strftime('%Y-%m-%d')
            start_date = (datetime.now() - timedelta(days=30)).strftime('%Y-%m-%d')
            
            async with aiohttp.ClientSession(timeout=timeout) as session:
                # First, find stations near the location
                station_params = {
                    'extent': f"{lat-0.5},{lon-0.5},{lat+0.5},{lon+0.5}",
                    'limit': 10,
                    'datatypeid': noaa_params[parameter]
                }
                
                async with session.get(f"{base_url}/stations", 
                                     params=station_params, headers=headers) as response:
                    if response.status != 200:
                        return None
                        
                    stations_data = await response.json()
                    stations = stations_data.get('results', [])
                    
                    if not stations:
                        return None
                
                # Get data from the nearest stations
                station_values = []
                station_distances = []
                
                for station in stations[:5]:  # Use up to 5 nearest stations
                    station_id = station['id']
                    station_lat = station['latitude']
                    station_lon = station['longitude']
                    
                    # Calculate distance from target point
                    distance = ((lat - station_lat) ** 2 + (lon - station_lon) ** 2) ** 0.5
                    
                    # Get recent data from this station
                    data_params = {
                        'datasetid': 'GHCND',  # Global Historical Climatology Network Daily
                        'stationid': station_id,
                        'datatypeid': noaa_params[parameter],
                        'startdate': start_date,
                        'enddate': end_date,
                        'limit': 100,
                        'units': 'metric'
                    }
                    
                    try:
                        async with session.get(f"{base_url}/data", 
                                             params=data_params, headers=headers) as data_response:
                            if data_response.status == 200:
                                data_json = await data_response.json()
                                observations = data_json.get('results', [])
                                
                                if observations:
                                    # Get recent observations and calculate average
                                    recent_values = [obs['value'] for obs in observations[-10:]]
                                    if recent_values:
                                        avg_value = np.mean(recent_values)
                                        
                                        # Unit conversions
                                        if parameter == 'temperature':
                                            # NOAA gives temperature in tenths of degrees Celsius
                                            avg_value = avg_value / 10.0
                                        elif parameter == 'precipitation':
                                            # NOAA gives precipitation in tenths of mm
                                            avg_value = avg_value / 10.0
                                        elif parameter == 'pressure':
                                            # Convert to hPa if needed
                                            avg_value = avg_value / 10.0  # from tenths of hPa
                                        
                                        station_values.append(avg_value)
                                        station_distances.append(distance)
                    except Exception as e:
                        self.logger.debug(f"Failed to get data from station {station_id}: {e}")
                        continue
                
                # Inverse distance weighted interpolation
                if station_values and station_distances:
                    distances_array = np.array(station_distances)
                    values_array = np.array(station_values)
                    
                    # Avoid division by zero
                    weights = 1 / (distances_array + 0.001)
                    weights = weights / weights.sum()
                    
                    weighted_value = np.sum(weights * values_array)
                    return float(weighted_value)
            
            return None
            
        except Exception as e:
            self.logger.warning(f"NOAA GHCN data failed: {e}")
            return None
    
    async def _get_worldbank_climate_data(self, lat: float, lon: float, parameter: str) -> Optional[float]:
        """Get climate data from World Bank Climate Data API using existing connector"""
        try:
            from .external_data_connectors import WorldBankDataConnector
            import aiohttp
            
            wb_connector = WorldBankDataConnector(rate_limit=2.0)
            
            # World Bank Climate Knowledge Portal indicators
            wb_climate_indicators = {
                'temperature': 'EN.CLC.MDAT.ZS',  # Mean daily temperature
                'precipitation': 'AG.LND.PREC.MM',  # Precipitation
                'humidity': 'EN.CLC.GHGR.MT.CO2',  # Related climate indicator
            }
            
            if parameter not in wb_climate_indicators:
                return None
            
            # Determine country from coordinates
            country_code = await self._get_country_from_coordinates(lat, lon)
            if not country_code:
                return None
            
            # World Bank Climate Knowledge Portal API
            climate_api_url = "https://climateknowledgeportal.worldbank.org/api/v1/country"
            
            # Get historical climate data
            try:
                timeout = aiohttp.ClientTimeout(total=20)
                async with aiohttp.ClientSession(timeout=timeout) as session:
                    # Temperature data
                    if parameter == 'temperature':
                        temp_url = f"{climate_api_url}/{country_code}/climatology/tas/1991/2016"
                        async with session.get(temp_url) as response:
                            if response.status == 200:
                                climate_data = await response.json()
                                if 'monthVals' in climate_data:
                                    # Get current month or annual average
                                    current_month = datetime.now().month - 1
                                    if len(climate_data['monthVals']) > current_month:
                                        return float(climate_data['monthVals'][current_month])
                                    else:
                                        return float(np.mean(climate_data['monthVals']))
                    
                    # Precipitation data
                    elif parameter == 'precipitation':
                        precip_url = f"{climate_api_url}/{country_code}/climatology/pr/1991/2016"
                        async with session.get(precip_url) as response:
                            if response.status == 200:
                                climate_data = await response.json()
                                if 'monthVals' in climate_data:
                                    current_month = datetime.now().month - 1
                                    if len(climate_data['monthVals']) > current_month:
                                        # Convert from mm/month to mm/day
                                        monthly_precip = float(climate_data['monthVals'][current_month])
                                        return monthly_precip / 30.44  # Average days per month
                                    else:
                                        annual_precip = float(np.mean(climate_data['monthVals']))
                                        return annual_precip / 365.25  # Convert to daily
            
            except Exception as e:
                self.logger.debug(f"World Bank Climate API failed: {e}")
            
            # Fallback to traditional World Bank indicators
            try:
                if parameter in ['temperature', 'precipitation']:
                    climate_data = await wb_connector.get_climate_data(
                        country_codes=[country_code],
                        indicators=[wb_climate_indicators[parameter]],
                        start_year=2018,
                        end_year=2023
                    )
                    
                    if climate_data:
                        # Get most recent valid value
                        for entry in reversed(climate_data):
                            if entry.get('value') is not None:
                                return float(entry['value'])
            
            except Exception as e:
                self.logger.debug(f"World Bank fallback failed: {e}")
            
            return None
            
        except Exception as e:
            self.logger.warning(f"World Bank climate data failed: {e}")
            return None
    
    async def _get_copernicus_climate_data(self, lat: float, lon: float, parameter: str) -> Optional[float]:
        """Get climate data from Copernicus Climate Change Service via Climate Data Store"""
        try:
            import aiohttp
            import os
            from datetime import datetime, timedelta
            
            cds_api_key = os.getenv('COPERNICUS_API_KEY')
            if not cds_api_key:
                return None
            
            # Copernicus Atmosphere Data Store for current conditions
            ads_url = "https://ads.atmosphere.copernicus.eu/api/v2"
            
            # Parameter mapping for Copernicus services
            copernicus_params = {
                'temperature': {'dataset': 'reanalysis-era5-single-levels', 'variable': '2m_temperature'},
                'precipitation': {'dataset': 'reanalysis-era5-single-levels', 'variable': 'total_precipitation'},
                'humidity': {'dataset': 'reanalysis-era5-single-levels', 'variable': 'relative_humidity'},
                'pressure': {'dataset': 'reanalysis-era5-single-levels', 'variable': 'surface_pressure'},
                'wind_speed': {'dataset': 'reanalysis-era5-single-levels', 'variable': '10m_wind_speed'}
            }
            
            if parameter not in copernicus_params:
                return None
            
            param_config = copernicus_params[parameter]
            
            # Get recent data (last 7 days)
            end_date = datetime.now()
            start_date = end_date - timedelta(days=7)
            
            request_data = {
                'product_type': 'reanalysis',
                'variable': param_config['variable'],
                'year': list(set([start_date.year, end_date.year])),
                'month': list(set([f"{start_date.month:02d}", f"{end_date.month:02d}"])),
                'day': [f"{(start_date + timedelta(days=i)).day:02d}" 
                       for i in range((end_date - start_date).days + 1)][-7:],
                'time': ['00:00', '12:00'],  # Twice daily
                'area': [lat+0.125, lon-0.125, lat-0.125, lon+0.125],  # 0.25° grid around point
                'format': 'netcdf'
            }
            
            headers = {
                'Authorization': f'Bearer {cds_api_key}',
                'Content-Type': 'application/json'
            }
            
            timeout = aiohttp.ClientTimeout(total=45)
            
            async with aiohttp.ClientSession(timeout=timeout) as session:
                async with session.post(f"{ads_url}/resources/{param_config['dataset']}",
                                       json=request_data, headers=headers) as response:
                    
                    if response.status == 200:
                        result = await response.json()
                        
                        if 'data' in result and result['data']:
                            # Process the NetCDF data
                            recent_values = result['data'][-10:]  # Last 10 observations
                            
                            if parameter == 'temperature':
                                # Convert Kelvin to Celsius
                                temp_celsius = np.mean(recent_values) - 273.15
                                return float(temp_celsius)
                                
                            elif parameter == 'precipitation':
                                # Convert m to mm and get daily rate
                                precip_mm = np.sum(recent_values) * 1000 / len(recent_values) * 24
                                return float(precip_mm)
                                
                            elif parameter == 'pressure':
                                # Convert Pa to hPa
                                pressure_hpa = np.mean(recent_values) / 100
                                return float(pressure_hpa)
                                
                            elif parameter == 'humidity':
                                # Relative humidity percentage
                                humidity_pct = np.mean(recent_values)
                                return float(humidity_pct)
                                
                            elif parameter == 'wind_speed':
                                # Wind speed in m/s
                                wind_ms = np.mean(recent_values)
                                return float(wind_ms)
                    
                    elif response.status == 202:
                        # Request accepted but processing
                        self.logger.info(f"Copernicus request queued for {lat}, {lon}")
                        return None
            
            return None
            
        except Exception as e:
            self.logger.warning(f"Copernicus climate data failed: {e}")
            return None
    
    async def _get_nasa_gldas_data(self, lat: float, lon: float, parameter: str) -> Optional[float]:
        """Get climate data from NASA GLDAS (Global Land Data Assimilation System)"""
        try:
            from .external_data_connectors import NASAEarthDataConnector
            import aiohttp
            
            nasa_connector = NASAEarthDataConnector()
            
            # GLDAS parameter mapping
            gldas_params = {
                'temperature': 'Tair_f_inst',  # Air temperature
                'precipitation': 'Rainf_f_tavg',  # Rainfall rate
                'humidity': 'Qair_f_inst',  # Specific humidity
                'pressure': 'Psurf_f_inst',  # Surface pressure
                'wind_speed': 'Wind_f_inst'  # Wind speed
            }
            
            if parameter not in gldas_params:
                return None
            
            # Use NASA Earth Data API
            earthdata_token = os.getenv('NASA_EARTHDATA_TOKEN')
            if not earthdata_token:
                return None
            
            # Giovanni API for GLDAS data
            giovanni_url = "https://giovanni.gsfc.nasa.gov/giovanni/daac-bin/service_manager.pl"
            
            # Get recent GLDAS data (monthly averages)
            current_date = datetime.now()
            
            request_params = {
                'service': 'TmAvMp',  # Time averaged map
                'starttime': f"{current_date.year}-{current_date.month-1:02d}-01T00:00:00Z",
                'endtime': f"{current_date.year}-{current_date.month:02d}-01T00:00:00Z",
                'bbox': f"{lon-0.25},{lat-0.25},{lon+0.25},{lat+0.25}",
                'data': f"GLDAS_NOAH025_M_2_1:{gldas_params[parameter]}",
                'variableFacets': f'dataProductTimeFrequency:Monthly;',
                'format': 'json'
            }
            
            headers = {'Authorization': f'Bearer {earthdata_token}'}
            timeout = aiohttp.ClientTimeout(total=30)
            
            async with aiohttp.ClientSession(timeout=timeout) as session:
                async with session.get(giovanni_url, params=request_params, headers=headers) as response:
                    if response.status == 200:
                        data = await response.json()
                        
                        if 'data' in data and data['data']:
                            values = data['data']
                            if values:
                                avg_value = np.mean([v for v in values if v is not None])
                                
                                # Unit conversions
                                if parameter == 'temperature':
                                    # Convert Kelvin to Celsius if needed
                                    if avg_value > 200:  # Likely in Kelvin
                                        return float(avg_value - 273.15)
                                    else:
                                        return float(avg_value)
                                        
                                elif parameter == 'precipitation':
                                    # Convert kg/m2/s to mm/day
                                    return float(avg_value * 86400)
                                    
                                elif parameter == 'pressure':
                                    # Convert Pa to hPa if needed
                                    if avg_value > 50000:  # Likely in Pa
                                        return float(avg_value / 100)
                                    else:
                                        return float(avg_value)
                                        
                                else:
                                    return float(avg_value)
            
            return None
            
        except Exception as e:
            self.logger.warning(f"NASA GLDAS data failed: {e}")
            return None
    
    async def _get_advanced_climate_data(self, lat: float, lon: float, parameter: str) -> Optional[float]:
        """Get real climate data using multiple advanced data sources with ensemble methods"""
        try:
            # Multi-source climate data integration with weighted ensemble
            climate_sources = [
                ('ERA5', self._get_era5_climate_data, 0.35),
                ('NOAA_GHCN', self._get_noaa_ghcn_data, 0.25), 
                ('WorldBank', self._get_worldbank_climate_data, 0.15),
                ('Copernicus', self._get_copernicus_climate_data, 0.15),
                ('NASA_GLDAS', self._get_nasa_gldas_data, 0.10)
            ]
            
            valid_values = []
            total_weight = 0.0
            
            # Collect data from all available sources
            for source_name, source_func, weight in climate_sources:
                try:
                    value = await source_func(lat, lon, parameter)
                    if value is not None and await self._validate_climate_value(parameter, value, lat):
                        quality = await self._assess_data_quality(source_name, lat, lon, parameter)
                        adjusted_weight = weight * quality
                        valid_values.append((value, adjusted_weight, source_name))
                        total_weight += adjusted_weight
                        self.logger.info(f"Climate data from {source_name}: {value} (weight: {adjusted_weight:.3f})")
                except Exception as e:
                    self.logger.warning(f"Failed to get {parameter} data from {source_name}: {e}")
                    continue
            
            if not valid_values:
                self.logger.error(f"No valid climate data sources available for {parameter} at ({lat}, {lon})")
                return await self._get_climatology_fallback(lat, lon, parameter)
            
            # Weighted ensemble average with uncertainty estimation
            weighted_sum = sum(value * weight for value, weight, _ in valid_values)
            ensemble_mean = weighted_sum / total_weight if total_weight > 0 else valid_values[0][0]
            
            # Calculate ensemble uncertainty (standard deviation)
            if len(valid_values) > 1:
                variance = sum(weight * (value - ensemble_mean) ** 2 for value, weight, _ in valid_values) / total_weight
                uncertainty = np.sqrt(variance)
                
                # Log uncertainty metrics for quality assessment
                self.logger.info(f"Climate ensemble for {parameter}: mean={ensemble_mean:.2f}, std={uncertainty:.2f}, sources={len(valid_values)}")
            
            # Cache the ensemble result
            await self._cache_climate_data(lat, lon, parameter, ensemble_mean, 'ensemble')
            
            return float(ensemble_mean)
            
        except Exception as e:
            self.logger.error(f"Advanced climate data retrieval failed: {e}")
            return await self._get_climatology_fallback(lat, lon, parameter)
    
    async def _get_era5_climate_data(self, lat: float, lon: float, parameter: str) -> Optional[float]:
        """Get high-resolution climate data from Copernicus ERA5 reanalysis"""
        try:
            # Use Copernicus Climate Data Store (CDS) API
            import cdsapi
            from datetime import datetime, timedelta
            
            if not hasattr(self, 'cds_client'):
                self.cds_client = cdsapi.Client()
            
            # Map parameters to ERA5 variables
            era5_vars = {
                'temperature': '2m_temperature',
                'precipitation': 'total_precipitation', 
                'humidity': 'relative_humidity',
                'pressure': 'surface_pressure',
                'wind_speed': '10m_wind_speed'
            }
            
            if parameter not in era5_vars:
                return None
                
            # Get recent data (last 7 days for near real-time)
            end_date = datetime.utcnow()
            start_date = end_date - timedelta(days=7)
            
            request_params = {
                'product_type': 'reanalysis',
                'format': 'netcdf',
                'variable': era5_vars[parameter],
                'date': f"{start_date.strftime('%Y-%m-%d')}/{end_date.strftime('%Y-%m-%d')}",
                'time': ['00:00', '06:00', '12:00', '18:00'],
                'area': [lat + 0.25, lon - 0.25, lat - 0.25, lon + 0.25],  # Small area around point
                'grid': [0.1, 0.1]  # High resolution
            }
            
            # Submit request and process NetCDF data
            result = self.cds_client.retrieve('reanalysis-era5-single-levels', request_params)
            
            # Process NetCDF file (simplified - would use xarray in production)
            import xarray as xr
            with xr.open_dataset(result.download()) as ds:
                # Get nearest grid point and temporal mean
                data_point = ds.sel(latitude=lat, longitude=lon, method='nearest')
                value = float(data_point[era5_vars[parameter]].mean().values)
                
                # Convert units if necessary
                if parameter == 'temperature':
                    value = value - 273.15  # Kelvin to Celsius
                elif parameter == 'precipitation':
                    value = value * 1000  # m to mm
                    
                return value
                
        except Exception as e:
            self.logger.warning(f"ERA5 climate data retrieval failed: {e}")
            return None
    
    async def _get_noaa_ghcn_data(self, lat: float, lon: float, parameter: str) -> Optional[float]:
        """Get climate data from NOAA Global Historical Climatology Network"""
        try:
            # NOAA GHCN Daily API
            api_key = os.getenv('NOAA_API_KEY')
            if not api_key:
                self.logger.warning("NOAA API key not configured")
                return None
                
            # Find nearest weather stations
            stations_url = f"https://www.ncei.noaa.gov/cdo-web/api/v2/stations"
            station_params = {
                'datatypeid': self._map_param_to_noaa(parameter),
                'locationid': f"FIPS:99",  # Global
                'limit': 5,
                'offset': 1
            }
            
            headers = {'token': api_key}
            
            async with aiohttp.ClientSession() as session:
                # Get nearby stations
                async with session.get(stations_url, params=station_params, headers=headers) as response:
                    if response.status != 200:
                        return None
                        
                    stations_data = await response.json()
                    
                if not stations_data.get('results'):
                    return None
                
                # Get data from closest stations
                station_values = []
                end_date = datetime.utcnow().strftime('%Y-%m-%d')
                start_date = (datetime.utcnow() - timedelta(days=30)).strftime('%Y-%m-%d')
                
                for station in stations_data['results'][:3]:  # Top 3 closest
                    try:
                        data_url = f"https://www.ncei.noaa.gov/cdo-web/api/v2/data"
                        data_params = {
                            'datasetid': 'GHCND',
                            'datatypeid': self._map_param_to_noaa(parameter),
                            'stationid': station['id'],
                            'startdate': start_date,
                            'enddate': end_date,
                            'limit': 100
                        }
                        
                        async with session.get(data_url, params=data_params, headers=headers) as data_response:
                            if data_response.status == 200:
                                data_json = await data_response.json()
                                if data_json.get('results'):
                                    # Calculate recent average
                                    values = [float(item['value']) for item in data_json['results'] if item.get('value')]
                                    if values:
                                        station_values.append(np.mean(values))
                                        
                    except Exception as e:
                        self.logger.warning(f"Failed to get data from station {station['id']}: {e}")
                        continue
                
                if station_values:
                    # Return mean of station values
                    return float(np.mean(station_values))
                    
        except Exception as e:
            self.logger.warning(f"NOAA GHCN data retrieval failed: {e}")
            
        return None
    
    async def _get_worldbank_climate_data(self, lat: float, lon: float, parameter: str) -> Optional[float]:
        """Get climate data from World Bank Climate Data API"""
        try:
            # Use existing WorldBank connector
            if not hasattr(self, 'worldbank_connector'):
                from .external_data_connectors import WorldBankDataConnector
                self.worldbank_connector = WorldBankDataConnector()
            
            # Map parameters to World Bank climate indicators
            wb_indicators = {
                'temperature': 'EN.TMP.MEAN.K',
                'precipitation': 'EN.PRC.MEAN.MM',
                'humidity': 'EN.HUM.MEAN.PC'
            }
            
            if parameter not in wb_indicators:
                return None
            
            # Get country code from coordinates
            country_code = await self._get_country_from_coordinates(lat, lon)
            if not country_code:
                return None
                
            # Get climate data for country
            climate_data = await self.worldbank_connector.get_climate_data(
                country_code=country_code,
                indicator=wb_indicators[parameter],
                years=5  # Recent 5 years average
            )
            
            if climate_data and len(climate_data) > 0:
                # Return most recent value or average
                values = [float(item['value']) for item in climate_data if item.get('value')]
                if values:
                    result = np.mean(values)
                    
                    # Unit conversions
                    if parameter == 'temperature':
                        result = result - 273.15  # Kelvin to Celsius
                        
                    return float(result)
                    
        except Exception as e:
            self.logger.warning(f"World Bank climate data retrieval failed: {e}")
            
        return None
    
    async def _get_copernicus_climate_data(self, lat: float, lon: float, parameter: str) -> Optional[float]:
        """Get climate data from Copernicus Climate Change Service"""
        try:
            # Copernicus Climate Data Store API integration
            api_url = "https://cds.climate.copernicus.eu/api/v2"
            api_key = os.getenv('COPERNICUS_API_KEY')
            
            if not api_key:
                self.logger.warning("Copernicus API key not configured")
                return None
            
            # Map parameters to Copernicus variables
            copernicus_vars = {
                'temperature': 'temperature_2m',
                'precipitation': 'total_precipitation',
                'humidity': 'relative_humidity_2m',
                'pressure': 'surface_pressure'
            }
            
            if parameter not in copernicus_vars:
                return None
            
            headers = {
                'Authorization': f'Bearer {api_key}',
                'Content-Type': 'application/json'
            }
            
            # Create data request
            request_data = {
                'dataset': 'reanalysis-era5-single-levels',
                'product_type': 'reanalysis',
                'variable': copernicus_vars[parameter],
                'area': [lat + 0.1, lon - 0.1, lat - 0.1, lon + 0.1],
                'format': 'json',
                'time_range': 'recent_7_days'
            }
            
            async with aiohttp.ClientSession() as session:
                async with session.post(f"{api_url}/retrieve", json=request_data, headers=headers) as response:
                    if response.status == 200:
                        data = await response.json()
                        
                        # Process response data
                        if 'values' in data and len(data['values']) > 0:
                            value = float(np.mean(data['values']))
                            
                            # Unit conversions
                            if parameter == 'temperature' and value > 200:  # Likely Kelvin
                                value = value - 273.15
                            elif parameter == 'precipitation':
                                value = value * 1000  # m to mm
                                
                            return value
                            
        except Exception as e:
            self.logger.warning(f"Copernicus climate data retrieval failed: {e}")
            
        return None
    
    async def _get_satellite_climate_data(self, lat: float, lon: float, parameter: str) -> Optional[float]:
        """Get climate data from satellite imagery analysis"""
        try:
            # Use NASA Earth Data connector for satellite imagery
            if not hasattr(self, 'nasa_connector'):
                from .external_data_connectors import NASAEarthDataConnector
                self.nasa_connector = NASAEarthDataConnector()
            
            # Map parameters to satellite products
            satellite_products = {
                'temperature': 'MOD11A1',  # MODIS Land Surface Temperature
                'precipitation': 'GPM_3IMERGHH',  # GPM precipitation
                'humidity': 'AIRS3STM',  # AIRS atmospheric humidity
            }
            
            if parameter not in satellite_products:
                return None
            
            # Get satellite data for location
            product = satellite_products[parameter]
            
            satellite_data = await self.nasa_connector.get_satellite_data(
                product=product,
                lat=lat,
                lon=lon,
                start_date=(datetime.utcnow() - timedelta(days=14)).strftime('%Y-%m-%d'),
                end_date=datetime.utcnow().strftime('%Y-%m-%d')
            )
            
            if satellite_data and len(satellite_data) > 0:
                # Process satellite imagery data
                values = []
                for data_point in satellite_data:
                    if 'value' in data_point and data_point['value'] is not None:
                        values.append(float(data_point['value']))
                
                if values:
                    result = np.mean(values)
                    
                    # Apply satellite-specific corrections
                    if parameter == 'temperature':
                        # MODIS LST corrections
                        result = result * 0.02 - 273.15  # Scale factor and K to C
                    elif parameter == 'precipitation':
                        # GPM precipitation scaling
                        result = result * 0.1  # Scale factor
                    
                    return float(result)
                    
        except Exception as e:
            self.logger.warning(f"Satellite climate data retrieval failed: {e}")
            
        return None
    
    async def _get_country_from_coordinates(self, lat: float, lon: float) -> Optional[str]:
        """Advanced geocoding to determine country code from coordinates using multiple sources"""
        try:
            # Multi-source geocoding with fallbacks
            geocoding_sources = [
                ('PostGIS_Database', self._get_country_from_postgis),
                ('Nominatim_OpenStreetMap', self._get_country_from_nominatim),
                ('WorldBank_API', self._get_country_from_worldbank_api),
                ('GeoNames_API', self._get_country_from_geonames),
                ('Natural_Earth_Data', self._get_country_from_natural_earth)
            ]
            
            for source_name, source_func in geocoding_sources:
                try:
                    country_code = await source_func(lat, lon)
                    if country_code and len(country_code) >= 2:
                        self.logger.info(f"Country code from {source_name}: {country_code}")
                        
                        # Validate country code format
                        if await self._validate_country_code(country_code):
                            # Cache the result for future use
                            await self._cache_geocoding_result(lat, lon, country_code, source_name)
                            return country_code.upper()
                            
                except Exception as e:
                    self.logger.warning(f"Geocoding failed for {source_name}: {e}")
                    continue
            
            # Final fallback to geographic regions
            self.logger.warning(f"All geocoding sources failed for ({lat}, {lon}), using geographic fallback")
            return await self._get_geographic_region_fallback(lat, lon)
            
        except Exception as e:
            self.logger.error(f"Complete geocoding failure: {e}")
            return 'WLD'  # World fallback
    
    async def _get_country_from_postgis(self, lat: float, lon: float) -> Optional[str]:
        """Use PostGIS database with Natural Earth country boundaries"""
        try:
            from .database_integration import DatabaseConfig
            import asyncpg
            
            config = DatabaseConfig()
            
            # Connect to PostGIS database
            conn = await asyncpg.connect(config.get_async_connection_string())
            
            try:
                # Query using PostGIS spatial functions
                query = """
                SELECT 
                    ne.iso_a2,
                    ne.name_long,
                    ne.continent,
                    ST_Distance(ST_GeogFromText('POINT(%s %s)'), ne.geom) as distance_m
                FROM natural_earth_countries ne
                WHERE ST_Contains(ne.geom, ST_GeogFromText('POINT(%s %s)')
                LIMIT 1;
                """
                
                result = await conn.fetchrow(query, lon, lat, lon, lat)
                
                if result:
                    country_code = result['iso_a2']
                    if country_code and country_code != '-99':  # Natural Earth uses -99 for no data
                        return country_code
                
                # If point not inside any country, find nearest country
                nearest_query = """
                SELECT 
                    ne.iso_a2,
                    ne.name_long,
                    ST_Distance(ST_GeogFromText('POINT(%s %s)'), ne.geom) as distance_m
                FROM natural_earth_countries ne
                ORDER BY ST_Distance(ST_GeogFromText('POINT(%s %s)'), ne.geom)
                LIMIT 1;
                """
                
                nearest_result = await conn.fetchrow(nearest_query, lon, lat, lon, lat)
                
                if nearest_result and nearest_result['distance_m'] < 200000:  # Within 200km
                    return nearest_result['iso_a2']
                    
            finally:
                await conn.close()
                
        except Exception as e:
            self.logger.warning(f"PostGIS geocoding failed: {e}")
            
        return None
    
    async def _get_country_from_nominatim(self, lat: float, lon: float) -> Optional[str]:
        """Use OpenStreetMap Nominatim reverse geocoding service"""
        try:
            nominatim_url = "https://nominatim.openstreetmap.org/reverse"
            
            params = {
                'lat': lat,
                'lon': lon,
                'format': 'json',
                'addressdetails': 1,
                'zoom': 10,
                'accept-language': 'en'
            }
            
            headers = {
                'User-Agent': 'PrometheusGeological/1.0 (scientific-research)'
            }
            
            async with aiohttp.ClientSession() as session:
                await asyncio.sleep(1)  # Respect rate limiting
                
                async with session.get(nominatim_url, params=params, headers=headers) as response:
                    if response.status == 200:
                        data = await response.json()
                        
                        if 'address' in data:
                            address = data['address']
                            
                            # Extract country code
                            country_code = address.get('country_code')
                            if country_code:
                                return country_code.upper()
                            
                            # Fallback to country name lookup
                            country_name = address.get('country')
                            if country_name:
                                return await self._convert_country_name_to_code(country_name)
                                
        except Exception as e:
            self.logger.warning(f"Nominatim geocoding failed: {e}")
            
        return None
    
    async def _get_country_from_geonames(self, lat: float, lon: float) -> Optional[str]:
        """Use GeoNames web service for reverse geocoding"""
        try:
            geonames_username = os.getenv('GEONAMES_USERNAME')
            if not geonames_username:
                self.logger.warning("GeoNames username not configured")
                return None
            
            geonames_url = "http://api.geonames.org/countryCodeJSON"
            
            params = {
                'lat': lat,
                'lng': lon,
                'username': geonames_username,
                'radius': 10  # 10km search radius
            }
            
            async with aiohttp.ClientSession() as session:
                async with session.get(geonames_url, params=params) as response:
                    if response.status == 200:
                        data = await response.json()
                        
                        country_code = data.get('countryCode')
                        if country_code:
                            return country_code
                            
        except Exception as e:
            self.logger.warning(f"GeoNames geocoding failed: {e}")
            
        return None
    
    async def _get_country_from_worldbank_api(self, lat: float, lon: float) -> Optional[str]:
        """Use World Bank API for country boundary determination"""
        try:
            # World Bank doesn't have direct reverse geocoding, but we can use their country data
            # combined with geographic logic for major regions
            
            # Use existing WorldBank connector if available
            if hasattr(self, 'worldbank_connector'):
                # Get all countries and find closest based on geographic center
                countries = await self.worldbank_connector.get_countries_list()
                
                if countries:
                    min_distance = float('inf')
                    closest_country = None
                    
                    for country in countries:
                        if 'latitude' in country and 'longitude' in country:
                            # Calculate distance to country center
                            country_lat = float(country['latitude'])
                            country_lon = float(country['longitude'])
                            
                            distance = np.sqrt((lat - country_lat)**2 + (lon - country_lon)**2)
                            
                            if distance < min_distance:
                                min_distance = distance
                                closest_country = country.get('id')  # ISO country code
                    
                    # Only return if reasonably close (within ~5 degrees)
                    if closest_country and min_distance < 5.0:
                        return closest_country
                        
        except Exception as e:
            self.logger.warning(f"World Bank API geocoding failed: {e}")
            
        return None
    
    async def _get_country_from_natural_earth(self, lat: float, lon: float) -> Optional[str]:
        """Use Natural Earth data for offline country boundary lookup"""
        try:
            # Download and use Natural Earth country boundaries
            # This would be a local lookup using downloaded shapefile data
            
            import geopandas as gpd
            from shapely.geometry import Point
            
            # Check if we have cached Natural Earth data
            ne_data_path = os.getenv('NATURAL_EARTH_DATA_PATH', './data/natural_earth')
            countries_file = os.path.join(ne_data_path, 'ne_50m_admin_0_countries.shp')
            
            if os.path.exists(countries_file):
                # Load country boundaries
                world = gpd.read_file(countries_file)
                
                # Create point geometry
                point = Point(lon, lat)
                
                # Find country containing the point
                country_match = world[world.geometry.contains(point)]
                
                if not country_match.empty:
                    iso_a2 = country_match.iloc[0]['ISO_A2']
                    if iso_a2 != '-99':  # Natural Earth no-data value
                        return iso_a2
                
                # If not inside any country, find nearest
                world['distance'] = world.geometry.distance(point)
                nearest_country = world.loc[world['distance'].idxmin()]
                
                if nearest_country['distance'] < 2.0:  # Within ~2 degrees
                    return nearest_country['ISO_A2']
                    
        except Exception as e:
            self.logger.warning(f"Natural Earth geocoding failed: {e}")
            
        return None
    
    async def _get_geographic_region_fallback(self, lat: float, lon: float) -> str:
        """Geographic region-based fallback for country determination"""
        try:
            # Advanced geographic regions based on continental boundaries
            
            # North America
            if (-170 <= lon <= -40) and (15 <= lat <= 85):
                if (-130 <= lon <= -60) and (25 <= lat <= 50):
                    return 'USA'  # Continental US region
                elif (-141 <= lon <= -60) and (50 <= lat <= 85):
                    return 'CAN'  # Canada region
                elif (-118 <= lon <= -86) and (14 <= lat <= 33):
                    return 'MEX'  # Mexico region
                else:
                    return 'NAM'  # North America general
            
            # Europe
            elif (-25 <= lon <= 45) and (35 <= lat <= 75):
                if (-10 <= lon <= 30) and (45 <= lat <= 70):
                    return 'EUR'  # Central/Northern Europe
                elif (15 <= lon <= 45) and (35 <= lat <= 50):
                    return 'EUR'  # Eastern Europe
                else:
                    return 'EUR'  # Europe general
            
            # Asia
            elif (25 <= lon <= 180) and (10 <= lat <= 85):
                if (70 <= lon <= 140) and (15 <= lat <= 55):
                    return 'CHN'  # China region
                elif (125 <= lon <= 150) and (30 <= lat <= 50):
                    return 'JPN'  # Japan region
                elif (65 <= lon <= 100) and (5 <= lat <= 40):
                    return 'IND'  # India region
                else:
                    return 'ASI'  # Asia general
            
            # Africa
            elif (-20 <= lon <= 55) and (-40 <= lat <= 40):
                return 'AFR'  # Africa
            
            # South America
            elif (-85 <= lon <= -30) and (-60 <= lat <= 15):
                if (-75 <= lon <= -45) and (-30 <= lat <= 5):
                    return 'BRA'  # Brazil region
                else:
                    return 'SAM'  # South America
            
            # Oceania
            elif (110 <= lon <= 180) and (-50 <= lat <= 0):
                return 'AUS'  # Australia region
            
            # Arctic/Antarctic
            elif lat > 75:
                return 'ARC'  # Arctic
            elif lat < -60:
                return 'ANT'  # Antarctica
            
            # Ocean fallback
            else:
                return 'OCN'  # Ocean/International waters
                
        except Exception:
            return 'WLD'  # World fallback
    
