    async def _cache_geocoding_result(self, lat: float, lon: float, country_code: str, source: str):
        """Cache geocoding results for performance optimization"""
        try:
            from .database_integration import DatabaseConfig
            import asyncpg
            
            config = DatabaseConfig()
            
            # Store in geocoding cache table
            conn = await asyncpg.connect(config.get_async_connection_string())
            
            try:
                insert_query = """
                INSERT INTO geocoding_cache 
                (location, country_code, source, cached_at, expires_at)
                VALUES (ST_GeogFromText('POINT(%s %s)'), %s, %s, NOW(), NOW() + INTERVAL '30 days')
                ON CONFLICT (location) DO UPDATE SET
                    country_code = EXCLUDED.country_code,
                    source = EXCLUDED.source,
                    cached_at = NOW(),
                    expires_at = NOW() + INTERVAL '30 days';
                """
                
                await conn.execute(insert_query, lon, lat, country_code, source)
                
            finally:
                await conn.close()
                
        except Exception as e:
            self.logger.warning(f"Failed to cache geocoding result: {e}")
    
