    async def _fallback_elevation_reference(self, lat: float, lon: float) -> str:
        """Fallback elevation reference determination with enhanced regional logic"""
        try:
            # Enhanced fallback with better regional precision
            if -180 <= lon <= 180 and -90 <= lat <= 90:
                # North America (enhanced regions)
                if -170 <= lon <= -50 and 15 <= lat <= 75:
                    if -170 <= lon <= -140 and lat > 60:  # Alaska
                        return 'NAVD88_ALASKA'
                    elif -140 <= lon <= -52 and lat > 49:  # Canada  
                        return 'CGVD2013'
                    elif -125 <= lon <= -66 and 24 <= lat <= 49:  # CONUS
                        return 'NAVD88'
                    else:  # Mexico/Central America
                        return 'NGVD29_MEX'
                
                # Europe (enhanced regions)
                elif -25 <= lon <= 40 and 35 <= lat <= 75:
                    if lat > 60:  # Nordic countries
                        return 'NN2000'
                    elif lon < 5 and lat < 45:  # Western Europe
                        return 'NGF_IGN69'
                    else:  # Continental Europe
                        return 'EVRS'
                
                # Asia-Pacific
                elif 90 <= lon <= 180 and -50 <= lat <= 75:
                    if 129 <= lon <= 146 and 30 <= lat <= 46:  # Japan
                        return 'JGD2011_HEIGHT'
                    elif 110 <= lon <= 155 and -45 <= lat <= -10:  # Australia
                        return 'AHD'
                    else:
                        return 'MSL_REGIONAL'
                
                # Global enhanced fallback
                else:
                    if abs(lat) > 60:  # Polar regions
                        return 'WGS84_ELLIPSOID'
                    else:
                        return 'MSL'
            
            return 'UNKNOWN'
            
        except Exception:
            return 'MSL'
    
