    async def _validate_climate_value(self, parameter: str, value: float, lat: float) -> bool:
        """Validate climate data values for physical realism"""
        try:
            abs_lat = abs(lat)
            
            if parameter == 'temperature':
                # Temperature bounds: -89°C to 57°C (recorded extremes)
                return -89.0 <= value <= 57.0
            elif parameter == 'precipitation':
                # Precipitation: 0 to 1000 mm/day (extreme maximum)
                return 0.0 <= value <= 1000.0
            elif parameter == 'humidity':
                # Relative humidity: 0% to 100%
                return 0.0 <= value <= 100.0
            elif parameter == 'pressure':
                # Sea level pressure: 870 to 1080 hPa (extreme range)
                return 870.0 <= value <= 1080.0
            elif parameter == 'wind_speed':
                # Wind speed: 0 to 120 m/s (extreme hurricane)
                return 0.0 <= value <= 120.0
            else:
                return True  # Unknown parameter, assume valid
        except:
            return False
    
    async def _assess_data_quality(self, source_name: str, lat: float, lon: float, parameter: str) -> float:
        """Assess data quality based on source reliability and location"""
        try:
            # Base quality scores for different sources
            source_quality = {
                'ERA5': 0.95,
                'NOAA_GHCN': 0.85,
                'WorldBank': 0.70,
                'Copernicus': 0.90,
                'NASA_GLDAS': 0.80
            }
            
            base_quality = source_quality.get(source_name, 0.50)
            
            # Adjust quality based on geographic factors
            abs_lat = abs(lat)
            
            # Data quality decreases in remote areas
            if abs_lat > 70:  # Polar regions
                base_quality *= 0.7
            elif abs_lat > 60:  # High latitudes
                base_quality *= 0.85
            
            # Ocean vs land adjustments
            if self._is_over_ocean(lat, lon):
                base_quality *= 0.8  # Ocean data typically less accurate
            
            # Parameter-specific adjustments
            if parameter == 'humidity' and abs_lat > 50:
                base_quality *= 0.9  # Humidity less reliable at high latitudes
            
            return min(1.0, base_quality)
            
        except:
            return 0.5
    
    async def _spatial_climate_interpolation(self, lat: float, lon: float, parameter: str) -> Optional[float]:
        """Advanced spatial interpolation from nearby weather stations"""
        try:
            from .database_integration import DatabaseIntegration
            from scipy.spatial.distance import cdist
            from sklearn.gaussian_process import GaussianProcessRegressor
            from sklearn.gaussian_process.kernels import RBF, Matern
            import numpy as np
            
            db_integration = DatabaseIntegration()
            
            # Query nearby climate observations within 100km
            climate_query = """
            SELECT latitude, longitude, parameter_value, measurement_time, data_quality,
                   ST_Distance(ST_GeogFromText('POINT(%s %s)'), 
                              ST_GeogFromText('POINT(' || longitude || ' ' || latitude || ')')) as distance_m
            FROM climate_observations 
            WHERE parameter_name = %s 
              AND ST_DWithin(ST_GeogFromText('POINT(%s %s)'), 
                           ST_GeogFromText('POINT(' || longitude || ' ' || latitude || ')'), 100000)
              AND measurement_time > NOW() - INTERVAL '30 days'
              AND data_quality > 0.5
            ORDER BY distance_m
            LIMIT 20
            """
            
            nearby_obs = await db_integration.execute_query(
                climate_query, (lon, lat, parameter, lon, lat)
            )
            
            if len(nearby_obs) >= 3:
                # Extract coordinates and values
                coords = np.array([[obs['latitude'], obs['longitude']] for obs in nearby_obs])
                values = np.array([obs['parameter_value'] for obs in nearby_obs])
                distances = np.array([obs['distance_m'] for obs in nearby_obs])
                qualities = np.array([obs['data_quality'] for obs in nearby_obs])
                
                # Weight by quality and inverse distance
                weights = qualities / (distances + 100)  # +100 to avoid division by zero
                weights = weights / weights.sum()
                
                # Multiple interpolation methods
                methods_results = []
                
                # 1. Inverse Distance Weighting with quality
                idw_result = np.sum(weights * values)
                methods_results.append(('IDW', idw_result, 0.4))
                
                # 2. Gaussian Process Regression for smooth interpolation
                if len(nearby_obs) >= 5:
                    try:
                        kernel = RBF(length_scale=10000) + Matern(length_scale=5000, nu=1.5)
                        gpr = GaussianProcessRegressor(kernel=kernel, alpha=1e-2)
                        gpr.fit(coords, values)
                        gpr_result, gpr_std = gpr.predict([[lat, lon]], return_std=True)
                        confidence = min(1.0, 1.0 / (gpr_std[0] + 0.1))
                        methods_results.append(('GPR', gpr_result[0], confidence * 0.6))
                    except:
                        pass
                
                # Ensemble result
                if methods_results:
                    total_weight = sum(weight for _, _, weight in methods_results)
                    if total_weight > 0:
                        ensemble_result = sum(value * weight for _, value, weight in methods_results) / total_weight
                        return float(ensemble_result)
            
            return None
            
        except Exception as e:
            self.logger.debug(f"Spatial climate interpolation failed: {e}")
            return None
    
    async def _geographic_climate_model(self, lat: float, lon: float, parameter: str) -> float:
        """Physical geography-based climate modeling"""
        try:
            import math
            
            abs_lat = abs(lat)
            
            # Enhanced climate modeling based on physical geography
            if parameter == 'temperature':
                # Temperature model based on latitude, elevation, and continentality
                base_temp = 30 - (abs_lat * 0.65)  # Latitudinal temperature gradient
                
                # Seasonal variation
                day_of_year = datetime.now().timetuple().tm_yday
                seasonal_amplitude = 15 * math.cos(math.radians(abs_lat * 2))
                seasonal_temp = seasonal_amplitude * math.cos(2 * math.pi * (day_of_year - 172) / 365)
                
                # Continental vs maritime effects
                continentality = self._estimate_continentality(lat, lon)
                continental_effect = continentality * seasonal_amplitude * 0.3
                
                # Elevation effect (approximate)
                elevation_effect = -6.5 * (await self._estimate_elevation_from_geology(lat, lon) / 1000)
                
                return base_temp + seasonal_temp + continental_effect + elevation_effect
            
            elif parameter == 'precipitation':
                # Precipitation model based on geographic patterns
                # Equatorial convergence zone
                if abs_lat < 10:
                    base_precip = 1800 + 400 * math.cos(math.radians(lat * 18))
                # Subtropical high pressure
                elif 20 < abs_lat < 35:
                    base_precip = 200 + 300 * math.sin(math.radians((abs_lat - 20) * 6))
                # Mid-latitude westerlies
                elif 35 < abs_lat < 60:
                    base_precip = 800 + 600 * math.sin(math.radians((abs_lat - 35) * 3.6))
                # Polar regions
                else:
                    base_precip = 300 - abs_lat * 2
                
                # Orographic effects
                elevation = await self._estimate_elevation_from_geology(lat, lon)
                if elevation > 1000:
                    orographic_enhancement = min(2.0, elevation / 1000) * 200
                    base_precip += orographic_enhancement
                
                # Continental vs maritime
                continentality = self._estimate_continentality(lat, lon)
                maritime_effect = (1 - continentality) * 400
                
                return max(50, base_precip + maritime_effect) / 365.25  # Convert to daily
            
            elif parameter == 'humidity':
                # Humidity based on temperature and precipitation patterns
                temp = await self._geographic_climate_model(lat, lon, 'temperature')
                precip = await self._geographic_climate_model(lat, lon, 'precipitation')
                
                # Higher humidity with higher temperature and precipitation
                base_humidity = 40 + (temp * 1.5) + (precip * 0.02)
                
                # Coastal effects
                if not self._is_over_ocean(lat, lon):
                    distance_to_coast = self._estimate_distance_to_coast(lat, lon)
                    coastal_effect = max(0, 20 - distance_to_coast / 50)  # Decay with distance
                    base_humidity += coastal_effect
                
                return min(95, max(15, base_humidity))
            
            else:
                # Default values for other parameters
                return {'pressure': 1013.25, 'wind_speed': 5.0}.get(parameter, 10.0)
                
        except Exception as e:
            self.logger.debug(f"Geographic climate modeling failed: {e}")
            return self._emergency_climate_fallback(lat, lon, parameter)
    
    def _estimate_continentality(self, lat: float, lon: float) -> float:
        """Estimate continentality (0=maritime, 1=continental)"""
        try:
            # Simple approximation based on distance from major water bodies
            if self._is_over_ocean(lat, lon):
                return 0.0
            
            # Major continental interiors
            if -120 < lon < -90 and 30 < lat < 50:  # North American interior
                return 0.8
            elif 20 < lon < 60 and 45 < lat < 70:  # Siberian interior
                return 0.9
            elif 70 < lon < 120 and 35 < lat < 50:  # Central Asian interior
                return 0.85
            else:
                # Approximate based on distance to coast
                distance_to_coast = self._estimate_distance_to_coast(lat, lon)
                return min(1.0, distance_to_coast / 1000)  # 1000km = fully continental
        except:
            return 0.5
    
    def _is_over_ocean(self, lat: float, lon: float) -> bool:
        """Simple check if coordinates are over ocean"""
        # Very simplified - would use proper land/ocean mask in production
        try:
            # Major ocean regions
            if -180 < lon < -30 and -60 < lat < 60:  # Pacific/Atlantic
                return abs(lat) < 45 or abs(lon) > 120
            elif 30 < lon < 180 and -60 < lat < 60:  # Indian/Pacific
                return abs(lat) < 50
            else:
                return False
        except:
            return False
    
    def _estimate_distance_to_coast(self, lat: float, lon: float) -> float:
        """Estimate approximate distance to nearest coast in km"""
        try:
            # Very simplified approximation
            if self._is_over_ocean(lat, lon):
                return 0.0
            
            # Continental interiors (rough estimates)
            if -110 < lon < -95 and 35 < lat < 45:  # US Great Plains
                return 800
            elif 40 < lon < 80 and 45 < lat < 60:  # Central Asia
                return 1200
            elif -60 < lon < -40 and -30 < lat < -10:  # South American interior
                return 600
            else:
                return 300  # Default moderate distance
        except:
            return 500
    
    async def _emergency_climate_fallback(self, lat: float, lon: float, parameter: str) -> float:
        """Emergency fallback values when all other methods fail"""
        try:
            abs_lat = abs(lat)
            
            # Conservative fallback values by climate zone
            if parameter == 'temperature':
                if abs_lat < 23.5:  # Tropics
                    return 25.0
                elif abs_lat < 35:  # Subtropics
                    return 18.0
                elif abs_lat < 60:  # Temperate
                    return 10.0
                else:  # Polar
                    return -5.0
            
            elif parameter == 'precipitation':
                if abs_lat < 10:  # Equatorial
                    return 5.0  # mm/day
                elif abs_lat < 30:  # Subtropical
                    return 1.0
                elif abs_lat < 60:  # Temperate
                    return 2.0
                else:  # Polar
                    return 0.5
            
            elif parameter == 'humidity':
                if abs_lat < 30:
                    return 70.0
                else:
                    return 60.0
            
            elif parameter == 'pressure':
                # Standard atmosphere pressure adjusted for latitude
                return 1013.25 - (abs_lat * 0.1)
            
            elif parameter == 'wind_speed':
                # Average wind speeds by latitude
                if 30 < abs_lat < 60:  # Westerlies
                    return 8.0
                else:
                    return 5.0
            
            else:
                return 10.0
                
        except:
            # Final emergency values
            return {'temperature': 15.0, 'precipitation': 1.0, 'humidity': 65.0, 
                   'pressure': 1013.25, 'wind_speed': 5.0}.get(parameter, 10.0)
    
