    async def _calculate_landsat_ndvi(self, satellite_record) -> Optional[float]:
        """Calculate NDVI from real Landsat band data with advanced processing"""
        try:
            import numpy as np
            from scipy import ndimage
            
            # Extract coordinates and metadata
            if hasattr(satellite_record, 'coordinates'):
                lat, lon = satellite_record.coordinates[:2]
            else:
                lat, lon = satellite_record.get('lat', 0), satellite_record.get('lon', 0)
            
            # Multi-source Landsat data acquisition
            landsat_data = await self._acquire_landsat_bands(lat, lon, satellite_record)
            
            if not landsat_data or 'bands' not in landsat_data:
                return await self._fallback_landsat_ndvi_calculation(lat, lon)
            
            bands = landsat_data['bands']
            
            # Landsat 8/9 OLI bands (updated band numbers)
            # Band 4 (Red): 630-680 nm
            # Band 5 (NIR): 845-885 nm
            red_band = bands.get('B4', bands.get('red'))
            nir_band = bands.get('B5', bands.get('nir'))
            
            if red_band is None or nir_band is None:
                return await self._interpolate_landsat_bands(lat, lon, bands)
            
            # Advanced atmospheric correction using 6S model
            corrected_red = await self._atmospheric_correction_6s(red_band, 'red', landsat_data)
            corrected_nir = await self._atmospheric_correction_6s(nir_band, 'nir', landsat_data)
            
            # Calculate NDVI with quality assessment
            if isinstance(corrected_red, (int, float)) and isinstance(corrected_nir, (int, float)):
                if (corrected_nir + corrected_red) != 0:
                    ndvi = (corrected_nir - corrected_red) / (corrected_nir + corrected_red)
                    
                    # Apply quality flags and cloud masking
                    quality_flags = landsat_data.get('quality', {})
                    if await self._validate_landsat_quality(quality_flags, ndvi):
                        # BRDF correction for view/sun angle effects
                        corrected_ndvi = await self._apply_brdf_correction(ndvi, landsat_data)
                        return max(-1.0, min(1.0, corrected_ndvi))
            
            # Multi-pixel neighborhood analysis for validation
            return await self._spatial_ndvi_validation(lat, lon, landsat_data)
            
        except Exception as e:
            self.logger.error(f"Landsat NDVI calculation failed: {e}")
            return None
    
