    async def _query_sentinel_database(self, lat: float, lon: float) -> Optional[Dict[str, Any]]:
        """Query local database for cached Sentinel-2 NDVI data"""
        try:
            from .database_integration import PostgreSQLGISManager, DatabaseConfig
            
            if not hasattr(self, 'db_manager') or not self.db_manager:
                return None
            
            # Spatial query for nearby Sentinel-2 observations within 1km and 30 days
            query = """
                SELECT ndvi_value, acquisition_date, cloud_cover_percent, 
                       quality_flag, processing_level, ST_Distance(
                           ST_Point(%s, %s)::geography, 
                           location::geography
                       ) as distance_m
                FROM satellite_ndvi_archive 
                WHERE sensor_type = 'Sentinel-2' 
                AND ST_DWithin(location::geography, ST_Point(%s, %s)::geography, 1000)
                AND acquisition_date >= NOW() - INTERVAL '30 days'
                AND quality_flag >= 0.7
                ORDER BY distance_m ASC, acquisition_date DESC
                LIMIT 5;
            """
            
            result = await self.db_manager.execute_query(
                query, (lon, lat, lon, lat)
            )
            
            if result:
                # Select best quality observation with temporal weighting
                best_obs = max(result, key=lambda x: (
                    x['quality_flag'] * 0.6 + 
                    (1 - x['cloud_cover_percent']/100) * 0.3 +
                    (1 - min(x['distance_m']/1000, 1)) * 0.1
                ))
                
                return {
                    'ndvi': best_obs['ndvi_value'],
                    'quality': best_obs['quality_flag'],
                    'source': 'database_sentinel',
                    'acquisition_date': best_obs['acquisition_date'],
                    'cloud_cover': best_obs['cloud_cover_percent'],
                    'distance_m': best_obs['distance_m']
                }
            
            return None
            
        except Exception as e:
            self.logger.warning(f"Database Sentinel query failed: {e}")
            return None
    
    async def _query_copernicus_sentinel_hub(self, lat: float, lon: float) -> Optional[Dict[str, Any]]:
        """Query Copernicus Sentinel Hub for real-time NDVI data"""
        try:
            import aiohttp
            import asyncio
            from datetime import datetime, timedelta
            
            # Copernicus Sentinel Hub Configuration
            sentinel_hub_config = {
                'base_url': 'https://services.sentinel-hub.com',
                'client_id': os.environ.get('COPERNICUS_CLIENT_ID'),
                'client_secret': os.environ.get('COPERNICUS_CLIENT_SECRET'),
                'instance_id': os.environ.get('COPERNICUS_INSTANCE_ID')
            }
            
            if not all(sentinel_hub_config.values()):
                return None
            
            # Get OAuth2 token
            token = await self._get_copernicus_oauth_token(sentinel_hub_config)
            if not token:
                return None
            
            # Define search area (1km x 1km bbox)
            bbox_offset = 0.005  # ~500m
            bbox = [
                lon - bbox_offset, lat - bbox_offset,
                lon + bbox_offset, lat + bbox_offset
            ]
            
            # Process request for NDVI calculation
            headers = {
                'Authorization': f'Bearer {token}',
                'Content-Type': 'application/json'
            }
            
            # Sentinel-2 NDVI calculation request
            payload = {
                'input': {
                    'bounds': {
                        'bbox': bbox,
                        'properties': {'crs': 'http://www.opengis.net/def/crs/EPSG/0/4326'}
                    },
                    'data': [{
                        'type': 'S2L2A',
                        'dataFilter': {
                            'timeRange': {
                                'from': (datetime.now() - timedelta(days=30)).strftime('%Y-%m-%dT00:00:00Z'),
                                'to': datetime.now().strftime('%Y-%m-%dT23:59:59Z')
                            },
                            'maxCloudCoverage': 30
                        }
                    }]
                },
                'output': {
                    'width': 32,
                    'height': 32,
                    'responses': [{
                        'identifier': 'ndvi',
                        'format': {'type': 'image/tiff'}
                    }]
                },
                'evalscript': """
                    function setup() {
                        return {
                            input: ['B04', 'B08', 'CLM', 'SCL'],
                            output: { bands: 1, sampleType: 'FLOAT32' }
                        };
                    }
                    
                    function evaluatePixel(sample) {
                        // Cloud and quality masking
                        if (sample.CLM > 0 || sample.SCL === 3 || sample.SCL === 8 || sample.SCL === 9) {
                            return [NaN];
                        }
                        
                        // NDVI calculation with atmospheric correction
                        let ndvi = (sample.B08 - sample.B04) / (sample.B08 + sample.B04);
                        return [ndvi];
                    }
                """
            }
            
            async with aiohttp.ClientSession() as session:
                async with session.post(
                    f"{sentinel_hub_config['base_url']}/api/v1/process",
                    headers=headers,
                    json=payload,
                    timeout=aiohttp.ClientTimeout(total=60)
                ) as response:
                    if response.status == 200:
                        # Process TIFF response and calculate mean NDVI
                        ndvi_result = await self._process_sentinel_tiff_response(response, lat, lon)
                        if ndvi_result:
                            return {
                                'ndvi': ndvi_result['mean_ndvi'],
                                'quality': ndvi_result['quality_score'],
                                'source': 'copernicus_sentinel_hub',
                                'valid_pixels': ndvi_result['valid_pixels'],
                                'total_pixels': ndvi_result['total_pixels'],
                                'std_dev': ndvi_result.get('std_dev', 0)
                            }
            
            return None
            
        except Exception as e:
            self.logger.warning(f"Copernicus Sentinel Hub query failed: {e}")
            return None
    
    async def _query_esa_scihub_sentinel(self, lat: float, lon: float) -> Optional[Dict[str, Any]]:
        """Query ESA Copernicus Open Access Hub for Sentinel data"""
        try:
            import aiohttp
            from datetime import datetime, timedelta
            
            # ESA SciHub credentials
            username = os.environ.get('ESA_SCIHUB_USERNAME')
            password = os.environ.get('ESA_SCIHUB_PASSWORD')
            
            if not username or not password:
                return None
            
            # Search parameters
            bbox_size = 0.01  # ~1km
            start_date = (datetime.now() - timedelta(days=30)).strftime('%Y-%m-%d')
            end_date = datetime.now().strftime('%Y-%m-%d')
            
            # OpenSearch API query
            search_url = 'https://apihub.copernicus.eu/apihub/search'
            query_params = {
                'q': (
                    f'platformname:Sentinel-2 AND '
                    f'producttype:S2MSI2A AND '
                    f'footprint:"Intersects(POLYGON(({lon-bbox_size} {lat-bbox_size},' 
                    f'{lon+bbox_size} {lat-bbox_size},{lon+bbox_size} {lat+bbox_size},' 
                    f'{lon-bbox_size} {lat+bbox_size},{lon-bbox_size} {lat-bbox_size})))" AND '
                    f'beginposition:[{start_date}T00:00:00.000Z TO {end_date}T23:59:59.999Z] AND '
                    f'cloudcoverpercentage:[0 TO 30]'
                ),
                'rows': 5,
                'orderby': 'beginposition desc',
                'format': 'json'
            }
            
            auth = aiohttp.BasicAuth(username, password)
            
            async with aiohttp.ClientSession(auth=auth) as session:
                async with session.get(
                    search_url, 
                    params=query_params,
                    timeout=aiohttp.ClientTimeout(total=60)
                ) as response:
                    if response.status == 200:
                        data = await response.json()
                        
                        if data.get('feed', {}).get('entry'):
                            # Process the most recent suitable product
                            best_product = await self._select_best_sentinel_product(
                                data['feed']['entry'], lat, lon
                            )
                            
                            if best_product:
                                # Download and process NDVI from selected product
                                ndvi_result = await self._process_sentinel_product_ndvi(
                                    best_product, lat, lon, session
                                )
                                if ndvi_result:
                                    return {
                                        'ndvi': ndvi_result['ndvi'],
                                        'quality': ndvi_result['quality'],
                                        'source': 'esa_scihub',
                                        'product_id': best_product.get('id'),
                                        'acquisition_date': best_product.get('date')
                                    }
            
            return None
            
        except Exception as e:
            self.logger.warning(f"ESA SciHub query failed: {e}")
            return None
    
