    async def _get_geological_features(self, lat: float, lon: float) -> List[float]:
        """Get comprehensive geological features using database and external sources"""
        try:
            from .database_integration import PostgreSQLGISManager, DatabaseConfig
            from .external_data_connectors import USGSConnector, DataIntegrationManager
            import numpy as np
            
            geological_features = []
            
            # Query geological database for nearby structures
            geological_data = await self._query_geological_database(lat, lon)
            
            if geological_data:
                # Extract comprehensive geological features
                features = await self._extract_geological_features(geological_data, lat, lon)
                if features:
                    return features
            
            # Fallback to external data sources
            external_features = await self._get_external_geological_data(lat, lon)
            if external_features:
                return external_features
            
            # Final fallback: geological interpolation from regional data
            return await self._interpolate_geological_features(lat, lon)
            
        except Exception as e:
            self.logger.error(f"Geological feature extraction failed for {lat}, {lon}: {e}")
