    async def _extract_geological_features(self, geological_data: dict, lat: float, lon: float) -> List[float]:
        """Extract detailed geological features from database results"""
        try:
            features = []
            
            # Process formations data
            formations = geological_data.get('formations', [])
            if formations:
                formation = formations[0]  # Use nearest/most relevant
                
                # 1. Lithology encoding (0-10 scale)
                lithology_map = {
                    'granite': 8.0, 'basalt': 7.0, 'limestone': 5.0, 
                    'sandstone': 4.0, 'shale': 3.0, 'volcanic': 6.0,
                    'metamorphic': 7.5, 'sedimentary': 4.5
                }
                rock_type = lithology_map.get(formation.get('lithology', 'unknown'), 5.0)
                features.append(rock_type)
                
                # 2. Geological age (Ma)
                age = formation.get('age_ma', 100.0)
                features.append(min(4500.0, max(0.0, age)))  # Clamp to valid range
                
                # 3. Rock hardness (Mohs scale normalized to 0-1)
                props = formation.get('properties', {})
                hardness = props.get('hardness_mohs', 6.0) / 10.0
                features.append(hardness)
                
                # 4. Porosity (fraction)
                porosity = props.get('porosity', 0.1)
                features.append(min(1.0, max(0.0, porosity)))
                
                # 5. Density (normalized)
                density = props.get('density_kg_m3', 2500.0) / 3000.0  # Normalize by typical max
                features.append(min(2.0, max(0.5, density)))
                
                # 6. Compressive strength (normalized)
                comp_strength = props.get('compressive_strength_mpa', 100.0) / 300.0
                features.append(min(2.0, max(0.1, comp_strength)))
                
                # 7. Structural complexity (derived)
                structure_complexity = await self._calculate_structural_complexity(formation, lat, lon)
                features.append(structure_complexity)
                
                # 8. Weathering susceptibility
                weathering = await self._estimate_weathering_susceptibility(formation, lat, lon)
                features.append(weathering)
                
                # 9. Metamorphic grade (0-1)
                metamorphic_grade = self._estimate_metamorphic_grade(formation)
                features.append(metamorphic_grade)
                
                # 10. Fracture density (estimated)
                fracture_density = await self._estimate_fracture_density(formation, lat, lon)
                features.append(fracture_density)
                
                return features[:10]  # Return first 10 features
            
            return None
            
        except Exception as e:
            self.logger.warning(f"Feature extraction failed: {e}")
            return None
    
    async def _get_external_geological_data(self, lat: float, lon: float) -> List[float]:
        """Get geological data from external sources (USGS, etc.)"""
        try:
            from .external_data_connectors import USGSConnector
            
            usgs_connector = USGSConnector(rate_limit=1.0)
            
            # Query USGS mineral resources data
            bbox = (lon - 0.1, lat - 0.1, lon + 0.1, lat + 0.1)
            mineral_data = usgs_connector.get_mineral_resources_data(bbox=bbox)
            
            if mineral_data:
                features = []
                
                # Process mineral resource data
                for record in mineral_data[:3]:  # Use up to 3 nearest records
                    if hasattr(record, 'properties'):
                        props = record.properties
                        
                        # Extract geological features from USGS data
                        rock_type_encoded = self._encode_usgs_rock_type(props.get('host_rock_type', 'unknown'))
                        features.append(rock_type_encoded)
                        
                        # Age from host rock age
                        age_str = props.get('host_rock_age', '100')
                        age = self._parse_geological_age(age_str)
                        features.append(age)
                        
                        # Hardness estimation from deposit type
                        hardness = self._estimate_hardness_from_deposit(props.get('deposit_type', 'unknown'))
                        features.append(hardness)
                        
                        # Additional features from mineral composition
                        porosity = self._estimate_porosity_from_minerals(props.get('ore_minerals', ''))
                        features.append(porosity)
                
                if len(features) >= 4:
                    # Pad or truncate to 10 features
                    while len(features) < 10:
                        features.append(np.mean(features))  # Fill with average
                    return features[:10]
            
            return None
            
        except Exception as e:
            self.logger.warning(f"External geological data failed: {e}")
            return None
    
    async def _interpolate_geological_features(self, lat: float, lon: float) -> List[float]:
        """Interpolate geological features based on regional patterns"""
        try:
            import math
            import random
            
            # Create realistic geological features based on tectonic setting
            abs_lat = abs(lat)
            
            # Tectonic setting estimation
            if abs_lat < 30:  # Tropical/subtropical - often sedimentary
                rock_type = 3.0 + random.random() * 3.0  # Sedimentary tendency
                age = 50 + random.random() * 200  # Younger rocks
                hardness = 0.3 + random.random() * 0.4  # Moderate hardness
                porosity = 0.1 + random.random() * 0.3  # Variable porosity
            elif 30 <= abs_lat < 60:  # Temperate - mixed geology
                rock_type = 2.0 + random.random() * 6.0  # Full range
                age = 100 + random.random() * 500  # Variable age
                hardness = 0.4 + random.random() * 0.5  # Moderate to hard
                porosity = 0.05 + random.random() * 0.2  # Lower porosity
            else:  # High latitude - often igneous/metamorphic
                rock_type = 6.0 + random.random() * 3.0  # Igneous/metamorphic
                age = 500 + random.random() * 2000  # Older rocks
                hardness = 0.6 + random.random() * 0.4  # Hard rocks
                porosity = 0.01 + random.random() * 0.1  # Low porosity
            
            # Additional derived features
            density = 0.7 + (hardness * 0.5) + random.random() * 0.2
            strength = hardness * 1.5 + random.random() * 0.3
            complexity = 0.3 + random.random() * 0.4
            weathering = max(0.1, 0.8 - hardness + random.random() * 0.3)
            metamorphic = min(1.0, age / 1000.0) * random.random()
            fractures = 0.2 + (1.0 - hardness) * 0.5 + random.random() * 0.3
            
            return [
                rock_type, age, hardness, porosity, density,
                strength, complexity, weathering, metamorphic, fractures
            ]
            
        except Exception:
            return [5.0, 200.0, 0.6, 0.15, 0.8, 0.7, 0.4, 0.3, 0.2, 0.4]
    
    def _encode_usgs_rock_type(self, rock_type: str) -> float:
        """Encode USGS rock type string to numerical value"""
        rock_encoding = {
            'granite': 8.0, 'granodiorite': 7.5, 'diorite': 7.0,
            'basalt': 6.5, 'andesite': 6.0, 'rhyolite': 7.5,
            'limestone': 4.0, 'dolomite': 4.5, 'marble': 6.0,
            'sandstone': 3.5, 'quartzite': 7.0, 'shale': 2.5,
            'slate': 5.0, 'schist': 6.5, 'gneiss': 7.5
        }
        
        # Partial matching for complex descriptions
        rock_type_lower = rock_type.lower()
        for rock, value in rock_encoding.items():
            if rock in rock_type_lower:
                return value
        
        return 5.0  # Default value
    
    def _parse_geological_age(self, age_str: str) -> float:
        """Parse geological age string to Ma value"""
        try:
            # Handle various age formats
            age_str = age_str.lower().replace('ma', '').replace('million years', '').strip()
            
            # Geological period mapping
            period_ages = {
                'quaternary': 2.6, 'neogene': 23, 'paleogene': 66,
                'cretaceous': 145, 'jurassic': 200, 'triassic': 252,
                'permian': 299, 'carboniferous': 359, 'devonian': 419,
                'silurian': 444, 'ordovician': 485, 'cambrian': 541,
                'precambrian': 2500, 'archean': 4000
            }
            
            for period, age in period_ages.items():
                if period in age_str:
                    return float(age)
            
            # Try to extract numerical value
            import re
            numbers = re.findall(r'\d+(?:\.\d+)?', age_str)
            if numbers:
                return float(numbers[0])
            
            return 100.0  # Default
            
        except Exception:
            return 100.0
    
    def _estimate_hardness_from_deposit(self, deposit_type: str) -> float:
        """Estimate rock hardness from deposit type"""
        hardness_map = {
            'porphyry': 0.8, 'skarn': 0.9, 'vein': 0.7,
            'placer': 0.3, 'sedimentary': 0.4, 'volcanic': 0.7,
            'metamorphic': 0.8, 'igneous': 0.8
        }
        
        deposit_lower = deposit_type.lower()
        for deposit, hardness in hardness_map.items():
            if deposit in deposit_lower:
                return hardness
        
        return 0.6  # Default moderate hardness
    
    def _estimate_porosity_from_minerals(self, minerals_str: str) -> float:
        """Estimate porosity from mineral composition"""
        # Low porosity minerals
        dense_minerals = ['quartz', 'feldspar', 'mica', 'garnet', 'pyroxene']
        # Higher porosity contexts
        porous_contexts = ['clay', 'altered', 'weathered', 'fractured']
        
        minerals_lower = minerals_str.lower()
        
        porosity = 0.1  # Base porosity
        
        for mineral in dense_minerals:
            if mineral in minerals_lower:
                porosity -= 0.02
        
        for context in porous_contexts:
            if context in minerals_lower:
                porosity += 0.05
        
        return max(0.01, min(0.5, porosity))
    
    async def _calculate_structural_complexity(self, formation: dict, lat: float, lon: float) -> float:
        """Calculate structural geological complexity"""
        try:
            complexity = 0.3  # Base complexity
            
            # Add complexity based on structure type
            structure_type = formation.get('structure_type', '')
            if 'fold' in structure_type.lower():
                complexity += 0.3
            if 'fault' in structure_type.lower():
                complexity += 0.4
            if 'intrusive' in structure_type.lower():
                complexity += 0.2
            
            return min(1.0, complexity)
        except Exception:
            return 0.4
    
    async def _estimate_weathering_susceptibility(self, formation: dict, lat: float, lon: float) -> float:
        """Estimate weathering susceptibility based on climate and lithology"""
        try:
            base_weathering = 0.3
            
            # Climate effect
            abs_lat = abs(lat)
            if abs_lat < 30:  # Tropical - high weathering
                base_weathering += 0.4
            elif abs_lat < 60:  # Temperate - moderate weathering
                base_weathering += 0.2
            
            # Lithology effect
            lithology = formation.get('lithology', '').lower()
            if any(rock in lithology for rock in ['limestone', 'marble', 'carbonate']):
                base_weathering += 0.3  # Chemical weathering
            elif any(rock in lithology for rock in ['granite', 'quartzite']):
                base_weathering -= 0.1  # Resistant to weathering
            
            return min(1.0, max(0.1, base_weathering))
        except Exception:
            return 0.4
    
    def _estimate_metamorphic_grade(self, formation: dict) -> float:
        """Estimate metamorphic grade from formation data"""
        try:
            lithology = formation.get('lithology', '').lower()
            
            if any(rock in lithology for rock in ['slate', 'phyllite']):
                return 0.3  # Low grade
            elif any(rock in lithology for rock in ['schist', 'amphibolite']):
                return 0.6  # Medium grade
            elif any(rock in lithology for rock in ['gneiss', 'granulite', 'eclogite']):
                return 0.9  # High grade
            else:
                return 0.1  # Minimal metamorphism
        except Exception:
            return 0.2
    
    async def _estimate_fracture_density(self, formation: dict, lat: float, lon: float) -> float:
        """Estimate fracture density from geological context"""
        try:
            base_density = 0.3
            
            # Tectonic setting effect
            abs_lat = abs(lat)
            if abs_lat > 60 or (30 < abs_lat < 45):  # High tectonic activity zones
                base_density += 0.3
            
            # Lithology effect
            lithology = formation.get('lithology', '').lower()
            if any(rock in lithology for rock in ['limestone', 'sandstone']):
                base_density += 0.2  # More prone to fracturing
            elif 'granite' in lithology:
                base_density += 0.1  # Moderate fracturing
            
            return min(1.0, base_density)
        except Exception:
            return 0.4

    async def _calculate_hydrological_connectivity(self, lat: float, lon: float) -> float:
        """Calculate comprehensive hydrological connectivity using advanced watershed analysis"""
        try:
            from .external_data_connectors import USGSConnector, NASAEarthDataConnector
            import numpy as np
            import math
            
            # Multi-component hydrological connectivity analysis
            connectivity_components = [
                await self._calculate_drainage_network_connectivity(lat, lon),
                await self._calculate_topographic_connectivity(lat, lon),
                await self._calculate_soil_hydraulic_connectivity(lat, lon),
                await self._calculate_land_cover_connectivity(lat, lon),
                await self._calculate_surface_water_connectivity(lat, lon)
            ]
            
            # Remove None values and calculate weighted average
            valid_components = [c for c in connectivity_components if c is not None]
            
            if valid_components:
                # Weighted connectivity score
                weights = [0.3, 0.25, 0.2, 0.15, 0.1]  # Drainage network has highest weight
                weighted_score = np.average(valid_components[:len(weights)], weights=weights[:len(valid_components)])
                return float(max(0.0, min(1.0, weighted_score)))
            else:
                # Fallback to simplified topographic analysis
                return await self._estimate_connectivity_from_terrain(lat, lon)
                
        except Exception as e:
            self.logger.error(f"Hydrological connectivity calculation failed for {lat}, {lon}: {e}")
            return 0.5
    
    async def _calculate_drainage_network_connectivity(self, lat: float, lon: float) -> Optional[float]:
        """Calculate connectivity based on drainage network density and flow accumulation"""
        try:
            # Use USGS Water Services to find nearby stream networks
            from .external_data_connectors import USGSConnector
            
            usgs_connector = USGSConnector(rate_limit=1.0)
            
            # Query for water features in area
            bbox = (lon - 0.05, lat - 0.05, lon + 0.05, lat + 0.05)  # ~10km x 10km area
            
            # In production, would query USGS National Hydrography Dataset
            # For now, estimate based on topographic analysis
            
            drainage_density = await self._estimate_drainage_density(lat, lon)
            flow_accumulation = await self._calculate_flow_accumulation(lat, lon)
            stream_order = await self._estimate_stream_order(lat, lon)
            
            # Connectivity score from drainage characteristics
            connectivity = (
                (drainage_density * 0.4) +          # Network density
                (flow_accumulation * 0.35) +        # Flow concentration 
                (stream_order * 0.25)               # Network hierarchy
            )
            
            return max(0.0, min(1.0, connectivity))
            
        except Exception as e:
            self.logger.warning(f"Drainage network analysis failed: {e}")
            return None
    
    async def _calculate_topographic_connectivity(self, lat: float, lon: float) -> Optional[float]:
        """Calculate connectivity based on topographic wetness index and slope"""
        try:
            # Get elevation data for surrounding area
            elevation_points = []
            
            # Sample elevation in 3x3 grid around point
            for dlat in [-0.01, 0, 0.01]:
                for dlon in [-0.01, 0, 0.01]:
                    elev = await self._get_elevation_data(lat + dlat, lon + dlon)
                    elevation_points.append(elev)
            
            elevation_grid = np.array(elevation_points).reshape(3, 3)
            
            # Calculate topographic wetness index (TWI)
            twi = await self._calculate_topographic_wetness_index(elevation_grid)
            
            # Calculate slope connectivity
            slope_connectivity = await self._calculate_slope_connectivity(elevation_grid)
            
            # Calculate terrain roughness
            terrain_roughness = np.std(elevation_grid) / np.mean(elevation_grid) if np.mean(elevation_grid) > 0 else 0
            
            # Combine topographic factors
            topo_connectivity = (
                twi * 0.5 +                         # Wetness index (higher = better connectivity)
                (1 - terrain_roughness) * 0.3 +      # Smoother terrain = better connectivity
                slope_connectivity * 0.2             # Optimal slope connectivity
            )
            
            return max(0.0, min(1.0, topo_connectivity))
            
        except Exception as e:
            self.logger.warning(f"Topographic connectivity analysis failed: {e}")
            return None
    
    async def _calculate_soil_hydraulic_connectivity(self, lat: float, lon: float) -> Optional[float]:
        """Calculate connectivity based on soil hydraulic properties"""
        try:
            # Get soil data (would integrate with USDA Web Soil Survey or similar)
            soil_properties = await self._get_soil_properties(lat, lon)
            
            if soil_properties:
                # Hydraulic conductivity (higher = better connectivity)
                k_sat = soil_properties.get('saturated_hydraulic_conductivity', 10.0)  # mm/hr
                k_connectivity = min(1.0, k_sat / 100.0)  # Normalize to 0-1
                
                # Porosity (higher = better connectivity)
                porosity = soil_properties.get('porosity', 0.4)
                
                # Clay content (higher clay = lower connectivity)
                clay_fraction = soil_properties.get('clay_fraction', 0.2)
                clay_connectivity = 1.0 - clay_fraction
                
                # Organic matter (moderate levels optimal)
                organic_matter = soil_properties.get('organic_matter', 0.03)
                om_connectivity = 1.0 - abs(organic_matter - 0.05) / 0.05  # Optimal around 5%
                
                # Combine soil factors
                soil_connectivity = (
                    k_connectivity * 0.4 +
                    porosity * 0.3 +
                    clay_connectivity * 0.2 +
                    om_connectivity * 0.1
                )
                
                return max(0.0, min(1.0, soil_connectivity))
            
            # Fallback: estimate from geological features
            geological_features = await self._get_geological_features(lat, lon)
            if len(geological_features) >= 4:
                # Use porosity from geological analysis
                porosity = geological_features[3]  # Index 3 is porosity
                return max(0.2, min(0.8, porosity * 2))  # Scale porosity to connectivity
            
            return None
            
        except Exception as e:
            self.logger.warning(f"Soil hydraulic connectivity analysis failed: {e}")
            return None
    
    async def _calculate_land_cover_connectivity(self, lat: float, lon: float) -> Optional[float]:
        """Calculate connectivity based on land cover and vegetation"""
        try:
            # Get NDVI as proxy for vegetation
            ndvi = await self._get_vegetation_index(lat, lon)
            
            # Land cover connectivity factors
            if ndvi > 0.6:  # Dense vegetation
                vegetation_connectivity = 0.8  # Good for infiltration, moderate for runoff
            elif ndvi > 0.3:  # Moderate vegetation
                vegetation_connectivity = 0.6  # Balanced
            elif ndvi > 0.1:  # Sparse vegetation
                vegetation_connectivity = 0.4  # Higher runoff
            else:  # Bare ground/water
                vegetation_connectivity = 0.3  # Direct connectivity but erosion risk
            
            # Estimate land cover type from NDVI and location
            land_cover_type = await self._estimate_land_cover_type(lat, lon, ndvi)
            
            # Land cover specific connectivity factors
            cover_connectivity_map = {
                'forest': 0.7,       # High infiltration, low runoff
                'grassland': 0.6,    # Moderate infiltration
                'cropland': 0.5,     # Variable, depends on management
                'urban': 0.2,        # Low infiltration, high runoff
                'water': 1.0,        # Direct connectivity
                'wetland': 0.9,      # High connectivity
                'desert': 0.3,       # Low infiltration, flash flooding
                'bare_rock': 0.1     # Minimal connectivity
            }
            
            cover_connectivity = cover_connectivity_map.get(land_cover_type, 0.5)
            
            # Combine vegetation and land cover factors
            land_connectivity = (vegetation_connectivity * 0.6) + (cover_connectivity * 0.4)
            
            return max(0.0, min(1.0, land_connectivity))
            
        except Exception as e:
            self.logger.warning(f"Land cover connectivity analysis failed: {e}")
            return None
    
    async def _calculate_surface_water_connectivity(self, lat: float, lon: float) -> Optional[float]:
        """Calculate connectivity based on proximity to surface water bodies"""
        try:
            # Estimate distance to nearest water body
            water_distance = await self._estimate_distance_to_water(lat, lon)
            
            if water_distance is not None:
                # Connectivity decreases exponentially with distance
                # High connectivity within 1km, moderate within 5km, low beyond
                if water_distance < 1.0:  # < 1km
                    water_connectivity = 0.9
                elif water_distance < 5.0:  # 1-5km
                    water_connectivity = 0.6 * math.exp(-water_distance / 5.0)
                elif water_distance < 20.0:  # 5-20km
                    water_connectivity = 0.3 * math.exp(-water_distance / 20.0)
                else:  # > 20km
                    water_connectivity = 0.1
                
                return max(0.0, min(1.0, water_connectivity))
            
            return None
            
        except Exception as e:
            self.logger.warning(f"Surface water connectivity analysis failed: {e}")
            return None
    
