    async def _calculate_topographic_wetness_index(self, elevation_grid: np.ndarray) -> float:
        """Calculate topographic wetness index from elevation grid"""
        try:
            # TWI = ln(a / tan(b))
            # where a = specific catchment area, b = slope
            
            # Calculate slope from elevation grid
            dy, dx = np.gradient(elevation_grid)
            slope = np.sqrt(dx**2 + dy**2)
            slope_radians = np.arctan(slope)
            
            # Avoid division by zero
            slope_radians = np.maximum(slope_radians, 0.01)
            
            # Simplified catchment area (would use flow accumulation in reality)
            catchment_area = 100.0  # Assume 100 m²/m width
            
            # Calculate TWI for center cell
            center_slope = slope_radians[1, 1]
            twi = math.log(catchment_area / math.tan(center_slope))
            
            # Normalize to 0-1 range (typical TWI range is 2-20)
            normalized_twi = (twi - 2.0) / 18.0
            
            return max(0.0, min(1.0, normalized_twi))
            
        except Exception:
            return 0.5
    
    async def _calculate_slope_connectivity(self, elevation_grid: np.ndarray) -> float:
        """Calculate slope-based connectivity factor"""
        try:
            # Calculate average slope
            dy, dx = np.gradient(elevation_grid)
            slope_magnitude = np.sqrt(dx**2 + dy**2)
            avg_slope = np.mean(slope_magnitude)
            
            # Optimal slope for connectivity (not too flat, not too steep)
            # Peak connectivity around 2-5% slope
            if avg_slope < 0.02:      # Too flat
                connectivity = avg_slope / 0.02 * 0.5  # Low connectivity
            elif avg_slope < 0.05:    # Optimal range
                connectivity = 0.8 + (0.05 - avg_slope) / 0.03 * 0.2  # High connectivity
            elif avg_slope < 0.15:    # Moderate slope
                connectivity = 0.8 - (avg_slope - 0.05) / 0.10 * 0.4  # Decreasing
            else:                     # Too steep
                connectivity = 0.3 * math.exp(-(avg_slope - 0.15) / 0.1)  # Low connectivity
            
            return max(0.0, min(1.0, connectivity))
            
        except Exception:
            return 0.5
    
