    async def _get_us_census_data(self, lat: float, lon: float) -> Optional[float]:
        """Get US Census population data via Census Bureau API"""
        try:
            import aiohttp
            
            # US Census Geocoding API to get FIPS codes
            geocode_url = "https://geocoding.geo.census.gov/geocoder/locations/onelineaddress"
            geocode_params = {
                'address': f"{lat},{lon}",
                'benchmark': 'Public_AR_Current',
                'format': 'json'
            }
            
            async with aiohttp.ClientSession() as session:
                async with session.get(geocode_url, params=geocode_params) as response:
                    if response.status == 200:
                        geocode_data = await response.json()
                        
                        # Extract FIPS codes for detailed population query
                        if 'result' in geocode_data and 'addressMatches' in geocode_data['result']:
                            matches = geocode_data['result']['addressMatches']
                            if matches:
                                components = matches[0]['addressComponents']
                                state_fips = components.get('state')
                                county_fips = components.get('county')
                                tract_fips = components.get('tract')
                                
                                # Query ACS population data
                                if state_fips and county_fips:
                                    return await self._query_acs_population_data(state_fips, county_fips, tract_fips)
            
            # Fallback to simplified distance-based estimation
            return await self._estimate_us_population_by_distance(lat, lon)
            
        except Exception as e:
            self.logger.warning(f"US Census data query failed: {e}")
            return None
    
