    async def _calculate_tropospheric_delay(self, weather_data, lat, lon):
        """Calculate tropospheric delay from weather models"""
        try:
            tropospheric_delay = {
                'delay_mm': 0.0,
                'uncertainty_mm': 1.0,
                'hydrostatic_component_mm': 0.0,
                'wet_component_mm': 0.0
            }
            
            # Extract meteorological parameters
            temperature_k = 288.0  # Default
            pressure_hpa = 1013.0  # Default  
            humidity_percent = 60.0  # Default
            
            if 'weather_models' in weather_data:
                if 'era5' in weather_data['weather_models']:
                    era5_data = weather_data['weather_models']['era5']
                    if 'temperature' in era5_data:
                        temperature_k = era5_data.get('temperature', 288.0)
                    if 'pressure' in era5_data:
                        pressure_hpa = era5_data.get('pressure', 1013.0)
                    if 'humidity' in era5_data:
                        humidity_percent = era5_data.get('humidity', 60.0)
            
            # Hydrostatic delay calculation (simplified)
            # Uses Saastamoinen model approximation
            hydrostatic_delay_mm = 2.3 * pressure_hpa / 1013.0 * 1000  # Convert to mm
            
            # Wet delay calculation
            water_vapor_pressure = humidity_percent / 100.0 * 6.1 * np.exp(17.3 * (temperature_k - 273.15) / (temperature_k - 35.85))
            wet_delay_mm = 0.1 * water_vapor_pressure * 1000  # Convert to mm
            
            tropospheric_delay['hydrostatic_component_mm'] = hydrostatic_delay_mm
            tropospheric_delay['wet_component_mm'] = wet_delay_mm
            tropospheric_delay['delay_mm'] = hydrostatic_delay_mm + wet_delay_mm
            tropospheric_delay['uncertainty_mm'] = max(1.0, tropospheric_delay['delay_mm'] * 0.1)
            
            return tropospheric_delay
            
        except Exception as e:
            self.logger.error(f"Tropospheric delay calculation failed: {e}")
            return {'delay_mm': 2.0, 'uncertainty_mm': 1.0}

    async def _estimate_ionospheric_delay(self, lat, lon, insar_result):
        """Estimate ionospheric delay"""
        try:
            ionospheric_delay = {
                'delay_mm': 0.0,
                'uncertainty_mm': 0.5,
                'tec_units': 0.0,
                'frequency_dependent': True
            }
            
            # Simplified ionospheric delay estimation
            # Depends on latitude (magnetic latitude), time of day, solar activity
            magnetic_lat = abs(lat)
            
            # Base TEC (Total Electron Content) estimation
            base_tec = 10.0 + 20.0 * np.sin(np.radians(magnetic_lat))  # TECU
            
            # Convert TEC to delay (for C-band SAR, ~5.6 cm wavelength)
            # Ionospheric delay is frequency dependent: delay ∝ 1/f²
            frequency_ghz = 5.4  # C-band center frequency
            delay_factor = 40.3 / (frequency_ghz ** 2)  # Constant factor
            
            ionospheric_delay_m = base_tec * delay_factor * 1e16 / 1e18  # Convert units
            ionospheric_delay['delay_mm'] = ionospheric_delay_m * 1000  # Convert to mm
            ionospheric_delay['tec_units'] = base_tec
            ionospheric_delay['uncertainty_mm'] = max(0.3, ionospheric_delay['delay_mm'] * 0.2)
            
            return ionospheric_delay
            
        except Exception as e:
            self.logger.error(f"Ionospheric delay estimation failed: {e}")
            return {'delay_mm': 0.5, 'uncertainty_mm': 0.3}

    async def _apply_ml_phase_screen_correction(self, phase_screen, weather_data, lat, lon):
        """Apply ML-based phase screen correction"""
        try:
            ml_correction = {
                'correction_applied': False,
                'model_confidence': 0.5,
                'residual_correction_mm': 0.0
            }
            
            # If model manager is available, apply ML correction
            if hasattr(self, 'model_manager'):
                try:
                    # Load atmospheric correction model
                    atmo_model = await self.model_manager.load_model(
                        'atmospheric_phase_correction_v1.2'
                    )
                    
                    if atmo_model:
                        # Prepare input features
                        features = self._prepare_ml_features(phase_screen, weather_data, lat, lon)
                        
                        # Apply model prediction
                        residual_correction = await atmo_model.predict(features)
                        
                        ml_correction['correction_applied'] = True
                        ml_correction['model_confidence'] = 0.8
                        ml_correction['residual_correction_mm'] = residual_correction
                        
                except Exception as model_e:
                    self.logger.warning(f"ML model application failed: {model_e}")
            
            return ml_correction
            
        except Exception as e:
            self.logger.error(f"ML phase screen correction failed: {e}")
            return {'correction_applied': False}

    def _prepare_ml_features(self, phase_screen, weather_data, lat, lon):
        """Prepare features for ML atmospheric correction model"""
        try:
            features = []
            
            # Geographic features
            features.extend([lat, lon, abs(lat)])  # Include magnetic latitude approximation
            
            # Atmospheric delay components
            features.append(phase_screen.get('total_delay_mm', 0.0))
            features.append(phase_screen.get('tropospheric_delay', {}).get('delay_mm', 0.0))
            features.append(phase_screen.get('ionospheric_delay', {}).get('delay_mm', 0.0))
            
            # Weather parameters
            if 'quality_metrics' in weather_data:
                features.append(weather_data['quality_metrics'].get('overall_quality', 0.5))
            else:
                features.append(0.5)
            
            # Source count
            features.append(len(weather_data.get('sources', [])))
            
            return np.array(features).reshape(1, -1)
            
        except Exception as e:
            self.logger.error(f"ML feature preparation failed: {e}")
            return np.array([[lat, lon, 0, 0, 0, 0, 0.5, 1]])  # Default features

