    async def _construct_bayesian_prior(self, historical_data: List[Dict], 
                                       value_info: Dict, external_context: Dict) -> Dict:
        """Construct informative Bayesian prior from historical data"""
        try:
            import numpy as np
            from scipy import stats
            
            if not historical_data:
                # Use weakly informative prior
                return {
                    'distribution': 'normal',
                    'mean': value_info.get('value', 0.0),
                    'std': abs(value_info.get('value', 1.0)) * 0.5,
                    'confidence': 0.1
                }
            
            # Extract relevant values from historical data
            values = []
            weights = []
            
            for record in historical_data:
                if record.get('literature_value') is not None:
                    values.append(float(record['literature_value']))
                    # Weight by quality grade and confidence
                    quality_weight = {'A': 1.0, 'B': 0.8, 'C': 0.6, 'D': 0.4}.get(
                        record.get('quality_grade', 'D'), 0.3
                    )
                    confidence_weight = float(record.get('confidence', 0.5))
                    sample_weight = np.log1p(record.get('sample_size', 1)) / 10.0
                    
                    weights.append(quality_weight * confidence_weight + sample_weight)
            
            if not values:
                return {
                    'distribution': 'normal',
                    'mean': value_info.get('value', 0.0),
                    'std': abs(value_info.get('value', 1.0)) * 0.5,
                    'confidence': 0.2
                }
            
            values = np.array(values)
            weights = np.array(weights)
            weights = weights / np.sum(weights)  # Normalize weights
            
            # Fit multiple distributions and select best via AIC
            distributions = {
                'normal': stats.norm,
                'lognormal': stats.lognorm,
                'gamma': stats.gamma,
                'beta': stats.beta
            }
            
            best_dist = None
            best_aic = np.inf
            best_params = {}
            
            for dist_name, dist_class in distributions.items():
                try:
                    # Fit weighted distribution
                    if dist_name == 'normal':
                        mean = np.average(values, weights=weights)
                        std = np.sqrt(np.average((values - mean)**2, weights=weights))
                        params = (mean, std)
                        aic = 2 * 2 - 2 * np.sum(weights * np.log(dist_class.pdf(values, mean, std) + 1e-10))
                    else:
                        params = dist_class.fit(values)
                        aic = 2 * len(params) - 2 * np.sum(np.log(dist_class.pdf(values, *params) + 1e-10))
                    
                    if aic < best_aic:
                        best_aic = aic
                        best_dist = dist_name
                        best_params = params
                        
                except:
                    continue
            
            # Construct prior parameters
            prior = {
                'distribution': best_dist,
                'params': best_params,
                'aic': best_aic,
                'mean': np.average(values, weights=weights),
                'std': np.sqrt(np.average((values - np.average(values, weights=weights))**2, weights=weights)),
                'median': np.median(values),
                'quantiles': {
                    '5%': np.percentile(values, 5),
                    '25%': np.percentile(values, 25),
                    '75%': np.percentile(values, 75),
                    '95%': np.percentile(values, 95)
                },
                'confidence': float(np.mean(weights)),
                'n_samples': len(values)
            }
            
            return prior
            
        except Exception as e:
            self.logger.error(f"Prior construction failed: {e}")
            return {
                'distribution': 'normal',
                'mean': value_info.get('value', 0.0),
                'std': abs(value_info.get('value', 1.0)) * 0.3,
                'confidence': 0.3
            }
    
    async def _ensemble_validation(self, value_info):
        """Advanced ensemble validation using multiple model architectures with real data"""
        try:
            import torch
            import torch.nn as nn
            import numpy as np
            from sklearn.ensemble import (
                RandomForestRegressor, GradientBoostingRegressor, 
                ExtraTreesRegressor, AdaBoostRegressor,
                BaggingRegressor, VotingRegressor
            )
            from sklearn.neural_network import MLPRegressor
            from sklearn.gaussian_process import GaussianProcessRegressor
            from sklearn.gaussian_process.kernels import RBF, Matern, WhiteKernel, ConstantKernel
            from sklearn.svm import SVR
            from sklearn.linear_model import BayesianRidge, ARDRegression
            import xgboost as xgb
            import lightgbm as lgb
            from catboost import CatBoostRegressor
            import psycopg2
            from typing import List, Dict, Tuple
            
            # 1. Retrieve validation data from multiple sources
            validation_data = await self._retrieve_ensemble_validation_data(value_info)
            
            if not validation_data or len(validation_data) < 10:
                # Need minimum samples for ensemble validation
                return await self._fallback_ensemble_validation(value_info)
            
            # 2. Prepare features and targets from validation data
            X_train, y_train, X_val, y_val = await self._prepare_ensemble_data(
                validation_data, value_info
            )
            
            # 3. Initialize diverse ensemble of models
            ensemble_models = {
                # Tree-based models
                'random_forest': RandomForestRegressor(
                    n_estimators=200, max_depth=10, min_samples_split=5,
                    min_samples_leaf=2, max_features='sqrt', bootstrap=True,
                    oob_score=True, n_jobs=-1, random_state=42
                ),
                'gradient_boosting': GradientBoostingRegressor(
                    n_estimators=150, learning_rate=0.05, max_depth=5,
                    min_samples_split=5, min_samples_leaf=3, subsample=0.8,
                    loss='huber', alpha=0.9, random_state=42
                ),
                'extra_trees': ExtraTreesRegressor(
                    n_estimators=200, max_depth=10, min_samples_split=5,
                    min_samples_leaf=2, max_features='sqrt', bootstrap=False,
                    n_jobs=-1, random_state=42
                ),
                
                # Advanced boosting models
                'xgboost': xgb.XGBRegressor(
                    n_estimators=200, learning_rate=0.05, max_depth=6,
                    subsample=0.8, colsample_bytree=0.8, gamma=0.1,
                    reg_alpha=0.1, reg_lambda=1.0, objective='reg:squarederror',
                    n_jobs=-1, random_state=42
                ),
                'lightgbm': lgb.LGBMRegressor(
                    n_estimators=200, learning_rate=0.05, max_depth=8,
                    num_leaves=31, subsample=0.8, colsample_bytree=0.8,
                    reg_alpha=0.1, reg_lambda=1.0, min_child_samples=5,
                    n_jobs=-1, random_state=42
                ),
                'catboost': CatBoostRegressor(
                    iterations=200, learning_rate=0.05, depth=6,
                    l2_leaf_reg=3, bagging_temperature=1, random_strength=1,
                    border_count=128, verbose=False, random_state=42
                ),
                
                # Bayesian models
                'bayesian_ridge': BayesianRidge(
                    n_iter=300, tol=0.001, alpha_1=1e-6, alpha_2=1e-6,
                    lambda_1=1e-6, lambda_2=1e-6, compute_score=True
                ),
                'ard_regression': ARDRegression(
                    n_iter=300, tol=0.001, alpha_1=1e-6, alpha_2=1e-6,
                    lambda_1=1e-6, lambda_2=1e-6, compute_score=True
                ),
                
                # Gaussian Process
                'gaussian_process': GaussianProcessRegressor(
                    kernel=ConstantKernel(1.0, (1e-3, 1e3)) * 
                           Matern(length_scale=1.0, length_scale_bounds=(1e-3, 1e3), nu=1.5) +
                           WhiteKernel(noise_level=1, noise_level_bounds=(1e-10, 1e2)),
                    n_restarts_optimizer=10, alpha=1e-6, normalize_y=True
                ),
                
                # Support Vector Regression
                'svr_rbf': SVR(kernel='rbf', C=1.0, gamma='scale', epsilon=0.1),
                'svr_poly': SVR(kernel='poly', C=1.0, degree=3, epsilon=0.1),
                
                # Neural Network
                'neural_network': MLPRegressor(
                    hidden_layer_sizes=(100, 50, 25), activation='relu',
                    solver='adam', learning_rate='adaptive', max_iter=500,
                    alpha=0.001, batch_size='auto', random_state=42
                )
            }
            
            # 4. Train all models and collect predictions
            ensemble_predictions = {}
            ensemble_scores = {}
            model_uncertainties = {}
            
            for model_name, model in ensemble_models.items():
                try:
                    # Train model
                    model.fit(X_train, y_train)
                    
                    # Make predictions
                    train_pred = model.predict(X_train)
                    val_pred = model.predict(X_val)
                    
                    # Calculate validation score
                    from sklearn.metrics import mean_squared_error, r2_score, mean_absolute_error
                    val_score = 1.0 / (1.0 + mean_squared_error(y_val, val_pred))
                    
                    # Store results
                    ensemble_predictions[model_name] = val_pred
                    ensemble_scores[model_name] = val_score
                    
                    # Estimate model-specific uncertainty
                    if hasattr(model, 'predict_proba') or hasattr(model, 'predict_var'):
                        if hasattr(model, 'predict_var'):
                            _, var = model.predict(X_val, return_std=True)
                            model_uncertainties[model_name] = var
                        else:
                            # Use residuals for uncertainty
                            residuals = np.abs(y_val - val_pred)
                            model_uncertainties[model_name] = np.std(residuals)
                    else:
                        residuals = np.abs(y_val - val_pred)
                        model_uncertainties[model_name] = np.std(residuals)
                        
                except Exception as e:
                    self.logger.warning(f"Model {model_name} failed: {e}")
                    continue
            
            if not ensemble_scores:
                return 0.5  # Default if all models fail
            
            # 5. Advanced ensemble combination strategies
            
            # 5a. Weighted average based on validation scores
            weights = np.array(list(ensemble_scores.values()))
            weights = weights / np.sum(weights)
            weighted_score = np.average(list(ensemble_scores.values()), weights=weights)
            
            # 5b. Bayesian Model Averaging
            bma_score = await self._bayesian_model_averaging(
                ensemble_predictions, ensemble_scores, y_val
            )
            
            # 5c. Stacked generalization (meta-learning)
            stacked_score = await self._stacked_generalization(
                ensemble_predictions, ensemble_scores, X_val, y_val, value_info
            )
            
            # 5d. Dynamic ensemble selection
            dynamic_score = await self._dynamic_ensemble_selection(
                ensemble_models, ensemble_scores, X_val, y_val, value_info
            )
            
            # 6. Calculate ensemble agreement and diversity
            ensemble_agreement = await self._calculate_ensemble_agreement(ensemble_predictions)
            ensemble_diversity = await self._calculate_ensemble_diversity(ensemble_predictions)
            
            # 7. Combine all validation methods
            final_score = (
                weighted_score * 0.25 +
                bma_score * 0.25 +
                stacked_score * 0.30 +
                dynamic_score * 0.20
            )
            
            # Adjust score based on ensemble agreement and diversity
            # High agreement with high diversity is best
            agreement_factor = ensemble_agreement * ensemble_diversity
            final_score = final_score * (0.8 + 0.2 * agreement_factor)
            
            # 8. Store detailed validation results
            validation_details = {
                'ensemble_score': float(final_score),
                'individual_scores': ensemble_scores,
                'weighted_average': float(weighted_score),
                'bayesian_average': float(bma_score),
                'stacked_score': float(stacked_score),
                'dynamic_score': float(dynamic_score),
                'ensemble_agreement': float(ensemble_agreement),
                'ensemble_diversity': float(ensemble_diversity),
                'model_uncertainties': model_uncertainties,
                'n_models': len(ensemble_scores),
                'n_samples': len(y_val)
            }
            
            # Store in instance for later use
            self.last_ensemble_validation = validation_details
            
            return float(final_score)
            
        except Exception as e:
            self.logger.error(f"Advanced ensemble validation failed: {e}")
            return await self._fallback_ensemble_validation(value_info)
    
