    async def _validate_geological_statistics(self, value, property_name, material, context):
        """Validate against geological database statistics"""
        try:
            cursor = self.geological_db_conn.cursor()
            
            # Query geological database for statistical validation
            if property_name in ['density', 'porosity', 'permeability']:
                table_column_map = {
                    'density': ('rock_mechanical_properties', 'density_kg_m3'),
                    'porosity': ('rock_mechanical_properties', 'porosity'),
                    'permeability': ('rock_mechanical_properties', 'permeability_m2')
                }
                
                if property_name in table_column_map:
                    table, column = table_column_map[property_name]
                    
                    cursor.execute(f"""
                        SELECT AVG({column}) as mean, STDDEV({column}) as std,
                               MIN({column}) as min_val, MAX({column}) as max_val,
                               COUNT(*) as sample_count
                        FROM {table}
                        WHERE LOWER(lithology) LIKE LOWER(%s)
                        AND {column} IS NOT NULL
                    """, (f'%{material}%',))
                    
                    result = cursor.fetchone()
                    
                    if result and result[4] > 5:  # At least 5 samples
                        mean, std, min_val, max_val, count = result
                        
                        if std and std > 0:
                            # Calculate Z-score
                            z_score = abs((value - mean) / std)
                            
                            # Convert to confidence (higher for lower z-score)
                            if z_score <= 1:
                                confidence = 0.95
                            elif z_score <= 2:
                                confidence = 0.8
                            elif z_score <= 3:
                                confidence = 0.5
                            else:
                                confidence = 0.1
                            
                            return confidence
                        else:
                            # Use range-based validation
                            if min_val <= value <= max_val:
                                return 0.8
                            else:
                                return 0.3
            
            return 0.6  # Default for unhandled properties
            
        except Exception as e:
            self.logger.error(f"Geological statistics validation failed: {e}")
            return 0.5
    
