    def _get_current_model_version(self):
        """Get current model version with database integration and versioning"""
        try:
            # Database-integrated model versioning
            version_info = asyncio.run(self._get_model_version_from_db())
            if version_info:
                return version_info
                
            # Git-based versioning if available
            git_version = self._get_git_model_version()
            if git_version:
                return git_version
                
            # MLOps model registry integration
            mlops_version = self._get_mlops_model_version()
            if mlops_version:
                return mlops_version
                
            # Semantic versioning with feature tracking
            semantic_version = self._generate_semantic_version()
            
            # Update database with new version
            asyncio.run(self._update_model_version_db(semantic_version))
            
            return semantic_version
            
        except Exception as e:
            self.logger.error(f"Model version retrieval failed: {e}")
            # Generate emergency fallback version
            import time
            fallback_version = {
                'version': f"fallback_v{int(time.time())}",
                'timestamp': datetime.utcnow().isoformat(),
                'status': 'emergency_fallback',
                'error': str(e)
            }
            return fallback_version
    
    def _update_monitoring_metrics(self, start_time, validated_values):
        """Update monitoring metrics after extraction"""
        try:
            import time
            
            # Update performance metrics
            extraction_time = time.time() - start_time
            self.performance_metrics['extraction_times'].append(extraction_time)
            
            # Keep only recent metrics (last 1000)
            if len(self.performance_metrics['extraction_times']) > 1000:
                self.performance_metrics['extraction_times'] = self.performance_metrics['extraction_times'][-1000:]
            
            # Update confidence tracking
            if validated_values:
                confidences = [v.get('confidence', 0) for v in validated_values]
                avg_confidence = sum(confidences) / len(confidences)
                
                # Update rolling average
                current_avg = self.extraction_log['average_confidence']
                total_extractions = self.extraction_log['total_extractions']
                
                self.extraction_log['average_confidence'] = (
                    (current_avg * (total_extractions - 1) + avg_confidence) / total_extractions
                )
            
            # Update property distribution
            for value_info in validated_values:
                material = value_info.get('material', 'unknown')
                if material not in self.extraction_log['material_distribution']:
                    self.extraction_log['material_distribution'][material] = 0
                self.extraction_log['material_distribution'][material] += 1
                
        except Exception as e:
            self.logger.error(f"Error updating monitoring metrics: {e}")
    
    async def _track_extraction_experiment(self, text, entities, validated_values, start_time):
        """Track extraction as MLOps experiment"""
        try:
            if not self.mlops_manager:
                return
            
            import time
            
            experiment_data = {
                'experiment_name': f"property_extraction_{self.property_name}",
                'parameters': {
                    'property_name': self.property_name,
                    'text_length': len(text),
                    'entity_count': len(entities) if entities else 0
                },
                'metrics': {
                    'extraction_time': time.time() - start_time,
                    'values_extracted': len(validated_values),
                    'avg_confidence': sum(v.get('confidence', 0) for v in validated_values) / len(validated_values) if validated_values else 0
                },
                'artifacts': {
                    'extracted_values': validated_values
                }
            }
            
            await self.mlops_manager.log_experiment(experiment_data)
            
        except Exception as e:
            self.logger.error(f"Error tracking MLOps experiment: {e}")
    
    async def _fallback_extraction(self, text, entities):
        """Fallback extraction when advanced systems fail"""
        try:
            # Use basic pattern matching as fallback
            values = []
            
            for pattern in getattr(self, 'regex_patterns', []):
                matches = pattern.finditer(text)
                for match in matches:
                    try:
                        value_str = match.group(1)
                        unit = match.group(2) if match.lastindex > 1 else None
                        
                        value = float(value_str)
                        standardized_value = self._basic_unit_conversion(value, unit)
                        
                        values.append({
                            'value': standardized_value,
                            'original_value': value,
                            'unit': unit,
                            'confidence': 0.5,  # Low confidence for fallback
                            'extraction_method': 'fallback_pattern',
                            'material': 'unknown'
                        })
                        
                    except (ValueError, TypeError):
                        continue
            
            return values
            
        except Exception as e:
            self.logger.error(f"Fallback extraction failed: {e}")
            return []
    
    def _basic_unit_conversion(self, value, unit):
        """Basic unit conversion for fallback"""
        if not unit:
            return value
        
        unit = unit.upper()
        
        # Basic pressure conversions
        if unit in ['MPA', 'MПАMPA']:
            return value * 1e6
        elif unit in ['KPA', 'KПАKPA']:
            return value * 1e3
        elif unit in ['GPA', 'GПАGPA']:
            return value * 1e9
        
        # Basic density conversions
        elif unit in ['G/CM³', 'G/CM3']:
            return value * 1000
        
        return value

