class GeologicalKnowledgeGraphReasoner:
    """Advanced knowledge graph construction and reasoning for geological data"""
    
    def __init__(self):
        self.graph = nx.DiGraph()
        self.entity_embeddings = {}
        self.reasoning_rules = self._initialize_reasoning_rules()
    
    def _initialize_reasoning_rules(self):
        """Initialize geological reasoning rules"""
        return {
            'material_property_rules': [
                {'if': 'high_quartz_content', 'then': 'high_hardness'},
                {'if': 'high_porosity', 'then': 'low_strength'},
                {'if': 'crystalline_structure', 'then': 'anisotropic_properties'}
            ],
            'process_property_rules': [
                {'if': 'metamorphic_process', 'then': 'foliated_structure'},
                {'if': 'igneous_origin', 'then': 'interlocking_crystals'},
                {'if': 'sedimentary_origin', 'then': 'layered_structure'}
            ]
        }
    
    async def construct_knowledge_graph(self, entities, relationships, properties):
        """Construct knowledge graph from extracted information"""
        try:
            # Add entity nodes
            for entity_type, entity_list in entities.items():
                for entity in entity_list:
                    node_id = f"{entity_type}_{hashlib.md5(entity['text'].encode()).hexdigest()[:8]}"
                    self.graph.add_node(node_id, **{
                        'label': entity['text'],
                        'type': entity_type,
                        'confidence': entity.get('confidence', 0.8),
                        'extraction_method': entity.get('extraction_method', 'unknown')
                    })
            
            # Add relationship edges
            for relationship in relationships:
                source_id = self._find_entity_node(relationship['source'])
                target_id = self._find_entity_node(relationship['target'])
                
                if source_id and target_id:
                    self.graph.add_edge(source_id, target_id, **{
                        'relation': relationship['type'],
                        'confidence': relationship.get('confidence', 0.7),
                        'evidence': relationship.get('evidence', [])
                    })
            
            # Add property nodes and connections
            for material, props in properties.items():
                material_node = self._find_material_node(material)
                if material_node:
                    for prop_name, prop_values in props.items():
                        prop_node_id = f"property_{prop_name}_{material}"
                        self.graph.add_node(prop_node_id, **{
                            'label': f"{prop_name}",
                            'type': 'property',
                            'values': prop_values,
                            'material': material
                        })
                        
                        self.graph.add_edge(material_node, prop_node_id, **{
                            'relation': 'has_property',
                            'confidence': 0.9
                        })
            
            return self.graph
            
        except Exception as e:
            logger.error(f"Error constructing knowledge graph: {e}")
            return self.graph
    
    def _find_entity_node(self, entity_text):
        """Find node ID for entity text"""
        for node_id, node_data in self.graph.nodes(data=True):
            if node_data.get('label', '').lower() == entity_text.lower():
                return node_id
        return None
    
    def _find_material_node(self, material_name):
        """Find node ID for material"""
        for node_id, node_data in self.graph.nodes(data=True):
            if (node_data.get('type') == 'geological_materials' and 
                node_data.get('label', '').lower() == material_name.lower()):
                return node_id
        return None

