class UncertaintyQuantificationFramework:
    """Quantify uncertainty in extracted information"""
    
    async def quantify_uncertainty(self, extracted_data):
        """Calculate uncertainty scores for extracted data"""
        try:
            uncertainty_scores = {}
            
            for data_type, data_list in extracted_data.items():
                scores = []
                for item in data_list:
                    # Calculate uncertainty based on multiple factors
                    confidence = item.get('confidence', 0.5)
                    method_reliability = self._get_method_reliability(item.get('extraction_method'))
                    context_strength = self._assess_context_strength(item.get('context', ''))
                    
                    uncertainty = 1.0 - (confidence * method_reliability * context_strength)
                    scores.append(uncertainty)
                
                uncertainty_scores[data_type] = {
                    'mean_uncertainty': np.mean(scores) if scores else 1.0,
                    'std_uncertainty': np.std(scores) if scores else 0.0,
                    'individual_scores': scores
                }
            
            return uncertainty_scores
            
        except Exception as e:
            return {}
    
    def _get_method_reliability(self, method):
        """Get reliability score for extraction method"""
        method_scores = {
            'neural': 0.85,
            'pattern': 0.70,
            'hybrid': 0.90,
            'manual': 0.95,
            'unknown': 0.50
        }
        return method_scores.get(method, 0.50)
    
    def _assess_context_strength(self, context):
        """Assess strength of contextual information"""
        if not context:
            return 0.3
        
        # Check for key indicators
        indicators = ['measured', 'observed', 'tested', 'laboratory', 'field', 'experimental']
        strength = 0.5
        
        for indicator in indicators:
            if indicator in context.lower():
                strength += 0.1
        
        return min(strength, 1.0)

