async def _extract_temporal_information(text, article, nlp, logger):
    """Extract temporal information from the article"""
    
    temporal_info = {
        'publication_date': article.get('publication_date'),
        'temporal_references': [],
        'study_period': None
    }
    
    try:
        if nlp:
            doc = nlp(text[:2000])  # Limit text length
            for ent in doc.ents:
                if ent.label_ in ['DATE', 'TIME']:
                    temporal_info['temporal_references'].append({
                        'text': ent.text,
                        'label': ent.label_,
                        'start': ent.start_char,
                        'end': ent.end_char
                    })
        
    except Exception as e:
        logger.error(f"Error in temporal extraction: {str(e)}")
    
    return temporal_info

