async def _integrate_article_results(extracted, article_id, properties, entities, relationships, local_kg, uncertainty_scores, temporal_info, external_validation, extracted_content, logger):
    """Integrate results from a single article into the main extraction structure"""
    
    try:
        # Store article-specific results
        extracted['extraction_metadata'][article_id] = {
            'properties': properties,
            'entities': entities,
            'relationships': relationships,
            'knowledge_graph_nodes': local_kg.number_of_nodes(),
            'knowledge_graph_edges': local_kg.number_of_edges(),
            'uncertainty_scores': uncertainty_scores,
            'temporal_info': temporal_info,
            'external_validation': external_validation,
            'multimodal_content': extracted_content
        }
        
        # Merge into global knowledge structures
        for material, props in properties.items():
            if material not in extracted['properties']:
                extracted['properties'][material] = {}
            
            for prop_category, prop_values in props.items():
                if prop_category not in extracted['properties'][material]:
                    extracted['properties'][material][prop_category] = []
                extracted['properties'][material][prop_category].extend(prop_values)
        
        # Merge knowledge graph
        extracted['knowledge_graph'] = nx.compose(extracted['knowledge_graph'], local_kg)
        
    except Exception as e:
        logger.error(f"Error integrating article results: {str(e)}")

async def _consolidate_cross_article_knowledge(extracted, kg_reasoner, sentence_model, logger):
    """Consolidate knowledge across multiple articles"""
    
    try:
        # Consolidate property values
        consolidated = {'properties': {}, 'knowledge_graph': extracted['knowledge_graph']}
        
        for material, categories in extracted['properties'].items():
            consolidated['properties'][material] = {}
            
            for category, prop_list in categories.items():
                # Statistical consolidation of property values
                if prop_list:
                    values = [item['value'] for item in prop_list if isinstance(item, dict) and 'value' in item]
                    if values:
                        consolidated['properties'][material][category] = {
                            'mean': np.mean(values),
                            'std': np.std(values),
                            'min': np.min(values),
                            'max': np.max(values),
                            'count': len(values),
                            'individual_values': prop_list
                        }
        
        return consolidated
        
    except Exception as e:
        logger.error(f"Error in knowledge consolidation: {str(e)}")
        return extracted

async def _validate_extracted_knowledge(consolidated_knowledge, external_validation, uncertainty_framework, logger):
    """Validate and refine extracted knowledge"""
    
    try:
        # Apply validation rules and filters
        validated = {}
        
        for material, properties in consolidated_knowledge.get('properties', {}).items():
            validated[material] = {}
            
            for prop_name, prop_data in properties.items():
                # Apply statistical validation
                if isinstance(prop_data, dict) and 'count' in prop_data:
                    if prop_data['count'] >= 2:  # Minimum sample size
                        # Calculate confidence interval
                        mean_val = prop_data['mean']
                        std_val = prop_data['std']
                        
                        prop_data['confidence_interval'] = (
                            mean_val - 1.96 * std_val,
                            mean_val + 1.96 * std_val
                        )
                        prop_data['validated'] = True
                    else:
                        prop_data['validated'] = False
                    
                    validated[material][prop_name] = prop_data
        
        return validated
        
    except Exception as e:
        logger.error(f"Error in knowledge validation: {str(e)}")
        return consolidated_knowledge

async def _generate_extraction_report(validated_knowledge, article_count, logger):
    """Generate comprehensive extraction report"""
    
    report = {
        'summary': {
            'articles_processed': article_count,
            'materials_identified': len(validated_knowledge.keys()),
            'properties_extracted': 0,
            'average_confidence': 0.0
        },
        'material_coverage': {},
        'property_statistics': {},
        'quality_metrics': {},
        'recommendations': []
    }
    
    try:
        total_properties = 0
        confidence_scores = []
        
        for material, properties in validated_knowledge.items():
            material_props = 0
            for prop_name, prop_data in properties.items():
                if isinstance(prop_data, dict):
                    material_props += 1
                    total_properties += 1
                    
                    # Collect confidence scores if available
                    if 'individual_values' in prop_data:
                        for val in prop_data['individual_values']:
                            if isinstance(val, dict) and 'confidence' in val:
                                confidence_scores.append(val['confidence'])
            
            report['material_coverage'][material] = material_props
        
        report['summary']['properties_extracted'] = total_properties
        if confidence_scores:
            report['summary']['average_confidence'] = np.mean(confidence_scores)
        
        # Generate recommendations
        if total_properties < 10:
            report['recommendations'].append("Consider expanding literature search for more comprehensive property coverage")
        
        if report['summary']['average_confidence'] < 0.7:
            report['recommendations'].append("Low average confidence scores suggest need for additional validation")
        
        return report
        
    except Exception as e:
        logger.error(f"Error generating extraction report: {str(e)}")
        return report

async def _fallback_basic_extraction(articles, logger):
    """Fallback to basic regex-based extraction if neural models fail"""
    
    extracted = {}
    
    try:
        for article in articles:
            text = article.get('abstract', '') + ' ' + article.get('full_text', '')
            
            # Basic regex patterns
            patterns = {
                'ucs': r'(?:UCS|compressive strength|σ_c).*?(\d+\.?\d*)\s*(?:MPa|kPa)',
                'tensile_strength': r'(?:tensile|σ_t).*?(\d+\.?\d*)\s*(?:MPa|kPa)',
                'elastic_modulus': r'(?:Young|elastic modulus|E).*?(\d+\.?\d*)\s*(?:GPa|MPa)',
                'poisson_ratio': r'(?:Poisson|ν).*?(\d+\.?\d*)',
                'cohesion': r'(?:cohesion|c).*?(\d+\.?\d*)\s*(?:MPa|kPa)',
                'friction_angle': r'(?:friction angle|φ).*?(\d+\.?\d*)\s*(?:°|degrees)'
            }
            
            # Extract rock type
            rock_patterns = r'(granite|basalt|limestone|sandstone|shale|marble|quartzite)'
            rock_matches = re.findall(rock_patterns, text.lower())
            
            if rock_matches:
                rock_type = rock_matches[0]
                if rock_type not in extracted:
                    extracted[rock_type] = {'mechanical': {}}
                
                # Extract property values
                for prop, pattern in patterns.items():
                    matches = re.findall(pattern, text)
                    if matches:
                        try:
                            value = float(matches[0])
                            # Convert units if needed
                            if prop in ['ucs', 'tensile_strength', 'cohesion']:
                                value *= 1e6  # Convert MPa to Pa
                            elif prop == 'elastic_modulus':
                                value *= 1e9  # Convert GPa to Pa
                            extracted[rock_type]['mechanical'][prop] = value
                        except ValueError:
                            continue
        
    except Exception as e:
        logger.warning(f"Fallback extraction failed: {e}")
    
    return {
        'extracted_knowledge': extracted,
        'extraction_report': {'fallback_mode': True},
        'processing_metadata': {'fallback_extraction': True}
    }

def merge_property_dicts(dict1, dict2):
    """Advanced merge of property dictionaries with uncertainty propagation and conflict resolution"""
    import numpy as np
    from datetime import datetime
    
    for category in dict2:
        if category not in dict1:
            dict1[category] = {}
        
        for prop, value in dict2[category].items():
            if prop in dict1[category]:
                existing_value = dict1[category][prop]
                
                # Handle uncertainty-aware merging
                if isinstance(value, dict) and isinstance(existing_value, dict):
                    if 'mean' in value and 'uncertainty' in value:
                        # Weighted average based on uncertainty
                        w1 = 1.0 / (existing_value.get('uncertainty', 1.0) ** 2)
                        w2 = 1.0 / (value.get('uncertainty', 1.0) ** 2)
                        
                        merged_mean = (w1 * existing_value['mean'] + w2 * value['mean']) / (w1 + w2)
                        merged_uncertainty = np.sqrt(1.0 / (w1 + w2))
                        
                        dict1[category][prop] = {
                            'mean': merged_mean,
                            'uncertainty': merged_uncertainty,
                            'confidence': min(existing_value.get('confidence', 0.8), value.get('confidence', 0.8)),
                            'sources': list(set(existing_value.get('sources', []) + value.get('sources', []))),
                            'last_updated': datetime.now().isoformat()
                        }
                    else:
                        dict1[category][prop] = value
                else:
                    dict1[category][prop] = value
            else:
                dict1[category][prop] = value


