    async def _cross_reference_cod_structures(self, session, compound: str) -> Dict[str, Any]:
        """Cross-reference with Crystallography Open Database for validation"""
        try:
            cod_api_url = "http://www.crystallography.net/cod/search"
            
            # Generate search variants
            search_variants = self._generate_formula_variants(compound)
            
            cod_matches = []
            
            for variant in search_variants[:3]:
                params = {
                    'text': variant,
                    'format': 'json',
                    'limit': 10
                }
                
                try:
                    await asyncio.sleep(0.2)
                    
                    async with session.get(cod_api_url, params=params) as response:
                        if response.status == 200:
                            data = await response.json()
                            if data and isinstance(data, list):
                                for entry in data:
                                    if self._validate_cod_entry(entry, compound):
                                        cod_matches.append({
                                            'cod_id': entry.get('id'),
                                            'formula': entry.get('formula'),
                                            'space_group': entry.get('space_group'),
                                            'cell_parameters': entry.get('cell'),
                                            'publication': entry.get('publication'),
                                            'match_confidence': self._calculate_match_confidence(entry, compound)
                                        })
                
                except Exception as e:
                    self.logger.debug(f"COD search failed for {variant}: {e}")
                    continue
            
            if cod_matches:
                # Sort by match confidence
                cod_matches.sort(key=lambda x: x['match_confidence'], reverse=True)
                
                return {
                    'open_structures': cod_matches[:5],  # Top 5 matches
                    'total_matches': len(cod_matches),
                    'cross_validation_score': np.mean([m['match_confidence'] for m in cod_matches])
                }
            
        except Exception as e:
            self.logger.debug(f"COD cross-reference failed: {e}")
        
        return {}
    
    def _construct_csd_search_queries(self, compound: str) -> Dict[str, Dict]:
        """Construct optimized CSD search queries for different search types"""
        queries = {}
        
        # Exact formula search
        queries['formula'] = {
            'query_type': 'formula',
            'formula': compound,
            'exact_match': True,
            'include_polymorphs': True
        }
        
        # Substructure search
        queries['substructure'] = {
            'query_type': 'substructure',
            'pattern': self._generate_substructure_pattern(compound),
            'tolerance': 0.1
        }
        
        # Text-based search
        queries['text'] = {
            'query_type': 'text',
            'search_terms': [compound] + self._generate_synonyms(compound),
            'include_derivatives': True
        }
        
        # Property-based search
        if self._has_known_properties(compound):
            queries['properties'] = {
                'query_type': 'properties',
                'formula': compound,
                'property_filters': self._get_property_filters(compound)
            }
        
        return queries
    
    async def _analyze_crystal_structures(self, csd_data: Dict, compound: str) -> Dict[str, Any]:
        """Advanced crystal structure analysis and validation"""
        try:
            analysis_results = {
                'structural_analysis': {},
                'polymorphism_analysis': {},
                'phase_relationships': {},
                'thermodynamic_stability': {}
            }
            
            # Extract all structures from different sources
            all_structures = []
            
            # Process structures from different tiers
            for source_key, source_data in csd_data.items():
                if isinstance(source_data, dict) and 'structures' in source_data:
                    structures = source_data['structures']
                    if isinstance(structures, list):
                        all_structures.extend(structures)
            
            if not all_structures:
                return analysis_results
            
            # Structural analysis
            analysis_results['structural_analysis'] = await self._perform_structural_analysis(all_structures)
            
            # Polymorphism detection and analysis
            polymorphs = await self._detect_polymorphs(all_structures, compound)
            if polymorphs:
                analysis_results['polymorphism_analysis'] = polymorphs
            
            # Phase relationship mapping
            phase_data = await self._map_phase_relationships(all_structures, compound)
            if phase_data:
                analysis_results['phase_relationships'] = phase_data
            
            # Thermodynamic stability assessment
            stability_data = await self._assess_thermodynamic_stability(all_structures, compound)
            if stability_data:
                analysis_results['thermodynamic_stability'] = stability_data
            
            # Add metadata
            analysis_results['analysis_metadata'] = {
                'total_structures_analyzed': len(all_structures),
                'analysis_timestamp': datetime.now().isoformat(),
                'compound': compound,
                'analysis_methods': ['structural', 'polymorphism', 'phase_mapping', 'thermodynamic']
            }
            
            # Update original data with analysis
            csd_data['advanced_analysis'] = analysis_results
            
            return csd_data
            
        except Exception as e:
            self.logger.error(f"Crystal structure analysis failed: {e}")
            return csd_data
    
    async def _predict_properties_from_structure(self, csd_data: Dict) -> Dict[str, Any]:
        """ML-based property prediction from crystal structures"""
        try:
            # Check if we have structural data
            structures = []
            for source_data in csd_data.values():
                if isinstance(source_data, dict) and 'structures' in source_data:
                    structures.extend(source_data['structures'])
            
            if not structures:
                return {}
            
            ml_predictions = {
                'mechanical_properties': {},
                'thermal_properties': {},
                'electronic_properties': {},
                'ensemble_predictions': {}
            }
            
            # Extract structural features for ML models
            structural_features = await self._extract_structural_features(structures)
            
            if not structural_features:
                return {}
            
            # Mechanical property predictions
            mechanical_model = await self._load_mechanical_property_model()
            if mechanical_model:
                mech_pred = mechanical_model.predict(structural_features)
                ml_predictions['mechanical_properties'] = {
                    'bulk_modulus_gpa': float(mech_pred.get('bulk_modulus', 0)),
                    'shear_modulus_gpa': float(mech_pred.get('shear_modulus', 0)),
                    'youngs_modulus_gpa': float(mech_pred.get('youngs_modulus', 0)),
                    'poissons_ratio': float(mech_pred.get('poissons_ratio', 0)),
                    'hardness_gpa': float(mech_pred.get('hardness', 0))
                }
            
            # Thermal property predictions
            thermal_model = await self._load_thermal_property_model()
            if thermal_model:
                thermal_pred = thermal_model.predict(structural_features)
                ml_predictions['thermal_properties'] = {
                    'thermal_conductivity': float(thermal_pred.get('thermal_conductivity', 0)),
                    'thermal_expansion': float(thermal_pred.get('thermal_expansion', 0)),
                    'melting_point_k': float(thermal_pred.get('melting_point', 0)),
                    'debye_temperature': float(thermal_pred.get('debye_temperature', 0))
                }
            
            # Electronic property predictions
            electronic_model = await self._load_electronic_property_model()
            if electronic_model:
                elec_pred = electronic_model.predict(structural_features)
                ml_predictions['electronic_properties'] = {
                    'band_gap_ev': float(elec_pred.get('band_gap', 0)),
                    'dielectric_constant': float(elec_pred.get('dielectric_constant', 0)),
                    'electrical_conductivity': float(elec_pred.get('electrical_conductivity', 0))
                }
            
            # Ensemble predictions with uncertainty quantification
            ensemble_pred = await self._ensemble_structure_predictions(structural_features)
            if ensemble_pred:
                ml_predictions['ensemble_predictions'] = ensemble_pred
            
            # Add prediction metadata
            ml_predictions['prediction_metadata'] = {
                'structures_analyzed': len(structures),
                'feature_dimensions': len(structural_features) if isinstance(structural_features, list) else structural_features.shape if hasattr(structural_features, 'shape') else 0,
                'model_versions': {
                    'mechanical': '2.1.0',
                    'thermal': '2.0.5', 
                    'electronic': '1.9.3'
                },
                'prediction_confidence': ensemble_pred.get('confidence', 0.5) if ensemble_pred else 0.5,
                'prediction_timestamp': datetime.now().isoformat()
            }
            
            return ml_predictions
            
        except Exception as e:
            self.logger.error(f"ML property prediction failed: {e}")
            return {}
    
    async def _cache_csd_data(self, compound: str, csd_data: Dict):
        """Cache CSD data in database with intelligent storage management"""
        try:
            # Use the database integration module
            if hasattr(self, 'database_manager') and self.database_manager:
                
                # Prepare cache entry
                cache_entry = {
                    'compound': compound,
                    'csd_data': csd_data,
                    'cache_timestamp': datetime.now(),
                    'data_sources': list(csd_data.keys()),
                    'structure_count': sum(
                        len(data.get('structures', [])) 
                        for data in csd_data.values() 
                        if isinstance(data, dict) and 'structures' in data
                    ),
                    'cache_version': '2.0.0'
                }
                
                # Store in appropriate table based on database schema
                await self.database_manager.store_chemical_data(cache_entry)
                
                self.logger.debug(f"CSD data cached for {compound}")
            
            # Also use external data connectors cache
            if hasattr(self, 'external_data_manager') and self.external_data_manager:
                await self.external_data_manager.cache_external_data('csd', compound, csd_data)
            
        except Exception as e:
            self.logger.error(f"CSD data caching failed: {e}")
    
    async def _update_csd_knowledge_graph(self, compound: str, csd_data: Dict):
        """Update knowledge graph with CSD relationships"""
        try:
            if hasattr(self, 'knowledge_graph') and self.knowledge_graph:
                
                # Extract relationships from CSD data
                relationships = []
                
                # Structure-property relationships
                if 'advanced_analysis' in csd_data:
                    analysis = csd_data['advanced_analysis']
                    
                    # Add polymorphic relationships
                    if 'polymorphism_analysis' in analysis:
                        poly_data = analysis['polymorphism_analysis']
                        for polymorph in poly_data.get('polymorphs', []):
                            relationships.append({
                                'type': 'polymorph_of',
                                'source': compound,
                                'target': polymorph.get('variant', ''),
                                'properties': polymorph
                            })
                    
                    # Add phase relationships
                    if 'phase_relationships' in analysis:
                        phase_data = analysis['phase_relationships']
                        for phase in phase_data.get('phases', []):
                            relationships.append({
                                'type': 'phase_transition',
                                'source': compound,
                                'target': phase.get('phase_name', ''),
                                'conditions': phase.get('conditions', {}),
                                'properties': phase
                            })
                
                # ML prediction relationships
                if 'ml_predictions' in csd_data:
                    ml_pred = csd_data['ml_predictions']
                    for prop_category, props in ml_pred.items():
                        if isinstance(props, dict) and prop_category != 'prediction_metadata':
                            for prop_name, prop_value in props.items():
                                relationships.append({
                                    'type': 'predicted_property',
                                    'source': compound,
                                    'property': prop_name,
                                    'value': prop_value,
                                    'category': prop_category,
                                    'confidence': ml_pred.get('prediction_metadata', {}).get('prediction_confidence', 0.5)
                                })
                
                # Update knowledge graph
                await self.knowledge_graph.add_relationships(relationships)
                
                self.logger.debug(f"Knowledge graph updated with {len(relationships)} CSD relationships")
        
        except Exception as e:
            self.logger.error(f"Knowledge graph update failed: {e}")
    
    async def _get_cached_csd_data(self, compound: str) -> Dict[str, Any]:
        """Retrieve cached CSD data with freshness validation"""
        try:
            if hasattr(self, 'database_manager') and self.database_manager:
                cached_data = await self.database_manager.get_chemical_data('csd', compound)
                
                if cached_data:
                    # Check cache freshness (30 days)
                    cache_time = cached_data.get('cache_timestamp')
                    if cache_time and isinstance(cache_time, datetime):
                        age_hours = (datetime.now() - cache_time).total_seconds() / 3600
                        
                        if age_hours < 720:  # 30 days
                            self.logger.debug(f"Using cached CSD data for {compound} (age: {age_hours:.1f}h)")
                            return cached_data.get('csd_data', {})
                        else:
                            self.logger.debug(f"Cached CSD data expired for {compound}")
            
            # Fallback to external data manager cache
            if hasattr(self, 'external_data_manager') and self.external_data_manager:
                return await self.external_data_manager.get_cached_data('csd', compound)
            
        except Exception as e:
            self.logger.debug(f"Cache retrieval failed: {e}")
        
        return {}
    
