    async def _perform_structural_analysis(self, structures: List[Dict]) -> Dict[str, Any]:
        """Comprehensive structural analysis of crystal structures"""
        if not structures:
            return {}
        
        analysis = {
            'space_group_distribution': {},
            'cell_parameter_statistics': {},
            'symmetry_analysis': {},
            'structural_motifs': []
        }
        
