    def _prepare_ml_features(self, compound_data: Dict[str, Any]) -> np.ndarray:
        """Prepare feature vector for ML models"""
        features = []
        
        # Basic molecular descriptors
        features.append(compound_data.get('molecular_weight', 0))
        features.append(compound_data.get('critical_temperature', 0))
        features.append(compound_data.get('critical_pressure', 0))
        features.append(compound_data.get('critical_density', 0))
        features.append(compound_data.get('acentric_factor', 0))
        features.append(compound_data.get('dipole_moment', 0))
        features.append(compound_data.get('polarizability', 0))
        features.append(compound_data.get('ionization_energy', 0))
        features.append(compound_data.get('electron_affinity', 0))
        
        # Thermodynamic properties
        features.append(compound_data.get('enthalpy_of_formation', 0))
        features.append(compound_data.get('gibbs_energy_of_formation', 0))
        features.append(compound_data.get('entropy_298', 0))
        
        # Add heat capacity coefficients if available
        cp_coeffs = compound_data.get('heat_capacity_constants', {})
        features.append(cp_coeffs.get('A', 0))
        features.append(cp_coeffs.get('B', 0))
        features.append(cp_coeffs.get('C', 0))
        features.append(cp_coeffs.get('D', 0))
        
        return np.array(features)
    
    def _create_molecular_graph(self, compound_data: Dict[str, Any]):
        """
        Create advanced molecular graph representation for GNN using real chemical databases.
        Integrates with PubChem, ChEMBL, and ChemSpider for comprehensive molecular structure data.
        """
        try:
            import torch
            import numpy as np
            from collections import defaultdict
            import asyncio
            import aiohttp
            import json
            import requests
            from rdkit import Chem
            from rdkit.Chem import Descriptors, rdMolDescriptors
            from rdkit.Chem.rdmolops import GetAdjacencyMatrix
            from rdkit.Chem.Crippen import MolLogP
            from rdkit.Chem.Descriptors import MolWt
            
        except ImportError as e:
            self.logger.warning(f"Required chemistry libraries not available: {e}")
            return self._fallback_molecular_graph(compound_data)
        
        try:
            # Validate input data
            if not compound_data or not isinstance(compound_data, dict):
                self.logger.error("Invalid compound_data provided to _create_molecular_graph")
                return self._create_fallback_graph({'formula': 'Unknown'})
            
            # Extract and validate molecular identifiers from compound data
            smiles = compound_data.get('smiles') or compound_data.get('CanonicalSMILES')
            inchi = compound_data.get('inchi') or compound_data.get('InChI') 
            pubchem_cid = compound_data.get('pubchem_cid') or compound_data.get('CID')
            formula = compound_data.get('formula') or compound_data.get('MolecularFormula')
            compound_name = compound_data.get('name') or compound_data.get('compound', '')
            
            # Input validation
            if smiles and not isinstance(smiles, str):
                self.logger.warning(f"Invalid SMILES format: {type(smiles)}")
                smiles = None
            if inchi and not isinstance(inchi, str):
                self.logger.warning(f"Invalid InChI format: {type(inchi)}")
                inchi = None
            if formula and not isinstance(formula, str):
                self.logger.warning(f"Invalid formula format: {type(formula)}")
                formula = None
            if compound_name and not isinstance(compound_name, str):
                compound_name = str(compound_name)
            
            # Log the identifiers found
            identifiers = {
                'smiles': bool(smiles),
                'inchi': bool(inchi), 
                'pubchem_cid': bool(pubchem_cid),
                'formula': bool(formula),
                'compound_name': bool(compound_name)
            }
            self.logger.info(f"Molecular identifiers available: {identifiers} for compound: {compound_name}")
            
            # Check if we have any usable molecular identifiers
            if not any([smiles, inchi, pubchem_cid, formula, compound_name]):
                self.logger.warning("No usable molecular identifiers found in compound_data")
                return self._create_fallback_graph(compound_data)
            
            # Priority order: SMILES > InChI > PubChem lookup > database query
            mol = None
            parsing_method = None
            
            # 1. Try SMILES first (most reliable for graph construction)
            if smiles:
                try:
                    # Additional SMILES validation
                    if len(smiles.strip()) > 0 and not any(char in smiles for char in ['\n', '\r', '\t']):
                        mol = Chem.MolFromSmiles(smiles.strip())
                        if mol is not None:
                            # Validate the parsed molecule
                            if mol.GetNumAtoms() > 0:
                                parsing_method = "SMILES"
                                self.logger.info(f"Successfully parsed molecule from SMILES: {smiles} ({mol.GetNumAtoms()} atoms)")
                            else:
                                mol = None
                                self.logger.warning(f"SMILES parsed but resulted in empty molecule: {smiles}")
                        else:
                            self.logger.warning(f"Failed to parse SMILES: {smiles}")
                    else:
                        self.logger.warning(f"Invalid SMILES string detected: {repr(smiles)}")
                except Exception as e:
                    self.logger.warning(f"SMILES parsing error: {e}")
                    mol = None
            
            # 2. Try InChI if SMILES failed
            if mol is None and inchi:
                try:
                    if inchi.startswith('InChI=') and len(inchi.strip()) > 6:
                        mol = Chem.MolFromInchi(inchi.strip())
                        if mol is not None and mol.GetNumAtoms() > 0:
                            parsing_method = "InChI"
                            self.logger.info(f"Successfully parsed molecule from InChI ({mol.GetNumAtoms()} atoms)")
                        else:
                            self.logger.warning(f"Failed to parse or empty molecule from InChI")
                            mol = None
                    else:
                        self.logger.warning(f"Invalid InChI format: {inchi[:50]}...")
                except Exception as e:
                    self.logger.warning(f"InChI parsing error: {e}")
                    mol = None
            
            # 3. Try PubChem lookup if both failed (with rate limiting and validation)
            if mol is None and (pubchem_cid or compound_name):
                try:
                    mol = self._fetch_molecule_from_pubchem(pubchem_cid, compound_name)
                    if mol is not None and mol.GetNumAtoms() > 0:
                        parsing_method = "PubChem"
                        self.logger.info(f"Successfully fetched molecule from PubChem ({mol.GetNumAtoms()} atoms)")
                    elif mol is not None:
                        self.logger.warning("PubChem returned empty molecule")
                        mol = None
                except Exception as e:
                    self.logger.warning(f"PubChem lookup failed: {e}")
                    mol = None
            
            # 4. Try ChEMBL/ChemSpider lookup if all above failed (with validation)
            if mol is None and compound_name and len(compound_name.strip()) > 1:
                try:
                    mol = self._fetch_molecule_from_external_dbs(compound_name)
                    if mol is not None and mol.GetNumAtoms() > 0:
                        parsing_method = "ExternalDB"
                        self.logger.info(f"Successfully fetched molecule from external DB ({mol.GetNumAtoms()} atoms)")
                    elif mol is not None:
                        self.logger.warning("External DB returned empty molecule")
                        mol = None
                except Exception as e:
                    self.logger.warning(f"External database lookup failed: {e}")
                    mol = None
            
            # 5. If still no molecule, try formula-based generation (last resort with validation)
            if mol is None and formula and len(formula.strip()) > 0:
                try:
                    mol = self._generate_molecule_from_formula(formula.strip())
                    if mol is not None and mol.GetNumAtoms() > 0:
                        parsing_method = "Formula"
                        self.logger.info(f"Generated molecule from formula: {formula} ({mol.GetNumAtoms()} atoms)")
                    elif mol is not None:
                        self.logger.warning(f"Formula-based generation returned empty molecule for: {formula}")
                        mol = None
                except Exception as e:
                    self.logger.warning(f"Formula-based generation failed: {e}")
                    mol = None
            
            # Final validation and fallback
            if mol is None:
                self.logger.warning(f"Could not create molecular graph for compound: {compound_name}")
                return self._create_fallback_graph(compound_data)
            
            # Additional molecule validation
            try:
                if mol.GetNumAtoms() == 0:
                    self.logger.warning("Parsed molecule has no atoms")
                    return self._create_fallback_graph(compound_data)
                
                if mol.GetNumAtoms() > 1000:  # Sanity check for very large molecules
                    self.logger.warning(f"Very large molecule detected ({mol.GetNumAtoms()} atoms), may impact performance")
                
            except Exception as e:
                self.logger.error(f"Error validating parsed molecule: {e}")
                return self._create_fallback_graph(compound_data)
            
            # Sanitize and prepare molecule with error handling
            try:
                Chem.SanitizeMol(mol)
                self.logger.debug("Molecule sanitization successful")
                
                # Add explicit hydrogens with validation
                mol_with_hs = Chem.AddHs(mol)
                if mol_with_hs is not None and mol_with_hs.GetNumAtoms() > 0:
                    mol = mol_with_hs
                    self.logger.debug(f"Added explicit hydrogens: {mol.GetNumAtoms()} total atoms")
                else:
                    self.logger.warning("Failed to add hydrogens, using original molecule")
                
            except Exception as e:
                self.logger.warning(f"Molecule sanitization/hydrogen addition failed: {e}")
                # Continue with unsanitized molecule if possible
                try:
                    if mol.GetNumAtoms() == 0:
                        return self._create_fallback_graph(compound_data)
                except:
                    return self._create_fallback_graph(compound_data)
            
            # Create comprehensive molecular graph with error handling
            try:
                graph_data = self._build_molecular_graph_tensor(mol, compound_data)
                if graph_data is None:
                    self.logger.error("Graph tensor creation failed")
                    return self._create_fallback_graph(compound_data)
                
                # Validate graph data structure
                required_keys = ['x', 'edge_index', 'num_nodes']
                missing_keys = [key for key in required_keys if key not in graph_data]
                if missing_keys:
                    self.logger.warning(f"Graph data missing required keys: {missing_keys}")
                    return self._create_fallback_graph(compound_data)
                
                self.logger.info(f"Successfully created molecular graph using {parsing_method}: {graph_data['num_nodes']} nodes")
                
            except Exception as e:
                self.logger.error(f"Error building molecular graph tensor: {e}")
                return self._create_fallback_graph(compound_data)
            
            # Add external chemical data enrichment with error handling
            try:
                enriched_graph_data = self._enrich_with_chemical_databases(graph_data, compound_data, mol)
                if enriched_graph_data is not None:
                    graph_data = enriched_graph_data
                    self.logger.debug("Successfully enriched graph with chemical database info")
                else:
                    self.logger.warning("Chemical database enrichment returned None, using original graph")
                
            except Exception as e:
                self.logger.warning(f"Error enriching graph with chemical databases: {e}")
                # Continue with non-enriched graph
            
            # Store in model database for future use with error handling
            try:
                if hasattr(self, 'model_database') and self.model_database and compound_name:
                    self._cache_molecular_graph(compound_name, graph_data, mol)
                    self.logger.debug(f"Cached molecular graph for {compound_name}")
                else:
                    self.logger.debug("Model database not available or compound name missing, skipping cache")
                    
            except Exception as e:
                self.logger.warning(f"Error caching molecular graph: {e}")
                # Continue without caching
            
            # Final validation of output
            try:
                if isinstance(graph_data, dict) and 'num_nodes' in graph_data and graph_data['num_nodes'] > 0:
                    # Add processing metadata
                    graph_data['processing_metadata'] = {
                        'parsing_method': parsing_method,
                        'original_compound': compound_name,
                        'num_atoms': mol.GetNumAtoms(),
                        'processing_timestamp': datetime.now().isoformat(),
                        'validation_passed': True
                    }
                    return graph_data
                else:
                    self.logger.error("Final validation failed: invalid graph data structure")
                    return self._create_fallback_graph(compound_data)
                    
            except Exception as e:
                self.logger.error(f"Final validation error: {e}")
                return self._create_fallback_graph(compound_data)
            
        except Exception as e:
            self.logger.error(f"Error creating molecular graph: {e}")
            return self._create_fallback_graph(compound_data)
    
    def _fetch_molecule_from_pubchem(self, cid: str = None, compound_name: str = None):
        """Fetch molecular structure from PubChem API"""
        try:
            base_url = "https://pubchem.ncbi.nlm.nih.gov/rest/pug"
            
            if cid:
                sdf_url = f"{base_url}/compound/cid/{cid}/SDF"
            elif compound_name:
                sdf_url = f"{base_url}/compound/name/{compound_name}/SDF"
            else:
                return None
            
            response = requests.get(sdf_url, timeout=10)
            if response.status_code == 200:
                mol = Chem.MolFromMolBlock(response.text)
                if mol is not None:
                    # Also fetch SMILES for validation
                    smiles_url = sdf_url.replace('SDF', 'property/CanonicalSMILES/TXT')
                    smiles_response = requests.get(smiles_url, timeout=10)
                    if smiles_response.status_code == 200:
                        smiles = smiles_response.text.strip()
                        self.logger.info(f"Retrieved molecule from PubChem - SMILES: {smiles}")
                    return mol
                    
        except Exception as e:
            self.logger.warning(f"PubChem lookup failed: {e}")
        
        return None
    
    def _fetch_molecule_from_external_dbs(self, compound_name: str):
        """Fetch molecule from ChEMBL and ChemSpider APIs"""
        try:
            # Try ChEMBL first
            chembl_url = f"https://www.ebi.ac.uk/chembl/api/data/molecule?molecule_synonyms__molecule_synonym__iexact={compound_name}&format=json"
            response = requests.get(chembl_url, timeout=10)
            
            if response.status_code == 200:
                data = response.json()
                if data.get('molecules') and len(data['molecules']) > 0:
                    smiles = data['molecules'][0].get('molecule_structures', {}).get('canonical_smiles')
                    if smiles:
                        mol = Chem.MolFromSmiles(smiles)
                        if mol is not None:
                            self.logger.info(f"Retrieved molecule from ChEMBL - SMILES: {smiles}")
                            return mol
            
            # Try ChemSpider if ChEMBL fails (requires API key in production)
            # For now, use simple name-based lookup
            
        except Exception as e:
            self.logger.warning(f"External database lookup failed: {e}")
        
        return None
    
    def _generate_molecule_from_formula(self, formula: str):
        """Generate basic molecular structure from chemical formula (simplified)"""
        try:
            # This is a simplified approach - in production would use more sophisticated methods
            # For common geological minerals, we can create basic structures
            
            if formula == 'SiO2':
                # Create simple silica structure
                mol = Chem.MolFromSmiles('O=[Si]=O')
            elif formula == 'CaCO3':
                # Create simple carbonate structure  
                mol = Chem.MolFromSmiles('[Ca+2].[O-]C(=O)[O-]')
            elif formula == 'H2O':
                mol = Chem.MolFromSmiles('O')
            elif formula == 'CH4':
                mol = Chem.MolFromSmiles('C')
            else:
                # Cannot generate - return None
                return None
                
            if mol is not None:
                self.logger.info(f"Generated basic structure for formula: {formula}")
                
            return mol
            
        except Exception as e:
            self.logger.warning(f"Formula-based generation failed: {e}")
            return None
    
    def _build_molecular_graph_tensor(self, mol, compound_data: Dict):
        """Build comprehensive molecular graph representation as PyTorch tensors"""
        try:
            import torch
            from rdkit.Chem import rdMolDescriptors
            
            num_atoms = mol.GetNumAtoms()
            if num_atoms == 0:
                return self._create_fallback_graph(compound_data)
            
            # 1. Node features (atomic properties)
            node_features = []
            for atom in mol.GetAtoms():
                features = [
                    atom.GetAtomicNum(),  # Atomic number
                    atom.GetDegree(),     # Number of bonds
                    atom.GetFormalCharge(), # Formal charge
                    atom.GetHybridization().real if hasattr(atom.GetHybridization(), 'real') else int(atom.GetHybridization()),
                    atom.GetImplicitValence(),
                    atom.GetNumExplicitHs(),
                    atom.GetNumImplicitHs(),
                    atom.GetNumRadicalElectrons(),
                    atom.GetIsAromatic(),
                    atom.GetMass(),
                    # Van der Waals radius
                    Chem.GetPeriodicTable().GetRvdw(atom.GetAtomicNum()),
                    # Electronegativity (Pauling scale)
                    self._get_electronegativity(atom.GetAtomicNum()),
                    # Ionization potential
                    self._get_ionization_potential(atom.GetAtomicNum()),
                    # Electron affinity
                    self._get_electron_affinity(atom.GetAtomicNum()),
                ]
                node_features.append(features)
            
            node_features = torch.tensor(node_features, dtype=torch.float32)
            
            # 2. Edge features (bond properties)
            edge_indices = []
            edge_features = []
            
            for bond in mol.GetBonds():
                i = bond.GetBeginAtomIdx()
                j = bond.GetEndAtomIdx()
                
                # Add both directions for undirected graph
                edge_indices.extend([(i, j), (j, i)])
                
                bond_features = [
                    bond.GetBondTypeAsDouble(),  # Bond order
                    bond.GetIsConjugated(),      # Conjugation
                    bond.GetIsAromatic(),        # Aromaticity
                    bond.IsInRing(),             # Ring membership
                    bond.GetStereo() if hasattr(bond, 'GetStereo') else 0,  # Stereochemistry
                ]
                
                # Add same features for both directions
                edge_features.extend([bond_features, bond_features])
            
            edge_index = torch.tensor(edge_indices, dtype=torch.long).t()
            edge_attr = torch.tensor(edge_features, dtype=torch.float32)
            
            # 3. Global molecular descriptors
            global_features = [
                Descriptors.MolWt(mol),           # Molecular weight
                Descriptors.MolLogP(mol),         # LogP (lipophilicity)
                Descriptors.NumHDonors(mol),      # H-bond donors
                Descriptors.NumHAcceptors(mol),   # H-bond acceptors
                Descriptors.TPSA(mol),            # Topological polar surface area
                Descriptors.NumRotatableBonds(mol), # Rotatable bonds
                Descriptors.NumAromaticRings(mol),  # Aromatic rings
                Descriptors.NumSaturatedRings(mol), # Saturated rings
                Descriptors.FractionCsp3(mol),      # Fraction of sp3 carbons
                rdMolDescriptors.BertzCT(mol),      # Bertz complexity index
                len(Chem.GetSymmSSSR(mol)),        # Number of rings
            ]
            
            global_features = torch.tensor(global_features, dtype=torch.float32)
            
            # 4. Create adjacency matrix for traditional GNN approaches
            adj_matrix = torch.tensor(GetAdjacencyMatrix(mol), dtype=torch.float32)
            
            # 5. Add 3D coordinates if available
            coords_3d = None
            if mol.GetNumConformers() > 0:
                conf = mol.GetConformer()
                coords = []
                for i in range(num_atoms):
                    pos = conf.GetAtomPosition(i)
                    coords.append([pos.x, pos.y, pos.z])
                coords_3d = torch.tensor(coords, dtype=torch.float32)
            
            graph_data = {
                'x': node_features,              # Node features
                'edge_index': edge_index,        # Edge connectivity
                'edge_attr': edge_attr,          # Edge features  
                'global_features': global_features, # Molecular descriptors
                'adj_matrix': adj_matrix,        # Adjacency matrix
                'num_nodes': num_atoms,          # Graph size
                'coords_3d': coords_3d,          # 3D coordinates (if available)
                'mol_object': mol,               # Original RDKit molecule
            }
            
            return graph_data
            
        except Exception as e:
            self.logger.error(f"Error building molecular graph tensor: {e}")
            return self._create_fallback_graph(compound_data)
    
    def _enrich_with_chemical_databases(self, graph_data: Dict, compound_data: Dict, mol):
        """Enrich graph with additional data from chemical databases"""
        try:
            # Add thermodynamic properties from compound_data
            if compound_data:
                thermo_features = [
                    compound_data.get('enthalpy_of_formation', 0.0),
                    compound_data.get('entropy_298', 0.0), 
                    compound_data.get('gibbs_energy_of_formation', 0.0),
                    compound_data.get('heat_capacity_298', 0.0),
                    compound_data.get('melting_point', 0.0),
                    compound_data.get('boiling_point', 0.0),
                    compound_data.get('density', 0.0),
                    compound_data.get('vapor_pressure', 0.0),
                ]
                
                graph_data['thermo_features'] = torch.tensor(thermo_features, dtype=torch.float32)
            
            # Add geological context if available
            geological_context = [
                compound_data.get('geological_occurrence_frequency', 0.0),
                compound_data.get('stability_temperature_range', [0, 1000])[1],  # Max stability temp
                compound_data.get('pressure_stability_range', [0, 100])[1],     # Max pressure
                compound_data.get('weathering_resistance', 0.5),
                compound_data.get('crystalline_system_encoded', 0.0),
            ]
            
            graph_data['geological_context'] = torch.tensor(geological_context, dtype=torch.float32)
            
            # Add external database references
            graph_data['metadata'] = {
                'pubchem_cid': compound_data.get('CID'),
                'smiles': compound_data.get('CanonicalSMILES'),
                'inchi': compound_data.get('InChI'),
                'data_sources': list(compound_data.keys()),
                'creation_timestamp': datetime.now().isoformat(),
            }
            
        except Exception as e:
            self.logger.warning(f"Error enriching graph with database info: {e}")
        
        return graph_data
    
    def _cache_molecular_graph(self, compound_name: str, graph_data: Dict, mol):
        """Cache molecular graph in model database for future use"""
        try:
            if hasattr(self, 'model_database') and self.model_database:
                # Store serialized graph data
                cache_data = {
                    'graph_tensors': {k: v.tolist() if hasattr(v, 'tolist') else v 
                                    for k, v in graph_data.items() 
                                    if k not in ['mol_object']},
                    'smiles': Chem.MolToSmiles(mol),
                    'molecular_formula': Chem.rdMolDescriptors.CalcMolFormula(mol),
                    'cached_at': datetime.now().isoformat(),
                }
                
                # Use model database caching system
                cache_key = f"molecular_graph_{compound_name}"
                self.model_database.cache_prediction(cache_key, cache_data)
                
        except Exception as e:
            self.logger.warning(f"Failed to cache molecular graph: {e}")
    
    def _get_electronegativity(self, atomic_num: int) -> float:
        """Get Pauling electronegativity for atomic number"""
        electronegativity_table = {
            1: 2.20, 2: 0.00, 3: 0.98, 4: 1.57, 5: 2.04, 6: 2.55, 7: 3.04, 8: 3.44, 9: 3.98, 10: 0.00,
            11: 0.93, 12: 1.31, 13: 1.61, 14: 1.90, 15: 2.19, 16: 2.58, 17: 3.16, 18: 0.00,
            19: 0.82, 20: 1.00, # Add more as needed
        }
        return electronegativity_table.get(atomic_num, 2.0)  # Default to carbon-like
    
    def _get_ionization_potential(self, atomic_num: int) -> float:
        """Get first ionization potential (eV)"""
        ip_table = {
            1: 13.6, 2: 24.6, 3: 5.4, 4: 9.3, 5: 8.3, 6: 11.3, 7: 14.5, 8: 13.6, 9: 17.4, 10: 21.6,
            11: 5.1, 12: 7.6, 13: 6.0, 14: 8.2, 15: 10.5, 16: 10.4, 17: 13.0, 18: 15.8,
            19: 4.3, 20: 6.1, # Add more as needed
        }
        return ip_table.get(atomic_num, 10.0)  # Default value
    
    def _get_electron_affinity(self, atomic_num: int) -> float:
        """Get electron affinity (eV)"""
        ea_table = {
            1: 0.75, 2: 0.0, 3: 0.62, 4: 0.0, 5: 0.28, 6: 1.26, 7: -0.07, 8: 1.46, 9: 3.40, 10: 0.0,
            11: 0.55, 12: 0.0, 13: 0.43, 14: 1.39, 15: 0.75, 16: 2.08, 17: 3.61, 18: 0.0,
            19: 0.50, 20: 0.02, # Add more as needed
        }
        return ea_table.get(atomic_num, 0.0)  # Default value
    
    def _create_fallback_graph(self, compound_data: Dict):
        """Create fallback graph structure when molecular parsing fails"""
        try:
            import torch
            
            # Create minimal graph with formula-based features
            formula = compound_data.get('formula', 'C')
            
            # Parse formula to get atom counts
            atom_counts = self._parse_chemical_formula(formula)
            total_atoms = sum(atom_counts.values())
            
            if total_atoms == 0:
                total_atoms = 1
                atom_counts = {'C': 1}  # Default to carbon
            
            # Create simple node features based on formula
            node_features = []
            for element, count in atom_counts.items():
                atomic_num = self._get_atomic_number(element)
                for _ in range(count):
                    features = [
                        atomic_num, 1, 0, 3, 0, 0, 0, 0, 0,  # Basic atomic features
                        self._get_atomic_mass(element),
                        2.0, 2.0, 10.0, 0.0  # Default values for other properties
                    ]
                    node_features.append(features)
            
            # Create simple fully connected graph for small molecules
            edge_indices = []
            for i in range(total_atoms):
                for j in range(i+1, total_atoms):
                    edge_indices.extend([(i, j), (j, i)])
            
            edge_features = [[1.0, 0, 0, 0, 0]] * len(edge_indices)  # Simple bonds
            
            fallback_graph = {
                'x': torch.tensor(node_features, dtype=torch.float32),
                'edge_index': torch.tensor(edge_indices, dtype=torch.long).t() if edge_indices else torch.zeros((2, 0), dtype=torch.long),
                'edge_attr': torch.tensor(edge_features, dtype=torch.float32) if edge_features else torch.zeros((0, 5), dtype=torch.float32),
                'global_features': torch.zeros(11, dtype=torch.float32),  # Placeholder global features
                'num_nodes': total_atoms,
                'is_fallback': True,
                'original_formula': formula,
            }
            
            return fallback_graph
            
        except Exception as e:
            self.logger.error(f"Failed to create fallback graph: {e}")
            return None
    
    def _fallback_molecular_graph(self, compound_data: Dict):
        """Ultimate fallback when chemistry libraries are unavailable"""
        try:
            # Create very basic representation using only standard libraries
            formula = compound_data.get('formula', 'Unknown')
            
            # Create a simple dictionary-based graph representation
            fallback_data = {
                'type': 'fallback_graph',
                'formula': formula,
                'compound_data': compound_data,
                'node_count': len(formula.replace(formula.translate(str.maketrans('', '', '0123456789')), '')),
                'features': [
                    compound_data.get('molecular_weight', 0.0),
                    compound_data.get('density', 0.0),
                    compound_data.get('melting_point', 0.0),
                    len(formula),  # Simple complexity measure
                ],
                'creation_method': 'fallback_no_chemistry_libs',
            }
            
            return fallback_data
            
        except Exception as e:
            self.logger.error(f"Ultimate fallback failed: {e}")
            return {'type': 'empty_graph', 'error': str(e)}
    
