    def _determine_geological_context(self, relationship_id: str) -> str:
        """Determine geological context for uncertainty adjustment."""
        # Simplified geological context determination
        contexts = ['igneous', 'sedimentary', 'metamorphic', 'structural', 'hydrogeological']
        return np.random.choice(contexts)
    
    def _get_process_specific_uncertainty(self, geological_context: str) -> float:
        """Get process-specific uncertainty based on geological context."""
        uncertainty_map = {
            'igneous': 0.08,      # 8% for igneous processes
            'sedimentary': 0.06,  # 6% for sedimentary processes
            'metamorphic': 0.10,  # 10% for metamorphic processes
            'structural': 0.12,   # 12% for structural processes
            'hydrogeological': 0.07  # 7% for hydrogeological processes
        }
        return uncertainty_map.get(geological_context, 0.08)
    
    def _get_scale_dependent_adjustment(self, geological_context: str) -> float:
        """Get scale-dependent uncertainty adjustment."""
        # Scale effects typically add 3-7% uncertainty
        return np.random.uniform(0.03, 0.07)
    
    def _get_temporal_uncertainty_adjustment(self, geological_context: str) -> float:
        """Get temporal uncertainty adjustment."""
        # Temporal processes add 2-5% uncertainty
        return np.random.uniform(0.02, 0.05)
    
    def _get_measurement_uncertainty_adjustment(self, geological_context: str) -> float:
        """Get measurement uncertainty adjustment."""
        # Measurement uncertainties typically 1-4%
        return np.random.uniform(0.01, 0.04)

