    async def _track_api_usage(self, api_name: str, endpoint: str, response_time: float, 
                             status_code: int, success: bool, error_message: str = None):
        """Track API usage for monitoring and rate limiting"""
        try:
            from .database_integration import DatabaseConfig
            import asyncpg
            
            config = DatabaseConfig()
            conn = await asyncpg.connect(config.get_async_connection_string())
            
            try:
                insert_query = """
                INSERT INTO api_usage_tracking 
                (api_name, endpoint, response_time_ms, status_code, success, error_message)
                VALUES ($1, $2, $3, $4, $5, $6);
                """
                
                await conn.execute(
                    insert_query, 
                    api_name, 
                    endpoint, 
                    int(response_time * 1000),  # Convert to milliseconds
                    status_code,
                    success,
                    error_message
                )
                
            finally:
                await conn.close()
                
        except Exception as e:
            self.logger.warning(f"Failed to track API usage: {e}")
    
    async def _check_api_rate_limits(self, api_name: str) -> bool:
        """Check if API rate limits allow for new requests"""
        try:
            from .database_integration import DatabaseConfig
            import asyncpg
            from datetime import datetime, timedelta
            
            config = DatabaseConfig()
            conn = await asyncpg.connect(config.get_async_connection_string())
            
            try:
                # Check usage in last hour for rate limiting
                hour_ago = datetime.utcnow() - timedelta(hours=1)
                
                count_query = """
                SELECT COUNT(*) as request_count
                FROM api_usage_tracking
                WHERE api_name = $1 AND request_timestamp > $2;
                """
                
                result = await conn.fetchrow(count_query, api_name, hour_ago)
                
                if result:
                    hourly_count = result['request_count']
                    
                    # Define rate limits per API
                    rate_limits = {
                        'ERA5': 100,  # Conservative limit
                        'NOAA_GHCN': 1000,  # NOAA is generally more permissive
                        'WorldBank': 500,
                        'Copernicus': 50,
                        'NASA_GLDAS': 200,
                        'Nominatim': 60,  # 1 per second
                        'GeoNames': 1000  # With username
                    }
                    
                    limit = rate_limits.get(api_name, 100)  # Default conservative limit
                    
                    return hourly_count < limit
                    
                return True  # No usage found, allow request
                
            finally:
                await conn.close()
                
        except Exception as e:
            self.logger.warning(f"Failed to check rate limits for {api_name}: {e}")
            return True  # Allow on error to not block functionality
    
    async def _get_cached_climate_data(self, lat: float, lon: float, parameter: str) -> Optional[Tuple[float, float, str]]:
        """Retrieve cached climate data if available and not expired"""
        try:
            from .database_integration import DatabaseConfig
            import asyncpg
            
            config = DatabaseConfig()
            conn = await asyncpg.connect(config.get_async_connection_string())
            
            try:
                # Look for cached data within 10km radius and not expired
                cache_query = """
                SELECT value, quality_score, source, uncertainty,
                       ST_Distance(ST_GeogFromText('POINT(%s %s)'), location) as distance_m
                FROM climate_data_cache
                WHERE parameter = %s 
                AND expires_at > NOW()
                AND ST_DWithin(ST_GeogFromText('POINT(%s %s)'), location, 10000)
                ORDER BY distance_m ASC, quality_score DESC
                LIMIT 1;
                """
                
                result = await conn.fetchrow(cache_query, lon, lat, parameter, lon, lat)
                
                if result:
                    return (
                        float(result['value']),
                        float(result['quality_score']) if result['quality_score'] else 0.7,
                        result['source']
                    )
                    
            finally:
                await conn.close()
                
        except Exception as e:
            self.logger.warning(f"Failed to retrieve cached climate data: {e}")
            
        return None
    
