    async def _update_climate_metrics(self, api_name: str, success: bool, response_time: float):
        """Update climate data operation metrics"""
        try:
            self.climate_metrics['api_calls_total'] += 1
            
            if success:
                # Update success rate
                if api_name not in self.api_success_rates:
                    self.api_success_rates[api_name] = {'success': 0, 'total': 0}
                    
                self.api_success_rates[api_name]['success'] += 1
            else:
                self.climate_metrics['failed_requests'] += 1
                
            if api_name not in self.api_success_rates:
                self.api_success_rates[api_name] = {'success': 0, 'total': 0}
                
            self.api_success_rates[api_name]['total'] += 1
            
            # Update average response time
            current_avg = self.climate_metrics['average_response_time']
            total_calls = self.climate_metrics['api_calls_total']
            
            new_avg = ((current_avg * (total_calls - 1)) + response_time) / total_calls
            self.climate_metrics['average_response_time'] = new_avg
            
            self.climate_metrics['last_updated'] = datetime.utcnow().isoformat()
            
        except Exception as e:
            self.logger.warning(f"Failed to update climate metrics: {e}")
    
    def get_climate_system_status(self) -> Dict[str, Any]:
        """Get status and performance metrics of the advanced climate data system"""
        try:
            # Calculate success rates
            success_rates = {}
            for api_name, stats in self.api_success_rates.items():
                if stats['total'] > 0:
                    success_rates[api_name] = stats['success'] / stats['total']
                else:
                    success_rates[api_name] = 0.0
            
            status = {
                'system_status': 'operational',
                'metrics': self.climate_metrics.copy(),
                'api_success_rates': success_rates,
                'available_apis': list(self.api_keys.keys()),
                'authenticated_apis': [key for key, value in self.api_keys.items() if value],
                'cache_hit_rate': self.climate_metrics['cache_hits'] / 
                                 max(1, self.climate_metrics['cache_hits'] + self.climate_metrics['cache_misses']),
                'last_status_check': datetime.utcnow().isoformat()
            }
            
            return status
            
        except Exception as e:
            return {
                'system_status': 'error',
                'error': str(e),
                'last_status_check': datetime.utcnow().isoformat()
            }
    
