    async def _check_statistical_consistency(self, value_info):
        """Check statistical consistency with historical data"""
        try:
            from .database_integration import DatabaseIntegration
            
            if not hasattr(self, '_db_integration'):
                return 0.6
            
            value = value_info.get('value', 0)
            property_name = self.property_name
            
            # Query historical data
            query = '''
            SELECT property_value, confidence 
            FROM geological_properties 
            WHERE property_name = %s 
            AND property_value BETWEEN %s AND %s
            ORDER BY confidence DESC
            LIMIT 100
            '''
            
            try:
                results = await self._db_integration.execute_query(
                    query, (property_name, value * 0.5, value * 2.0)
                )
                
                if results:
                    values = [r['property_value'] for r in results]
                    mean_val = np.mean(values)
                    std_val = np.std(values)
                    
                    # Z-score based consistency
                    if std_val > 0:
                        z_score = abs(value - mean_val) / std_val
                        consistency = max(0.0, 1.0 - z_score / 3.0)  # 3-sigma rule
                    else:
                        consistency = 1.0 if value == mean_val else 0.5
                    
                    self._last_sample_size = len(values)
                    return consistency
                else:
                    self._last_sample_size = 0
                    return 0.5
                    
            except Exception as e:
                logger.warning(f"Statistical consistency query failed: {e}")
                return 0.5
                
        except Exception as e:
            logger.warning(f"Statistical consistency check failed: {e}")
            return 0.5
    
    def _check_physics_constraints(self, value_info):
        """Check physical constraint consistency"""
        try:
            value = value_info.get('value', 0)
            unit = value_info.get('unit', '')
            property_name = self.property_name.lower()
            
            physics_checks = []
            
            # Define physical constraints for geological properties
            constraints = {
                'density': [
                    ('positive', lambda x: x > 0, 'Density must be positive'),
                    ('realistic_range', lambda x: 1.0 <= x <= 20.0, 'Density outside typical geological range'),
                    ('unit_consistency', lambda x: any(u in unit.lower() for u in ['g/cm³', 'kg/m³']), 'Invalid density unit')
                ],
                'porosity': [
                    ('positive', lambda x: x >= 0, 'Porosity cannot be negative'),
                    ('percentage_limit', lambda x: x <= 100, 'Porosity cannot exceed 100%'),
                    ('realistic_range', lambda x: 0 <= x <= 50, 'Porosity outside typical geological range'),
                    ('unit_consistency', lambda x: any(u in unit.lower() for u in ['%', 'percent']), 'Invalid porosity unit')
                ],
                'permeability': [
                    ('positive', lambda x: x >= 0, 'Permeability cannot be negative'),
                    ('realistic_range', lambda x: 0.001 <= x <= 1000000, 'Permeability outside typical range'),
                    ('unit_consistency', lambda x: any(u in unit.lower() for u in ['md', 'darcy', 'm²']), 'Invalid permeability unit')
                ],
                'temperature': [
                    ('absolute_zero', lambda x: x >= -273.15 if '°c' in unit.lower() or 'celsius' in unit.lower() else x >= 0, 'Temperature below absolute zero'),
                    ('realistic_range', lambda x: -50 <= x <= 1500, 'Temperature outside geological range'),
                    ('unit_consistency', lambda x: any(u in unit.lower() for u in ['°c', '°f', 'k']), 'Invalid temperature unit')
                ],
                'pressure': [
                    ('positive', lambda x: x >= 0, 'Pressure cannot be negative'),
                    ('realistic_range', lambda x: 0.1 <= x <= 10000, 'Pressure outside typical geological range'),
                    ('unit_consistency', lambda x: any(u in unit.lower() for u in ['bar', 'psi', 'pa', 'mpa']), 'Invalid pressure unit')
                ]
            }
            
            property_constraints = constraints.get(property_name, [])
            
            passed_checks = 0
            total_checks = len(property_constraints)
            
            for check_name, check_func, description in property_constraints:
                try:
                    if check_func(value):
                        passed_checks += 1
                        physics_checks.append(f"{check_name}: PASSED")
                    else:
                        physics_checks.append(f"{check_name}: FAILED - {description}")
                except Exception as e:
                    physics_checks.append(f"{check_name}: ERROR - {str(e)}")
            
            self._last_physics_checks = physics_checks
            
            # Calculate physics consistency score
            if total_checks > 0:
                return passed_checks / total_checks
            else:
                return 1.0  # No constraints defined
                
        except Exception as e:
            logger.warning(f"Physics constraints check failed: {e}")
            return 0.5
    
    async def _check_cross_reference_consistency(self, value_info, text):
        """Check consistency through cross-referencing"""
        try:
            cross_refs = []
            
            # Look for multiple mentions of the same property in text
            property_mentions = []
            value = value_info.get('value', 0)
            
            # Find other numerical values in the text that might refer to the same property
            import re
            value_pattern = r'(\d+\.?\d*)\s*([a-zA-Z/%°]*)'
            
            for match in re.finditer(value_pattern, text):
                try:
                    found_value = float(match.group(1))
                    found_unit = match.group(2)
                    
                    # Check if this could be the same property
                    if (abs(found_value - value) / max(value, 1) < 0.3 and  # Within 30%
                        self._validate_unit_for_property(self.property_name, found_unit)):
                        property_mentions.append({
                            'value': found_value,
                            'unit': found_unit,
                            'position': match.start()
                        })
                        cross_refs.append(f"Similar value found: {found_value} {found_unit}")
                        
                except ValueError:
                    continue
            
            self._last_cross_refs = cross_refs
            
            # Calculate consistency based on agreement between mentions
            if len(property_mentions) <= 1:
                return 0.6  # Single mention - moderate confidence
            
            # Calculate coefficient of variation for multiple mentions
            values = [m['value'] for m in property_mentions]
            mean_val = np.mean(values)
            std_val = np.std(values)
            
            if mean_val > 0:
                cv = std_val / mean_val
                consistency = max(0.3, 1.0 - cv)  # Lower bound of 0.3
            else:
                consistency = 0.5
            
            return consistency
            
        except Exception as e:
            logger.warning(f"Cross-reference consistency check failed: {e}")
            return 0.5
    
    def _get_expected_range_for_path(self, path):
        """Get expected value range for causal path"""
        try:
            # Basic expected ranges for geological properties
            expected_ranges = {
                'density': (1.5, 8.0),
                'porosity': (5.0, 40.0),
                'permeability': (0.1, 10000),
                'temperature': (0, 300),
                'pressure': (1, 1000)
            }
            
            target_property = path[-1] if path else self.property_name
            return expected_ranges.get(target_property.lower())
            
        except Exception:
            return None
    
    def _calculate_range_consistency(self, value, expected_range):
        """Calculate how well value fits within expected range"""
        try:
            if not expected_range:
                return 0.5
            
            min_val, max_val = expected_range
            
            if min_val <= value <= max_val:
                # Value is within range - calculate how central it is
                range_size = max_val - min_val
                center = (min_val + max_val) / 2
                distance_from_center = abs(value - center)
                centrality = 1.0 - (distance_from_center / (range_size / 2))
                return max(0.7, centrality)  # Minimum 0.7 for in-range values
            else:
                # Value is outside range - calculate how far
                if value < min_val:
                    distance = min_val - value
                    reference = min_val
                else:
                    distance = value - max_val
                    reference = max_val
                
                relative_distance = distance / reference if reference > 0 else 1
                consistency = max(0.1, 1.0 / (1 + relative_distance))
                return consistency
                
        except Exception:
            return 0.5
    
    def _calculate_dataset_consistency(self, value, dataset):
        """Calculate consistency with external dataset"""
        try:
            if not dataset:
                return 0.5
            
            dataset_values = []
            for record in dataset:
                try:
                    if 'value' in record:
                        dataset_values.append(float(record['value']))
                    elif 'property_value' in record:
                        dataset_values.append(float(record['property_value']))
                except (ValueError, TypeError):
                    continue
            
            if not dataset_values:
                return 0.5
            
            # Calculate percentile position of our value
            dataset_values.sort()
            n = len(dataset_values)
            
            # Find position of our value in sorted dataset
            position = 0
            for i, dataset_val in enumerate(dataset_values):
                if value <= dataset_val:
                    position = i
                    break
            else:
                position = n
            
            percentile = position / n if n > 0 else 0.5
            
            # Consistency is higher for values near the median
            consistency = 1.0 - abs(percentile - 0.5) * 2
            return max(0.2, consistency)
            
        except Exception as e:
            logger.warning(f"Dataset consistency calculation failed: {e}")
            return 0.5
    
    def _detect_value_anomaly(self, value_info):
        """Detect if value is anomalous using isolation forest"""
        try:
            from sklearn.ensemble import IsolationForest
            
            if not hasattr(self, '_anomaly_detector') or not hasattr(self, '_training_values'):
                return 0.0  # No anomaly detection if not initialized
            
            value = value_info.get('value', 0)
            
            # Prepare features for anomaly detection
            features = np.array([[value, value_info.get('confidence', 0.5)]])
            
            # Predict anomaly
            anomaly_score = self._anomaly_detector.decision_function(features)[0]
            
            # Convert to 0-1 scale where 1 is highly anomalous
            normalized_score = max(0, min(1, (0.5 - anomaly_score) / 0.5))
            
            return normalized_score
            
        except Exception as e:
            logger.warning(f"Anomaly detection failed: {e}")
            return 0.0
    
    def _calculate_confidence_adjustment(self, consistency_scores):
        """Calculate confidence adjustment based on consistency"""
        try:
            total_score = sum(score * weight for _, score, weight in consistency_scores)
            
            if total_score > 0.8:
                return 1.1  # Boost confidence for highly consistent values
            elif total_score > 0.6:
                return 1.0  # No adjustment
            elif total_score > 0.4:
                return 0.9  # Slight penalty
            else:
                return 0.7  # Significant penalty for inconsistent values
                
        except Exception:
            return 1.0
    
    def _generate_consistency_recommendations(self, consistency_scores):
        """Generate recommendations based on consistency analysis"""
        try:
            recommendations = []
            
            for name, score, weight in consistency_scores:
                if score < 0.5:
                    if name == 'graph':
                        recommendations.append("Consider verifying causal relationships in knowledge graph")
                    elif name == 'knowledge':
                        recommendations.append("Cross-check with additional geological databases")
                    elif name == 'statistical':
                        recommendations.append("Value may be outside normal statistical range")
                    elif name == 'physics':
                        recommendations.append("Check physical constraints and units")
                    elif name == 'cross_reference':
                        recommendations.append("Look for additional supporting evidence in text")
            
            if not recommendations:
                recommendations.append("Value appears consistent across all validation methods")
            
            return recommendations
            
        except Exception:
            return ["Consistency analysis completed"]
    
    async def _store_consistency_metadata(self, value_info, consistency_report):
        """Store consistency metadata for learning"""
        try:
            metadata = {
                'timestamp': datetime.utcnow().isoformat(),
                'property': self.property_name,
                'value': value_info.get('value'),
                'consistency_score': consistency_report['overall_consistency'],
                'component_scores': consistency_report['component_scores'],
                'anomaly_score': consistency_report['anomaly_score']
            }
            
            # Store in consistency history
            if not hasattr(self, '_consistency_history'):
                self._consistency_history = []
            
            self._consistency_history.append(metadata)
            
            # Keep only recent history
            if len(self._consistency_history) > 500:
                self._consistency_history = self._consistency_history[-500:]
                
        except Exception as e:
            logger.warning(f"Consistency metadata storage failed: {e}")
    
