    async def _fallback_geological_entities(self, text):
        """Fallback geological entity extraction"""
        try:
            geological_entities = []
            
            # Use basic geological material matching as fallback
            geological_materials = [
                'granite', 'basalt', 'limestone', 'sandstone', 'shale', 'marble',
                'quartzite', 'gneiss', 'schist', 'rhyolite', 'andesite', 'diorite',
                'conglomerate', 'breccia', 'slate', 'phyllite', 'amphibolite'
            ]
            
            text_lower = text.lower()
            for material in geological_materials:
                if material in text_lower:
                    start_pos = text_lower.find(material)
                    geological_entities.append({
                        'text': material,
                        'label': 'geological_material',
                        'start': start_pos,
                        'end': start_pos + len(material),
                        'confidence': 0.9,
                        'source': 'fallback_extraction'
                    })
            
            return geological_entities
            
        except Exception as e:
            logger.error(f"Fallback geological entity extraction failed: {e}")
            return []
    
