    async def _semantic_causal_extraction(self, text, entities, cause):
        """Transformer-based semantic causal extraction"""
        try:
            import torch
            from sklearn.metrics.pairwise import cosine_similarity
            
            semantic_values = []
            
            # Generate embeddings for text and cause
            inputs = self._geological_tokenizer(text, return_tensors="pt", truncation=True, max_length=512)
            
            with torch.no_grad():
                outputs = self._geological_model(**inputs)
                text_embeddings = outputs.last_hidden_state
            
            # Generate cause-specific query embedding
            cause_query = f"What is the {cause} value in this geological context?"
            cause_inputs = self._geological_tokenizer(cause_query, return_tensors="pt")
            
            with torch.no_grad():
                cause_outputs = self._geological_model(**cause_inputs)
                cause_embedding = cause_outputs.last_hidden_state.mean(dim=1)
            
            # Find semantically relevant spans
            window_size = 8
            tokens = self._geological_tokenizer.convert_ids_to_tokens(inputs['input_ids'][0])
            
            for i in range(len(tokens) - window_size):
                span_embedding = text_embeddings[0, i:i+window_size].mean(dim=0, keepdim=True)
                similarity = torch.cosine_similarity(cause_embedding, span_embedding)
                
                if similarity.item() > 0.7:  # High semantic similarity
                    span_text = self._geological_tokenizer.decode(inputs['input_ids'][0, i:i+window_size])
                    
                    # Extract numerical values from semantically relevant spans
                    import re
                    value_matches = re.findall(r'(\\d+\\.?\\d*)\\s*([a-zA-Z/%°]*)', span_text)
                    
                    for value_str, unit in value_matches:
                        try:
                            semantic_values.append({
                                'value': float(value_str),
                                'unit': unit,
                                'confidence': similarity.item() * 0.9,
                                'source': 'semantic_transformer',
                                'method': 'bert_semantic_similarity',
                                'span_context': span_text.strip(),
                                'semantic_similarity': similarity.item()
                            })
                        except ValueError:
                            continue
            
            return semantic_values
            
        except Exception as e:
            logger.warning(f"Semantic causal extraction failed: {e}")
            return []
    
    async def _knowledge_graph_causal_extraction(self, text, entities, cause):
        """Knowledge graph-enhanced causal discovery"""
        try:
            kg_values = []
            
            if not hasattr(self, '_knowledge_graph'):
                return []
            
            # Query knowledge graph for causal pathways
            causal_pathways = await self._knowledge_graph.find_causal_pathways(
                source_entities=[e.get('text', '') for e in entities],
                target_property=cause
            )
            
            for pathway in causal_pathways:
                # Extract values along each causal pathway
                pathway_values = await self._extract_pathway_values(text, pathway, cause)
                
                for value_info in pathway_values:
                    value_info.update({
                        'source': 'knowledge_graph_pathway',
                        'causal_pathway': pathway['path'],
                        'pathway_confidence': pathway.get('confidence', 0.5),
                        'reasoning_chain': pathway.get('reasoning', [])
                    })
                    kg_values.append(value_info)
            
            return kg_values
            
        except Exception as e:
            logger.warning(f"Knowledge graph causal extraction failed: {e}")
            return []
    
    async def _physics_informed_causal_extraction(self, text, entities, cause):
        """Multi-physics informed causal modeling"""
        try:
            physics_values = []
            
            # Define physics-based causal relationships
            physics_models = {
                'density': {
                    'porosity': lambda p: 2.65 * (1 - p/100),  # Bulk density from porosity
                    'depth': lambda d: 1.0 + 0.0001 * d,  # Density increase with depth
                    'pressure': lambda pr: 1.0 + pr * 0.0001  # Density from pressure
                },
                'porosity': {
                    'density': lambda d: (2.65 - d) / 2.65 * 100,  # Porosity from density
                    'permeability': lambda k: 15 * (k / 1000) ** 0.5,  # Porosity-permeability relation
                    'grain_size': lambda gs: 20 + gs * 5  # Porosity from grain size
                },
                'permeability': {
                    'porosity': lambda p: 1000 * (p/15) ** 2,  # Kozeny-Carman relation
                    'grain_size': lambda gs: gs ** 2 * 0.1,  # Grain size control
                    'fracture_density': lambda fd: fd * 100  # Fracture permeability
                }
            }
            
            # Extract cause values for physics calculations
            for entity in entities:
                entity_text = entity.get('text', '').lower()
                entity_value = self._extract_numerical_value_from_entity(entity, text)
                
                if entity_value and cause.lower() in physics_models:
                    property_models = physics_models[cause.lower()]
                    
                    # Check if entity matches any physics model input
                    for model_input, model_func in property_models.items():
                        if model_input in entity_text:
                            try:
                                predicted_value = model_func(entity_value['value'])
                                physics_values.append({
                                    'value': predicted_value,
                                    'unit': self._get_standard_unit_for_property(cause),
                                    'confidence': 0.8 * entity_value.get('confidence', 0.7),
                                    'source': 'physics_informed_model',
                                    'physics_model': f"{model_input}_to_{cause}",
                                    'input_value': entity_value['value'],
                                    'input_property': model_input
                                })
                            except Exception as e:
                                logger.warning(f"Physics model calculation failed: {e}")
            
            return physics_values
            
        except Exception as e:
            logger.warning(f"Physics-informed causal extraction failed: {e}")
            return []
    
    async def _database_cross_validate_causes(self, extracted_values, cause):
        """Real-time database cross-validation"""
        try:
            validated_values = []
            
            for value_info in extracted_values:
                value = value_info.get('value', 0)
                unit = value_info.get('unit', '')
                
                # Query geological properties database
                validation_query = '''
                SELECT property_value, unit, confidence, source_reference, 
                       geological_context, measurement_method
                FROM geological_properties 
                WHERE property_name = %s 
                AND property_value BETWEEN %s AND %s
                ORDER BY confidence DESC
                LIMIT 10
                '''
                
                try:
                    results = await self._db_integration.execute_query(
                        validation_query, 
                        (cause, value * 0.8, value * 1.2)  # 20% tolerance
                    )
                    
                    if results:
                        # Calculate database validation score
                        db_values = [r['property_value'] for r in results]
                        mean_db_value = np.mean(db_values)
                        std_db_value = np.std(db_values)
                        
                        if std_db_value > 0:
                            z_score = abs(value - mean_db_value) / std_db_value
                            db_validation_score = max(0.1, 1.0 - z_score / 3.0)
                        else:
                            db_validation_score = 1.0 if value == mean_db_value else 0.5
                        
                        # Update confidence based on database validation
                        original_confidence = value_info.get('confidence', 0.5)
                        validated_confidence = original_confidence * db_validation_score
                        
                        value_info.update({
                            'confidence': validated_confidence,
                            'database_validation_score': db_validation_score,
                            'database_matches': len(results),
                            'database_mean': mean_db_value,
                            'database_std': std_db_value,
                            'validation_references': [r['source_reference'] for r in results[:3]]
                        })
                        
                        if validated_confidence > 0.3:  # Minimum validation threshold
                            validated_values.append(value_info)
                    else:
                        # No database matches - apply penalty but keep if originally high confidence
                        if value_info.get('confidence', 0) > 0.7:
                            value_info['confidence'] *= 0.6
                            value_info['database_validation_score'] = 0.5
                            value_info['database_matches'] = 0
                            validated_values.append(value_info)
                        
                except Exception as e:
                    logger.warning(f"Database validation query failed: {e}")
                    validated_values.append(value_info)  # Keep original if query fails
            
            return validated_values
            
        except Exception as e:
            logger.warning(f"Database cross-validation failed: {e}")
            return extracted_values
    
    async def _ensemble_causal_prediction(self, extracted_values, text, cause):
        """Ensemble learning for causal factor prediction"""
        try:
            from sklearn.ensemble import RandomForestRegressor, GradientBoostingRegressor
            from sklearn.neural_network import MLPRegressor
            from sklearn.preprocessing import StandardScaler
            
            if len(extracted_values) < 3:
                return extracted_values
            
            # Prepare features for ensemble learning
            features = []
            targets = []
            
            for value_info in extracted_values:
                feature_vector = [
                    value_info.get('confidence', 0.5),
                    value_info.get('semantic_similarity', 0.5),
                    value_info.get('database_validation_score', 0.5),
                    len(value_info.get('unit', '')),
                    value_info.get('value', 0) / max(1, np.mean([v.get('value', 1) for v in extracted_values]))
                ]
                features.append(feature_vector)
                targets.append(value_info.get('value', 0))
            
            features = np.array(features)
            targets = np.array(targets)
            
            # Train ensemble models
            scaler = StandardScaler()
            features_scaled = scaler.fit_transform(features)
            
            models = {
                'random_forest': RandomForestRegressor(n_estimators=50, random_state=42),
                'gradient_boost': GradientBoostingRegressor(n_estimators=50, random_state=42),
                'neural_network': MLPRegressor(hidden_layer_sizes=(64, 32), random_state=42, max_iter=500)
            }
            
            ensemble_predictions = {}
            for name, model in models.items():
                try:
                    model.fit(features_scaled, targets)
                    predictions = model.predict(features_scaled)
                    ensemble_predictions[name] = predictions
                except Exception as e:
                    logger.warning(f"Ensemble model {name} failed: {e}")
            
            # Generate ensemble-enhanced values
            ensemble_values = []
            for i, value_info in enumerate(extracted_values):
                # Calculate ensemble prediction average
                predictions = [preds[i] for preds in ensemble_predictions.values() if len(preds) > i]
                if predictions:
                    ensemble_pred = np.mean(predictions)
                    pred_std = np.std(predictions) if len(predictions) > 1 else 0.1
                    
                    # Blend original value with ensemble prediction
                    original_value = value_info.get('value', 0)
                    original_confidence = value_info.get('confidence', 0.5)
                    
                    ensemble_weight = min(0.7, original_confidence)
                    blended_value = (original_value * ensemble_weight + 
                                   ensemble_pred * (1 - ensemble_weight))
                    
                    value_info.update({
                        'value': blended_value,
                        'ensemble_prediction': ensemble_pred,
                        'ensemble_uncertainty': pred_std,
                        'ensemble_weight': ensemble_weight,
                        'original_value': original_value,
                        'source': f"{value_info.get('source', 'unknown')}_ensemble_enhanced"
                    })
                
                ensemble_values.append(value_info)
            
            return ensemble_values
            
        except Exception as e:
            logger.warning(f"Ensemble causal prediction failed: {e}")
            return extracted_values
    
    def _calibrate_extraction_uncertainty(self, extracted_values, text, cause):
        """Advanced uncertainty quantification and calibration"""
        try:
            import numpy as np
            from scipy import stats
            
            calibrated_values = []
            
            if len(extracted_values) < 2:
                return extracted_values
            
            # Calculate statistical measures across all extracted values
            values = [v.get('value', 0) for v in extracted_values]
            confidences = [v.get('confidence', 0.5) for v in extracted_values]
            
            value_mean = np.mean(values)
            value_std = np.std(values) if len(values) > 1 else 0.1
            confidence_mean = np.mean(confidences)
            
            for value_info in extracted_values:
                value = value_info.get('value', 0)
                confidence = value_info.get('confidence', 0.5)
                
                # Z-score based uncertainty
                z_score = abs(value - value_mean) / max(value_std, 0.01)
                z_score_penalty = max(0.5, 1.0 - z_score / 3.0)
                
                # Confidence relative to group
                relative_confidence = confidence / max(confidence_mean, 0.1)
                
                # Ensemble agreement uncertainty
                ensemble_uncertainty = value_info.get('ensemble_uncertainty', 0.1)
                ensemble_penalty = max(0.7, 1.0 - ensemble_uncertainty / max(value, 0.01))
                
                # Combined uncertainty calibration
                calibrated_confidence = confidence * z_score_penalty * ensemble_penalty
                
                # Epistemic vs aleatoric uncertainty decomposition
                epistemic_uncertainty = ensemble_uncertainty  # Model uncertainty
                aleatoric_uncertainty = value_std / len(values) ** 0.5  # Data uncertainty
                
                value_info.update({
                    'confidence': calibrated_confidence,
                    'epistemic_uncertainty': epistemic_uncertainty,
                    'aleatoric_uncertainty': aleatoric_uncertainty,
                    'total_uncertainty': (epistemic_uncertainty ** 2 + aleatoric_uncertainty ** 2) ** 0.5,
                    'z_score': z_score,
                    'uncertainty_calibration_applied': True
                })
                
                calibrated_values.append(value_info)
            
            return calibrated_values
            
        except Exception as e:
            logger.warning(f"Uncertainty calibration failed: {e}")
            return extracted_values
    
    async def _expert_system_validation(self, extracted_values, cause):
        """Geological domain expert system validation"""
        try:
            expert_validated_values = []
            
            # Define geological expert rules
            expert_rules = {
                'density': {
                    'min_value': 1.0,
                    'max_value': 20.0,
                    'typical_range': (2.0, 8.0),
                    'common_values': [2.65, 2.7, 3.2],  # Quartz, common minerals
                    'unit_preferences': ['g/cm³', 'kg/m³']
                },
                'porosity': {
                    'min_value': 0.0,
                    'max_value': 50.0,
                    'typical_range': (5.0, 35.0),
                    'common_values': [15, 20, 25],
                    'unit_preferences': ['%', 'percent']
                },
                'permeability': {
                    'min_value': 0.001,
                    'max_value': 1000000,
                    'typical_range': (0.1, 10000),
                    'common_values': [1, 10, 100, 1000],
                    'unit_preferences': ['mD', 'darcy']
                }
            }
            
            expert_rule = expert_rules.get(cause.lower(), {})
            if not expert_rule:
                return extracted_values
            
            for value_info in extracted_values:
                value = value_info.get('value', 0)
                unit = value_info.get('unit', '').lower()
                
                expert_score = 1.0
                validation_notes = []
                
                # Range validation
                if value < expert_rule.get('min_value', 0):
                    expert_score *= 0.3
                    validation_notes.append(f"Value below minimum ({expert_rule['min_value']})")
                elif value > expert_rule.get('max_value', float('inf')):
                    expert_score *= 0.3
                    validation_notes.append(f"Value above maximum ({expert_rule['max_value']})")
                elif 'typical_range' in expert_rule:
                    min_typical, max_typical = expert_rule['typical_range']
                    if min_typical <= value <= max_typical:
                        expert_score *= 1.1  # Boost for typical range
                        validation_notes.append("Value in typical geological range")
                    else:
                        expert_score *= 0.8
                        validation_notes.append("Value outside typical range but within limits")
                
                # Unit validation
                preferred_units = [u.lower() for u in expert_rule.get('unit_preferences', [])]
                if any(pref_unit in unit for pref_unit in preferred_units):
                    expert_score *= 1.05
                    validation_notes.append("Preferred unit detected")
                elif unit and not any(pref_unit in unit for pref_unit in preferred_units):
                    expert_score *= 0.9
                    validation_notes.append("Non-standard unit")
                
                # Common value proximity
                common_values = expert_rule.get('common_values', [])
                if common_values:
                    closest_common = min(common_values, key=lambda x: abs(x - value))
                    relative_distance = abs(value - closest_common) / max(closest_common, 1)
                    if relative_distance < 0.1:  # Within 10% of common value
                        expert_score *= 1.1
                        validation_notes.append(f"Close to common value ({closest_common})")
                    elif relative_distance < 0.3:  # Within 30%
                        expert_score *= 1.05
                        validation_notes.append("Reasonably close to expected values")
                
                # Update confidence with expert validation
                original_confidence = value_info.get('confidence', 0.5)
                expert_validated_confidence = original_confidence * expert_score
                
                value_info.update({
                    'confidence': expert_validated_confidence,
                    'expert_validation_score': expert_score,
                    'expert_validation_notes': validation_notes,
                    'geological_expert_validated': True
                })
                
                expert_validated_values.append(value_info)
            
            return expert_validated_values
            
        except Exception as e:
            logger.warning(f"Expert system validation failed: {e}")
            return extracted_values

