    async def _extract_linguistic_features(self, text):
        """Extract advanced linguistic features"""
        try:
            import re
            from collections import Counter
            
            features = {
                'text_statistics': {
                    'character_count': len(text),
                    'word_count': len(text.split()),
                    'sentence_count': len(re.findall(r'[.!?]+', text)),
                    'paragraph_count': len(text.split('\n\n')),
                    'avg_word_length': np.mean([len(word) for word in text.split()]) if text.split() else 0,
                    'avg_sentence_length': len(text.split()) / max(len(re.findall(r'[.!?]+', text)), 1)
                },
                'lexical_diversity': {
                    'type_token_ratio': len(set(text.split())) / max(len(text.split()), 1),
                    'hapax_legomena_ratio': sum(1 for count in Counter(text.split()).values() if count == 1) / max(len(text.split()), 1),
                    'vocabulary_richness': len(set(text.lower().split())) / max(len(text.split()), 1)
                },
                'syntactic_complexity': {
                    'punctuation_density': len(re.findall(r'[^\w\s]', text)) / max(len(text), 1),
                    'capitalization_ratio': len(re.findall(r'[A-Z]', text)) / max(len(text), 1),
                    'numeric_density': len(re.findall(r'\d', text)) / max(len(text), 1)
                },
                'readability_metrics': await self._calculate_readability_metrics(text)
            }
            
            return features
            
        except Exception as e:
            self.logger.error(f"Linguistic feature extraction failed: {e}")
            return {'error': 'linguistic_extraction_failed'}
    
    async def _extract_semantic_features_dp(self, text):
        """Extract semantic features with differential privacy"""
        try:
            import torch
            from transformers import AutoTokenizer, AutoModel
            
            # Tokenize and encode
            inputs = self.privacy_tokenizer(text, return_tensors="pt", max_length=512, truncation=True)
            
            with torch.no_grad():
                outputs = self.privacy_model(**inputs)
                embeddings = outputs.last_hidden_state.mean(dim=1).squeeze().numpy()
            
            # Apply differential privacy noise
            epsilon = getattr(self, 'privacy_epsilon', 1.0)
            sensitivity = 1.0
            noise_scale = sensitivity / epsilon
            
            noisy_embeddings = embeddings + np.random.normal(0, noise_scale, embeddings.shape)
            
            # Create privacy-preserving semantic features
            features = {
                'embedding_statistics': {
                    'mean_activation': float(np.mean(noisy_embeddings)),
                    'std_activation': float(np.std(noisy_embeddings)),
                    'max_activation': float(np.max(noisy_embeddings)),
                    'min_activation': float(np.min(noisy_embeddings)),
                    'embedding_norm': float(np.linalg.norm(noisy_embeddings))
                },
                'semantic_clusters': await self._identify_semantic_clusters(noisy_embeddings),
                'topic_distribution': await self._estimate_topic_distribution(text, noisy_embeddings),
                'privacy_parameters': {
                    'epsilon_used': epsilon,
                    'noise_scale': noise_scale,
                    'sensitivity': sensitivity
                }
            }
            
            return features
            
        except Exception as e:
            self.logger.error(f"Semantic feature extraction failed: {e}")
            return {'error': 'semantic_extraction_failed'}
    
    async def _extract_geological_text_features(self, text):
        """Extract domain-specific geological features"""
        try:
            # Geological terminology patterns
            geological_patterns = {
                'rock_types': r'\b(granite|basalt|limestone|sandstone|shale|quartzite|gneiss|schist|marble|slate)\b',
                'minerals': r'\b(quartz|feldspar|mica|calcite|olivine|pyroxene|amphibole|plagioclase)\b',
                'processes': r'\b(weathering|erosion|sedimentation|metamorphism|igneous|intrusion|extrusion)\b',
                'structures': r'\b(fault|fold|joint|fracture|bedding|foliation|lineation|cleavage)\b',
                'time_periods': r'\b(precambrian|paleozoic|mesozoic|cenozoic|jurassic|cretaceous|tertiary|quaternary)\b',
                'units': r'\b(\d+\s*(ma|mpa|gpa|km|m|cm|mm|°c|°f|atm|bar|psi))\b',
                'coordinates': r'\b(\d+[°]?\s*\d*[′]?\s*\d*[″]?\s*[nsew])\b'
            }
            
            features = {}
            for category, pattern in geological_patterns.items():
                matches = re.findall(pattern, text.lower())
                features[f'{category}_count'] = len(matches)
                features[f'{category}_density'] = len(matches) / max(len(text.split()), 1)
                features[f'{category}_unique'] = len(set(matches))
            
            # Domain-specific complexity metrics
            features['geological_complexity'] = await self._calculate_geological_complexity(text)
            features['technical_sophistication'] = await self._assess_technical_sophistication(text)
            features['data_quality_indicators'] = await self._identify_data_quality_indicators(text)
            
            return features
            
        except Exception as e:
            self.logger.error(f"Geological text feature extraction failed: {e}")
            return {'error': 'geological_extraction_failed'}
    
    async def _extract_kg_linkage_features(self, text):
        """Extract knowledge graph entity linkage features"""
        try:
            # Connect to knowledge graph if available
            if hasattr(self, 'knowledge_graph') and self.knowledge_graph:
                # Entity recognition and linking
                entities = await self._extract_named_entities(text)
                linked_entities = await self._link_entities_to_kg(entities)
                
                features = {
                    'entity_coverage': len(linked_entities) / max(len(entities), 1),
                    'kg_connectivity': await self._calculate_kg_connectivity(linked_entities),
                    'domain_coherence': await self._assess_domain_coherence(linked_entities),
                    'knowledge_density': len(linked_entities) / max(len(text.split()), 1),
                    'entity_types': Counter([ent.get('type') for ent in linked_entities])
                }
                
                return features
            else:
                return {'kg_not_available': True}
                
        except Exception as e:
            self.logger.error(f"KG linkage feature extraction failed: {e}")
            return {'error': 'kg_linkage_failed'}
    
    # =============================================================================
    # ADVANCED ENTITY FEATURE EXTRACTION HELPER METHODS  
    # =============================================================================
    
    async def _analyze_entity_relationships(self, entities):
        """Analyze relationships between entities"""
        try:
            relationships = {
                'entity_pairs': [],
                'relationship_types': {},
                'network_metrics': {}
            }
            
            # Analyze pairwise relationships
            for i, entity1 in enumerate(entities):
                for j, entity2 in enumerate(entities[i+1:], i+1):
                    relationship = await self._determine_entity_relationship(entity1, entity2)
                    if relationship:
                        relationships['entity_pairs'].append({
                            'entity1': entity1.get('text', '') if isinstance(entity1, dict) else str(entity1),
                            'entity2': entity2.get('text', '') if isinstance(entity2, dict) else str(entity2),
                            'relationship': relationship
                        })
            
            return relationships
            
        except Exception as e:
            self.logger.error(f"Entity relationship analysis failed: {e}")
            return {'error': 'relationship_analysis_failed'}
    
    async def _enrich_entities_with_kg(self, entities):
        """Enrich entities with knowledge graph information"""
        try:
            enriched_entities = []
            
            if hasattr(self, 'knowledge_graph') and self.knowledge_graph:
                for entity in entities:
                    entity_text = entity.get('text', '') if isinstance(entity, dict) else str(entity)
                    
                    # Query knowledge graph
                    kg_info = await self._query_kg_for_entity(entity_text)
                    
                    enriched_entity = {
                        'original': entity,
                        'kg_matches': kg_info.get('matches', []),
                        'confidence_score': kg_info.get('confidence', 0.0),
                        'semantic_types': kg_info.get('types', []),
                        'related_concepts': kg_info.get('related', [])
                    }
                    
                    enriched_entities.append(enriched_entity)
            
            return enriched_entities
            
        except Exception as e:
            self.logger.error(f"KG entity enrichment failed: {e}")
            return {'error': 'kg_enrichment_failed'}
    
    # =============================================================================
    # MODEL VERSIONING HELPER METHODS
    # =============================================================================
    
    async def _get_model_version_from_db(self):
        """Get model version from database"""
        try:
            if hasattr(self, 'database_manager') and self.database_manager:
                query = """
                SELECT version, created_at, metadata 
                FROM model_versions 
                WHERE model_name = %s 
                ORDER BY created_at DESC 
                LIMIT 1
                """
                result = await self.database_manager.execute_query(query, [self.property_name])
                
                if result:
                    return {
                        'version': result[0]['version'],
                        'timestamp': result[0]['created_at'].isoformat(),
                        'metadata': result[0]['metadata'],
                        'source': 'database'
                    }
            
            return None
            
        except Exception as e:
            self.logger.error(f"Database model version retrieval failed: {e}")
            return None
    
    def _get_git_model_version(self):
        """Get model version from git"""
        try:
            import subprocess
            
            # Get git commit hash
            result = subprocess.run(['git', 'rev-parse', 'HEAD'], 
                                  capture_output=True, text=True)
            
            if result.returncode == 0:
                commit_hash = result.stdout.strip()
                
                # Get commit timestamp
                result = subprocess.run(['git', 'show', '-s', '--format=%ci', commit_hash], 
                                      capture_output=True, text=True)
                
                timestamp = result.stdout.strip() if result.returncode == 0 else datetime.utcnow().isoformat()
                
                return {
                    'version': f'git_{commit_hash[:8]}',
                    'commit_hash': commit_hash,
                    'timestamp': timestamp,
                    'source': 'git'
                }
            
            return None
            
        except Exception as e:
            self.logger.error(f"Git version retrieval failed: {e}")
            return None
    
    def _get_mlops_model_version(self):
        """Get model version from MLOps registry"""
        try:
            if hasattr(self, 'mlops_manager') and self.mlops_manager:
                version_info = self.mlops_manager.get_latest_model_version(self.property_name)
                
                if version_info:
                    return {
                        'version': version_info['version'],
                        'model_uri': version_info['uri'],
                        'timestamp': version_info['timestamp'],
                        'metrics': version_info.get('metrics', {}),
                        'source': 'mlops'
                    }
            
            return None
            
        except Exception as e:
            self.logger.error(f"MLOps version retrieval failed: {e}")
            return None
    
    def _generate_semantic_version(self):
        """Generate semantic version based on features and capabilities"""
        try:
            import time
            
            # Feature-based versioning
            major = 2  # Major version for advanced implementations
            minor = 1  # Minor version for new features
            patch = int(time.time() % 1000)  # Patch version
            
            version_string = f"v{major}.{minor}.{patch}"
            
            return {
                'version': version_string,
                'semantic_version': {
                    'major': major,
                    'minor': minor,
                    'patch': patch
                },
                'features': {
                    'privacy_preserving': True,
                    'knowledge_graph_integration': True,
                    'advanced_nlp': True,
                    'database_integration': True
                },
                'timestamp': datetime.utcnow().isoformat(),
                'source': 'semantic_generation'
            }
            
        except Exception as e:
            self.logger.error(f"Semantic version generation failed: {e}")
            return {'version': 'v2.1.0', 'error': str(e)}
    
    async def _update_model_version_db(self, version_info):
        """Update model version in database"""
        try:
            if hasattr(self, 'database_manager') and self.database_manager:
                query = """
                INSERT INTO model_versions (model_name, version, metadata, created_at)
                VALUES (%s, %s, %s, %s)
                ON CONFLICT (model_name, version) DO UPDATE SET
                metadata = EXCLUDED.metadata,
                updated_at = NOW()
                """
                
                await self.database_manager.execute_query(query, [
                    self.property_name,
                    version_info['version'],
                    json.dumps(version_info),
                    datetime.utcnow()
                ])
                
                self.logger.info(f"Model version {version_info['version']} updated in database")
        
        except Exception as e:
            self.logger.error(f"Database model version update failed: {e}")
    
    # =============================================================================
    # UTILITY HELPER METHODS
    # =============================================================================
    
    def _count_features_recursive(self, features_dict):
        """Recursively count features in nested dictionary"""
        count = 0
        for value in features_dict.values():
            if isinstance(value, dict):
                count += self._count_features_recursive(value)
            elif isinstance(value, (list, tuple)):
                count += len(value)
            else:
                count += 1
        return count
    
    def _discretize_length(self, length):
        """Discretize text length for privacy"""
        if length < 50:
            return 'short'
        elif length < 200:
            return 'medium'
        elif length < 500:
            return 'long'
        else:
            return 'very_long'
    
    def _discretize_count(self, count):
        """Discretize count for privacy"""
        if count < 10:
            return 'few'
        elif count < 50:
            return 'some'
        elif count < 100:
            return 'many'
        else:
            return 'very_many'
    
    async def _apply_differential_privacy_noise(self, features):
        """Apply differential privacy noise to numerical features"""
        try:
            epsilon = getattr(self, 'privacy_epsilon', 1.0)
            
            def add_noise_recursive(obj):
                if isinstance(obj, dict):
                    return {k: add_noise_recursive(v) for k, v in obj.items()}
                elif isinstance(obj, (int, float)) and not isinstance(obj, bool):
                    noise = np.random.laplace(0, 1/epsilon)
                    return max(0, obj + noise)  # Ensure non-negative
                else:
                    return obj
            
            return add_noise_recursive(features)
            
        except Exception as e:
            self.logger.error(f"Differential privacy noise application failed: {e}")
            return features
    
    async def _update_privacy_budget_usage(self, text, features):
        """Update privacy budget usage tracking"""
        try:
            if not hasattr(self, 'privacy_budget_log'):
                self.privacy_budget_log = []
            
            budget_entry = {
                'timestamp': datetime.utcnow().isoformat(),
                'text_hash': hashlib.sha256(text.encode()).hexdigest()[:16],
                'epsilon_used': getattr(self, 'privacy_epsilon', 1.0),
                'feature_count': self._count_features_recursive(features)
            }
            
            self.privacy_budget_log.append(budget_entry)
            
            # Keep only recent entries
            if len(self.privacy_budget_log) > 1000:
                self.privacy_budget_log = self.privacy_budget_log[-1000:]
                
        except Exception as e:
            self.logger.error(f"Privacy budget tracking failed: {e}")
    
